--
-- Name: calculate_rfm(); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.calculate_rfm() RETURNS TABLE(id_cliente integer, r_score integer, f_score integer, m_score integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'analytics', 'pg_temp'
    AS $$
  WITH rfm_base AS (
    SELECT 
      dc.id_cliente,
      COALESCE(CURRENT_DATE - MAX(fo.fecha_creacion)::date, 999) AS recency_days,
      COUNT(DISTINCT fo.id_orden) AS frequency,
      COALESCE(SUM(fo.amount_gross), 0) AS monetary
    FROM analytics.dim_clientes_scd dc
    LEFT JOIN analytics.hecho_ordenes fo 
      ON dc.id_cliente = fo.customer_id_fk 
      AND fo.estado = 'completed'
    WHERE dc.is_active = TRUE
    GROUP BY dc.id_cliente
  ),
  rfm_percentiles AS (
    SELECT 
      id_cliente,
      recency_days,
      frequency,
      monetary,
      NTILE(4) OVER (ORDER BY recency_days DESC) AS r_score,
      NTILE(4) OVER (ORDER BY frequency) AS f_score,
      NTILE(4) OVER (ORDER BY monetary) AS m_score
    FROM rfm_base
  )
  SELECT id_cliente, r_score, f_score, m_score FROM rfm_percentiles;
$$;


--
-- Name: calculate_seller_health_score(); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.calculate_seller_health_score() RETURNS TABLE(id_vendedor uuid, health_score numeric, health_status character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_id_vendedor uuid;
  v_health_score numeric;
  v_health_status varchar;
BEGIN
  FOR v_id_vendedor, v_health_score, v_health_status IN
    WITH seller_metrics AS (
      SELECT 
        ds.id_vendedor AS sid,
        COALESCE(SUM(fo.amount_gross), 0) AS gmv_30d,
        COUNT(DISTINCT fo.id_orden) AS orders_30d,
        CASE 
          WHEN COUNT(DISTINCT fo.id_orden) >= 30 
          THEN ROUND(AVG(fo.rating), 2)
          ELSE NULL
        END AS avg_rating,
        ROUND(
          COUNT(DISTINCT CASE WHEN fo.delivered_on_time = 'true' THEN fo.id_orden END) * 100.0 / 
          NULLIF(COUNT(DISTINCT fo.id_orden), 0), 2
        ) AS on_time_rate,
        ROUND(
          COUNT(DISTINCT CASE WHEN fo.estado = 'cancelled' THEN fo.id_orden END) * 100.0 / 
          NULLIF(COUNT(DISTINCT fo.id_orden), 0), 2
        ) AS cancel_rate,
        ROUND(
          COUNT(DISTINCT CASE WHEN fo.chargeback = 'true' THEN fo.id_orden END) * 100.0 / 
          NULLIF(COUNT(DISTINCT fo.id_orden), 0), 2
        ) AS chargeback_rate,
        ROUND(
          COUNT(DISTINCT CASE WHEN fo.returned = 'true' THEN fo.order_item_id END) * 100.0 / 
          NULLIF(SUM(fo.quantity), 0), 2
        ) AS return_rate,
        0.0 AS gmv_growth_mom
      FROM analytics.dim_vendedores_scd ds
      LEFT JOIN analytics.hecho_ordenes fo 
        ON ds.id_vendedor = fo.seller_id_fk
        AND fo.estado = 'completed'
        AND fo.fecha_creacion >= CURRENT_DATE - INTERVAL '30 days'
      WHERE ds.is_active = TRUE
      GROUP BY ds.id_vendedor
    ),
    health_calculation AS (
      SELECT 
        sm.sid,
        sm.gmv_30d, sm.orders_30d, sm.avg_rating, sm.on_time_rate, sm.cancel_rate, sm.chargeback_rate, sm.return_rate, sm.gmv_growth_mom,
        ROUND((PERCENT_RANK() OVER (ORDER BY sm.gmv_30d) * 30)::NUMERIC, 2) AS gmv_component,
        ROUND(
          COALESCE((sm.avg_rating / 5.0) * 15, 0) +
          GREATEST(0, 10 - (sm.cancel_rate * 2)) +
          GREATEST(0, 5 - (sm.chargeback_rate * 10))
        , 2) AS quality_component,
        ROUND(
          (COALESCE(sm.on_time_rate, 0) / 100.0) * 20
        , 2) AS efficiency_component,
        ROUND(10, 2) AS growth_component
      FROM seller_metrics sm
    ),
    final_score AS (
      SELECT 
        hc.sid,
        ROUND(
          COALESCE(hc.gmv_component, 0) +
          COALESCE(hc.quality_component, 0) +
          COALESCE(hc.efficiency_component, 0) +
          COALESCE(hc.growth_component, 0)
        , 2) AS hs,
        CASE 
          WHEN ROUND(
                COALESCE(hc.gmv_component, 0) +
                COALESCE(hc.quality_component, 0) +
                COALESCE(hc.efficiency_component, 0) +
                COALESCE(hc.growth_component, 0)
              , 2) >= 80 THEN 'Platinum'
          WHEN ROUND(
                COALESCE(hc.gmv_component, 0) +
                COALESCE(hc.quality_component, 0) +
                COALESCE(hc.efficiency_component, 0) +
                COALESCE(hc.growth_component, 0)
              , 2) >= 60 THEN 'Gold'
          WHEN ROUND(
                COALESCE(hc.gmv_component, 0) +
                COALESCE(hc.quality_component, 0) +
                COALESCE(hc.efficiency_component, 0) +
                COALESCE(hc.growth_component, 0)
              , 2) >= 40 THEN 'Silver'
          ELSE 'Bronze'
        END AS hst
      FROM health_calculation hc
    )
    SELECT fs.sid, fs.hs, fs.hst FROM final_score fs
  LOOP
    id_vendedor := v_id_vendedor;
    health_score := v_health_score;
    health_status := v_health_status;
    RETURN NEXT;
  END LOOP;
END;
$$;


