-- Name: fn_is_admin_safe(); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.fn_is_admin_safe() RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_proc WHERE proname='fn_is_admin' AND pronamespace='auth'::regnamespace) THEN
    RETURN auth.fn_is_admin();
  ELSE
    RAISE WARNING '[P0UF10] auth.fn_is_admin() no existe en este ambiente; acceso admin denegado por defecto (fail-closed).';
    RETURN false;
  END IF;
END;
$$;


--
-- Name: fn_refrescar_zonas_rentables(uuid); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.fn_refrescar_zonas_rentables(p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'analytics', 'pg_temp'
    AS $_$
DECLARE
  v_actualizados integer := 0;
  v_col_location text;
  v_has_updated_at boolean;
  r RECORD;
BEGIN
  SELECT column_name INTO v_col_location FROM information_schema.columns
    WHERE table_schema='auth' AND table_name='ordenes'
    AND column_name IN ('location_delivery','punto_entrega','delivery_point') LIMIT 1;

  IF v_col_location IS NULL THEN
    RAISE WARNING '[P0UF07] Sin columna de ubicación de entrega; fn_refrescar_zonas_rentables no puede operar, retornando 0.';
    RETURN 0;
  END IF;

  -- V2.1: verificar si frequent_buyers.fecha_actualizacion existe antes de intentar setearla
  SELECT EXISTS(SELECT 1 FROM information_schema.columns
    WHERE table_schema='auth' AND table_name='frequent_buyers' AND column_name='updated_at')
  INTO v_has_updated_at;

  FOR r IN EXECUTE format($f$
    SELECT o.id_vendedor, o.id_comprador, ST_Centroid(ST_Collect(o.%1$I)) AS centro
    FROM auth.ordenes o
    WHERE o.estado = 'completada' AND o.fecha_eliminacion IS NULL AND o.%1$I IS NOT NULL
      AND ($2 IS NULL OR o.id_vendedor = $2)
    GROUP BY o.id_vendedor, o.id_comprador
  $f$, v_col_location) USING p_id_vendedor, p_id_vendedor
  LOOP
    IF v_has_updated_at THEN
      EXECUTE 'UPDATE auth.frequent_buyers SET zona_grid = $1, updated_at = now() WHERE id_vendedor = $2 AND id_comprador = $3'
        USING r.centro, r.id_vendedor, r.id_comprador;
    ELSE
      EXECUTE 'UPDATE auth.frequent_buyers SET zona_grid = $1 WHERE id_vendedor = $2 AND id_comprador = $3'
        USING r.centro, r.id_vendedor, r.id_comprador;
    END IF;
    IF FOUND THEN v_actualizados := v_actualizados + 1; END IF;
  END LOOP;
  RETURN v_actualizados;
EXCEPTION WHEN OTHERS THEN
  INSERT INTO auth.h_ubica_fidelizacion_audit(actor_user_id, accion, detalle, creado_en)
  VALUES (p_id_vendedor, 'REFRESH_ZONAS_FALLIDO', jsonb_build_object('error', SQLERRM), now());
  RAISE EXCEPTION '[P0UF05] Fallo al refrescar zonas rentables: %', SQLERRM USING ERRCODE = 'P0001';
END;
$_$;


--
-- Name: fn_usuario_activo(uuid); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.fn_usuario_activo(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
  v_has_deleted boolean;
  v_has_activo boolean;
  v_result boolean;
BEGIN
  SELECT EXISTS(SELECT 1 FROM information_schema.columns
    WHERE table_schema='auth' AND table_name='users' AND column_name='deleted_at') INTO v_has_deleted;
  SELECT EXISTS(SELECT 1 FROM information_schema.columns
    WHERE table_schema='auth' AND table_name='users' AND column_name IN ('activo','is_active')) INTO v_has_activo;

  IF v_has_deleted AND v_has_activo THEN
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM auth.users WHERE id = $1 AND (activo = true OR is_active = true) AND deleted_at IS NULL)')
      INTO v_result USING p_user_id;
  ELSIF v_has_activo THEN
    SELECT EXISTS(SELECT 1 FROM auth.users WHERE id = p_user_id AND activo = true) INTO v_result;
  ELSE
    -- Ninguna columna reconocible: fallback conservador, requiere solo existencia del usuario
    SELECT EXISTS(SELECT 1 FROM auth.users WHERE id = p_user_id) INTO v_result;
    RAISE WARNING '[P0UF09] auth.users no tiene columnas activo/is_active/deleted_at reconocibles; validación degradada a solo-existencia para %', p_user_id;
  END IF;
  RETURN v_result;
END;
$_$;


--
-- Name: get_clientes_recurrentes(uuid); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.get_clientes_recurrentes(p_id_vendedor uuid) RETURNS TABLE(id_comprador uuid, total_compras bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'analytics', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid;
BEGIN
  -- V2.1: usa fn_usuario_activo (resuelve columnas dinámicamente) en vez de asumir fecha_eliminacion
  IF NOT analytics.fn_usuario_activo(p_id_vendedor) THEN
    RAISE EXCEPTION '[P0UF02] Vendedor % no existe o está inactivo', p_id_vendedor
      USING ERRCODE = 'P0002', HINT = 'Verificar auth.users';
  END IF;

  v_caller := auth.fn_current_user_id();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION '[P0UF03] No hay sesión autenticada válida (JWT ausente o expirado)'
      USING ERRCODE = '28000', HINT = 'Reautenticar sesión';
  END IF;

  -- V2.1: usa fn_is_admin_safe (fail-closed si la función no existe)
  IF v_caller <> p_id_vendedor AND NOT analytics.fn_is_admin_safe() THEN
    RAISE EXCEPTION '[P0UF04] Acceso denegado: % no puede consultar métricas de otro vendedor', v_caller
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT o.id_comprador, COUNT(*)::bigint AS total_compras
  FROM auth.ordenes o
  WHERE o.id_vendedor = p_id_vendedor
    AND o.estado = 'completada'
    AND o.fecha_eliminacion IS NULL
  GROUP BY o.id_comprador
  HAVING COUNT(*) > 1
  ORDER BY total_compras DESC;
END;
$$;


--
-- Name: get_zonas_rentables(uuid); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.get_zonas_rentables(p_id_vendedor uuid) RETURNS TABLE(zone_geojson text, lat_center double precision, lng_center double precision, total_ventas bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'analytics', 'pg_temp'
    AS $_$
DECLARE
  v_caller uuid := auth.fn_current_user_id();
  v_col_location text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION '[P0UF03] No hay sesión autenticada válida' USING ERRCODE = '28000';
  END IF;

  IF v_caller <> p_id_vendedor AND NOT analytics.fn_is_admin_safe() THEN
    RAISE EXCEPTION '[P0UF04] Acceso denegado: no puedes consultar zonas de otro vendedor' USING ERRCODE = '42501';
  END IF;

  IF NOT analytics.fn_usuario_activo(p_id_vendedor) THEN
    RAISE EXCEPTION '[P0UF02] Vendedor % no existe o está inactivo', p_id_vendedor USING ERRCODE = 'P0002';
  END IF;

  -- V2.1: resolver dinámicamente el nombre real de la columna de ubicación de entrega
  SELECT column_name INTO v_col_location FROM information_schema.columns
    WHERE table_schema='auth' AND table_name='ordenes'
    AND column_name IN ('location_delivery','punto_entrega','delivery_point') LIMIT 1;

  IF v_col_location IS NULL THEN
    RAISE EXCEPTION '[P0UF07] auth.ordenes no tiene columna de ubicación de entrega reconocible. get_zonas_rentables no puede operar.'
      USING ERRCODE = 'P0003', HINT = 'Ejecutar CT0 y confirmar el nombre real de la columna geoespacial.';
  END IF;

  RETURN QUERY EXECUTE format($f$
    SELECT
      ST_AsGeoJSON(ST_Centroid(ST_Collect(o.%1$I)))::text,
      ROUND(AVG(ST_Y(o.%1$I))::numeric, 4)::double precision,
      ROUND(AVG(ST_X(o.%1$I))::numeric, 4)::double precision,
      COUNT(*)::bigint
    FROM auth.ordenes o
    WHERE o.id_vendedor = $1
      AND o.estado = 'completada'
      AND o.fecha_eliminacion IS NULL
      AND o.%1$I IS NOT NULL
    GROUP BY ST_SnapToGrid(o.%1$I, 0.01)
    ORDER BY 4 DESC
  $f$, v_col_location) USING p_id_vendedor;
END;
$_$;


