--
-- Name: refresh_customer_segments(); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.refresh_customer_segments() RETURNS TABLE(customers_segmented integer, segment_changes integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_customers_count INT;
  v_changes_count INT;
BEGIN
  INSERT INTO analytics.segmentos_clientes (
    customer_id_fk, recency_score, frequency_score, monetary_score,
    nombre_segmento, segment_tier, is_churn, churn_risk_score
  )
  WITH rfm_calc AS (
    SELECT 
      dc.id_cliente,
      NTILE(4) OVER (ORDER BY COALESCE(CURRENT_DATE - MAX(fo.fecha_creacion)::date, 999) DESC) AS r_score,
      NTILE(4) OVER (ORDER BY COUNT(fo.id_orden)) AS f_score,
      NTILE(4) OVER (ORDER BY COALESCE(SUM(fo.amount_gross), 0)) AS m_score,
      COALESCE(CURRENT_DATE - MAX(fo.fecha_creacion)::date, 999) AS days_since,
      COUNT(fo.id_orden) AS order_count,
      COALESCE(SUM(fo.amount_gross), 0) AS total_spent
    FROM analytics.dim_clientes_scd dc
    LEFT JOIN analytics.hecho_ordenes fo 
      ON dc.id_cliente = fo.customer_id_fk
      AND fo.estado = 'completed'
    WHERE dc.is_active = TRUE
    GROUP BY dc.id_cliente
  ),
  segment_assign AS (
    SELECT 
      id_cliente, r_score, f_score, m_score,
      CASE 
        WHEN r_score >= 3 AND f_score >= 3 AND m_score >= 3 THEN 'Champions'
        WHEN r_score >= 2 AND f_score >= 3 AND m_score >= 3 THEN 'Loyal Customers'
        WHEN r_score >= 3 AND f_score >= 2 THEN 'Potential Loyalists'
        WHEN r_score >= 3 AND f_score = 1 THEN 'New Customers'
        WHEN r_score = 2 OR f_score >= 2 THEN 'At Risk'
        WHEN r_score <= 1 AND f_score >= 3 THEN 'Cant Lose Them'
        ELSE 'Hibernating'
      END AS nombre_segmento,
      CASE 
        WHEN r_score >= 3 AND f_score >= 3 AND m_score >= 3 THEN 'Premium'
        WHEN days_since > 90 THEN 'Churn'
        ELSE 'Active'
      END AS tier,
      CASE WHEN days_since > 90 THEN TRUE ELSE FALSE END AS is_churn
    FROM rfm_calc
  )
  SELECT 
    id_cliente, r_score, f_score, m_score,
    nombre_segmento, tier, is_churn, 0.0
  FROM segment_assign;
  
  GET DIAGNOSTICS v_customers_count = ROW_COUNT;
  
  WITH segment_changes AS (
    SELECT COUNT(*) AS change_count
    FROM analytics.segmentos_clientes cs1
    WHERE cs1.calculado_en::DATE = CURRENT_DATE
      AND EXISTS (
        SELECT 1 FROM analytics.segmentos_clientes cs2
        WHERE cs2.customer_id_fk = cs1.customer_id_fk
          AND cs2.calculado_en::DATE = CURRENT_DATE - INTERVAL '1 day'
          AND cs2.nombre_segmento != cs1.nombre_segmento
      )
  )
  SELECT change_count INTO v_changes_count FROM segment_changes;
  
  RETURN QUERY SELECT v_customers_count, COALESCE(v_changes_count, 0);
END;
$$;


--
-- Name: refresh_vendor_metrics(); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.refresh_vendor_metrics() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'analytics', 'pg_temp'
    AS $$
BEGIN
  -- Usar tabla hecho_metricas_vendedor en lugar de MV inexistente
  INSERT INTO analytics.hecho_metricas_vendedor (seller_id_fk, date_id_fk, orders_count, gmv, avg_rating, returned_items, cancellations, on_time_rate)
  SELECT 
    ds.id_vendedor,
    to_char(CURRENT_DATE, 'YYYYMMDD')::integer,
    COUNT(DISTINCT fo.id_orden),
    COALESCE(SUM(fo.amount_gross), 0),
    COALESCE(AVG(fo.rating), 0),
    COUNT(DISTINCT CASE WHEN fo.returned = 'true' THEN fo.order_item_id END),
    COUNT(DISTINCT CASE WHEN fo.estado = 'cancelled' THEN fo.id_orden END),
    ROUND(COUNT(DISTINCT CASE WHEN fo.delivered_on_time = 'true' THEN fo.id_orden END) * 100.0 / NULLIF(COUNT(DISTINCT fo.id_orden), 0), 2)
  FROM analytics.dim_vendedores_scd ds
  LEFT JOIN analytics.hecho_ordenes fo ON ds.id_vendedor = fo.seller_id_fk
    AND fo.estado = 'completed'
    AND fo.fecha_creacion >= CURRENT_DATE - INTERVAL '30 days'
  WHERE ds.is_active = TRUE
  GROUP BY ds.id_vendedor
  ON CONFLICT (seller_id_fk, date_id_fk) DO UPDATE SET
    orders_count = EXCLUDED.orders_count,
    gmv = EXCLUDED.gmv,
    avg_rating = EXCLUDED.avg_rating,
    returned_items = EXCLUDED.returned_items,
    cancellations = EXCLUDED.cancellations,
    on_time_rate = EXCLUDED.on_time_rate;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[P0UF06] Refresh de vendor_metrics falló, degradación controlada: %', SQLERRM;
END;
$$;


--
-- Name: sync_compro_edges(uuid); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.sync_compro_edges(p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'analytics', 'pg_temp'
    AS $_$
DECLARE
  r RECORD;
  v_sync integer := 0;
  v_seller_label text;
BEGIN
  -- V2.1: resolver el label real del vendedor en el grafo (User vs Vendor) antes de iterar
  SELECT name INTO v_seller_label FROM ag_catalog.ag_label
    WHERE graph = (SELECT graphid FROM ag_catalog.ag_graph WHERE name = 'smtp_posix_graph')
    AND kind = 'v' AND name IN ('User','Vendor') LIMIT 1;

  IF v_seller_label IS NULL THEN
    -- V2.1: esto ya NO se oculta como "fallo esperado" -- es un error de mapeo real, se marca distinto
    INSERT INTO auth.h_ubica_fidelizacion_audit(actor_user_id, accion, detalle, creado_en)
    VALUES (p_id_vendedor, 'AGE_MAPEO_LABEL_NO_ENCONTRADO', jsonb_build_object('grafo','smtp_posix_graph'), now());
    RAISE EXCEPTION '[P0UF08] No se encontró label de vértice User/Vendor en smtp_posix_graph. Esto es un error de mapeo de esquema AGE, no un fallo transitorio; requiere corrección manual antes de reintentar.'
      USING ERRCODE = 'P0004';
  END IF;

  FOR r IN
    SELECT o.id_vendedor, o.id_comprador, COUNT(*) AS total
    FROM auth.ordenes o
    WHERE o.estado = 'completada' AND o.fecha_eliminacion IS NULL
      AND (p_id_vendedor IS NULL OR o.id_vendedor = p_id_vendedor)
    GROUP BY o.id_vendedor, o.id_comprador
  LOOP
    BEGIN
      EXECUTE format($q$
        SELECT * FROM cypher('smtp_posix_graph', $cypher$
          MATCH (b:User {id: $%1$s}), (v:%2$s {id: $%3$s})
          MERGE (b)-[e:COMPRO]->(v)
          SET e.total_ordenes = $%4$s, e.fecha_actualizacion = timestamp()
          RETURN e
        $cypher$, jsonb_build_object('id_comprador', %5$L, 'id_vendedor', %6$L, 'total', %7$L)
        ) AS (result agtype)
      $q$, 'id_comprador', v_seller_label, 'id_vendedor', 'total', r.id_comprador::text, r.id_vendedor::text, r.total);
      v_sync := v_sync + 1;
    EXCEPTION WHEN OTHERS THEN
      -- V2.1: solo fallos transitorios reales de grafo caen aquí (label ya fue validado arriba)
      INSERT INTO auth.h_ubica_fidelizacion_audit(actor_user_id, accion, detalle, creado_en)
      VALUES (r.id_vendedor, 'AGE_SYNC_COMPRO_FALLIDO_TRANSITORIO', jsonb_build_object('id_comprador', r.id_comprador, 'error', SQLERRM), now());
    END;
  END LOOP;
  RETURN v_sync;
END;
$_$;


--
-- Name: trigger_export_alerts(); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.trigger_export_alerts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Alerta si alguna exportación falla
  IF NEW.estado = 'failed' THEN
    INSERT INTO analytics.alertas_exportacion (
      export_run_id, tipo_alerta, alert_severity, alert_message
    ) VALUES (
      NEW.export_run_id,
      'EXPORT_FAILED',
      'CRITICAL',
      'Daily export failed: ' || COALESCE(NEW.error_message, 'Unknown error')
    );
  END IF;
  
  -- Alerta si checksums no coinciden
  IF NEW.primary_copy_success AND NEW.backup_copy_success AND
     NEW.checksum_primary != NEW.checksum_backup THEN
    INSERT INTO analytics.alertas_exportacion (
      export_run_id, tipo_alerta, alert_severity, alert_message
    ) VALUES (
      NEW.export_run_id,
      'CHECKSUM_MISMATCH',
      'WARNING',
      'Primary and backup checksums do not match'
    );
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: trigger_seller_alerts(); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.trigger_seller_alerts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Alerta: Cancel rate > 5%
  IF NEW.cancellation_rate > 5.0 THEN
    INSERT INTO analytics.alertas_vendedor (
      seller_id_fk, tipo_alerta, alert_severity, alert_message,
      metric_name, metric_current_value, metric_threshold, action_required
    ) VALUES (
      NEW.seller_id_fk, 'HIGH_CANCEL_RATE', 'WARNING',
      'Cancellation rate exceeds 5%',
      'cancellation_rate', NEW.cancellation_rate, 5.0,
      'Contact seller to understand cancellation causes'
    );
  END IF;
  
  -- Alerta: Health score cae > 20 puntos en 7d
  IF NEW.health_score < (
    SELECT health_score FROM analytics.puntaje_salud_vendedor
    WHERE seller_id_fk = NEW.seller_id_fk
      AND calculado_en >= CURRENT_DATE - INTERVAL '7 days'
    LIMIT 1
  ) - 20 THEN
    INSERT INTO analytics.alertas_vendedor (
      seller_id_fk, tipo_alerta, alert_severity, alert_message,
      metric_name, metric_current_value, action_required
    ) VALUES (
      NEW.seller_id_fk, 'HEALTH_DECLINE', 'CRITICAL',
      'Health score dropped > 20 points in 7 days',
      'health_score', NEW.health_score,
      'Urgent: Contact seller and assess reason for decline'
    );
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: assert_rls_hardening(); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.assert_rls_hardening() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_policies
    WHERE schemaname IN ('public','audit')
      AND (
        lower(regexp_replace(COALESCE(qual,''), '\\s+', '', 'g')) IN ('true','(true)')
        OR lower(regexp_replace(COALESCE(with_check,''), '\\s+', '', 'g')) IN ('true','(true)')
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='SE_DETECTO_POLICY_PERMISIVA_USING_TRUE';
  END IF;

  RETURN jsonb_build_object('ok', true, 'message', 'RLS endurecido');
EXCEPTION
  WHEN SQLSTATE '42501' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'RLS_WEAK', 'message', SQLERRM);
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INTERNAL_ERROR', 'message', SQLERRM);
END;
$$;


--
-- Name: audit_security_event(text, jsonb); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.audit_security_event(p_event text, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO audit.audit_log(tipo_evento, id_actor, payload)
  VALUES (p_event, auth.jwt_user_id_safe(), COALESCE(p_payload, '{}'::jsonb));
END;
$$;


--
-- Name: buscar_vendedores_cercanos(double precision, double precision, double precision, text, integer, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.buscar_vendedores_cercanos(p_latitud double precision, p_longitud double precision, p_radio_metros double precision DEFAULT 5000, p_search_term text DEFAULT NULL::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id_vendedor uuid, nombre_tienda text, distancia_metros double precision, reputacion_score double precision, categoria_principal text, score_hibrido double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'api', 'auth', 'audit', 'ag_catalog'
    AS $$
DECLARE
  v_actor uuid;
  v_radio double precision;
  v_limit integer;
  v_offset integer;
BEGIN
  v_actor := auth.jwt_user_id_safe();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='28000', MESSAGE='AUTENTICACION_REQUERIDA';
  END IF;

  IF p_latitud IS NULL OR p_longitud IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='COORDENADAS_REQUERIDAS';
  END IF;
  IF p_latitud < -90 OR p_latitud > 90 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='LATITUD_INVALIDA';
  END IF;
  IF p_longitud < -180 OR p_longitud > 180 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='LONGITUD_INVALIDA';
  END IF;

  v_radio := api.validar_radio_metros(p_radio_metros);
  v_limit := LEAST(GREATEST(COALESCE(p_limit,20),1),100);
  v_offset := GREATEST(COALESCE(p_offset,0),0);

  INSERT INTO audit.audit_log(tipo_evento, id_actor, payload)
  VALUES (
    'CU-C-010.BUSQUEDA_GEO',
    v_actor,
    jsonb_build_object('latitud',p_latitud,'longitud',p_longitud,'radio_metros',v_radio,'search_term',p_search_term,'limit',v_limit,'offset',v_offset)
  );

  RETURN QUERY
  SELECT
    p.id_usuario::uuid AS id_vendedor,
    COALESCE(
      to_jsonb(p)->>'tienda_nombre',
      to_jsonb(p)->>'store_name',
      to_jsonb(p)->>'display_name',
      to_jsonb(p)->>'full_name',
      to_jsonb(p)->>'name',
      'SIN_NOMBRE'
    ) AS nombre_tienda,
    ST_Distance(l.geom::geography, ST_SetSRID(ST_MakePoint(p_longitud,p_latitud),4326)::geography) AS distancia_metros,
    COALESCE(
      NULLIF(to_jsonb(p)->>'reputacion_score','')::double precision,
      NULLIF(to_jsonb(p)->>'reputation_score','')::double precision,
      NULLIF(to_jsonb(p)->>'rating_score','')::double precision,
      0.0
    ) AS reputacion_score,
    COALESCE(to_jsonb(p)->>'categoria_text', to_jsonb(p)->>'categoria_nombre') AS categoria_principal,
    (
      ST_Distance(l.geom::geography, ST_SetSRID(ST_MakePoint(p_longitud,p_latitud),4326)::geography)*0.3
      - COALESCE(
          NULLIF(to_jsonb(p)->>'reputacion_score','')::double precision,
          NULLIF(to_jsonb(p)->>'reputation_score','')::double precision,
          NULLIF(to_jsonb(p)->>'rating_score','')::double precision,
          0.0
        )*0.7
    )::double precision AS score_hibrido
  FROM public.perfiles p
  JOIN auth.ubicaciones l ON l.id_usuario = p.id_usuario
  WHERE l.geom IS NOT NULL
    AND COALESCE(NULLIF(to_jsonb(p)->>'is_active','')::boolean, true) = true
    AND to_jsonb(p)->>'deleted_at' IS NULL
    AND COALESCE(NULLIF(to_jsonb(l)->>'is_active','')::boolean, true) = true
    AND to_jsonb(l)->>'deleted_at' IS NULL
    AND ST_DWithin(l.geom::geography, ST_SetSRID(ST_MakePoint(p_longitud,p_latitud),4326)::geography, v_radio)
    AND (
      p_search_term IS NULL OR btrim(p_search_term)=''
      OR COALESCE(to_jsonb(p)->>'tienda_nombre',to_jsonb(p)->>'display_name',to_jsonb(p)->>'full_name',to_jsonb(p)->>'name','') ILIKE '%'||p_search_term||'%'
      OR COALESCE(to_jsonb(p)->>'categoria_text',to_jsonb(p)->>'categoria_nombre','') ILIKE '%'||p_search_term||'%'
    )
  ORDER BY score_hibrido ASC
  LIMIT v_limit OFFSET v_offset;
END;
$$;


--
-- Name: buscar_vendedores_cercanos_safe(double precision, double precision, double precision, text, integer, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.buscar_vendedores_cercanos_safe(p_latitud double precision, p_longitud double precision, p_radio_metros double precision DEFAULT 5000, p_search_term text DEFAULT NULL::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id_vendedor uuid, nombre_tienda text, distancia_metros double precision, reputacion_score double precision, categoria_principal text, score_hibrido double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT * FROM api.buscar_vendedores_cercanos(p_latitud,p_longitud,p_radio_metros,p_search_term,p_limit,p_offset);
EXCEPTION
  WHEN SQLSTATE '22023' THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='PARAMETRO_INVALIDO_CU_C_010';
  WHEN SQLSTATE '28000' THEN
    RAISE EXCEPTION USING ERRCODE='28000', MESSAGE='NO_AUTORIZADO_CU_C_010';
  WHEN OTHERS THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='FALLO_CONTROLADO_CU_C_010: ' || SQLERRM;
END;
$$;


--
-- Name: get_bridge_buyers(uuid, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_bridge_buyers(p_id_vendedor uuid, p_limite integer DEFAULT 10) RETURNS TABLE(id_comprador uuid, influence_score integer, etiqueta text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'api', 'ag_catalog'
    AS $_$
BEGIN
  RETURN QUERY
  SELECT
    (r.id_comprador::text)::UUID    AS id_comprador,
    r.network_reach::INT        AS influence_score,
    CASE
      WHEN r.network_reach >= 10 THEN 'influencer_local'
      WHEN r.network_reach >= 5  THEN 'cliente_alta_conectividad'
      ELSE 'cliente_conectado'
    END AS etiqueta
  FROM cypher('smtp_posix_graph', $cypher$
    -- ⚠️ ADAPTER: reemplazar :Comprador, :Vendedor, :COMPRO_A, :CONOCE
    -- con labels y aristas reales del grafo (detección 4.6)
    MATCH (b:Comprador)-[:COMPRO_A]->(s:Vendedor {id_sql: $id_vendedor})
    WITH b, s
    MATCH (b)-[:CONOCE|:INTERACTUO_CON*1..2]->(x)
    WHERE x.estado = 'active'
    WITH b, count(DISTINCT x) AS network_reach
    WHERE network_reach > 0
    RETURN
      b.id_sql AS id_comprador,
      network_reach
    ORDER BY network_reach DESC
    LIMIT $limite
  $cypher$, jsonb_build_object(
    'id_vendedor', p_id_vendedor::text,
    'limite',    p_limite
  )) AS r(id_comprador, network_reach);

EXCEPTION WHEN OTHERS THEN
  -- Degradación elegante si AGE no disponible o labels no existen
  RAISE WARNING 'get_bridge_buyers: AGE no disponible o labels incorrectos: %', SQLERRM;
  RETURN;
END;
$_$;


--
-- Name: get_demand_gaps(uuid, integer, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_demand_gaps(p_id_vendedor uuid, p_radio_metros integer DEFAULT 1000, p_dias_atras integer DEFAULT 7) RETURNS TABLE(gap_lat double precision, gap_lng double precision, busquedas_vacias bigint, categoria text, ultima_busqueda timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'api', 'analytics', 'ag_catalog'
    AS $$
DECLARE
  v_anchor_geom GEOMETRY;
BEGIN
  SELECT geom INTO v_anchor_geom
  FROM api.get_seller_anchor(p_id_vendedor);

  IF v_anchor_geom IS NULL THEN
    RAISE EXCEPTION 'Vendedor sin ubicación operativa vigente. Requiere check-in activo.';
  END IF;

  RETURN QUERY
  SELECT
    ST_Y(s.search_point)    AS gap_lat,
    ST_X(s.search_point)    AS gap_lng,
    count(*)                AS busquedas_vacias,
    s.categoria,
    max(s.buscado_en)      AS ultima_busqueda
  FROM analytics.telemetria_busqueda s
  WHERE s.tiene_resultado = false
    AND ST_DWithin(
          s.search_point::geography,
          v_anchor_geom::geography,
          p_radio_metros
        )
    AND s.buscado_en >= now() - (p_dias_atras || ' days')::INTERVAL
  GROUP BY s.search_point, s.categoria
  ORDER BY busquedas_vacias DESC
  LIMIT 50;
END;
$$;


--
-- Name: get_loyalty_ranking(uuid, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_loyalty_ranking(p_id_vendedor uuid, p_limite integer DEFAULT 20) RETURNS TABLE(id_comprador uuid, compras_confirmadas bigint, ultima_compra timestamp with time zone, etiqueta text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'api', 'ag_catalog'
    AS $$
  SELECT
    o.id_comprador,
    count(*)                AS compras_confirmadas,
    max(o.fecha_confirmacion)     AS ultima_compra,
    CASE
      WHEN count(*) >= 5
        THEN 'cliente_frecuente'
      WHEN min(o.fecha_confirmacion)::date >= CURRENT_DATE - INTERVAL '30 days'
        THEN 'nuevo_en_la_zona'
      ELSE 'cliente_recurrente'
    END AS etiqueta
  FROM auth.ordenes o
  JOIN auth.users u ON u.id = o.id_comprador
  WHERE o.id_vendedor = p_id_vendedor
    AND o.estado = 'confirmed'
    AND u.activo  = true
    AND u.fecha_eliminacion IS NULL
  GROUP BY o.id_comprador
  ORDER BY compras_confirmadas DESC
  LIMIT p_limite;
$$;


--
-- Name: get_opportunity_signal(uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_opportunity_signal(p_id_vendedor uuid) RETURNS TABLE(semaforo text, score integer, busquedas_vacias bigint, vendedores_cercanos bigint, mensaje text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'api', 'analytics', 'ag_catalog'
    AS $$
DECLARE
  v_anchor_geom        GEOMETRY;
  v_busquedas_vacias   BIGINT;
  v_vendedores_cercanos BIGINT;
  v_score              INT;
BEGIN
  SELECT geom, checkin_en INTO v_anchor_geom FROM api.get_seller_anchor(p_id_vendedor);

  IF v_anchor_geom IS NULL THEN
    RETURN QUERY SELECT
      'GRIS'::TEXT,
      0::INT,
      0::BIGINT,
      0::BIGINT,
      'Sin check-in activo. Realiza check-in para ver oportunidades.'::TEXT;
    RETURN;
  END IF;

  SELECT count(*) INTO v_busquedas_vacias
  FROM analytics.telemetria_busqueda
  WHERE tiene_resultado = false
    AND ST_DWithin(search_point::geography, v_anchor_geom::geography, 1000)
    AND buscado_en >= now() - INTERVAL '7 days';

  SELECT count(*) INTO v_vendedores_cercanos
  FROM public.perfiles p
  JOIN auth.users u     ON u.id = p.id_usuario
  JOIN auth.ubicaciones l ON l.id_usuario = u.id
  WHERE p.role = 'vendedor'
    AND p.id  != p_id_vendedor
    AND u.activo  = true
    AND u.fecha_eliminacion IS NULL
    AND l.is_merchant_spot = true
    AND ST_DWithin(l.geom::geography, v_anchor_geom::geography, 1000);

  v_score := LEAST(100, (v_busquedas_vacias * 10) - (v_vendedores_cercanos * 5));
  v_score := GREATEST(0, v_score);

  RETURN QUERY SELECT
    CASE
      WHEN v_score >= 60 THEN 'VERDE'
      WHEN v_score >= 30 THEN 'AMARILLO'
      ELSE 'ROJO'
    END::TEXT,
    v_score::INT,
    v_busquedas_vacias,
    v_vendedores_cercanos,
    CASE
      WHEN v_score >= 60 THEN 'Alta demanda insatisfecha cercana. Buena ubicación.'
      WHEN v_score >= 30 THEN 'Demanda moderada. Considera explorar zonas adyacentes.'
      ELSE 'Baja demanda o zona saturada. Evalúa reubicación.'
    END::TEXT;
END;
$$;


--
-- Name: get_seller_anchor(uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_seller_anchor(p_id_vendedor uuid) RETURNS TABLE(id_vendedor uuid, id_usuario uuid, geom public.geometry, checkin_en timestamp with time zone, horas_activo double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'api', 'ag_catalog'
    AS $$
  SELECT
    p.id                                                      AS id_vendedor,
    p.id_usuario,
    l.geom,
    l.checkin_en,
    EXTRACT(EPOCH FROM (now() - l.checkin_en)) / 3600.0       AS horas_activo
  FROM public.perfiles p
  JOIN auth.users u     ON u.id = p.id_usuario
  JOIN auth.ubicaciones l ON l.id_usuario = u.id
  WHERE p.id   = p_id_vendedor
    AND p.role = 'vendedor'
    AND u.activo    = true
    AND u.fecha_eliminacion   IS NULL
    AND l.is_merchant_spot = true
    AND l.checkin_en > now() - INTERVAL '8 hours'
  LIMIT 1;
$$;


--
-- Name: get_seller_intelligence_dashboard(uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_seller_intelligence_dashboard(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'api', 'analytics', 'ag_catalog'
    AS $$
DECLARE
  v_result        JSONB := '{}'::JSONB;
  v_semaforo      JSONB;
  v_ventas        JSONB;
  v_loyalty       JSONB;
  v_bridge_buyers JSONB;
  v_demand_gaps   JSONB;
  v_anchor        JSONB;
  v_caller_id     UUID;
BEGIN
  v_caller_id := auth.jwt_user_id_safe();

  IF p_id_vendedor NOT IN (
    SELECT p.id FROM public.perfiles p
    JOIN auth.users u ON u.id = p.id_usuario
    WHERE u.id = v_caller_id
      AND p.role = 'vendedor'
      AND u.activo  = true
      AND u.fecha_eliminacion IS NULL
  ) AND NOT EXISTS (
    SELECT 1 FROM auth.users
    WHERE id = v_caller_id
      AND role = 'admin'
      AND activo  = true
      AND fecha_eliminacion IS NULL
  ) THEN
    RAISE EXCEPTION 'Acceso denegado: solo el propietario o admin puede consultar este dashboard';
  END IF;

  BEGIN
    SELECT jsonb_agg(row_to_json(a)) INTO v_anchor
    FROM api.get_seller_anchor(p_id_vendedor) a;
    v_result := v_result || jsonb_build_object(
      'anchor', COALESCE(v_anchor, '[]'::JSONB)
    );
  EXCEPTION WHEN OTHERS THEN
    v_result := v_result || jsonb_build_object(
      'anchor', NULL, 'anchor_error', SQLERRM
    );
  END;

  BEGIN
    SELECT jsonb_agg(row_to_json(s)) INTO v_semaforo
    FROM api.get_opportunity_signal(p_id_vendedor) s;
    v_result := v_result || jsonb_build_object(
      'semaforo', COALESCE(v_semaforo, '[]'::JSONB)
    );
  EXCEPTION WHEN OTHERS THEN
    v_result := v_result || jsonb_build_object(
      'semaforo', NULL, 'semaforo_error', SQLERRM
    );
  END;

  BEGIN
    SELECT jsonb_agg(row_to_json(v)) INTO v_ventas
    FROM api.get_ventas_del_dia(p_id_vendedor) v;
    v_result := v_result || jsonb_build_object(
      'ventas_hoy', COALESCE(v_ventas, '[]'::JSONB)
    );
  EXCEPTION WHEN OTHERS THEN
    v_result := v_result || jsonb_build_object(
      'ventas_hoy', NULL,
      'ventas_error', 'Fuente transaccional no configurada o columnas incompatibles'
    );
  END;

  BEGIN
    SELECT jsonb_agg(row_to_json(l)) INTO v_loyalty
    FROM api.get_loyalty_ranking(p_id_vendedor) l;
    v_result := v_result || jsonb_build_object(
      'ranking_lealtad', COALESCE(v_loyalty, '[]'::JSONB)
    );
  EXCEPTION WHEN OTHERS THEN
    v_result := v_result || jsonb_build_object(
      'ranking_lealtad', NULL,
      'lealtad_error', SQLERRM
    );
  END;

  BEGIN
    SELECT jsonb_agg(row_to_json(d)) INTO v_demand_gaps
    FROM api.get_demand_gaps(p_id_vendedor) d;
    v_result := v_result || jsonb_build_object(
      'demand_gaps', COALESCE(v_demand_gaps, '[]'::JSONB)
    );
  EXCEPTION WHEN OTHERS THEN
    v_result := v_result || jsonb_build_object(
      'demand_gaps', NULL, 'gaps_error', SQLERRM
    );
  END;

  BEGIN
    SELECT jsonb_agg(row_to_json(b)) INTO v_bridge_buyers
    FROM api.get_bridge_buyers(p_id_vendedor, 20) b;
    v_result := v_result || jsonb_build_object(
      'bridge_buyers', COALESCE(v_bridge_buyers, '[]'::JSONB)
    );
  EXCEPTION WHEN OTHERS THEN
    v_result := v_result || jsonb_build_object(
      'bridge_buyers', NULL, 'bridge_error', SQLERRM
    );
  END;

  RETURN v_result;
END;
$$;


--
-- Name: get_ventas_del_dia(uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_ventas_del_dia(p_id_vendedor uuid) RETURNS TABLE(ventas_hoy bigint, total_hoy numeric, ultima_venta_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'api', 'ag_catalog'
    AS $$
  SELECT
    count(*)                    AS ventas_hoy,
    COALESCE(sum(o.total), 0)   AS total_hoy,
    max(o.fecha_confirmacion)         AS ultima_venta_at
  FROM auth.ordenes o
  JOIN auth.users u ON u.id = o.id_comprador
  WHERE o.id_vendedor = p_id_vendedor
    AND o.fecha_confirmacion::date = CURRENT_DATE
    AND o.estado = 'confirmed'
    AND u.activo  = true
    AND u.fecha_eliminacion IS NULL;
$$;


--
-- Name: recomendar_vendedores_grafo(uuid, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.recomendar_vendedores_grafo(p_id_comprador uuid, p_limit integer DEFAULT 5) RETURNS TABLE(id_vendedor uuid, nombre_vendedor text, categoria text, score bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'api', 'auth', 'audit', 'ag_catalog'
    AS $_$
DECLARE
  v_actor uuid;
  v_limit integer;
  v_graph text;
  r record;
BEGIN
  v_actor := auth.jwt_user_id_safe();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='28000', MESSAGE='AUTENTICACION_REQUERIDA';
  END IF;

  IF p_id_comprador IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='P_COMPRADOR_ID_REQUERIDO';
  END IF;

  IF p_id_comprador <> v_actor THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='NO_AUTORIZADO_VER_RECOMENDACIONES_AJENAS';
  END IF;

  v_limit := LEAST(GREATEST(COALESCE(p_limit,5),1),50);

  BEGIN
    SELECT name INTO v_graph FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_graph := NULL;
  END;

  IF v_graph IS NULL THEN
    RETURN; -- degradación controlada
  END IF;

  FOR r IN
    SELECT
      q.id_vendedor::text::uuid AS id_vendedor,
      q.nombre_vendedor::text AS nombre_vendedor,
      q.categoria::text AS categoria,
      q.score::bigint AS score
    FROM cypher(
      v_graph,
      format($cypher$
        MATCH (c:Comprador {id: "%s"})-[:COMPRO_A]->(v_hist:Vendedor)
        MATCH (c2:Comprador)-[:COMPRO_A]->(v_hist)
        MATCH (c2)-[:COMPRO_A]->(v_rec:Vendedor)
        WHERE v_rec.id <> v_hist.id
          AND coalesce(v_rec.estado,'active') = 'active'
        RETURN v_rec.id AS id_vendedor,
               coalesce(v_rec.nombre,'SIN_NOMBRE') AS nombre_vendedor,
               coalesce(v_rec.categoria,null) AS categoria,
               count(DISTINCT c2) AS score
        ORDER BY score DESC
        LIMIT %s
      $cypher$, p_id_comprador::text, v_limit)
    ) AS q(id_vendedor, nombre_vendedor, categoria, score)
  LOOP
    INSERT INTO audit.recomendaciones_entregadas(id_comprador, vendedor_recomendado_id, categoria, score)
    VALUES (p_id_comprador, r.id_vendedor, r.categoria, r.score);

    INSERT INTO audit.audit_log(tipo_evento, id_actor, payload)
    VALUES (
      'CU-C-011.RECOMENDACION_ENTREGADA',
      v_actor,
      jsonb_build_object(
        'id_comprador', p_id_comprador,
        'id_vendedor', r.id_vendedor,
        'categoria', r.categoria,
        'score', r.score
      )
    );

    id_vendedor := r.id_vendedor;
    nombre_vendedor := r.nombre_vendedor;
    categoria := r.categoria;
    score := r.score;
    RETURN NEXT;
  END LOOP;
END;
$_$;


--
-- Name: recomendar_vendedores_grafo_safe(uuid, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.recomendar_vendedores_grafo_safe(p_id_comprador uuid, p_limit integer DEFAULT 5) RETURNS TABLE(id_vendedor uuid, nombre_vendedor text, categoria text, score bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY SELECT * FROM api.recomendar_vendedores_grafo(p_id_comprador,p_limit);
EXCEPTION
  WHEN SQLSTATE '42501' THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='ACCESO_DENEGADO_CU_C_011';
  WHEN SQLSTATE '22004' THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='PARAMETROS_INCOMPLETOS_CU_C_011';
  WHEN OTHERS THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='FALLO_CONTROLADO_CU_C_011: '||SQLERRM;
END;
$$;


--
-- Name: registrar_contrato_frontend(text, text, jsonb); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.registrar_contrato_frontend(p_contract_name text, p_version text, p_schema jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'pg_temp'
    AS $$
BEGIN
  IF p_contract_name IS NULL OR btrim(p_contract_name) = '' THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='CONTRACT_NAME_INVALIDO';
  END IF;
  IF p_version IS NULL OR btrim(p_version) = '' THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='VERSION_INVALIDA';
  END IF;
  IF p_schema IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='SCHEMA_REQUERIDO';
  END IF;

  INSERT INTO api.frontend_contract_registry(contract_name, version, json_schema)
  VALUES (p_contract_name, p_version, p_schema)
  ON CONFLICT (contract_name) DO UPDATE
    SET version = EXCLUDED.version,
        json_schema = EXCLUDED.json_schema,
        fecha_actualizacion = now();

  INSERT INTO audit.audit_log(tipo_evento, id_actor, payload)
  VALUES ('CU-C-012.CONTRATO_FRONTEND', NULL,
          jsonb_build_object('contract_name',p_contract_name,'version',p_version));

  RETURN jsonb_build_object('ok', true, 'contract_name', p_contract_name, 'version', p_version);
END;
$$;


--
-- Name: registrar_contrato_frontend_safe(text, text, jsonb); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.registrar_contrato_frontend_safe(p_contract_name text, p_version text, p_schema jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'pg_temp'
    AS $$
BEGIN
  RETURN api.registrar_contrato_frontend(p_contract_name, p_version, p_schema);
EXCEPTION
  WHEN SQLSTATE '22023' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'VALIDATION_ERROR', 'message', SQLERRM);
  WHEN SQLSTATE '22004' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NULL_ERROR', 'message', SQLERRM);
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INTERNAL_ERROR', 'message', SQLERRM);
END;
$$;


--
-- Name: sync_vendedor_status_to_age(uuid, text); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.sync_vendedor_status_to_age(p_id_vendedor uuid, p_nuevo_estado text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'api', 'audit', 'ag_catalog'
    AS $_$
DECLARE
  v_graph_name text;
  v_sync_status text := 'skipped';
  v_sqlstate text := NULL;
  v_error text := NULL;
BEGIN
  IF p_id_vendedor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22004', MESSAGE='VENDEDOR_ID_REQUERIDO';
  END IF;

  IF p_nuevo_estado NOT IN ('active','inactive') THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='ESTADO_INVALIDO';
  END IF;

  BEGIN
    SELECT name INTO v_graph_name FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_graph_name := NULL;
  END;

  IF v_graph_name IS NOT NULL THEN
    BEGIN
      PERFORM * FROM cypher(
        v_graph_name,
        format($cypher$
          MERGE (v:Vendedor {id: "%s"})
          SET v.estado = "%s"
          RETURN v
        $cypher$, p_id_vendedor::text, p_nuevo_estado)
      ) AS (_ agtype);
      v_sync_status := 'synced';
    EXCEPTION WHEN OTHERS THEN
      v_sync_status := 'failed';
      v_sqlstate := SQLSTATE;
      v_error := SQLERRM;
    END;
  END IF;

  INSERT INTO audit.audit_log(tipo_evento, id_actor, payload)
  VALUES (
    'CU-C-014.SYNC_SQL_AGE',
    NULL,
    jsonb_build_object(
      'id_vendedor', p_id_vendedor,
      'estado_sql', p_nuevo_estado,
      'estado_age', CASE WHEN v_sync_status='synced' THEN p_nuevo_estado ELSE NULL END,
      'sync_status', v_sync_status,
      'error_sqlstate', v_sqlstate,
      'error_message', v_error
    )
  );

  RETURN jsonb_build_object(
    'id_vendedor', p_id_vendedor,
    'estado_sql', p_nuevo_estado,
    'estado_age', CASE WHEN v_sync_status='synced' THEN p_nuevo_estado ELSE NULL END,
    'sync_status', v_sync_status,
    'error_sqlstate', v_sqlstate,
    'error_message', v_error
  );
END;
$_$;


--
-- Name: sync_vendedor_status_to_age_safe(uuid, text); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.sync_vendedor_status_to_age_safe(p_id_vendedor uuid, p_nuevo_estado text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'pg_temp'
    AS $$
BEGIN
  RETURN api.sync_vendedor_status_to_age(p_id_vendedor, p_nuevo_estado);
EXCEPTION
  WHEN SQLSTATE '22004' THEN
    RETURN jsonb_build_object('ok',false,'code','NULL_PARAM','message',SQLERRM);
  WHEN SQLSTATE '22023' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_PARAM','message',SQLERRM);
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok',false,'code','INTERNAL_ERROR','message',SQLERRM);
END;
$$;


--
-- Name: validar_radio_metros(double precision); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.validar_radio_metros(p_radio_metros double precision) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  IF p_radio_metros IS NULL OR p_radio_metros <= 0 THEN
    RETURN 5000;
  ELSIF p_radio_metros > 50000 THEN
    RETURN 50000;
  END IF;
  RETURN p_radio_metros;
END;
$$;


--
-- Name: actualizar_fecha_actualizacion(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.actualizar_fecha_actualizacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
        NEW.actualizado_en = now();
        RETURN NEW;
    END;
    $$;


--
-- Name: alternar_visibilidad_ruta(text, text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.alternar_visibilidad_ruta(p_schema_name text, p_object_name text, p_visible boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app, pg_temp'
    AS $$
    DECLARE
        v_object_type  text;
        v_owner_name   text;
        v_rls_toggled  boolean := false;
        v_rls_enforced boolean := false;
        v_full_name    text;
    BEGIN
        IF NOT public.is_admin_activo() THEN
            RAISE EXCEPTION 'Solo administradores activos pueden cambiar la visibilidad de rutas'
                USING ERRCODE = '42501';
        END IF;

        -- Resolver tipo + owner desde pg_class (tablas/vistas/MVs)
        SELECT CASE c.relkind
                    WHEN 'r' THEN 'table'
                    WHEN 'v' THEN 'view'
                    WHEN 'm' THEN 'materialized_view'
                    ELSE NULL END,
                pg_get_userbyid(c.relowner)
           INTO v_object_type, v_owner_name
           FROM pg_catalog.pg_class c
           JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
          WHERE n.nspname = p_schema_name AND c.relname = p_object_name;

        IF v_object_type IS NULL THEN
            -- funciones viven en pg_proc, no en pg_class
            IF EXISTS (
                SELECT 1 FROM pg_catalog.pg_proc p
                JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
                WHERE n.nspname = p_schema_name AND p.proname = p_object_name
            ) THEN
                v_object_type := 'function';
            ELSE
                RAISE EXCEPTION 'Objeto %s.%s no encontrado', p_schema_name, p_object_name
                    USING ERRCODE = '42704';
            END IF;
        END IF;

        v_full_name := quote_ident(p_schema_name) || '.' || quote_ident(p_object_name);

        -- RLS interino: solo si es tabla propia (evita 'permiso denegado')
        IF v_object_type = 'table' AND v_owner_name = current_user THEN
            IF p_visible THEN
                EXECUTE format('ALTER TABLE %s DISABLE ROW LEVEL SECURITY', v_full_name);
                v_rls_enforced := false;
            ELSE
                EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', v_full_name);
                v_rls_enforced := true;
            END IF;
            v_rls_toggled := true;
        ELSE
            -- objeto ajeno o no-tabla: solo catalogamos la visibilidad (interino)
            v_rls_enforced := false;
        END IF;

        -- UPSERT en el catálogo de rutas (nombres españoles)
        INSERT INTO app.catalogo_rutas
            (nombre_esquema, tipo_objeto, nombre_objeto, visible, rls_activado, actualizado_en)
        VALUES (p_schema_name, v_object_type, p_object_name, p_visible, v_rls_enforced, now())
        ON CONFLICT (nombre_esquema, nombre_objeto, tipo_objeto)
        DO UPDATE SET visible       = EXCLUDED.visible,
                      rls_activado  = EXCLUDED.rls_activado,
                      actualizado_en = now();

        RETURN jsonb_build_object(
            'ok',           true,
            'schema',       p_schema_name,
            'object',       p_object_name,
            'object_type',  v_object_type,
            'visibility',   p_visible,
            'rls_toggled',  v_rls_toggled,
            'rls_enforced', v_rls_enforced
        );
    END;
    $$;


--
-- Name: assert_buyer_tier_constraints(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.assert_buyer_tier_constraints(p_id_comprador uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_tier text := COALESCE(auth.resolve_effective_tier(p_id_comprador), 'bronze');
  v_max_open integer;
  v_open_orders integer;
BEGIN
  SELECT numeric_value INTO v_max_open
  FROM public.commercial_tier_rule_values
  WHERE actor_role = 'buyer' AND tier_code = v_tier AND rule_code = 'max_open_orders';

  SELECT COUNT(*)::integer INTO v_open_orders
  FROM auth.ordenes
  WHERE id_comprador = p_id_comprador
    AND estado IN ('proposed','assigned','payment_confirmed');

  IF v_max_open IS NOT NULL AND v_open_orders >= v_max_open THEN
    RAISE EXCEPTION 'LIMITE_ORDENES_ALCANZADO_PARA_PERFIL_%', v_tier USING ERRCODE = 'P0001';
  END IF;
END;
$$;


--
-- Name: assert_seller_tier_constraints(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.assert_seller_tier_constraints(p_id_vendedor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_tier text := COALESCE(auth.resolve_effective_tier(p_id_vendedor), 'bronze');
  v_max_active integer;
  v_active integer;
BEGIN
  SELECT numeric_value INTO v_max_active
  FROM public.commercial_tier_rule_values
  WHERE actor_role = 'seller' AND tier_code = v_tier AND rule_code = 'max_concurrent_orders';

  IF v_max_active IS NULL THEN
    RAISE EXCEPTION 'TIER_RULE_NOT_FOUND: max_concurrent_orders para tier %', v_tier USING ERRCODE = 'P0003';
  END IF;

  SELECT COUNT(*)::integer INTO v_active
  FROM auth.ordenes
  WHERE id_vendedor = p_id_vendedor
    AND estado IN ('assigned','payment_confirmed','preparing','in_delivery');

  IF v_active >= v_max_active THEN
    RAISE EXCEPTION 'SELLER_TIER_EXCEEDED: % ventas activas, max %', v_active, v_max_active USING ERRCODE = 'P0007';
  END IF;
END;
$$;


--
-- Name: auth_fn_calcular_clusters_compradores(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.auth_fn_calcular_clusters_compradores(p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS TABLE(cluster_id integer, total_compradores bigint, centroid public.geometry, radio_km numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_now timestamp with time zone := now();
    v_eps double precision := 0.005; -- ~500m en grados
BEGIN
    RETURN QUERY
    WITH ubicaciones_activas AS (
        SELECT DISTINCT ON (ub.id_usuario)
               ub.id_usuario,
               ub.geom
          FROM auth.ubicaciones ub
         WHERE ub.is_active IS NOT FALSE
           AND ub.fecha_eliminacion IS NULL
           AND ub.geom IS NOT NULL
           AND (p_id_vendedor IS NULL OR EXISTS (
                SELECT 1 FROM auth.ordenes o
                WHERE o.id_comprador = ub.id_usuario
                  AND o.id_vendedor = p_id_vendedor
                  AND o.estado = 'completed'
           ))
         ORDER BY ub.id_usuario, ub.fecha_actualizacion DESC
    ),
    clustered AS (
        SELECT ua.id_usuario,
               ST_ClusterDBSCAN(ua.geom, v_eps, 2) OVER () AS cid,
               ua.geom
          FROM ubicaciones_activas ua
    )
    SELECT c.cid,
           count(DISTINCT c.id_usuario)::bigint AS total_compradores,
           ST_Centroid(ST_Collect(c.geom)) AS centroid,
           (ST_MaxDistance(ST_Collect(c.geom), ST_Centroid(ST_Collect(c.geom))) / 1000.0)::numeric AS radio_km
      FROM clustered c
     WHERE c.cid >= 0
     GROUP BY c.cid
     ORDER BY total_compradores DESC;
END;
$$;


--
-- Name: auth_fn_calcular_prediccion_demanda(uuid, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.auth_fn_calcular_prediccion_demanda(p_id_vendedor uuid DEFAULT NULL::uuid, p_region_code text DEFAULT NULL::text, p_horizonte_dias integer DEFAULT 30) RETURNS TABLE(region_code text, lat double precision, lon double precision, demanda_estimada numeric, intervalo_confianza_inf numeric, intervalo_confianza_sup numeric, total_historicos bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_corte timestamp with time zone := now() - (p_horizonte_dias || ' days')::interval;
BEGIN
    RETURN QUERY
    WITH ordenes_historicas AS (
        SELECT o.region_code,
               o.id_vendedor,
               count(*) AS total_ordenes,
               avg(o.total) AS ticket_promedio
          FROM auth.ordenes o
         WHERE o.estado = 'completed'
           AND o.fecha_creacion >= v_corte
           AND (p_id_vendedor IS NULL OR o.id_vendedor = p_id_vendedor)
           AND (p_region_code IS NULL OR o.region_code = p_region_code)
         GROUP BY o.region_code, o.id_vendedor
    ),
    region_centroids AS (
        SELECT DISTINCT ON (o2.region_code)
               o2.region_code,
               ST_Y(o2.location_delivery::geometry) AS lat,
               ST_X(o2.location_delivery::geometry) AS lon
          FROM auth.ordenes o2
         WHERE o2.location_delivery IS NOT NULL
           AND o2.estado = 'completed'
    )
    SELECT COALESCE(oh.region_code, p_region_code) AS region,
           COALESCE(rc.lat, 0)::double precision,
           COALESCE(rc.lon, 0)::double precision,
           COALESCE(oh.total_ordenes * COALESCE(oh.ticket_promedio, 1), 0) AS demanda_estimada,
           COALESCE(oh.total_ordenes * COALESCE(oh.ticket_promedio, 1) * 0.85, 0) AS intervalo_inf,
           COALESCE(oh.total_ordenes * COALESCE(oh.ticket_promedio, 1) * 1.15, 0) AS intervalo_sup,
           COALESCE(oh.total_ordenes, 0::bigint) AS total_historico
      FROM ordenes_historicas oh
      LEFT JOIN region_centroids rc ON rc.region_code = oh.region_code
     ORDER BY oh.total_ordenes DESC;
END;
$$;


--
-- Name: auth_fn_detectar_geofence_local(uuid, double precision, double precision, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.auth_fn_detectar_geofence_local(p_id_usuario uuid DEFAULT NULL::uuid, p_lat double precision DEFAULT NULL::double precision, p_lon double precision DEFAULT NULL::double precision, p_tipo_zona text DEFAULT NULL::text) RETURNS TABLE(dentro boolean, id_zona uuid, nombre_zona text, tipo_zona text, distancia_km double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_lat double precision := p_lat;
    v_lon double precision := p_lon;
    v_punto geometry;
BEGIN
    -- Derivar coordenadas desde ubicación activa si no se pasaron directamente
    IF (v_lat IS NULL OR v_lon IS NULL) AND p_id_usuario IS NOT NULL THEN
        SELECT ST_Y(ub.geom::geometry), ST_X(ub.geom::geometry)
          INTO v_lat, v_lon
          FROM auth.ubicaciones ub
         WHERE ub.id_usuario = p_id_usuario
           AND ub.is_active IS NOT FALSE
           AND ub.fecha_eliminacion IS NULL
         ORDER BY ub.fecha_actualizacion DESC NULLS LAST
         LIMIT 1;
    END IF;

    IF v_lat IS NULL OR v_lon IS NULL THEN
        RETURN QUERY SELECT false, NULL::uuid, NULL::text, NULL::text, NULL::double precision;
        RETURN;
    END IF;

    v_punto := ST_SetSRID(ST_MakePoint(v_lon, v_lat), 4326);

    RETURN QUERY
    SELECT true,
           z.id_zona,
           z.name,
           z.zone_type,
           ST_Distance(z.geom::geography, v_punto::geography) / 1000.0
      FROM public.geo_zones z
     WHERE z.is_active IS NOT FALSE
       AND z.fecha_eliminacion IS NULL
       AND z.geom IS NOT NULL
       AND (p_tipo_zona IS NULL OR z.zone_type = p_tipo_zona)
       AND ST_Contains(z.geom, v_punto)
     ORDER BY ST_Area(z.geom) ASC
     LIMIT 1;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, NULL::uuid, NULL::text, NULL::text, NULL::double precision;
    END IF;
END;
$$;


--
-- Name: auth_fn_evaluar_triggers_campanas(uuid, double precision, double precision); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.auth_fn_evaluar_triggers_campanas(p_id_comprador uuid, p_lat double precision DEFAULT NULL::double precision, p_lon double precision DEFAULT NULL::double precision) RETURNS TABLE(campania_id uuid, nombre_campania text, activado boolean, tipo_trigger text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_lat double precision := p_lat;
    v_lon double precision := p_lon;
    v_punto geometry;
    v_now timestamp with time zone := now();
BEGIN
    -- Derivar coordenadas si no se pasaron
    IF (v_lat IS NULL OR v_lon IS NULL) AND p_id_comprador IS NOT NULL THEN
        SELECT ST_Y(ub.geom::geometry), ST_X(ub.geom::geometry)
          INTO v_lat, v_lon
          FROM auth.ubicaciones ub
         WHERE ub.id_usuario = p_id_comprador
           AND ub.is_active IS NOT FALSE
           AND ub.fecha_eliminacion IS NULL
         ORDER BY ub.fecha_actualizacion DESC
         LIMIT 1;
    END IF;

    IF v_lat IS NULL OR v_lon IS NULL THEN
        RAISE EXCEPTION 'No se pudo determinar ubicación del comprador %', p_id_comprador
              USING HINT = 'Proporcione lat/lon o asegúrese de que el comprador tenga una ubicación activa',
              ERRCODE = 'P0002';
    END IF;

    v_punto := ST_SetSRID(ST_MakePoint(v_lon, v_lat), 4326);

    -- Evaluar campañas activas con zona geográfica definida
    RETURN QUERY
    WITH campanas_activas AS (
        SELECT c.id, c.nombre, c.metadata
          FROM auth.campanas c
         WHERE c.estado = 'activa'
           AND (c.fecha_inicio IS NULL OR c.fecha_inicio <= v_now)
           AND (c.fecha_fin IS NULL OR c.fecha_fin >= v_now)
    ),
    triggers_evaluados AS (
        SELECT ca.id,
               ca.nombre,
               ca.metadata->>'trigger_type' AS trigger_type
          FROM campanas_activas ca
         WHERE EXISTS (
            SELECT 1
              FROM public.geo_zones gz
             WHERE gz.is_active IS NOT FALSE
               AND gz.fecha_eliminacion IS NULL
               AND gz.geom IS NOT NULL
               AND gz.metadata->>'campania_id' = ca.id::text
               AND ST_Contains(gz.geom, v_punto)
         )
            OR (
                -- Trigger de radio: buscar vendedores cercanos asociados a la campaña
                ca.metadata ? 'radio_km'
                AND EXISTS (
                    SELECT 1
                      FROM public.seller_establishments se
                      JOIN auth.campanias_vendedor cv ON cv.id_vendedor = se.id
                     WHERE cv.id = ca.id
                       AND se.geom IS NOT NULL
                       AND ST_DWithin(se.geom::geography, v_punto::geography,
                            COALESCE((ca.metadata->>'radio_km')::numeric, 1) * 1000)
                )
            )
    ),
    logged AS (
        INSERT INTO auth.eventos_campania (id, campania_id, id_usuario, tipo_evento, metadata, created_at)
        SELECT gen_random_uuid(), te.id, p_id_comprador, 'geo_trigger_activated',
               jsonb_build_object(
                   'lat', v_lat,
                   'lon', v_lon,
                   'trigger_type', COALESCE(te.trigger_type, 'geo_fence'),
                   'evaluated_at', v_now
               ),
               v_now
          FROM triggers_evaluados te
        RETURNING campania_id, tipo_evento
    )
    SELECT te.id, te.nombre, true, COALESCE(te.trigger_type, 'geo_fence')
      FROM triggers_evaluados te;

    IF NOT FOUND THEN
        -- No triggers activados: retornar fila indicativa
        RETURN QUERY
        SELECT NULL::uuid, NULL::text, false, NULL::text
        LIMIT 0; -- empty set means no triggers activated
    END IF;
END;
$$;


--
-- Name: auth_fn_recalcular_geo_cache(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.auth_fn_recalcular_geo_cache(p_id_usuario uuid DEFAULT NULL::uuid) RETURNS TABLE(usuario_id uuid, cluster_id integer, radio_km numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_now timestamp with time zone := now();
BEGIN
    -- Eliminar clusters previos para el/los usuario(s) objetivo
    IF p_id_usuario IS NOT NULL THEN
        DELETE FROM auth.ubicacion_clusters WHERE id_usuario = p_id_usuario;
    ELSE
        DELETE FROM auth.ubicacion_clusters;
    END IF;

    -- Insertar clusters recalculados: agrupar ubicaciones por proximidad (~1km)
    -- usando ST_ClusterDBSCAN para agrupar puntos cercanos
    WITH ranked_ubics AS (
        SELECT ub.id_usuario,
               ub.geom,
               row_number() OVER (PARTITION BY ub.id_usuario ORDER BY ub.fecha_actualizacion DESC) AS rn
          FROM auth.ubicaciones ub
         WHERE ub.is_active IS NOT FALSE
           AND ub.fecha_eliminacion IS NULL
           AND ub.geom IS NOT NULL
           AND (p_id_usuario IS NULL OR ub.id_usuario = p_id_usuario)
    ),
    clustered AS (
        SELECT ru.id_usuario,
               ST_ClusterDBSCAN(ru.geom, 0.01, 1) OVER (PARTITION BY ru.id_usuario) AS cid,
               ru.geom
          FROM ranked_ubics ru
         WHERE ru.rn <= 20  -- últimas 20 ubicaciones por usuario
    ),
    agg_clusters AS (
        SELECT c.id_usuario,
               c.cid AS cluster_id,
               ST_Centroid(ST_Collect(c.geom)) AS centroid,
               array_agg(DISTINCT c.id_usuario) AS locs,
               ST_MaxDistance(ST_Collect(c.geom), ST_Centroid(ST_Collect(c.geom))) / 1000.0 AS radius_km
          FROM clustered c
         WHERE c.cid >= 0
         GROUP BY c.id_usuario, c.cid
    )
    INSERT INTO auth.ubicacion_clusters (id, id_usuario, id_cluster, cluster_centroid, ubicacion_ids, radio_km, calculado_at, metadata)
    SELECT gen_random_uuid(),
           ac.id_usuario,
           ac.cluster_id,
           ac.centroid,
           ac.locs::uuid[],
           COALESCE(ac.radius_km, 0.5),
           v_now,
           jsonb_build_object('recalculo_automatico', true, 'total_puntos', array_length(ac.locs, 1))
      FROM agg_clusters ac
      ORDER BY ac.id_usuario, ac.cluster_id;

    -- Retornar los clusters generados
    RETURN QUERY
    SELECT uc.id_usuario, uc.id_cluster, uc.radio_km
      FROM auth.ubicacion_clusters uc
     WHERE uc.calculado_at = v_now
       AND (p_id_usuario IS NULL OR uc.id_usuario = p_id_usuario)
     ORDER BY uc.id_usuario, uc.id_cluster;
END;
$$;


--
-- Name: auth_fn_registrar_conversion_geo(uuid, uuid, uuid, double precision, double precision); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.auth_fn_registrar_conversion_geo(p_id_comprador uuid, p_id_campania uuid, p_id_orden uuid DEFAULT NULL::uuid, p_lat double precision DEFAULT NULL::double precision, p_lon double precision DEFAULT NULL::double precision) RETURNS TABLE(evento_id uuid, conversion_distancia_km double precision, conversion_exitosa boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_evento_id uuid := gen_random_uuid();
    v_lat double precision := p_lat;
    v_lon double precision := p_lon;
    v_punto geometry;
    v_distancia_km double precision;
    v_campania_valida boolean;
BEGIN
    -- Validar que la campaña existe y está activa
    SELECT EXISTS (
        SELECT 1 FROM auth.campanas c
        WHERE c.id = p_id_campania
          AND c.estado = 'activa'
    ) INTO v_campania_valida;

    IF NOT v_campania_valida THEN
        RAISE EXCEPTION 'La campaña % no existe o no está activa', p_id_campania
              USING ERRCODE = 'P0002';
    END IF;

    -- Derivar coordenadas
    IF (v_lat IS NULL OR v_lon IS NULL) AND p_id_comprador IS NOT NULL THEN
        SELECT ST_Y(ub.geom::geometry), ST_X(ub.geom::geometry)
          INTO v_lat, v_lon
          FROM auth.ubicaciones ub
         WHERE ub.id_usuario = p_id_comprador
           AND ub.is_active IS NOT FALSE
           AND ub.fecha_eliminacion IS NULL
         ORDER BY ub.fecha_actualizacion DESC
         LIMIT 1;
    END IF;

    IF v_lat IS NOT NULL AND v_lon IS NOT NULL THEN
        v_punto := ST_SetSRID(ST_MakePoint(v_lon, v_lat), 4326);

        -- Calcular distancia a la zona geográfica de la campaña más cercana
        SELECT min(ST_Distance(gz.geom::geography, v_punto::geography) / 1000.0)
          INTO v_distancia_km
          FROM public.geo_zones gz
         WHERE gz.is_active IS NOT FALSE
           AND gz.fecha_eliminacion IS NULL
           AND gz.geom IS NOT NULL
           AND gz.metadata->>'campania_id' = p_id_campania::text;
    END IF;

    -- Insertar evento de conversión
    INSERT INTO auth.eventos_campania (id, campania_id, id_usuario, tipo_evento, metadata, created_at)
    VALUES (
        v_evento_id,
        p_id_campania,
        p_id_comprador,
        'conversion',
        jsonb_build_object(
            'id_orden', p_id_orden,
            'lat', v_lat,
            'lon', v_lon,
            'distancia_km', v_distancia_km,
            'conversion_exitosa', true,
            'registrado_en', now()
        ),
        now()
    );

    -- Actualizar contador de conversiones en la campaña
    UPDATE auth.campanas c
       SET conversiones = COALESCE(c.conversiones, 0) + 1
     WHERE c.id = p_id_campania;

    RETURN QUERY
    SELECT v_evento_id, v_distancia_km, true;
END;
$$;


--
-- Name: auth_fn_sync_cerca_de_graph(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.auth_fn_sync_cerca_de_graph(p_id_usuario uuid) RETURNS TABLE(outbox_id uuid, tipo_evento text, estado text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_geom geometry;
    v_radio_km double precision := 1.0; -- radio de cercanía
BEGIN
    -- Obtener ubicación actual del usuario
    SELECT ub.geom INTO v_geom
      FROM auth.ubicaciones ub
     WHERE ub.id_usuario = p_id_usuario
       AND ub.is_active IS NOT FALSE
       AND ub.fecha_eliminacion IS NULL
       AND ub.geom IS NOT NULL
     ORDER BY ub.fecha_actualizacion DESC
     LIMIT 1;

    IF v_geom IS NULL THEN
        RAISE EXCEPTION 'No se encontró ubicación activa para el usuario %', p_id_usuario
              USING HINT = 'Registre una ubicación antes de sincronizar cercanía',
              ERRCODE = 'P0002';
    END IF;

    -- Insertar eventos de cercanía en el outbox
    RETURN QUERY
    WITH cercanos AS (
        SELECT ub2.id_usuario AS id_vecino,
               ST_Distance(v_geom::geography, ub2.geom::geography) / 1000.0 AS distancia_km
          FROM auth.ubicaciones ub2
         WHERE ub2.id_usuario <> p_id_usuario
           AND ub2.is_active IS NOT FALSE
           AND ub2.fecha_eliminacion IS NULL
           AND ub2.geom IS NOT NULL
           AND ST_DWithin(v_geom::geography, ub2.geom::geography, v_radio_km * 1000)
    ),
    inserted AS (
        INSERT INTO auth.age_sync_outbox (id, aggregate_type, aggregate_id, tipo_evento, payload, estado, fecha_creacion)
        SELECT gen_random_uuid(),
               'user_proximity',
               p_id_usuario,
               'NEARBY_USER_DETECTED',
               jsonb_build_object(
                   'source_user_id', p_id_usuario,
                   'target_user_id', c.id_vecino,
                   'distance_km', c.distancia_km,
                   'sensor_at', now()
               ),
               'pending',
               now()
          FROM cercanos c
          WHERE c.distancia_km <= v_radio_km
        RETURNING id, tipo_evento, estado
    )
    SELECT i.id, i.tipo_evento, i.estado
      FROM inserted i;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'No se encontraron usuarios cercanos dentro de % km', v_radio_km
              USING HINT = 'Puede aumentar el radio de búsqueda registrando más ubicaciones',
              ERRCODE = 'P0002';
    END IF;
END;
$$;


--
-- Name: auth_fn_sync_segunda_vecindad_graph(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.auth_fn_sync_segunda_vecindad_graph(p_id_usuario uuid) RETURNS TABLE(outbox_id uuid, tipo_evento text, estado text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_geom geometry;
    v_radio_1km double precision := 1.0;
    v_radio_2km double precision := 2.5;
BEGIN
    -- Obtener ubicación actual
    SELECT ub.geom INTO v_geom
      FROM auth.ubicaciones ub
     WHERE ub.id_usuario = p_id_usuario
       AND ub.is_active IS NOT FALSE
       AND ub.fecha_eliminacion IS NULL
       AND ub.geom IS NOT NULL
     ORDER BY ub.fecha_actualizacion DESC
     LIMIT 1;

    IF v_geom IS NULL THEN
        RAISE EXCEPTION 'No se encontró ubicación activa para el usuario %', p_id_usuario
              USING HINT = 'Registre una ubicación antes de sincronizar segunda vecindad',
              ERRCODE = 'P0002';
    END IF;

    -- Primera vecindad: contactos directos cercanos
    RETURN QUERY
    WITH primera_vecindad AS (
        SELECT ub2.id_usuario, ub2.geom
          FROM auth.ubicaciones ub2
         WHERE ub2.id_usuario <> p_id_usuario
           AND ub2.is_active IS NOT FALSE
           AND ub2.fecha_eliminacion IS NULL
           AND ub2.geom IS NOT NULL
           AND ST_DWithin(v_geom::geography, ub2.geom::geography, v_radio_1km * 1000)
    ),
    segunda_vecindad AS (
        SELECT ub3.id_usuario AS id_segundo_vecino,
               pv.id_usuario AS id_intermediario,
               ST_Distance(v_geom::geography, ub3.geom::geography) / 1000.0 AS distancia_km
          FROM auth.ubicaciones ub3
          JOIN primera_vecindad pv ON pv.id_usuario <> ub3.id_usuario
         WHERE ub3.id_usuario <> p_id_usuario
           AND ub3.is_active IS NOT FALSE
           AND ub3.fecha_eliminacion IS NULL
           AND ub3.geom IS NOT NULL
           AND ST_DWithin(v_geom::geography, ub3.geom::geography, v_radio_2km * 1000)
           AND NOT ST_DWithin(v_geom::geography, ub3.geom::geography, v_radio_1km * 1000)
    ),
    distinct_segunda AS (
        SELECT DISTINCT ON (sv.id_segundo_vecino)
               sv.id_segundo_vecino,
               sv.id_intermediario,
               sv.distancia_km
          FROM segunda_vecindad sv
         ORDER BY sv.id_segundo_vecino, sv.distancia_km ASC
    ),
    inserted AS (
        INSERT INTO auth.age_sync_outbox (id, aggregate_type, aggregate_id, tipo_evento, payload, estado, fecha_creacion)
        SELECT gen_random_uuid(),
               'user_proximity',
               p_id_usuario,
               'SECOND_DEGREE_NEIGHBOR_DETECTED',
               jsonb_build_object(
                   'source_user_id', p_id_usuario,
                   'target_user_id', ds.id_segundo_vecino,
                   'intermediary_user_id', ds.id_intermediario,
                   'distance_km', ds.distancia_km,
                   'sensor_at', now()
               ),
               'pending',
               now()
          FROM distinct_segunda ds
        RETURNING id, tipo_evento, estado
    )
    SELECT i.id, i.tipo_evento, i.estado
      FROM inserted i;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'No se encontraron usuarios en segunda vecindad para el usuario %', p_id_usuario
              USING HINT = 'Se requieren más ubicaciones de usuarios cercanos',
              ERRCODE = 'P0002';
    END IF;
END;
$$;


