--
-- Name: buyer_confirm_payment_v2(uuid, date, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.buyer_confirm_payment_v2(p_order_id uuid, p_order_month date, p_region_code text, p_payment_method text, p_payment_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_id_comprador uuid := app.current_request_user_id_safe();
  v_idem_key text := app.current_request_idempotency_key_safe();
  v_existing_response jsonb;
  v_response_payload jsonb;
BEGIN
  IF v_id_comprador IS NULL THEN
    RAISE EXCEPTION 'AUTH_UID_REQUERIDO' USING ERRCODE = 'P0002';
  END IF;

  SELECT response_payload INTO v_existing_response
  FROM app.idempotency_requests
  WHERE actor_user_id = v_id_comprador
    AND operation_name = 'confirm_payment'
    AND idempotency_key = v_idem_key;
  IF v_existing_response IS NOT NULL THEN RETURN v_existing_response; END IF;

  -- Transición real de la máquina de estados: pendiente -> confirmada
  UPDATE auth.ordenes
  SET estado = 'confirmada',
      fecha_confirmacion = now(),
      fecha_actualizacion = now()
  WHERE id = p_order_id
    AND order_month = p_order_month
    AND region_code = p_region_code
    AND id_comprador = v_id_comprador
    AND estado = 'pendiente';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDEN_NO_ELEGIBLE_PARA_PAGO_O_PARAMETROS_INVALIDOS' USING ERRCODE = 'P0008';
  END IF;

  v_response_payload := jsonb_build_object(
    'order_id', p_order_id,
    'status', 'confirmada',
    'payment_method', p_payment_method,
    'payment_ref', p_payment_ref,
    'timestamp', now()
  );

  INSERT INTO app.idempotency_requests (actor_user_id, operation_name, idempotency_key, response_payload)
  VALUES (v_id_comprador, 'confirm_payment', v_idem_key, v_response_payload);

  RETURN v_response_payload;
END;
$$;


--
-- Name: calcular_total(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.calcular_total(p_items jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_item    jsonb;
  v_prod    record;
  v_lineas  jsonb := '[]'::jsonb;
  v_subtotal numeric := 0;
  v_cant    int;
  v_idp     uuid;
BEGIN
  IF jsonb_array_length(COALESCE(p_items, '[]'::jsonb)) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'p_items vacio',
                              'total', 0, 'subtotal', 0);
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb))
  LOOP
    v_idp  := (v_item->>'id_producto')::uuid;
    v_cant := COALESCE((v_item->>'cantidad')::int, 0);
    IF v_cant <= 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'cantidad invalida',
                                'id_producto', v_idp::text);
    END IF;

    SELECT id, precio, stock_available, nombre
      INTO v_prod
      FROM auth.productos
     WHERE id = v_idp AND activo = true;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'error', 'producto inexistente o inactivo',
                                'id_producto', v_idp::text);
    END IF;
    -- stock_available es TEXT en el schema real: cast numerico explicito
    IF (v_prod.stock_available::numeric) < v_cant THEN
      RETURN jsonb_build_object('ok', false, 'error', 'stock insuficiente',
                                'id_producto', v_idp::text,
                                'stock_available', v_prod.stock_available,
                                'solicitado', v_cant);
    END IF;

    v_subtotal := v_subtotal + (v_prod.precio * v_cant);
    v_lineas := v_lineas || jsonb_build_object(
      'id_producto', v_idp, 'nombre', v_prod.nombre,
      'cantidad', v_cant, 'precio_unitario', v_prod.precio,
      'total_linea', v_prod.precio * v_cant);
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'items', v_lineas,
    'subtotal', round(v_subtotal, 2),
    'total', round(v_subtotal, 2));
END;
$$;


