--
-- Name: fn_seller_operable(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.fn_seller_operable(p_seller_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
    v_seller_user_id   uuid;
    v_seller_verified  boolean;
    v_current_user_id  uuid;
    v_is_admin         boolean;
BEGIN
    IF p_seller_id IS NULL THEN
        RETURN false;
    END IF;

    BEGIN
        SELECT s.id_usuario, s.is_verified
          INTO v_seller_user_id, v_seller_verified
          FROM seller.profiles s
         WHERE s.id = p_seller_id
         LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
        RETURN false;
    END;

    IF NOT FOUND THEN
        RETURN false;
    END IF;

    IF v_seller_verified IS DISTINCT FROM true THEN
        RETURN false;
    END IF;

    v_current_user_id := auth.current_jwt_user_id();
    v_is_admin        := auth.is_db_admin();

    IF v_is_admin THEN
        RETURN true;
    END IF;

    IF v_current_user_id IS NULL THEN
        RETURN false;
    END IF;

    RETURN v_seller_user_id = v_current_user_id;
END;
$$;


