--
-- Name: func_v4_maintenance_purge_idempotency(integer, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.func_v4_maintenance_purge_idempotency(p_retention_hours integer DEFAULT 48, p_batch_size integer DEFAULT 5000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public'
    AS $$
DECLARE
    v_deleted_rows     integer := 0;
    v_cutoff_timestamp timestamptz;
    v_rows_this_batch  integer;
BEGIN
    v_cutoff_timestamp := now() - (p_retention_hours || ' hours')::interval;

    RAISE NOTICE 'Purga idempotencia: cutoff=%', v_cutoff_timestamp;

    LOOP
        -- Tabla BASE (no la vista) + PK id (no ctid) + ON CONFLICT-free.
        DELETE FROM app.solicitudes_idempotencia
        WHERE id IN (
            SELECT id
            FROM   app.solicitudes_idempotencia
            WHERE  fecha_creacion < v_cutoff_timestamp
            ORDER  BY id
            LIMIT  p_batch_size
            FOR UPDATE SKIP LOCKED
        );

        GET DIAGNOSTICS v_rows_this_batch = ROW_COUNT;
        v_deleted_rows := v_deleted_rows + v_rows_this_batch;

        EXIT WHEN v_rows_this_batch < p_batch_size;

        PERFORM pg_sleep(0.05);
    END LOOP;

    RAISE NOTICE 'Purga completada: % filas', v_deleted_rows;
    RETURN v_deleted_rows;
END;
$$;


