-- Name: get_seller_coverage_circle_v4(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.get_seller_coverage_circle_v4(p_id_vendedor uuid) RETURNS TABLE(id_vendedor uuid, center_geom public.geometry, radius_meters numeric, profile_tier text)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    p_id_vendedor,
    sl.geom,
    (SELECT numeric_value FROM public.commercial_tier_rule_values
     WHERE actor_role = 'seller' AND rule_code = 'max_radius_meters'
       AND tier_code = public.get_active_actor_tier(p_id_vendedor, 'seller')),
    public.get_active_actor_tier(p_id_vendedor, 'seller')
  FROM app.resolve_seller_location_v4(p_id_vendedor) sl;
$$;


--
-- Name: get_seller_sales_context_v2(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.get_seller_sales_context_v2() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_id_vendedor uuid := app.current_request_user_id_safe();
  v_tier_code text;
  v_max_concurrent integer;
  v_sla_minutes integer;
  v_active_orders_count integer;
  v_remaining_capacity integer;
  v_seller_geom geometry(Point, 4326);
  v_resolved_source text;
BEGIN
  IF v_id_vendedor IS NULL THEN RAISE EXCEPTION 'AUTH_UID_REQUERIDO' USING ERRCODE = 'P0002'; END IF;
  SELECT source, geom INTO v_resolved_source, v_seller_geom FROM app.resolve_seller_location_v4(v_id_vendedor);
  v_tier_code := COALESCE(public.get_active_actor_tier(v_id_vendedor, 'seller'), 'bronze');
  SELECT numeric_value INTO v_max_concurrent FROM public.commercial_tier_rule_values
    WHERE actor_role = 'seller' AND tier_code = v_tier_code AND rule_code = 'max_concurrent_orders';
  SELECT numeric_value INTO v_sla_minutes FROM public.commercial_tier_rule_values
    WHERE actor_role = 'seller' AND tier_code = v_tier_code AND rule_code = 'response_sla_minutes';
  SELECT COUNT(*)::integer INTO v_active_orders_count FROM auth.ordenes
    WHERE id_vendedor = v_id_vendedor AND estado IN ('assigned','payment_confirmed','preparing','in_delivery');
  v_remaining_capacity := GREATEST(0, COALESCE(v_max_concurrent,0) - v_active_orders_count);
  RETURN jsonb_build_object(
    'id_vendedor', v_id_vendedor, 'tier', v_tier_code,
    'rules', jsonb_build_object('max_concurrent_orders', v_max_concurrent, 'response_sla_minutes', v_sla_minutes, 'remaining_capacity', v_remaining_capacity),
    'geo_context', jsonb_build_object('source', v_resolved_source, 'coordinates', ST_AsText(v_seller_geom)),
    'timestamp', now()
  );
END;
$$;


--
-- Name: handle_user_delete(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.handle_user_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_actor  uuid := app.jwt_user_id_safe();
    v_before jsonb;
    v_after  jsonb;
BEGIN
    -- Purge físico explícito: se respeta el bypass del pipeline de purga.
    IF current_setting('app.allow_physical_purge', true) IN ('true', 'on') THEN
        RETURN OLD;
    END IF;

    v_before := to_jsonb(OLD);

    UPDATE auth.users
       SET activo             = false,
           lifecycle_state    = CASE WHEN OLD.fecha_anonimizacion IS NULL
                                     THEN 'soft_deleted'
                                     ELSE OLD.lifecycle_state END,
           fecha_eliminacion  = COALESCE(OLD.fecha_eliminacion, now()),
           deleted_by         = COALESCE(OLD.deleted_by, v_actor),
           deleted_reason     = COALESCE(OLD.deleted_reason, 'DELETE_INTERCEPTED'),
           fecha_actualizacion = now()
     WHERE id = OLD.id;

    SELECT to_jsonb(u) INTO v_after FROM auth.users u WHERE u.id = OLD.id;

    RETURN NULL;  -- cancela el DELETE físico; la baja queda como soft-delete.
END;
$$;


