--
-- Name: proc_maintenance_reindex_brin(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.proc_maintenance_reindex_brin() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
BEGIN
  -- Re-indexar BRIN para consolidar rangos tras crecimiento de tablas
  REINDEX INDEX CONCURRENTLY idx_orders_brin_created_at;
  REINDEX INDEX CONCURRENTLY idx_orders_brin_closed_at;
  REINDEX INDEX CONCURRENTLY idx_audit_logged_changes_brin_changed_at;
  REINDEX INDEX CONCURRENTLY idx_reward_ledger_brin_created_at;
  
  -- Actualizar estadísticas post-reindex
  ANALYZE auth.ordenes;
  ANALYZE audit.logged_changes;
  ANALYZE public.order_reward_ledger;
  
  RAISE NOTICE 'Re-indexación BRIN completada exitosamente';
END;
$$;


--
-- Name: proc_v4_maintenance_create_partitions(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.proc_v4_maintenance_create_partitions() RETURNS text
    LANGUAGE sql STABLE
    AS $$ SELECT NULL::text; $$;


--
-- Name: proc_v4_maintenance_create_partitions(date); Type: PROCEDURE; Schema: app; Owner: -
--

CREATE PROCEDURE app.proc_v4_maintenance_create_partitions(IN p_target_date date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_start_month date := date_trunc('month', p_target_date)::date;

  v_end_month date := (v_start_month + interval '1 month')::date;

  v_month_suffix text := to_char(v_start_month, 'YYYY_MM');

  v_region_rec RECORD;

  v_parent text := 'orders_m' || to_char(v_start_month, 'YYYY_MM');

  v_child text;

BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_class WHERE relname = v_parent) THEN
    EXECUTE format(
      'CREATE TABLE public.%I PARTITION OF auth.ordenes FOR VALUES FROM (%L) TO (%L);
',
      v_parent, v_start_month, v_end_month);

  END IF;

  FOR v_region_rec IN SELECT region_code FROM public.operating_regions WHERE is_active = true LOOP
    v_child := v_parent || '_' || replace(v_region_rec.region_code, '-', '_');

    IF NOT EXISTS (SELECT 1 FROM pg_class WHERE relname = v_child) THEN
      EXECUTE format('CREATE TABLE public.%I PARTITION OF public.%I FOR VALUES IN (%L);
',
        v_child, v_parent, v_region_rec.region_code);

      EXECUTE format('
',
        'idx_geo_' || v_child, v_child);

    END IF;

  END LOOP;

END;

$$;


--
-- Name: public_fn_comprador_en_zona_delivery(uuid, double precision, double precision); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.public_fn_comprador_en_zona_delivery(p_id_comprador uuid DEFAULT NULL::uuid, p_lat double precision DEFAULT NULL::double precision, p_lon double precision DEFAULT NULL::double precision) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_lat double precision := p_lat;
    v_lon double precision := p_lon;
    v_pto geometry;
BEGIN
    -- Si no se dan coordenadas, se derivan de la ubicación activa del comprador.
    IF (v_lat IS NULL OR v_lon IS NULL) AND p_id_comprador IS NOT NULL THEN
        SELECT ST_Y(ub.punto::geometry), ST_X(ub.punto::geometry)
          INTO v_lat, v_lon
          FROM auth.ubicaciones ub
         WHERE ub.id_usuario = p_id_comprador
           AND ub.is_active IS NOT FALSE
           AND ub.fecha_eliminacion IS NULL
         ORDER BY ub.fecha_actualizacion DESC NULLS LAST
         LIMIT 1;
    END IF;

    IF v_lat IS NULL OR v_lon IS NULL THEN
        RETURN false;
    END IF;

    v_pto := ST_SetSRID(ST_MakePoint(v_lon, v_lat), 4326);

    RETURN EXISTS (
        SELECT 1
          FROM public.geo_zones z
         WHERE z.is_active IS NOT FALSE
           AND z.fecha_eliminacion IS NULL
           AND z.geom IS NOT NULL
           AND ST_Contains(z.geom, v_pto)
    );
END;
$$;


--
-- Name: public_get_nearby_merchants_social(double precision, double precision, integer, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.public_get_nearby_merchants_social(p_lat double precision, p_lng double precision, p_radius_m integer DEFAULT 2000, p_id_comprador uuid DEFAULT NULL::uuid) RETURNS TABLE(id_vendedor uuid, nombre_tienda text, distancia_m double precision, es_favorito boolean, tipo_relacion text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'pg_temp'
