$$;


--
-- Name: public_get_nearby_merchants_social(double precision, double precision, double precision, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.public_get_nearby_merchants_social(p_lat double precision, p_lon double precision, p_radio_km double precision DEFAULT 5.0, p_id_comprador uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS TABLE(id_vendedor uuid, nombre text, distancia_km double precision, es_favorito boolean, tiene_relacion boolean, reputacion numeric, total_ordenes_completadas bigint, ultima_orden timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_pto geography := ST_SetSRID(ST_MakePoint(p_lon, p_lat), 4326)::geography;
    v_radio_m double precision := p_radio_km * 1000;
BEGIN
    IF p_lat IS NULL OR p_lon IS NULL THEN
        RAISE EXCEPTION 'Se requieren coordenadas (lat, lon) para la búsqueda'
              USING ERRCODE = 'P0002';
    END IF;

    RETURN QUERY
    WITH vendedores_cercanos AS (
        SELECT u.id AS id_vendedor,
               COALESCE(ppv.nombre_marca, u.nombre_visible) AS nombre,
               ROUND((ST_Distance(v_pto, ub.geom::geography) / 1000.0)::numeric, 3)::double precision AS distancia_km,
               (fav.id IS NOT NULL) AS es_favorito,
               rel.relationship_type IS NOT NULL AS tiene_relacion
          FROM auth.users u
          JOIN auth.ubicaciones ub ON ub.id_usuario = u.id
           AND ub.is_active IS NOT FALSE
           AND ub.fecha_eliminacion IS NULL
          LEFT JOIN auth.perfiles_publicos_vendedor ppv ON ppv.id_vendedor = u.id
          LEFT JOIN public.buyer_favorite_sellers fav
            ON fav.id_vendedor = u.id AND fav.id_comprador = p_id_comprador
           AND fav.fecha_eliminacion IS NULL
          LEFT JOIN public.user_relationships rel
            ON rel.to_user_id = u.id AND rel.from_user_id = p_id_comprador
           AND rel.relationship_type IN ('follows', 'trusted')
           AND rel.estado = 'active'
           AND rel.fecha_eliminacion IS NULL
         WHERE u.role = 'seller'
           AND (u.activo IS DISTINCT FROM false)
           AND u.fecha_eliminacion IS NULL
           AND ST_DWithin(v_pto, ub.geom::geography, v_radio_m)
    ),
    order_stats AS (
        SELECT o.id_vendedor,
               count(*)::bigint AS total_ordenes,
               max(o.fecha_creacion) AS ultima_orden
          FROM auth.ordenes o
         WHERE o.estado = 'completed'
         GROUP BY o.id_vendedor
    )
    SELECT vc.id_vendedor,
           vc.nombre,
           vc.distancia_km,
           vc.es_favorito,
           vc.tiene_relacion,
           COALESCE(os.total_ordenes, 0)::numeric / GREATEST(1::numeric, vc.distancia_km::numeric) AS reputacion,
           COALESCE(os.total_ordenes, 0::bigint),
           os.ultima_orden
      FROM vendedores_cercanos vc
      LEFT JOIN order_stats os ON os.id_vendedor = vc.id_vendedor
     ORDER BY vc.es_favorito DESC,
              vc.tiene_relacion DESC,
              reputacion DESC NULLS LAST,
              vc.distancia_km ASC
     LIMIT p_limit;
END;
$$;


--
-- Name: public_get_request_role(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.public_get_request_role() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'pg_catalog'
    AS $$
    SELECT CASE
        WHEN auth.jwt_claims() ->> 'role' IN ('buyer', 'seller', 'db_admin')
        THEN auth.jwt_claims() ->> 'role'
        ELSE 'anon'
    END;
$$;


--
-- Name: public_sync_purchase_to_graph(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.public_sync_purchase_to_graph(p_id_orden uuid) RETURNS TABLE(outbox_id uuid, operacion text, estado text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_orden record;
    v_outbox_id uuid := gen_random_uuid();
BEGIN
    -- Obtener datos de la orden
    SELECT o.id, o.id_comprador, o.id_vendedor, o.total, o.estado,
           o.region_code, o.fecha_creacion, o.location_delivery
      INTO v_orden
      FROM auth.ordenes o
     WHERE o.id = p_id_orden;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden % no encontrada', p_id_orden
              USING ERRCODE = 'P0002';
    END IF;

    IF v_orden.estado <> 'completed' THEN
        RAISE EXCEPTION 'La orden % no está completada (estado actual: %)', p_id_orden, v_orden.estado
              USING ERRCODE = 'P0002';
    END IF;

    -- Insertar en el outbox del grafo de afinidad
    INSERT INTO auth.afinidad_graph_outbox (id, id_vendedor, operacion, payload, procesado, fecha_creacion)
    VALUES (
        v_outbox_id,
        v_orden.id_vendedor,
        'purchase_sync',
        jsonb_build_object(
            'id_orden', v_orden.id,
            'id_comprador', v_orden.id_comprador,
            'id_vendedor', v_orden.id_vendedor,
            'total', v_orden.total,
            'region_code', v_orden.region_code,
            'fecha_creacion', v_orden.fecha_creacion,
            'location_delivery', CASE WHEN v_orden.location_delivery IS NOT NULL
                THEN ST_AsGeoJSON(v_orden.location_delivery)::jsonb
                ELSE NULL END,
            'sync_action', 'insert_edge',
            'edge_type', 'PURCHASED_FROM'
        ),
        false,
        now()
    );

    -- También insertar en el outbox de AGE general
    INSERT INTO auth.age_sync_outbox (id, aggregate_type, aggregate_id, tipo_evento, payload, estado, fecha_creacion)
    VALUES (
        gen_random_uuid(),
        'order',
        p_id_orden,
        'ORDER_COMPLETED_GEO',
        jsonb_build_object(
            'id_orden', v_orden.id,
            'id_comprador', v_orden.id_comprador,
            'id_vendedor', v_orden.id_vendedor,
            'total', v_orden.total,
            'region_code', v_orden.region_code
        ),
        'pending',
        now()
    );

    RETURN QUERY
    SELECT v_outbox_id, 'purchase_sync', 'pending';
END;
$$;


--
-- Name: public_tg_comprador_crud_audit_age(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.public_tg_comprador_crud_audit_age() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'auth', 'public', 'ag_catalog', 'pg_catalog'
    AS $_$
DECLARE
    v_actor  uuid := app.jwt_user_id_safe();
    v_uid    text;
    v_role   text;
    v_email  text;
    v_user   text;
    v_query  text;
BEGIN
    -- Se auditan solo filas de compradores (rol 'buyer').
    IF TG_OP = 'DELETE' THEN
        IF OLD.role IS DISTINCT FROM 'buyer' THEN
            RETURN OLD;
        END IF;
        v_uid := OLD.id::text; v_role := OLD.role; v_email := OLD.email; v_user := OLD.username;
    ELSE
        IF NEW.role IS DISTINCT FROM 'buyer' THEN
            RETURN NEW;
        END IF;
        v_uid := NEW.id::text; v_role := NEW.role; v_email := NEW.email; v_user := NEW.username;
    END IF;

    -- 1) Auditoría SQL canónica (fuente de verdad).
    INSERT INTO audit.logged_changes(table_schema, table_name, operation, record_pk,
        actor_user_id, actor_role, old_data, new_data)
    VALUES (TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP,
        jsonb_build_object('id', v_uid),
        v_actor, app.current_request_role_safe(),
        CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) ELSE NULL END,
        CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) ELSE NULL END);

    -- 2) Sync AGE best-effort (smtp_posix_graph, vértice User con propiedad user_uuid).
    --    Este deployment de AGE no soporta MERGE ni MATCH filtrado; se usa CREATE vía
    --    SQL dinámico (event-append) con degradación elegante.
    BEGIN
        IF EXISTS (SELECT 1 FROM pg_catalog.pg_extension WHERE extname = 'age') THEN
            LOAD 'age';
            v_query := format(
                'SELECT * FROM ag_catalog.cypher(''smtp_posix_graph'', $c$ CREATE (u:User {user_uuid: %L, role: %L, email: %L, username: %L, audit_op: %L, audit_ts: %L, audit_actor: %L}) RETURN u $c$) AS (v ag_catalog.agtype)',
                v_uid, COALESCE(v_role,''), COALESCE(v_email,''), COALESCE(v_user,''),
                TG_OP, to_char(now(),'YYYY-MM-DD"T"HH24:MI:SS"Z"'), COALESCE(v_actor::text,''));
            EXECUTE v_query;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        -- Degradación elegante: la auditoría SQL ya quedó registrada.
        RAISE WARNING '[COMPRADOR_AGE_AUDIT_FAILED] %: %', v_uid, SQLERRM;
    END;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$_$;


