--
-- Name: reactivate_user(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reactivate_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'auth', 'public', 'pg_catalog'
    AS $$
BEGIN
    -- Solo actúa en transición hacia activo.
    IF NEW.activo IS TRUE AND (OLD.activo IS DISTINCT FROM TRUE OR OLD.lifecycle_state = 'soft_deleted') THEN
        -- Validar estado previo: no se puede reactivar tras anonimización.
        IF OLD.fecha_anonimizacion IS NOT NULL THEN
            RAISE EXCEPTION 'No se permite reactivar un usuario anonimizado'
                USING ERRCODE = 'P0001';
        END IF;

        NEW.lifecycle_state    := 'active';
        NEW.fecha_eliminacion  := NULL;
        NEW.deleted_by         := NULL;
        NEW.deleted_reason     := NULL;
        NEW.elegible_purga_en  := NULL;
        NEW.fecha_actualizacion := now();
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: resolve_buyer_location_v4(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_buyer_location_v4(p_id_comprador uuid) RETURNS TABLE(source text, geom public.geometry)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
  SELECT source_type::text, location::geometry(Point, 4326)
  FROM public.user_location_snapshots
  WHERE id_usuario = p_id_comprador AND is_active = true
    AND (source_type <> 'device_event' OR fecha_captura >= (now() - INTERVAL '24 hours'))
  ORDER BY
    CASE source_type
      WHEN 'profile' THEN 1
      WHEN 'address_book' THEN 2
      WHEN 'device_event' THEN 3
      WHEN 'order_flow' THEN 4
      WHEN 'admin_backfill' THEN 5
      ELSE 99 END ASC,
    fecha_captura DESC
  LIMIT 1;
$$;


--
-- Name: resolve_seller_location_v4(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_seller_location_v4(p_id_vendedor uuid) RETURNS TABLE(source text, geom public.geometry)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH ranked_locations AS (
    SELECT 'profile' AS source_type, location AS geom, fecha_creacion AS captured_at, 2 AS priority_weight
    FROM public.perfiles
    WHERE id_usuario = p_id_vendedor AND is_active = true AND location IS NOT NULL
    UNION ALL
    SELECT 'device_event', location, fecha_captura, 3
    FROM public.device_events
    WHERE id_usuario = p_id_vendedor AND fecha_captura >= (now() - INTERVAL '2 hours')
    UNION ALL
    SELECT 'order_flow', seller_location, fecha_creacion, 4
    FROM public.order_geo_snapshots
    WHERE region_code IN (
      SELECT region_code FROM auth.ordenes WHERE id_vendedor = p_id_vendedor AND estado = 'completed'
    )
  )
  SELECT r.source_type::text, r.geom::geometry(Point, 4326)
  FROM ranked_locations r
  ORDER BY r.priority_weight ASC, r.captured_at DESC
  LIMIT 1;
END;
$$;


--
-- Name: rpc_admin_assert_access(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_assert_access(p_required_scope text DEFAULT 'admin'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor_id uuid;
  v_role     text;
BEGIN
  -- R-30: validación de entrada
  IF p_required_scope NOT IN ('admin','superadmin','auditor') THEN
    RAISE EXCEPTION 'scope inválido: %', p_required_scope USING ERRCODE = '22P02';
  END IF;

  v_actor_id := public.get_app_actor_id();
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
  END IF;

  v_role := COALESCE(app.jwt_role_safe(),'');

  IF p_required_scope = 'admin' AND v_role NOT IN ('administrador_role','superadmin_role') THEN
    RAISE EXCEPTION 'Rol insuficiente: se requiere admin (actual=%)', v_role USING ERRCODE = '42501';
  ELSIF p_required_scope = 'superadmin' AND v_role NOT IN ('superadmin_role','SuperAdmin') THEN
    RAISE EXCEPTION 'Rol insuficiente: se requiere superadmin' USING ERRCODE = '42501';
  ELSIF p_required_scope = 'auditor' AND v_role NOT IN ('administrador_role','superadmin_role','auditor_role') THEN
    RAISE EXCEPTION 'Rol insuficiente: se requiere auditor' USING ERRCODE = '42501';
  END IF;

  -- Verificar que el usuario esté activo
  IF NOT EXISTS (
    SELECT 1 FROM auth.users
    WHERE id = v_actor_id
      AND COALESCE(is_active, true) = true
      AND fecha_eliminacion IS NULL
  ) THEN
    RAISE EXCEPTION 'Actor inactivo o suspendido' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'status','ok',
    'actor_id', v_actor_id,
    'role', v_role,
    'scope', p_required_scope,
    'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
END;
$$;


--
-- Name: rpc_admin_assign_work_item(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_assign_work_item(p_work_item_id uuid, p_assignee_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_admin_id     uuid;
  v_target_id    uuid;
  v_item_type    text;
  v_ref_id       uuid;
  v_already_assigned uuid;
BEGIN
  v_admin_id := app.jwt_user_id_safe();
  IF v_admin_id IS NULL OR app.jwt_role_safe() <> 'db_admin' THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;

  v_target_id := COALESCE(p_assignee_id, v_admin_id);

  SELECT tipo_item, ref_id, id_admin_asignado
  INTO v_item_type, v_ref_id, v_already_assigned
  FROM app.work_items
  WHERE work_item_id = p_work_item_id AND estado IN ('open','in_progress')
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ítem no encontrado o ya cerrado' USING ERRCODE = 'P0001';
  END IF;

  UPDATE app.work_items
  SET id_admin_asignado = v_target_id,
      assigned_at = now(),
      estado = 'in_progress',
      fecha_actualizacion = now()
  WHERE work_item_id = p_work_item_id;

  -- Registrar en audit log (WORM, R-56)
  INSERT INTO app.admin_audit_log
    (id_admin, tipo_accion, target_resource, id_recurso_objetivo, action_details)
  VALUES
    (v_admin_id, 'assign_work_item', 'work_item', p_work_item_id,
     jsonb_build_object('assignee', v_target_id, 'prev_assignee', v_already_assigned,
                        'item_type', v_item_type, 'ref_id', v_ref_id));

  RETURN jsonb_build_object(
    'work_item_id',  p_work_item_id,
    'assigned_to',   v_target_id,
    'status',        'in_progress',
    'timestamp_utc', now()
  );
END;
$$;


--
-- Name: rpc_admin_baja_categoria(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_baja_categoria(p_categoria_id uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := app.jwt_user_id_safe();
BEGIN
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
    END IF;
    IF NOT auth.fn_is_admin() THEN
        RAISE EXCEPTION 'Rol insuficiente (requiere admin)' USING ERRCODE = '42501';
    END IF;
    IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
        RAISE EXCEPTION 'motivo obligatorio' USING ERRCODE = '23502';
    END IF;

    UPDATE auth.categorias
       SET activo = false,
           deleted_by = v_actor,
           deletion_reason = p_motivo
     WHERE id = p_categoria_id AND activo = true
    RETURNING id INTO p_categoria_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Categoría inexistente o ya inactiva' USING ERRCODE = '02000';
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'categoria_id', p_categoria_id,
        'tipo_cambio', 'BAJA_LOGICA',
        'timestamp_utc', to_char(now(),'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    );
END; $$;


--
-- Name: rpc_admin_generate_report(text, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_generate_report(p_report_type text, p_params jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_admin_id uuid;
  v_report   jsonb;
  v_since    timestamptz := COALESCE((p_params->>'since')::timestamptz, now() - interval '30 days');
  v_until    timestamptz := COALESCE((p_params->>'until')::timestamptz, now());
BEGIN
  v_admin_id := app.jwt_user_id_safe();
  IF v_admin_id IS NULL OR app.jwt_role_safe() <> 'db_admin' THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;

  IF p_report_type NOT IN ('disputes_summary','fraud_summary','moderation_summary','activity_audit','config_changelog') THEN
    RAISE EXCEPTION 'report_type inválido: %', p_report_type USING ERRCODE = '22023';
  END IF;

  CASE p_report_type
    WHEN 'disputes_summary' THEN
      SELECT jsonb_build_object(
        'period', jsonb_build_object('since', v_since, 'until', v_until),
        'total',          count(*),
        'by_status',      jsonb_object_agg(estado, cnt),
        'by_severity',    jsonb_object_agg(severity, scnt),
        'avg_resolution_hours',
          round(avg(EXTRACT(EPOCH FROM (resuelto_en - fecha_creacion))/3600)::numeric, 1)
      ) INTO v_report
      FROM (
        SELECT estado, severity,
          count(*) OVER (PARTITION BY estado)   AS cnt,
          count(*) OVER (PARTITION BY severity) AS scnt,
          resuelto_en, fecha_creacion
        FROM app.disputes
        WHERE fecha_creacion BETWEEN v_since AND v_until
          AND fecha_eliminacion IS NULL
      ) sub;

    WHEN 'fraud_summary' THEN
      SELECT jsonb_build_object(
        'period', jsonb_build_object('since', v_since, 'until', v_until),
        'total_scores_computed',  count(*),
        'high_risk_count',        count(*) FILTER (WHERE score_value >= 0.7),
        'suspended_count',        count(*) FILTER (WHERE estado_flag = 'suspended'),
        'avg_score',              round(avg(score_value)::numeric, 3),
        'top_triggered_rules',    (
          SELECT jsonb_agg(r) FROM (
            SELECT unnest(triggered_rules) AS rule, count(*) AS freq
            FROM app.fraud_scores
            WHERE computed_at BETWEEN v_since AND v_until
            GROUP BY rule ORDER BY freq DESC LIMIT 5
          ) r)
      ) INTO v_report
      FROM app.fraud_scores
      WHERE computed_at BETWEEN v_since AND v_until;

    WHEN 'moderation_summary' THEN
      SELECT jsonb_build_object(
        'period', jsonb_build_object('since', v_since, 'until', v_until),
        'total',        count(*),
        'approved',     count(*) FILTER (WHERE estado = 'approved'),
        'removed',      count(*) FILTER (WHERE estado = 'removed'),
        'pending',      count(*) FILTER (WHERE estado = 'pending'),
        'by_type',      jsonb_object_agg(content_type, type_cnt)
      ) INTO v_report
      FROM (
        SELECT estado, content_type,
               count(*) OVER (PARTITION BY content_type) AS type_cnt
        FROM app.content_moderation
        WHERE fecha_creacion BETWEEN v_since AND v_until
      ) sub;

    WHEN 'activity_audit' THEN
      SELECT jsonb_build_object(
        'period', jsonb_build_object('since', v_since, 'until', v_until),
        'total_actions',  count(*),
        'by_action_type', jsonb_object_agg(tipo_accion, acnt),
        'by_admin',       jsonb_object_agg(id_admin::text, adcnt)
      ) INTO v_report
      FROM (
        SELECT tipo_accion, id_admin,
               count(*) OVER (PARTITION BY tipo_accion) AS acnt,
               count(*) OVER (PARTITION BY id_admin)    AS adcnt
        FROM app.admin_audit_log
        WHERE ejecutado_en BETWEEN v_since AND v_until
      ) sub;

    WHEN 'config_changelog' THEN
      SELECT jsonb_build_object(
        'period',  jsonb_build_object('since', v_since, 'until', v_until),
        'changes', jsonb_agg(jsonb_build_object(
          'config_key', ch.config_key, 'old_value', ch.old_value,
          'new_value', ch.new_value, 'changed_by', ch.changed_by,
          'reason', ch.change_reason, 'changed_at', ch.fecha_cambio)
          ORDER BY ch.fecha_cambio DESC)
      ) INTO v_report
      FROM app.config_history ch
      WHERE ch.fecha_cambio BETWEEN v_since AND v_until;
  END CASE;

  RETURN jsonb_build_object(
    'report_type',   p_report_type,
    'params',        p_params,
    'report',        COALESCE(v_report, '{"empty": true}'::jsonb),
    'generated_by',  v_admin_id,
    'timestamp_utc', now()
  );
END; $$;


--
-- Name: rpc_admin_get_config(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_get_config(p_config_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_admin_id uuid;
BEGIN
  v_admin_id := app.jwt_user_id_safe();
  IF v_admin_id IS NULL OR app.jwt_role_safe() <> 'db_admin' THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;

  IF p_config_key IS NOT NULL THEN
    RETURN (SELECT jsonb_build_object(
      'config_key', sc.config_key,
      'config_value', sc.config_value,
      'category', sc.category,
      'description', sc.description,
      'updated_at', sc.fecha_actualizacion)
    FROM app.v_system_config_projection sc WHERE sc.config_key = p_config_key);
  ELSE
    RETURN (SELECT jsonb_agg(row_to_json(sc)::jsonb)
            FROM app.v_system_config_projection sc);
  END IF;
END; $$;


--
-- Name: rpc_admin_get_dashboard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_get_dashboard() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_admin_id  uuid;
  v_panel     record;
  v_heatmap   jsonb;
BEGIN
  -- R-30: Autenticación
  v_admin_id := app.jwt_user_id_safe();
  IF v_admin_id IS NULL OR app.jwt_role_safe() <> 'db_admin' THEN
    RAISE EXCEPTION 'Acceso denegado: requiere rol db_admin' USING ERRCODE = '42501';
  END IF;

  -- Leer MV (fallback a tabla base si MV vacía)
  SELECT * INTO v_panel FROM app.mv_admin_control_panel LIMIT 1;

  IF NOT FOUND THEN
    -- Fallback: calcular en caliente
    SELECT
      count(*) FILTER (WHERE estado NOT IN ('resolved','closed')) AS disputes_open,
      0 AS disputes_unassigned, 0 AS disputes_critical, 0 AS disputes_created_24h,
      0 AS fraud_warning_count, 0 AS fraud_suspended_count, 0 AS fraud_high_risk_active,
      0 AS moderation_pending, 0 AS moderation_removed_24h, 0 AS admin_actions_24h,
      now() AS refrescado_en
    INTO v_panel
    FROM app.disputes;
  END IF;

  -- Heatmap de riesgo (proyección geoespacial)
  SELECT jsonb_agg(h) INTO v_heatmap
  FROM app.v_risk_heatmap_projection h;

  -- R-30: Contrato de salida
  RETURN jsonb_build_object(
    'disputes',    jsonb_build_object(
                     'open',          v_panel.disputes_open,
                     'unassigned',    v_panel.disputes_unassigned,
                     'critical',      v_panel.disputes_critical,
                     'created_24h',   v_panel.disputes_created_24h),
    'fraud',       jsonb_build_object(
                     'warning',       v_panel.fraud_warning_count,
                     'suspended',     v_panel.fraud_suspended_count,
                     'high_risk',     v_panel.fraud_high_risk_active),
    'moderation',  jsonb_build_object(
                     'pending',       v_panel.moderation_pending,
                     'removed_24h',   v_panel.moderation_removed_24h),
    'activity',    jsonb_build_object(
                     'admin_actions_24h', v_panel.admin_actions_24h),
    'risk_heatmap', COALESCE(v_heatmap, '[]'::jsonb),
    'refreshed_at', v_panel.refrescado_en,
    'timestamp_utc', now()
  );
END;
$$;


--
-- Name: rpc_admin_get_entity_detail(text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_get_entity_detail(p_entity_type text, p_entity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_admin_id    uuid;
  v_base        jsonb := 'null'::jsonb;
  v_fraud       jsonb := 'null'::jsonb;
  v_disputes    jsonb := '[]'::jsonb;
  v_moderation  jsonb := '[]'::jsonb;
  v_admin_acts  jsonb := '[]'::jsonb;
BEGIN
  -- R-30: Autenticación y autorización
  v_admin_id := app.jwt_user_id_safe();
  IF v_admin_id IS NULL OR app.jwt_role_safe() <> 'db_admin' THEN
    RAISE EXCEPTION 'Acceso denegado: requiere rol db_admin' USING ERRCODE = '42501';
  END IF;

  -- R-30: Validar tipo de entidad
  IF p_entity_type NOT IN ('user', 'order', 'dispute', 'product') THEN
    RAISE EXCEPTION 'entity_type inválido: %. Permitidos: user, order, dispute, product',
      p_entity_type USING ERRCODE = '22023';
  END IF;

  -- Leer entidad base con proyección (R-94)
  CASE p_entity_type
    WHEN 'user' THEN
      SELECT jsonb_build_object(
        'id_usuario',    u.id,
        'email',      left(u.email, 2) || '***' || right(u.email, 4),  -- ofuscar
        'role',       u.role,
        'created_at', u.fecha_creacion,
        'deleted_at', u.fecha_eliminacion
      ) INTO v_base
      FROM auth.users u WHERE u.id = p_entity_id AND u.fecha_eliminacion IS NULL;

    WHEN 'order' THEN
      SELECT jsonb_build_object(
        'order_id',      o.id_orden,
        'id_comprador',      o.id_comprador,
        'status',        o.estado,
        'total_amount',  o.total,
        'created_at',    o.fecha_creacion
      ) INTO v_base
      FROM auth.ordenes o WHERE o.id_orden = p_entity_id;

    WHEN 'dispute' THEN
      SELECT jsonb_build_object(
        'dispute_id',     d.id_disputa,
        'order_id',       d.id_orden,
        'reason',         d.dispute_reason,
        'status',         d.estado,
        'severity',       d.severity,
        'created_at',     d.fecha_creacion,
        'resolved_at',    d.resuelto_en
      ) INTO v_base
      FROM app.disputes d WHERE d.id_disputa = p_entity_id AND d.fecha_eliminacion IS NULL;

    WHEN 'product' THEN
      SELECT jsonb_build_object(
        'product_id',  p.id_producto,
        'id_vendedor',   p.id_vendedor,
        'name',        p.name,
        'category',    p.category,
        'price',       p.price,
        'stock_available', p.stock_available,
        'created_at',  p.fecha_creacion
      ) INTO v_base
      FROM auth.productos p WHERE p.id_producto = p_entity_id AND p.fecha_eliminacion IS NULL;
  END CASE;

  IF v_base IS NULL THEN
    RETURN jsonb_build_object('found', false, 'entity_type', p_entity_type, 'entity_id', p_entity_id);
  END IF;

  -- Contexto: fraud score (para user)
  IF p_entity_type = 'user' THEN
    SELECT jsonb_build_object(
      'score_value',  f.score_value,
      'flag_status',  f.estado_flag,
      'triggered',    f.triggered_rules,
      'expires_at',   f.fecha_expiracion
    ) INTO v_fraud
    FROM app.fraud_scores f
    WHERE f.id_usuario = p_entity_id AND f.fecha_expiracion > now()
    ORDER BY f.computed_at DESC LIMIT 1;
  END IF;

  -- Contexto: disputas relacionadas
  SELECT jsonb_agg(jsonb_build_object(
    'dispute_id', d.id_disputa, 'reason', d.dispute_reason,
    'status', d.estado, 'severity', d.severity
  )) INTO v_disputes
  FROM app.disputes d
  WHERE (d.id_iniciador = p_entity_id OR d.id_orden = p_entity_id)
    AND d.fecha_eliminacion IS NULL
  LIMIT 10;

  -- Contexto: moderaciones (para user)
  IF p_entity_type = 'user' THEN
    SELECT jsonb_agg(jsonb_build_object(
      'content_type', cm.content_type,
      'status', cm.estado,
      'flagged_reason', cm.flagged_reason,
      'reviewed_at', cm.revisado_en
    )) INTO v_moderation
    FROM app.content_moderation cm
    WHERE cm.id_autor = p_entity_id
    ORDER BY cm.fecha_creacion DESC LIMIT 5;
  END IF;

  -- Contexto: acciones admin previas
  SELECT jsonb_agg(jsonb_build_object(
    'action_type', al.tipo_accion,
    'admin_id', al.id_admin,
    'performed_at', al.ejecutado_en,
    'details', al.action_details
  ) ORDER BY al.ejecutado_en DESC) INTO v_admin_acts
  FROM app.admin_audit_log al
  WHERE al.id_recurso_objetivo = p_entity_id
  LIMIT 10;

  -- R-30: Contrato de salida
  RETURN jsonb_build_object(
    'found',        true,
    'entity_type',  p_entity_type,
    'entity_id',    p_entity_id,
    'base',         v_base,
    'fraud_context', COALESCE(v_fraud, 'null'::jsonb),
    'disputes',      COALESCE(v_disputes, '[]'::jsonb),
    'moderation',    COALESCE(v_moderation, '[]'::jsonb),
    'admin_actions', COALESCE(v_admin_acts, '[]'::jsonb),
    'timestamp_utc', now()
  );
END;
$$;


--
-- Name: rpc_admin_get_forensic_timeline(text, uuid, integer, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_get_forensic_timeline(p_entity_type text, p_entity_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_admin_id uuid;
  v_events   jsonb;
  v_total    int;
BEGIN
  v_admin_id := app.jwt_user_id_safe();
  IF v_admin_id IS NULL OR app.jwt_role_safe() <> 'db_admin' THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;

  SELECT count(*) INTO v_total
  FROM app.v_forensic_timeline_projection
  WHERE id_entidad = p_entity_id OR related_entity_id = p_entity_id;

  SELECT jsonb_agg(row_to_json(t)::jsonb ORDER BY t.event_time DESC)
  INTO v_events
  FROM (
    SELECT * FROM app.v_forensic_timeline_projection
    WHERE id_entidad = p_entity_id OR related_entity_id = p_entity_id
    ORDER BY event_time DESC
    LIMIT p_limit OFFSET p_offset
  ) t;

  RETURN jsonb_build_object(
    'entity_type',  p_entity_type,
    'entity_id',    p_entity_id,
    'events',       COALESCE(v_events, '[]'::jsonb),
    'total',        v_total,
    'limit',        p_limit,
    'offset',       p_offset,
    'timestamp_utc', now()
  );
END;
$$;


--
-- Name: rpc_admin_get_technical_anomalies(text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_get_technical_anomalies(p_kind text DEFAULT 'ip_shared'::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_threshold int;
  v_window    int := 60;
  v_items     jsonb := '[]'::jsonb;
  v_config    jsonb;
BEGIN
  PERFORM app.rpc_admin_assert_access('auditor');

  -- R-30
  IF p_kind NOT IN ('ip_shared','device_shared','hardware_shared','high_login_concentration') THEN
    RAISE EXCEPTION 'p_kind inválido' USING ERRCODE='22P02';
  END IF;
  IF p_limit IS NULL OR p_limit <= 0 OR p_limit > 500 THEN
    RAISE EXCEPTION 'p_limit debe estar en (0,500]' USING ERRCODE='22003';
  END IF;

  -- Cargar umbral desde detection_configurations
  SELECT config_value INTO v_config
  FROM public.detection_configurations
  WHERE config_key = CASE p_kind
                       WHEN 'ip_shared'                THEN 'technical_anomaly_ip_min_users'
                       WHEN 'device_shared'            THEN 'technical_anomaly_device_min_users'
                       WHEN 'hardware_shared'          THEN 'technical_anomaly_hardware_min_users'
                       WHEN 'high_login_concentration' THEN 'technical_anomaly_login_burst'
                     END
    AND is_active = true
    AND fecha_eliminacion IS NULL;

  v_threshold := COALESCE((v_config->>'threshold')::int, 2);
  v_window    := COALESCE((v_config->>'window_minutes')::int, 60);

  -- Degradación elegante: si la tabla existe pero está vacía
  IF NOT EXISTS (SELECT 1 FROM auth.user_telemetry_sessions LIMIT 1) THEN
    RETURN jsonb_build_object(
      'status','dependency_missing',
      'reason','auth.user_telemetry_sessions vacía; no hay datos de telemetría todavía',
      'kind', p_kind,
      'items','[]'::jsonb,
      'meta', jsonb_build_object('threshold', v_threshold),
      'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
    );
  END IF;

  IF p_kind = 'ip_shared' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.user_count DESC), '[]'::jsonb)
    INTO v_items
    FROM (
      SELECT host(ip_address) AS ip, user_count, first_seen, last_seen, user_ids
      FROM app.v_technical_anomalies_ip
      WHERE user_count >= v_threshold
      ORDER BY user_count DESC
      LIMIT p_limit
    ) t;
  ELSIF p_kind = 'device_shared' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.user_count DESC),'[]'::jsonb)
    INTO v_items
    FROM (
      SELECT id_dispositivo, user_count, first_seen, last_seen, user_ids
      FROM app.v_technical_anomalies_device
      WHERE user_count >= v_threshold
      ORDER BY user_count DESC
      LIMIT p_limit
    ) t;
  ELSIF p_kind = 'hardware_shared' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.user_count DESC),'[]'::jsonb)
    INTO v_items
    FROM (
      SELECT hardware_id, user_count, user_ids
      FROM app.v_technical_anomalies_hardware
      WHERE user_count >= v_threshold
      ORDER BY user_count DESC
      LIMIT p_limit
    ) t;
  ELSE -- high_login_concentration
    SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.login_count DESC),'[]'::jsonb)
    INTO v_items
    FROM (
      SELECT id_usuario::text AS id_usuario,
             COUNT(*)      AS login_count,
             MIN(started_at) AS first_login,
             MAX(started_at) AS last_login
      FROM auth.user_telemetry_sessions
      WHERE started_at > now() - make_interval(mins => v_window)
      GROUP BY id_usuario
      HAVING COUNT(*) >= v_threshold
      ORDER BY COUNT(*) DESC
      LIMIT p_limit
    ) t;
  END IF;

  -- Auditar consulta
  PERFORM app.rpc_audit_log_append(
    'ADMIN_TECHNICAL_ANOMALIES_QUERY', 'technical_signals', p_kind,
    jsonb_build_object('threshold', v_threshold, 'items_count', jsonb_array_length(v_items))
  );

  RETURN jsonb_build_object(
    'status','ok',
    'kind', p_kind,
    'items', v_items,
    'meta', jsonb_build_object(
      'threshold', v_threshold,
      'window_minutes', v_window,
      'count', jsonb_array_length(v_items),
      'limit', p_limit
    ),
    'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
END;
$$;


--
-- Name: rpc_admin_get_user_technical_signals(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_get_user_technical_signals(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_ips        jsonb;
  v_devices    jsonb;
  v_hardware   jsonb;
  v_recent     jsonb;
BEGIN
  PERFORM app.rpc_admin_assert_access('auditor');

  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id requerido' USING ERRCODE='23502';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_user_id) THEN
    RETURN jsonb_build_object('status','not_found','id_usuario',p_user_id);
  END IF;

  SELECT COALESCE(jsonb_agg(DISTINCT host(ip_address)),'[]'::jsonb) INTO v_ips
  FROM auth.user_telemetry_sessions
  WHERE id_usuario = p_user_id AND ip_address IS NOT NULL;

  SELECT COALESCE(jsonb_agg(DISTINCT id_dispositivo),'[]'::jsonb) INTO v_devices
  FROM auth.user_telemetry_sessions
  WHERE id_usuario = p_user_id AND id_dispositivo IS NOT NULL;

  SELECT COALESCE(jsonb_agg(DISTINCT hardware_id),'[]'::jsonb) INTO v_hardware
  FROM auth.user_telemetry_sessions
  WHERE id_usuario = p_user_id AND hardware_id IS NOT NULL;

  SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.started_at DESC),'[]'::jsonb) INTO v_recent
  FROM (
    SELECT session_id, host(ip_address) AS ip, id_dispositivo, hardware_id, user_agent, started_at
    FROM auth.user_telemetry_sessions
    WHERE id_usuario = p_user_id
    ORDER BY started_at DESC
    LIMIT 20
  ) t;

  RETURN jsonb_build_object(
    'status','ok',
    'id_usuario', p_user_id,
    'ip_addresses',  v_ips,
    'device_ids',    v_devices,
    'hardware_ids',  v_hardware,
    'recent_sessions', v_recent,
    'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
END;
$$;


--
-- Name: rpc_admin_get_work_queue(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_get_work_queue(p_filters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_admin_id  uuid;
  v_items     jsonb;
  v_total     int;
  v_limit     int  := COALESCE((p_filters->>'limit')::int, 20);
  v_offset    int  := COALESCE((p_filters->>'offset')::int, 0);
  v_type      text := p_filters->>'item_type';
  v_status    text := COALESCE(p_filters->>'status', 'open');
  v_only_mine bool := COALESCE((p_filters->>'only_mine')::bool, false);
BEGIN
  v_admin_id := app.jwt_user_id_safe();
  IF v_admin_id IS NULL OR app.jwt_role_safe() <> 'db_admin' THEN
    RAISE EXCEPTION 'Acceso denegado: requiere rol db_admin' USING ERRCODE = '42501';
  END IF;

  IF v_type IS NOT NULL AND v_type NOT IN ('dispute','fraud_alert','content_flag','report_request') THEN
    RAISE EXCEPTION 'item_type inválido: %', v_type USING ERRCODE = '22023';
  END IF;

  -- Contar total
  SELECT count(*) INTO v_total
  FROM app.v_admin_work_queue_projection wi
  WHERE (v_type IS NULL OR wi.tipo_item = v_type)
    AND wi.estado = v_status
    AND (NOT v_only_mine OR wi.id_admin_asignado = v_admin_id);

  -- Obtener página
  SELECT jsonb_agg(row_to_json(wi)::jsonb ORDER BY
    CASE wi.priority WHEN 'critical' THEN 1 WHEN 'high' THEN 2
                     WHEN 'normal' THEN 3 ELSE 4 END,
    wi.vencimiento_sla_en ASC NULLS LAST
  ) INTO v_items
  FROM (
    SELECT * FROM app.v_admin_work_queue_projection
    WHERE (v_type IS NULL OR tipo_item = v_type)
      AND estado = v_status
      AND (NOT v_only_mine OR id_admin_asignado = v_admin_id)
    ORDER BY
      CASE priority WHEN 'critical' THEN 1 WHEN 'high' THEN 2 WHEN 'normal' THEN 3 ELSE 4 END,
      vencimiento_sla_en ASC NULLS LAST
    LIMIT v_limit OFFSET v_offset
  ) wi;

  RETURN jsonb_build_object(
    'items',      COALESCE(v_items, '[]'::jsonb),
    'total',      v_total,
    'limit',      v_limit,
    'offset',     v_offset,
    'timestamp_utc', now()
  );
END;
$$;


--
-- Name: rpc_admin_network_graph_view(text, text, integer, integer, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_network_graph_view(p_focus_entity_type text DEFAULT 'Seller'::text, p_focus_entity_id text DEFAULT NULL::text, p_depth integer DEFAULT 1, p_limit_nodes integer DEFAULT 100, p_limit_edges integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ag_catalog', 'app', 'public', 'auth', 'pg_temp'
    AS $_$
DECLARE
  v_graph_name TEXT;
  v_nodes      jsonb := '[]'::jsonb;
  v_edges      jsonb := '[]'::jsonb;
  v_truncated  boolean := false;
  v_dep_missing jsonb;
BEGIN
  PERFORM app.rpc_admin_assert_access('auditor');

  -- R-30: validación de entrada
  IF p_focus_entity_type NOT IN ('Seller','Buyer','Producto','Categoria','Ubicacion') THEN
    RAISE EXCEPTION 'entity_type inválido: %', p_focus_entity_type USING ERRCODE='22P02';
  END IF;
  IF p_depth < 1 OR p_depth > 3 THEN
    RAISE EXCEPTION 'depth debe estar en [1,3]' USING ERRCODE='22003';
  END IF;
  IF p_limit_nodes <= 0 OR p_limit_nodes > 500 THEN
    RAISE EXCEPTION 'limit_nodes debe estar en (0,500]' USING ERRCODE='22003';
  END IF;
  IF p_limit_edges <= 0 OR p_limit_edges > 1000 THEN
    RAISE EXCEPTION 'limit_edges debe estar en (0,1000]' USING ERRCODE='22003';
  END IF;

  -- Degradación elegante: AGE no disponible
  BEGIN
    SELECT name INTO v_graph_name
    FROM ag_catalog.ag_graph
    WHERE name = 'kambalache_marketplace_graph'
    LIMIT 1;
  EXCEPTION WHEN undefined_table OR undefined_schema THEN
    v_graph_name := NULL;
  END;

  IF v_graph_name IS NULL THEN
    v_dep_missing := jsonb_build_object(
      'status','dependency_missing',
      'reason','AGE no disponible o grafo kambalache_marketplace_graph no existe',
      'graph', jsonb_build_object('nodes', v_nodes, 'edges', v_edges),
      'meta', jsonb_build_object(
        'truncated', false,
        'max_nodes', p_limit_nodes,
        'max_edges', p_limit_edges,
        'source','age'
      ),
      'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
    );
    -- Auditoría de intento
    PERFORM app.rpc_audit_log_append(
      'ADMIN_NETWORK_GRAPH_VIEW_DEGRADED',
      'graph',
      COALESCE(p_focus_entity_id,'*'),
      jsonb_build_object('entity_type',p_focus_entity_type,'depth',p_depth)
    );
    RETURN v_dep_missing;
  END IF;

  -- Consulta Cypher acotada. Labels y aristas verificadas contra age_graph_implementation_V4.sql.
  IF p_focus_entity_id IS NULL THEN
    -- Sin foco: retornar hasta p_limit_nodes de un tipo dado (muestra)
    EXECUTE format($cy$
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'id', (n).id::text,
               'label', %L,
               'entity_type', %L,
               'entity_id', (n).properties->>'entity_id',
               'state', COALESCE((n).properties->>'state','activo')
             )), '[]'::jsonb)
      FROM cypher('kambalache_marketplace_graph', $c$
        MATCH (n:%s)
        RETURN n
        LIMIT %s
      $c$) AS (n agtype)
    $cy$, p_focus_entity_type, p_focus_entity_type, p_focus_entity_type, p_limit_nodes)
    INTO v_nodes;
  ELSE
    -- Con foco: BFS acotada de profundidad p_depth
    EXECUTE format($cy$
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'id', (n).id::text,
               'label', (n).label,
               'entity_id', (n).properties->>'entity_id',
               'state', COALESCE((n).properties->>'state','activo')
             )), '[]'::jsonb)
      FROM cypher('kambalache_marketplace_graph', $c$
        MATCH (a:%s {id_entidad: %L})-[*1..%s]-(n)
        RETURN DISTINCT n
        LIMIT %s
      $c$) AS (n agtype)
    $cy$, p_focus_entity_type, p_focus_entity_id, p_depth, p_limit_nodes)
    INTO v_nodes;

    EXECUTE format($cy$
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'id', (r).id::text,
               'source', (r).start_id::text,
               'target', (r).end_id::text,
               'type', (r).label
             )), '[]'::jsonb)
      FROM cypher('kambalache_marketplace_graph', $c$
        MATCH (a:%s {id_entidad: %L})-[r*1..%s]-(b)
        UNWIND r AS rel
        RETURN DISTINCT rel
        LIMIT %s
      $c$) AS (r agtype)
    $cy$, p_focus_entity_type, p_focus_entity_id, p_depth, p_limit_edges)
    INTO v_edges;
  END IF;

  v_truncated := (jsonb_array_length(v_nodes) >= p_limit_nodes)
              OR (jsonb_array_length(v_edges) >= p_limit_edges);

  -- Auditoría de acceso al visor
  PERFORM app.rpc_audit_log_append(
    'ADMIN_NETWORK_GRAPH_VIEW',
    'graph',
    COALESCE(p_focus_entity_id,'*'),
    jsonb_build_object(
      'entity_type',p_focus_entity_type,
      'depth',p_depth,
      'nodes_returned', jsonb_array_length(v_nodes),
      'edges_returned', jsonb_array_length(v_edges),
      'truncated', v_truncated
    )
  );

  RETURN jsonb_build_object(
    'status','ok',
    'graph', jsonb_build_object('nodes', v_nodes, 'edges', v_edges),
    'meta', jsonb_build_object(
      'truncated', v_truncated,
      'max_nodes', p_limit_nodes,
      'max_edges', p_limit_edges,
      'source','age',
      'graph_name', v_graph_name,
      'focus_entity_type', p_focus_entity_type,
      'focus_entity_id', p_focus_entity_id,
      'depth', p_depth
    ),
    'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );

EXCEPTION
  WHEN undefined_function OR undefined_table THEN
    -- AGE cargado pero cypher() no disponible en sesión
    RETURN jsonb_build_object(
      'status','dependency_missing',
      'reason','cypher() no disponible en la sesión (LOAD ''age'' requerido)',
      'graph', jsonb_build_object('nodes','[]'::jsonb,'edges','[]'::jsonb),
      'meta', jsonb_build_object('source','age','max_nodes',p_limit_nodes,'max_edges',p_limit_edges),
      'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
    );
END;
$_$;


--
-- Name: rpc_admin_network_health_summary(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_network_health_summary() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor jsonb;
  v_row   app.mv_admin_network_health%ROWTYPE;
BEGIN
  -- R-82: seguridad transversal (CU-ADMIN-045)
  v_actor := app.rpc_admin_assert_access('auditor');

  SELECT * INTO v_row FROM app.mv_admin_network_health LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'status','dependency_missing',
      'reason','mv_admin_network_health vacía; ejecutar REFRESH',
      'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
    );
  END IF;

  RETURN jsonb_build_object(
    'status','ok',
    'summary', jsonb_build_object(
      'users_active',            v_row.users_active,
      'users_suspended',         v_row.users_suspended,
      'users_inactive',          v_row.users_inactive,
      'alerts_open',             v_row.alerts_open,
      'alerts_high',             v_row.alerts_high,
      'critical_alerts_pending', v_row.critical_alerts_pending,
      'transitions_last_24h',    v_row.transitions_last_24h,
      'refreshed_at',            v_row.refrescado_en
    ),
    'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
END;
$$;


--
-- Name: rpc_admin_node_impact_summary(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_node_impact_summary(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ag_catalog', 'app', 'public', 'auth', 'pg_temp'
    AS $_$
DECLARE
  v_row       app.v_user_impact_projection%ROWTYPE;
  v_graph     TEXT;
  v_degree    INTEGER := NULL;
  v_neighbors INTEGER := NULL;
  v_role      TEXT;
BEGIN
  PERFORM app.rpc_admin_assert_access('admin');

  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id no puede ser NULL' USING ERRCODE='23502';
  END IF;

  SELECT * INTO v_row FROM app.v_user_impact_projection WHERE id_usuario = p_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'status','not_found',
      'id_usuario', p_user_id,
      'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
    );
  END IF;

  v_role := v_row.role;

  -- Impacto en AGE (degradación elegante)
  BEGIN
    SELECT name INTO v_graph FROM ag_catalog.ag_graph
    WHERE name='kambalache_marketplace_graph' LIMIT 1;
  EXCEPTION WHEN undefined_table OR invalid_schema_name THEN
    v_graph := NULL;
  END;

  IF v_graph IS NOT NULL THEN
    BEGIN
      -- Grado del vértice matcheado por id_entidad
      EXECUTE format($cy$
        SELECT (n)::text::int
        FROM cypher('kambalache_marketplace_graph', $c$
          MATCH (u {id_entidad: %L})-[r]-()
          RETURN count(DISTINCT r)
        $c$) AS (n agtype)
      $cy$, p_user_id::text)
      INTO v_degree;

      EXECUTE format($cy$
        SELECT (n)::text::int
        FROM cypher('kambalache_marketplace_graph', $c$
          MATCH (u {id_entidad: %L})-[]-(x)
          RETURN count(DISTINCT x)
        $c$) AS (n agtype)
      $cy$, p_user_id::text)
      INTO v_neighbors;
    EXCEPTION WHEN OTHERS THEN
      v_degree := NULL; v_neighbors := NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'status','ok',
    'id_usuario', p_user_id,
    'sql_impact', jsonb_build_object(
      'role',                v_role,
      'is_active',           v_row.is_active,
      'already_deleted',     v_row.fecha_eliminacion IS NOT NULL,
      'open_alerts',         v_row.open_alerts,
      'active_memberships',  v_row.active_memberships,
      'transitions_count',   v_row.transitions_count
    ),
    'graph_impact', jsonb_build_object(
      'graph_available',   v_graph IS NOT NULL,
      'degree',            v_degree,
      'neighbors',         v_neighbors
    ),
    'is_admin_role', v_role IN ('administrador_role','superadmin_role','SuperAdmin'),
    'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
END;
$_$;


--
-- Name: rpc_admin_query_fraud_graph(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_query_fraud_graph(p_user_id uuid, p_depth integer DEFAULT 2) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_admin_id  uuid;
  v_nodes     jsonb;
  v_edges     jsonb;
BEGIN
  v_admin_id := app.jwt_user_id_safe();
  IF v_admin_id IS NULL OR app.jwt_role_safe() <> 'db_admin' THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;

  IF p_depth NOT BETWEEN 1 AND 4 THEN
    RAISE EXCEPTION 'depth debe estar entre 1 y 4' USING ERRCODE = '22023';
  END IF;

  BEGIN
    -- Nodos del vecindario (R-42: cypher via wrapper)
    SELECT jsonb_agg(jsonb_build_object(
      'id', n.id, 'label', n.label, 'properties', n.properties))
    INTO v_nodes
    FROM cypher('smtp_posix_graph', format(
      'MATCH (center {user_id: "%s"})-[*..' || p_depth || ']->(neighbor)
       RETURN neighbor AS n',
      p_user_id
    )) AS (n agtype);

    -- Aristas del vecindario
    SELECT jsonb_agg(jsonb_build_object(
      'from', e.start_id, 'to', e.end_id, 'type', e.edge_label, 'properties', e.properties))
    INTO v_edges
    FROM cypher('smtp_posix_graph', format(
      'MATCH (center {user_id: "%s"})-[r*..' || p_depth || ']->(neighbor)
       RETURN r AS e',
      p_user_id
    )) AS (e agtype);

  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Error consultando grafo AGE (¿extensión disponible?): %', SQLERRM
      USING ERRCODE = '58000';
  END;

  RETURN jsonb_build_object(
    'id_usuario',      p_user_id,
    'depth',        p_depth,
    'nodes',        COALESCE(v_nodes, '[]'::jsonb),
    'edges',        COALESCE(v_edges, '[]'::jsonb),
    'node_count',   jsonb_array_length(COALESCE(v_nodes, '[]'::jsonb)),
    'edge_count',   jsonb_array_length(COALESCE(v_edges, '[]'::jsonb)),
    'timestamp_utc', now()
  );
END; $$;


--
-- Name: rpc_admin_resolve_case(text, uuid, text, text, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_resolve_case(p_case_type text, p_case_id uuid, p_decision text, p_rationale text, p_effects jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_admin_id    uuid;
  v_decision_id uuid;
  v_decision_hash text;
  v_current_status text;
  v_work_item_id   uuid;
BEGIN
  -- R-30: Autenticación
  v_admin_id := app.jwt_user_id_safe();
  IF v_admin_id IS NULL OR app.jwt_role_safe() <> 'db_admin' THEN
    RAISE EXCEPTION 'Acceso denegado: requiere rol db_admin' USING ERRCODE = '42501';
  END IF;

  -- R-30: Validar parámetros
  IF p_case_type NOT IN ('dispute','content','fraud','user_sanction') THEN
    RAISE EXCEPTION 'case_type inválido: %', p_case_type USING ERRCODE = '22023';
  END IF;
  IF p_rationale IS NULL OR length(trim(p_rationale)) < 10 THEN
    RAISE EXCEPTION 'rationale obligatorio (mínimo 10 caracteres)' USING ERRCODE = '22023';
  END IF;

  -- Validar estado actual del caso según tipo
  CASE p_case_type
    WHEN 'dispute' THEN
      SELECT estado INTO v_current_status FROM app.disputes
      WHERE id_disputa = p_case_id AND fecha_eliminacion IS NULL FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Disputa no encontrada' USING ERRCODE = 'P0001'; END IF;
      IF v_current_status IN ('resolved','closed') THEN
        RAISE EXCEPTION 'Disputa ya resuelta (estado: %)', v_current_status USING ERRCODE = 'P0002';
      END IF;

    WHEN 'content' THEN
      SELECT estado INTO v_current_status FROM app.content_moderation
      WHERE moderation_id = p_case_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Contenido no encontrado' USING ERRCODE = 'P0001'; END IF;
      IF v_current_status <> 'pending' THEN
        RAISE EXCEPTION 'Contenido ya procesado (estado: %)', v_current_status USING ERRCODE = 'P0002';
      END IF;

    WHEN 'fraud' THEN
      SELECT estado_flag INTO v_current_status FROM app.fraud_scores
      WHERE score_id = p_case_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Score no encontrado' USING ERRCODE = 'P0001'; END IF;
      IF v_current_status = 'none' THEN
        RAISE EXCEPTION 'Score sin flag activo' USING ERRCODE = 'P0002';
      END IF;

    WHEN 'user_sanction' THEN
      SELECT (CASE WHEN fecha_eliminacion IS NULL THEN 'active' ELSE 'deleted' END)
      INTO v_current_status FROM auth.users WHERE id = p_case_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'Usuario no encontrado' USING ERRCODE = 'P0001'; END IF;
  END CASE;

  -- 1. Registrar decisión WORM (R-56, R-47)
  INSERT INTO app.case_decisions
    (case_type, id_caso, id_admin, decision, rationale, effects)
  VALUES
    (p_case_type, p_case_id, v_admin_id, p_decision, p_rationale, p_effects)
  RETURNING decision_id, decision_hash INTO v_decision_id, v_decision_hash;

  -- 2. Actualizar registro origen según tipo y decisión
  CASE p_case_type
    WHEN 'dispute' THEN
      UPDATE app.disputes SET
        estado = CASE WHEN p_decision = 'escalate' THEN 'escalated' ELSE 'resolved' END,
        resolution_type = CASE
          WHEN p_decision = 'resolve_refund' THEN 'refund'
          WHEN p_decision = 'resolve_partial_refund' THEN 'partial_refund'
          WHEN p_decision = 'resolve_replacement' THEN 'replacement'
          ELSE 'no_action' END,
        resolution_amount = COALESCE((p_effects->>'amount')::numeric, 0),
        id_admin_asignado = v_admin_id,
        resuelto_en = now(),
        notes = p_rationale
      WHERE id_disputa = p_case_id;

    WHEN 'content' THEN
      UPDATE app.content_moderation SET
        estado = CASE p_decision WHEN 'approve' THEN 'approved' WHEN 'remove' THEN 'removed'
                                 WHEN 'escalate' THEN 'escalated' ELSE 'removed' END,
        reviewed_by_admin = v_admin_id,
        revisado_en = now(),
        removal_reason = p_rationale,
        fecha_actualizacion = now()
      WHERE moderation_id = p_case_id;

    WHEN 'fraud' THEN
      UPDATE app.fraud_scores SET
        estado_flag = CASE p_decision
          WHEN 'suspend' THEN 'suspended'
          WHEN 'warn'    THEN 'warning'
          WHEN 'dismiss' THEN 'none'
          ELSE estado_flag END
      WHERE score_id = p_case_id;

    WHEN 'user_sanction' THEN
      IF p_decision = 'suspend' THEN
        UPDATE auth.users SET fecha_eliminacion = now() WHERE id = p_case_id;
      END IF;
  END CASE;

  -- 3. Cerrar ítem de trabajo asociado
  SELECT work_item_id INTO v_work_item_id
  FROM app.work_items WHERE ref_id = p_case_id AND estado <> 'resolved' LIMIT 1;

  IF v_work_item_id IS NOT NULL THEN
    UPDATE app.work_items
    SET estado = 'resolved', fecha_actualizacion = now()
    WHERE work_item_id = v_work_item_id;
  END IF;

  -- 4. Registrar en admin_audit_log WORM (R-56)
  INSERT INTO app.admin_audit_log
    (id_admin, tipo_accion, target_resource, id_recurso_objetivo, action_details)
  VALUES
    (v_admin_id, 'resolve_case', p_case_type, p_case_id,
     jsonb_build_object(
       'decision_id', v_decision_id, 'decision', p_decision,
       'rationale', p_rationale, 'effects', p_effects,
       'decision_hash', v_decision_hash));

  -- 5. Proyectar al ledger para no-repudio (R-47)
  PERFORM app.rpc_ledger_append_event(
    'admin_case_resolved', p_case_id, p_case_type,
    jsonb_build_object(
      'decision_id', v_decision_id, 'admin_id', v_admin_id,
      'decision', p_decision, 'hash', v_decision_hash));

  -- R-30: Contrato de salida
  RETURN jsonb_build_object(
    'decision_id',    v_decision_id,
    'case_type',      p_case_type,
    'case_id',        p_case_id,
    'decision',       p_decision,
    'decision_hash',  v_decision_hash,
    'status',         'resolved',
    'timestamp_utc',  now()
  );
END;
$$;


--
-- Name: rpc_admin_resolve_visual_state(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_resolve_visual_state(p_entity_type text, p_entity_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_visual TEXT;
  v_color  TEXT;
  v_hint   TEXT;
BEGIN
  PERFORM app.rpc_admin_assert_access('auditor');

  -- R-30
  IF p_entity_type NOT IN ('user','alert','case') THEN
    RAISE EXCEPTION 'entity_type inválido (esperado: user|alert|case)' USING ERRCODE='22P02';
  END IF;
  IF p_entity_id IS NULL OR length(trim(p_entity_id)) = 0 THEN
    RAISE EXCEPTION 'entity_id requerido' USING ERRCODE='23502';
  END IF;

  SELECT visual_state INTO v_visual
  FROM app.v_admin_visual_state
  WHERE tipo_entidad = p_entity_type AND id_entidad = p_entity_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'status','not_found',
      'entity_type', p_entity_type,
      'entity_id',   p_entity_id
    );
  END IF;

  v_color := CASE v_visual
               WHEN 'activo'      THEN 'green'
               WHEN 'en_revision' THEN 'yellow'
               WHEN 'suspendido'  THEN 'red'
               ELSE 'gray'
             END;

  v_hint := CASE v_visual
              WHEN 'activo'      THEN 'Entidad operativa normal'
              WHEN 'en_revision' THEN 'Entidad con alertas activas o pendiente de revisión admin'
              WHEN 'suspendido'  THEN 'Entidad dada de baja o cerrada (evidencia preservada)'
            END;

  RETURN jsonb_build_object(
    'status','ok',
    'entity_type',  p_entity_type,
    'entity_id',    p_entity_id,
    'visual_state', v_visual,
    'color',        v_color,
    'hint',         v_hint,
    'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
END;
$$;


--
-- Name: rpc_admin_resolve_visual_state_batch(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_resolve_visual_state_batch(p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_count int;
  v_result jsonb;
BEGIN
  PERFORM app.rpc_admin_assert_access('auditor');

  IF jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'p_items debe ser un array JSON' USING ERRCODE='22P02';
  END IF;

  v_count := jsonb_array_length(p_items);
  IF v_count = 0 THEN
    RETURN jsonb_build_object('status','ok','items','[]'::jsonb,'meta',jsonb_build_object('count',0));
  END IF;
  IF v_count > 500 THEN
    RAISE EXCEPTION 'p_items no puede exceder 500 elementos' USING ERRCODE='22003';
  END IF;

  WITH req AS (
    SELECT (elem->>'entity_type')::text AS tipo_entidad,
           (elem->>'entity_id')::text   AS id_entidad
    FROM jsonb_array_elements(p_items) elem
  ), resolved AS (
    SELECT r.tipo_entidad, r.id_entidad, v.visual_state
    FROM req r
    LEFT JOIN app.v_admin_visual_state v
           ON v.tipo_entidad = r.tipo_entidad AND v.id_entidad = r.id_entidad
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'entity_type',  tipo_entidad,
    'entity_id',    id_entidad,
    'visual_state', COALESCE(visual_state,'not_found'),
    'color',        CASE COALESCE(visual_state,'not_found')
                      WHEN 'activo'      THEN 'green'
                      WHEN 'en_revision' THEN 'yellow'
                      WHEN 'suspendido'  THEN 'red'
                      ELSE 'gray'
                    END
  )), '[]'::jsonb)
  INTO v_result FROM resolved;

  RETURN jsonb_build_object(
    'status','ok',
    'items', v_result,
    'meta', jsonb_build_object('count', v_count),
    'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
END;
$$;


--
-- Name: rpc_admin_restaurar_categoria(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_restaurar_categoria(p_categoria_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := app.jwt_user_id_safe();
BEGIN
    IF v_actor IS NULL OR NOT auth.fn_is_admin() THEN
        RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
    END IF;

    UPDATE auth.categorias
       SET activo = true
     WHERE id = p_categoria_id AND activo = false
    RETURNING id INTO p_categoria_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Categoría inexistente o ya activa' USING ERRCODE = '02000';
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'categoria_id', p_categoria_id,
        'tipo_cambio', 'RESTAURADA',
        'timestamp_utc', to_char(now(),'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    );
END; $$;


