--
-- Name: rpc_admin_technical_anomalies_scan_and_alert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_technical_anomalies_scan_and_alert() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_ip_count      int := 0;
  v_device_count  int := 0;
  v_ins_count     int := 0;
BEGIN
  PERFORM app.rpc_admin_assert_access('admin');

  IF NOT EXISTS (SELECT 1 FROM auth.user_telemetry_sessions LIMIT 1) THEN
    RETURN jsonb_build_object('status','dependency_missing','reason','sin telemetría');
  END IF;

  -- IP compartida crítica (>=5 usuarios)
  WITH ins AS (
    INSERT INTO public.admin_alerts(tipo, descripcion, nivel_riesgo, score_riesgo, estado, referencia_tipo, referencia_id)
    SELECT
      'TECHNICAL_IP_SHARED',
      format('IP %s compartida por %s usuarios', host(v.ip_address), v.user_count),
      CASE WHEN v.user_count >= 10 THEN 'critico'
           WHEN v.user_count >= 5  THEN 'alto'
           ELSE 'medio' END,
      LEAST(100, v.user_count * 10),
      'open',
      'ip', host(v.ip_address)
    FROM app.v_technical_anomalies_ip v
    WHERE v.user_count >= 3
      AND NOT EXISTS (
        SELECT 1 FROM public.admin_alerts a
        WHERE a.tipo='TECHNICAL_IP_SHARED'
          AND a.referencia_id = host(v.ip_address)
          AND a.estado IN ('open','in_review')
      )
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_ip_count FROM ins;

  WITH ins AS (
    INSERT INTO public.admin_alerts(tipo, descripcion, nivel_riesgo, score_riesgo, estado, referencia_tipo, referencia_id)
    SELECT
      'TECHNICAL_DEVICE_SHARED',
      format('device_id %s compartido por %s usuarios', v.id_dispositivo, v.user_count),
      CASE WHEN v.user_count >= 5 THEN 'critico'
           WHEN v.user_count >= 3 THEN 'alto'
           ELSE 'medio' END,
      LEAST(100, v.user_count * 15),
      'open',
      'device', v.id_dispositivo
    FROM app.v_technical_anomalies_device v
    WHERE v.user_count >= 2
      AND NOT EXISTS (
        SELECT 1 FROM public.admin_alerts a
        WHERE a.tipo='TECHNICAL_DEVICE_SHARED'
          AND a.referencia_id = v.id_dispositivo
          AND a.estado IN ('open','in_review')
      )
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_device_count FROM ins;

  v_ins_count := v_ip_count + v_device_count;

  PERFORM app.rpc_audit_log_append(
    'ADMIN_TECHNICAL_ANOMALIES_SCAN', 'technical_signals','*',
    jsonb_build_object('ip_alerts', v_ip_count, 'device_alerts', v_device_count)
  );

  RETURN jsonb_build_object(
    'status','ok',
    'alerts_created', v_ins_count,
    'breakdown', jsonb_build_object('ip', v_ip_count, 'device', v_device_count),
    'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
END;
$$;


--
-- Name: rpc_admin_top_network_anomalies(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_top_network_anomalies(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_items jsonb := '[]'::jsonb;
BEGIN
  PERFORM app.rpc_admin_assert_access('auditor');

  -- R-30: validación
  IF p_limit IS NULL OR p_limit <= 0 OR p_limit > 500 THEN
    RAISE EXCEPTION 'p_limit debe estar en (0, 500]' USING ERRCODE = '22003';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY (t.score_riesgo, t.created_at) DESC), '[]'::jsonb)
  INTO v_items
  FROM (
    SELECT id, tipo, descripcion, nivel_riesgo, score_riesgo,
           estado, referencia_id, referencia_tipo, created_at
    FROM app.v_admin_top_anomalies
    ORDER BY
      CASE nivel_riesgo
        WHEN 'critico' THEN 1
        WHEN 'alto'    THEN 2
        WHEN 'medio'   THEN 3
        WHEN 'bajo'    THEN 4
        ELSE 5
      END,
      created_at DESC
    LIMIT p_limit
  ) t;

  RETURN jsonb_build_object(
    'status','ok',
    'items', v_items,
    'meta', jsonb_build_object(
      'limit', p_limit,
      'count', jsonb_array_length(v_items),
      'source','public.admin_alerts'
    ),
    'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
END;
$$;


--
-- Name: rpc_admin_update_config(text, jsonb, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_admin_update_config(p_config_key text, p_new_value jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_admin_id  uuid;
  v_old_value jsonb;
  v_hist_id   uuid;
  v_hist_hash text;
BEGIN
  v_admin_id := app.jwt_user_id_safe();
  IF v_admin_id IS NULL OR app.jwt_role_safe() <> 'db_admin' THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 10 THEN
    RAISE EXCEPTION 'reason obligatorio (mínimo 10 caracteres)' USING ERRCODE = '22023';
  END IF;

  -- Leer valor anterior
  SELECT config_value INTO v_old_value FROM app.system_config WHERE config_key = p_config_key;

  -- UPSERT en system_config
  INSERT INTO app.system_config (config_key, config_value, updated_by, fecha_actualizacion)
  VALUES (p_config_key, p_new_value, v_admin_id, now())
  ON CONFLICT (config_key) DO UPDATE
    SET config_value = EXCLUDED.config_value,
        updated_by = EXCLUDED.updated_by,
        fecha_actualizacion = EXCLUDED.fecha_actualizacion;

  -- Registrar en historial WORM
  INSERT INTO app.config_history (config_key, old_value, new_value, changed_by, change_reason)
  VALUES (p_config_key, v_old_value, p_new_value, v_admin_id, p_reason)
  RETURNING history_id, history_hash INTO v_hist_id, v_hist_hash;

  -- Registrar en admin_audit_log (R-56)
  INSERT INTO app.admin_audit_log
    (id_admin, tipo_accion, target_resource, id_recurso_objetivo, action_details)
  VALUES
    (v_admin_id, 'update_config', 'system_config',
     (SELECT config_id FROM app.system_config WHERE config_key = p_config_key),
     jsonb_build_object('key', p_config_key, 'old', v_old_value, 'new', p_new_value, 'reason', p_reason));

  RETURN jsonb_build_object(
    'config_key',   p_config_key,
    'new_value',    p_new_value,
    'history_id',   v_hist_id,
    'history_hash', v_hist_hash,
    'timestamp_utc', now()
  );
END; $$;


--
-- Name: rpc_audit_log_append(text, text, text, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_audit_log_append(p_action text, p_target_type text, p_target_id text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor_id uuid := public.get_app_actor_id();
  v_id       integer;
BEGIN
  IF p_action IS NULL OR length(trim(p_action)) = 0 THEN RAISE EXCEPTION 'action requerido' USING ERRCODE='23502'; END IF;
  IF p_target_type IS NULL OR length(trim(p_target_type)) = 0 THEN RAISE EXCEPTION 'target_type requerido' USING ERRCODE='23502'; END IF;
  INSERT INTO auth.auditoria(id_actor, action, target_kind, id_objetivo, metadata, fecha_creacion)
  VALUES (v_actor_id, p_action, p_target_type, p_target_id,
    COALESCE(p_metadata,'{}'::jsonb) || jsonb_build_object('timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'event_hash', encode(digest(COALESCE(p_action,'')||COALESCE(p_target_type,'')||COALESCE(p_target_id,'')||COALESCE(p_metadata::text,''),'sha256'),'hex')), now())
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('status','ok','audit_id', v_id);
END;
$$;


--
-- Name: rpc_bi_detect_bridge_customers(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_bi_detect_bridge_customers() RETURNS TABLE(id_comprador text, zones_covered_count bigint, total_spent numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog'
    AS $_$
BEGIN
    RETURN QUERY
    SELECT
        v.uid,
        v.zones_count,
        v.total_monto::numeric(12,2)
    FROM (
        SELECT * FROM cypher('kambalache_network', $cypher$
            MATCH (u:UserNode)-[r:COMPRO_EXITOSAMENTE]->(s:SellerNode),
                  (o:OrderNode {id: r.id_orden})-[:DELIVERS_TO]->(z:Zone)
            WITH u.id AS uid, count(DISTINCT z.label) AS zones_count, sum(r.monto) AS total_monto
            WHERE zones_count > 1
            RETURN uid, zones_count, total_monto
        $cypher$, jsonb_empty_object())
        AS (uid agtype, zones_count agtype, total_monto agtype)
    ) AS v(uid, zones_count, total_monto)
    ORDER BY v.total_monto DESC, v.zones_count DESC;
END;
$_$;


--
-- Name: rpc_bi_get_seller_affinity_network(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_bi_get_seller_affinity_network(p_target_id_vendedor text, p_quadrant_label text) RETURNS TABLE(potential_partner_id_vendedor text, shared_customers_count bigint, strength_percentage numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog'
    AS $_$
BEGIN
    RETURN QUERY
    SELECT
        v.partner_id,
        v.shared_clients,
        ((v.shared_clients::numeric / v.total_seller_clients) * 100)::numeric(5,2)
            AS strength_percentage
    FROM (
        SELECT * FROM cypher('kambalache_network', $cypher$
            MATCH (s1:SellerNode {id: $id_objetivo})-[:SUPPLIES_IN]->(z:Zone {label: $quadrant}),
                  (u:UserNode)-[:COMPRO_EXITOSAMENTE]->(s1)
            MATCH (u)-[:COMPRO_EXITOSAMENTE]->(s2:SellerNode)
            WHERE s2.id <> s1.id
            MATCH (s2)-[:SUPPLIES_IN]->(z)
            WITH s1, s2, count(DISTINCT u) AS shared_count
            MATCH (all_u:UserNode)-[:COMPRO_EXITOSAMENTE]->(s1)
            WITH s2.id AS partner_id, shared_count, count(DISTINCT all_u) AS total_base
            RETURN partner_id, shared_count, total_base
        $cypher$, jsonb_build_object(
                'target_id', p_target_id_vendedor,
                'quadrant',  p_quadrant_label
        )) AS (partner_id agtype, shared_count agtype, total_base agtype)
    ) AS v(partner_id, shared_clients, total_seller_clients)
    ORDER BY v.shared_clients DESC;
END;
$_$;


--
-- Name: rpc_cu_a_bs_001_main(text, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_cu_a_bs_001_main(p_action text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_target uuid;
BEGIN
  CASE p_action
    WHEN 'soft_delete' THEN
      v_target := nullif(p_payload->>'target_user_id','')::uuid;
      v_result := auth.admin_soft_delete_user(v_target, p_payload->>'reason');
    WHEN 'restore' THEN
      v_target := nullif(p_payload->>'target_user_id','')::uuid;
      v_result := auth.admin_restore_user(v_target, p_payload->>'reason');
    WHEN 'anonymize' THEN
      v_target := nullif(p_payload->>'target_user_id','')::uuid;
      v_result := auth.admin_anonymize_user(v_target, p_payload->>'reason');
    WHEN 'purge' THEN
      v_target := nullif(p_payload->>'target_user_id','')::uuid;
      v_result := auth.admin_purge_user(v_target, p_payload->>'reason');
    WHEN 'auto_route' THEN
      v_target := nullif(p_payload->>'target_user_id','')::uuid;
      v_result := auth.admin_auto_route_purge_or_anonymize(v_target, p_payload->>'reason');
    WHEN 'set_membership' THEN
      v_target := nullif(p_payload->>'target_user_id','')::uuid;
      v_result := auth.admin_set_user_membership(v_target, p_payload->>'tier_code');
    WHEN 'set_legal_hold' THEN
      v_target := nullif(p_payload->>'target_user_id','')::uuid;
      v_result := auth.admin_set_legal_hold(v_target, (p_payload->>'legal_hold')::boolean, p_payload->>'reason');
    WHEN 'maintenance' THEN
      v_result := auth.admin_run_user_lifecycle_maintenance(coalesce((p_payload->>'limit')::integer,100));
    ELSE
      RAISE EXCEPTION 'accion no soportada: %', p_action;
  END CASE;
  RETURN coalesce(v_result, jsonb_build_object('action',p_action,'ok',true));
END;
$$;


