--
-- Name: rpc_safe_soft_delete(text, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_safe_soft_delete(p_target_table text, p_target_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_admin_id  uuid;
  v_log_id    uuid;
  v_log_hash  text;
  v_rows_upd  int;
  v_allowed   text[] := ARRAY['auth.users','auth.productos','app.disputes','app.content_moderation'];
BEGIN
  v_admin_id := app.jwt_user_id_safe();
  IF v_admin_id IS NULL OR app.jwt_role_safe() <> 'db_admin' THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;

  IF p_target_table <> ALL(v_allowed) THEN
    RAISE EXCEPTION 'Tabla no soportada para soft delete: %. Permitidas: %',
      p_target_table, array_to_string(v_allowed, ', ') USING ERRCODE = '22023';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 10 THEN
    RAISE EXCEPTION 'reason obligatorio (mínimo 10 caracteres)' USING ERRCODE = '22023';
  END IF;

  -- Ejecutar soft delete dinámico según tabla
  CASE p_target_table
    WHEN 'auth.users' THEN
      UPDATE auth.users SET fecha_eliminacion = now()
      WHERE id = p_target_id AND fecha_eliminacion IS NULL;
      GET DIAGNOSTICS v_rows_upd = ROW_COUNT;

    WHEN 'auth.productos' THEN
      UPDATE auth.productos SET fecha_eliminacion = now()
      WHERE id_producto = p_target_id AND fecha_eliminacion IS NULL;
      GET DIAGNOSTICS v_rows_upd = ROW_COUNT;

    WHEN 'app.disputes' THEN
      UPDATE app.disputes SET fecha_eliminacion = now()
      WHERE id_disputa = p_target_id AND fecha_eliminacion IS NULL;
      GET DIAGNOSTICS v_rows_upd = ROW_COUNT;

    WHEN 'app.content_moderation' THEN
      UPDATE app.content_moderation SET fecha_eliminacion = now()
      WHERE moderation_id = p_target_id AND fecha_eliminacion IS NULL;
      GET DIAGNOSTICS v_rows_upd = ROW_COUNT;
  END CASE;

  IF v_rows_upd = 0 THEN
    RAISE EXCEPTION 'Registro no encontrado o ya borrado: tabla=%, id=%',
      p_target_table, p_target_id USING ERRCODE = 'P0003';
  END IF;

  -- Registrar en WORM log (R-88)
  INSERT INTO app.soft_delete_log (target_table, id_objetivo, deleted_by, reason)
  VALUES (p_target_table, p_target_id, v_admin_id, p_reason)
  RETURNING delete_log_id, log_hash INTO v_log_id, v_log_hash;

  -- Registrar en admin_audit_log (R-56)
  INSERT INTO app.admin_audit_log
    (id_admin, tipo_accion, target_resource, id_recurso_objetivo, action_details)
  VALUES
    (v_admin_id, 'soft_delete', p_target_table, p_target_id,
     jsonb_build_object('reason', p_reason, 'log_id', v_log_id, 'log_hash', v_log_hash));

  -- Proyectar al ledger (R-88)
  PERFORM app.rpc_ledger_append_event(
    'soft_deleted', p_target_id, p_target_table,
    jsonb_build_object('deleted_by', v_admin_id, 'reason', p_reason, 'log_hash', v_log_hash));

  RETURN jsonb_build_object(
    'delete_log_id', v_log_id,
    'target_table',  p_target_table,
    'target_id',     p_target_id,
    'log_hash',      v_log_hash,
    'deleted_at',    now(),
    'timestamp_utc', now()
  );
END;
$$;


--
-- Name: rpc_v4_accept_coordinated_sale(uuid, date, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_v4_accept_coordinated_sale(p_order_id uuid, p_order_month date, p_region_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_id_vendedor uuid := app.current_request_user_id_safe();
  v_idem_key text := app.current_request_idempotency_key_safe();
  v_existing_response jsonb;
  v_session_context jsonb;
  v_remaining_capacity integer;
  v_sla_minutes integer;
  v_tier text;
  v_response_payload jsonb;
BEGIN
  -- 1. Guardia fail-closed de identidad
  IF v_id_vendedor IS NULL THEN
    RAISE EXCEPTION 'AUTH_UID_REQUERIDO' USING ERRCODE = 'P0002';
  END IF;

  -- 2. Interceptor de idempotencia
  SELECT response_payload INTO v_existing_response
  FROM app.idempotency_requests
  WHERE actor_user_id = v_id_vendedor
    AND operation_name = 'accept_sale'
    AND idempotency_key = v_idem_key;
  IF v_existing_response IS NOT NULL THEN RETURN v_existing_response; END IF;

  -- 3. Contexto de sesión del vendedor (capacidad + SLA)
  v_session_context := app.get_seller_sales_context_v2();
  v_remaining_capacity := (v_session_context->'rules'->>'remaining_capacity')::integer;
  v_sla_minutes := COALESCE((v_session_context->'rules'->>'response_sla_minutes')::integer, 60);

  -- 4. Guardia defensiva de capacidad (fail-closed)
  IF v_remaining_capacity IS NULL OR v_remaining_capacity <= 0 THEN
    RAISE EXCEPTION 'LIMITE_DE_CAPACIDAD_VENDEDOR_AGOTADO' USING ERRCODE = 'P0007';
  END IF;

  -- 5. Captura atómica dirigida a la sub-partición física
  --    WHERE id_vendedor IS NULL: exclusión mutua contra condiciones de carrera
  UPDATE auth.ordenes SET
    id_vendedor = v_id_vendedor,
    estado = 'assigned',
    expiracion_coordinacion_en = now() + (v_sla_minutes || ' minutes')::interval,
    fecha_actualizacion = now()
  WHERE id = p_order_id
    AND order_month = p_order_month
    AND region_code = p_region_code
    AND id_vendedor IS NULL
    AND estado = 'proposed';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'OPORTUNIDAD_ALCANZADA_O_EXPIRADA' USING ERRCODE = 'P0006';
  END IF;

  -- 6. Registro de idempotencia
  v_response_payload := jsonb_build_object(
    'order_id', p_order_id,
    'status', 'assigned',
    'sla_minutes', v_sla_minutes,
    'coordination_expires_at', now() + (v_sla_minutes || ' minutes')::interval,
    'timestamp', now()
  );

  INSERT INTO app.idempotency_requests (actor_user_id, operation_name, idempotency_key, response_payload)
  VALUES (v_id_vendedor, 'accept_sale', v_idem_key, v_response_payload);

  RETURN v_response_payload;
END;
$$;


