-- Name: rpc_v4_confirm_coordinated_purchase(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_v4_confirm_coordinated_purchase(p_order_id uuid, p_selected_seller_id uuid, p_region_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public'
    AS $$ BEGIN RETURN true; END; $$;


--
-- Name: rpc_v4_confirm_coordinated_purchase(uuid, uuid, text, public.geometry); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_v4_confirm_coordinated_purchase(p_order_id uuid, p_selected_id_vendedor uuid, p_region_code text, p_delivery_geom public.geometry) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_id_comprador uuid := app.current_request_user_id_safe();
  v_idem_key text := app.current_request_idempotency_key_safe();
  v_existing_response jsonb;
  v_buyer_geom geometry(Point, 4326);
  v_seller_geom geometry(Point, 4326);
  v_current_month date := date_trunc('month', now())::date;
  v_response_payload jsonb;
BEGIN
  -- 1. Guardia fail-closed de identidad
  IF v_id_comprador IS NULL THEN
    RAISE EXCEPTION 'AUTH_UID_REQUERIDO' USING ERRCODE = 'P0002';
  END IF;

  -- 2. Interceptor de idempotencia perimetral
  SELECT response_payload INTO v_existing_response
  FROM app.idempotency_requests
  WHERE actor_user_id = v_id_comprador
    AND operation_name = 'confirm_purchase'
    AND idempotency_key = v_idem_key;
  IF v_existing_response IS NOT NULL THEN RETURN v_existing_response; END IF;

  -- 3. Guardia de cupos por tier
  PERFORM app.assert_buyer_tier_constraints(v_id_comprador);

  -- 4. Resolución geoespacial PostGIS
  SELECT r_geom.geom INTO v_buyer_geom
  FROM app.resolve_buyer_location_v4(v_id_comprador) AS r_geom;
  IF v_buyer_geom IS NULL THEN
    RAISE EXCEPTION 'IMPOSIBLE_RESOLVER_COORDENADAS_DE_ENVIO_VALIDAS' USING ERRCODE = 'P0010';
  END IF;

  SELECT location INTO v_seller_geom
  FROM auth.productos
  WHERE id_vendedor = p_selected_id_vendedor AND is_active = true
  LIMIT 1;
  IF v_seller_geom IS NULL THEN
    RAISE EXCEPTION 'VENDEDOR_O_PRODUCTO_NO_DISPONIBLE_EN_ZONA' USING ERRCODE = 'P0011';
  END IF;

  -- 5. Mutación atómica sobre la sub-partición física de auth.ordenes
  UPDATE auth.ordenes SET
    id_vendedor = p_selected_id_vendedor,
    estado = 'proposed',
    fecha_actualizacion = now()
  WHERE id = p_order_id
    AND order_month = v_current_month
    AND region_code = p_region_code
    AND id_comprador = v_id_comprador;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TRANSACCION_CHECKOUT_INVALIDA_O_ORDEN_INEXISTENTE' USING ERRCODE = 'P0012';
  END IF;

  -- 6. Congelación del snapshot geográfico para BI territorial
  INSERT INTO public.order_geo_snapshots (
    id_orden, order_month, region_code, buyer_location, seller_location, delivery_location,
    delivery_zone_label, buyer_to_seller_meters, buyer_to_delivery_meters, seller_to_delivery_meters
  ) VALUES (
    p_order_id, v_current_month, p_region_code,
    v_buyer_geom, v_seller_geom, p_delivery_geom,
    'CUADRANTE_METRO_' || replace(p_region_code, '-', '_'),
    ST_Distance(v_buyer_geom::geography, v_seller_geom::geography),
    ST_Distance(v_buyer_geom::geography, p_delivery_geom::geography),
    ST_Distance(v_seller_geom::geography, p_delivery_geom::geography)
  );

  -- 7. Registro de idempotencia
  v_response_payload := jsonb_build_object(
    'order_id', p_order_id, 'order_month', v_current_month,
    'region_code', p_region_code, 'status', 'proposed', 'timestamp', now()
  );

  INSERT INTO app.idempotency_requests (actor_user_id, operation_name, idempotency_key, response_payload)
  VALUES (v_id_comprador, 'confirm_purchase', v_idem_key, v_response_payload);

  RETURN v_response_payload;
END;
$$;


--
-- Name: rpc_v4_dispatch_order(uuid, date, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_v4_dispatch_order(p_order_id uuid, p_order_month date, p_region_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_id_vendedor uuid := auth.jwt_user_id_safe();
  v_idem_key text := app.current_request_idempotency_key();
  v_existing_response jsonb;
  v_verification_pin text;
  v_encrypted_hash text;
  v_response_payload jsonb;
BEGIN
  -- R-30: Validación de identidad con auth.jwt_user_id_safe()
  IF v_id_vendedor IS NULL THEN 
    RAISE EXCEPTION 'AUTH_UID_REQUERIDO' USING ERRCODE = 'P0002'; 
  END IF;

  -- R-35: Guardia de idempotencia (retorno inmediato si existe)
  SELECT response_payload INTO v_existing_response 
  FROM app.idempotency_requests
  WHERE actor_user_id = v_id_vendedor 
    AND operation_name = 'dispatch_order' 
    AND idempotency_key = v_idem_key;

  IF v_existing_response IS NOT NULL THEN 
    RETURN v_existing_response; 
  END IF;

  -- Generar PIN criptográfico de 4 dígitos y hash Blowfish
  v_verification_pin := lpad(floor(random() * 10000)::text, 4, '0');
  v_encrypted_hash := crypt(v_verification_pin, gen_salt('bf', 8));

  -- R-37: Actualización dirigida a la sub-partición física
  UPDATE auth.ordenes
  SET estado = 'ready_for_delivery',
      vendedor_listo_en = now(),
      delivery_verification_hash = v_encrypted_hash
  WHERE id = p_order_id
    AND order_month = p_order_month
    AND region_code = p_region_code
    AND id_vendedor = v_id_vendedor;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDEN_LOGISTICA_NO_ENCONTRADA' USING ERRCODE = 'P0003';
  END IF;

  -- Construir respuesta con PIN plano (única vez)
  v_response_payload := jsonb_build_object(
    'order_id', p_order_id,
    'status', 'ready_for_delivery',
    'pin_plain', v_verification_pin,
    'seller_ready_at', now()
  );

  -- Persistir idempotencia
  INSERT INTO app.idempotency_requests (actor_user_id, operation_name, idempotency_key, response_payload)
  VALUES (v_id_vendedor, 'dispatch_order', v_idem_key, v_response_payload);

  RETURN v_response_payload;
END;
$$;


--
-- Name: rpc_v4_execute_express_purchase(uuid, uuid, text, numeric, public.geometry); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_v4_execute_express_purchase(p_product_id uuid, p_selected_id_vendedor uuid, p_region_code text, p_order_total numeric, p_delivery_geom public.geometry) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_id_comprador uuid := app.current_request_user_id_safe();
  v_idem_key text := app.current_request_idempotency_key_safe();
  v_existing_response jsonb;
  v_buyer_geom geometry(Point, 4326);
  v_seller_geom geometry(Point, 4326);
  v_order_id uuid := gen_random_uuid();
  v_current_month date := date_trunc('month', now())::date;
  v_response_payload jsonb;
BEGIN
  IF v_id_comprador IS NULL THEN RAISE EXCEPTION 'AUTH_UID_REQUERIDO' USING ERRCODE = 'P0002'; END IF;

  SELECT response_payload INTO v_existing_response FROM app.idempotency_requests
    WHERE actor_user_id = v_id_comprador AND operation_name = 'express_purchase' AND idempotency_key = v_idem_key;
  IF v_existing_response IS NOT NULL THEN RETURN v_existing_response; END IF;

  PERFORM app.assert_buyer_tier_constraints(v_id_comprador);

  IF NOT EXISTS (SELECT 1 FROM app.v_seller_operational_capacity_v4
                 WHERE id_vendedor = p_selected_id_vendedor AND is_eligible_for_matching = true) THEN
    RAISE EXCEPTION 'VENDEDOR_SATURADO_COMPRA_EXPRESS_RECHAZADA' USING ERRCODE = 'P0007';
  END IF;

  SELECT geom INTO v_buyer_geom FROM app.resolve_buyer_location_v4(v_id_comprador);
  SELECT location INTO v_seller_geom FROM auth.productos
    WHERE id = p_product_id AND id_vendedor = p_selected_id_vendedor AND is_active = true LIMIT 1;

  IF v_buyer_geom IS NULL OR v_seller_geom IS NULL THEN
    RAISE EXCEPTION 'ERROR_GEOESPACIAL_ELEMENTOS_FUERA_DE_COBERTURA' USING ERRCODE = 'P0011';
  END IF;

  INSERT INTO auth.ordenes (id, order_month, region_code, id_comprador, id_vendedor, id_producto,
    estado, total, unit_price_snapshot, fecha_creacion, fecha_actualizacion)
  VALUES (v_order_id, v_current_month, p_region_code, v_id_comprador, p_selected_id_vendedor, p_product_id,
    'payment_confirmed', p_order_total, p_order_total, now(), now());

  INSERT INTO public.order_geo_snapshots (id_orden, order_month, region_code, buyer_location, seller_location,
    delivery_location, delivery_zone_label, buyer_to_seller_meters, buyer_to_delivery_meters, seller_to_delivery_meters)
  VALUES (v_order_id, v_current_month, p_region_code, v_buyer_geom, v_seller_geom, p_delivery_geom,
    'CUADRANTE_EXPRESS_' || replace(p_region_code, '-', '_'),
    ST_Distance(v_buyer_geom::geography, v_seller_geom::geography),
    ST_Distance(v_buyer_geom::geography, p_delivery_geom::geography),
    ST_Distance(v_seller_geom::geography, p_delivery_geom::geography));

  v_response_payload := jsonb_build_object('order_id', v_order_id, 'order_month', v_current_month,
    'region_code', p_region_code, 'status', 'payment_confirmed', 'timestamp', now());

  INSERT INTO app.idempotency_requests (actor_user_id, operation_name, idempotency_key, response_payload)
  VALUES (v_id_comprador, 'express_purchase', v_idem_key, v_response_payload);

  RETURN v_response_payload;
END;
$$;


--
-- Name: rpc_v4_finalize_delivery(uuid, date, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_v4_finalize_delivery(p_order_id uuid, p_order_month date, p_region_code text, p_input_pin text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_id_comprador uuid := auth.jwt_user_id_safe();
  v_idem_key text := app.current_request_idempotency_key();
  v_existing_response jsonb;
  v_stored_hash text;
  v_id_vendedor uuid;
  v_order_total numeric(12,2);
  v_points_to_credit numeric(12,2);
  v_response_payload jsonb;
BEGIN
  -- R-30: Validación de identidad
  IF v_id_comprador IS NULL THEN 
    RAISE EXCEPTION 'AUTH_UID_REQUERIDO' USING ERRCODE = 'P0002'; 
  END IF;

  -- R-35: Guardia de idempotencia
  SELECT response_payload INTO v_existing_response 
  FROM app.idempotency_requests
  WHERE actor_user_id = v_id_comprador 
    AND operation_name = 'finalize_delivery' 
    AND idempotency_key = v_idem_key;

  IF v_existing_response IS NOT NULL THEN 
    RETURN v_existing_response; 
  END IF;

  -- R-37: Bloqueo pesimista en sub-partición física
  SELECT delivery_verification_hash, id_vendedor, total
  INTO v_stored_hash, v_id_vendedor, v_order_total
  FROM auth.ordenes
  WHERE id = p_order_id 
    AND order_month = p_order_month 
    AND region_code = p_region_code 
    AND id_comprador = v_id_comprador
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDEN_NO_ENCONTRADA_O_ACCESO_DENEGADO' USING ERRCODE = 'P0003';
  END IF;

  -- Verificación criptográfica del PIN (no-repudio)
  IF v_stored_hash IS NULL OR v_stored_hash <> crypt(p_input_pin, v_stored_hash) THEN
    RAISE EXCEPTION 'AUTENTICACION_DE_ENTREGA_FALLIDA' USING ERRCODE = 'P0005';
  END IF;

  -- Transición al estado terminal (inmutable)
  UPDATE auth.ordenes 
  SET estado = 'completed', 
      fecha_confirmacion = now() 
  WHERE id = p_order_id 
    AND order_month = p_order_month 
    AND region_code = p_region_code;

  -- Calcular puntos de lealtad (10% del total)
  v_points_to_credit := (v_order_total * 0.10)::numeric(12,2);

  -- Insertar en ledger (R-37: FK compuesta)
  INSERT INTO public.order_reward_ledger (
    id_orden, order_month, region_code, 
    id_comprador, id_vendedor, points_credited
  )
  VALUES (
    p_order_id, p_order_month, p_region_code, 
    v_id_comprador, v_id_vendedor, v_points_to_credit
  );

  -- Construir respuesta
  v_response_payload := jsonb_build_object(
    'order_id', p_order_id,
    'status', 'completed',
    'points_credited', v_points_to_credit,
    'closed_at', now()
  );

  -- Persistir idempotencia
  INSERT INTO app.idempotency_requests (
    actor_user_id, operation_name, idempotency_key, response_payload
  )
  VALUES (
    v_id_comprador, 'finalize_delivery', v_idem_key, v_response_payload
  );

  -- NOTA: El trigger trg_sync_age_completion proyectará hacia Apache AGE

  RETURN v_response_payload;
END;
$$;


--
-- Name: rpc_v4_initialize_session_context(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_v4_initialize_session_context() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := app.current_request_user_id_safe();
  v_role text := app.current_request_role_safe();
  v_tier text := COALESCE(app.current_request_profile_tier_safe(), 'bronze');
  v_geom geometry(Point, 4326);
  v_source text;
  v_max_amount numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_UID_REQUIRED' USING ERRCODE = '28000';
  END IF;

  SELECT source, geom INTO v_source, v_geom FROM app.resolve_buyer_location_v4(v_user_id);

  IF v_geom IS NULL THEN
    RETURN jsonb_build_object('status', 'LOCATION_REQUIRED', 'id_usuario', v_user_id, 'tier', v_tier);
  END IF;

  v_max_amount := public.get_tier_rule_numeric(v_tier, 'buyer', 'max_order_amount');

  RETURN jsonb_build_object(
    'status', 'CONTEXT_INITIALIZED',
    'id_usuario', v_user_id,
    'role', v_role,
    'tier', v_tier,
    'location', jsonb_build_object('source', v_source, 'coordinates', array[ST_X(v_geom), ST_Y(v_geom)]),
    'max_order_amount_allowed', v_max_amount
  );
END;
$$;


--
-- Name: rpc_v4_manage_cart_item(uuid, integer, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_v4_manage_cart_item(p_product_id uuid, p_quantity integer, p_add_to_favorites boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_id_comprador uuid := app.current_request_user_id_safe();
  v_tier text := COALESCE(app.current_request_profile_tier_safe(), 'bronze');
  v_item_price numeric;
  v_current_total numeric;
  v_max_amount numeric;
  v_points integer;
BEGIN
  IF v_id_comprador IS NULL THEN RAISE EXCEPTION 'AUTH_UID_REQUERIDO' USING ERRCODE = 'P0002'; END IF;

  SELECT price INTO v_item_price FROM auth.productos WHERE id = p_product_id AND is_active = true;
  IF v_item_price IS NULL THEN RAISE EXCEPTION 'PRODUCT_NOT_AVAILABLE'; END IF;

  IF p_add_to_favorites THEN
    INSERT INTO public.user_favorites (id_usuario, id_producto) VALUES (v_id_comprador, p_product_id) ON CONFLICT DO NOTHING;
  END IF;

  -- H4 CORREGIDO: fail-closed — si no hay regla, se asume límite 0 (bloquea) en vez de bypass silencioso
  v_max_amount := COALESCE(public.get_tier_rule_numeric(v_tier, 'buyer', 'max_order_amount'), 0);

  SELECT COALESCE(SUM(quantity * unit_price_snapshot), 0) INTO v_current_total
  FROM public.cart_items WHERE id_comprador = v_id_comprador AND id_producto <> p_product_id;
  v_current_total := v_current_total + (p_quantity * v_item_price);

  IF v_current_total > v_max_amount THEN
    RAISE EXCEPTION 'EXCEEDS_TIER_MAX_AMOUNT: Limite %', v_max_amount USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.cart_items (id_comprador, id_producto, quantity, unit_price_snapshot)
  VALUES (v_id_comprador, p_product_id, p_quantity, v_item_price)
  ON CONFLICT (id_comprador, id_producto) DO UPDATE SET
    quantity = p_quantity, unit_price_snapshot = v_item_price, fecha_actualizacion = now();

  v_points := floor((p_quantity * v_item_price) * 0.10);

  RETURN jsonb_build_object(
    'status', 'CART_UPDATED', 'product_id', p_product_id, 'quantity', p_quantity,
    'projected_total', v_current_total, 'points_earned', v_points
  );
END;
$$;


--
-- Name: rpc_v4_rank_buyer_opportunities_for_seller(date, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_v4_rank_buyer_opportunities_for_seller(p_order_month date, p_region_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public'
    AS $$ BEGIN RETURN '[]'::jsonb; END; $$;


--
-- Name: rpc_v4_rank_buyer_opportunities_for_seller(public.geometry, date, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_v4_rank_buyer_opportunities_for_seller(p_reference_geom public.geometry, p_order_month date, p_region_code text) RETURNS TABLE(id_orden uuid, final_score numeric, distance_meters numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
  SELECT
    o.id AS id_orden,
    ((10000 - ST_Distance(gs.buyer_location::geography, p_reference_geom::geography)) +
     (COALESCE((cap.remaining_capacity), 0) * 100))::numeric AS final_score,
    ST_Distance(gs.buyer_location::geography, p_reference_geom::geography) AS distance_meters
  FROM auth.ordenes o
  INNER JOIN public.order_geo_snapshots gs
    ON o.id = gs.id_orden AND o.order_month = gs.order_month AND o.region_code = gs.region_code
  INNER JOIN app.v_seller_operational_capacity_v4 cap
    ON cap.id_vendedor = app.current_request_user_id_safe()
  WHERE o.order_month = p_order_month
    AND o.region_code = p_region_code
    AND o.estado = 'proposed'
    AND o.id_vendedor IS NULL
    AND cap.is_eligible_for_matching = true
  ORDER BY final_score DESC;
$$;


--
-- Name: rpc_v4_rank_seller_candidates_for_buyer(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_v4_rank_seller_candidates_for_buyer(p_region_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public'
    AS $$ BEGIN RETURN '[]'::jsonb; END; $$;


--
-- Name: rpc_v4_rank_seller_candidates_for_buyer(public.geometry); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_v4_rank_seller_candidates_for_buyer(p_reference_geom public.geometry) RETURNS TABLE(id_vendedor uuid, final_score numeric, distance_meters numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
  SELECT
    p.id_vendedor,
    (GREATEST(0, 50000 - ST_Distance(p.location::geography, p_reference_geom::geography)) +
     (COALESCE((SELECT numeric_value FROM public.commercial_tier_rule_values
                WHERE actor_role = 'seller' AND rule_code = 'priority_score_boost'
                  AND tier_code = public.get_active_actor_tier(p.id_vendedor, 'seller')), 0) * 100))::numeric AS final_score,
    ST_Distance(p.location::geography, p_reference_geom::geography) AS distance_meters
  FROM auth.productos p
  INNER JOIN app.v_seller_operational_capacity_v4 cap ON p.id_vendedor = cap.id_vendedor
  WHERE p.is_active = true AND cap.is_eligible_for_matching = true
  ORDER BY final_score DESC;
$$;


--
-- Name: rpc_v4_verify_system_consistency(uuid, date, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rpc_v4_verify_system_consistency(p_order_id uuid, p_month date DEFAULT NULL::date, p_region text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller  uuid    := auth.current_jwt_user_id();
  v_admin   boolean := false;
  v_order   record;
  v_checks  jsonb   := '[]'::jsonb;
  v_ok      boolean;
  v_compro  integer := 0;
BEGIN
  BEGIN
    v_admin := auth.is_db_admin();
  EXCEPTION WHEN OTHERS THEN
    v_admin := false;
  END;
  IF NOT v_admin AND v_caller IS NULL THEN
    RAISE EXCEPTION 'operacion_no_autorizada' USING ERRCODE = '42501';
  END IF;
  IF p_order_id IS NULL THEN
    RAISE EXCEPTION 'order_id_requerido' USING ERRCODE = '22004';
  END IF;

  SELECT * INTO v_order
    FROM auth.ordenes
   WHERE id = p_order_id
     AND (p_month IS NULL OR order_month = p_month)
     AND (p_region IS NULL OR region_code = p_region)
     AND fecha_eliminacion IS NULL;

  v_checks := v_checks || jsonb_build_object(
    'check', 'orden_existe_v4', 'ok', FOUND,
    'detail', jsonb_build_object('order_id', p_order_id, 'month', p_month, 'region', p_region));

  IF NOT FOUND THEN
    RETURN jsonb_build_object('consistent', false, 'checks', v_checks);
  END IF;

  v_ok := COALESCE(v_order.total, 0) > 0;
  v_checks := v_checks || jsonb_build_object(
    'check', 'total_positivo', 'ok', v_ok,
    'detail', jsonb_build_object('total', v_order.total));

  v_ok := v_order.id_comprador IS NOT NULL
          AND v_order.id_vendedor IS NOT NULL
          AND v_order.id_comprador <> v_order.id_vendedor;
  v_checks := v_checks || jsonb_build_object(
    'check', 'buyer_seller_distintos', 'ok', v_ok,
    'detail', jsonb_build_object('buyer', v_order.id_comprador, 'seller', v_order.id_vendedor));

  SELECT (EXISTS (SELECT 1 FROM auth.users u
                   WHERE u.id = v_order.id_comprador
                     AND COALESCE(u.activo, true) AND u.fecha_eliminacion IS NULL)
       AND EXISTS (SELECT 1 FROM auth.users u
                    WHERE u.id = v_order.id_vendedor
                      AND COALESCE(u.activo, true) AND u.fecha_eliminacion IS NULL))
    INTO v_ok;
  v_checks := v_checks || jsonb_build_object(
    'check', 'participantes_activos', 'ok', v_ok, 'detail', 'buyer y seller activos');

  -- Arista COMPRO en smtp_posix_graph (buyer -> seller)
  BEGIN
    LOAD 'age';
    SET LOCAL search_path = ag_catalog, public, pg_temp;
    SELECT count(*) INTO v_compro
      FROM smtp_posix_graph."COMPRO" e
      JOIN smtp_posix_graph."User" b ON b.id = e.start_id
      JOIN smtp_posix_graph."User" v ON v.id = e.end_id
     WHERE agtype_to_json(b.properties)->>'user_uuid' = v_order.id_comprador::text
       AND agtype_to_json(v.properties)->>'user_uuid' = v_order.id_vendedor::text;
  EXCEPTION WHEN OTHERS THEN
    v_compro := 0;
  END;
  v_checks := v_checks || jsonb_build_object(
    'check', 'compro_edge_en_grafo', 'ok', (v_compro > 0),
    'detail', jsonb_build_object('compro_edges', v_compro));

  SELECT EXISTS (SELECT 1 FROM public.order_geo_evidence WHERE id_orden = p_order_id)
    INTO v_ok;
  v_checks := v_checks || jsonb_build_object(
    'check', 'evidencia_geo', 'ok', v_ok, 'detail', 'public.order_geo_evidence');

  RETURN jsonb_build_object(
    'consistent', (SELECT bool_and((c->>'ok')::boolean) FROM jsonb_array_elements(v_checks) c),
    'checks', v_checks);
END;
$$;


--
-- Name: tg_categoria_soft_delete_defaults(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.tg_categoria_soft_delete_defaults() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        NEW.fecha_actualizacion := now();
        -- Sincroniza activo ↔ fecha_eliminacion
        IF NEW.activo = false AND NEW.fecha_eliminacion IS NULL THEN
            NEW.fecha_eliminacion := now();
        ELSIF NEW.activo = true AND NEW.fecha_eliminacion IS NOT NULL THEN
            NEW.fecha_eliminacion := NULL;
            NEW.deleted_by := NULL;
            NEW.deletion_reason := NULL;
        END IF;
    END IF;
    RETURN NEW;
END; $$;


--
-- Name: tg_categorias_audit_age(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.tg_categorias_audit_age() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'auth', 'public', 'ag_catalog'
    AS $_$
DECLARE
    v_actor  uuid := app.jwt_user_id_safe();
    v_tipo   text;
    v_snap   jsonb;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_tipo := 'CREADA';
        v_snap := to_jsonb(NEW);
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.activo = true AND NEW.activo = false THEN
            v_tipo := 'BAJA_LOGICA';
        ELSIF OLD.activo = false AND NEW.activo = true THEN
            v_tipo := 'RESTAURADA';
        ELSE
            v_tipo := 'EDITADA';
        END IF;
        v_snap := jsonb_build_object('old', to_jsonb(OLD), 'new', to_jsonb(NEW));
    END IF;

    INSERT INTO app.h_categorias_audit
        (id_categoria, id_actor, tipo_cambio, snapshot, hash_evento)
    VALUES (
        NEW.id, v_actor, v_tipo, v_snap,
        encode(digest(v_snap::text || v_tipo || COALESCE(v_actor::text,''), 'sha256'), 'hex')
    );

    -- Sync AGE con degradación elegante (R-58)
    BEGIN
        LOAD 'age';
        PERFORM * FROM cypher('kambalache_marketplace_graph', $c$
            MERGE (c:Categoria {id_sql: $cid})
              SET c.activo = $act, c.nombre = $nom
            $c$, jsonb_build_object(
                'cid', NEW.id::text,
                'act', NEW.activo,
                'nom', COALESCE(NEW.nombre,'')
            )) AS (v agtype);
        IF v_actor IS NOT NULL AND v_tipo <> 'CREADA' THEN
            PERFORM * FROM cypher('kambalache_marketplace_graph', $c$
                MATCH (u:Usuario {id_sql: $uid}), (c:Categoria {id_sql: $cid})
                CREATE (u)-[:EDITO_CATEGORIA {tipo: $t, ts: $ts}]->(c)
                $c$, jsonb_build_object(
                    'uid', v_actor::text,
                    'cid', NEW.id::text,
                    't',   v_tipo,
                    'ts',  to_char(now(),'YYYY-MM-DD"T"HH24:MI:SS"Z"')
                )) AS (v agtype);
        END IF;
    EXCEPTION WHEN OTHERS THEN
        -- Degradación elegante: SQL sigue siendo canónico
        NULL;
    END;

    RETURN NEW;
END; $_$;


