-- Name: tg_validar_categoria_activa_producto(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.tg_validar_categoria_activa_producto() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.id_categoria IS NOT NULL
       AND NOT app.categoria_esta_activa(NEW.id_categoria) THEN
        RAISE EXCEPTION 'Categoría % inactiva o eliminada — producto rechazado', NEW.id_categoria
            USING ERRCODE = '23514';
    END IF;
