END; $$;


--
-- Name: trg_content_flag_to_work_queue(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.trg_content_flag_to_work_queue() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO app.work_items
    (tipo_item, ref_table, ref_id, priority, estado, title, vencimiento_sla_en)
  VALUES
    ('content_flag', 'app.content_moderation', NEW.moderation_id,
     'normal', 'open',
     'Contenido Flaggeado: ' || NEW.content_type || ' por ' || COALESCE(NEW.flagged_reason,'—'),
     now() + interval '48 hours')
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: trg_dispute_to_work_queue(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.trg_dispute_to_work_queue() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_priority text;
  v_sla_offset interval;
BEGIN
  v_priority := CASE NEW.severity
    WHEN 'critical' THEN 'critical'
    WHEN 'high'     THEN 'high'
    ELSE 'normal'
  END;
  v_sla_offset := CASE v_priority
    WHEN 'critical' THEN interval '2 hours'
    WHEN 'high'     THEN interval '8 hours'
    ELSE                 interval '24 hours'
  END;

  INSERT INTO app.work_items
    (tipo_item, ref_table, ref_id, priority, estado, title, summary, vencimiento_sla_en)
  VALUES
    ('dispute', 'app.disputes', NEW.id_disputa, v_priority, 'open',
     'Disputa: ' || NEW.dispute_reason || ' (' || NEW.severity || ')',
     'Iniciada por ' || NEW.initiator_role || ' — orden ' || NEW.id_orden,
     now() + v_sla_offset)
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: trg_fraud_score_to_work_queue(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.trg_fraud_score_to_work_queue() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.score_value >= 0.7 AND NEW.estado_flag IN ('warning','suspended') THEN
    INSERT INTO app.work_items
      (tipo_item, ref_table, ref_id, priority, estado, title, vencimiento_sla_en)
    VALUES
      ('fraud_alert', 'app.fraud_scores', NEW.id,
       CASE WHEN NEW.score_value >= 0.9 THEN 'critical' ELSE 'high' END,
       'open',
       'Alerta Fraude: usuario ' || NEW.id_usuario || ' — score ' || NEW.score_value,
       now() + interval '4 hours')
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_v4_audit_geo_snapshot(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.trg_v4_audit_geo_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO audit.logged_changes(
    table_schema, table_name, operation, record_pk,
    actor_user_id, actor_role, old_data, new_data
  ) VALUES (
    TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP,
    jsonb_build_object('id_orden', COALESCE((to_jsonb(OLD)->>'id_orden'), (to_jsonb(NEW)->>'id_orden'))),
    app.current_request_user_id_safe(),
    app.current_request_role_safe(),
    CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) ELSE NULL END
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;


