    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'pg_catalog'
    AS $$
BEGIN
  PERFORM app.assert_buyer_tier_constraints(NEW.id_comprador);
  RETURN NEW;
END;
