--
-- Name: trg_v4_enforce_seller_tier_on_assign(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.trg_v4_enforce_seller_tier_on_assign() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'pg_catalog'
    AS $$
BEGIN
  IF (OLD.id_vendedor IS NULL AND NEW.id_vendedor IS NOT NULL)
     OR (NEW.estado = 'assigned' AND OLD.estado <> 'assigned') THEN
    PERFORM app.assert_seller_tier_constraints(NEW.id_vendedor);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_v4_immutable_order_fields(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.trg_v4_immutable_order_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.id_comprador IS DISTINCT FROM OLD.id_comprador THEN
    RAISE EXCEPTION 'IMMUTABLE_FIELD: id_comprador' USING ERRCODE = 'P0013';
  END IF;
  IF NEW.fecha_creacion IS DISTINCT FROM OLD.fecha_creacion THEN
    RAISE EXCEPTION 'IMMUTABLE_FIELD: created_at' USING ERRCODE = 'P0014';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'IMMUTABLE_FIELD: id' USING ERRCODE = 'P0014';
  END IF;
  IF NEW.order_month IS DISTINCT FROM OLD.order_month OR NEW.region_code IS DISTINCT FROM OLD.region_code THEN
    RAISE EXCEPTION 'IMMUTABLE_FIELD: partition keys' USING ERRCODE = 'P0015';
  END IF;
  IF OLD.id_vendedor IS NOT NULL AND NEW.id_vendedor IS DISTINCT FROM OLD.id_vendedor THEN
    RAISE EXCEPTION 'IMMUTABLE_FIELD: id_vendedor ya asignado' USING ERRCODE = 'P0014';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_v4_maintain_current_location(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.trg_v4_maintain_current_location() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.is_active = true THEN
    UPDATE public.user_location_snapshots
    SET is_active = false, fecha_actualizacion = now()
    WHERE id_usuario = NEW.id_usuario AND id <> NEW.id AND is_active = true;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_v4_sync_age_on_assign(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.trg_v4_sync_age_on_assign() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'pg_catalog'
    AS $_$
BEGIN
  IF NEW.estado = 'assigned' AND OLD.estado <> 'assigned'
     AND NEW.id_vendedor IS NOT NULL THEN
    PERFORM ag_catalog.cypher('smtp_posix_graph', $cypher$
      MERGE (s:Seller {id_usuario: $id_vendedor})
      MERGE (o:Order {id_orden: $id_orden})
      MERGE (s)-[:FULFILLS {assigned_at: $ts}]->(o)
    $cypher$, jsonb_build_object(
      'id_vendedor', NEW.id_vendedor::text,
      'id_orden', NEW.id::text,
      'ts', now()::text
    ));
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[AGE_SYNC_FAILED] order=% seller=%: %', NEW.id, NEW.id_vendedor, SQLERRM;
  RETURN NEW;
END;
$_$;


--
-- Name: trg_v4_sync_age_on_delivery(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.trg_v4_sync_age_on_delivery() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'pg_catalog'
    AS $_$
BEGIN
  IF NEW.estado = 'completed' AND OLD.estado <> 'completed' AND NEW.id_vendedor IS NOT NULL THEN
    PERFORM ag_catalog.cypher('smtp_posix_graph', $cypher$
      MERGE (s:Seller {id_usuario: $id_vendedor})
      MERGE (z:Zone {geohash: $geohash})
      MERGE (s)-[:SUPPLIES_IN {completed_at: $ts, id_orden: $id_orden}]->(z)
    $cypher$, jsonb_build_object(
      'id_vendedor', NEW.id_vendedor::text,
      'geohash', ST_GeoHash((SELECT delivery_location FROM public.order_geo_snapshots
                              WHERE id_orden = NEW.id LIMIT 1)::geometry, 6),
      'ts', now()::text,
      'id_orden', NEW.id::text
    ));
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[AGE_SYNC_FAILED] delivery order=%: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$_$;


--
-- Name: trg_v4_validate_order_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.trg_v4_validate_order_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'pg_temp'
    AS $$
DECLARE
  v_allowed boolean;
  v_actor text;
BEGIN
  IF NEW.estado IS NOT DISTINCT FROM OLD.estado THEN RETURN NEW; END IF;
  v_actor := COALESCE(app.current_request_role_safe(), 'system');
  SELECT is_allowed INTO v_allowed
  FROM public.transiciones_estado_orden
  WHERE from_status = OLD.estado AND to_status = NEW.estado AND actor_scope = v_actor
  LIMIT 1;
  IF COALESCE(v_allowed, false) = false THEN
    SELECT is_allowed INTO v_allowed
    FROM public.transiciones_estado_orden
    WHERE from_status = OLD.estado AND to_status = NEW.estado AND actor_scope = 'system'
    LIMIT 1;
  END IF;
  IF COALESCE(v_allowed, false) = false THEN
    RAISE EXCEPTION 'FORBIDDEN_TRANSITION: % -> % para actor %', OLD.estado, NEW.estado, v_actor
      USING ERRCODE = 'P0016';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_v4_validate_seller_exists(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.trg_v4_validate_seller_exists() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.id_vendedor IS NOT NULL AND OLD.id_vendedor IS NULL THEN
    -- Verificamos en products que el seller tenga al menos un producto activo
    IF NOT EXISTS (
      SELECT 1 FROM auth.productos
      WHERE id_vendedor = NEW.id_vendedor AND is_active = true
    ) THEN
      RAISE EXCEPTION 'SELLER_NOT_FOUND_OR_INACTIVE: %', NEW.id_vendedor USING ERRCODE = 'P0009';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: upsert_buyer_location_snapshot(uuid, text, double precision, double precision, numeric, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.upsert_buyer_location_snapshot(p_user_id uuid, p_source text, p_latitude double precision, p_longitude double precision, p_accuracy_meters numeric DEFAULT NULL::numeric, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF p_user_id <> app.current_request_user_id_safe()
     AND NOT app.current_request_is_admin_safe() THEN
    RAISE EXCEPTION 'ACTOR_MISMATCH' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.user_location_snapshots (id_usuario, source_type, location, is_active, fecha_captura)
  VALUES (p_user_id, p_source, ST_SetSRID(ST_MakePoint(p_longitude, p_latitude), 4326), true, now())
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: log_row_change(); Type: FUNCTION; Schema: audit; Owner: -
--

CREATE FUNCTION audit.log_row_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'audit', 'pg_temp'
    AS $$
DECLARE
  v_pk_json jsonb;
BEGIN
  IF (TG_TABLE_NAME = 'orders' OR TG_TABLE_NAME = 'order_geo_snapshots') THEN
    v_pk_json := jsonb_build_object(
      'id', COALESCE((to_jsonb(OLD)->>'id'), (to_jsonb(NEW)->>'id')),
      'order_month', COALESCE((to_jsonb(OLD)->>'order_month'), (to_jsonb(NEW)->>'order_month')),
      'region_code', COALESCE((to_jsonb(OLD)->>'region_code'), (to_jsonb(NEW)->>'region_code'))
    );
  ELSE
    v_pk_json := jsonb_build_object('id', COALESCE((to_jsonb(OLD)->>'id'), (to_jsonb(NEW)->>'id')));
  END IF;

  INSERT INTO audit.logged_changes (
    table_schema, table_name, operation, record_pk, actor_user_id, actor_role, old_data, new_data
  ) VALUES (
    TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP, v_pk_json,
    app.current_request_user_id_safe(), app.current_request_role_safe(),
    CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) ELSE NULL END
  );

  IF (TG_OP = 'DELETE') THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$$;


--
-- Name: _reserve_for_order_internal(uuid, uuid, uuid, integer, uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth._reserve_for_order_internal(p_orden_id uuid, p_producto_id uuid, p_ubicacion_id uuid, p_cantidad integer, p_actor uuid, p_role text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_order        record;
    v_stock_antes  integer;
BEGIN
    IF p_cantidad <= 0 THEN
        RAISE EXCEPTION 'Cantidad de reserva debe ser positiva [RN-023]';
    END IF;

    IF p_role NOT IN ('seller', 'buyer', 'db_admin', 'system') THEN
        RAISE EXCEPTION 'Rol de actor inválido para reserva: % [RN-025]', p_role;
    END IF;

    -- RN-024: Orden debe existir
    SELECT id, id_comprador, id_vendedor, estado INTO v_order
    FROM auth.ordenes WHERE id = p_orden_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden inexistente [RN-024]';
    END IF;

    -- Lock y verificar stock
    SELECT stock_disponible INTO v_stock_antes
    FROM auth.inventario_ubicacion
    WHERE id_producto = p_producto_id
      AND id_ubicacion = p_ubicacion_id
      AND id_vendedor = v_order.id_vendedor
    FOR UPDATE;

    -- RN-026: Stock disponible suficiente (o backorder permitido)
    IF COALESCE(v_stock_antes, 0) < p_cantidad THEN
        IF NOT EXISTS (
            SELECT 1 FROM auth.inventario_producto
            WHERE id_producto = p_producto_id AND permite_backorder = true
        ) THEN
            RAISE EXCEPTION 'Stock disponible insuficiente para reserva (disponible: %, solicitado: %) [RN-026]',
                COALESCE(v_stock_antes, 0), p_cantidad;
        END IF;
    END IF;

    UPDATE auth.inventario_ubicacion
    SET stock_reservado = stock_reservado + p_cantidad, fecha_modificacion = now()
    WHERE id_producto = p_producto_id AND id_ubicacion = p_ubicacion_id;

    -- INSERT con la columna NOT NULL real: id_producto (verificado en
    -- .11 vía information_schema; NO existe producto_id).
    INSERT INTO auth.movimientos_inventario(
        id_producto, id_vendedor, id_ubicacion,
        tipo_movimiento, cantidad, referencia_tipo, referencia_id,
        motivo, actor_user_id, actor_role, metadata
    )
    VALUES (
        p_producto_id, v_order.id_vendedor, p_ubicacion_id,
        'reserva', p_cantidad, 'orden', p_orden_id,
        'reserva automática por orden', p_actor, p_role,
        jsonb_build_object(
            'origen',       'reserva_orden',
            'orden_id',     p_orden_id,
            'ubicacion_id', p_ubicacion_id
        )
    );

    PERFORM auth.fn_recalc_inventory_product(p_producto_id);

    RETURN jsonb_build_object(
        'ok', true,
        'orden_id', p_orden_id,
        'producto_id', p_producto_id,
        'cantidad_reservada', p_cantidad
    );
END;
$$;


--
-- Name: FUNCTION _reserve_for_order_internal(p_orden_id uuid, p_producto_id uuid, p_ubicacion_id uuid, p_cantidad integer, p_actor uuid, p_role text); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth._reserve_for_order_internal(p_orden_id uuid, p_producto_id uuid, p_ubicacion_id uuid, p_cantidad integer, p_actor uuid, p_role text) IS 'Reserva real de inventario por orden con actor/role explícitos. Uso interno (REVOKE PUBLIC): la llaman inventory_reserve_for_order (tras RN-025) y fn_trg_auto_reserve_on_order_confirm (role=system). Inserta movimiento en producto_id (NOT NULL real) + id_producto (legacy).';


