--

CREATE FUNCTION auth.abrir_disputa(p_intercambio_id uuid, p_tipo_disputa text, p_descripcion text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
