    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    -- Delega en responder_intercambio que ya tiene toda la lógica
    -- de autorización y validación de estado
    RETURN auth.responder_intercambio(
        p_intercambio_id := p_intercambio_id,
        p_decision       := 'aceptar'
    );
END;
$$;


--
-- Name: actualizar_estado_envio(uuid, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.actualizar_estado_envio(p_orden_id uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_role TEXT;
    v_uid UUID;
    v_orden auth.ordenes%ROWTYPE;
    v_envio_id UUID;
    v_estado TEXT;
    v_codigo TEXT;
    v_transportista TEXT;
    v_direccion JSONB;
    v_observaciones TEXT;
    v_uc_id INTEGER;
    v_user_node BIGINT;
    v_uc_node BIGINT;
BEGIN
    v_role := auth.current_jwt_role();
    v_uid := auth.current_jwt_user_id();

    SELECT * INTO v_orden
    FROM auth.ordenes
    WHERE id = p_orden_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden no encontrada: %', p_orden_id;
    END IF;

    IF v_role = 'seller' THEN
        IF v_uid IS NULL OR v_orden.id_vendedor <> v_uid THEN
            RAISE EXCEPTION 'Permiso denegado para actualizar envio de la orden';
        END IF;
    ELSIF v_role = 'db_admin' THEN
        NULL;
    ELSIF current_user = 'postgres' THEN
        NULL;
    ELSE
        RAISE EXCEPTION 'Permiso denegado: role=%', COALESCE(v_role, 'null');
    END IF;

    IF v_orden.estado = 'cancelada' THEN
        RAISE EXCEPTION 'No se puede actualizar envio para una orden cancelada';
    END IF;

    v_estado := CASE COALESCE(NULLIF(lower(trim(p_payload->>'estado')), ''), 'pendiente_preparacion')
        WHEN 'pendiente_preparacion' THEN 'pendiente_preparacion'
        WHEN 'preparando' THEN 'preparando'
        WHEN 'en_camino' THEN 'en_camino'
        WHEN 'entregado' THEN 'entregado'
        WHEN 'incidencia' THEN 'incidencia'
        WHEN 'cancelado' THEN 'cancelado'
        ELSE 'pendiente_preparacion'
    END;

    v_codigo := NULLIF(trim(COALESCE(p_payload->>'codigo_seguimiento', '')), '');
    v_transportista := COALESCE(NULLIF(trim(COALESCE(p_payload->>'transportista', '')), ''), 'interno');
    v_observaciones := NULLIF(trim(COALESCE(p_payload->>'observaciones', '')), '');
    v_direccion := CASE
        WHEN p_payload ? 'direccion_entrega' AND jsonb_typeof(p_payload->'direccion_entrega') = 'object'
            THEN p_payload->'direccion_entrega'
        WHEN jsonb_typeof(COALESCE(v_orden.metadata->'direccion_entrega', '{}'::JSONB)) = 'object'
            THEN COALESCE(v_orden.metadata->'direccion_entrega', '{}'::JSONB)
        ELSE '{}'::JSONB
    END;

    SELECT id INTO v_envio_id
    FROM auth.envios
    WHERE id_orden = p_orden_id;

    IF v_envio_id IS NULL THEN
        INSERT INTO auth.envios (
            id_orden,
            id_comprador,
            id_vendedor,
            estado,
            codigo_seguimiento,
            transportista,
            direccion_entrega,
            metadata,
            fecha_envio,
            fecha_entrega
        ) VALUES (
            v_orden.id,
            v_orden.id_comprador,
            v_orden.id_vendedor,
            v_estado,
            v_codigo,
            v_transportista,
            v_direccion,
            jsonb_build_object('observaciones', v_observaciones, 'last_update_at', now()),
            CASE WHEN v_estado IN ('en_camino', 'entregado') THEN now() ELSE NULL END,
            CASE WHEN v_estado = 'entregado' THEN now() ELSE NULL END
        ) RETURNING id INTO v_envio_id;
    ELSE
        UPDATE auth.envios
        SET estado = v_estado,
            codigo_seguimiento = COALESCE(v_codigo, codigo_seguimiento),
            transportista = v_transportista,
            direccion_entrega = CASE
                WHEN v_direccion = '{}'::JSONB THEN direccion_entrega
                ELSE v_direccion
            END,
            metadata = metadata || jsonb_build_object('observaciones', v_observaciones, 'last_update_at', now()),
            fecha_envio = CASE
                WHEN v_estado IN ('en_camino', 'entregado') THEN COALESCE(fecha_envio, now())
                ELSE fecha_envio
            END,
            fecha_entrega = CASE
                WHEN v_estado = 'entregado' THEN COALESCE(fecha_entrega, now())
                ELSE fecha_entrega
            END
        WHERE id = v_envio_id;
    END IF;

    INSERT INTO auth.envio_eventos (id_envio, estado, actor_user_id, payload)
    VALUES (
        v_envio_id,
        v_estado,
        COALESCE(v_uid, v_orden.id_vendedor),
        jsonb_build_object(
            'codigo_seguimiento', v_codigo,
            'transportista', v_transportista,
            'observaciones', v_observaciones,
            'updated_at', now()
        )
    );

    UPDATE auth.ordenes
    SET metadata = metadata || jsonb_build_object(
        'envio_id', v_envio_id,
        'estado_envio', v_estado,
        'codigo_seguimiento', v_codigo,
        'transportista', v_transportista,
        'ultima_actualizacion_envio', now()
    )
    WHERE id = v_orden.id;

    SELECT id INTO v_uc_id FROM auth.use_cases WHERE slug = 'order_completion';

    v_user_node := auth.ensure_query_graph_node(
        'user',
        v_orden.id_vendedor,
        NULL,
        NULL,
        v_orden.id_vendedor,
        'seller:' || v_orden.id_vendedor::TEXT,
        jsonb_build_object('id_usuario', v_orden.id_vendedor)
    );

    v_uc_node := auth.ensure_query_graph_node(
        'use_case',
        NULL,
        NULL,
        v_uc_id,
        NULL,
        'order_completion',
        jsonb_build_object('phase', 'phase11')
    );

    PERFORM auth.ensure_query_graph_edge(
        v_user_node,
        v_uc_node,
        'ORDER_COMPLETION:' || v_envio_id::TEXT,
        v_orden.id_vendedor,
        jsonb_build_object(
            'envio_id', v_envio_id,
            'orden_id', v_orden.id,
            'shipment_status', v_estado,
            'tracking_code', v_codigo,
            'carrier', v_transportista,
            'updated_at', now()
        )
    );

    RETURN jsonb_build_object(
        'envio_id', v_envio_id,
        'orden_id', v_orden.id,
        'estado_envio', v_estado,
        'codigo_seguimiento', COALESCE(v_codigo, ''),
        'transportista', v_transportista,
        'entregado', (v_estado = 'entregado')
    );
END;
$$;


--
-- Name: actualizar_estado_envio_json(uuid, json); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.actualizar_estado_envio_json(p_orden_id uuid, p_payload json DEFAULT '{}'::json) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$ BEGIN RETURN auth.actualizar_estado_envio(p_orden_id, auth.json_to_jsonb(p_payload)); END; $$;


--
-- Name: FUNCTION actualizar_estado_envio_json(p_orden_id uuid, p_payload json); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.actualizar_estado_envio_json(p_orden_id uuid, p_payload json) IS 'Wrapper JSON explicito para compatibilidad PostgREST sin overload ambiguo.';


--
-- Name: acumular_puntos_intercambio(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.acumular_puntos_intercambio(p_intercambio_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_actor         UUID;
    v_role          TEXT;
    v_estado        TEXT;
    v_solicitante   UUID;
    v_receptor      UUID;
    v_puntos_sol    NUMERIC;
    v_puntos_rec    NUMERIC;
    v_ya_acumulado  BOOLEAN;
    v_from_node     BIGINT;
    v_to_node       BIGINT;
BEGIN
    v_actor := auth.current_jwt_user_id();
    v_role  := auth.current_jwt_role();

    IF v_actor IS NULL AND v_role <> 'db_admin' THEN
        RAISE EXCEPTION 'jwt requerido para acumular puntos';
    END IF;

    SELECT i.estado, i.solicitante_id, i.receptor_id
    INTO   v_estado, v_solicitante, v_receptor
    FROM   auth.intercambios i
    WHERE  i.id = p_intercambio_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'intercambio no encontrado: %', p_intercambio_id;
    END IF;

    IF v_role <> 'db_admin' AND v_actor <> v_solicitante AND v_actor <> v_receptor THEN
        RAISE EXCEPTION 'solo participantes o db_admin pueden acumular puntos del intercambio';
    END IF;

    IF v_estado <> 'completada' THEN
        RAISE EXCEPTION 'solo intercambios completados pueden acumular puntos; estado actual: %', v_estado;
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM auth.h_intercambios_audit
        WHERE intercambio_id = p_intercambio_id
          AND evento = 'puntos_acumulados'
    ) INTO v_ya_acumulado;

    IF v_ya_acumulado THEN
        RETURN jsonb_build_object(
            'ok', FALSE,
            'mensaje', 'puntos ya acumulados para este intercambio',
            'intercambio_id', p_intercambio_id
        );
    END IF;

    SELECT COALESCE(SUM(p.puntos_recompensa), 0)
    INTO   v_puntos_sol
    FROM   auth.intercambio_articulos ia
    JOIN   auth.productos p ON p.id = ia.producto_id
    WHERE  ia.intercambio_id = p_intercambio_id
      AND  ia.rol_en_intercambio = 'receptor';

    SELECT COALESCE(SUM(p.puntos_recompensa), 0)
    INTO   v_puntos_rec
    FROM   auth.intercambio_articulos ia
    JOIN   auth.productos p ON p.id = ia.producto_id
    WHERE  ia.intercambio_id = p_intercambio_id
      AND  ia.rol_en_intercambio = 'solicitante';

    INSERT INTO auth.billetera (id_usuario, saldo, moneda)
    VALUES (v_solicitante, v_puntos_sol, 'Puntos')
    ON CONFLICT (id_usuario) DO UPDATE
       SET saldo             = auth.billetera.saldo + EXCLUDED.saldo,
           fecha_modificacion = NOW()
    WHERE  auth.billetera.activo = TRUE;

    INSERT INTO auth.billetera (id_usuario, saldo, moneda)
    VALUES (v_receptor, v_puntos_rec, 'Puntos')
    ON CONFLICT (id_usuario) DO UPDATE
       SET saldo             = auth.billetera.saldo + EXCLUDED.saldo,
           fecha_modificacion = NOW()
    WHERE  auth.billetera.activo = TRUE;

    INSERT INTO auth.h_intercambios_audit (
        intercambio_id, actor_user_id, evento, payload
    ) VALUES (
        p_intercambio_id,
        COALESCE(v_actor, v_solicitante),
        'puntos_acumulados',
        jsonb_build_object(
            'solicitante_id',      v_solicitante,
            'receptor_id',         v_receptor,
            'puntos_solicitante',  v_puntos_sol,
            'puntos_receptor',     v_puntos_rec,
            'acumulado_en',        NOW()
        )
    );

    v_from_node := auth.ensure_query_graph_node(
        'user', v_solicitante, NULL, NULL, v_solicitante,
        'user:' || v_solicitante::TEXT,
        jsonb_build_object('id_usuario', v_solicitante)
    );
    v_to_node := auth.ensure_query_graph_node(
        'user', v_receptor, NULL, NULL, v_receptor,
        'user:' || v_receptor::TEXT,
        jsonb_build_object('id_usuario', v_receptor)
    );
    PERFORM auth.ensure_query_graph_edge(
        v_from_node,
        v_to_node,
        'PUNTOS_ACUMULADOS',
        COALESCE(v_actor, v_solicitante),
        jsonb_build_object(
            'intercambio_id',     p_intercambio_id,
            'puntos_solicitante', v_puntos_sol,
            'puntos_receptor',    v_puntos_rec,
            'acumulado_en',       NOW()
        )
    );

    RETURN jsonb_build_object(
        'ok',                  TRUE,
        'intercambio_id',      p_intercambio_id,
        'solicitante_id',      v_solicitante,
        'receptor_id',         v_receptor,
        'puntos_solicitante',  v_puntos_sol,
        'puntos_receptor',     v_puntos_rec
    );
END;
$$;


--
-- Name: admin_anonymize_user(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_anonymize_user(p_target_user_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
declare
  v_before jsonb; v_after jsonb;
  v_new_email text; v_new_username text;
  v_hash_email text; v_hash_username text;
  v_user auth.users%rowtype;
begin
  if not auth.is_db_admin() then raise exception 'Solo db_admin puede anonymizar'; end if;
  if p_reason is null or btrim(p_reason)='' then raise exception 'reason es obligatorio'; end if;

  select * into v_user from auth.users where id=p_target_user_id;
  if not found then raise exception 'Usuario objetivo no existe'; end if;
  if v_user.fecha_eliminacion is null then raise exception 'La cuenta debe estar soft_deleted antes de anonymizar'; end if;
  if v_user.legal_hold then raise exception 'La cuenta está en legal_hold'; end if;

  select to_jsonb(v_user) into v_before;
  v_hash_email    := encode(digest(coalesce(v_user.email,''),'sha256'),'hex');
  v_hash_username := encode(digest(coalesce(v_user.username,''),'sha256'),'hex');
  v_new_email     := 'deleted+'||replace(p_target_user_id::text,'-','')||'@anon.kambalache.local';
  v_new_username  := 'deleted_'||left(replace(p_target_user_id::text,'-',''),16);

  insert into auth.user_anonymization_map(
    target_user_id,original_email_sha256,original_username_sha256,
    anonymized_email,anonymized_username,anonymized_by)
  values (p_target_user_id,v_hash_email,v_hash_username,v_new_email,v_new_username,auth.fn_current_user_id())
  ON CONFLICT (target_user_id) do update
  set anonymized_email=excluded.anonymized_email, anonymized_username=excluded.anonymized_username,
      anonymized_by=excluded.anonymized_by, fecha_anonimizacion=now();

  update auth.users
  set email=v_new_email, username=v_new_username,
      password_hash=encode(digest(gen_random_uuid()::text,'sha256'),'hex'),
      otp_code=null, otp_expiry=null,
      activo=false, lifecycle_state='anonymized',
      fecha_anonimizacion=now(), anonymized_by=auth.fn_current_user_id(), fecha_actualizacion=now()
  where id=p_target_user_id;

  update auth.user_profiles
  set nombre=null, apellido=null, telefono=null, url_avatar=null,
      bio='Cuenta anonymizada', fecha_actualizacion=now()
  where id_usuario=p_target_user_id;

  update auth.perfiles_publicos_vendedor
  set nombre_marca='Cuenta anonymizada', biografia=null, url_logo=null,
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('anonymized',true,'anonymized_at',now()),
      activo=false, fecha_modificacion=now()
  where id_vendedor=p_target_user_id;

  update auth.sesiones_tokens set revocado=true
  where id_usuario=p_target_user_id and revocado=false;

  select to_jsonb(u) into v_after from auth.users u where u.id=p_target_user_id;
  perform auth.lifecycle_log_event('ANONYMIZE','critical',p_target_user_id,p_reason,
    v_before,v_after,v_before->>'lifecycle_state',v_after->>'lifecycle_state','rpc',null);

  update auth.user_purge_queue
  set strategy='anonymized_keep_history', estado='executed',
      executed_at=now(), fecha_actualizacion=now(), attempts=attempts+1
  where target_user_id=p_target_user_id and estado='pending';

  perform auth.sync_user_lifecycle_projection(p_target_user_id,'ANONYMIZE');
  return jsonb_build_object('id_usuario',p_target_user_id,'lifecycle_state','anonymized');
end;
$$;


--
-- Name: admin_auto_route_purge_or_anonymize(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_auto_route_purge_or_anonymize(p_target_user_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_dep bigint := auth.count_blocking_user_dependencies(p_target_user_id);
BEGIN
  IF NOT auth.is_db_admin() THEN RAISE EXCEPTION 'Solo db_admin'; END IF;
  IF v_dep > 0 THEN
    RETURN auth.admin_anonymize_user(p_target_user_id, p_reason||':' ||'auto_routed_from_purge_attempt');
  ELSE
    RETURN auth.admin_purge_user(p_target_user_id, p_reason);
  END IF;
END;
$$;


--
-- Name: admin_bulk_change_plan(uuid[], text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_bulk_change_plan(p_vendedor_ids uuid[], p_plan_codigo text, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor      uuid;
    v_plan_id    uuid;
    v_procesados integer := 0;
    v_errores    integer := 0;
    v_vid        uuid;
BEGIN
    v_actor := auth.fn_current_user_id();
    IF (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role') != 'db_admin' THEN
        RAISE EXCEPTION 'solo_admin' USING ERRCODE = '42501';
    END IF;

    IF p_motivo IS NULL OR length(trim(p_motivo)) < 10 THEN
        RAISE EXCEPTION 'motivo_requerido (min 10 chars)' USING ERRCODE = '22023';
    END IF;

    SELECT id INTO v_plan_id FROM auth.planes_membresia
    WHERE codigo = p_plan_codigo AND activo = true;
    IF v_plan_id IS NULL THEN
        RAISE EXCEPTION 'plan_no_encontrado: %', p_plan_codigo USING ERRCODE = 'P0001';
    END IF;

    FOREACH v_vid IN ARRAY p_vendedor_ids LOOP
        BEGIN
            UPDATE auth.membresias_vendedor
            SET id_plan          = v_plan_id,
                es_trial         = false,
                trial_expiracion = NULL,
                fecha_expiracion = now() + interval '1 month'
            WHERE id_vendedor = v_vid
              AND estado IN ('activo', 'grace_period')
              AND fecha_eliminacion IS NULL;

            INSERT INTO auth.h_vendedores_audit (id_usuario, operacion, datos_nuevos, motivo, modificado_por)
            VALUES (v_vid, 'UPDATE',
                    jsonb_build_object('plan_nuevo', p_plan_codigo),
                    p_motivo, v_actor);

            v_procesados := v_procesados + 1;
        EXCEPTION WHEN OTHERS THEN
            v_errores := v_errores + 1;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'procesados', v_procesados,
        'errores',    v_errores,
        'plan_nuevo', p_plan_codigo
    );
END;
$$;


--
-- Name: admin_cerrar_conversacion(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_cerrar_conversacion(p_conversacion_id uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_admin uuid := auth.uid();
BEGIN
    IF auth.role() <> 'db_admin' THEN
        RAISE EXCEPTION 'Solo administradores pueden cerrar conversaciones'
            USING ERRCODE = 'P0036';
    END IF;

    UPDATE auth.conversaciones SET
        estado             = 'bloqueada',
        metadata           = metadata || jsonb_build_object('cerrado_por', v_admin, 'motivo', p_motivo),
        fecha_modificacion = now()
    WHERE id = p_conversacion_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Conversación no encontrada' USING ERRCODE = 'P0037';
    END IF;

    RETURN jsonb_build_object('ok', true, 'conversacion_id', p_conversacion_id, 'estado', 'bloqueada');
END;
$$;


--
-- Name: admin_change_membresia(uuid, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_change_membresia(p_id_vendedor uuid, p_tier_code text, p_motivo text, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_admin_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE v_admin uuid := COALESCE(p_admin_id, auth.fn_current_user_id());
BEGIN
  IF NOT auth.is_db_admin() AND p_admin_id IS NULL THEN
    RAISE EXCEPTION 'Solo administradores' USING ERRCODE='42501';
  END IF;
  IF p_tier_code NOT IN ('bronze','silver','gold') THEN
    RAISE EXCEPTION 'Tier inválido: %. Valores: bronze, silver, gold', p_tier_code USING ERRCODE='P0001';
  END IF;

  -- Delegación canónica a CU-A-BS V2.0
  RETURN auth.admin_set_user_membership(
    p_target_user_id := p_id_vendedor,
    p_tier_code      := p_tier_code,
    p_starts_at      := now(),
    p_ends_at        := p_ends_at,
    p_reason         := p_motivo,
    p_metadata       := jsonb_build_object('delegated_from','admin_change_membresia','admin',v_admin)
  );
END;
$$;


--
-- Name: admin_force_deactivate_ubicacion(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_force_deactivate_ubicacion(p_ubicacion_id uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_admin_id uuid := (nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid;
  v_role     text := nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'role';
  v_ub       auth.ubicaciones%ROWTYPE;
BEGIN
  -- RN-010: Solo db_admin
  IF v_role <> 'db_admin' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'acceso_denegado');
  END IF;

  -- RN-011: Motivo obligatorio para admin
  IF p_motivo IS NULL OR char_length(trim(p_motivo)) < 5 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'motivo_obligatorio_min_5_caracteres');
  END IF;

  SELECT * INTO v_ub FROM auth.ubicaciones WHERE id = p_ubicacion_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ubicacion_no_encontrada');
  END IF;

  UPDATE auth.ubicaciones
  SET estado      = 'inactivo',
      es_principal = false,
      fecha_eliminacion  = now(),
      deleted_by  = v_admin_id,
      fecha_actualizacion  = now()
  WHERE id = p_ubicacion_id;

  -- 'SUSPEND' es válido en h_vendedores_audit
  INSERT INTO auth.h_vendedores_audit
    (id_usuario, operacion, datos_anteriores, datos_nuevos, modificado_por, motivo)
  VALUES (v_ub.id_usuario, 'SUSPEND',
    row_to_json(v_ub)::jsonb,
    jsonb_build_object(
      'ubicacion_id', p_ubicacion_id,
      'estado', 'inactivo',
      'deleted_at', now(),
      'admin_id', v_admin_id
    ),
    v_admin_id, p_motivo);

  INSERT INTO auth.ubicacion_graph_outbox (id_ubicacion, id_usuario, operacion, payload)
  VALUES (p_ubicacion_id, v_ub.id_usuario, 'DEACTIVATE',
    jsonb_build_object('estado', 'inactivo', 'admin_action', true, 'motivo', p_motivo));

  RETURN jsonb_build_object('ok', true, 'motivo', p_motivo);
END;
$$;


--
-- Name: admin_force_set_availability(uuid, boolean, text, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_force_set_availability(p_id_vendedor uuid, p_disponible boolean, p_motivo text, p_admin_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE v_admin uuid; v_anterior boolean;
BEGIN
  v_admin := COALESCE(p_admin_id, auth.fn_current_user_id());
  IF NOT auth.is_db_admin() AND p_admin_id IS NULL THEN
    RAISE EXCEPTION 'Solo administradores' USING ERRCODE = '42501';
  END IF;
  SELECT disponible_ahora INTO v_anterior
  FROM auth.perfiles_publicos_vendedor WHERE id_vendedor=p_id_vendedor;
  IF NOT FOUND THEN RAISE EXCEPTION 'Vendedor no encontrado' USING ERRCODE='P0001'; END IF;

  UPDATE auth.perfiles_publicos_vendedor
  SET disponible_ahora=p_disponible, ultima_disponibilidad=now(),
      modo_disponibilidad='forzado_admin',
      ubicacion_activa_id=CASE WHEN NOT p_disponible THEN NULL ELSE ubicacion_activa_id END,
      fecha_modificacion=now()
  WHERE id_vendedor=p_id_vendedor;

  IF NOT p_disponible THEN
    UPDATE auth.sesiones_operativas_vendedor
    SET fin_sesion=now(), motivo_cierre='admin', cerrado_por=v_admin
    WHERE id_vendedor=p_id_vendedor AND fin_sesion IS NULL;
  END IF;

  INSERT INTO auth.h_vendedores_audit(id_usuario,operacion,datos_anteriores,datos_nuevos,modificado_por,motivo)
  VALUES (p_id_vendedor,'SUSPEND',
    jsonb_build_object('disponible_ahora',v_anterior),
    jsonb_build_object('disponible_ahora',p_disponible,'admin',v_admin),
    v_admin, COALESCE(p_motivo,'Forzado por admin'));

  RETURN jsonb_build_object('id_vendedor',p_id_vendedor,'disponible_ahora',p_disponible,'forzado_por',v_admin,'timestamp',now());
END;
$$;


--
-- Name: admin_get_operational_alerts(text, text, text, boolean, integer, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_get_operational_alerts(p_estado text DEFAULT NULL::text, p_severidad text DEFAULT NULL::text, p_tipo text DEFAULT NULL::text, p_incluir_ocultas boolean DEFAULT false, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, tipo text, id_entidad text, referencia_tipo text, severidad text, estado text, fuente text, payload jsonb, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.current_jwt_role() <> 'db_admin' THEN
    RAISE EXCEPTION 'Solo administradores' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM public.admin_get_operational_alerts(p_estado, p_severidad, p_tipo, p_incluir_ocultas, p_limit, p_offset);
END;
$$;


--
-- Name: admin_get_top_bundles(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_get_top_bundles(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor text;
    v_result jsonb;
BEGIN
    v_actor := (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role');
    IF v_actor != 'db_admin' THEN
        RAISE EXCEPTION 'Solo administradores' USING ERRCODE = '42501';
    END IF;

    SELECT jsonb_agg(row_to_json(t)) INTO v_result
    FROM (
        SELECT
            bp.id, bp.nombre, bp.descuento_pct, bp.activo,
            u.email AS vendedor_email,
            (SELECT COUNT(*) FROM auth.bundle_items bi WHERE bi.id_lote = bp.id) AS items_count,
            bp.fecha_creacion
        FROM auth.bundles_producto bp
        JOIN auth.users u ON u.id = bp.id_vendedor
        ORDER BY bp.fecha_creacion DESC
        LIMIT p_limit
    ) t;

    RETURN jsonb_build_object('bundles',coalesce(v_result,'[]'));
END;
$$;


--
-- Name: admin_get_vendedores_alto_riesgo(integer, integer, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_get_vendedores_alto_riesgo(p_score_min integer DEFAULT 50, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_admin uuid;
BEGIN
    v_admin := auth.fn_current_user_id();
    IF auth.role() <> 'db_admin' THEN
        RAISE EXCEPTION 'Solo administradores' USING ERRCODE = '42501';
    END IF;

    RETURN QUERY
    SELECT jsonb_build_object(
        'id_vendedor',    u.id,
        'email',          u.email,
        'nombre_marca',   ppv.nombre_marca,
        'score_riesgo',   rs.score,
        'nivel_riesgo',   rs.nivel_riesgo,
        'factores',       rs.factores_riesgo,
        'tiene_badge',    COALESCE(bc.tiene_badge, false),
        'total_resenas',  COALESCE(bc.total_resenas, 0),
        'calificacion',   COALESCE(bc.calificacion, 0),
        'membresia',      mv.estado,
        'alertas_abiertas', (
            SELECT COUNT(*) FROM public.admin_alerts aa
            WHERE aa.usuario_afectado_id::uuid = u.id AND aa.estado = 'abierta'
        )
    )
    FROM public.user_risk_scores rs
    JOIN auth.users u ON u.id = rs.id_usuario
    LEFT JOIN auth.perfiles_publicos_vendedor ppv ON ppv.id_vendedor = u.id
    LEFT JOIN auth.badge_confiable bc ON bc.id_vendedor = u.id
    LEFT JOIN auth.membresias_vendedor mv ON mv.id_vendedor = u.id
    WHERE rs.score >= p_score_min
      AND u.role = 'seller'
      AND u.fecha_eliminacion IS NULL
    ORDER BY rs.score DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: admin_get_vendedores_por_plan(text, text, integer, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_get_vendedores_por_plan(p_plan_codigo text DEFAULT NULL::text, p_estado text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_cursor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_rows jsonb;
BEGIN
    IF (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role') != 'db_admin' THEN
        RAISE EXCEPTION 'solo_admin' USING ERRCODE = '42501';
    END IF;

    SELECT jsonb_agg(
        jsonb_build_object(
            'id_vendedor',     mv.id_vendedor,
            'plan',            pm.codigo,
            'estado',          mv.estado,
            'score_confianza', mv.score_confianza,
            'fecha_expiracion',mv.fecha_expiracion,
            'es_trial',        mv.es_trial,
            'override_flags',  mv.override_flags
        ) ORDER BY mv.fecha_creacion DESC
    ) INTO v_rows
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.fecha_eliminacion IS NULL
      AND (p_plan_codigo IS NULL OR pm.codigo = p_plan_codigo)
      AND (p_estado IS NULL OR mv.estado = p_estado)
      AND (p_cursor IS NULL OR mv.id_vendedor > p_cursor)
    ORDER BY mv.id_vendedor ASC
    LIMIT LEAST(p_limit, 200);

    RETURN jsonb_build_object(
        'vendedores',   COALESCE(v_rows, '[]'::jsonb),
        'total',        COALESCE(jsonb_array_length(v_rows), 0),
        'filtro_plan',  p_plan_codigo,
        'filtro_estado',p_estado
    );
END;
$$;


--
-- Name: admin_get_vendor_audit_summary(uuid, integer, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_get_vendor_audit_summary(p_id_vendedor uuid, p_limite integer DEFAULT 50, p_admin_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE v_result jsonb;
BEGIN
  IF NOT auth.is_db_admin() AND p_admin_id IS NULL THEN
    RAISE EXCEPTION 'Solo administradores' USING ERRCODE='42501';
  END IF;

  SELECT jsonb_build_object(
    'vendedor',jsonb_build_object(
      'id',u.id,'email',u.email,'username',u.username,
      'role',u.role,'is_verified',u.is_verified,
      'activo',u.activo,
      'lifecycle_state',u.lifecycle_state,
      'deleted_at',u.fecha_eliminacion,'legal_hold',u.legal_hold),
    'perfil',jsonb_build_object(
      'activo',ppv.activo,'disponible_ahora',ppv.disponible_ahora,
      'score_reputacion',ppv.score_reputacion,'total_resenas',ppv.total_resenas),
    'membresia_activa',jsonb_build_object(
      'tier_code',auth.resolve_effective_tier(u.id,now())),
    'auditoria_reciente',(
      SELECT jsonb_agg(jsonb_build_object(
        'operacion',ha.operacion,'datos_anteriores',ha.datos_anteriores,
        'datos_nuevos',ha.datos_nuevos,'modificado_por',ha.modificado_por,
        'motivo',ha.motivo,'fecha',ha.fecha_cambio) ORDER BY ha.fecha_cambio DESC)
      FROM auth.h_vendedores_audit ha WHERE ha.id_usuario=p_id_vendedor
      LIMIT GREATEST(1,LEAST(COALESCE(p_limite,50),200))),
    'sesiones_operativas',(
      SELECT jsonb_agg(jsonb_build_object(
        'inicio',sov.inicio_sesion,'fin',sov.fin_sesion,
        'motivo_cierre',sov.motivo_cierre,'ubicacion_id',sov.id_ubicacion)
        ORDER BY sov.inicio_sesion DESC)
      FROM auth.sesiones_operativas_vendedor sov WHERE sov.id_vendedor=p_id_vendedor
      LIMIT 10))
  INTO v_result
  FROM auth.users u
  LEFT JOIN auth.perfiles_publicos_vendedor ppv ON ppv.id_vendedor=u.id
  WHERE u.id=p_id_vendedor;

  RETURN COALESCE(v_result,'{"error":"vendedor_no_encontrado"}');
END;
$$;


