--
-- Name: admin_list_user_lifecycle_dashboard(text, text, text, integer, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_list_user_lifecycle_dashboard(p_role text DEFAULT NULL::text, p_tier_code text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(id_usuario uuid, email text, role text, effective_tier_code text, lifecycle_state text, legal_hold boolean, estado_verificacion text, elegible_purga_en timestamp with time zone, blocked_dependency_count bigint, active_sessions bigint, queue_status text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
  select u.id, u.email, u.role,
    auth.resolve_effective_tier(u.id,now()),
    u.lifecycle_state, u.legal_hold, u.estado_verificacion, u.elegible_purga_en,
    auth.count_blocking_user_dependencies(u.id),
    (select count(*) from auth.sesiones_tokens st where st.id_usuario=u.id and st.revocado=false),
    (select q.estado from auth.user_purge_queue q where q.target_user_id=u.id order by q.fecha_creacion desc limit 1)
  from auth.users u
  where auth.is_db_admin()
    and (p_role is null or u.role=p_role)
    and (p_tier_code is null or auth.resolve_effective_tier(u.id,now())=p_tier_code)
    and (p_state is null or u.lifecycle_state=p_state)
  order by u.fecha_actualizacion desc
  limit greatest(1,least(coalesce(p_limit,100),500))
  offset greatest(0,coalesce(p_offset,0));
$$;


--
-- Name: admin_moderar_resena(uuid, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_moderar_resena(p_resena_id uuid, p_accion text, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_admin   uuid;
    v_resena  auth.resenas%ROWTYPE;
BEGIN
    v_admin := auth.fn_current_user_id();
    IF auth.role() <> 'db_admin' THEN
        RAISE EXCEPTION 'Solo administradores pueden moderar reseñas' USING ERRCODE = '42501';
    END IF;
    IF char_length(trim(COALESCE(p_motivo, ''))) < 10 THEN
        RAISE EXCEPTION 'Motivo debe tener al menos 10 caracteres' USING ERRCODE = 'P0055';
    END IF;
    IF p_accion NOT IN ('moderar', 'restaurar') THEN
        RAISE EXCEPTION 'Acción inválida: usar moderar o restaurar' USING ERRCODE = 'P0056';
    END IF;

    SELECT * INTO v_resena FROM auth.resenas WHERE id = p_resena_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Reseña no encontrada' USING ERRCODE = 'P0054';
    END IF;

    UPDATE auth.resenas SET
        moderada           = (p_accion = 'moderar'),
        moderada_at        = CASE WHEN p_accion = 'moderar' THEN now() ELSE NULL END,
        moderada_por       = CASE WHEN p_accion = 'moderar' THEN v_admin ELSE NULL END,
        moderacion_motivo  = CASE WHEN p_accion = 'moderar' THEN trim(p_motivo) ELSE NULL END,
        fecha_modificacion = now()
    WHERE id = p_resena_id;

    -- Recalcular badge tras moderación
    PERFORM auth.fn_calcular_badge_confiable(v_resena.id_vendedor);

    -- Auditoría
    INSERT INTO auth.h_vendedores_audit
        (id_usuario, operacion, datos_anteriores, datos_nuevos, modificado_por, motivo)
    VALUES (
        v_resena.id_vendedor, 'UPDATE',
        jsonb_build_object('resena_id', p_resena_id, 'moderada', v_resena.moderada),
        jsonb_build_object('resena_id', p_resena_id, 'accion', p_accion),
        v_admin, p_motivo
    );

    RETURN jsonb_build_object('ok', true, 'resena_id', p_resena_id, 'accion', p_accion);
END;
$$;


--
-- Name: admin_purge_user(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_purge_user(p_target_user_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
declare v_before jsonb; v_dep_count bigint; v_user auth.users%rowtype;
begin
  if not auth.is_db_admin() then raise exception 'Solo db_admin puede purgar'; end if;
  if p_reason is null or btrim(p_reason)='' then raise exception 'reason es obligatorio'; end if;

  select * into v_user from auth.users where id=p_target_user_id;
  if not found then raise exception 'Usuario objetivo no existe'; end if;
  if v_user.legal_hold then raise exception 'La cuenta está en legal_hold'; end if;
  if v_user.fecha_eliminacion is null then raise exception 'La cuenta debe pasar primero por soft_delete'; end if;
  if v_user.elegible_purga_en is null or v_user.elegible_purga_en > now() then
    raise exception 'La cuenta aún no es elegible para purge'; end if;

  v_dep_count := auth.count_blocking_user_dependencies(p_target_user_id);
  if v_dep_count > 0 then
    raise exception 'La cuenta tiene % dependencias bloqueantes; use anonymización', v_dep_count; end if;

  select to_jsonb(v_user) into v_before;
  perform set_config('app.allow_physical_purge','on',true);
  perform auth.purge_user_lifecycle_projection(p_target_user_id,'PURGE');
  delete from auth.users where id=p_target_user_id;

  insert into auth.user_lifecycle_audit(
    action,severity,actor_user_id,actor_role,target_user_id,target_role,
    target_effective_tier,reason,lifecycle_state_before,lifecycle_state_after,
    before_state,after_state,request_claims,source
  ) values (
    'PURGE','critical',auth.fn_current_user_id(),auth.current_app_role(),
    p_target_user_id,v_user.role,auth.resolve_effective_tier(p_target_user_id,now()),
    p_reason,v_user.lifecycle_state,'purged',v_before,null,auth.jwt_claims(),'rpc'
  );

  update auth.user_purge_queue
  set estado='executed', executed_at=now(), fecha_actualizacion=now(), attempts=attempts+1
  where target_user_id=p_target_user_id and estado='pending';

  return jsonb_build_object('id_usuario',p_target_user_id,'purged',true);
end;
$$;


--
-- Name: admin_reactivar_membresia(uuid, text, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_reactivar_membresia(p_id_vendedor uuid, p_motivo text, p_dias_ext integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid;
    v_rows  integer;
BEGIN
    v_actor := auth.fn_current_user_id();
    IF (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role') != 'db_admin' THEN
        RAISE EXCEPTION 'solo_admin' USING ERRCODE = '42501';
    END IF;

    UPDATE auth.membresias_vendedor
    SET estado           = 'activo',
        fecha_expiracion = now() + (p_dias_ext || ' days')::interval
    WHERE id_vendedor = p_id_vendedor
      AND estado IN ('suspendida', 'expirada', 'grace_period')
      AND fecha_eliminacion IS NULL;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        RETURN jsonb_build_object('warning', 'sin_membresia_suspendida', 'id_vendedor', p_id_vendedor);
    END IF;

    INSERT INTO auth.h_vendedores_audit (id_usuario, operacion, datos_nuevos, motivo, modificado_por)
    VALUES (p_id_vendedor, 'UPDATE',
            jsonb_build_object('estado', 'activo', 'dias_extendidos', p_dias_ext),
            p_motivo, v_actor);

    RETURN jsonb_build_object('reactivado', true, 'id_vendedor', p_id_vendedor, 'dias_ext', p_dias_ext);
END;
$$;


--
-- Name: admin_reactivate_ubicacion(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_reactivate_ubicacion(p_ubicacion_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_admin_id uuid := (nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid;
  v_role     text := nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'role';
  v_ub       auth.ubicaciones%ROWTYPE;
BEGIN
  IF v_role <> 'db_admin' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'acceso_denegado');
  END IF;

  SELECT * INTO v_ub FROM auth.ubicaciones WHERE id = p_ubicacion_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ubicacion_no_encontrada');
  END IF;

  -- RN-012: No reactivar si el usuario está soft-deleted (CU-A-BS)
  IF EXISTS (
    SELECT 1 FROM auth.users
    WHERE id = v_ub.id_usuario AND (activo = false OR fecha_eliminacion IS NOT NULL)
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'usuario_inactivo_o_borrado',
      'mensaje', 'Restaurar usuario primero (CU-A-BS-005)'
    );
  END IF;

  UPDATE auth.ubicaciones
  SET estado     = 'activo',
      fecha_eliminacion = NULL,
      deleted_by = NULL,
      fecha_actualizacion = now()
  WHERE id = p_ubicacion_id;

  INSERT INTO auth.h_vendedores_audit (id_usuario, operacion, datos_nuevos, modificado_por, motivo)
  VALUES (v_ub.id_usuario, 'UPDATE',
    jsonb_build_object('ubicacion_id', p_ubicacion_id, 'estado', 'activo', 'deleted_at', NULL),
    v_admin_id, 'admin_reactivate_ubicacion');

  INSERT INTO auth.ubicacion_graph_outbox (id_ubicacion, id_usuario, operacion, payload)
  VALUES (p_ubicacion_id, v_ub.id_usuario, 'UPSERT',
    jsonb_build_object('estado', 'activo', 'reactivado_by', v_admin_id));

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: admin_recalcular_afinidad_vendedor(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_recalcular_afinidad_vendedor(p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor text;
    v_vid   uuid;
    v_count integer := 0;
BEGIN
    v_actor := (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role');
    IF v_actor != 'db_admin' THEN
        RAISE EXCEPTION 'Solo administradores pueden forzar recálculo' USING ERRCODE = '42501';
    END IF;

    IF p_id_vendedor IS NOT NULL THEN
        PERFORM auth.fn_calcular_afinidad(p_id_vendedor);
        v_count := 1;
    ELSE
        FOR v_vid IN
            SELECT DISTINCT id_vendedor FROM auth.ordenes
            WHERE estado = 'confirmada' AND fecha_creacion > now() - interval '90 days'
        LOOP
            PERFORM auth.fn_calcular_afinidad(v_vid);
            v_count := v_count + 1;
        END LOOP;
    END IF;

    RETURN jsonb_build_object('vendedores_procesados',v_count,'timestamp',now());
END;
$$;


--
-- Name: admin_recalcular_rfm_vendedor(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_recalcular_rfm_vendedor(p_id_vendedor uuid, p_motivo text DEFAULT 'recalculo_manual_admin'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor   uuid;
    v_count   integer;
BEGIN
    v_actor := auth.fn_current_user_id();

    -- RN-020: Solo db_admin
    IF (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role') != 'db_admin' THEN
        RAISE EXCEPTION 'acceso_denegado' USING ERRCODE = '42501';
    END IF;

    v_count := auth.fn_calcular_rfm_snapshot(p_id_vendedor);

    -- Auditoría
    INSERT INTO auth.h_vendedores_audit (
        id_usuario, operacion, datos_nuevos, motivo
    ) VALUES (
        p_id_vendedor, 'UPDATE',
        jsonb_build_object('rfm_compradores_actualizados', v_count),
        p_motivo
    );

    RETURN jsonb_build_object(
        'id_vendedor',   p_id_vendedor,
        'compradores',   v_count,
        'snapshot_date', CURRENT_DATE
    );
END;
$$;


--
-- Name: admin_recalcular_riesgo(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_recalcular_riesgo(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_admin         uuid;
    v_cancelados    integer;
    v_reportes      integer;
    v_negativos     integer;
    v_score_nuevo   integer;
BEGIN
    v_admin := auth.fn_current_user_id();
    IF auth.role() <> 'db_admin' THEN
        RAISE EXCEPTION 'Solo administradores pueden recalcular riesgo' USING ERRCODE = '42501';
    END IF;

    SELECT COUNT(*) INTO v_cancelados
    FROM auth.ordenes
    WHERE id_vendedor = p_id_vendedor AND estado = 'cancelada';

    SELECT COUNT(*) INTO v_reportes
    FROM auth.nlp_queue nq
    JOIN auth.resenas r ON r.id = nq.resena_id
    WHERE r.id_vendedor = p_id_vendedor AND nq.estado = 'completado';

    SELECT COUNT(*) INTO v_negativos
    FROM auth.resenas
    WHERE id_vendedor = p_id_vendedor AND calificacion <= 2 AND verificada = true;

    v_score_nuevo := LEAST(100, (
        (v_cancelados  * 5) +
        (v_negativos   * 8) +
        (v_reportes    * 3)
    ));

    INSERT INTO public.user_risk_scores (
        id_usuario, score,
        intercambios_cancelados, ratings_negativos, reportes_recibidos,
        factores_riesgo
    ) VALUES (
        p_id_vendedor, v_score_nuevo,
        v_cancelados, v_negativos, v_reportes,
        jsonb_build_object(
            'cancelados', v_cancelados,
            'negativos',  v_negativos,
            'reportes',   v_reportes,
            'calculado_at', now()
        )
    )
    ON CONFLICT (id_usuario) DO UPDATE SET
        score                    = v_score_nuevo,
        intercambios_cancelados  = v_cancelados,
        ratings_negativos        = v_negativos,
        reportes_recibidos       = v_reportes,
        factores_riesgo          = jsonb_build_object(
            'cancelados', v_cancelados,
            'negativos',  v_negativos,
            'reportes',   v_reportes,
            'calculado_at', now()
        );

    RETURN jsonb_build_object(
        'ok',           true,
        'id_vendedor',  p_id_vendedor,
        'score_nuevo',  v_score_nuevo,
        'nivel',        CASE
            WHEN v_score_nuevo <= 25  THEN 'bajo'
            WHEN v_score_nuevo <= 50  THEN 'medio'
            WHEN v_score_nuevo <= 75  THEN 'alto'
            ELSE 'critico'
        END,
        'factores',     jsonb_build_object(
            'cancelados', v_cancelados,
            'negativos',  v_negativos,
            'reportes',   v_reportes
        )
    );
END;
$$;


--
-- Name: admin_recalcular_riesgo_vendedor(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_recalcular_riesgo_vendedor(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN auth.admin_recalcular_riesgo(p_id_vendedor);
END;
$$;


--
-- Name: admin_reconcile_inventory(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_reconcile_inventory(p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := auth.fn_current_user_id();
    v_count integer := 0;
    v_producto_id uuid;
BEGIN
    IF auth.fn_current_role() NOT IN ('db_admin','system') THEN
        RAISE EXCEPTION 'Solo db_admin o system puede reconciliar inventario' USING ERRCODE = '42501';
    END IF;

    FOR v_producto_id IN
        SELECT id_producto FROM auth.inventario_producto
        WHERE (p_id_vendedor IS NULL OR id_vendedor = p_id_vendedor)
    LOOP
        PERFORM auth.fn_recalc_inventory_product(v_producto_id);
        PERFORM auth.fn_inventory_alert_check(v_producto_id);
        v_count := v_count + 1;
    END LOOP;

    IF p_id_vendedor IS NOT NULL THEN
        INSERT INTO auth.admin_acciones_vendedor(
            id_vendedor, admin_user_id, accion, motivo
        )
        VALUES (p_id_vendedor, v_actor, 'reconcile_inventory', 'reconciliación manual de agregados de inventario');
    END IF;

    RETURN jsonb_build_object('ok', true, 'productos_reconciliados', v_count);
END;
$$;


--
-- Name: admin_resolver_moderacion(uuid, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_resolver_moderacion(p_reporte_id uuid, p_decision text, p_notas text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
declare v_actor_id uuid; v_reporte record;
begin
  v_actor_id := auth.fn_current_user_id();
  if auth.fn_current_user_role() <> 'db_admin' then raise exception 'admin_role_required'; end if;
  if p_decision not in ('aprobar','desactivar','eliminar','advertir') then raise exception 'decision_invalida'; end if;

  select * into v_reporte from auth.producto_moderacion_queue where id = p_reporte_id for update;
  if not found then raise exception 'reporte_not_found'; end if;

  update auth.producto_moderacion_queue
  set estado='resuelto', revisor_id=v_actor_id, decision=p_decision,
      notas_revisor=p_notas, resuelto_en=now()
  where id = p_reporte_id;

  -- Aplicar decisión al producto
  if p_decision = 'desactivar' then
    update auth.productos set activo = false where id = v_reporte.id_producto;
    perform auth.fn_write_publicacion_audit(v_reporte.id_producto, 'ADMIN_DEACTIVATE_MODERACION', p_notas, null,
      (select to_jsonb(p) from auth.productos p where p.id = v_reporte.id_producto));
  elsif p_decision = 'eliminar' then
    update auth.productos set activo=false, fecha_eliminacion=now(), deleted_by=v_actor_id,
      delete_reason='admin_moderacion:' || p_reporte_id::text
    where id = v_reporte.id_producto;
    perform auth.fn_write_publicacion_audit(v_reporte.id_producto, 'ADMIN_SOFT_DELETE_MODERACION', p_notas, null,
      (select to_jsonb(p) from auth.productos p where p.id = v_reporte.id_producto));
  end if;

  return jsonb_build_object('reporte_id', p_reporte_id, 'decision', p_decision, 'aplicado', true);
end; $$;


--
-- Name: admin_restore_user(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_restore_user(p_target_user_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_user auth.users%rowtype;
begin
  if not auth.is_db_admin() then raise exception 'Solo db_admin puede restaurar'; end if;
  if p_reason is null or btrim(p_reason)='' then raise exception 'reason es obligatorio'; end if;

  select * into v_user from auth.users where id=p_target_user_id;
  if not found then raise exception 'Usuario objetivo no existe'; end if;
  if v_user.fecha_anonimizacion is not null then raise exception 'No se permite restore después de anonymización'; end if;

  select to_jsonb(v_user) into v_before;
  update auth.users
  set activo=true, lifecycle_state='active',
      fecha_eliminacion=null, deleted_by=null, deleted_reason=null,
      elegible_purga_en=null, purged_at=null, fecha_actualizacion=now()
  where id=p_target_user_id;

  update auth.perfiles_publicos_vendedor
  set activo=true, fecha_modificacion=now() where id_vendedor=p_target_user_id;

  update auth.user_purge_queue
  set estado='cancelled', fecha_actualizacion=now()
  where target_user_id=p_target_user_id and estado='pending';

  select to_jsonb(u) into v_after from auth.users u where u.id=p_target_user_id;
  perform auth.lifecycle_log_event('RESTORE','info',p_target_user_id,p_reason,
    v_before,v_after,v_before->>'lifecycle_state',v_after->>'lifecycle_state','rpc',null);
  perform auth.sync_user_lifecycle_projection(p_target_user_id,'RESTORE');

  return jsonb_build_object('id_usuario',p_target_user_id,'lifecycle_state','active');
end;
$$;


--
-- Name: admin_resync_all_badges_membresia(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_resync_all_badges_membresia() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_updated integer;
BEGIN
  IF COALESCE(auth.get_request_jwt_claims() ->> 'role', '') <> 'db_admin' THEN
    RAISE EXCEPTION 'solo_db_admin';
  END IF;

  WITH updated AS (
    UPDATE auth.perfiles_publicos_vendedor pp
       SET badge_membresia = COALESCE(pm.codigo, 'bronze'),
           fecha_modificacion = now()
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan AND pm.activo = true
    WHERE mv.id_vendedor = pp.id_vendedor
      AND mv.estado = 'activa'
      AND pp.badge_membresia IS DISTINCT FROM pm.codigo
    RETURNING pp.id_vendedor
  )
  SELECT count(*) INTO v_updated FROM updated;

  RETURN v_updated;
END;
$$;


--
-- Name: admin_revertir_canje(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_revertir_canje(p_canje_id uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_admin_id  uuid;
    v_canje     record;
    v_saldo_act numeric;
BEGIN
    v_admin_id := auth.fn_current_user_id();

    IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = v_admin_id AND role = 'db_admin') THEN
        RAISE EXCEPTION 'acceso_denegado' USING ERRCODE = '42501';
    END IF;

    SELECT c.*, b.saldo AS saldo_billetera
    INTO v_canje
    FROM auth.canjes_puntos c
    JOIN auth.billetera b ON b.id_usuario = c.id_usuario
    WHERE c.id = p_canje_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'canje_no_encontrado', 'codigo', 'WALLET_010');
    END IF;

    IF v_canje.estado <> 'aprobado' THEN
        RETURN jsonb_build_object(
            'error',  'canje_no_reversible',
            'codigo', 'WALLET_011',
            'estado_actual', v_canje.estado
        );
    END IF;

    IF v_canje.fecha_canje < now() - INTERVAL '30 days' THEN
        RETURN jsonb_build_object(
            'error',  'canje_fuera_de_ventana',
            'codigo', 'WALLET_012',
            'detalle', 'Solo se pueden revertir canjes de los últimos 30 días'
        );
    END IF;

    SELECT saldo INTO v_saldo_act
    FROM auth.billetera WHERE id_usuario = v_canje.id_usuario FOR UPDATE;

    UPDATE auth.billetera
    SET saldo = saldo + v_canje.puntos_debitados,
        fecha_modificacion = now()
    WHERE id_usuario = v_canje.id_usuario;

    UPDATE auth.canjes_puntos
    SET estado = 'revertido',
        fecha_modificacion = now(),
        detalle = detalle || jsonb_build_object(
            'revertido_por', v_admin_id,
            'motivo',        p_motivo,
            'revertido_en',  now()
        )
    WHERE id = p_canje_id;

    INSERT INTO auth.movimientos_puntos (
        id_usuario, tipo_movimiento, monto, saldo_anterior, saldo_posterior,
        referencia, detalle
    ) VALUES (
        v_canje.id_usuario, 'reversion_canje', v_canje.puntos_debitados,
        v_saldo_act, v_saldo_act + v_canje.puntos_debitados,
        p_canje_id::text,
        jsonb_build_object('admin_id', v_admin_id, 'motivo', p_motivo)
    );

    INSERT INTO auth.h_vendedores_audit (
        id_usuario, campo_modificado, valor_anterior, valor_nuevo,
        modificado_por, motivo
    ) VALUES (
        v_canje.id_usuario, 'canje_revertido', 'aprobado', 'revertido',
        v_admin_id, p_motivo
    );

    RETURN jsonb_build_object(
        'revertido',   true,
        'saldo_nuevo', v_saldo_act + v_canje.puntos_debitados,
        'puntos_devueltos', v_canje.puntos_debitados
    );
END;
$$;


--
-- Name: admin_run_user_lifecycle_maintenance(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_run_user_lifecycle_maintenance(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
declare
  v_row record;
  v_processed_anonymize integer:=0; v_processed_purge integer:=0; v_archived_queue integer:=0;
begin
  if not auth.is_db_admin() then raise exception 'Solo db_admin puede ejecutar mantenimiento'; end if;

  update auth.sesiones_tokens set revocado=true where fecha_expiracion<now() and revocado=false;

  for v_row in
    select u.id from auth.users u
    join auth.v_user_effective_lifecycle_policy p on p.id_usuario=u.id
    where u.lifecycle_state='soft_deleted' and u.legal_hold=false
      and u.fecha_eliminacion is not null
      and u.estado_verificacion not in ('pending','manual_review')
      and now() >= u.fecha_eliminacion + make_interval(days=>p.anonymize_after_days)
      and auth.user_requires_anonymization(u.id)
    limit greatest(1,least(coalesce(p_limit,100),500))
  loop
    perform auth.admin_anonymize_user(v_row.id,'maintenance_anonymize');
    v_processed_anonymize := v_processed_anonymize + 1;
  end loop;

  for v_row in
    select u.id from auth.users u
    where u.lifecycle_state in ('soft_deleted','purge_ready') and u.legal_hold=false
      and u.elegible_purga_en is not null and u.elegible_purga_en<=now()
      and u.estado_verificacion not in ('pending','manual_review')
      and auth.count_blocking_user_dependencies(u.id)=0
    limit greatest(1,least(coalesce(p_limit,100),500))
  loop
    perform auth.admin_purge_user(v_row.id,'maintenance_purge');
    v_processed_purge := v_processed_purge + 1;
  end loop;

  delete from auth.user_purge_queue
  where archived=false and estado in ('executed','cancelled') and fecha_actualizacion < now()-interval '90 days';
  get diagnostics v_archived_queue = row_count;

  insert into auth.log_mantenimiento(tipo,resultado,detalle_jsonb,ejecutado_por,archivado)
  values ('user_lifecycle_maintenance','ok',
    jsonb_build_object('processed_anonymize',v_processed_anonymize,
      'processed_purge',v_processed_purge,'archived_queue_rows',v_archived_queue),
    auth.fn_current_user_id(), false);

  return jsonb_build_object('processed_anonymize',v_processed_anonymize,
    'processed_purge',v_processed_purge,'archived_queue_rows',v_archived_queue);
end;
$$;


--
-- Name: admin_set_estado_perfil_publico(uuid, boolean, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_set_estado_perfil_publico(p_id_vendedor uuid, p_activo boolean, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_row auth.perfiles_publicos_vendedor%ROWTYPE;
BEGIN
  IF COALESCE(auth.get_request_jwt_claims() ->> 'role', '') <> 'db_admin' THEN
    RAISE EXCEPTION 'solo_db_admin_puede_cambiar_estado_perfil';
  END IF;

  PERFORM set_config(
    'app.audit_reason',
    COALESCE(p_motivo,
      CASE WHEN p_activo THEN 'reactivacion_perfil_publico'
           ELSE 'suspension_perfil_publico' END),
    true
  );

  UPDATE auth.perfiles_publicos_vendedor
     SET activo = p_activo, fecha_modificacion = now()
   WHERE id_vendedor = p_id_vendedor
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'perfil_publico_no_encontrado: %', p_id_vendedor;
  END IF;

  -- Log en admin_acciones_vendedor
  INSERT INTO auth.admin_acciones_vendedor
    (id_vendedor, id_admin, accion, motivo)
  VALUES (
    p_id_vendedor,
    auth.current_jwt_user_id(),
    CASE WHEN p_activo THEN 'perfil_reactivado' ELSE 'perfil_suspendido' END,
    COALESCE(p_motivo, 'sin motivo registrado')
  );

  PERFORM set_config('app.audit_reason', '', true);

  RETURN jsonb_build_object(
    'ok', true,
    'id_vendedor', v_row.id_vendedor,
    'slug_publico', v_row.slug_publico,
    'activo', v_row.activo
  );
END;
$$;


--
-- Name: admin_set_inventory_freeze(uuid, boolean, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_set_inventory_freeze(p_id_vendedor uuid, p_freeze boolean, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_admin uuid := auth.fn_current_user_id();
    v_before jsonb;
    v_after jsonb;
BEGIN
    -- RN-027: Solo db_admin puede congelar
    IF auth.fn_current_role() <> 'db_admin' THEN
        RAISE EXCEPTION 'Solo db_admin puede congelar inventario [RN-027]' USING ERRCODE = '42501';
    END IF;

    -- RN-028: Motivo obligatorio
    IF length(trim(coalesce(p_motivo,''))) < 5 THEN
        RAISE EXCEPTION 'Motivo requerido (mínimo 5 caracteres) [RN-028]';
    END IF;

    -- Verificar que existe política habilitada
    IF NOT auth.fn_check_inventory_domain_policy('freeze_inventory') THEN
        RAISE EXCEPTION 'Política de congelamiento deshabilitada' USING ERRCODE = '42501';
    END IF;

    SELECT to_jsonb(ppv.*) INTO v_before
    FROM auth.perfiles_publicos_vendedor ppv WHERE id_vendedor = p_id_vendedor FOR UPDATE;

    IF v_before IS NULL THEN
        RAISE EXCEPTION 'Perfil de vendedor inexistente';
    END IF;

    UPDATE auth.perfiles_publicos_vendedor
    SET inventario_congelado = p_freeze,
        motivo_congelamiento = CASE WHEN p_freeze THEN p_motivo ELSE NULL END,
        disponible_ahora = CASE WHEN p_freeze THEN false ELSE disponible_ahora END,
        fecha_modificacion = now()
    WHERE id_vendedor = p_id_vendedor;

    SELECT to_jsonb(ppv.*) INTO v_after
    FROM auth.perfiles_publicos_vendedor ppv WHERE id_vendedor = p_id_vendedor;

    INSERT INTO auth.admin_acciones_vendedor(
        id_vendedor, admin_user_id, accion, motivo, datos_anteriores, datos_nuevos
    )
    VALUES (
        p_id_vendedor, v_admin,
        CASE WHEN p_freeze THEN 'freeze_inventory' ELSE 'unfreeze_inventory' END,
        p_motivo, v_before, v_after
    );

    -- RN-029: Revocar sesiones al congelar
    IF p_freeze THEN
        UPDATE auth.sesiones_tokens
        SET revocado = true
        WHERE id_usuario = p_id_vendedor;

        -- Registrar movimiento de congelamiento en todos los productos del vendedor
        INSERT INTO auth.movimientos_inventario(
            id_producto, id_vendedor, tipo_movimiento, cantidad, motivo,
            actor_user_id, actor_role, metadata
        )
        SELECT ip.id_producto, p_id_vendedor, 'admin_congelamiento', 1, p_motivo,
               v_admin, 'db_admin', jsonb_build_object('freeze', true)
        FROM auth.inventario_producto ip
        WHERE ip.id_vendedor = p_id_vendedor;
    ELSE
        -- Al descongelar, registrar movimiento
        INSERT INTO auth.movimientos_inventario(
            id_producto, id_vendedor, tipo_movimiento, cantidad, motivo,
            actor_user_id, actor_role, metadata
        )
        SELECT ip.id_producto, p_id_vendedor, 'admin_descongelamiento', 1, p_motivo,
               v_admin, 'db_admin', jsonb_build_object('freeze', false)
        FROM auth.inventario_producto ip
        WHERE ip.id_vendedor = p_id_vendedor;
    END IF;

    RETURN jsonb_build_object(
        'ok', true,
        'id_vendedor', p_id_vendedor,
        'inventario_congelado', p_freeze,
        'motivo', p_motivo
    );
END;
$$;


--
-- Name: admin_set_legal_hold(uuid, boolean, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_set_legal_hold(p_target_user_id uuid, p_legal_hold boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not auth.is_db_admin() then raise exception 'Solo db_admin puede operar legal hold'; end if;
  if p_reason is null or btrim(p_reason)='' then raise exception 'reason es obligatorio'; end if;
  select to_jsonb(u) into v_before from auth.users u where u.id=p_target_user_id;
  if v_before is null then raise exception 'Usuario objetivo no existe'; end if;
  update auth.users
  set legal_hold=p_legal_hold,
      legal_hold_reason=case when p_legal_hold then p_reason else null end,
      fecha_actualizacion=now()
  where id=p_target_user_id;
  select to_jsonb(u) into v_after from auth.users u where u.id=p_target_user_id;
  perform auth.lifecycle_log_event(
    case when p_legal_hold then 'LEGAL_HOLD_SET' else 'LEGAL_HOLD_CLEAR' end,
    'warning',p_target_user_id,p_reason,v_before,v_after,
    v_before->>'lifecycle_state',v_after->>'lifecycle_state','rpc',null);
  return jsonb_build_object('id_usuario',p_target_user_id,'legal_hold',p_legal_hold);
end;
$$;


--
-- Name: admin_set_override_flag(uuid, text, boolean, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_set_override_flag(p_id_vendedor uuid, p_flag text, p_valor boolean, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor      uuid;
    v_flags_ant  jsonb;
    v_flags_nuevo jsonb;
BEGIN
    v_actor := auth.fn_current_user_id();
    IF (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role') != 'db_admin' THEN
        RAISE EXCEPTION 'solo_admin' USING ERRCODE = '42501';
    END IF;

    -- Obtener flags actuales
    SELECT override_flags INTO v_flags_ant
    FROM auth.membresias_vendedor
    WHERE id_vendedor = p_id_vendedor AND estado IN ('activo', 'grace_period') AND fecha_eliminacion IS NULL
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'vendedor_sin_membresia_activa: %', p_id_vendedor USING ERRCODE = 'P0001';
    END IF;

    v_flags_nuevo := COALESCE(v_flags_ant, '{}'::jsonb) || jsonb_build_object(p_flag, p_valor);

    UPDATE auth.membresias_vendedor
    SET override_flags = v_flags_nuevo
    WHERE id_vendedor = p_id_vendedor
      AND estado IN ('activo', 'grace_period')
      AND fecha_eliminacion IS NULL;

    -- Auditoría
    INSERT INTO auth.h_vendedores_audit (id_usuario, operacion, datos_anteriores, datos_nuevos, motivo, modificado_por)
    VALUES (p_id_vendedor, 'UPDATE',
            jsonb_build_object('override_flags', v_flags_ant),
            jsonb_build_object('override_flags', v_flags_nuevo, 'flag', p_flag, 'valor', p_valor),
            COALESCE(p_motivo, 'Override flag: ' || p_flag || '=' || p_valor::text),
            v_actor);

    RETURN jsonb_build_object(
        'override_aplicado', true,
        'flag',              p_flag,
        'valor',             p_valor,
        'override_flags',    v_flags_nuevo
    );
END;
$$;


--
-- Name: admin_set_perfil_activo(uuid, boolean, text, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_set_perfil_activo(p_id_vendedor uuid, p_activo boolean, p_motivo text, p_admin_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_admin    uuid;
  v_anterior boolean;
BEGIN
  -- V2: fn_current_user_id() canónico + is_db_admin()
  v_admin := COALESCE(p_admin_id, auth.fn_current_user_id());
  IF NOT auth.is_db_admin() AND p_admin_id IS NULL THEN
    RAISE EXCEPTION 'Solo administradores' USING ERRCODE='42501';
  END IF;
  IF p_motivo IS NULL OR trim(p_motivo)='' THEN
    RAISE EXCEPTION 'Motivo requerido' USING ERRCODE='P0001';
  END IF;

  SELECT activo INTO v_anterior
  FROM auth.perfiles_publicos_vendedor WHERE id_vendedor=p_id_vendedor;
  IF v_anterior IS NULL THEN
    RAISE EXCEPTION 'Vendedor no encontrado' USING ERRCODE='P0002';
  END IF;

  UPDATE auth.perfiles_publicos_vendedor
  SET activo=p_activo,
      disponible_ahora=CASE WHEN NOT p_activo THEN false ELSE disponible_ahora END,
      fecha_modificacion=now()
  WHERE id_vendedor=p_id_vendedor;

  IF NOT p_activo THEN
    UPDATE auth.sesiones_operativas_vendedor
    SET fin_sesion=now(), motivo_cierre='admin', cerrado_por=v_admin
    WHERE id_vendedor=p_id_vendedor AND fin_sesion IS NULL;
    UPDATE auth.sesiones_tokens SET revocado=true
    WHERE id_usuario=p_id_vendedor AND revocado=false AND fecha_expiracion>now();
  END IF;

  INSERT INTO auth.h_vendedores_audit(id_usuario,operacion,datos_anteriores,datos_nuevos,modificado_por,motivo)
  VALUES (p_id_vendedor,
    CASE WHEN p_activo THEN 'UPDATE' ELSE 'SUSPEND' END,
    jsonb_build_object('activo',v_anterior),
    jsonb_build_object('activo',p_activo,'admin',v_admin),
    v_admin, p_motivo);

  RETURN jsonb_build_object(
    'id_vendedor',p_id_vendedor,'activo',p_activo,'admin',v_admin,'timestamp',now());
END;
$$;


--
-- Name: admin_set_perfil_verificado(uuid, boolean, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_set_perfil_verificado(p_id_vendedor uuid, p_verificado boolean, p_tipo text DEFAULT 'identidad_documento'::text, p_notas text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_admin uuid;
BEGIN
  IF COALESCE(auth.get_request_jwt_claims() ->> 'role', '') <> 'db_admin' THEN
    RAISE EXCEPTION 'solo_db_admin_puede_verificar_perfil';
  END IF;

  v_admin := auth.current_jwt_user_id();

  -- Historial de verificación
  INSERT INTO auth.perfil_verificaciones
    (id_vendedor, id_admin, accion, tipo, notas)
  VALUES (
    p_id_vendedor, v_admin,
    CASE WHEN p_verificado THEN 'verificado' ELSE 'revocado' END,
    p_tipo, p_notas
  );

  -- Actualizar perfil
  PERFORM set_config('app.audit_reason',
    CASE WHEN p_verificado THEN 'perfil_verificado' ELSE 'verificacion_revocada' END, true);

  UPDATE auth.perfiles_publicos_vendedor
     SET verificado      = p_verificado,
         verificado_at   = CASE WHEN p_verificado THEN now() ELSE NULL END,
         fecha_modificacion = now()
   WHERE id_vendedor = p_id_vendedor;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'perfil_publico_no_encontrado: %', p_id_vendedor;
  END IF;

  PERFORM set_config('app.audit_reason', '', true);

  RETURN jsonb_build_object(
    'ok', true,
    'id_vendedor', p_id_vendedor,
    'verificado', p_verificado,
    'tipo', p_tipo
  );
END;
$$;


--
-- Name: admin_set_seller_profile_active(uuid, boolean, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_set_seller_profile_active(p_target_user_id uuid, p_activo boolean, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'ag_catalog'
    AS $$
DECLARE
  v_caller uuid;
  v_before jsonb;
  v_after  jsonb;
BEGIN
  v_caller := auth.fn_current_user_id();

  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id=v_caller AND role='db_admin') THEN
    RAISE EXCEPTION 'Solo db_admin puede ejecutar gobernanza de perfil' USING ERRCODE = 'P0601';
  END IF;

  -- Target debe ser seller
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id=p_target_user_id AND role='seller') THEN
    RAISE EXCEPTION 'Target no es vendedor' USING ERRCODE = 'P0602';
  END IF;

  SELECT to_jsonb(ppv.*) INTO v_before
  FROM auth.perfiles_publicos_vendedor ppv
  WHERE ppv.id_vendedor = p_target_user_id;

  IF v_before IS NULL THEN
    RAISE EXCEPTION 'Perfil público del target inexistente' USING ERRCODE = 'P0600';
  END IF;

  UPDATE auth.perfiles_publicos_vendedor
  SET activo            = p_activo,
      disponible_ahora  = CASE WHEN p_activo THEN disponible_ahora ELSE false END,
      disponible_hasta  = CASE WHEN NOT p_activo THEN now() ELSE disponible_hasta END,
      fecha_modificacion = now()
  WHERE id_vendedor = p_target_user_id;

  SELECT to_jsonb(ppv.*) INTO v_after
  FROM auth.perfiles_publicos_vendedor ppv
  WHERE ppv.id_vendedor = p_target_user_id;

  INSERT INTO auth.h_vendedores_audit (
    id_usuario, operacion, datos_anteriores, datos_nuevos, modificado_por, motivo
  ) VALUES (
    p_target_user_id,
    CASE WHEN p_activo THEN 'ADMIN_REACTIVATE' ELSE 'ADMIN_SUSPEND' END,
    v_before, v_after, v_caller,
    COALESCE(p_motivo, 'admin_set_seller_profile_active')
  );

  -- Revocación de sesiones al suspender
  IF NOT p_activo THEN
    BEGIN
      UPDATE auth.sesiones_tokens
      SET revocado = true
      WHERE id_usuario = p_target_user_id AND revocado = false;
    EXCEPTION WHEN undefined_table THEN NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'target_user_id',  p_target_user_id,
    'perfil_activo',   p_activo,
    'suspended_by',    v_caller,
    'changed_at',      now()
  );
END;
$$;


--
-- Name: admin_set_user_membership(uuid, text, timestamp with time zone, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_set_user_membership(p_target_user_id uuid, p_tier_code text, p_starts_at timestamp with time zone DEFAULT now(), p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not auth.is_db_admin() then raise exception 'Solo db_admin puede asignar membresías'; end if;
  select to_jsonb(u) into v_before from auth.users u where u.id=p_target_user_id;
  if v_before is null then raise exception 'Usuario objetivo no existe'; end if;

  update auth.user_service_memberships set estado='expired', fecha_actualizacion=now()
  where id_usuario=p_target_user_id and estado='active';

  insert into auth.user_service_memberships(id_usuario,tier_code,estado,inicia_en,ends_at,assigned_by,reason,metadata)
  values (p_target_user_id,p_tier_code,'active',coalesce(p_starts_at,now()),p_ends_at,
    auth.fn_current_user_id(),p_reason,coalesce(p_metadata,'{}'::jsonb));

  select to_jsonb(u) into v_after from auth.users u where u.id=p_target_user_id;
  perform auth.lifecycle_log_event('TIER_CHANGED','info',p_target_user_id,p_reason,v_before,v_after,
    u.lifecycle_state,u.lifecycle_state,'rpc',null)
  from auth.users u where u.id=p_target_user_id;

  return jsonb_build_object('id_usuario',p_target_user_id,
    'effective_tier',auth.resolve_effective_tier(p_target_user_id,now()));
end;
$$;


--
-- Name: admin_soft_delete_categoria_global(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_soft_delete_categoria_global(p_categoria_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
declare v_actor_id uuid; v_before jsonb; v_after jsonb;
begin
  v_actor_id := auth.fn_current_user_id();
  if auth.fn_current_user_role() <> 'db_admin' then raise exception 'admin_role_required'; end if;
  if p_reason is null or btrim(p_reason) = '' then raise exception 'reason_required'; end if;

  select to_jsonb(cg) into v_before from auth.categorias_globales cg where cg.id = p_categoria_id for update;
  if v_before is null then raise exception 'categoria_global_not_found'; end if;

  update auth.categorias_globales
  set activo=false, fecha_eliminacion=coalesce(fecha_eliminacion,now()),
      deleted_by=coalesce(deleted_by,v_actor_id), delete_reason=coalesce(delete_reason,p_reason)
  where id = p_categoria_id;

  select to_jsonb(cg) into v_after from auth.categorias_globales cg where cg.id = p_categoria_id;
  perform auth.fn_write_publicacion_audit(null,'ADMIN_SOFT_DELETE_CATEGORIA_GLOBAL',p_reason,v_before,v_after);
  return jsonb_build_object('categoria_global_id', p_categoria_id, 'deleted', true, 'data', v_after);
end; $$;


--
-- Name: admin_soft_delete_user(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_soft_delete_user(p_target_user_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
declare
  v_before jsonb; v_after jsonb;
  v_policy auth.v_user_effective_lifecycle_policy%rowtype;
  v_strategy text;
begin
  if not auth.is_db_admin() then raise exception 'Solo db_admin puede ejecutar soft delete' USING ERRCODE = 'K4030'; end if;
  if p_reason is null or btrim(p_reason)='' then raise exception 'reason es obligatorio'; end if;
  if auth.fn_current_user_id() = p_target_user_id then
    raise exception 'No se permite auto-soft-delete administrativo'; end if;

  select to_jsonb(u) into v_before from auth.users u where u.id=p_target_user_id;
  if v_before is null then raise exception 'Usuario objetivo no existe'; end if;

  select * into v_policy from auth.v_user_effective_lifecycle_policy v where v.id_usuario=p_target_user_id;

  update auth.users
  set activo=false, lifecycle_state='soft_deleted',
      fecha_eliminacion=coalesce(fecha_eliminacion,now()),
      deleted_by=coalesce(deleted_by,auth.fn_current_user_id()),
      deleted_reason=coalesce(deleted_reason,p_reason),
      elegible_purga_en=coalesce(elegible_purga_en,now()+make_interval(days=>v_policy.retention_days)),
      fecha_actualizacion=now()
  where id=p_target_user_id;

  if v_policy.auto_revoke_sessions then
    update auth.sesiones_tokens set revocado=true where id_usuario=p_target_user_id and revocado=false;
  end if;

  update auth.perfiles_publicos_vendedor
  set activo=false, fecha_modificacion=now() where id_vendedor=p_target_user_id;

  update auth.ubicaciones
  set estado='inactivo', fecha_actualizacion=now()
  where id_usuario=p_target_user_id and estado='activo';

  v_strategy := case
    when auth.user_requires_anonymization(p_target_user_id) then 'anonymize_after_retention'
    else 'purge_if_still_dependency_free'
  end;

  insert into auth.user_purge_queue(
    target_user_id,target_role,target_effective_tier,strategy,estado,eligible_at,requested_by)
  select u.id, u.role, auth.resolve_effective_tier(u.id,now()),
    v_strategy, 'pending',
    coalesce(u.elegible_purga_en,now()+interval '1 day'),
    auth.fn_current_user_id()
  from auth.users u where u.id=p_target_user_id
  ON CONFLICT (target_user_id, estado) do nothing;

  select to_jsonb(u) into v_after from auth.users u where u.id=p_target_user_id;
  perform auth.lifecycle_log_event('SOFT_DELETE','warning',p_target_user_id,p_reason,
    v_before,v_after,v_before->>'lifecycle_state',v_after->>'lifecycle_state','rpc',null);
  perform auth.sync_user_lifecycle_projection(p_target_user_id,'SOFT_DELETE');

  return jsonb_build_object('id_usuario',p_target_user_id,'lifecycle_state','soft_deleted',
    'strategy',v_strategy,
    'purge_eligible_at',(select elegible_purga_en from auth.users where id=p_target_user_id));
end;
$$;


--
-- Name: admin_suspend_membresia(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_suspend_membresia(p_id_vendedor uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid;
    v_rows  integer;
BEGIN
    v_actor := auth.fn_current_user_id();
    IF (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role') != 'db_admin' THEN
        RAISE EXCEPTION 'solo_admin: solo administradores pueden suspender membresías'
        USING ERRCODE = '42501';
    END IF;

    IF p_motivo IS NULL OR length(trim(p_motivo)) < 10 THEN
        RAISE EXCEPTION 'motivo_requerido: se requiere motivo descriptivo (min 10 chars)'
        USING ERRCODE = '22023';
    END IF;

    UPDATE auth.membresias_vendedor
    SET estado = 'suspendida'
    WHERE id_vendedor = p_id_vendedor
      AND estado IN ('activo', 'grace_period')
      AND fecha_eliminacion IS NULL;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        RETURN jsonb_build_object('warning', 'sin_membresia_activa', 'id_vendedor', p_id_vendedor);
    END IF;

    -- Auditoría con operacion SUSPEND
    INSERT INTO auth.h_vendedores_audit (id_usuario, operacion, datos_nuevos, motivo, modificado_por)
    VALUES (p_id_vendedor, 'SUSPEND',
            jsonb_build_object('estado', 'suspendida', 'actor', v_actor),
            p_motivo, v_actor);

    RETURN jsonb_build_object('suspendido', true, 'id_vendedor', p_id_vendedor, 'motivo', p_motivo);
END;
$$;


--
-- Name: admin_upsert_categoria_global(uuid, uuid, text, text, text, smallint, boolean, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_upsert_categoria_global(p_categoria_id uuid DEFAULT NULL::uuid, p_parent_id uuid DEFAULT NULL::uuid, p_nombre text DEFAULT NULL::text, p_slug text DEFAULT NULL::text, p_descripcion text DEFAULT NULL::text, p_nivel smallint DEFAULT 1, p_activo boolean DEFAULT true, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
declare
  v_before jsonb; v_after jsonb; v_id uuid;
begin
  if auth.fn_current_user_role() <> 'db_admin' then raise exception 'admin_role_required'; end if;
  if p_nombre is null or btrim(p_nombre) = '' then raise exception 'nombre_required'; end if;
  if p_slug   is null or btrim(p_slug)   = '' then raise exception 'slug_required';   end if;
  if jsonb_typeof(coalesce(p_metadata, '{}')) <> 'object' then raise exception 'metadata_must_be_object'; end if;

  if p_categoria_id is null then
    insert into auth.categorias_globales (parent_id,nombre,slug,descripcion,nivel,metadata,activo)
    values (p_parent_id, btrim(p_nombre), lower(btrim(p_slug)), nullif(btrim(coalesce(p_descripcion,'')), ''),
            coalesce(p_nivel,1), coalesce(p_metadata,'{}'), coalesce(p_activo,true))
    returning id into v_id;
  else
    select to_jsonb(cg) into v_before from auth.categorias_globales cg where cg.id = p_categoria_id for update;
    if v_before is null then raise exception 'categoria_global_not_found'; end if;
    update auth.categorias_globales
    set parent_id=p_parent_id, nombre=btrim(p_nombre), slug=lower(btrim(p_slug)),
        descripcion=nullif(btrim(coalesce(p_descripcion,'')), ''), nivel=coalesce(p_nivel,nivel),
        metadata=coalesce(p_metadata,metadata), activo=coalesce(p_activo,activo),
        fecha_eliminacion=null, deleted_by=null, delete_reason=null
    where id = p_categoria_id returning id into v_id;
  end if;

  select to_jsonb(cg) into v_after from auth.categorias_globales cg where cg.id = v_id;
  perform auth.fn_write_publicacion_audit(null,'ADMIN_UPSERT_CATEGORIA_GLOBAL',null,v_before,v_after);
  return jsonb_build_object('categoria_global_id', v_id, 'data', v_after);
end; $$;


--
-- Name: admin_upsert_tier_policy(text, text, integer, integer, boolean, boolean, boolean, boolean, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.admin_upsert_tier_policy(p_role text, p_tier_code text, p_retention_days integer, p_anonymize_after_days integer, p_allow_physical_purge boolean, p_require_manual_review boolean, p_require_identity_verification boolean, p_auto_revoke_sessions boolean, p_admin_flags jsonb DEFAULT '{}'::jsonb, p_frontend_flags jsonb DEFAULT '{}'::jsonb, p_verification_rules jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
begin
  if not auth.is_db_admin() then raise exception 'Solo db_admin puede modificar políticas'; end if;
  insert into auth.service_tier_policies(
    role,tier_code,retention_days,anonymize_after_days,allow_physical_purge,
    require_manual_review,require_identity_verification,auto_revoke_sessions,
    admin_flags,frontend_flags,verification_rules,updated_by
  ) values (
    p_role,p_tier_code,p_retention_days,p_anonymize_after_days,p_allow_physical_purge,
    p_require_manual_review,p_require_identity_verification,p_auto_revoke_sessions,
    coalesce(p_admin_flags,'{}'::jsonb),coalesce(p_frontend_flags,'{}'::jsonb),
    coalesce(p_verification_rules,'{}'::jsonb),auth.fn_current_user_id()
  )
  ON CONFLICT (role, tier_code) do update
  set retention_days=excluded.retention_days, anonymize_after_days=excluded.anonymize_after_days,
      allow_physical_purge=excluded.allow_physical_purge, require_manual_review=excluded.require_manual_review,
      require_identity_verification=excluded.require_identity_verification,
      auto_revoke_sessions=excluded.auto_revoke_sessions, admin_flags=excluded.admin_flags,
      frontend_flags=excluded.frontend_flags, verification_rules=excluded.verification_rules,
      updated_by=excluded.updated_by, fecha_actualizacion=now(), is_active=true;
  return jsonb_build_object('role',p_role,'tier_code',p_tier_code,'updated',true);
end;
$$;


--
-- Name: age_backfill_graph(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.age_backfill_graph() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ag_catalog', 'auth', 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_batch_size  CONSTANT INT := 100;
    v_offset      INT := 0;
    v_payload     TEXT;
    v_users       INT := 0;
    v_mails       INT := 0;
    v_batch_count INT;
    v_t0          TIMESTAMPTZ;
BEGIN
    LOAD 'age';
    SET LOCAL search_path = ag_catalog, auth, public, pg_catalog;

    v_t0 := clock_timestamp();

    -- ── 1. Pre-crear nodos UseCase estables (4 llamadas individuales) ─────
    -- AGE no soporta SET en múltiples nodos encadenados via WITH en una sola
    -- query → error "Entity failed to be updated: N". Se hacen 4 MERGE por
    -- separado: cada uno ~2ms, total < 10ms, cero WARNING.
    BEGIN
        EXECUTE $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
            MERGE (u:UseCase {slug: 'register_user'})
            SET u.name='Registro de usuario', u.source='smtp-posix-core'
            RETURN u
        $c$) AS (r ag_catalog.agtype)$q$;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'UseCase register_user falló: %', SQLERRM;
    END;

    BEGIN
        EXECUTE $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
            MERGE (u:UseCase {slug: 'login_user'})
            SET u.name='Inicio de sesion', u.source='smtp-posix-core'
            RETURN u
        $c$) AS (r ag_catalog.agtype)$q$;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'UseCase login_user falló: %', SQLERRM;
    END;

    BEGIN
        EXECUTE $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
            MERGE (u:UseCase {slug: 'verify_otp'})
            SET u.name='Verificacion OTP', u.source='smtp-posix-core'
            RETURN u
        $c$) AS (r ag_catalog.agtype)$q$;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'UseCase verify_otp falló: %', SQLERRM;
    END;

    BEGIN
        EXECUTE $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
            MERGE (u:UseCase {slug: 'enqueue_mail'})
            SET u.name='Encolado de correo', u.source='smtp-posix-core'
            RETURN u
        $c$) AS (r ag_catalog.agtype)$q$;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'UseCase enqueue_mail falló: %', SQLERRM;
    END;

    RAISE NOTICE 'age_backfill_graph fase-1 (UseCases): %ms',
        round(extract(milliseconds FROM clock_timestamp() - v_t0));

    -- ── 2. UNWIND usuarios — Pass A: nodo + aristas registro/login ────────
    -- 1 llamada cypher por lote de 100 usuarios (UNWIND → sin overhead por fila)
    v_offset := 0;
    LOOP
        SELECT string_agg(
            format(
                '{uuid:%L,email:%L,role:%L,is_verified:%L,username:%L,created_at:%L}',
                id::text, email, role::text, is_verified::text,
                COALESCE(username, ''), fecha_creacion::text
            ),
            ','
        ), count(*)
        INTO v_payload, v_batch_count
        FROM (
            SELECT * FROM auth.users
            ORDER BY fecha_creacion
            LIMIT v_batch_size OFFSET v_offset
        ) batch;

        EXIT WHEN v_payload IS NULL;

        BEGIN
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    UNWIND [%s] AS ud
                    MERGE (u:User {user_uuid: ud.uuid})
                    SET u.email = ud.email,
                        u.role = ud.role,
                        u.is_verified = ud.is_verified,
                        u.username = ud.username,
                        u.created_at = ud.created_at
                    WITH u, ud
                    MATCH (uc_reg:UseCase {slug: 'register_user'})
                    WITH u, ud, uc_reg
                    MERGE (uc_reg)-[e1:CREATED_USER {role: ud.role, at: ud.created_at}]->(u)
                    WITH u, ud
                    MATCH (uc_login:UseCase {slug: 'login_user'})
                    WITH u, ud, uc_login
                    MERGE (u)-[e2:ELIGIBLE_FOR_LOGIN {is_verified: ud.is_verified, at: ud.created_at}]->(uc_login)
                    RETURN count(u) AS n
                $c$) AS (n ag_catalog.agtype)$q$,
                v_payload
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'UNWIND users lote offset=% falló: %', v_offset, SQLERRM;
        END;

        v_users  := v_users + v_batch_count;
        v_offset := v_offset + v_batch_size;
        EXIT WHEN v_batch_count < v_batch_size;
    END LOOP;

    RAISE NOTICE 'age_backfill_graph fase-2a (usuarios nodo+edges): % filas, %ms',
        v_users, round(extract(milliseconds FROM clock_timestamp() - v_t0));

    -- ── 3. UNWIND usuarios — Pass B: arista VERIFIED_BY_OTP (solo verificados)
    v_offset := 0;
    LOOP
        SELECT string_agg(
            format(
                '{uuid:%L,fecha_creacion:%L}',
                id::text, fecha_creacion::text
            ),
            ','
        ), count(*)
        INTO v_payload, v_batch_count
        FROM (
            SELECT id, fecha_creacion FROM auth.users
            WHERE is_verified = true
            ORDER BY fecha_creacion
            LIMIT v_batch_size OFFSET v_offset
        ) batch;

        EXIT WHEN v_payload IS NULL;

        BEGIN
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    UNWIND [%s] AS ud
                    MATCH (u:User {user_uuid: ud.uuid})
                    WITH u, ud
                    MATCH (uc_otp:UseCase {slug: 'verify_otp'})
                    WITH u, ud, uc_otp
                    MERGE (u)-[e:VERIFIED_BY_OTP {at: ud.created_at}]->(uc_otp)
                    RETURN count(u) AS n
                $c$) AS (n ag_catalog.agtype)$q$,
                v_payload
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'UNWIND verified lote offset=% falló: %', v_offset, SQLERRM;
        END;
        v_offset := v_offset + v_batch_size;
        EXIT WHEN v_batch_count < v_batch_size;
    END LOOP;

    RAISE NOTICE 'age_backfill_graph fase-2b (verified OTP): %ms',
        round(extract(milliseconds FROM clock_timestamp() - v_t0));

    -- ── 4. UNWIND correos — Pass A: nodo + arista QUEUED_MAIL ─────────────
    v_offset := 0;
    LOOP
        SELECT string_agg(
            format(
                '{mail_id:%L,subject:%L,recipient:%L,status:%L,owner_uuid:%L,created_at:%L,updated_at:%L}',
                mq.id::text, mq.subject, mq.recipient, mq.estado,
                COALESCE(mq.id_usuario::text,
                    (SELECT u.id::text FROM auth.users u WHERE u.email = mq.recipient LIMIT 1),
                    ''),
                mq.created_at::text,
                NOW()::text
            ),
            ','
        ), count(*)
        INTO v_payload, v_batch_count
        FROM (
            SELECT * FROM auth.mail_queue
            ORDER BY created_at
            LIMIT v_batch_size OFFSET v_offset
        ) mq;

        EXIT WHEN v_payload IS NULL;

        BEGIN
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    UNWIND [%s] AS md
                    MERGE (m:Mail {mail_id: md.mail_id})
                    SET m.subject    = md.subject,
                        m.recipient  = md.recipient,
                        m.status     = md.status,
                        m.owner_uuid = md.owner_uuid,
                        m.created_at = md.created_at,
                        m.updated_at = md.updated_at
                    WITH m, md
                    MATCH (uc:UseCase {slug: 'enqueue_mail'})
                    WITH m, md, uc
                    MERGE (uc)-[e:QUEUED_MAIL {status: md.status, at: md.created_at}]->(m)
                    RETURN count(m) AS n
                $c$) AS (n ag_catalog.agtype)$q$,
                v_payload
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'UNWIND mails lote offset=% falló: %', v_offset, SQLERRM;
        END;

        v_mails  := v_mails + v_batch_count;
        v_offset := v_offset + v_batch_size;
        EXIT WHEN v_batch_count < v_batch_size;
    END LOOP;

    RAISE NOTICE 'age_backfill_graph fase-3a (correos nodo+edges): % filas, %ms',
        v_mails, round(extract(milliseconds FROM clock_timestamp() - v_t0));

    -- ── 5. UNWIND correos — Pass B: arista OWNS_MAIL (solo correos con owner)
    v_offset := 0;
    LOOP
        SELECT string_agg(
            format(
                '{owner_uuid:%L,mail_id:%L,recipient:%L}',
                COALESCE(mq.id_usuario::text,
                    (SELECT u.id::text FROM auth.users u WHERE u.email = mq.recipient LIMIT 1)),
                mq.id::text,
                mq.recipient
            ),
            ','
        )
        INTO v_payload
        FROM (
            SELECT mq2.*
            FROM auth.mail_queue mq2
            WHERE mq2.id_usuario IS NOT NULL
               OR EXISTS (
                   SELECT 1 FROM auth.users u WHERE u.email = mq2.recipient LIMIT 1
               )
            ORDER BY mq2.created_at
            LIMIT v_batch_size OFFSET v_offset
        ) mq;

        EXIT WHEN v_payload IS NULL;

        BEGIN
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    UNWIND [%s] AS md
                    MATCH (u:User {user_uuid: md.owner_uuid}), (m:Mail {mail_id: md.mail_id})
                    MERGE (u)-[e:OWNS_MAIL {recipient: md.recipient}]->(m)
                    RETURN count(e) AS n
                $c$) AS (n ag_catalog.agtype)$q$,
                v_payload
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'UNWIND OWNS_MAIL lote offset=% falló: %', v_offset, SQLERRM;
        END;

        v_offset := v_offset + v_batch_size;
    END LOOP;

    RAISE NOTICE 'age_backfill_graph fase-3b (OWNS_MAIL): %ms total',
        round(extract(milliseconds FROM clock_timestamp() - v_t0));

    RETURN jsonb_build_object(
        'users_backfilled', v_users,
        'mails_backfilled', v_mails
    );
END;
$_$;


--
-- Name: FUNCTION age_backfill_graph(); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.age_backfill_graph() IS 'v4: UNWIND batch + 4 MERGE independientes en fase-1 (AGE no soporta WITH-chain multi-label SET). Sin WARNING, fase-1 < 10ms.';


--
-- Name: age_graph_stats(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.age_graph_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ag_catalog', 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_role   TEXT;
    v_result JSONB;
BEGIN
    v_role := COALESCE(current_setting('request.jwt.claims', true)::JSONB ->> 'role', '');

    IF v_role <> 'db_admin' THEN
        RAISE EXCEPTION 'Acceso denegado: solo db_admin' USING ERRCODE = '42501';
    END IF;

    LOAD 'age';
    SET LOCAL search_path = ag_catalog, auth, public, pg_catalog;

    -- Acceso directo a tablas de label (sin full Cypher scan — evita timeout en grafos grandes)
    SELECT jsonb_build_object(
        'total_vertices',   (SELECT SUM(cnt) FROM (
                               SELECT COUNT(*)::INT AS cnt FROM smtp_posix_graph."User"
                               UNION ALL SELECT COUNT(*)::INT FROM smtp_posix_graph."Mail"
                               UNION ALL SELECT COUNT(*)::INT FROM smtp_posix_graph."UseCase"
                            ) s),
        'total_edges',      (SELECT COUNT(*)::INT FROM smtp_posix_graph._ag_label_edge),
        'user_vertices',    (SELECT COUNT(*)::INT FROM smtp_posix_graph."User"),
        'mail_vertices',    (SELECT COUNT(*)::INT FROM smtp_posix_graph."Mail"),
        'usecase_vertices', (SELECT COUNT(*)::INT FROM smtp_posix_graph."UseCase"),
        'graph_name',       'smtp_posix_graph'
    ) INTO v_result;

    RETURN v_result;
END;
$$;


--
-- Name: FUNCTION age_graph_stats(); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.age_graph_stats() IS 'Estadísticas del grafo AGE (acceso directo por tabla, sin full Cypher scan). Solo db_admin. Parche: 62_fix_age_graph_stats_performance.sql';


--
-- Name: age_mail_journey(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.age_mail_journey(p_mail_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ag_catalog', 'auth', 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_role        TEXT;
    v_jwt_user_id UUID;
    v_owner_uuid  TEXT;
    v_result      JSONB;
BEGIN
    v_role        := COALESCE(current_setting('request.jwt.claims', true)::JSONB ->> 'role', '');
    v_jwt_user_id := NULLIF(
        COALESCE(current_setting('request.jwt.claims', true)::JSONB ->> 'sub', ''),
        ''
    )::UUID;

    IF v_role NOT IN ('buyer', 'seller', 'db_admin') THEN
        RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
    END IF;

    IF v_role IN ('buyer', 'seller') THEN
        SELECT id_usuario::text INTO v_owner_uuid
        FROM auth.mail_queue
        WHERE id = p_mail_id;

        IF v_owner_uuid IS DISTINCT FROM v_jwt_user_id::text THEN
            RAISE EXCEPTION 'Acceso denegado: el correo no pertenece al usuario actual' USING ERRCODE = '42501';
        END IF;
    END IF;

    LOAD 'age';
    SET LOCAL search_path = ag_catalog, auth, public, pg_catalog;

    EXECUTE format(
        $q$SELECT jsonb_agg(
               jsonb_build_object(
                   'mail',     agtype_out(m)::text,
                   'edge',     agtype_out(e)::text,
                   'neighbor', agtype_out(n)::text
               )
           )
           FROM ag_catalog.cypher('smtp_posix_graph', $c$
               MATCH (m:Mail {mail_id: %s})-[e]-(n)
               RETURN m, e, n
           $c$) AS (m ag_catalog.agtype, e ag_catalog.agtype, n ag_catalog.agtype)$q$,
        p_mail_id::text
    ) INTO v_result;

    RETURN COALESCE(v_result, '[]'::JSONB);
END;
$_$;


--
-- Name: FUNCTION age_mail_journey(p_mail_id integer); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.age_mail_journey(p_mail_id integer) IS '[fix-12] Journey Cypher de un correo. agtype_out() para compat AGE 1.7.0-rc0.';


--
-- Name: age_run_cypher(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.age_run_cypher(p_cypher text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ag_catalog', 'auth', 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_role   TEXT;
    v_result JSONB;
BEGIN
    v_role := COALESCE(current_setting('request.jwt.claims', true)::JSONB ->> 'role', '');

    IF v_role <> 'db_admin' THEN
        RAISE EXCEPTION 'Acceso denegado: solo db_admin' USING ERRCODE = '42501';
    END IF;

    -- Prevenir escrituras destructivas desde la API (solo MATCH permitido)
    IF lower(p_cypher) ~ '\y(create|merge|delete|detach|set|remove|drop)\y' THEN
        RAISE EXCEPTION 'Solo consultas MATCH permitidas via RPC' USING ERRCODE = '42501';
    END IF;

    LOAD 'age';
    SET LOCAL search_path = ag_catalog, auth, public, pg_catalog;

    EXECUTE format(
        $q$SELECT jsonb_agg(jsonb_build_object('r', agtype_out(result)::text))
           FROM ag_catalog.cypher('smtp_posix_graph', $c$%s$c$)
                AS (result ag_catalog.agtype)
           LIMIT 500$q$,
        p_cypher
    ) INTO v_result;

    RETURN COALESCE(v_result, '[]'::JSONB);
END;
$_$;


--
-- Name: FUNCTION age_run_cypher(p_cypher text); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.age_run_cypher(p_cypher text) IS '[fix-12] Cypher MATCH en smtp_posix_graph. agtype_out() para compat AGE 1.7.0-rc0. Max 500 filas. Mutaciones bloqueadas.';


--
-- Name: age_sync_disponibilidad(uuid, boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.age_sync_disponibilidad(p_id_vendedor uuid, p_disponible boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $_$
DECLARE v_graph text;
BEGIN
  SELECT name INTO v_graph FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;
  IF v_graph IS NULL THEN RETURN; END IF;
  EXECUTE format(
    'SELECT * FROM cypher(%L, $c$MATCH (u:User {id: "%s"}) SET u.disponible_ahora = %s, u.ultima_disponibilidad = "%s"$c$) AS (v agtype)',
    v_graph, p_id_vendedor, p_disponible, now());
EXCEPTION WHEN OTHERS THEN NULL;
END;
$_$;


--
-- Name: age_sync_ubicacion(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.age_sync_ubicacion(p_id_vendedor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $_$
DECLARE
  v_graph text;
  v_lat double precision;
  v_lon double precision;
  v_ubicacion_id uuid;
BEGIN
  SELECT name INTO v_graph FROM ag_catalog.ag_graph WHERE name = 'smtp_posix_graph';
  IF v_graph IS NULL THEN
    RAISE NOTICE 'Grafo smtp_posix_graph no disponible';
    RETURN;
  END IF;

  SELECT ub.id, ub.latitud, ub.longitud
  INTO v_ubicacion_id, v_lat, v_lon
  FROM auth.ubicaciones ub
  WHERE ub.id_usuario = p_id_vendedor
    AND ub.is_active IS NOT FALSE
    AND ub.fecha_eliminacion IS NULL
  ORDER BY ub.es_principal DESC NULLS LAST, ub.fecha_actualizacion DESC NULLS LAST
  LIMIT 1;

  IF v_ubicacion_id IS NULL OR v_lat IS NULL OR v_lon IS NULL THEN
    RAISE NOTICE 'Vendedor % no tiene ubicación activa con coordenadas', p_id_vendedor;
    RETURN;
  END IF;

  EXECUTE format(
    'SELECT * FROM cypher(%L, $c$
      MATCH (u:User {id: %L})
      SET u.ubicacion_id = %L,
          u.latitud = %s,
          u.longitud = %s,
          u.ultima_sync_ubicacion = timestamp()
    $c$) AS (v agtype)',
    v_graph, p_id_vendedor::text, v_ubicacion_id::text, v_lat, v_lon
  );
END;
$_$;


--
-- Name: age_use_case_graph(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.age_use_case_graph() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ag_catalog', 'auth', 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_role   TEXT;
    v_result JSONB;
BEGIN
    v_role := COALESCE(current_setting('request.jwt.claims', true)::JSONB ->> 'role', '');

    IF v_role NOT IN ('buyer', 'seller', 'db_admin') THEN
        RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
    END IF;

    LOAD 'age';
    SET LOCAL search_path = ag_catalog, auth, public, pg_catalog;

    SELECT jsonb_agg(
        jsonb_build_object(
            'use_case', agtype_out(uc)::text,
            'edge',     agtype_out(e)::text,
            'neighbor', agtype_out(n)::text
        )
    )
    INTO v_result
    FROM ag_catalog.cypher('smtp_posix_graph', $cy$
        MATCH (uc:UseCase)-[e]-(n)
        RETURN uc, e, n
    $cy$) AS (uc ag_catalog.agtype, e ag_catalog.agtype, n ag_catalog.agtype);

    RETURN COALESCE(v_result, '[]'::JSONB);
END;
$_$;


--
-- Name: FUNCTION age_use_case_graph(); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.age_use_case_graph() IS '[fix-12] Devuelve todas las aristas del grafo de casos de uso. agtype_out() para compat AGE 1.7.0-rc0.';


--
-- Name: age_user_neighborhood(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.age_user_neighborhood(p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ag_catalog', 'auth', 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_role        TEXT;
    v_jwt_user_id UUID;
    v_target      UUID;
    v_result      JSONB;
BEGIN
    v_role        := COALESCE(current_setting('request.jwt.claims', true)::JSONB ->> 'role', '');
    v_jwt_user_id := NULLIF(
        COALESCE(current_setting('request.jwt.claims', true)::JSONB ->> 'sub', ''),
        ''
    )::UUID;

    IF v_role NOT IN ('buyer', 'seller', 'db_admin') THEN
        RAISE EXCEPTION 'Acceso denegado: rol insuficiente' USING ERRCODE = '42501';
    END IF;

    IF v_role IN ('buyer', 'seller') THEN
        v_target := COALESCE(p_user_id, v_jwt_user_id);
        IF v_target IS DISTINCT FROM v_jwt_user_id THEN
            RAISE EXCEPTION 'Acceso denegado: solo puedes consultar tu propio grafo' USING ERRCODE = '42501';
        END IF;
    ELSE
        v_target := COALESCE(p_user_id, v_jwt_user_id);
    END IF;

    IF v_target IS NULL THEN
        RETURN '{"error": "Se requiere p_user_id o JWT sub"}'::JSONB;
    END IF;

    LOAD 'age';
    SET LOCAL search_path = ag_catalog, auth, public, pg_catalog;

    EXECUTE format(
        $q$SELECT jsonb_agg(
               jsonb_build_object(
                   'vertex',   agtype_out(u)::text,
                   'edge',     agtype_out(e)::text,
                   'neighbor', agtype_out(n)::text
               )
           )
           FROM ag_catalog.cypher('smtp_posix_graph', $c$
               MATCH (u:User {user_uuid: %L})-[e]-(n)
               RETURN u, e, n
           $c$) AS (u ag_catalog.agtype, e ag_catalog.agtype, n ag_catalog.agtype)$q$,
        v_target::text
    ) INTO v_result;

    RETURN COALESCE(v_result, '[]'::JSONB);
END;
$_$;


--
-- Name: FUNCTION age_user_neighborhood(p_user_id uuid); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.age_user_neighborhood(p_user_id uuid) IS '[fix-12] Vecindario Cypher de un usuario. agtype_out() para compat AGE 1.7.0-rc0.';


--
-- Name: aplicar_promocion(uuid, uuid, numeric); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.aplicar_promocion(p_intercambio_id uuid, p_promocion_id uuid, p_valor_aplicado numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_row auth.promociones_aplicadas;
BEGIN
    v_row := auth.fn_aplicar_promocion(
        p_intercambio_id  := p_intercambio_id,
        p_promocion_id    := p_promocion_id,
        p_valor_aplicado  := p_valor_aplicado
    );

    RETURN jsonb_build_object(
        'id',               v_row.id,
        'intercambio_id',   v_row.intercambio_id,
        'promocion_id',     v_row.promocion_id,
        'id_usuario',       v_row.id_usuario,
        'valor_aplicado',   v_row.valor_aplicado,
        'puntos_otorgados', v_row.puntos_otorgados,
        'aplicada_en',      v_row.aplicada_en
    );
END;
$$;


--
-- Name: apply_auth_schema_sanity_hardening(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.apply_auth_schema_sanity_hardening() RETURNS TABLE(rls_enabled_count integer, fk_validated_count integer, users_trigger_recreated boolean, query_graph_trigger_recreated boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
  rec RECORD;
  v_rls_enabled_count INTEGER := 0;
  v_fk_validated_count INTEGER := 0;
  v_users_trigger_recreated BOOLEAN := FALSE;
  v_query_graph_trigger_recreated BOOLEAN := FALSE;
BEGIN
  -- 1) Habilitar RLS en cualquier tabla auth que ya tenga policies definidas y RLS apagado.
  FOR rec IN
    SELECT n.nspname, c.relname
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'auth'
      AND c.relkind = 'r'
      AND NOT c.relrowsecurity
      AND EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = c.oid)
  LOOP
    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', rec.nspname, rec.relname);
    v_rls_enabled_count := v_rls_enabled_count + 1;
  END LOOP;

  -- 2) Validar FKs no validadas en auth.
  FOR rec IN
    SELECT n.nspname, c.relname, con.conname
    FROM pg_constraint con
    JOIN pg_class c ON c.oid = con.conrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'auth'
      AND con.contype = 'f'
      AND NOT con.convalidated
  LOOP
    EXECUTE format('ALTER TABLE %I.%I VALIDATE CONSTRAINT %I', rec.nspname, rec.relname, rec.conname);
    v_fk_validated_count := v_fk_validated_count + 1;
  END LOOP;

  -- 3) Reafirmar trigger users->query_graph si falta.
  IF NOT EXISTS (
    SELECT 1
    FROM pg_trigger t
    JOIN pg_class c ON c.oid = t.tgrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'auth'
      AND c.relname = 'users'
      AND t.tgname = 'trg_users_query_graph_sync'
      AND NOT t.tgisinternal
  ) THEN
    EXECUTE 'CREATE TRIGGER trg_users_query_graph_sync AFTER INSERT OR UPDATE ON auth.users FOR EACH ROW EXECUTE FUNCTION auth.trg_users_query_graph_sync()';
    v_users_trigger_recreated := TRUE;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_trigger t
    JOIN pg_class c ON c.oid = t.tgrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'auth'
      AND c.relname = 'query_graph_nodes'
      AND t.tgname = 'trg_query_graph_nodes_set_updated_at'
      AND NOT t.tgisinternal
  ) THEN
    EXECUTE 'CREATE TRIGGER trg_query_graph_nodes_set_updated_at BEFORE UPDATE ON auth.query_graph_nodes FOR EACH ROW EXECUTE FUNCTION auth.set_updated_at()';
    v_query_graph_trigger_recreated := TRUE;
  END IF;

  RETURN QUERY SELECT
    v_rls_enabled_count,
    v_fk_validated_count,
    v_users_trigger_recreated,
    v_query_graph_trigger_recreated;
END;
$$;


--
-- Name: assert_admin_actor(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.assert_admin_actor() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public'
    AS $$
BEGIN
  IF auth.current_jwt_role() IS DISTINCT FROM 'db_admin' THEN
    RAISE EXCEPTION 'Acceso denegado: se requiere rol db_admin, rol actual es %', COALESCE(auth.current_jwt_role(), 'NULL');
  END IF;
END;
$$;


--
-- Name: base64url_encode(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.base64url_encode(p_input text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_output TEXT;
BEGIN
    v_output := encode(convert_to(p_input, 'UTF8'), 'base64');
    v_output := replace(v_output, E'\n', '');
    v_output := replace(v_output, '=', '');
    v_output := replace(v_output, '+', '-');
    v_output := replace(v_output, '/', '_');
    RETURN v_output;
END;
$$;


--
-- Name: buyer_aplica_a_promo_vecindad(double precision, double precision); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.buyer_aplica_a_promo_vecindad(p_lat double precision, p_lng double precision) RETURNS TABLE(id_zona_promo uuid, id_vendedor uuid, nombre text, descuento_pct numeric, vence_en timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'ag_catalog', 'public'
    AS $$
DECLARE
    v_actor_id  uuid := auth.fn_current_user_id();
    v_punto     geometry;
BEGIN
    -- Validar comprador activo
    IF NOT EXISTS (
        SELECT 1 FROM auth.users
        WHERE id = v_actor_id
          AND activo = true AND fecha_eliminacion IS NULL
    ) THEN
        RAISE EXCEPTION 'P0208: Comprador inactivo' USING ERRCODE = 'P0001';
    END IF;

    v_punto := ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326);

    RETURN QUERY
    SELECT
        spz.id,
        spz.id_vendedor,
        spz.nombre,
        spz.descuento_pct,
        spz.vence_en
    FROM auth.seller_promo_zones spz
    JOIN auth.users s
        ON s.id = spz.id_vendedor
       AND s.activo = true AND s.fecha_eliminacion IS NULL
    WHERE spz.activo = true
      AND spz.fecha_eliminacion IS NULL
      AND now() BETWEEN spz.inicia_en AND spz.vence_en
      AND ST_Contains(spz.poligono, v_punto)
      -- Excluir zonas ya canjeadas por este comprador
      AND NOT EXISTS (
          SELECT 1 FROM auth.seller_promo_claims spc
          WHERE spc.id_zona_promo = spz.id
            AND spc.id_comprador = v_actor_id
      );
END;
$$;


--
-- Name: buyer_buscar_vendedores_cercanos(double precision, double precision, integer, uuid, integer, integer, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.buyer_buscar_vendedores_cercanos(p_latitud double precision, p_longitud double precision, p_radio_metros integer DEFAULT 2000, p_id_categoria uuid DEFAULT NULL::uuid, p_limite integer DEFAULT 20, p_offset integer DEFAULT 0, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_actor    uuid;
  v_radio    int;
  v_punto    geography;
  v_resultado jsonb;
  v_count    int;
BEGIN
  -- V2: fn_current_user_id() canónico (comprador puede ser anónimo)
  v_actor := COALESCE(p_user_id, auth.fn_current_user_id());

  -- FA-1: Coordenadas inválidas
  IF p_latitud NOT BETWEEN -90 AND 90 OR p_longitud NOT BETWEEN -180 AND 180 THEN
    RAISE EXCEPTION 'Coordenadas inválidas' USING ERRCODE='P0001';
  END IF;

  v_radio := GREATEST(100, LEAST(50000, COALESCE(p_radio_metros,2000)));
  v_punto := ST_SetSRID(ST_MakePoint(p_longitud,p_latitud),4326)::geography;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id_vendedor',va.id_vendedor,
      'slug_publico',va.slug_publico,
      'nombre_marca',va.nombre_marca,
      'url_logo',va.url_logo,
      'ubicacion_id',va.id_ubicacion,
      'ubicacion_nombre',va.ubicacion_nombre,
      'distancia_metros',round(ST_Distance(va.punto,v_punto)::numeric,0),
      'tipo_ubicacion',va.tipo_ubicacion,
      'calificacion_promedio',va.calificacion_promedio,
      'total_resenas',va.total_resenas,
      'score_reputacion',va.score_reputacion,
      'disponible_ahora',va.disponible_ahora
    ) ORDER BY ST_Distance(va.punto,v_punto) ASC
  )
  INTO v_resultado
  FROM auth.mv_vendedores_activos va
  WHERE ST_DWithin(va.punto, v_punto, v_radio)
    AND (p_id_categoria IS NULL OR EXISTS (
      SELECT 1 FROM auth.productos p
      WHERE p.id_vendedor=va.id_vendedor AND p.id_categoria=p_id_categoria AND p.activo=true))
  LIMIT GREATEST(1,LEAST(COALESCE(p_limite,20),100))
  OFFSET GREATEST(0,COALESCE(p_offset,0));

  v_count := jsonb_array_length(COALESCE(v_resultado,'[]'));

  -- Telemetría de búsqueda (FA-3: falla silenciosa)
  BEGIN
    INSERT INTO auth.product_search_audit(id_usuario,latitud,longitud,radio_metros,resultados_count,id_categoria)
    VALUES (v_actor,p_latitud,p_longitud,v_radio,v_count,p_id_categoria);
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object(
    'vendedores',COALESCE(v_resultado,'[]'),
    'total',v_count,
    'radio_metros',v_radio,
    'timestamp',now());
END;
$$;


--
-- Name: buyer_check_own_role(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.buyer_check_own_role() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE v_role text := (SELECT role FROM auth.users WHERE id=auth.fn_current_user_id());
BEGIN
  IF v_role = 'buyer' THEN
    RAISE EXCEPTION 'Compradores no tienen acceso al dashboard de vendedor' USING ERRCODE='42501';
  END IF;
END;
$$;


--
-- Name: buyer_claim_promo_vecindad(uuid, double precision, double precision); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.buyer_claim_promo_vecindad(p_promo_zone_id uuid, p_lat double precision, p_lng double precision) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog', 'pg_catalog', 'extensions'
    AS $$
DECLARE
    v_actor_id  uuid := auth.fn_current_user_id();
    v_zone      auth.seller_promo_zones%ROWTYPE;
    v_punto     geography;
    v_claim_id  uuid;
BEGIN
    v_punto := ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography;

    -- Obtener zona activa
    SELECT * INTO v_zone
    FROM auth.seller_promo_zones
    WHERE id = p_promo_zone_id
      AND activo = true
      AND fecha_eliminacion IS NULL
      AND now() BETWEEN inicia_en AND vence_en;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'P0209: Zona promocional no activa o vencida' USING ERRCODE = 'P0001';
    END IF;

    -- Validar que el comprador está dentro del polígono
    IF NOT ST_Contains(v_zone.poligono, v_punto::geometry) THEN
        RAISE EXCEPTION 'P0210: El comprador no está dentro del área de la promoción' USING ERRCODE = 'P0001';
    END IF;

    -- Validar que no haya canjeo previo
    IF EXISTS (
        SELECT 1 FROM auth.seller_promo_claims
        WHERE id_zona_promo = p_promo_zone_id AND id_comprador = v_actor_id
    ) THEN
        RAISE EXCEPTION 'P0211: Ya existe un canje para esta zona' USING ERRCODE = 'P0001';
    END IF;

    INSERT INTO auth.seller_promo_claims (
        id_zona_promo, id_comprador, punto_claim, claim_estado
    ) VALUES (
        p_promo_zone_id, v_actor_id, v_punto, 'VALIDO'
    ) RETURNING id INTO v_claim_id;

    RETURN jsonb_build_object(
        'status', 'OK',
        'claim_id', v_claim_id,
        'descuento_pct', v_zone.descuento_pct,
        'promo_zone_id', p_promo_zone_id
    );
END;
$$;


--
-- Name: buyer_confirm_payment_v2(uuid, date, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.buyer_confirm_payment_v2(p_order_id uuid, p_order_month date, p_region_code text, p_payment_method text, p_payment_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
    -- Delega íntegro en la implementación canónica (app), que valida
    -- identidad, idempotencia y transición de estado via trigger.
    RETURN app.buyer_confirm_payment_v2(
        p_order_id,
        p_order_month,
        p_region_code,
        p_payment_method,
        p_payment_ref
    );
END;
$$;


--
-- Name: buyer_crear_resena(uuid, integer, text, uuid, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.buyer_crear_resena(p_id_orden uuid, p_calificacion integer, p_comentario text DEFAULT NULL::text, p_id_producto uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_actor      uuid;
  v_id_vendedor uuid;
  v_resena_id  uuid;
BEGIN
  -- V2: fn_current_user_id() canónico
  v_actor := COALESCE(p_user_id, auth.fn_current_user_id());
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Actor no resuelto' USING ERRCODE='P0001'; END IF;

  -- FA-2: Calificación inválida
  IF p_calificacion NOT BETWEEN 1 AND 5 THEN
    RAISE EXCEPTION 'Calificación debe ser entre 1 y 5, recibido: %', p_calificacion USING ERRCODE='P0002';
  END IF;

  -- FA-3: Orden no confirmada o no pertenece al comprador
  SELECT id_vendedor INTO v_id_vendedor
  FROM auth.ordenes WHERE id=p_id_orden AND id_comprador=v_actor AND estado='confirmada';
  IF v_id_vendedor IS NULL THEN
    RAISE EXCEPTION 'Orden no encontrada, no confirmada o no pertenece al comprador' USING ERRCODE='P0003';
  END IF;

  -- FA-4: Reseña duplicada
  IF EXISTS (SELECT 1 FROM auth.resenas WHERE id_orden=p_id_orden AND id_comprador=v_actor) THEN
    RAISE EXCEPTION 'Ya existe una reseña para esta orden' USING ERRCODE='P0004';
  END IF;

  INSERT INTO auth.resenas(
    id_orden,id_producto,id_comprador,id_vendedor,
    calificacion,comentario,fecha_creacion,fecha_modificacion)
  VALUES (p_id_orden,p_id_producto,v_actor,v_id_vendedor,
    p_calificacion,p_comentario,now(),now())
  RETURNING id INTO v_resena_id;
  -- NOTA V2: NO se recalcula score aquí — el trigger lo hace automáticamente

  -- Telemetría (FA-5: falla silenciosa)
  BEGIN
    INSERT INTO auth.telemetria_vendedor(id_vendedor,tipo_evento,metadata)
    VALUES (v_id_vendedor,'resena_recibida',
      jsonb_build_object('calificacion',p_calificacion,'resena_id',v_resena_id));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object(
    'resena_id',v_resena_id,'id_vendedor',v_id_vendedor,
    'calificacion',p_calificacion,'timestamp',now());
END;
$$;


--
-- Name: buyer_iniciar_conversacion(uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.buyer_iniciar_conversacion(p_id_vendedor uuid, p_mensaje text, p_producto_id uuid DEFAULT NULL::uuid, p_orden_id uuid DEFAULT NULL::uuid, p_asunto text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor  uuid;
    v_conv   auth.conversaciones%ROWTYPE;
    v_msg_id uuid;
BEGIN
    v_actor := coalesce(
        (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')::uuid
    );
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Actor no resuelto desde JWT' USING ERRCODE = 'P0001';
    END IF;
    IF v_actor = p_id_vendedor THEN
        RAISE EXCEPTION 'No puedes iniciar conversación contigo mismo' USING ERRCODE = 'P0031';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM auth.users u
        JOIN auth.perfiles_publicos_vendedor ppv ON ppv.id_vendedor = u.id
        WHERE u.id = p_id_vendedor AND u.role = 'seller' AND ppv.activo = true
    ) THEN
        RAISE EXCEPTION 'Vendedor no encontrado o inactivo' USING ERRCODE = 'P0032';
    END IF;

    -- Buscar hilo activo existente
    SELECT * INTO v_conv
    FROM auth.conversaciones
    WHERE id_comprador = v_actor
      AND id_vendedor  = p_id_vendedor
      AND (p_orden_id    IS NULL OR id_orden    = p_orden_id)
      AND (p_producto_id IS NULL OR id_producto = p_producto_id)
      AND estado = 'activa'
    LIMIT 1;

    IF NOT FOUND THEN
        INSERT INTO auth.conversaciones
            (id_comprador, id_vendedor, id_orden, id_producto, asunto, tipo, estado)
        VALUES (
            v_actor, p_id_vendedor,
            p_orden_id, p_producto_id,
            p_asunto,
            CASE WHEN p_orden_id IS NOT NULL THEN 'postventa'
                 WHEN p_producto_id IS NOT NULL THEN 'consulta'
                 ELSE 'consulta' END,
            'activa'
        )
        RETURNING * INTO v_conv;
    END IF;

    INSERT INTO auth.mensajes
        (id_conversacion, emisor_id, cuerpo, tipo_contenido)
    VALUES (v_conv.id, v_actor, p_mensaje, 'texto')
    RETURNING id INTO v_msg_id;

    RETURN jsonb_build_object(
        'ok',              true,
        'conversacion_id', v_conv.id,
        'mensaje_id',      v_msg_id,
        'es_nueva',        (v_conv.mensajes_count = 0)
    );
END;
$$;


--
-- Name: buyer_log_interaction(uuid, text, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.buyer_log_interaction(p_target_id uuid, p_event_type text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_actor_id uuid; v_id bigint;
BEGIN
  v_actor_id := auth.fn_current_user_id();

  IF p_event_type NOT IN ('PROFILE_VIEW','PRODUCT_SAVED','PRODUCT_VIEW','STORE_VIEW','PRODUCT_UNSAVED') THEN
    RAISE EXCEPTION 'event_type_invalido';
  END IF;

  IF p_target_id IS NULL THEN RAISE EXCEPTION 'target_id_required'; END IF;
  IF jsonb_typeof(coalesce(p_metadata,'{}')) <> 'object' THEN
    RAISE EXCEPTION 'metadata_must_be_object';
  END IF;

  INSERT INTO auth.interaction_logs (id_actor, id_objetivo, tipo_evento, metadata)
  VALUES (v_actor_id, p_target_id, p_event_type, coalesce(p_metadata, '{}'))
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('log_id', v_id, 'event_type', p_event_type, 'recorded_at', now());
END; $$;


--
-- Name: buyer_registrar_busqueda(text, double precision, double precision, numeric, integer, uuid, boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.buyer_registrar_busqueda(p_query_text text, p_lat double precision, p_lng double precision, p_radius_km numeric, p_results_count integer, p_categoria_id uuid DEFAULT NULL::uuid, p_consentimiento boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog', 'pg_catalog', 'extensions'
    AS $$
DECLARE
    v_actor_id  uuid := auth.fn_current_user_id();
    v_id        uuid;
BEGIN
    -- Validar actor activo
    IF NOT EXISTS (
        SELECT 1 FROM auth.users
        WHERE id = v_actor_id
          AND activo = true AND fecha_eliminacion IS NULL
    ) THEN
        RAISE EXCEPTION 'P0205: Comprador inactivo' USING ERRCODE = 'P0001';
    END IF;

    -- Solo persistir si hay consentimiento
    IF NOT p_consentimiento THEN
        RETURN jsonb_build_object('status', 'OMITIDO', 'razon', 'sin_consentimiento');
    END IF;

    INSERT INTO auth.search_events (
        id_comprador, query_text, punto, radius_km,
        results_count, id_categoria, consentimiento
    ) VALUES (
        v_actor_id,
        p_query_text,
        ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography,
        p_radius_km,
        p_results_count,
        p_categoria_id,
        true
    ) RETURNING id INTO v_id;

    RETURN jsonb_build_object('status', 'OK', 'search_event_id', v_id);
END;
$$;


--
-- Name: buyer_reportar_producto(uuid, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.buyer_reportar_producto(p_producto_id uuid, p_motivo text, p_categoria_motivo text DEFAULT 'otro'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
declare v_actor_id uuid; v_id bigint;
begin
  v_actor_id := auth.fn_current_user_id();
  if p_motivo is null or btrim(p_motivo) = '' then raise exception 'motivo_required'; end if;

  -- Verificar que el producto existe y está activo
  if not exists (select 1 from auth.productos where id = p_producto_id and activo = true and fecha_eliminacion is null) then
    raise exception 'producto_not_found_or_inactive';
  end if;

  -- Prioridad alta para vendedores Silver+ (feature flag moderacion_prioritaria)
  insert into auth.producto_moderacion_queue (id_producto, reportado_por, motivo, categoria_motivo,
    prioridad, estado)
  values (p_producto_id, v_actor_id, btrim(p_motivo), p_categoria_motivo,
    case when auth.fn_get_feature_flag(v_actor_id, 'moderacion_prioritaria') then 8 else 5 end,
    'pendiente')
  returning id into v_id;

  return jsonb_build_object('reporte_id', v_id, 'estado', 'pendiente');
end; $$;


--
-- Name: buyer_submit_resena(uuid, integer, text, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.buyer_submit_resena(p_orden_id uuid, p_calificacion integer, p_comentario text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'ag_catalog'
    AS $$
DECLARE
  v_caller       uuid;
  v_id_comprador uuid;
  v_id_vendedor  uuid;
  v_id_producto  uuid;
  v_entregado    boolean := false;
  v_resena_id    uuid;
BEGIN
  v_caller := auth.fn_current_user_id();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'JWT requerido' USING ERRCODE = 'P0001';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id=v_caller AND role='buyer') THEN
    RAISE EXCEPTION 'Solo buyer puede emitir reseña' USING ERRCODE = 'P0501';
  END IF;

  IF p_calificacion NOT BETWEEN 1 AND 5 THEN
    RAISE EXCEPTION 'Calificacion debe ser 1..5' USING ERRCODE = 'P0502';
  END IF;

  -- Validar orden pertenece al buyer
  SELECT o.id_comprador, o.id_vendedor
  INTO v_id_comprador, v_id_vendedor
  FROM auth.ordenes o
  WHERE o.id = p_orden_id;

  IF NOT FOUND OR v_id_comprador IS DISTINCT FROM v_caller THEN
    RAISE EXCEPTION 'Orden inválida o no pertenece al comprador' USING ERRCODE = 'P0503';
  END IF;

  -- Regla de elegibilidad: envío entregado
  SELECT EXISTS (
    SELECT 1 FROM auth.envios e
    WHERE e.id_orden = p_orden_id AND e.estado = 'entregado'
  ) INTO v_entregado;

  IF v_entregado IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'No se puede reseñar: envío no entregado' USING ERRCODE = 'P0504';
  END IF;

  -- Producto: primer item de la orden
  SELECT oi.id_producto INTO v_id_producto
  FROM auth.orden_items oi
  WHERE oi.id_orden = p_orden_id
  ORDER BY oi.posicion ASC LIMIT 1;

  INSERT INTO auth.resenas (
    id_orden, id_producto, id_comprador, id_vendedor,
    calificacion, comentario, metadata
  ) VALUES (
    p_orden_id, v_id_producto, v_caller, v_id_vendedor,
    p_calificacion, p_comentario, COALESCE(p_metadata, '{}'::jsonb)
  ) RETURNING id INTO v_resena_id;

  RETURN jsonb_build_object(
    'resena_id',    v_resena_id,
    'id_orden',     p_orden_id,
    'id_vendedor',  v_id_vendedor,
    'calificacion', p_calificacion,
    'created_at',   now()
  );
END;
$$;


--
-- Name: cancelar_intercambio(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.cancelar_intercambio(p_intercambio_id uuid, p_motivo_cancelacion text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_actor UUID;
    v_role TEXT;
    v_estado_actual TEXT;
    v_solicitante UUID;
    v_receptor UUID;
    v_from_node BIGINT;
    v_to_node BIGINT;
BEGIN
    v_actor := auth.current_jwt_user_id();
    v_role := auth.current_jwt_role();

    IF v_actor IS NULL AND v_role <> 'db_admin' THEN
        RAISE EXCEPTION 'jwt requerido para cancelar intercambio';
    END IF;

    IF p_intercambio_id IS NULL THEN
        RAISE EXCEPTION 'p_intercambio_id es obligatorio';
    END IF;

    SELECT i.estado, i.solicitante_id, i.receptor_id
    INTO v_estado_actual, v_solicitante, v_receptor
    FROM auth.intercambios i
    WHERE i.id = p_intercambio_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'intercambio no encontrado';
    END IF;

    IF v_role <> 'db_admin' AND v_actor <> v_solicitante AND v_actor <> v_receptor THEN
        RAISE EXCEPTION 'solo participantes pueden cancelar el intercambio';
    END IF;

    IF v_estado_actual NOT IN ('propuesta', 'aceptada') THEN
        RAISE EXCEPTION 'solo intercambios en estado propuesta o aceptada pueden cancelarse; estado actual: %', v_estado_actual;
    END IF;

    INSERT INTO auth.h_intercambios_audit (
        intercambio_id,
        actor_user_id,
        evento,
        payload
    ) VALUES (
        p_intercambio_id,
        COALESCE(v_actor, v_solicitante),
        'exchange_cancellation_intent',
        jsonb_build_object(
            'from_estado', v_estado_actual,
            'motivo_cancelacion', NULLIF(BTRIM(p_motivo_cancelacion), ''),
            'actor_user_id', COALESCE(v_actor, v_solicitante),
            'cancelled_at', NOW()
        )
    );

    UPDATE auth.intercambios
    SET estado = 'cancelada',
        mensaje = CASE 
            WHEN NULLIF(BTRIM(p_motivo_cancelacion), '') IS NOT NULL 
            THEN COALESCE(mensaje, '') || ' [CANCELADO: ' || BTRIM(p_motivo_cancelacion) || ']'
            ELSE COALESCE(mensaje, '') || ' [CANCELADO]'
        END
    WHERE id = p_intercambio_id;

    v_from_node := auth.ensure_query_graph_node(
        'user',
        v_solicitante,
        NULL,
        NULL,
        v_solicitante,
        'user:' || v_solicitante::TEXT,
        jsonb_build_object('id_usuario', v_solicitante)
    );

    v_to_node := auth.ensure_query_graph_node(
        'user',
        v_receptor,
        NULL,
        NULL,
        v_receptor,
        'user:' || v_receptor::TEXT,
        jsonb_build_object('id_usuario', v_receptor)
    );

    PERFORM auth.ensure_query_graph_edge(
        v_from_node,
        v_to_node,
        'EXCHANGE_CANCELLED',
        COALESCE(v_actor, v_solicitante),
        jsonb_build_object(
            'intercambio_id', p_intercambio_id,
            'actor_user_id', COALESCE(v_actor, v_solicitante),
            'previous_estado', v_estado_actual,
            'motivo_cancelacion', NULLIF(BTRIM(p_motivo_cancelacion), ''),
            'cancelled_at', NOW()
        )
    );

    RETURN jsonb_build_object(
        'ok', TRUE,
        'intercambio_id', p_intercambio_id,
        'estado_old', v_estado_actual,
        'estado_new', 'cancelada',
        'solicitante_id', v_solicitante,
        'receptor_id', v_receptor,
        'motivo_cancelacion', NULLIF(BTRIM(p_motivo_cancelacion), ''),
        'actor_user_id', COALESCE(v_actor, v_solicitante)
    );
END;
$$;


--
-- Name: canjear_puntos(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.canjear_puntos(p_beneficio_id uuid, p_referencia_operacion text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_actor           UUID;
    v_role            TEXT;
    v_beneficio       auth.beneficios_catalogo%ROWTYPE;
    v_billetera       auth.billetera%ROWTYPE;
    v_saldo_nuevo     NUMERIC(12,2);
    v_canje_id        UUID;
    v_from_node       BIGINT;
    v_to_node         BIGINT;
    v_use_case_id     INTEGER;
BEGIN
    v_actor := auth.current_jwt_user_id();
    v_role := auth.current_jwt_role();

    IF v_actor IS NULL AND v_role <> 'db_admin' THEN
        RAISE EXCEPTION 'jwt requerido para canjear puntos';
    END IF;

    IF p_beneficio_id IS NULL THEN
        RAISE EXCEPTION 'p_beneficio_id es obligatorio';
    END IF;

    SELECT * INTO v_beneficio
    FROM auth.beneficios_catalogo b
    WHERE b.id = p_beneficio_id
      AND b.activo = TRUE
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'beneficio no encontrado o inactivo';
    END IF;

    SELECT * INTO v_billetera
    FROM auth.billetera w
    WHERE w.id_usuario = v_actor
      AND w.activo = TRUE
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'billetera no encontrada para el usuario';
    END IF;

    IF v_billetera.saldo < v_beneficio.costo_puntos THEN
        RAISE EXCEPTION 'saldo insuficiente: saldo=%, costo=%', v_billetera.saldo, v_beneficio.costo_puntos;
    END IF;

    v_saldo_nuevo := v_billetera.saldo - v_beneficio.costo_puntos;

    UPDATE auth.billetera
    SET saldo = v_saldo_nuevo,
        fecha_modificacion = NOW()
    WHERE id = v_billetera.id;

    INSERT INTO auth.canjes_puntos (
        id_usuario,
        beneficio_id,
        puntos_debitados,
        saldo_anterior,
        saldo_posterior,
        estado,
        referencia_operacion,
        detalle
    ) VALUES (
        v_actor,
        v_beneficio.id,
        v_beneficio.costo_puntos,
        v_billetera.saldo,
        v_saldo_nuevo,
        'aprobado',
        NULLIF(BTRIM(p_referencia_operacion), ''),
        jsonb_build_object(
            'beneficio_codigo', v_beneficio.codigo,
            'beneficio_nombre', v_beneficio.nombre
        )
    ) RETURNING id INTO v_canje_id;

    -- Auditoria funcional: auth.canjes_puntos es el ledger auditable del canje.

    v_from_node := auth.ensure_query_graph_node(
        'user',
        v_actor,
        NULL,
        NULL,
        v_actor,
        'user:' || v_actor::TEXT,
        jsonb_build_object('id_usuario', v_actor)
    );

    v_use_case_id := auth.ensure_use_case_catalog_entry(
        'CU131',
        'Canjear puntos por beneficios',
        'Canje de puntos desde billetera por beneficios del catalogo'
    );

    v_to_node := auth.ensure_query_graph_node(
        'use_case',
        NULL,
        NULL,
        v_use_case_id,
        v_actor,
        'use_case:CU131',
        jsonb_build_object('use_case_code', 'CU131')
    );

    PERFORM auth.ensure_query_graph_edge(
        v_from_node,
        v_to_node,
        'POINTS_REDEEMED',
        v_actor,
        jsonb_build_object(
            'canje_id', v_canje_id,
            'beneficio_id', v_beneficio.id,
            'beneficio_codigo', v_beneficio.codigo,
            'puntos_debitados', v_beneficio.costo_puntos,
            'saldo_posterior', v_saldo_nuevo,
            'created_at', NOW()
        )
    );

    RETURN jsonb_build_object(
        'ok', TRUE,
        'canje_id', v_canje_id,
        'id_usuario', v_actor,
        'beneficio_id', v_beneficio.id,
        'beneficio_codigo', v_beneficio.codigo,
        'beneficio_nombre', v_beneficio.nombre,
        'puntos_debitados', v_beneficio.costo_puntos,
        'saldo_anterior', v_billetera.saldo,
        'saldo_posterior', v_saldo_nuevo
    );
END;
$$;


--
-- Name: change_user_role(uuid, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.change_user_role(p_user_id uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_actor_id UUID;
    v_actor_role TEXT;
    v_new_role TEXT;
    v_reason TEXT;
    v_old_role TEXT;
    v_user auth.users%ROWTYPE;
BEGIN
    v_actor_id := auth.current_jwt_user_id();
    v_actor_role := auth.current_jwt_role();

    IF v_actor_id IS NULL OR v_actor_role IS NULL THEN
        RAISE EXCEPTION 'jwt requerido';
    END IF;

    IF v_actor_role <> 'db_admin' THEN
        RAISE EXCEPTION 'solo db_admin puede cambiar roles';
    END IF;

    IF p_user_id IS NULL THEN
        RAISE EXCEPTION 'p_user_id es requerido';
    END IF;

    v_new_role := lower(NULLIF(trim(COALESCE(p_payload->>'newRole', p_payload->>'new_role', '')), ''));
    v_reason := NULLIF(trim(COALESCE(p_payload->>'reason', p_payload->>'motivo', '')), '');

    IF v_new_role IS NULL THEN
        RAISE EXCEPTION 'newRole es requerido';
    END IF;

    IF v_new_role NOT IN ('buyer', 'seller', 'db_admin') THEN
        RAISE EXCEPTION 'newRole invalido';
    END IF;

    SELECT * INTO v_user
    FROM auth.users
    WHERE id = p_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'usuario no encontrado';
    END IF;

    v_old_role := v_user.role;

    IF v_old_role = v_new_role THEN
        RETURN jsonb_build_object(
            'cambiado', FALSE,
            'id_usuario', v_user.id,
            'rol_anterior', v_old_role,
            'rol_nuevo', v_new_role,
            'cambiado_por', v_actor_id,
            'motivo', v_reason
        );
    END IF;

    PERFORM set_config('app.role_change_source', 'rpc_admin_change', true);
    PERFORM set_config('app.role_change_reason', COALESCE(v_reason, ''), true);

    UPDATE auth.users
    SET role = v_new_role
    WHERE id = p_user_id
    RETURNING * INTO v_user;

    RETURN jsonb_build_object(
        'cambiado', TRUE,
        'id_usuario', v_user.id,
        'email', v_user.email,
        'nombre_usuario', v_user.username,
        'rol_anterior', v_old_role,
        'rol_nuevo', v_user.role,
        'cambiado_por', v_actor_id,
        'motivo', v_reason,
        'fecha_cambio', NOW()
    );
END;
$$;


--
-- Name: check_jwt_not_revoked(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.check_jwt_not_revoked() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_headers json;
    v_auth text;
    v_token text;
BEGIN
    BEGIN
        v_headers := current_setting('request.headers', true)::json;
    EXCEPTION WHEN OTHERS THEN
        v_headers := NULL;
    END;

    IF v_headers IS NULL THEN
        RETURN;
    END IF;

    v_auth := COALESCE(v_headers->>'authorization', v_headers->>'Authorization', '');
    IF v_auth IS NULL OR length(trim(v_auth)) = 0 THEN
        RETURN;
    END IF;

    v_token := regexp_replace(trim(v_auth), '^[Bb][Ee][Aa][Rr][Ee][Rr][[:space:]]+', '');
    IF v_token IS NULL OR length(v_token) < 20 THEN
        RETURN;
    END IF;

    IF auth.rpc_access_token_revoked(v_token) THEN
        RAISE EXCEPTION 'Sesión cerrada'
            USING ERRCODE = '28000';
    END IF;
END;
$$;


--
-- Name: FUNCTION check_jwt_not_revoked(); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.check_jwt_not_revoked() IS 'PostgREST db-pre-request: bloquea JWT cuyo hash está revocado. Anónimo pasa.';


--
-- Name: completar_intercambio(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.completar_intercambio(p_intercambio_id uuid, p_nota_cierre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_actor UUID;
    v_role TEXT;
    v_estado_actual TEXT;
    v_solicitante UUID;
    v_receptor UUID;
    v_from_node BIGINT;
    v_to_node BIGINT;
    v_puntos_solicitante INTEGER;
    v_puntos_receptor INTEGER;
BEGIN
    v_actor := auth.current_jwt_user_id();
    v_role := auth.current_jwt_role();

    IF v_actor IS NULL AND v_role <> 'db_admin' THEN
        RAISE EXCEPTION 'jwt requerido para completar intercambio';
    END IF;

    IF p_intercambio_id IS NULL THEN
        RAISE EXCEPTION 'p_intercambio_id es obligatorio';
    END IF;

    SELECT i.estado, i.solicitante_id, i.receptor_id
    INTO v_estado_actual, v_solicitante, v_receptor
    FROM auth.intercambios i
    WHERE i.id = p_intercambio_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'intercambio no encontrado';
    END IF;

    IF v_role <> 'db_admin' AND v_actor <> v_solicitante AND v_actor <> v_receptor THEN
        RAISE EXCEPTION 'solo participantes pueden completar el intercambio';
    END IF;

    IF v_estado_actual <> 'aceptada' THEN
        RAISE EXCEPTION 'solo intercambios en estado aceptada pueden completarse';
    END IF;

    SELECT COALESCE(SUM(p.puntos_recompensa), 0)
    INTO v_puntos_solicitante
    FROM auth.intercambio_articulos ia
    JOIN auth.productos p ON p.id = ia.producto_id
    WHERE ia.intercambio_id = p_intercambio_id
      AND ia.rol_en_intercambio = 'receptor';

    SELECT COALESCE(SUM(p.puntos_recompensa), 0)
    INTO v_puntos_receptor
    FROM auth.intercambio_articulos ia
    JOIN auth.productos p ON p.id = ia.producto_id
    WHERE ia.intercambio_id = p_intercambio_id
      AND ia.rol_en_intercambio = 'solicitante';

    INSERT INTO auth.h_intercambios_audit (
        intercambio_id,
        actor_user_id,
        evento,
        payload
    ) VALUES (
        p_intercambio_id,
        COALESCE(v_actor, v_solicitante),
        'exchange_completion_intent',
        jsonb_build_object(
            'from_estado', v_estado_actual,
            'nota_cierre', NULLIF(BTRIM(p_nota_cierre), ''),
            'puntos_estimados_solicitante', v_puntos_solicitante,
            'puntos_estimados_receptor', v_puntos_receptor
        )
    );

    UPDATE auth.intercambios
    SET estado = 'completada',
        mensaje = COALESCE(NULLIF(BTRIM(p_nota_cierre), ''), mensaje)
    WHERE id = p_intercambio_id;

    v_from_node := auth.ensure_query_graph_node(
        'user',
        v_solicitante,
        NULL,
        NULL,
        v_solicitante,
        'user:' || v_solicitante::TEXT,
        jsonb_build_object('id_usuario', v_solicitante)
    );

    v_to_node := auth.ensure_query_graph_node(
        'user',
        v_receptor,
        NULL,
        NULL,
        v_receptor,
        'user:' || v_receptor::TEXT,
        jsonb_build_object('id_usuario', v_receptor)
    );

    PERFORM auth.ensure_query_graph_edge(
        v_from_node,
        v_to_node,
        'EXCHANGE_COMPLETED',
        COALESCE(v_actor, v_solicitante),
        jsonb_build_object(
            'intercambio_id', p_intercambio_id,
            'actor_user_id', COALESCE(v_actor, v_solicitante),
            'puntos_estimados_solicitante', v_puntos_solicitante,
            'puntos_estimados_receptor', v_puntos_receptor,
            'nota_cierre', NULLIF(BTRIM(p_nota_cierre), ''),
            'completed_at', NOW()
        )
    );

    RETURN jsonb_build_object(
        'ok', TRUE,
        'intercambio_id', p_intercambio_id,
        'estado_old', v_estado_actual,
        'estado_new', 'completada',
        'solicitante_id', v_solicitante,
        'receptor_id', v_receptor,
        'puntos_estimados_solicitante', v_puntos_solicitante,
        'puntos_estimados_receptor', v_puntos_receptor
    );
END;
$$;


--
-- Name: confirm_password_reset(text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.confirm_password_reset(p_email text, p_otp text, p_new_password text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_updated INT;
BEGIN
    UPDATE auth.users
    SET password_hash = crypt(p_new_password, gen_salt('bf')),
        otp_code = NULL,
        otp_expiry = NULL
    WHERE email = p_email
      AND otp_code = p_otp
      AND otp_expiry > NOW();

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN v_updated > 0;
END;
$$;


--
-- Name: confirmar_recepcion(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.confirmar_recepcion(p_intercambio_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_user_id       uuid := auth.current_jwt_user_id();
    v_intercambio   auth.intercambios%ROWTYPE;
BEGIN
    SELECT * INTO v_intercambio
    FROM auth.intercambios
    WHERE id = p_intercambio_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Intercambio no encontrado: %', p_intercambio_id
            USING ERRCODE = 'P0001';
    END IF;

    -- Solo el receptor del bien puede confirmar recepción
    IF v_intercambio.receptor_id <> v_user_id THEN
        RAISE EXCEPTION 'Solo el receptor puede confirmar la recepción'
            USING ERRCODE = '42501';
    END IF;

    -- Solo se puede confirmar si está en estado 'aceptado' o 'en_curso'
    IF v_intercambio.estado NOT IN ('aceptado', 'en_curso', 'completado') THEN
        RAISE EXCEPTION 'El intercambio no está en un estado válido para confirmar recepción. Estado actual: %',
            v_intercambio.estado
            USING ERRCODE = '22023';
    END IF;

    UPDATE auth.intercambios
    SET estado = 'entregado', actualizado_en = NOW()
    WHERE id = p_intercambio_id;

    RETURN jsonb_build_object(
        'confirmado', true,
        'intercambio_id', p_intercambio_id,
        'estado', 'entregado'
    );
END;
$$;


--
-- Name: consultar_saldo_puntos(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.consultar_saldo_puntos() RETURNS TABLE(id uuid, saldo numeric, moneda text, activo boolean, fecha_modificacion timestamp with time zone, puntos_acumulados_historico numeric, nivel_lealtad_id uuid, user_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_actor_id UUID;
BEGIN
    v_actor_id := auth.current_jwt_user_id();
    IF v_actor_id IS NOT NULL THEN
        PERFORM auth.registrar_consulta_saldo_grafo(v_actor_id);
    END IF;
    RETURN QUERY
    SELECT
        b.id, b.saldo, b.moneda, b.activo,
        b.fecha_modificacion, b.puntos_acumulados_historico,
        b.nivel_lealtad_id, b.id_usuario
    FROM auth.billetera b
    WHERE (
        auth.current_jwt_role() = 'db_admin'
        OR b.id_usuario = v_actor_id
    );
END;
$$;


--
-- Name: count_blocking_user_dependencies(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.count_blocking_user_dependencies(p_target_user_id uuid) RETURNS bigint
    LANGUAGE plpgsql STABLE
    AS $_$
declare v_row record; v_sql text; v_count bigint:=0; v_local bigint;
begin
  for v_row in select * from auth.user_purge_block_rules where is_blocking=true loop
    v_sql := format('select count(*) from %I.%I where %I=$1',
      v_row.source_schema, v_row.source_table, v_row.source_column);
    execute v_sql into v_local using p_target_user_id;
    v_count := v_count + coalesce(v_local,0);
  end loop;
  return v_count;
end;
$_$;


--
-- Name: crear_consulta_servicio(uuid, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.crear_consulta_servicio(p_orden_id uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_role TEXT;
    v_uid UUID;
    v_orden auth.ordenes%ROWTYPE;
    v_consulta_id UUID;
    v_tipo TEXT;
    v_asunto TEXT;
    v_estado TEXT;
    v_envio_id UUID;
    v_owner UUID;
    v_uc_id INTEGER;
    v_user_node BIGINT;
    v_uc_node BIGINT;
BEGIN
    v_role := auth.current_jwt_role();
    v_uid := auth.current_jwt_user_id();

    SELECT * INTO v_orden
    FROM auth.ordenes
    WHERE id = p_orden_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden no encontrada: %', p_orden_id;
    END IF;

    IF v_role = 'buyer' THEN
        IF v_uid IS NULL OR v_orden.id_comprador <> v_uid THEN
            RAISE EXCEPTION 'Permiso denegado para crear consulta sobre esta orden';
        END IF;
        v_owner := v_orden.id_comprador;
    ELSIF v_role = 'seller' THEN
        IF v_uid IS NULL OR v_orden.id_vendedor <> v_uid THEN
            RAISE EXCEPTION 'Permiso denegado para crear consulta sobre esta orden';
        END IF;
        v_owner := v_orden.id_vendedor;
    ELSIF v_role = 'db_admin' OR current_user = 'postgres' THEN
        v_owner := COALESCE(v_uid, v_orden.id_comprador);
    ELSE
        RAISE EXCEPTION 'Permiso denegado: role=%', COALESCE(v_role, 'null');
    END IF;

    v_tipo := CASE COALESCE(NULLIF(lower(trim(p_payload->>'tipo')), ''), 'postventa')
        WHEN 'postventa' THEN 'postventa'
        WHEN 'entrega' THEN 'entrega'
        WHEN 'pago' THEN 'pago'
        WHEN 'producto' THEN 'producto'
        ELSE 'postventa'
    END;

    v_estado := CASE COALESCE(NULLIF(lower(trim(p_payload->>'estado')), ''), 'abierta')
        WHEN 'abierta' THEN 'abierta'
        WHEN 'en_revision' THEN 'en_revision'
        WHEN 'respondida' THEN 'respondida'
        WHEN 'cerrada' THEN 'cerrada'
        ELSE 'abierta'
    END;

    v_asunto := COALESCE(NULLIF(trim(COALESCE(p_payload->>'asunto', '')), ''), 'Consulta postventa');

    SELECT id INTO v_envio_id
    FROM auth.envios
    WHERE id_orden = p_orden_id;

    INSERT INTO auth.consultas_servicio (
        id_orden,
        id_envio,
        id_comprador,
        id_vendedor,
        tipo,
        estado,
        asunto,
        detalle,
        respuesta
    ) VALUES (
        v_orden.id,
        COALESCE(NULLIF(p_payload->>'id_envio', '')::UUID, v_envio_id),
        v_orden.id_comprador,
        v_orden.id_vendedor,
        v_tipo,
        v_estado,
        v_asunto,
        COALESCE(p_payload, '{}'::JSONB) || jsonb_build_object('created_at', now()),
        '{}'::JSONB
    ) RETURNING id INTO v_consulta_id;

    SELECT id INTO v_uc_id FROM auth.use_cases WHERE slug = 'buyer_service_inquiry';

    v_user_node := auth.ensure_query_graph_node(
        'user',
        v_owner,
        NULL,
        NULL,
        v_owner,
        CASE WHEN v_role = 'seller' THEN 'seller:' ELSE 'buyer:' END || v_owner::TEXT,
        jsonb_build_object('id_usuario', v_owner)
    );

    v_uc_node := auth.ensure_query_graph_node(
        'use_case',
        NULL,
        NULL,
        v_uc_id,
        NULL,
        'buyer_service_inquiry',
        jsonb_build_object('phase', 'phase11')
    );

    PERFORM auth.ensure_query_graph_edge(
        v_user_node,
        v_uc_node,
        'SERVICE_INQUIRY:' || v_consulta_id::TEXT,
        v_owner,
        jsonb_build_object(
            'consulta_id', v_consulta_id,
            'orden_id', v_orden.id,
            'tipo', v_tipo,
            'estado', v_estado,
            'created_at', now()
        )
    );

    RETURN jsonb_build_object(
        'consulta_id', v_consulta_id,
        'orden_id', v_orden.id,
        'tipo', v_tipo,
        'estado', v_estado,
        'asunto', v_asunto
    );
END;
$$;


--
-- Name: crear_consulta_servicio_json(uuid, json); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.crear_consulta_servicio_json(p_orden_id uuid, p_payload json DEFAULT '{}'::json) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$ BEGIN RETURN auth.crear_consulta_servicio(p_orden_id, auth.json_to_jsonb(p_payload)); END; $$;


--
-- Name: FUNCTION crear_consulta_servicio_json(p_orden_id uuid, p_payload json); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.crear_consulta_servicio_json(p_orden_id uuid, p_payload json) IS 'Wrapper JSON explicito para compatibilidad PostgREST sin overload ambiguo.';


--
-- Name: crear_orden_compra(jsonb, text, uuid, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.crear_orden_compra(p_items jsonb, p_moneda text DEFAULT 'MXN'::text, p_id_comprador uuid DEFAULT NULL::uuid, p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_role TEXT;
    v_uid UUID;
    v_comprador UUID;
    v_vendedor UUID;
    v_orden_id UUID;
    v_total NUMERIC(14,2) := 0;
    v_item JSONB;
    v_pos INTEGER := 0;
    v_cantidad INTEGER;
    v_precio NUMERIC(14,2);
    v_descuento NUMERIC(14,2);
    v_total_linea NUMERIC(14,2);
    v_producto UUID;
    v_uc_id INTEGER;
    v_user_node BIGINT;
    v_uc_node BIGINT;
BEGIN
    v_role := auth.current_jwt_role();
    v_uid := auth.current_jwt_user_id();

    IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'p_items debe ser arreglo JSON/JSONB no vacio';
    END IF;

    IF v_role = 'buyer' THEN
        IF v_uid IS NULL THEN
            RAISE EXCEPTION 'JWT sin claim sub para role buyer';
        END IF;
        v_comprador := v_uid;
    ELSIF v_role = 'db_admin' THEN
        v_comprador := COALESCE(p_id_comprador, v_uid);
    ELSIF current_user = 'postgres' THEN
        v_comprador := COALESCE(p_id_comprador, (SELECT id FROM auth.users WHERE role='buyer' ORDER BY fecha_creacion DESC LIMIT 1));
    ELSE
        RAISE EXCEPTION 'Permiso denegado: role=%', COALESCE(v_role, 'null');
    END IF;

    IF v_comprador IS NULL THEN
        RAISE EXCEPTION 'No se pudo resolver comprador para crear orden';
    END IF;

    IF p_id_vendedor IS NOT NULL THEN
        v_vendedor := p_id_vendedor;
    ELSE
        SELECT p.id_vendedor
        INTO v_vendedor
        FROM auth.productos p
        WHERE p.id = NULLIF((p_items->0->>'producto_id'),'')::UUID
        LIMIT 1;

        IF v_vendedor IS NULL THEN
            SELECT id INTO v_vendedor FROM auth.users WHERE role='seller' ORDER BY fecha_creacion DESC LIMIT 1;
        END IF;
    END IF;

    IF v_vendedor IS NULL THEN
        RAISE EXCEPTION 'No se pudo resolver vendedor para crear orden';
    END IF;

    INSERT INTO auth.ordenes (id_comprador, id_vendedor, estado, total, moneda, metadata)
    VALUES (
        v_comprador,
        v_vendedor,
        'pendiente',
        0,
        COALESCE(NULLIF(trim(p_moneda), ''), 'MXN'),
        jsonb_build_object('source', 'auth.crear_orden_compra', 'created_at', now())
    )
    RETURNING id INTO v_orden_id;

    FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
        v_pos := v_pos + 1;
        v_cantidad := COALESCE(NULLIF(v_item->>'cantidad','')::INTEGER, 1);
        IF v_cantidad <= 0 THEN
            RAISE EXCEPTION 'Cantidad invalida en posicion %', v_pos;
        END IF;

        v_precio := COALESCE(NULLIF(v_item->>'precio_unitario','')::NUMERIC, 0);
        IF v_precio < 0 THEN
            RAISE EXCEPTION 'Precio invalido en posicion %', v_pos;
        END IF;

        v_descuento := COALESCE(NULLIF(v_item->>'descuento_monto','')::NUMERIC, 0);
        IF v_descuento < 0 THEN
            RAISE EXCEPTION 'Descuento invalido en posicion %', v_pos;
        END IF;

        v_total_linea := ROUND(GREATEST((v_precio * v_cantidad) - v_descuento, 0), 2);
        v_total := v_total + v_total_linea;

        v_producto := NULLIF(v_item->>'producto_id','')::UUID;

        INSERT INTO auth.orden_items (
            id_orden,
            posicion,
            id_producto,
            cantidad,
            precio_unitario,
            descuento_monto,
            total_linea,
            detalle_jsonb
        ) VALUES (
            v_orden_id,
            v_pos,
            v_producto,
            v_cantidad,
            v_precio,
            v_descuento,
            v_total_linea,
            COALESCE(v_item, '{}'::JSONB)
        );
    END LOOP;

    UPDATE auth.ordenes
    SET total = ROUND(v_total, 2),
        metadata = metadata || jsonb_build_object('items_count', v_pos)
    WHERE id = v_orden_id;

    SELECT id INTO v_uc_id FROM auth.use_cases WHERE slug = 'gestionar_ordenes_compra';

    v_user_node := auth.ensure_query_graph_node(
        'user',
        v_comprador,
        NULL,
        NULL,
        v_comprador,
        'buyer:' || v_comprador::TEXT,
        jsonb_build_object('id_usuario', v_comprador)
    );

    v_uc_node := auth.ensure_query_graph_node(
        'use_case',
        NULL,
        NULL,
        v_uc_id,
        NULL,
        'gestionar_ordenes_compra',
        jsonb_build_object('phase', 'phase10')
    );

    PERFORM auth.ensure_query_graph_edge(
        v_user_node,
        v_uc_node,
        'ORDER_CREATE:' || v_orden_id::TEXT,
        v_comprador,
        jsonb_build_object(
            'order_id', v_orden_id,
            'items_count', v_pos,
            'total', ROUND(v_total, 2),
            'currency', COALESCE(NULLIF(trim(p_moneda), ''), 'MXN'),
            'created_at', now()
        )
    );

    RETURN jsonb_build_object(
        'orden_id', v_orden_id,
        'estado', 'pendiente',
        'items_count', v_pos,
        'total', ROUND(v_total, 2),
        'moneda', COALESCE(NULLIF(trim(p_moneda), ''), 'MXN')
    );
END;
$$;


--
-- Name: crear_orden_compra_json(json, text, uuid, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.crear_orden_compra_json(p_items json, p_moneda text DEFAULT 'MXN'::text, p_id_comprador uuid DEFAULT NULL::uuid, p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$ BEGIN RETURN auth.crear_orden_compra(auth.json_to_jsonb(p_items), p_moneda, p_id_comprador, p_id_vendedor); END; $$;


