  RETURN json_build_object('success', true, 'id', p_id);
END;
$$;


--
-- Name: fn_actualizar_billetera_analytics(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_actualizar_billetera_analytics() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_periodo date;
BEGIN
    v_periodo := date_trunc('day', NEW.fecha_creacion)::date;

    INSERT INTO auth.billetera_analytics (
        id_usuario, periodo, tipo_periodo,
        total_ganado, total_canjeado, total_expirado,
        total_transferido_out, total_transferido_in,
        total_cashback, num_movimientos
    ) VALUES (
        NEW.id_usuario, v_periodo, 'dia',
        CASE WHEN NEW.tipo_movimiento IN ('ganado_venta','ganado_bienvenida') THEN NEW.monto ELSE 0 END,
        CASE WHEN NEW.tipo_movimiento = 'canje' THEN ABS(NEW.monto) ELSE 0 END,
        CASE WHEN NEW.tipo_movimiento = 'expiracion' THEN ABS(NEW.monto) ELSE 0 END,
        CASE WHEN NEW.tipo_movimiento = 'transferencia_enviada' THEN ABS(NEW.monto) ELSE 0 END,
        CASE WHEN NEW.tipo_movimiento = 'transferencia_recibida' THEN NEW.monto ELSE 0 END,
        CASE WHEN NEW.tipo_movimiento = 'cashback' THEN NEW.monto ELSE 0 END,
        1
    )
    ON CONFLICT (id_usuario, periodo, tipo_periodo) DO UPDATE SET
        total_ganado          = auth.billetera_analytics.total_ganado
            + CASE WHEN NEW.tipo_movimiento IN ('ganado_venta','ganado_bienvenida') THEN NEW.monto ELSE 0 END,
        total_canjeado        = auth.billetera_analytics.total_canjeado
            + CASE WHEN NEW.tipo_movimiento = 'canje' THEN ABS(NEW.monto) ELSE 0 END,
        total_expirado        = auth.billetera_analytics.total_expirado
            + CASE WHEN NEW.tipo_movimiento = 'expiracion' THEN ABS(NEW.monto) ELSE 0 END,
        total_transferido_out = auth.billetera_analytics.total_transferido_out
            + CASE WHEN NEW.tipo_movimiento = 'transferencia_enviada' THEN ABS(NEW.monto) ELSE 0 END,
        total_transferido_in  = auth.billetera_analytics.total_transferido_in
            + CASE WHEN NEW.tipo_movimiento = 'transferencia_recibida' THEN NEW.monto ELSE 0 END,
        total_cashback        = auth.billetera_analytics.total_cashback
            + CASE WHEN NEW.tipo_movimiento = 'cashback' THEN NEW.monto ELSE 0 END,
        num_movimientos       = auth.billetera_analytics.num_movimientos + 1,
        fecha_actualizacion            = now();

    RETURN NEW;
END;
$$;


--
-- Name: fn_admin_purgar_historico(text, timestamp with time zone, boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_admin_purgar_historico(p_tabla_origen text DEFAULT NULL::text, p_hasta timestamp with time zone DEFAULT now(), p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_role          TEXT;
    v_uid           UUID;
    v_count_elegibles BIGINT := 0;
    v_count_purgados  BIGINT := 0;
    v_preview       JSONB;
BEGIN
    v_role := auth.current_jwt_role();
    v_uid  := auth.current_jwt_user_id();

    IF v_role IS DISTINCT FROM 'db_admin' THEN
        RAISE EXCEPTION 'Solo db_admin puede purgar el histórico' USING ERRCODE = '42501';
    END IF;

    -- Contar registros elegibles
    SELECT COUNT(*)
    INTO v_count_elegibles
    FROM auth.historial_eliminaciones
    WHERE NOT purgado
      AND retencion_hasta <= p_hasta
      AND (p_tabla_origen IS NULL OR tabla_origen = p_tabla_origen);

    -- Desglose por tabla para el reporte
    SELECT jsonb_object_agg(tabla_origen, cnt)
    INTO v_preview
    FROM (
        SELECT tabla_origen, COUNT(*) AS cnt
        FROM auth.historial_eliminaciones
        WHERE NOT purgado
          AND retencion_hasta <= p_hasta
          AND (p_tabla_origen IS NULL OR tabla_origen = p_tabla_origen)
        GROUP BY tabla_origen
    ) t;

    IF p_dry_run THEN
        RETURN jsonb_build_object(
            'modo',              'dry_run',
            'registros_elegibles', v_count_elegibles,
            'desglose_por_tabla', COALESCE(v_preview, '{}'),
            'tabla_filtro',      p_tabla_origen,
            'hasta',             p_hasta,
            'mensaje',           'Ejecute con p_dry_run=false para purgar definitivamente'
        );
    END IF;

    -- Purga efectiva: marcar como purgado (tombstone) o eliminar físicamente
    -- Usamos eliminación física para no inflar la tabla de histórico indefinidamente.
    DELETE FROM auth.historial_eliminaciones
    WHERE NOT purgado
      AND retencion_hasta <= p_hasta
      AND (p_tabla_origen IS NULL OR tabla_origen = p_tabla_origen);

    GET DIAGNOSTICS v_count_purgados = ROW_COUNT;

    -- Registro en log_mantenimiento
    INSERT INTO auth.log_mantenimiento (tipo, resultado, detalle_jsonb, ejecutado_por, archivado)
    VALUES (
        'PURGA_HISTORICO_ELIMINACIONES',
        'EXITOSO',
        jsonb_build_object(
            'tabla_filtro',     p_tabla_origen,
            'hasta',            p_hasta,
            'registros_purgados', v_count_purgados,
            'desglose',         COALESCE(v_preview, '{}'),
            'ejecutado_por',    v_uid,
            'ejecutado_en',     now()
        ),
        v_uid,
        false
    );

    RETURN jsonb_build_object(
        'modo',                'ejecutado',
        'registros_purgados',  v_count_purgados,
        'desglose_por_tabla',  COALESCE(v_preview, '{}'),
        'tabla_filtro',        p_tabla_origen,
        'hasta',               p_hasta
    );
END;
$$;


--
-- Name: fn_admin_resumen_ejecutivo(jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_admin_resumen_ejecutivo(p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_role     TEXT;
    v_kpis     JSONB;
    v_salud    JSONB;
    v_riesgo   JSONB;
    v_alertas  JSONB;
BEGIN
    -- Validar rol (db_admin únicamente)
    v_role := auth.current_jwt_role();
    IF v_role NOT IN ('db_admin') THEN
        RAISE EXCEPTION 'acceso denegado: rol db_admin requerido para fn_admin_resumen_ejecutivo'
            USING ERRCODE = '42501';
    END IF;

    -- KPIs ejecutivos
    SELECT to_jsonb(k.*) INTO v_kpis
    FROM auth.vw_kpis_ejecutivos k
    LIMIT 1;

    -- Salud financiera
    SELECT to_jsonb(s.*) INTO v_salud
    FROM auth.vw_salud_financiera s
    LIMIT 1;

    -- Top 10 usuarios de mayor riesgo
    SELECT jsonb_agg(r.*) INTO v_riesgo
    FROM (
        SELECT id_usuario, username, email, riesgo_score, nivel_riesgo,
               intercambios_cancelados, reportes_recibidos, intentos_fallidos_24h
        FROM auth.vw_consola_riesgo
        WHERE riesgo_score IS NOT NULL
        ORDER BY riesgo_score DESC
        LIMIT 10
    ) r;

    -- Alertas activas (resumen)
    SELECT jsonb_agg(a.*) INTO v_alertas
    FROM (
        SELECT id, severidad, titulo, estado, prioridad, created_at
        FROM auth.vw_disputas_resumen
        WHERE estado = 'activo'
        ORDER BY prioridad DESC
        LIMIT 20
    ) a;

    RETURN jsonb_build_object(
        'kpis',             COALESCE(v_kpis,   '{}'::jsonb),
        'salud_financiera', COALESCE(v_salud,  '{}'::jsonb),
        'riesgo_top10',     COALESCE(v_riesgo, '[]'::jsonb),
        'alertas_activas',  COALESCE(v_alertas,'[]'::jsonb),
        'generado_en',      now()
    );
END;
$$;


--
-- Name: fn_afinidad_outbox_trigger(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_afinidad_outbox_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    -- Solo encolar si tipo positiva o negativa (no neutra)
    IF NEW.tipo_correlacion IN ('positiva', 'negativa') THEN
        INSERT INTO auth.afinidad_graph_outbox (
            id_vendedor, operacion, payload
        )
        VALUES (
            NEW.id_vendedor,
            CASE NEW.tipo_correlacion
                WHEN 'positiva' THEN 'sync_comprado_junto'
                ELSE 'sync_excluye_a'
            END,
            jsonb_build_object(
                'producto_a_id', NEW.producto_a_id,
                'producto_b_id', NEW.producto_b_id,
                'frecuencia', NEW.frecuencia,
                'lift', NEW.lift
            )
        )
        ON CONFLICT DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_aplicar_cashback(uuid, uuid, numeric); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_aplicar_cashback(p_id_vendedor uuid, p_orden_id uuid, p_total_venta numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_limites   jsonb;
    v_regla     record;
    v_puntos    numeric;
    v_saldo_ant numeric;
BEGIN
    -- Verificar plan Silver+
    v_limites := auth.fn_get_wallet_limits(p_id_vendedor);
    IF NOT COALESCE((v_limites ->> 'cashback_automatico')::boolean, false) THEN
        RETURN jsonb_build_object('skipped', true, 'motivo', 'plan_insuficiente');
    END IF;

    -- Verificar que no haya cashback previo para esta orden
    IF EXISTS (
        SELECT 1 FROM auth.movimientos_puntos
        WHERE id_usuario = p_id_vendedor
          AND tipo_movimiento = 'cashback'
          AND referencia = p_orden_id::text
    ) THEN
        RETURN jsonb_build_object('skipped', true, 'motivo', 'cashback_ya_aplicado');
    END IF;

    -- Obtener regla de mayor prioridad aplicable
    SELECT * INTO v_regla
    FROM auth.cashback_reglas
    WHERE activo = true
      AND (fecha_fin IS NULL OR fecha_fin > now())
      AND aplica_a = 'todas'
    ORDER BY prioridad DESC
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('skipped', true, 'motivo', 'sin_regla_activa');
    END IF;

    -- Calcular puntos de cashback
    IF v_regla.tipo_aplicacion = 'porcentaje' THEN
        v_puntos := ROUND(p_total_venta * v_regla.valor / 100, 2);
    ELSE
        v_puntos := v_regla.valor;
    END IF;

    IF v_puntos <= 0 THEN
        RETURN jsonb_build_object('skipped', true, 'motivo', 'puntos_cero');
    END IF;

    -- Acreditar como cashback
    SELECT saldo INTO v_saldo_ant FROM auth.billetera WHERE id_usuario = p_id_vendedor FOR UPDATE;

    UPDATE auth.billetera
    SET saldo = saldo + v_puntos,
        puntos_acumulados_historico = puntos_acumulados_historico + v_puntos,
        fecha_modificacion = now()
    WHERE id_usuario = p_id_vendedor;

    INSERT INTO auth.movimientos_puntos (
        id_usuario, tipo_movimiento, monto, saldo_anterior, saldo_posterior,
        referencia, detalle, expira_en
    ) VALUES (
        p_id_vendedor, 'cashback', v_puntos, v_saldo_ant, v_saldo_ant + v_puntos,
        p_orden_id::text,
        jsonb_build_object(
            'regla_id', v_regla.id, 'regla_nombre', v_regla.nombre,
            'total_venta', p_total_venta, 'tipo', v_regla.tipo_aplicacion, 'valor', v_regla.valor
        ),
        now() + INTERVAL '12 months'
    );

    RETURN jsonb_build_object(
        'cashback_aplicado', true,
        'puntos',            v_puntos,
        'regla',             v_regla.nombre,
        'saldo_nuevo',       v_saldo_ant + v_puntos
    );
END;
$$;


--
-- Name: fn_aplicar_promocion(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_aplicar_promocion(p_orden_id uuid, p_codigo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $_$
DECLARE
    v_actor uuid;
    v_prom  auth.promociones%ROWTYPE;
    v_orden auth.ordenes%ROWTYPE;
    v_desc  numeric;
    v_puntos numeric;
BEGIN
    v_actor := (nullif(current_setting('request.jwt.claims', true),'')::jsonb ->> 'sub')::uuid;
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Actor no resuelto' USING ERRCODE = 'P0001';
    END IF;

    -- Sanitizar código: solo alfanumérico + guiones (prevenir inyección)
    IF NOT (upper(trim(p_codigo)) ~ '^[A-Z0-9_-]{3,30}$') THEN
        RAISE EXCEPTION 'Formato de código inválido' USING ERRCODE = 'P0091';
    END IF;

    SELECT * INTO v_orden FROM auth.ordenes
    WHERE id = p_orden_id AND id_comprador = v_actor AND estado = 'pendiente';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden no encontrada, no pertenece al actor o ya confirmada'
            USING ERRCODE = 'P0092';
    END IF;

    SELECT * INTO v_prom FROM auth.promociones
    WHERE codigo = upper(trim(p_codigo)) AND activo = true;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Código de promoción inválido o inactivo'
            USING ERRCODE = 'P0093';
    END IF;

    IF now() NOT BETWEEN v_prom.fecha_inicio AND v_prom.fecha_fin THEN
        RAISE EXCEPTION 'La promoción no está vigente' USING ERRCODE = 'P0094';
    END IF;
    IF v_prom.max_usos IS NOT NULL AND v_prom.usos_actuales >= v_prom.max_usos THEN
        RAISE EXCEPTION 'La promoción ha agotado sus usos disponibles' USING ERRCODE = 'P0095';
    END IF;
    IF EXISTS (
        SELECT 1 FROM auth.promociones_aplicadas
        WHERE id_promocion = v_prom.id AND id_usuario = v_actor
    ) THEN
        RAISE EXCEPTION 'Ya usaste esta promoción anteriormente' USING ERRCODE = 'P0096';
    END IF;

    v_desc := CASE v_prom.tipo
        WHEN 'porcentaje' THEN ROUND(v_orden.total * v_prom.valor / 100, 2)
        WHEN 'monto_fijo' THEN LEAST(v_prom.valor, v_orden.total)
        WHEN 'envio_gratis' THEN 0
        WHEN 'puntos'      THEN 0
        ELSE 0
    END;
    v_puntos := CASE v_prom.tipo WHEN 'puntos' THEN v_prom.puntos_otorgados ELSE 0 END;

    INSERT INTO auth.promociones_aplicadas
        (id_orden, id_usuario, id_promocion, descripcion, monto_descuento, puntos_otorgados)
    VALUES (
        p_orden_id, v_actor, v_prom.id,
        v_prom.nombre || ' (' || v_prom.codigo || ')',
        v_desc, v_puntos
    );

    RETURN jsonb_build_object(
        'ok',              true,
        'promocion_id',    v_prom.id,
        'codigo',          v_prom.codigo,
        'tipo',            v_prom.tipo,
        'monto_descuento', v_desc,
        'puntos_otorgados',v_puntos,
        'total_antes',     v_orden.total,
        'total_despues',   v_orden.total - v_desc
    );
END;
$_$;


--
-- Name: fn_assert_seller_operable(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_assert_seller_operable(p_id_vendedor uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    AS $$
declare v_role text;
 v_profile_activo boolean;

begin
  select u.role,
         exists (
           select 1 from auth.perfiles_publicos_vendedor ppv
           where ppv.id_vendedor = u.id and ppv.activo = true
         )
  into v_role, v_profile_activo
  from auth.users u
  where u.id = p_id_vendedor;


  if not found then raise exception 'seller_not_found';
 end if;

  if v_role <> 'seller' then raise exception 'user_is_not_seller';
 end if;

  if coalesce(v_profile_activo, false) = false then raise exception 'seller_public_profile_inactive';
 end if;

end;
 $$;


--
-- Name: fn_assign_membership(uuid, text, uuid, integer, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_assign_membership(p_user_id uuid, p_tier text DEFAULT 'bronze'::text, p_assigned_by uuid DEFAULT NULL::uuid, p_duration_days integer DEFAULT NULL::integer, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_policy record;
  v_expires_at timestamptz;
  v_assignment_id uuid;
BEGIN
  IF NOT auth.fn_is_admin() THEN
    RAISE EXCEPTION 'Solo db_admin puede asignar membresías' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_policy
  FROM auth.membership_policy_catalog
  WHERE tier = lower(p_tier) AND active = true;

  IF v_policy IS NULL THEN
    RAISE EXCEPTION 'Membresía inválida o inactiva: %', p_tier USING ERRCODE = 'P0002';
  END IF;

  v_expires_at := CASE
    WHEN COALESCE(p_duration_days, NULLIF(v_policy.retention_days,'')::integer) IS NULL THEN NULL
    ELSE now() + make_interval(days => COALESCE(p_duration_days, NULLIF(v_policy.retention_days,'')::integer))
  END;

  UPDATE auth.user_membership_assignments
  SET estado = 'replaced', fecha_actualizacion = now()
  WHERE id_usuario = p_user_id AND estado = 'active';

  INSERT INTO auth.user_membership_assignments(
    id_usuario, tier, estado, inicia_en, fecha_expiracion, assigned_by, assignment_reason
  )
  VALUES (p_user_id, v_policy.tier, 'active', now(), v_expires_at, p_assigned_by, p_reason)
  RETURNING id INTO v_assignment_id;

  UPDATE auth.users
  SET default_tier_code = v_policy.tier,
      membership_expires_at = v_expires_at,
      fecha_actualizacion = now()
  WHERE id = p_user_id;

  INSERT INTO auth.user_lifecycle_audit(
    action, severity, actor_user_id, target_user_id, target_effective_tier,
    reason, after_state, source
  )
  VALUES ('MEMBERSHIP_ASSIGNED', 'info', p_assigned_by, p_user_id, v_policy.tier,
          p_reason, jsonb_build_object('tier', v_policy.tier, 'expires_at', v_expires_at), 'rpc');

  RETURN jsonb_build_object('assignment_id', v_assignment_id, 'tier', v_policy.tier, 'expires_at', v_expires_at);
END;
$$;


--
-- Name: fn_audit_producto_condicion(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_audit_producto_condicion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.condicion is distinct from old.condicion then
    insert into auth.h_productos_condicion_audit (
      id_producto, condicion_old, condicion_new,
      modificado_por, motivo, fecha_cambio
    ) values (
      old.id, old.condicion, new.condicion,
      auth.fn_try_current_user_id(), 'seller_upsert_product', now()
    );

  end if;

  return new;

end;
 $$;


--
-- Name: fn_audit_producto_precio_descuento(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_audit_producto_precio_descuento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.precio IS DISTINCT FROM OLD.precio
     OR NEW.descuento_porcentaje IS DISTINCT FROM OLD.descuento_porcentaje THEN
    INSERT INTO auth.h_productos_audit (
      id_producto, producto_id, operacion,
      datos_anteriores, datos_nuevos,
      precio_old, precio_new, descuento_old, descuento_new,
      modificado_por, motivo, fecha_cambio, fecha_creacion
    ) VALUES (
      OLD.id, OLD.id, TG_OP,
      jsonb_build_object('precio', OLD.precio, 'descuento', OLD.descuento_porcentaje),
      jsonb_build_object('precio', NEW.precio, 'descuento', NEW.descuento_porcentaje),
      COALESCE(OLD.precio, 0), COALESCE(NEW.precio, 0),
      COALESCE(OLD.descuento_porcentaje, 0), COALESCE(NEW.descuento_porcentaje, 0),
      COALESCE(auth.fn_try_current_user_id(), OLD.id_vendedor),
      'seller_upsert_product', now(), now()
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_auto_deactivate_no_stock_products(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_auto_deactivate_no_stock_products() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_dias integer;
    v_count integer := 0;
    v_prod record;
BEGIN
    SELECT (limite_jsonb ->> 'dias_sin_stock')::integer INTO v_dias
    FROM auth.politicas_operativas
    WHERE codigo = 'system.inventory.auto_deactivate' AND habilitada = true;

    v_dias := COALESCE(v_dias, 30);

    FOR v_prod IN
        SELECT ip.id_producto, ip.id_vendedor
        FROM auth.inventario_producto ip
        JOIN auth.productos p ON p.id = ip.id_producto
        WHERE ip.stock_disponible = 0
          AND ip.activo = true
          AND p.activo = true
          AND NOT EXISTS (
              SELECT 1 FROM auth.movimientos_inventario m
              WHERE m.id_producto = ip.id_producto
                AND m.tipo_movimiento IN ('entrada','ajuste_positivo')
                AND m.fecha_movimiento > now() - (v_dias || ' days')::interval
          )
    LOOP
        UPDATE auth.productos SET activo = false, fecha_modificacion = now()
        WHERE id = v_prod.id_producto;

        UPDATE auth.inventario_producto SET activo = false, fecha_modificacion = now()
        WHERE id_producto = v_prod.id_producto;

        INSERT INTO auth.admin_acciones_vendedor(
            id_vendedor, admin_user_id, accion, motivo
        )
        VALUES (
            v_prod.id_vendedor, NULL, 'auto_deactivate_product',
            format('Producto desactivado automáticamente por %s días sin stock', v_dias)
        );

        v_count := v_count + 1;
    END LOOP;

    RETURN v_count;
END;
$$;


--
-- Name: fn_block_physical_delete(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_block_physical_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF coalesce(current_setting('app.bypass_product_delete_guard', true), '') = 'on'
     OR coalesce(current_setting('app.allow_physical_purge', true), '') IN ('true', 'on')
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'physical_delete_blocked_on_%.%;
_use_soft_delete_rpc', TG_TABLE_SCHEMA, TG_TABLE_NAME;
END;
$$;


--
-- Name: FUNCTION fn_block_physical_delete(); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.fn_block_physical_delete() IS 'Guard DELETE físico genérico; escape hatch unificado app.allow_physical_purge=true|on (migración 102).';


--
-- Name: fn_bundle_deactivate_audit(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_bundle_deactivate_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    IF OLD.activo = true AND NEW.activo = false THEN
        INSERT INTO auth.h_vendedores_audit (id_usuario, operacion, datos_nuevos, motivo)
        VALUES (
            NEW.id_vendedor,
            'UPDATE',
            jsonb_build_object(
                'bundle_id', NEW.id,
                'nombre', NEW.nombre,
                'descuento_pct', NEW.descuento_pct,
                'accion', 'bundle_desactivado'
            ),
            'Bundle desactivado: ' || NEW.nombre
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_bundle_item_check_vendedor(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_bundle_item_check_vendedor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_vendedor_bundle   uuid;
    v_vendedor_producto uuid;
BEGIN
    SELECT b.id_vendedor INTO v_vendedor_bundle
    FROM auth.bundles_producto b WHERE b.id = NEW.id_lote;

    SELECT p.id_vendedor INTO v_vendedor_producto
    FROM auth.productos p WHERE p.id = NEW.id_producto;

    IF v_vendedor_bundle IS DISTINCT FROM v_vendedor_producto THEN
        RAISE EXCEPTION 'El producto % no pertenece al vendedor del bundle',
            NEW.id_producto USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: fn_bundle_updated_at(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_bundle_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN NEW.fecha_mod := now(); RETURN NEW; END;
$$;


--
-- Name: fn_calcular_abc_inventario(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_calcular_abc_inventario(p_id_vendedor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_caller uuid := auth.fn_current_user_id();
    v_limits jsonb;
BEGIN
    -- Solo Silver+ puede acceder a análisis ABC
    IF auth.fn_current_role() NOT IN ('db_admin','system') THEN
        v_limits := auth.fn_get_inventory_limits(v_caller);
        IF (v_limits ->> 'inventory_abc_analysis')::boolean IS NOT TRUE THEN
            RAISE EXCEPTION 'Análisis ABC solo disponible para Silver+';
        END IF;
    END IF;

    -- Calcular y clasificar
    WITH movimientos AS (
        SELECT
            m.id_vendedor,
            m.id_producto,
            count(*) AS num_movimientos,
            sum(abs(m.cantidad)) AS unidades_movidas,
            sum(abs(m.cantidad) * COALESCE(p.precio, 0)) AS valor_movido
        FROM auth.movimientos_inventario m
        JOIN auth.productos p ON p.id = m.id_producto
        WHERE m.id_vendedor = p_id_vendedor
          AND m.tipo_movimiento IN ('salida','consumo_reserva')
          AND m.fecha_movimiento > now() - interval '90 days'
        GROUP BY m.id_vendedor, m.id_producto
    ),
    total AS (
        SELECT sum(valor_movido) AS total_valor FROM movimientos
    ),
    ranked AS (
        SELECT
            m.*,
            sum(m.valor_movido) OVER (ORDER BY m.valor_movido DESC) / NULLIF(t.total_valor,0) * 100 AS pct_acum
        FROM movimientos m, total t
    )
    INSERT INTO auth.inventario_abc_analysis(
        id_vendedor, id_producto, clasificacion, movimientos_90d,
        porcentaje_acumulado, unidades_movidas_90d, valor_movido_90d
    )
    SELECT
        r.id_vendedor, r.id_producto,
        CASE WHEN r.pct_acum <= 70 THEN 'A'
             WHEN r.pct_acum <= 90 THEN 'B'
             ELSE 'C' END,
        r.num_movimientos, COALESCE(r.pct_acum, 100),
        r.unidades_movidas, r.valor_movido
    FROM ranked r
    ON CONFLICT (id_vendedor, id_producto) DO UPDATE SET
        clasificacion = EXCLUDED.clasificacion,
        movimientos_90d = EXCLUDED.movimientos_90d,
        porcentaje_acumulado = EXCLUDED.porcentaje_acumulado,
        unidades_movidas_90d = EXCLUDED.unidades_movidas_90d,
        valor_movido_90d = EXCLUDED.valor_movido_90d,
        calculado_en = now();
END;
$$;


--
-- Name: fn_calcular_afinidad(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_calcular_afinidad(p_id_vendedor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_total_transacciones integer;
BEGIN
    SELECT COUNT(DISTINCT o.id) INTO v_total_transacciones
    FROM auth.ordenes o
    WHERE o.id_vendedor = p_id_vendedor AND o.estado = 'confirmada';

    IF v_total_transacciones < 10 THEN
        RAISE NOTICE 'Vendedor % tiene < 10 transacciones, omitiendo cálculo', p_id_vendedor;
        RETURN;
    END IF;

    INSERT INTO auth.afinidad_productos (
        id_vendedor, producto_a_id, producto_b_id,
        frecuencia, confianza, lift, tipo_correlacion
    )
    WITH transacciones AS (
        SELECT DISTINCT oi.id_orden, oi.id_producto
        FROM auth.orden_items oi
        JOIN auth.ordenes o ON o.id = oi.id_orden
        WHERE o.id_vendedor = p_id_vendedor AND o.estado = 'confirmada'
    ),
    pares AS (
        SELECT
            LEAST(a.id_producto, b.id_producto)    AS prod_a,
            GREATEST(a.id_producto, b.id_producto) AS prod_b,
            COUNT(DISTINCT a.id_orden)::integer    AS frecuencia_ab
        FROM transacciones a
        JOIN transacciones b
            ON a.id_orden = b.id_orden AND a.id_producto != b.id_producto
        GROUP BY LEAST(a.id_producto, b.id_producto),
                 GREATEST(a.id_producto, b.id_producto)
        HAVING COUNT(DISTINCT a.id_orden) >= 2
    ),
    soporte_individual AS (
        SELECT id_producto, COUNT(DISTINCT id_orden)::numeric AS freq
        FROM transacciones GROUP BY id_producto
    )
    SELECT
        p_id_vendedor,
        pr.prod_a,
        pr.prod_b,
        pr.frecuencia_ab,
        ROUND((pr.frecuencia_ab::numeric / sa.freq), 4),
        ROUND(
            (pr.frecuencia_ab::numeric / v_total_transacciones)
            / ((sa.freq / v_total_transacciones) * (sb.freq / v_total_transacciones)),
        4),
        CASE
            WHEN ROUND(
                    (pr.frecuencia_ab::numeric / v_total_transacciones)
                    / ((sa.freq / v_total_transacciones) * (sb.freq / v_total_transacciones)),
                 4) > 1.2 THEN 'positiva'
            WHEN ROUND(
                    (pr.frecuencia_ab::numeric / v_total_transacciones)
                    / ((sa.freq / v_total_transacciones) * (sb.freq / v_total_transacciones)),
                 4) < 0.8 THEN 'negativa'
            ELSE 'neutra'
        END
    FROM pares pr
    JOIN soporte_individual sa ON sa.id_producto = pr.prod_a
    JOIN soporte_individual sb ON sb.id_producto = pr.prod_b
    ON CONFLICT (id_vendedor, producto_a_id, producto_b_id) DO UPDATE SET
        frecuencia       = EXCLUDED.frecuencia,
        confianza        = EXCLUDED.confianza,
        lift             = EXCLUDED.lift,
        tipo_correlacion = EXCLUDED.tipo_correlacion,
        calculado_en     = now();
END;
$$;


--
-- Name: fn_calcular_badge_confiable(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_calcular_badge_confiable(p_id_vendedor uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_avg         numeric;
    v_total       integer;
    v_resenas_pos integer;
    v_score       integer;
    v_cumple      boolean;
BEGIN
    SELECT
        COALESCE(ROUND(AVG(calificacion)::numeric, 2), 0),
        COUNT(*)::integer,
        COUNT(*) FILTER (WHERE calificacion >= 4)::integer
    INTO v_avg, v_total, v_resenas_pos
    FROM auth.resenas
    WHERE id_vendedor = p_id_vendedor AND verificada = true AND moderada = false;

    SELECT COALESCE(score, 100) INTO v_score
    FROM public.user_risk_scores WHERE id_usuario = p_id_vendedor;

    v_cumple := (v_score < 25 AND v_avg > 4.5 AND v_total >= 10);

    INSERT INTO auth.badge_confiable (
        id_vendedor, tiene_badge, calificacion, score_riesgo,
        total_resenas, resenas_positivas, cumple_criterio, ultima_eval, otorgado_en
    ) VALUES (
        p_id_vendedor, v_cumple, v_avg, COALESCE(v_score, 100),
        v_total, v_resenas_pos, v_cumple, now(),
        CASE WHEN v_cumple THEN now() ELSE NULL END
    )
    ON CONFLICT (id_vendedor) DO UPDATE SET
        tiene_badge       = v_cumple,
        calificacion      = v_avg,
        score_riesgo      = COALESCE(v_score, 100),
        total_resenas     = v_total,
        resenas_positivas = v_resenas_pos,
        cumple_criterio   = v_cumple,
        ultima_eval       = now(),
        otorgado_en       = CASE
            WHEN v_cumple AND NOT auth.badge_confiable.tiene_badge THEN now()
            ELSE auth.badge_confiable.otorgado_en
        END,
        revocado_en       = CASE
            WHEN NOT v_cumple AND auth.badge_confiable.tiene_badge THEN now()
            ELSE auth.badge_confiable.revocado_en
        END,
        fecha_mod         = now();

    -- Cascada a perfiles_publicos_vendedor
    UPDATE auth.perfiles_publicos_vendedor SET
        score_reputacion           = v_avg,
        total_resenas              = v_total,
        resenas_positivas          = v_resenas_pos,
        ultima_actualizacion_score = now()
    WHERE id_vendedor = p_id_vendedor;

    RETURN v_cumple;
END;
$$;


--
-- Name: fn_calcular_clusters_compradores(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_calcular_clusters_compradores(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_n integer;
BEGIN
  DELETE FROM auth.ubicacion_clusters WHERE id_usuario = p_id_vendedor;

  WITH compradores AS (
    SELECT DISTINCT u.id AS id_usuario, ub.punto
      FROM auth.users u
      JOIN auth.ubicaciones ub ON ub.id_usuario = u.id AND ub.is_active = true
     WHERE u.role = 'buyer'
  ), clustered AS (
    SELECT id_usuario, punto,
           ST_ClusterDBSCAN(punto::geometry, 0.01, 2) OVER () AS cid
      FROM compradores
  )
  INSERT INTO auth.ubicacion_clusters
    (id, id_usuario, id_cluster, cluster_centroid, ubicacion_ids, radio_km, calculado_at, metadata)
  SELECT gen_random_uuid(), p_id_vendedor, cid,
         ST_Centroid(ST_Collect(punto::geometry))::geometry,
         array_agg(id_usuario),
         COALESCE(ST_MaxDistance(ST_Centroid(ST_Collect(punto::geometry)), ST_Collect(punto::geometry)) / 1000.0, 0),
         now(), jsonb_build_object('n', count(*))
    FROM clustered WHERE cid IS NOT NULL GROUP BY cid;

  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('clusters_calculados', v_n, 'id_vendedor', p_id_vendedor);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: fn_calcular_clusters_ubicaciones_vendedor(uuid, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_calcular_clusters_ubicaciones_vendedor(p_id_vendedor uuid DEFAULT NULL::uuid, p_k integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_user_id  uuid := COALESCE(
    p_id_vendedor,
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid
  );
  v_limits   jsonb;
  v_count    integer;
  v_inserted integer;
BEGIN
  -- Verificar plan Gold si llamado por usuario (no pg_cron)
  IF p_id_vendedor IS NULL THEN
    v_limits := auth.fn_get_location_limits(v_user_id);
    IF NOT (v_limits->>'clusters_geo')::boolean THEN
      RAISE EXCEPTION 'feature_requiere_plan_gold_o_superior';
    END IF;
  END IF;

  SELECT COUNT(*) INTO v_count
  FROM auth.ubicaciones
  WHERE id_usuario = v_user_id
    AND estado = 'activo'
    AND fecha_eliminacion IS NULL
    AND punto IS NOT NULL;

  IF v_count < p_k THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'ubicaciones_insuficientes_para_k_clusters',
      'ubicaciones_activas', v_count,
      'k_requerido', p_k
    );
  END IF;

  -- Limpiar clusters anteriores del vendedor
  DELETE FROM auth.ubicacion_clusters WHERE id_usuario = v_user_id;

  -- Calcular con ST_ClusterKMeans
  INSERT INTO auth.ubicacion_clusters
    (id_usuario, id_cluster, cluster_centroid, ubicacion_ids, radio_km)
  WITH clustered AS (
    SELECT
      id,
      punto,
      ST_ClusterKMeans(punto::geometry, p_k)
        OVER (PARTITION BY id_usuario) AS cid
    FROM auth.ubicaciones
    WHERE id_usuario = v_user_id
      AND estado = 'activo'
      AND fecha_eliminacion IS NULL
      AND punto IS NOT NULL
  ),
  agg AS (
    SELECT
      cid,
      ST_Centroid(ST_Collect(punto::geometry))::geography AS centroid,
      ARRAY_AGG(id) AS ids,
      MAX(ST_Distance(
        punto,
        ST_Centroid(ST_Collect(punto::geometry))::geography
      )) / 1000.0 AS radio_km
    FROM clustered
    GROUP BY cid
  )
  SELECT
    v_user_id,
    cid,
    centroid,
    ids,
    ROUND(radio_km::numeric, 3)
  FROM agg;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'clusters_calculados', v_inserted,
    'k', p_k
  );
END;
$$;


--
-- Name: fn_calcular_comunidades_louvain_age(uuid, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_calcular_comunidades_louvain_age(p_id_vendedor uuid, p_min_comunes integer DEFAULT 2) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $_$
DECLARE
    v_graph_name text;
    v_result     record;
    v_count      integer := 0;
    v_cluster_id uuid := 0;
    v_visited    uuid[] := '{}';
BEGIN
    BEGIN
        SELECT name INTO v_graph_name FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;
        IF v_graph_name IS NULL THEN RETURN 0; END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'AGE no disponible para Louvain: %', SQLERRM;
        RETURN 0;
    END;

    -- Detectar compradores que comparten vendedores (proxy de Louvain)
    -- Cada grupo de compradores con >= p_min_comunes vendedores en común = comunidad
    FOR v_result IN
        EXECUTE format(
            $age$
            SELECT row_to_json(t) AS data
            FROM (
                SELECT * FROM cypher(%L, $c$
                    MATCH (b1:Buyer)-[:COMPRO_EN]->(s:Seller)<-[:COMPRO_EN]-(b2:Buyer)
                    WHERE b1.id_usuario < b2.id_usuario
                    WITH b1, b2, COUNT(s) AS comunes
                    WHERE comunes >= %s
                    RETURN b1.id_usuario AS buyer1, b2.id_usuario AS buyer2, comunes
                $c$) AS (buyer1 agtype, buyer2 agtype, comunes agtype)
            ) t
            $age$,
            v_graph_name, p_min_comunes
        )
    LOOP
        -- Asignar misma comunidad a pares relacionados (union-find simple)
        INSERT INTO auth.buyer_comunidades (
            id_vendedor, comunidad_id, id_comprador, algoritmo, score_pertenencia
        ) VALUES
            (p_id_vendedor, v_cluster_id,
             (v_result.data->>'buyer1')::uuid, 'louvain_age', 0.8),
            (p_id_vendedor, v_cluster_id,
             (v_result.data->>'buyer2')::uuid, 'louvain_age', 0.8)
        ON CONFLICT (id_vendedor, id_comprador, algoritmo) DO UPDATE SET
            comunidad_id     = EXCLUDED.comunidad_id,
            calculado_en     = now();
        v_count := v_count + 1;
        v_cluster_id := v_cluster_id + 1;
    END LOOP;

    RETURN v_count;
END;
$_$;


--
-- Name: fn_calcular_forecast_inventario(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_calcular_forecast_inventario(p_id_vendedor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_caller uuid := auth.fn_current_user_id();
    v_limits jsonb;
BEGIN
    IF auth.fn_current_role() NOT IN ('db_admin','system') THEN
        v_limits := auth.fn_get_inventory_limits(v_caller);
        IF (v_limits ->> 'inventory_forecasting')::boolean IS NOT TRUE THEN
            RAISE EXCEPTION 'Forecasting de inventario solo disponible para Gold';
        END IF;
    END IF;

    -- Usar regresión nativa PostgreSQL sobre ventana de 30 días
    WITH consumos_diarios AS (
        SELECT
            id_vendedor, id_producto,
            date_trunc('day', fecha_movimiento) AS dia,
            sum(abs(cantidad)) AS unidades_consumidas
        FROM auth.movimientos_inventario
        WHERE id_vendedor = p_id_vendedor
          AND tipo_movimiento IN ('salida','consumo_reserva')
          AND fecha_movimiento > now() - interval '30 days'
        GROUP BY id_vendedor, id_producto, date_trunc('day', fecha_movimiento)
    ),
    regresion AS (
        SELECT
            id_vendedor, id_producto,
            regr_count(unidades_consumidas, extract(epoch from dia)) AS puntos,
            regr_slope(unidades_consumidas, extract(epoch from dia)) * 86400 AS tasa_diaria, -- unidades/día
            regr_r2(unidades_consumidas, extract(epoch from dia)) AS r2
        FROM consumos_diarios
        GROUP BY id_vendedor, id_producto
    )
    INSERT INTO auth.inventario_forecast(
        id_vendedor, id_producto, dias_para_agotamiento, tasa_consumo_diaria,
        stock_actual, r2_ajuste, puntos_datos, confianza, recomendacion
    )
    SELECT
        r.id_vendedor, r.id_producto,
        CASE WHEN COALESCE(r.tasa_diaria, 0) > 0
             THEN ip.stock_disponible / r.tasa_diaria
             ELSE NULL END,
        r.tasa_diaria,
        ip.stock_disponible,
        r.r2,
        r.puntos::integer,
        CASE WHEN r.puntos >= 14 AND r.r2 > 0.7 THEN 'alta'
             WHEN r.puntos >= 7 AND r.r2 > 0.4 THEN 'media'
             ELSE 'baja' END,
        CASE
            WHEN COALESCE(r.tasa_diaria, 0) <= 0 THEN 'Sin consumo reciente'
            WHEN ip.stock_disponible / NULLIF(r.tasa_diaria, 0) < 7
                THEN format('¡Urgente! Stock se agota en %.0f días', ip.stock_disponible / r.tasa_diaria)
            WHEN ip.stock_disponible / NULLIF(r.tasa_diaria, 0) < 14
                THEN format('Reponer pronto — %.0f días restantes', ip.stock_disponible / r.tasa_diaria)
            ELSE 'Stock suficiente para el período analizado'
        END
    FROM regresion r
    JOIN auth.inventario_producto ip ON ip.id_producto = r.id_producto
    ON CONFLICT (id_vendedor, id_producto) DO UPDATE SET
        dias_para_agotamiento = EXCLUDED.dias_para_agotamiento,
        tasa_consumo_diaria = EXCLUDED.tasa_consumo_diaria,
        stock_actual = EXCLUDED.stock_actual,
        r2_ajuste = EXCLUDED.r2_ajuste,
        puntos_datos = EXCLUDED.puntos_datos,
        confianza = EXCLUDED.confianza,
        recomendacion = EXCLUDED.recomendacion,
        calculado_en = now();
END;
$$;


--
-- Name: fn_calcular_prediccion_demanda(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_calcular_prediccion_demanda(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_7d bigint; v_30d bigint; v_90d bigint; v_gmv numeric; v_res jsonb;
BEGIN
  SELECT count(*) FILTER (WHERE o.fecha_creacion >= now() - interval '7 days'),
         count(*) FILTER (WHERE o.fecha_creacion >= now() - interval '30 days'),
         count(*),
         coalesce(sum(o.total) FILTER (WHERE o.fecha_creacion >= now() - interval '30 days'), 0)
    INTO v_7d, v_30d, v_90d, v_gmv
    FROM auth.ordenes o
   WHERE o.id_vendedor = p_id_vendedor AND o.fecha_eliminacion IS NULL;

  v_res := jsonb_build_object(
    'id_vendedor', p_id_vendedor,
    'ordenes_7d', v_7d, 'ordenes_30d', v_30d, 'ordenes_90d', v_90d,
    'gmv_30d', v_gmv,
    'promedio_diario_7d', ROUND(v_7d::numeric / 7.0, 2),
    'prediccion_7d', ROUND((v_7d::numeric / 7.0) * 7, 2),
    'calculado_en', now());
  RETURN v_res;
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: fn_calcular_rfm_snapshot(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_calcular_rfm_snapshot(p_id_vendedor uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_hoy   date := CURRENT_DATE;
    v_count integer := 0;
BEGIN
    INSERT INTO auth.rfm_snapshots (
        id_vendedor, id_comprador, snapshot_date,
        recencia_dias, frecuencia, total, segmento, score_rfm
    )
    SELECT
        p_id_vendedor,
        id_comprador,
        v_hoy,
        recencia_dias,
        frecuencia,
        total,
        -- RN-007: Segmentos canónicos
        CASE
            WHEN recencia_dias <= 30  AND frecuencia >= 5 THEN 'champion'
            WHEN recencia_dias <= 60  AND frecuencia >= 3 THEN 'loyal'
            WHEN recencia_dias BETWEEN 61 AND 120          THEN 'at_risk'
            WHEN recencia_dias BETWEEN 121 AND 180         THEN 'hibernating'
            WHEN recencia_dias > 180                       THEN 'lost'
            WHEN frecuencia = 1                            THEN 'new'
            ELSE 'new'
        END                           AS segmento,
        -- RN-008: Score RFM 0-100 (R=40pts, F=40pts, M=20pts)
        LEAST(100.0,
            GREATEST(0, 40.0 - (recencia_dias::numeric * 40.0 / 180.0))
            + LEAST(frecuencia * 8.0, 40.0)
            + LEAST(total / 500.0, 20.0)
        )::numeric(5,2)               AS score_rfm
    FROM (
        SELECT
            id_comprador,
            EXTRACT(DAY FROM (now() - MAX(fecha_creacion)))::integer AS recencia_dias,
            COUNT(*)::integer                                         AS frecuencia,
            SUM(total)                                                AS total
        FROM auth.ordenes
        WHERE id_vendedor = p_id_vendedor
          AND estado = 'confirmada'
        GROUP BY id_comprador
    ) sq
    ON CONFLICT (id_vendedor, id_comprador, snapshot_date)
    DO UPDATE SET
        recencia_dias = EXCLUDED.recencia_dias,
        frecuencia    = EXCLUDED.frecuencia,
        total   = EXCLUDED.total,
        segmento      = EXCLUDED.segmento,
        score_rfm     = EXCLUDED.score_rfm;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


