--
-- Name: fn_canjear_beneficio(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_canjear_beneficio(p_beneficio_id uuid, p_ref_operacion text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor_id  uuid;
    v_billetera record;
    v_beneficio record;
    v_canje_id  uuid;
    v_ref       text;
BEGIN
    v_actor_id := auth.fn_current_user_id();
    v_ref      := COALESCE(p_ref_operacion, public.gen_random_uuid()::text);

    IF EXISTS (
        SELECT 1 FROM auth.canjes_puntos
        WHERE referencia_operacion = v_ref
          AND id_usuario = v_actor_id
          AND fecha_canje > now() - INTERVAL '60 seconds'
    ) THEN
        RETURN (
            SELECT jsonb_build_object(
                'canje_id',    id,
                'saldo_nuevo', saldo_posterior,
                'idempotente', true
            )
            FROM auth.canjes_puntos
            WHERE referencia_operacion = v_ref AND id_usuario = v_actor_id
            LIMIT 1
        );
    END IF;

    SELECT * INTO v_beneficio
    FROM auth.beneficios_catalogo
    WHERE id = p_beneficio_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'beneficio_no_encontrado', 'codigo', 'WALLET_004');
    END IF;
    IF NOT v_beneficio.activo THEN
        RETURN jsonb_build_object('error', 'beneficio_inactivo', 'codigo', 'WALLET_005');
    END IF;

    SELECT * INTO v_billetera FROM auth.billetera
    WHERE id_usuario = v_actor_id FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'billetera_no_encontrada', 'codigo', 'WALLET_001');
    END IF;
    IF NOT v_billetera.activo THEN
        RETURN jsonb_build_object('error', 'billetera_suspendida', 'codigo', 'WALLET_003');
    END IF;
    IF v_billetera.saldo < v_beneficio.costo_puntos THEN
        RETURN jsonb_build_object(
            'error',        'saldo_insuficiente', 'codigo', 'WALLET_002',
            'saldo_actual', v_billetera.saldo,
            'requerido',    v_beneficio.costo_puntos,
            'diferencia',   v_beneficio.costo_puntos - v_billetera.saldo
        );
    END IF;

    UPDATE auth.billetera
    SET saldo = saldo - v_beneficio.costo_puntos,
        fecha_modificacion = now()
    WHERE id_usuario = v_actor_id;

    INSERT INTO auth.canjes_puntos (
        id_usuario, beneficio_id, puntos_debitados, saldo_anterior, saldo_posterior,
        estado, referencia_operacion, detalle
    ) VALUES (
        v_actor_id, p_beneficio_id, v_beneficio.costo_puntos,
        v_billetera.saldo, v_billetera.saldo - v_beneficio.costo_puntos,
        'aprobado', v_ref,
        jsonb_build_object('origen', 'seller_panel', 'beneficio_codigo', v_beneficio.codigo)
    ) RETURNING id INTO v_canje_id;

    INSERT INTO auth.movimientos_puntos (
        id_usuario, tipo_movimiento, monto, saldo_anterior, saldo_posterior,
        referencia, detalle
    ) VALUES (
        v_actor_id, 'canje', -v_beneficio.costo_puntos,
        v_billetera.saldo, v_billetera.saldo - v_beneficio.costo_puntos,
        v_canje_id::text,
        jsonb_build_object('beneficio_id', p_beneficio_id, 'beneficio_codigo', v_beneficio.codigo)
    );

    RETURN jsonb_build_object(
        'canje_id',         v_canje_id,
        'saldo_nuevo',      v_billetera.saldo - v_beneficio.costo_puntos,
        'puntos_debitados', v_beneficio.costo_puntos
    );
END;
$$;


--
-- Name: fn_chatbot_evaluar_respuesta(uuid, uuid, text, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_chatbot_evaluar_respuesta(p_mensaje_id uuid, p_conversacion_id uuid, p_cuerpo text, p_id_vendedor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_regla     auth.chatbot_reglas%ROWTYPE;
    v_sim       numeric(4,3);
    v_msg_bot_id uuid;
    v_texto_norm text;
BEGIN
    -- Normalizar texto (minúsculas, sin tildes)
    v_texto_norm := lower(unaccent(p_cuerpo));

    -- Buscar mejor regla: primero del vendedor, luego globales
    SELECT r.*, similarity(v_texto_norm, lower(unaccent(r.patron))) AS sim
    INTO v_regla
    FROM auth.chatbot_reglas r
    WHERE r.activa = true
      AND (r.id_vendedor = p_id_vendedor OR r.id_vendedor IS NULL)
      AND similarity(v_texto_norm, lower(unaccent(r.patron))) >= r.umbral_sim
    ORDER BY
        (r.id_vendedor IS NOT NULL) DESC,  -- priorizar reglas del vendedor
        similarity(v_texto_norm, lower(unaccent(r.patron))) DESC,
        r.prioridad ASC
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN;  -- Sin coincidencia, no responder
    END IF;

    v_sim := similarity(v_texto_norm, lower(unaccent(v_regla.patron)));

    -- Insertar respuesta del chatbot como mensaje de sistema
    -- emisor_id = id_vendedor (chatbot actúa en nombre del vendedor)
    INSERT INTO auth.mensajes
        (id_conversacion, emisor_id, cuerpo, tipo_contenido,
         metadata)
    VALUES (
        p_conversacion_id,
        p_id_vendedor,
        v_regla.respuesta,
        'chatbot',
        jsonb_build_object(
            'chatbot', true,
            'regla_id', v_regla.id,
            'similitud', v_sim
        )
    )
    RETURNING id INTO v_msg_bot_id;

    -- Registrar en log
    INSERT INTO auth.chatbot_log
        (id_conversacion, mensaje_origen_id, regla_id, mensaje_bot_id, similitud, escalado)
    VALUES (p_conversacion_id, p_mensaje_id, v_regla.id, v_msg_bot_id, v_sim,
            v_regla.tipo_respuesta = 'escalamiento');

    -- Actualizar contador de usos de la regla
    UPDATE auth.chatbot_reglas SET usos_count = usos_count + 1
    WHERE id = v_regla.id;

EXCEPTION WHEN OTHERS THEN
    -- Degradación elegante: si chatbot falla, no bloquear mensaje principal
    NULL;
END;
$$;


--
-- Name: fn_check_downgrade_limites(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_check_downgrade_limites() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_new_max_prod   integer;
    v_new_max_ubi    integer;
    v_count_prod     integer;
    v_count_ubi      integer;
    v_plan_ant_precio numeric;
    v_plan_nuevo_precio numeric;
BEGIN
    -- Solo validar en cambio de plan
    IF NEW.id_plan = OLD.id_plan THEN RETURN NEW; END IF;

    -- Solo aplicar si es downgrade (precio menor)
    SELECT precio_mensual INTO v_plan_ant_precio  FROM auth.planes_membresia WHERE id = OLD.id_plan;
    SELECT precio_mensual INTO v_plan_nuevo_precio FROM auth.planes_membresia WHERE id = NEW.id_plan;

    IF v_plan_nuevo_precio >= v_plan_ant_precio THEN RETURN NEW; END IF; -- upgrade OK

    SELECT max_productos, max_ubicaciones
    INTO v_new_max_prod, v_new_max_ubi
    FROM auth.planes_membresia WHERE id = NEW.id_plan;

    SELECT COUNT(*) INTO v_count_prod
    FROM auth.productos
    WHERE id_vendedor = NEW.id_vendedor AND activo = true;

    SELECT COUNT(*) INTO v_count_ubi
    FROM auth.ubicaciones
    WHERE id_usuario = NEW.id_vendedor AND estado = 'activo';

    IF v_count_prod > v_new_max_prod THEN
        RAISE EXCEPTION 'downgrade_blocked_products: tienes % productos activos; plan % permite %',
            v_count_prod, (SELECT codigo FROM auth.planes_membresia WHERE id = NEW.id_plan), v_new_max_prod
        USING ERRCODE = 'P0001';
    END IF;

    IF v_count_ubi > v_new_max_ubi THEN
        RAISE EXCEPTION 'downgrade_blocked_ubicaciones: tienes % ubicaciones activas; plan % permite %',
            v_count_ubi, (SELECT codigo FROM auth.planes_membresia WHERE id = NEW.id_plan), v_new_max_ubi
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: fn_check_inventory_domain_policy(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_check_inventory_domain_policy(p_action text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_enabled boolean;
BEGIN
    SELECT habilitada INTO v_enabled
    FROM auth.politicas_operativas
    WHERE dominio = 'inventario' AND accion = p_action AND rol_aplicable = 'db_admin'
    LIMIT 1;
    RETURN COALESCE(v_enabled, true); -- default permisivo si no hay política
END;
$$;


--
-- Name: fn_count_active_products(uuid, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_count_active_products(p_id_vendedor uuid, p_exclude_producto_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  select count(*)::integer
  from auth.productos p
  where p.id_vendedor = p_id_vendedor
    and p.activo = true
    and p.fecha_eliminacion is null
    and (p_exclude_producto_id is null or p.id <> p_exclude_producto_id);

$$;


--
-- Name: fn_current_role(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_current_role() RETURNS text
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(NULLIF(current_setting('request.jwt.claim.role', true), ''), 'anon')
$$;


--
-- Name: fn_current_user_id(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_current_user_id() RETURNS uuid
    LANGUAGE plpgsql STABLE
    AS $$
declare v_claims jsonb;
 v_actor text;

begin
  v_claims := auth.fn_request_claims();

  v_actor := coalesce(
    v_claims ->> 'sub',
    v_claims ->> 'user_id',
    nullif(current_setting('app.current_user_id', true), '')
  );

  if v_actor is null or btrim(v_actor) = '' then
    raise exception 'unable_to_resolve_current_user';

  end if;

  return v_actor::uuid;

end;
 $$;


