-- Name: fn_current_user_id_safe(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_current_user_id_safe() RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
BEGIN
