--
-- Name: fn_current_user_role(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_current_user_role() RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
declare v_claims jsonb;
 v_role text;

begin
  v_claims := auth.fn_request_claims();

  v_role := coalesce(
