--
-- Name: fn_desconectar_ws_session(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_desconectar_ws_session(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_actor uuid := auth.uid();
BEGIN
    UPDATE auth.ws_sessions SET activa = false
    WHERE id = p_session_id AND id_usuario = v_actor;

    PERFORM pg_notify(
        'mensajes_kambalache',
        json_build_object(
            'evento',     'sesion_cerrada',
            'id_usuario',    v_actor,
            'session_id', p_session_id
        )::text
    );

    RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: fn_detectar_comunidades(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_detectar_comunidades() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_role TEXT;
BEGIN
    v_role := auth.current_jwt_role();

    IF v_role NOT IN ('admin', 'moderador', 'db_admin', 'svc_postgrest_admin') THEN
        RAISE EXCEPTION 'forbidden'
            USING ERRCODE = '42501',
                  MESSAGE = 'solo admin/moderador pueden ejecutar fn_detectar_comunidades';
    END IF;

    RETURN jsonb_build_object(
        'status', 'ok',
        'comunidades', jsonb_build_array()
    );
END;
$$;


--
-- Name: fn_detectar_geofence_local(numeric, numeric); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_detectar_geofence_local(p_lat numeric, p_lon numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_punto geometry;
  v_result jsonb;
BEGIN
  v_punto := ST_SetSRID(ST_MakePoint(p_lon, p_lat), 4326);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id_zona', z.id_zona,
           'name',    z.name,
           'zone_type', z.zone_type
         )), '[]'::jsonb)
    INTO v_result
   FROM public.geo_zones z
  WHERE z.is_active = true
    AND z.fecha_eliminacion IS NULL
    AND ST_Contains(z.geom, v_punto);

  RETURN v_result;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: fn_enqueue_compro_en_outbox(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_enqueue_compro_en_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    -- Solo cuando una orden pasa a 'confirmada'
    IF NEW.estado = 'confirmada' AND (OLD.estado IS DISTINCT FROM 'confirmada') THEN
        INSERT INTO auth.clientes_graph_outbox (operacion, payload)
        VALUES (
            'UPSERT_COMPRO_EN',
            jsonb_build_object(
                'id_comprador', NEW.id_comprador,
                'id_vendedor',  NEW.id_vendedor,
                'orden_id',     NEW.id,
                'total',        NEW.total,
                'fecha',        NEW.fecha_creacion
            )
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_enviar_mensaje(uuid, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_enviar_mensaje(p_conversacion_id uuid, p_cuerpo text, p_tipo_contenido text DEFAULT 'texto'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor  uuid;
    v_msg_id uuid;
BEGIN
    v_actor := coalesce(
        (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')::uuid
    );
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Actor no resuelto desde JWT' USING ERRCODE = 'P0001';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM auth.conversaciones
        WHERE id = p_conversacion_id
          AND (id_comprador = v_actor OR id_vendedor = v_actor)
          AND estado = 'activa'
    ) THEN
        RAISE EXCEPTION 'Conversación no encontrada, no autorizado o cerrada'
            USING ERRCODE = 'P0033';
    END IF;

    INSERT INTO auth.mensajes
        (id_conversacion, emisor_id, cuerpo, tipo_contenido)
    VALUES (p_conversacion_id, v_actor, p_cuerpo, p_tipo_contenido)
    RETURNING id INTO v_msg_id;

    RETURN jsonb_build_object('ok', true, 'mensaje_id', v_msg_id);
END;
$$;


--
-- Name: fn_escalar_a_consulta_servicio(uuid, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_escalar_a_consulta_servicio(p_conversacion_id uuid, p_motivo text, p_tipo_consulta text DEFAULT 'postventa'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor      uuid;
    v_conv       auth.conversaciones%ROWTYPE;
    v_consulta_id uuid;
    v_escalada_id uuid;
BEGIN
    v_actor := coalesce(
        (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')::uuid
    );
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Actor no resuelto desde JWT' USING ERRCODE = 'P0001';
    END IF;

    SELECT * INTO v_conv FROM auth.conversaciones WHERE id = p_conversacion_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Conversación no encontrada' USING ERRCODE = 'P0034';
    END IF;

    -- Verificar que el actor es participante
    IF v_actor NOT IN (v_conv.id_comprador, v_conv.id_vendedor)
       AND auth.role() <> 'db_admin' THEN
        RAISE EXCEPTION 'No autorizado para escalar esta conversación' USING ERRCODE = 'P0041';
    END IF;

    -- Verificar que no está ya escalada
    IF EXISTS (
        SELECT 1 FROM auth.consultas_escaladas
        WHERE id_conversacion = p_conversacion_id AND estado_sync = 'activo'
    ) THEN
        RAISE EXCEPTION 'Esta conversación ya tiene una consulta activa' USING ERRCODE = 'P0042';
    END IF;

    -- auth.consultas_servicio requiere id_orden NOT NULL
    -- Si no hay orden, no se puede escalar como consulta formal
    IF v_conv.id_orden IS NULL THEN
        RAISE EXCEPTION 'El escalamiento requiere que la conversación esté vinculada a una orden'
            USING ERRCODE = 'P0043';
    END IF;

    -- Crear consulta de servicio
    INSERT INTO auth.consultas_servicio
        (id_orden, id_comprador, id_vendedor, tipo, estado, asunto, detalle, id_conversacion, prioridad)
    VALUES (
        v_conv.id_orden,
        v_conv.id_comprador,
        v_conv.id_vendedor,
        p_tipo_consulta,
        'abierta',
        COALESCE(v_conv.asunto, 'Escalamiento desde mensajería'),
        jsonb_build_object('motivo', p_motivo, 'conv_id', p_conversacion_id),
        p_conversacion_id,
        'alta'
    )
    RETURNING id INTO v_consulta_id;

    -- Registrar escalamiento
    INSERT INTO auth.consultas_escaladas
        (id_conversacion, consulta_servicio_id, escalado_by, motivo_escalamiento)
    VALUES (p_conversacion_id, v_consulta_id, v_actor, p_motivo)
    RETURNING id INTO v_escalada_id;

    -- Cambiar tipo de conversación a 'soporte'
    UPDATE auth.conversaciones
    SET tipo               = 'soporte',
        metadata           = metadata || jsonb_build_object('escalada', true, 'consulta_id', v_consulta_id),
        fecha_modificacion = now()
    WHERE id = p_conversacion_id;

    -- Mensaje de sistema en la conversación
    INSERT INTO auth.mensajes
        (id_conversacion, emisor_id, cuerpo, tipo_contenido)
    VALUES (
        p_conversacion_id,
        v_actor,
        'Esta conversación fue escalada a soporte formal. Un agente la revisará pronto.',
        'sistema'
    );

    RETURN jsonb_build_object(
        'ok',             true,
        'consulta_id',    v_consulta_id,
        'escalada_id',    v_escalada_id
    );
END;
$$;


--
-- Name: fn_evaluar_alertas_ventas(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_evaluar_alertas_ventas() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $_$
DECLARE
    v_alerta  record;
    v_actual  numeric;
    v_previo  numeric;
    v_variacion numeric;
BEGIN
    FOR v_alerta IN
        SELECT * FROM auth.alertas_ventas WHERE activa = true
    LOOP
        -- Ingresos en ventana actual
        SELECT COALESCE(SUM(ingresos_netos), 0) INTO v_actual
        FROM auth.mv_ventas_vendedor
        WHERE id_vendedor = v_alerta.id_vendedor
          AND fecha_venta BETWEEN
              CURRENT_DATE - v_alerta.ventana_dias AND CURRENT_DATE - 1;

        -- Ingresos en ventana anterior del mismo largo
        SELECT COALESCE(SUM(ingresos_netos), 0) INTO v_previo
        FROM auth.mv_ventas_vendedor
        WHERE id_vendedor = v_alerta.id_vendedor
          AND fecha_venta BETWEEN
              CURRENT_DATE - (v_alerta.ventana_dias * 2) AND
              CURRENT_DATE - v_alerta.ventana_dias - 1;

        -- Calcular variación
        IF v_previo > 0 THEN
            v_variacion := ((v_actual - v_previo) / v_previo * 100)::numeric;
        ELSE
            v_variacion := 0;
        END IF;

        -- Disparar alerta si caída supera umbral y no alertamos en las últimas 24h
        IF v_variacion <= v_alerta.umbral_pct
           AND (v_alerta.ultima_alerta_at IS NULL
                OR v_alerta.ultima_alerta_at < now() - interval '24 hours')
        THEN
            INSERT INTO auth.notificaciones
                (id_usuario, tipo, cuerpo, metadata)
            VALUES (
                v_alerta.id_vendedor,
                'alerta_ventas',
                format('⚠️ Tus ventas cayeron %.1f%% en los últimos %s días (actual: $%s vs previo: $%s)',
                       ABS(v_variacion), v_alerta.ventana_dias,
                       ROUND(v_actual, 0), ROUND(v_previo, 0)),
                jsonb_build_object(
                    'variacion_pct',   ROUND(v_variacion, 2),
                    'ingresos_actual', ROUND(v_actual, 2),
                    'ingresos_previo', ROUND(v_previo, 2),
                    'ventana_dias',    v_alerta.ventana_dias,
                    'cu_origen',       'CU-V-008'
                )
            );

            UPDATE auth.alertas_ventas
            SET ultima_alerta_at   = now(),
                ultima_evaluacion  = now()
            WHERE id_vendedor = v_alerta.id_vendedor;
        ELSE
            UPDATE auth.alertas_ventas
            SET ultima_evaluacion = now()
            WHERE id_vendedor = v_alerta.id_vendedor;
        END IF;
    END LOOP;
END;
$_$;


--
-- Name: fn_evaluar_recompensa_contextual(uuid, text, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_evaluar_recompensa_contextual(p_id_vendedor uuid, p_tipo_contexto text, p_contexto_data jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_limites    jsonb;
    v_regla      record;
    v_ya_aplicado int;
BEGIN
    -- Solo Gold+
    v_limites := auth.fn_get_wallet_limits(p_id_vendedor);

    -- Obtener regla aplicable
    SELECT * INTO v_regla
    FROM auth.reglas_recompensa_contexto
    WHERE tipo_contexto = p_tipo_contexto AND activo = true
    ORDER BY recompensa_puntos DESC
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('skipped', true, 'motivo', 'sin_regla_activa');
    END IF;

    -- Verificar máximo por día
    SELECT COUNT(*) INTO v_ya_aplicado
    FROM auth.movimientos_puntos
    WHERE id_usuario = p_id_vendedor
      AND tipo_movimiento = 'recompensa_contextual'
      AND (detalle ->> 'regla_id') = v_regla.id::text
      AND fecha_creacion >= date_trunc('day', now());

    IF v_ya_aplicado >= v_regla.max_por_dia THEN
        RETURN jsonb_build_object(
            'skipped', true, 'motivo', 'maximo_dia_alcanzado',
            'max_por_dia', v_regla.max_por_dia
        );
    END IF;

    -- Acreditar recompensa
    PERFORM auth.fn_acreditar_puntos_venta(
        p_id_vendedor,
        v_regla.recompensa_puntos,
        'recompensa_contextual_' || v_regla.id::text,
        12
    );

    RETURN jsonb_build_object(
        'aplicado',      true,
        'regla_id',      v_regla.id,
        'regla_nombre',  v_regla.nombre,
        'puntos',        v_regla.recompensa_puntos
    );
END;
$$;


--
-- Name: fn_evaluar_triggers_campanas(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_evaluar_triggers_campanas(p_id_comprador uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_res jsonb;
BEGIN
  SELECT jsonb_build_object(
    'reglas_activas', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id', r.id, 'nombre', r.nombre, 'tipo_contexto', r.tipo_contexto,
      'plan_minimo', r.plan_minimo, 'recompensa_puntos', r.recompensa_puntos))
      FROM auth.reglas_recompensa_contexto r WHERE r.activo = true), '[]'::jsonb),
    'campanas_activas', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id', c.id, 'nombre', c.nombre, 'tipo', c.tipo, 'estado', c.estado))
      FROM auth.campanas c WHERE c.estado IN ('activa','activo','publicada')), '[]'::jsonb)
  ) INTO v_res;
  RETURN v_res;
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: fn_expire_memberships(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_expire_memberships() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_count integer := 0;
  r record;
  v_downgrade text;
BEGIN
  -- RN-005: Procesar todas las membresías activas vencidas
  FOR r IN
    SELECT uma.*, mpc.admin_parameters
    FROM auth.user_membership_assignments uma
    JOIN auth.membership_policy_catalog mpc ON mpc.tier = uma.tier
    WHERE uma.estado = 'active'
      AND uma.fecha_expiracion IS NOT NULL
      AND uma.fecha_expiracion <= now()
  LOOP
    UPDATE auth.user_membership_assignments
    SET estado = 'expired', fecha_actualizacion = now()
    WHERE id = r.id;

    -- RN-006: Downgrade automático según admin_parameters del plan
    v_downgrade := COALESCE(r.admin_parameters->>'auto_downgrade_to', 'bronze');
    PERFORM auth.fn_assign_membership(r.id_usuario, v_downgrade, NULL, NULL, 'auto_expire_downgrade');

    INSERT INTO auth.user_lifecycle_audit(
      id_usuario, tipo_evento, before_state, after_state, reason, source
    )
    VALUES (r.id_usuario, 'MEMBERSHIP_EXPIRED', to_jsonb(r),
            jsonb_build_object('downgrade_to', v_downgrade), 'membership expired', 'system');

    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('expired', v_count);
END;
$$;


--
-- Name: fn_galeria_fotos_geotag(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_galeria_fotos_geotag() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'auth', 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_id_vendedor uuid;
  v_punto       geography;
  v_lat         double precision;
  v_lon         double precision;
BEGIN
  -- Obtener id_vendedor del producto
  SELECT p.id_vendedor INTO v_id_vendedor
  FROM auth.productos p
  WHERE p.id = NEW.id_producto
    AND p.activo = true
    AND p.fecha_eliminacion IS NULL;

  IF v_id_vendedor IS NULL THEN
    RAISE EXCEPTION 'producto_not_found_or_inactive_for_geotag';
  END IF;

  -- Obtener ubicación activa del vendedor
  SELECT u.punto, u.latitud, u.longitud INTO v_punto, v_lat, v_lon
  FROM auth.ubicaciones u
  WHERE u.id_usuario = v_id_vendedor
    AND u.estado = 'activo'
  ORDER BY u.fecha_actualizacion DESC NULLS LAST
  LIMIT 1;

  -- Inyectar geo_tag en metadata (no sobreescribe campos existentes)
  IF v_punto IS NOT NULL THEN
    NEW.metadata := coalesce(NEW.metadata, '{}') ||
      jsonb_build_object(
        'geo_tag', jsonb_build_object(
          'type',        'Point',
          'coordinates', jsonb_build_array(v_lon, v_lat),
          'srid',        4326
        ),
        'geo_tag_at',   now()
      );
  END IF;

  RETURN NEW;
END; $$;


--
-- Name: fn_generate_unique_seller_slug(text, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_generate_unique_seller_slug(p_base_text text, p_exclude_id_vendedor uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_base      text;
  v_candidate text;
  v_n         integer := 0;
BEGIN
  v_base := auth.fn_slugify_text(p_base_text);

  LOOP
    v_candidate := CASE WHEN v_n = 0 THEN v_base ELSE v_base || '-' || v_n::text END;

    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM auth.perfiles_publicos_vendedor pp
      WHERE pp.slug_publico = v_candidate
        AND (p_exclude_id_vendedor IS NULL OR pp.id_vendedor <> p_exclude_id_vendedor)
    );

    v_n := v_n + 1;
    IF v_n > 9999 THEN
      RAISE EXCEPTION 'No fue posible generar slug único para %', p_base_text;
    END IF;
  END LOOP;

  RETURN v_candidate;
END;
$$;


--
-- Name: fn_get_feature_flag(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_get_feature_flag(p_id_vendedor uuid, p_flag text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_valor boolean;
BEGIN
    SELECT COALESCE(
        NULLIF((mv.override_flags ->> p_flag), '')::boolean,
        NULLIF((pm.feature_flags ->> p_flag), '')::boolean,
        false
    ) INTO v_valor
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.id_vendedor = p_id_vendedor
      AND mv.estado IN ('activo', 'grace_period')
      AND mv.fecha_eliminacion IS NULL
    ORDER BY mv.fecha_creacion DESC
    LIMIT 1;

    RETURN COALESCE(v_valor, false);
END;
$$;


--
-- Name: fn_get_inventory_limits(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_get_inventory_limits(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_flags jsonb;
BEGIN
    SELECT pm.feature_flags INTO v_flags
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.id_vendedor = p_id_vendedor
      AND mv.estado IN ('activa','trial');

    -- Fallback a bronze si no hay membresía activa
    IF v_flags IS NULL THEN
        SELECT pm.feature_flags INTO v_flags
        FROM auth.planes_membresia pm
        WHERE pm.codigo = 'bronze' AND pm.activo = true
        LIMIT 1;
    END IF;

    -- Defaults mínimos si planes no tienen los flags de inventario aún
    RETURN COALESCE(v_flags, '{}'::jsonb) || jsonb_build_object(
        'max_inventory_locations', COALESCE((v_flags ->> 'max_inventory_locations')::int, 1),
        'max_daily_adjustments', COALESCE((v_flags ->> 'max_daily_adjustments')::int, 20),
        'inventory_transfers', COALESCE((v_flags ->> 'inventory_transfers')::boolean, false),
        'inventory_abc_analysis', COALESCE((v_flags ->> 'inventory_abc_analysis')::boolean, false),
        'inventory_forecasting', COALESCE((v_flags ->> 'inventory_forecasting')::boolean, false)
    );
END;
$$;


--
-- Name: fn_get_location_limits(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_get_location_limits(p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_user_id uuid := COALESCE(
    p_id_vendedor,
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid
  );
  v_flags jsonb;
  v_result jsonb;
BEGIN
  SELECT pm.feature_flags INTO v_flags
  FROM auth.membresias_vendedor mv
  JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
  WHERE mv.id_vendedor = v_user_id
    AND mv.estado IN ('activa','trial')
  ORDER BY mv.ciclo_inicio DESC
  LIMIT 1;

  IF v_flags IS NULL THEN
    -- Degradación: plan Bronze por defecto si no hay membresía encontrada
    v_flags := jsonb_build_object(
      'max_ubicaciones', 3,
      'zona_cobertura_custom', false,
      'analytics_ubicacion', false,
      'horarios_inteligentes', false,
      'clusters_geo', false
    );
  END IF;

  -- Contar ubicaciones activas actuales
  SELECT jsonb_build_object(
    'max_ubicaciones',       (v_flags->>'max_ubicaciones')::integer,
    'zona_cobertura_custom', (v_flags->>'zona_cobertura_custom')::boolean,
    'analytics_ubicacion',   (v_flags->>'analytics_ubicacion')::boolean,
    'horarios_inteligentes', (v_flags->>'horarios_inteligentes')::boolean,
    'clusters_geo',          (v_flags->>'clusters_geo')::boolean,
    'activas_actuales',      COUNT(*)
  ) INTO v_result
  FROM auth.ubicaciones
  WHERE id_usuario = v_user_id
    AND estado = 'activo'
    AND fecha_eliminacion IS NULL;

  RETURN v_result;
END;
$$;


--
-- Name: fn_get_mensaje_traducido(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_get_mensaje_traducido(p_mensaje_id uuid, p_locale_destino text DEFAULT 'en'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor uuid := auth.uid();
    v_trad  auth.mensajes_traducciones%ROWTYPE;
    v_queue auth.traduccion_queue%ROWTYPE;
BEGIN
    -- Verificar participación (simplificado)
    SELECT t.* INTO v_trad
    FROM auth.mensajes_traducciones t
    WHERE t.mensaje_id = p_mensaje_id AND t.locale_destino = p_locale_destino;

    IF FOUND THEN
        RETURN jsonb_build_object(
            'ok',               true,
            'estado',           'completado',
            'texto_traducido',  v_trad.texto_traducido,
            'locale_origen',    v_trad.locale_origen,
            'motor',            v_trad.motor_usado
        );
    END IF;

    SELECT q.* INTO v_queue
    FROM auth.traduccion_queue q
    WHERE q.mensaje_id = p_mensaje_id AND q.locale_destino = p_locale_destino;

    RETURN jsonb_build_object(
        'ok',     true,
        'estado', COALESCE(v_queue.estado, 'no_solicitado')
    );
END;
$$;


--
-- Name: fn_get_mensajes_conversacion(uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_get_mensajes_conversacion(p_conversacion_id uuid, p_limit integer DEFAULT 50, p_antes_de timestamp with time zone DEFAULT now()) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_actor uuid := auth.uid();
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM auth.conversaciones
        WHERE id = p_conversacion_id
          AND (id_comprador = v_actor OR id_vendedor = v_actor)
    ) THEN
        RAISE EXCEPTION 'No autorizado' USING ERRCODE = 'P0035';
    END IF;

    RETURN QUERY
    SELECT jsonb_build_object(
        'mensaje_id',       m.id,
        'emisor_id',        m.emisor_id,
        'emisor_nombre',    COALESCE(up.nombre || ' ' || up.apellido, 'N/D'),
        'emisor_avatar',    up.url_avatar,
        'es_propio',        m.emisor_id = v_actor,
        'es_chatbot',       m.tipo_contenido = 'chatbot',
        'cuerpo',           CASE WHEN m.eliminado THEN '[Mensaje eliminado]' ELSE m.cuerpo END,
        'tipo_contenido',   m.tipo_contenido,
        'leido',            m.leido,
        'editado',          m.editado,
        'eliminado',        m.eliminado,
        'adjuntos',         COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id',            a.id,
                'tipo',          a.tipo_adjunto,
                'nombre',        a.nombre_original,
                'mime',          a.mime_type,
                'tamano_bytes',  a.tamano_bytes
            ))
            FROM auth.mensajes_adjuntos a
            WHERE a.mensaje_id = m.id AND a.activo = true
        ), '[]'::jsonb),
        'traduccion_lista', (m.metadata->>'traduccion_lista')::boolean,
        'fecha',            m.fecha_creacion
    )
    FROM auth.mensajes m
    LEFT JOIN auth.user_profiles up ON up.id_usuario = m.emisor_id
    WHERE m.id_conversacion = p_conversacion_id
      AND m.fecha_creacion < p_antes_de
    ORDER BY m.fecha_creacion DESC
    LIMIT p_limit;
END;
$$;


--
-- Name: fn_get_precio_efectivo(uuid, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_get_precio_efectivo(p_producto_id uuid, p_id_comprador uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
  with base as (
    select precio, descuento_porcentaje from auth.productos where id = p_producto_id and activo = true and fecha_eliminacion is null
  ),
  regla as (
    select descuento_pct, precio_fijo
    from auth.producto_precio_reglas r
    join base on true
    where r.id_producto = p_producto_id and r.activo = true
      and (r.vigencia_desde is null or r.vigencia_desde <= now())
      and (r.vigencia_hasta is null or r.vigencia_hasta >= now())
    order by r.prioridad desc limit 1
  )
  select coalesce(
    (select precio_fijo from regla where precio_fijo is not null),
    (select b.precio * (1 - coalesce(r.descuento_pct, b.descuento_porcentaje) / 100.0) from base b, regla r),
    (select precio * (1 - coalesce(descuento_porcentaje, 0) / 100.0) from base)
  );

$$;


--
-- Name: fn_get_publication_limits(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_get_publication_limits(p_id_vendedor uuid) RETURNS TABLE(membresia_codigo text, max_productos_activos integer, max_fotos_por_producto integer)
    LANGUAGE sql STABLE
    AS $$
with resolved as (
  select pm.codigo,
         (pm.feature_flags ->> 'max_productos_activos')::integer    as max_productos,
         (pm.feature_flags ->> 'max_fotos_por_producto')::integer   as max_fotos
  from auth.membresias_vendedor mv
  join auth.planes_membresia pm on pm.id = mv.id_plan and pm.activo = true
  where mv.id_vendedor = p_id_vendedor
    and mv.estado = 'activa'
  limit 1
),
fallback_bronze as (
  select pm.codigo,
         (pm.feature_flags ->> 'max_productos_activos')::integer,
         (pm.feature_flags ->> 'max_fotos_por_producto')::integer
  from auth.planes_membresia pm
  where pm.codigo = 'bronze' and pm.activo = true
  limit 1
)
select * from resolved
union all
select * from fallback_bronze where not exists (select 1 from resolved);

$$;


--
-- Name: fn_get_seller_punto_activo(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_get_seller_punto_activo(p_id_vendedor uuid) RETURNS public.geography
    LANGUAGE sql STABLE
    AS $$
  SELECT u.punto
  FROM auth.ubicaciones u
  WHERE u.id_usuario = p_id_vendedor
    AND u.estado = 'activo'
  ORDER BY u.fecha_actualizacion DESC NULLS LAST, u.fecha_creacion DESC
  LIMIT 1;
$$;


--
-- Name: fn_get_wallet_limits(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_get_wallet_limits(p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_uid   uuid;
    v_flags jsonb;
BEGIN
    v_uid := COALESCE(p_id_vendedor, auth.fn_current_user_id());

    SELECT pm.feature_flags INTO v_flags
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.id_vendedor = v_uid
      AND mv.estado IN ('activa', 'trial')
    ORDER BY mv.ciclo_inicio DESC
    LIMIT 1;

    -- Bronze por defecto si no hay membresía
    IF v_flags IS NULL THEN
        v_flags := '{"wallet_max_transferencia_diaria": 1000, "wallet_conversion_mxn": false,
                     "wallet_cashback": false, "wallet_transferencias_programadas": false,
                     "wallet_analytics": false}'::jsonb;
    END IF;

    RETURN jsonb_build_object(
        'max_transferencia_diaria',    COALESCE((v_flags ->> 'wallet_max_transferencia_diaria')::numeric, 1000),
        'conversion_disponible',       COALESCE((v_flags ->> 'wallet_conversion_mxn')::boolean, false),
        'cashback_automatico',         COALESCE((v_flags ->> 'wallet_cashback')::boolean, false),
        'transferencias_programadas',  COALESCE((v_flags ->> 'wallet_transferencias_programadas')::boolean, false),
        'analytics_billetera',         COALESCE((v_flags ->> 'wallet_analytics')::boolean, false),
        'transferencia_p2p',           true  -- todos los planes
    );
END;
$$;


--
-- Name: fn_graph_buyers_risk(jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_graph_buyers_risk(p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ag_catalog', 'smtp_posix_graph', 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_result  JSONB;
BEGIN
    -- ── Autorización ────────────────────────────────────────────────────────
    IF NOT auth.fn_has_graph_access() THEN
        RAISE EXCEPTION 'Acceso denegado al grafo: se requiere db_admin o acceso delegado'
            USING ERRCODE = '42501';
    END IF;

    LOAD 'age';
    SET LOCAL search_path = ag_catalog, smtp_posix_graph, auth, public, pg_catalog;

    WITH buyer_metrics AS (
        SELECT
            u.id                                                AS id_usuario,
            u.username,
            u.email,
            u.is_verified,
            COUNT(DISTINCT i.id)                               AS intercambios_total,
            COUNT(DISTINCT i.id) FILTER (WHERE i.estado = 'completado') AS intercambios_completados,
            COUNT(DISTINCT i.id) FILTER (WHERE i.estado = 'cancelado')  AS intercambios_cancelados,
            COALESCE(urs.score, 0)                             AS riesgo_score,
            COALESCE(urs.nivel_riesgo, 'sin_datos')            AS nivel_riesgo,
            COALESCE(urs.reportes_recibidos, 0)                AS reportes_recibidos,
            COALESCE(urs.ratings_negativos, 0)                 AS ratings_negativos,
            (SELECT COUNT(*)::INT FROM auth.login_attempts la
             WHERE la.email = u.email AND la.exitoso = FALSE
               AND la.fecha > now() - interval '24 hours')     AS intentos_fallidos_24h
        FROM auth.users u
        LEFT JOIN auth.intercambios i         ON (i.solicitante_id = u.id OR i.receptor_id = u.id)
        LEFT JOIN public.user_risk_scores urs ON urs.id_usuario = u.id
        WHERE u.role = 'buyer'
          AND u.is_verified = TRUE
        GROUP BY u.id, u.username, u.email, u.is_verified,
                 urs.score, urs.nivel_riesgo, urs.reportes_recibidos, urs.ratings_negativos
    ),
    -- FIX: usa agtype_access_operator en vez de properties->>'user_uuid'
    graph_connectivity AS (
        SELECT
            (trim(both '"' from ag_catalog.agtype_access_operator(
                uv.properties, '"user_uuid"'::agtype)::text))::uuid AS id_usuario,
            COUNT(e.id)::INT AS vendedores_conectados_grafo
        FROM smtp_posix_graph."User" uv
        LEFT JOIN smtp_posix_graph."INTERCAMBIA_CON" e ON e.end_id = uv.id
        GROUP BY 1
    ),
    graph_risk_cluster AS (
        SELECT DISTINCT
            (trim(both '"' from ag_catalog.agtype_access_operator(
                uv.properties, '"user_uuid"'::agtype)::text))::uuid AS id_usuario
        FROM smtp_posix_graph."User" uv
        JOIN smtp_posix_graph."TIENE_RIESGO_ALTO" re
            ON re.start_id = uv.id OR re.end_id = uv.id
    )
    SELECT jsonb_build_object(
        'compradores',
        jsonb_agg(
            jsonb_build_object(
                'id_usuario',               bm.id_usuario,
                'username',                 bm.username,
                'email',                    bm.email,
                'intercambios_total',       bm.intercambios_total,
                'intercambios_completados', bm.intercambios_completados,
                'intercambios_cancelados',  bm.intercambios_cancelados,
                'riesgo_score',             bm.riesgo_score,
                'nivel_riesgo',             bm.nivel_riesgo,
                'reportes_recibidos',       bm.reportes_recibidos,
                'ratings_negativos',        bm.ratings_negativos,
                'intentos_fallidos_24h',    bm.intentos_fallidos_24h,
                'vendedores_conectados_grafo', COALESCE(gc.vendedores_conectados_grafo, 0),
                'en_cluster_riesgo',        (grc.id_usuario IS NOT NULL)
            ) ORDER BY bm.riesgo_score DESC NULLS LAST
        ),
        'total',       COUNT(*),
        'generado_en', now()
    ) INTO v_result
    FROM buyer_metrics bm
    LEFT JOIN graph_connectivity gc  ON gc.id_usuario  = bm.id_usuario
    LEFT JOIN graph_risk_cluster grc ON grc.id_usuario = bm.id_usuario;

    RETURN COALESCE(v_result, '{"compradores":[], "total":0}'::jsonb);
END;
$$;


--
-- Name: fn_graph_grant_access(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_graph_grant_access(p_grantee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_role      TEXT;
    v_caller_id uuid;
    v_grantee   RECORD;
BEGIN
    v_role := COALESCE(current_setting('request.jwt.claims', true)::JSONB ->> 'role', '');
    IF v_role <> 'db_admin' THEN
        RAISE EXCEPTION 'Solo db_admin puede otorgar acceso al grafo' USING ERRCODE = '42501';
    END IF;

    v_caller_id := (current_setting('request.jwt.claims', true)::JSONB ->> 'user_id')::uuid;

    -- Verificar que el grantee existe
    SELECT id, username, email, role INTO v_grantee
    FROM auth.users WHERE id = p_grantee_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Usuario grantee no encontrado: %', p_grantee_id USING ERRCODE = 'P0002';
    END IF;

    INSERT INTO auth.graph_access_grants (grantee_id, granted_by)
    VALUES (p_grantee_id, v_caller_id)
    ON CONFLICT (grantee_id) DO UPDATE
        SET granted_by = EXCLUDED.granted_by,
            granted_at = now();

    RETURN jsonb_build_object(
        'status',     'granted',
        'grantee_id', p_grantee_id,
        'username',   v_grantee.username,
        'role',       v_grantee.role,
        'granted_by', v_caller_id,
        'granted_at', now()
    );
END;
$$;


--
-- Name: fn_graph_revoke_access(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_graph_revoke_access(p_grantee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_role    TEXT;
    v_deleted INT := 0;
BEGIN
    v_role := COALESCE(current_setting('request.jwt.claims', true)::JSONB ->> 'role', '');
    IF v_role <> 'db_admin' THEN
        RAISE EXCEPTION 'Solo db_admin puede revocar acceso al grafo' USING ERRCODE = '42501';
    END IF;
    DELETE FROM auth.graph_access_grants WHERE grantee_id = p_grantee_id;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    RETURN jsonb_build_object(
        'status',     CASE WHEN v_deleted > 0 THEN 'revoked' ELSE 'not_found' END,
        'grantee_id', p_grantee_id
    );
END;
$$;


--
-- Name: fn_graph_sellers_risk(jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_graph_sellers_risk(p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ag_catalog', 'smtp_posix_graph', 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_result  JSONB;
BEGIN
    -- ── Autorización ────────────────────────────────────────────────────────
    IF NOT auth.fn_has_graph_access() THEN
        RAISE EXCEPTION 'Acceso denegado al grafo: se requiere db_admin o acceso delegado'
            USING ERRCODE = '42501';
    END IF;

    LOAD 'age';
    SET LOCAL search_path = ag_catalog, smtp_posix_graph, auth, public, pg_catalog;

    WITH seller_metrics AS (
        SELECT
            u.id                                                AS id_usuario,
            u.username,
            u.email,
            u.is_verified,
            COUNT(DISTINCT p.id)                               AS total_productos,
            COUNT(DISTINCT p.id) FILTER (WHERE p.activo)       AS productos_activos,
            COUNT(DISTINCT i.id)                               AS intercambios_total,
            COUNT(DISTINCT i.id) FILTER (WHERE i.estado = 'completado') AS intercambios_completados,
            ROUND(COALESCE(AVG(r.calificacion), 0), 2)         AS calificacion_promedio,
            COALESCE(urs.score, 0)                             AS riesgo_score,
            COALESCE(urs.nivel_riesgo, 'sin_datos')            AS nivel_riesgo,
            COALESCE(urs.reportes_recibidos, 0)                AS reportes_recibidos,
            COALESCE(urs.intercambios_cancelados, 0)           AS intercambios_cancelados
        FROM auth.users u
        LEFT JOIN auth.productos p            ON p.id_vendedor = u.id
        LEFT JOIN auth.intercambios i         ON (i.solicitante_id = u.id OR i.receptor_id = u.id)
        LEFT JOIN auth.resenas r              ON r.id_vendedor = u.id
        LEFT JOIN public.user_risk_scores urs ON urs.id_usuario = u.id
        WHERE u.role = 'seller'
          AND u.is_verified = TRUE
        GROUP BY u.id, u.username, u.email, u.is_verified,
                 urs.score, urs.nivel_riesgo, urs.reportes_recibidos, urs.intercambios_cancelados
    ),
    -- FIX: usa agtype_access_operator en vez de properties->>'user_uuid'
    graph_connectivity AS (
        SELECT
            (trim(both '"' from ag_catalog.agtype_access_operator(
                uv.properties, '"user_uuid"'::agtype)::text))::uuid AS id_usuario,
            COUNT(e.id)::INT AS compradores_conectados_grafo
        FROM smtp_posix_graph."User" uv
        LEFT JOIN smtp_posix_graph."INTERCAMBIA_CON" e ON e.start_id = uv.id
        GROUP BY 1
    ),
    graph_risk_cluster AS (
        SELECT DISTINCT
            (trim(both '"' from ag_catalog.agtype_access_operator(
                uv.properties, '"user_uuid"'::agtype)::text))::uuid AS id_usuario
        FROM smtp_posix_graph."User" uv
        JOIN smtp_posix_graph."TIENE_RIESGO_ALTO" re
            ON re.start_id = uv.id OR re.end_id = uv.id
    )
    SELECT jsonb_build_object(
        'vendedores',
        jsonb_agg(
            jsonb_build_object(
                'id_usuario',               sm.id_usuario,
                'username',                 sm.username,
                'email',                    sm.email,
                'total_productos',          sm.total_productos,
                'productos_activos',        sm.productos_activos,
                'intercambios_total',       sm.intercambios_total,
                'intercambios_completados', sm.intercambios_completados,
                'calificacion_promedio',    sm.calificacion_promedio,
                'riesgo_score',             sm.riesgo_score,
                'nivel_riesgo',             sm.nivel_riesgo,
                'reportes_recibidos',       sm.reportes_recibidos,
                'intercambios_cancelados',  sm.intercambios_cancelados,
                'compradores_conectados_grafo', COALESCE(gc.compradores_conectados_grafo, 0),
                'en_cluster_riesgo',        (grc.id_usuario IS NOT NULL)
            ) ORDER BY sm.riesgo_score DESC NULLS LAST
        ),
        'total',       COUNT(*),
        'generado_en', now()
    ) INTO v_result
    FROM seller_metrics sm
    LEFT JOIN graph_connectivity gc  ON gc.id_usuario  = sm.id_usuario
    LEFT JOIN graph_risk_cluster grc ON grc.id_usuario = sm.id_usuario;

    RETURN COALESCE(v_result, '{"vendedores":[], "total":0}'::jsonb);
END;
$$;


--
-- Name: fn_graph_sync_cu064(jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_graph_sync_cu064(p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ag_catalog', 'smtp_posix_graph', 'auth', 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_productos    INT := 0;
    v_intercambios INT := 0;
    v_edges_op     INT := 0;
    v_edges_ic     INT := 0;
    v_risk_edges   INT := 0;
    r              RECORD;
BEGIN
    -- ── Autorización ────────────────────────────────────────────────────────
    IF NOT auth.fn_has_graph_access() THEN
        RAISE EXCEPTION 'Acceso denegado al grafo: se requiere db_admin o acceso delegado'
            USING ERRCODE = '42501';
    END IF;

    LOAD 'age';
    SET LOCAL search_path = ag_catalog, smtp_posix_graph, auth, public, pg_catalog;

    -- ── Sync Producto vertices + OFRECE_PRODUCTO edges ───────────────────────
    FOR r IN SELECT id, nombre, precio, activo, id_vendedor FROM auth.productos LOOP
        BEGIN
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    MERGE (p:Producto {id: %L})
                    SET p.nombre       = %L,
                        p.precio       = %s,
                        p.activo       = %s,
                        p.id_vendedor  = %L,
                        p.updated_at  = %L
                    RETURN p.id
                $c$) AS (r ag_catalog.agtype)$q$,
                r.id::text,
                COALESCE(r.nombre, ''),
                COALESCE(r.precio, 0)::text,
                r.activo::text,
                r.id_vendedor::text,
                now()::text
            );
            v_productos := v_productos + 1;

            -- OFRECE_PRODUCTO edge
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    MATCH (u:User {user_uuid: %L}), (p:Producto {id: %L})
                    MERGE (u)-[:OFRECE_PRODUCTO {activo: %s}]->(p)
                    RETURN 1
                $c$) AS (r ag_catalog.agtype)$q$,
                r.id_vendedor::text,
                r.id::text,
                r.activo::text
            );
            v_edges_op := v_edges_op + 1;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'fn_graph_sync_cu064 producto %: %', r.id, SQLERRM;
        END;
    END LOOP;

    -- ── Sync Intercambio vertices + INTERCAMBIA_CON edges ───────────────────
    FOR r IN SELECT id, solicitante_id, receptor_id, estado FROM auth.intercambios LOOP
        BEGIN
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    MERGE (i:Intercambio {id: %L})
                    SET i.estado      = %L,
                        i.solicitante = %L,
                        i.receptor    = %L,
                        i.updated_at  = %L
                    RETURN i.id
                $c$) AS (r ag_catalog.agtype)$q$,
                r.id::text,
                COALESCE(r.estado, 'pendiente'),
                r.solicitante_id::text,
                r.receptor_id::text,
                now()::text
            );
            v_intercambios := v_intercambios + 1;

            -- INTERCAMBIA_CON edge
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    MATCH (u1:User {user_uuid: %L}), (u2:User {user_uuid: %L})
                    MERGE (u1)-[e:INTERCAMBIA_CON {intercambio_id: %L}]->(u2)
                    SET e.estado = %L, e.updated_at = %L
                    RETURN 1
                $c$) AS (r ag_catalog.agtype)$q$,
                r.solicitante_id::text,
                r.receptor_id::text,
                r.id::text,
                COALESCE(r.estado, 'pendiente'),
                now()::text
            );
            v_edges_ic := v_edges_ic + 1;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'fn_graph_sync_cu064 intercambio %: %', r.id, SQLERRM;
        END;
    END LOOP;

    -- ── TIENE_RIESGO_ALTO edges ──────────────────────────────────────────────
    FOR r IN
        SELECT DISTINCT u1.id AS id1, u2.id AS id2
        FROM public.user_risk_scores urs1
        JOIN auth.users u1 ON u1.id = urs1.id_usuario
        JOIN auth.intercambios i ON (i.solicitante_id = u1.id OR i.receptor_id = u1.id)
        JOIN auth.users u2 ON u2.id = CASE
            WHEN i.solicitante_id = u1.id THEN i.receptor_id
            ELSE i.solicitante_id
        END
        JOIN public.user_risk_scores urs2 ON urs2.id_usuario = u2.id
        WHERE urs1.nivel_riesgo IN ('alto', 'critico')
          AND urs2.nivel_riesgo IN ('alto', 'critico')
          AND u1.id <> u2.id
    LOOP
        BEGIN
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    MATCH (u1:User {user_uuid: %L}), (u2:User {user_uuid: %L})
                    MERGE (u1)-[:TIENE_RIESGO_ALTO]->(u2)
                    RETURN 1
                $c$) AS (r ag_catalog.agtype)$q$,
                r.id1::text,
                r.id2::text
            );
            v_risk_edges := v_risk_edges + 1;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'fn_graph_sync_cu064 risk_edge %-%: %', r.id1, r.id2, SQLERRM;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'status',            'ok',
        'productos_sync',    v_productos,
        'intercambios_sync', v_intercambios,
        'edges_ofrece',      v_edges_op,
        'edges_intercambia', v_edges_ic,
        'edges_riesgo_alto', v_risk_edges,
        'ejecutado_en',      now()
    );
END;
$_$;


--
-- Name: fn_has_graph_access(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_has_graph_access() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_claims  TEXT;
    v_claims_j JSONB;
    v_role     TEXT;
    v_user_id  uuid;
BEGIN
    v_claims := current_setting('request.jwt.claims', true);
    IF v_claims IS NULL OR v_claims = '' THEN
        RETURN FALSE;
    END IF;

    v_claims_j := v_claims::JSONB;
    v_role     := COALESCE(v_claims_j ->> 'role', '');
    v_user_id  := (v_claims_j ->> 'user_id')::uuid;

    -- db_admin siempre tiene acceso
    IF v_role = 'db_admin' THEN
        RETURN TRUE;
    END IF;

    -- Otros roles: verificar grant explícito
    IF v_user_id IS NULL THEN
        RETURN FALSE;
    END IF;

    RETURN EXISTS (
        SELECT 1 FROM auth.graph_access_grants
        WHERE grantee_id = v_user_id
    );
EXCEPTION WHEN OTHERS THEN
    RETURN FALSE;
END;
$$;


--
-- Name: fn_init_nivel_billetera(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_init_nivel_billetera() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    SELECT id INTO NEW.nivel_lealtad_id
    FROM auth.niveles_lealtad
    WHERE codigo = 'BRONZE' AND activo = true
    LIMIT 1;
    RETURN NEW;
END;
$$;


--
-- Name: fn_inventory_alert_check(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_inventory_alert_check(p_producto_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    r record;
    v_tipo text;
    v_sev text;
BEGIN
    SELECT
        ip.id_producto, ip.id_vendedor, ip.stock_disponible, ip.umbral_alerta,
        p.nombre
    INTO r
    FROM auth.inventario_producto ip
    JOIN auth.productos p ON p.id = ip.id_producto
    WHERE ip.id_producto = p_producto_id;

    IF NOT FOUND THEN RETURN; END IF;

    IF r.stock_disponible <= 0 THEN
        v_tipo := 'sin_stock'; v_sev := 'alta';
    ELSIF r.stock_disponible <= r.umbral_alerta THEN
        v_tipo := 'stock_bajo'; v_sev := 'media';
    ELSE
        -- Resolver alertas previas si stock subió
        UPDATE auth.alertas_inventario
        SET resuelta = true, fecha_resolucion = now()
        WHERE id_producto = p_producto_id
          AND tipo_alerta IN ('stock_bajo','sin_stock')
          AND resuelta = false;
        RETURN;
    END IF;

    -- Insertar solo si no hay alerta activa del mismo tipo en las últimas 24h
    INSERT INTO auth.alertas_inventario(
        id_producto, id_vendedor, tipo_alerta, severidad, mensaje, metadata
    )
    SELECT
        r.id_producto, r.id_vendedor, v_tipo, v_sev,
        format('Producto "%s": stock disponible %s (umbral: %s)',
               r.nombre, r.stock_disponible, r.umbral_alerta),
        jsonb_build_object(
            'stock_disponible', r.stock_disponible,
            'umbral_alerta', r.umbral_alerta,
            'producto_nombre', r.nombre
        )
    WHERE NOT EXISTS (
        SELECT 1 FROM auth.alertas_inventario ai
        WHERE ai.id_producto = r.id_producto
          AND ai.tipo_alerta = v_tipo
          AND ai.resuelta = false
          AND ai.fecha_creacion > now() - interval '24 hours'
    );
END;
$$;


