--
-- Name: fn_mail_queue_audit_envio(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_mail_queue_audit_envio() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Audita SOLO cuando el worker marca el correo como entregado.
    IF OLD.estado = 'pendiente' AND NEW.estado = 'enviado' THEN
        INSERT INTO auth.log_envio_correos (id_usuario, email, tipo, estado, detalle)
        VALUES (
            NEW.id_usuario,
            NEW.recipient,
            COALESCE(NEW.tipo, 'notificacion'),
            'enviado',
            'T11 mail-worker: id=' || NEW.id || ' subject=' || left(NEW.subject, 120)
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_mail_queue_audit_envio(); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.fn_mail_queue_audit_envio() IS 'T11-SMTP-BRAIN: audita transiciones pendiente->enviado en auth.log_envio_correos (evidencia de entrega del worker).';


