--
-- Name: fn_marcar_leido(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_marcar_leido(p_conversacion_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor uuid;
    v_conv  auth.conversaciones%ROWTYPE;
BEGIN
    v_actor := coalesce(
        (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')::uuid
    );
    SELECT * INTO v_conv FROM auth.conversaciones WHERE id = p_conversacion_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Conversación no encontrada' USING ERRCODE = 'P0034';
    END IF;

    UPDATE auth.mensajes SET leido = true, leido_at = now()
    WHERE id_conversacion = p_conversacion_id
      AND emisor_id <> v_actor
      AND leido = false;

    UPDATE auth.conversaciones SET
        leido_comprador = CASE WHEN v_actor = id_comprador THEN true ELSE leido_comprador END,
        leido_vendedor  = CASE WHEN v_actor = id_vendedor  THEN true ELSE leido_vendedor END,
        fecha_modificacion = now()
    WHERE id = p_conversacion_id;

    -- CF-1: notify de lectura al emisor
    PERFORM pg_notify(
        'mensajes_kambalache',
        json_build_object(
            'evento',           'mensajes_leidos',
            'conversacion_id',  p_conversacion_id,
            'leido_by',         v_actor
        )::text
    );

    RETURN jsonb_build_object('ok', true, 'conversacion_id', p_conversacion_id);
END;
$$;


--
-- Name: fn_marcar_webhook_procesado(uuid, boolean, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_marcar_webhook_procesado(p_id uuid, p_ok boolean, p_error_msg text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    UPDATE auth.webhook_queue
    SET estado        = CASE WHEN p_ok THEN 'procesado' ELSE 'error' END,
        error_detalle = p_error_msg,
        procesado_at  = now(),
        intentos      = intentos + 1,
        proximo_intento = CASE
            WHEN NOT p_ok AND intentos + 1 < max_intentos
            THEN now() + interval '5 minutes' * (intentos + 1)  -- backoff exponencial
            ELSE NULL
        END
    WHERE id = p_id;
END;
$$;


--
-- Name: fn_membresia_audit_log(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_membresia_audit_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_evento    text;
    v_plan_ant  text;
    v_plan_nuevo text;
    v_actor_id  uuid;
BEGIN
    -- Obtener actor desde JWT si disponible
    v_actor_id := (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')::uuid;

    -- Determinar evento
    IF TG_OP = 'INSERT' THEN
        v_evento := CASE WHEN NEW.es_trial THEN 'trial_inicio' ELSE 'creacion' END;
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.id_plan != NEW.id_plan THEN
            SELECT codigo INTO v_plan_ant  FROM auth.planes_membresia WHERE id = OLD.id_plan;
            SELECT codigo INTO v_plan_nuevo FROM auth.planes_membresia WHERE id = NEW.id_plan;
            IF (SELECT precio_mensual FROM auth.planes_membresia WHERE id = NEW.id_plan) >
               (SELECT precio_mensual FROM auth.planes_membresia WHERE id = OLD.id_plan)
            THEN v_evento := 'upgrade';
            ELSE v_evento := 'downgrade';
            END IF;
        ELSIF OLD.estado != NEW.estado THEN
            v_evento := CASE NEW.estado
                WHEN 'suspendida'   THEN 'suspension'
                WHEN 'cancelada'    THEN 'cancelacion'
                WHEN 'grace_period' THEN 'grace_period'
                WHEN 'expirada'     THEN 'expiracion'
                WHEN 'activo'       THEN 'reactivacion'
                ELSE 'creacion'
            END;
        ELSIF OLD.score_confianza != NEW.score_confianza THEN
            v_evento := 'score_cambio';
        ELSIF OLD.override_flags != NEW.override_flags THEN
            v_evento := 'override_aplicado';
        ELSE
            RETURN NEW; -- Sin cambio relevante
        END IF;
    END IF;

    INSERT INTO auth.membresias_historial (
        id_vendedor, membresia_id, evento,
        plan_anterior, plan_nuevo, id_actor, motivo, metadata
    ) VALUES (
        NEW.id_vendedor, NEW.id, v_evento,
        v_plan_ant, v_plan_nuevo,
        v_actor_id,
        NULL,
        jsonb_build_object(
            'estado_anterior', CASE WHEN TG_OP = 'UPDATE' THEN OLD.estado ELSE NULL END,
            'estado_nuevo',    NEW.estado,
            'score_anterior',  CASE WHEN TG_OP = 'UPDATE' THEN OLD.score_confianza ELSE NULL END,
            'score_nuevo',     NEW.score_confianza,
            'override_flags',  NEW.override_flags
        )
    );

    -- Auditoría en h_vendedores_audit (solo INSERT, UPDATE, SUSPEND)
    INSERT INTO auth.h_vendedores_audit (
        id_usuario, operacion, datos_anteriores, datos_nuevos, motivo
    ) VALUES (
        NEW.id_vendedor,
        CASE WHEN v_evento = 'suspension' THEN 'SUSPEND' ELSE 'UPDATE' END,
        CASE WHEN TG_OP = 'UPDATE' THEN row_to_json(OLD)::jsonb ELSE NULL END,
        row_to_json(NEW)::jsonb,
        'Membresía: ' || v_evento
    );

    RETURN NEW;
END;
$$;


--
-- Name: fn_membresia_cascade_suspension(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_membresia_cascade_suspension() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    -- Transición a estado restringido
    IF NEW.estado IN ('suspendida', 'expirada', 'cancelada') AND
       OLD.estado NOT IN ('suspendida', 'expirada', 'cancelada') THEN

        -- Desactivar perfil público
        UPDATE auth.perfiles_publicos_vendedor
        SET activo = false, fecha_modificacion = now()
        WHERE id_vendedor = NEW.id_vendedor;

        -- Desactivar productos solo en suspensión o cancelación (no en expiración→grace)
        IF NEW.estado IN ('suspendida', 'cancelada') THEN
            UPDATE auth.productos
            SET activo = false, fecha_modificacion = now()
            WHERE id_vendedor = NEW.id_vendedor AND activo = true;
        END IF;
    END IF;

    -- Reactivación → restaurar perfil
    IF NEW.estado = 'activo' AND OLD.estado IN ('suspendida', 'grace_period', 'expirada') THEN
        UPDATE auth.perfiles_publicos_vendedor
        SET activo = true, fecha_modificacion = now()
        WHERE id_vendedor = NEW.id_vendedor;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: fn_membresia_outbox_age(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_membresia_outbox_age() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_operacion text;
    v_plan_cod  text;
BEGIN
    SELECT codigo INTO v_plan_cod FROM auth.planes_membresia WHERE id = NEW.id_plan;

    IF TG_OP = 'INSERT' THEN
        v_operacion := 'upsert_seller_node';
    ELSIF TG_OP = 'UPDATE' THEN
        v_operacion := CASE
            WHEN NEW.estado IN ('suspendida', 'cancelada') THEN 'suspend'
            WHEN OLD.id_plan != NEW.id_plan                  THEN 'update_plan'
            WHEN NEW.estado = 'activo' AND OLD.estado != 'activo' THEN 'set_active'
            ELSE 'update_plan'
        END;
    END IF;

    INSERT INTO auth.membresia_graph_outbox (id_vendedor, operacion, payload)
    VALUES (
        NEW.id_vendedor,
        v_operacion,
        jsonb_build_object(
            'plan',   v_plan_cod,
            'estado', NEW.estado,
            'activo', NEW.estado IN ('activo', 'grace_period'),
            'score',  NEW.score_confianza
        )
    );

    RETURN NEW;
END;
$$;


--
-- Name: fn_membresia_score_visibilidad(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_membresia_score_visibilidad() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    -- Solo actuar si cambió score_confianza
    IF TG_OP = 'UPDATE' AND OLD.score_confianza = NEW.score_confianza THEN
        RETURN NEW;
    END IF;

    -- Umbral: score < 30 → visibilidad reducida
    UPDATE auth.perfiles_publicos_vendedor
    SET
        score_confianza    = NEW.score_confianza,
        visibilidad_reducida = CASE
            WHEN NEW.score_confianza < 30  THEN true
            WHEN NEW.score_confianza >= 60 THEN false
            ELSE visibilidad_reducida  -- zona gris 30..59: mantener estado actual
        END,
        fecha_modificacion = now()
    WHERE id_vendedor = NEW.id_vendedor;

    RETURN NEW;
END;
$$;


--
-- Name: fn_membresia_sync_badge(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_membresia_sync_badge() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_plan_codigo text;
BEGIN
    -- Obtener código del plan nuevo
    SELECT codigo INTO v_plan_codigo
    FROM auth.planes_membresia WHERE id = NEW.id_plan;

    -- Sincronizar badge solo si membresia activa/grace
    IF NEW.estado IN ('activo', 'grace_period') THEN
        UPDATE auth.perfiles_publicos_vendedor
        SET
            badge_membresia    = v_plan_codigo,
            fecha_modificacion = now()
        WHERE id_vendedor = NEW.id_vendedor;
    END IF;

    RETURN NEW;
END;
$$;


