-- Name: fn_membresia_updated_at(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_membresia_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.fecha_modificacion := now();
    RETURN NEW;
END;
$$;


--
-- Name: fn_notify_demand_spike(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_notify_demand_spike() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_count integer;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM auth.interaction_logs
  WHERE id_objetivo = NEW.id_objetivo
    AND fecha_creacion >= now() - interval '5 minutes';

  IF v_count >= 10 THEN
    PERFORM pg_notify(
      'demand_spike',
      jsonb_build_object(
        'id_vendedor', NEW.id_objetivo,
        'event_count', v_count,
        'fired_at',    now()
      )::text
    );
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: fn_outbox_consumer_tick(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_outbox_consumer_tick() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_clientes integer;
    v_age_sync integer;
BEGIN
    v_clientes := auth.fn_procesar_clientes_graph_outbox(50);
    v_age_sync := auth.fn_procesar_age_sync_outbox(50);
    RETURN jsonb_build_object(
        'procesados',          v_clientes + v_age_sync,
        'procesados_clientes', v_clientes,
        'procesados_age_sync', v_age_sync,
        'pendientes_clientes', (SELECT count(*) FROM auth.clientes_graph_outbox WHERE estado = 'pendiente'),
        'pendientes_age_sync', (SELECT count(*) FROM auth.age_sync_outbox WHERE estado IN ('pending', 'failed')),
        'fallidos_clientes',   (SELECT count(*) FROM auth.clientes_graph_outbox WHERE estado = 'fallido'),
        'fallidos_age_sync',   (SELECT count(*) FROM auth.age_sync_outbox WHERE estado = 'failed'),
        'ts',                  now()
    );
END;
$$;


--
-- Name: FUNCTION fn_outbox_consumer_tick(); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.fn_outbox_consumer_tick() IS 'Entrypoint del worker systemd del outbox de compras: corre auth.fn_procesar_clientes_graph_outbox(50) y reporta conteos del outbox.';


