--
-- Name: fn_procesar_age_sync_outbox(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_procesar_age_sync_outbox(p_batch_size integer DEFAULT 50) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ag_catalog', 'auth', 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_graph CONSTANT text := 'smtp_posix_graph';
    v_max_batch CONSTANT int := GREATEST(1, LEAST(p_batch_size, 500));
    r RECORD;
    v_user RECORD;
    v_tier text;
    v_ok int := 0;
    v_fail int := 0;
BEGIN
    LOAD 'age';
    SET LOCAL search_path = ag_catalog, auth, public, pg_catalog;

    FOR r IN
        SELECT id, aggregate_id, tipo_evento
        FROM auth.age_sync_outbox
        WHERE estado IN ('pending', 'failed')
        ORDER BY fecha_creacion
        LIMIT v_max_batch
        FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            SELECT u.id, u.email, u.role, u.username, u.is_verified, u.activo,
                   u.nombre_visible, u.fecha_eliminacion, u.lifecycle_state
              INTO v_user
              FROM auth.users u
             WHERE u.id = r.aggregate_id;

            IF v_user.id IS NULL
               OR v_user.fecha_eliminacion IS NOT NULL
               OR coalesce(v_user.lifecycle_state, 'active') IN ('deleted', 'purged')
            THEN
                -- Usuario inexistente o eliminado: quitar el nodo del grafo
                EXECUTE format(
                    $q$SELECT * FROM ag_catalog.cypher(%L, $c$
                        MATCH (u:User {user_uuid: %L})
                        DETACH DELETE u
                        RETURN count(u)$c$) AS (res ag_catalog.agtype)$q$,
                    v_graph, r.aggregate_id::text);
            ELSE
                -- Upsert del nodo User, con profile_tier como fuente única
                v_tier := auth.resolve_effective_tier(r.aggregate_id);
                EXECUTE format(
                    $q$SELECT * FROM ag_catalog.cypher(%L, $c$
                        MERGE (u:User {user_uuid: %L})
                        SET u.email = %L,
                            u.role = %L,
                            u.is_verified = %L,
                            u.username = %L,
                            u.activo = %L,
                            u.nombre_visible = %L,
                            u.profile_tier = %L,
                            u.synced_at = %L
                        RETURN u$c$) AS (res ag_catalog.agtype)$q$,
                    v_graph,
                    r.aggregate_id::text,
                    coalesce(v_user.email, ''),
                    coalesce(v_user.role::text, ''),
                    coalesce(v_user.is_verified::text, 'false'),
                    coalesce(v_user.username, ''),
                    coalesce(v_user.activo::text, 'false'),
                    coalesce(v_user.nombre_visible, ''),
                    coalesce(v_tier, 'bronze'),
                    now()::text);
            END IF;

            UPDATE auth.age_sync_outbox
               SET estado = 'processed', procesado_en = now(), error = NULL
             WHERE id = r.id;
            v_ok := v_ok + 1;
        EXCEPTION WHEN OTHERS THEN
            UPDATE auth.age_sync_outbox
               SET estado = 'failed', error = left(SQLERRM, 500), procesado_en = now()
             WHERE id = r.id;
            v_fail := v_fail + 1;
            RAISE WARNING 'age_sync_outbox % (%) falló: %', r.id, r.tipo_evento, SQLERRM;
        END;
    END LOOP;

    RETURN v_ok;
END;
$_$;


--
-- Name: fn_procesar_billetera_graph_outbox(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_procesar_billetera_graph_outbox(p_batch_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_rec       record;
    v_ok        int := 0;
    v_fail      int := 0;
    v_graph     text;
BEGIN
    -- Verificar grafo disponible
    SELECT name INTO v_graph FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;
    IF v_graph IS NULL THEN
        RETURN jsonb_build_object('skipped', true, 'motivo', 'no_graph_configured');
    END IF;

    FOR v_rec IN
        SELECT * FROM auth.billetera_graph_outbox
        WHERE estado = 'pendiente'
          AND intentos < 3
        ORDER BY fecha_creacion
        LIMIT p_batch_size
        FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            IF v_rec.tipo_evento = 'TRANSFERRED_POINTS' THEN
                PERFORM ag_catalog.cypher(
                    v_graph,
                    format(
                        'MATCH (a:User {user_id: "%s"}), (b:User {user_id: "%s"})
                         CREATE (a)-[:TRANSFERRED_POINTS {
                             monto: %s,
                             transferencia_id: "%s",
                             comision: %s,
                             ts: timestamp()
                         }]->(b)',
                        v_rec.origen_id,
                        v_rec.receptor_id,
                        (v_rec.payload ->> 'monto_bruto')::numeric,
                        v_rec.payload ->> 'transferencia_id',
                        (v_rec.payload ->> 'comision')::numeric
                    ),
                    NULL
                )::record;

            ELSIF v_rec.tipo_evento = 'LEVEL_CHANGED' THEN
                PERFORM ag_catalog.cypher(
                    v_graph,
                    format(
                        'MATCH (u:User {user_id: "%s"})
                         SET u.nivel_lealtad = "%s",
                             u.puntos_historico = %s',
                        v_rec.origen_id,
                        v_rec.payload ->> 'nuevo_nivel',
                        (v_rec.payload ->> 'puntos_historico')::numeric
                    ),
                    NULL
                )::record;
            END IF;

            UPDATE auth.billetera_graph_outbox
            SET estado = 'procesado',
                procesado_at = now(),
                intentos = intentos + 1
            WHERE id = v_rec.id;

            v_ok := v_ok + 1;

        EXCEPTION WHEN OTHERS THEN
            UPDATE auth.billetera_graph_outbox
            SET intentos = intentos + 1,
                estado = CASE WHEN intentos + 1 >= 3 THEN 'fallido' ELSE 'pendiente' END,
                error_detalle = SQLERRM
            WHERE id = v_rec.id;
            v_fail := v_fail + 1;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'procesados', v_ok,
        'fallidos',   v_fail,
        'ts',         now()
    );
END;
$$;


--
-- Name: fn_procesar_clientes_graph_outbox(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_procesar_clientes_graph_outbox(p_batch_size integer DEFAULT 50) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $_$
DECLARE
    v_graph_name  text;
    v_rec         record;
    v_processed   integer := 0;
    v_id_comprador uuid;
    v_id_vendedor  uuid;
    v_b_email     text;
    v_b_role      text;
    v_b_username  text;
    v_b_verified  boolean;
    v_s_email     text;
    v_s_role      text;
    v_s_username  text;
    v_s_verified  boolean;
BEGIN
    -- RN-018: Degradación elegante si AGE no está disponible
    BEGIN
        SELECT name INTO v_graph_name FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;
        IF v_graph_name IS NULL THEN
            RAISE WARNING 'AGE: no se encontró grafo configurado';
            RETURN 0;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'AGE no disponible: %', SQLERRM;
        RETURN 0;
    END;

    FOR v_rec IN
        SELECT id, operacion, payload
        FROM auth.clientes_graph_outbox
        WHERE estado = 'pendiente'
        ORDER BY creado_en
        LIMIT p_batch_size
        FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            UPDATE auth.clientes_graph_outbox
            SET estado = 'procesando', intentos = intentos + 1
            WHERE id = v_rec.id;

            IF v_rec.operacion IN ('UPSERT_COMPRO_EN', 'UPSERT_BUYER_NODE') THEN
                v_id_comprador := NULLIF(v_rec.payload ->> 'id_comprador', '')::uuid;
                v_id_vendedor  := NULLIF(v_rec.payload ->> 'id_vendedor', '')::uuid;

                -- Upsert nodo User del comprador (label real: User, prop user_uuid).
                -- Props refrescadas desde auth.users cuando el usuario existe.
                IF v_id_comprador IS NOT NULL THEN
                    SELECT u.email, u.role::text, COALESCE(u.username, ''), u.is_verified
                      INTO v_b_email, v_b_role, v_b_username, v_b_verified
                    FROM auth.users u
                    WHERE u.id = v_id_comprador;

                    EXECUTE format(
                        $q$SELECT * FROM ag_catalog.cypher(%L, $c$
                            MERGE (b:User {user_uuid: %L})
                            SET b.email       = %L,
                                b.role        = %L,
                                b.username    = %L,
                                b.is_verified = %s
                            RETURN b
                        $c$) AS (b ag_catalog.agtype)$q$,
                        v_graph_name,
                        v_id_comprador::text,
                        COALESCE(v_b_email, ''),
                        COALESCE(v_b_role, 'unknown'),
                        COALESCE(v_b_username, ''),
                        COALESCE(v_b_verified, false)::text
                    );
                END IF;

                -- Upsert nodo User del vendedor (solo operaciones con vendedor)
                IF v_id_vendedor IS NOT NULL THEN
                    SELECT u.email, u.role::text, COALESCE(u.username, ''), u.is_verified
                      INTO v_s_email, v_s_role, v_s_username, v_s_verified
                    FROM auth.users u
                    WHERE u.id = v_id_vendedor;

                    EXECUTE format(
                        $q$SELECT * FROM ag_catalog.cypher(%L, $c$
                            MERGE (s:User {user_uuid: %L})
                            SET s.email       = %L,
                                s.role        = %L,
                                s.username    = %L,
                                s.is_verified = %s
                            RETURN s
                        $c$) AS (s ag_catalog.agtype)$q$,
                        v_graph_name,
                        v_id_vendedor::text,
                        COALESCE(v_s_email, ''),
                        COALESCE(v_s_role, 'unknown'),
                        COALESCE(v_s_username, ''),
                        COALESCE(v_s_verified, false)::text
                    );
                END IF;

                -- Edge canónico de compra: COMPRO (prop estado='completada').
                -- MERGE por par (b)-[r:COMPRO]->(s) sin mapa de props: matchea
                -- CUALQUIER edge COMPRO existente entre el par (idempotencia
                -- real, una arista por par) y los agregados se acumulan con
                -- coalesce. Nota: este AGE no soporta ON CREATE/ON MATCH SET.
                IF v_rec.operacion = 'UPSERT_COMPRO_EN'
                   AND v_id_comprador IS NOT NULL
                   AND v_id_vendedor IS NOT NULL THEN
                    EXECUTE format(
                        $q$SELECT * FROM ag_catalog.cypher(%L, $c$
                            MATCH (b:User {user_uuid: %L}), (s:User {user_uuid: %L})
                            MERGE (b)-[r:COMPRO]->(s)
                            SET r.estado        = 'completada',
                                r.total_ordenes = coalesce(r.total_ordenes, 0) + 1,
                                r.total         = coalesce(r.total, 0) + %s,
                                r.ultima_compra = %L,
                                r.orden_id      = %L,
                                r.creado_en     = coalesce(r.creado_en, %L)
                            RETURN r
                        $c$) AS (r ag_catalog.agtype)$q$,
                        v_graph_name,
                        v_id_comprador::text,
                        v_id_vendedor::text,
                        COALESCE((v_rec.payload ->> 'total')::numeric, 0),
                        COALESCE(v_rec.payload ->> 'fecha', ''),
                        COALESCE(v_rec.payload ->> 'orden_id', ''),
                        now()::text
                    );
                END IF;
            END IF;

            -- Operaciones no implementadas (ej. DELETE_COMPRO_EN) se marcan
            -- completadas sin efecto, igual que el comportamiento previo.
            UPDATE auth.clientes_graph_outbox
            SET estado = 'completado', procesado_en = now()
            WHERE id = v_rec.id;
            v_processed := v_processed + 1;

        EXCEPTION WHEN OTHERS THEN
            -- Reintento con tope: 'fallido' tras 5 intentos, si no 'pendiente'.
            UPDATE auth.clientes_graph_outbox
            SET estado = CASE WHEN intentos + 1 >= 5 THEN 'fallido' ELSE 'pendiente' END,
                intentos = intentos + 1,
                ultimo_error = SQLERRM
            WHERE id = v_rec.id;
        END;
    END LOOP;

    RETURN v_processed;
END;
$_$;


--
-- Name: FUNCTION fn_procesar_clientes_graph_outbox(p_batch_size integer); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.fn_procesar_clientes_graph_outbox(p_batch_size integer) IS 'Consumer del outbox compras→grafo AGE. Labels reales: nodo User (user_uuid), edge COMPRO (estado=completada). Idempotente via MERGE.';


--
-- Name: fn_procesar_expiracion_puntos(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_procesar_expiracion_puntos() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_rec              record;
    v_total_expirado   numeric := 0;
    v_usuarios_afect   int := 0;
BEGIN
    FOR v_rec IN
        SELECT
            mp.id_usuario,
            SUM(ABS(mp.monto)) AS puntos_a_expirar
        FROM auth.movimientos_puntos mp
        JOIN auth.billetera b ON b.id_usuario = mp.id_usuario AND b.activo = true
        WHERE mp.expira_en IS NOT NULL
          AND mp.expira_en <= now()
          AND mp.tipo_movimiento IN ('ganado_venta', 'ganado_bienvenida', 'cashback')
          AND mp.monto > 0
          AND NOT EXISTS (
              SELECT 1 FROM auth.movimientos_puntos mp2
              WHERE mp2.id_usuario = mp.id_usuario
                AND mp2.tipo_movimiento = 'expiracion'
                AND mp2.referencia = mp.id::text
          )
          AND b.saldo > 0
        GROUP BY mp.id_usuario
    LOOP
        DECLARE
            v_saldo_actual numeric;
            v_a_expirar    numeric;
        BEGIN
            SELECT saldo INTO v_saldo_actual
            FROM auth.billetera WHERE id_usuario = v_rec.id_usuario FOR UPDATE;

            v_a_expirar := LEAST(v_rec.puntos_a_expirar, v_saldo_actual);

            IF v_a_expirar > 0 THEN
                UPDATE auth.billetera
                SET saldo = saldo - v_a_expirar, fecha_modificacion = now()
                WHERE id_usuario = v_rec.id_usuario;

                INSERT INTO auth.movimientos_puntos (
                    id_usuario, tipo_movimiento, monto, saldo_anterior, saldo_posterior,
                    detalle
                ) VALUES (
                    v_rec.id_usuario, 'expiracion', -v_a_expirar,
                    v_saldo_actual, v_saldo_actual - v_a_expirar,
                    jsonb_build_object('procesado_en', now(), 'lote_expiracion', true)
                );

                v_total_expirado  := v_total_expirado + v_a_expirar;
                v_usuarios_afect  := v_usuarios_afect + 1;
            END IF;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'total_expirado',     v_total_expirado,
        'usuarios_afectados', v_usuarios_afect,
        'procesado_en',       now()
    );
END;
$$;


--
-- Name: fn_procesar_import_batch_next(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_procesar_import_batch_next() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
declare
  v_batch     record;

  v_fila      jsonb;

  v_fila_idx  integer := 0;

  v_ok        integer := 0;

  v_err       integer := 0;

  v_errores   jsonb := '[]';

  v_err_item  jsonb;

begin
  select * into v_batch
  from auth.productos_import_batch
  where estado = 'pendiente'
  order by fecha_creacion asc limit 1
  for update skip locked;


  if not found then return jsonb_build_object('status', 'no_pending_batches');
 end if;


  update auth.productos_import_batch set estado = 'procesando' where id = v_batch.id;


    perform set_config('request.jwt.claims',
    jsonb_build_object('sub', v_batch.id_vendedor, 'role', 'seller')::text, true);


  for v_fila in select value from jsonb_array_elements(v_batch.payload_jsonb) loop
    begin
      perform auth.seller_upsert_product(
        p_nombre_categoria := v_fila ->> 'categoria',
        p_nombre           := v_fila ->> 'nombre',
        p_descripcion      := v_fila ->> 'descripcion',
        p_precio           := (v_fila ->> 'precio')::numeric,
        p_condicion        := v_fila ->> 'condicion',
        p_activo           := false,          p_stock_total      := (v_fila ->> 'stock')::integer,
        p_motivo           := 'import_batch_' || v_batch.id::text
      );

      v_ok := v_ok + 1;

    exception when others then
      v_err_item := jsonb_build_object('fila', v_fila_idx, 'error', sqlerrm, 'data', v_fila);

      v_errores  := v_errores || jsonb_build_array(v_err_item);

      v_err      := v_err + 1;

    end;

    v_fila_idx := v_fila_idx + 1;

  end loop;


  update auth.productos_import_batch
  set estado = case when v_err = 0 then 'completado' else 'fallido' end,
      filas_ok = v_ok, filas_error = v_err,
      errores = v_errores, completed_at = now()
  where id = v_batch.id;


  return jsonb_build_object('batch_id', v_batch.id, 'filas_ok', v_ok, 'filas_error', v_err);

end;
 $$;


--
-- Name: fn_procesar_inventario_graph_outbox(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_procesar_inventario_graph_outbox(p_batch_size integer DEFAULT 50) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $_$
DECLARE
    v_evento record;
    v_procesados integer := 0;
    v_graph_name text;
BEGIN
    -- Introspección del nombre del grafo (CU-A-BS-001)
    BEGIN
        SELECT name INTO v_graph_name FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
        -- AGE no disponible: marcar todos como procesados con nota
        UPDATE auth.inventario_graph_outbox
        SET procesado = true, procesado_en = now(),
            error_ultimo = 'AGE no disponible — degradación elegante'
        WHERE procesado = false AND intentos >= 3;
        RETURN 0;
    END;

    IF v_graph_name IS NULL THEN RETURN 0; END IF;

    FOR v_evento IN
        SELECT * FROM auth.inventario_graph_outbox
        WHERE procesado = false AND intentos < 5
        ORDER BY creado_en
        LIMIT p_batch_size
        FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            -- Actualizar nodo Producto en AGE con stock actual
            EXECUTE format(
                $age$
                SELECT * FROM cypher(%L, $c$
                    MATCH (p:Producto {id_producto: %L})
                    SET p.stock_disponible = %s,
                        p.total_stock = %s,
                        p.tiene_stock = %s,
                        p.fecha_actualizacion = %L
                    RETURN p
                $c$) AS (p agtype)
                $age$,
                v_graph_name,
                v_evento.id_producto::text,
                (v_evento.payload ->> 'stock_disponible')::int,
                (v_evento.payload ->> 'stock_total')::int,
                (v_evento.payload ->> 'stock_disponible')::int > 0,
                now()::text
            );

            UPDATE auth.inventario_graph_outbox
            SET procesado = true, procesado_en = now()
            WHERE id = v_evento.id;

            v_procesados := v_procesados + 1;
        EXCEPTION WHEN OTHERS THEN
            UPDATE auth.inventario_graph_outbox
            SET intentos = intentos + 1,
                error_ultimo = SQLERRM
            WHERE id = v_evento.id;
        END;
    END LOOP;

    RETURN v_procesados;
END;
$_$;


--
-- Name: fn_procesar_membresia_graph_outbox(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_procesar_membresia_graph_outbox(p_batch_size integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $_$
DECLARE
    rec           record;
    v_graph_name  text;
    v_procesados  integer := 0;
    v_errores     integer := 0;
BEGIN
    -- Obtener nombre del grafo por introspección
    BEGIN
        SELECT name INTO v_graph_name FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
        v_graph_name := NULL;
    END;

    FOR rec IN
        SELECT id, id_vendedor, operacion, payload
        FROM auth.membresia_graph_outbox
        WHERE procesado_at IS NULL AND intentos < 3
        ORDER BY fecha_creacion ASC
        LIMIT p_batch_size
    LOOP
        BEGIN
            IF v_graph_name IS NOT NULL THEN
                CASE rec.operacion
                    WHEN 'upsert_seller_node', 'update_plan', 'set_active' THEN
                        EXECUTE format(
                            'SELECT * FROM cypher(%L, $c$ MATCH (s:Seller {user_id: %L})
                              SET s.plan = %L, s.activo = %L, s.score_confianza = %L,
                                  s.updated_at = %L
                              $c$) AS (v agtype)',
                            v_graph_name,
                            rec.id_vendedor::text,
                            rec.payload ->> 'plan',
                            (rec.payload ->> 'activo')::boolean,
                            rec.payload ->> 'score',
                            now()::text
                        );
                    WHEN 'suspend' THEN
                        EXECUTE format(
                            'SELECT * FROM cypher(%L, $c$ MATCH (s:Seller {user_id: %L})
                              SET s.activo = false, s.suspendida_at = %L $c$) AS (v agtype)',
                            v_graph_name,
                            rec.id_vendedor::text,
                            now()::text
                        );
                END CASE;
            END IF;

            UPDATE auth.membresia_graph_outbox
            SET procesado_at = now(), intentos = intentos + 1
            WHERE id = rec.id;

            v_procesados := v_procesados + 1;
        EXCEPTION WHEN OTHERS THEN
            UPDATE auth.membresia_graph_outbox
            SET intentos = intentos + 1, error_msg = SQLERRM
            WHERE id = rec.id;
            v_errores := v_errores + 1;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'procesados', v_procesados,
        'errores',    v_errores,
        'age_activo', v_graph_name IS NOT NULL
    );
END;
$_$;


--
-- Name: fn_procesar_perfil_graph_outbox(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_procesar_perfil_graph_outbox(p_batch integer DEFAULT 50) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $_$
DECLARE
  r               record;
  v_graph_name    text;
  v_processed     integer := 0;
  v_cypher        text;
BEGIN
  -- Obtener nombre del grafo por introspección (CU-A-BS-001)
  BEGIN
    SELECT name INTO v_graph_name
    FROM ag_catalog.ag_graph
    ORDER BY name LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    -- AGE no disponible: marcar como procesados con error
    UPDATE auth.perfil_graph_outbox
       SET procesado = true,
           ultimo_error = 'AGE extension no disponible: ' || sqlerrm,
           procesado_at = now()
     WHERE procesado = false
       AND intentos >= 3;
    RETURN 0;
  END;

  IF v_graph_name IS NULL THEN
    RETURN 0;  -- Grafo no configurado, degradación elegante
  END IF;

  FOR r IN
    SELECT *
    FROM auth.perfil_graph_outbox
    WHERE procesado = false
      AND intentos < 3
    ORDER BY fecha_creacion ASC
    LIMIT p_batch
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      IF r.operacion IN ('UPSERT', 'VERIFY') THEN
        v_cypher := FORMAT(
          'SELECT * FROM cypher(%L, $c$
            MERGE (s:Seller {user_id: %L})
            SET s.slug_publico = %L,
                s.nombre_marca = %L,
                s.activo = %s,
                s.verificado = %s,
                s.badge_membresia = %L,
                s.updated_at = %L
            RETURN s
          $c$) AS (s agtype)',
          v_graph_name,
          (r.payload->>'id_usuario')::text,
          (r.payload->>'slug_publico')::text,
          (r.payload->>'nombre_marca')::text,
          (r.payload->>'activo')::text,
          (r.payload->>'verificado')::text,
          (r.payload->>'badge_membresia')::text,
          now()::text
        );
        EXECUTE v_cypher;

      ELSIF r.operacion = 'SUSPEND' THEN
        v_cypher := FORMAT(
          'SELECT * FROM cypher(%L, $c$
            MATCH (s:Seller {user_id: %L})
            SET s.activo = false, s.suspended_at = %L
            RETURN s
          $c$) AS (s agtype)',
          v_graph_name,
          (r.payload->>'id_usuario')::text,
          now()::text
        );
        EXECUTE v_cypher;

      ELSIF r.operacion = 'DELETE' THEN
        v_cypher := FORMAT(
          'SELECT * FROM cypher(%L, $c$
            MATCH (s:Seller {user_id: %L})
            DETACH DELETE s
          $c$) AS (s agtype)',
          v_graph_name,
          (r.payload->>'id_usuario')::text
        );
        EXECUTE v_cypher;
      END IF;

      UPDATE auth.perfil_graph_outbox
         SET procesado = true,
             procesado_at = now(),
             ultimo_error = NULL
       WHERE id = r.id;

      v_processed := v_processed + 1;

    EXCEPTION WHEN OTHERS THEN
      UPDATE auth.perfil_graph_outbox
         SET intentos = intentos + 1,
             ultimo_error = SQLERRM
       WHERE id = r.id;
    END;
  END LOOP;

  -- Marcar como procesados con error los que superaron reintentos
  UPDATE auth.perfil_graph_outbox
     SET procesado = true,
         procesado_at = now()
   WHERE procesado = false
     AND intentos >= 3;

  RETURN v_processed;
END;
$_$;


--
-- Name: fn_procesar_productos_graph_outbox(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_procesar_productos_graph_outbox(p_batch_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $_$
declare
  v_event   record;

  v_ok      integer := 0;

  v_err     integer := 0;

  v_graph   text;

  v_sql     text;

begin
    begin
    select name into v_graph from ag_catalog.ag_graph order by name limit 1;

  exception when others then v_graph := null;
 end;


  for v_event in
    select id, id_producto, tipo_evento, payload
    from auth.productos_graph_outbox
    where procesado = false
      and intentos < 3
    order by fecha_creacion asc
    limit p_batch_size
    for update skip locked
  loop
    begin
      if v_graph is not null then
                if v_event.tipo_evento in ('UPSERT', 'ACTIVATE', 'RESTORE') then
          v_sql := format(
            $age$
            SELECT * FROM cypher(%L, $c$
              MERGE (p:Producto {id_producto: %L})
              SET p.nombre = %L, p.id_vendedor = %L, p.activo = true, p.fecha_actualizacion = %L
            $c$) AS (result agtype)
            $age$,
            v_graph,
            v_event.id_producto::text,
            v_event.payload ->> 'nombre',
            v_event.payload ->> 'id_vendedor',
            extract(epoch from now())::text
          );

          execute v_sql;

        elsif v_event.tipo_evento in ('DEACTIVATE', 'SOFT_DELETE') then
          v_sql := format(
            $age$
            SELECT * FROM cypher(%L, $c$
              MATCH (p:Producto {id_producto: %L})
              SET p.activo = false, p.deleted = %L, p.fecha_actualizacion = %L
            $c$) AS (result agtype)
            $age$,
            v_graph,
            v_event.id_producto::text,
            (v_event.tipo_evento = 'SOFT_DELETE')::text,
            extract(epoch from now())::text
          );

          execute v_sql;

        end if;

      end if;


      update auth.productos_graph_outbox
      set procesado=true, processed_at=now(), error_msg=null, intentos=intentos+1
      where id = v_event.id;

      v_ok := v_ok + 1;


    exception when others then
      update auth.productos_graph_outbox
      set intentos=intentos+1, error_msg=sqlerrm
      where id = v_event.id;

      v_err := v_err + 1;

    end;

  end loop;


  return jsonb_build_object('procesados_ok', v_ok, 'procesados_err', v_err);

end;
 $_$;


--
-- Name: fn_procesar_resena_graph_outbox(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_procesar_resena_graph_outbox(p_batch_size integer DEFAULT 50) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $_$
DECLARE
    v_graph_name  text;
    v_rec         record;
    v_procesados  int := 0;
BEGIN
    BEGIN
        SELECT name INTO v_graph_name FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;
        IF v_graph_name IS NULL THEN RETURN 0; END IF;
    EXCEPTION WHEN OTHERS THEN
        RETURN 0;  -- AGE no disponible, degradación elegante
    END;

    FOR v_rec IN
        SELECT o.id, o.resena_id, o.operacion, o.payload
        FROM auth.resena_graph_outbox o
        WHERE o.procesado = false AND o.intentos < 5
        ORDER BY o.fecha_creacion ASC
        LIMIT p_batch_size
        FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            EXECUTE format(
                'SELECT * FROM cypher(%L, $c$
                 MATCH (b:Buyer {user_id: %L}), (s:Seller {user_id: %L})
                 MERGE (b)-[r:RESENO_A {orden_id: %L}]->(s)
                 ON CREATE SET
                     r.calificacion = %s,
                     r.verificada   = %L,
                     r.fecha        = %L
                 ON MATCH SET
                     r.calificacion = %s,
                     r.sentimiento  = %L,
                     r.verificada   = %L,
                     r.actualizado  = %L
                 $c$) AS (v agtype)',
                v_graph_name,
                (v_rec.payload->>'id_comprador'),
                (v_rec.payload->>'id_vendedor'),
                (v_rec.payload->>'orden_id'),
                (v_rec.payload->>'calificacion')::float,
                (v_rec.payload->>'verificada')::boolean,
                now()::text,
                (v_rec.payload->>'calificacion')::float,
                COALESCE(v_rec.payload->>'sentimiento', 'neutro'),
                (v_rec.payload->>'verificada')::boolean,
                now()::text
            );

            UPDATE auth.resena_graph_outbox SET
                procesado    = true,
                procesado_at = now()
            WHERE id = v_rec.id;

            v_procesados := v_procesados + 1;

        EXCEPTION WHEN OTHERS THEN
            UPDATE auth.resena_graph_outbox SET
                intentos  = intentos + 1,
                error_msg = SQLERRM
            WHERE id = v_rec.id;
        END;
    END LOOP;

    RETURN v_procesados;
END;
$_$;


--
-- Name: fn_procesar_transferencias_programadas(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_procesar_transferencias_programadas() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_rec         record;
    v_ok          int := 0;
    v_fail        int := 0;
    v_result      jsonb;
BEGIN
    FOR v_rec IN
        SELECT * FROM auth.transferencias_programadas
        WHERE estado = 'pendiente'
          AND ejecutar_en <= now()
          AND intentos < 3
        ORDER BY ejecutar_en
        LIMIT 50
        FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            -- Simular JWT del origen para fn_current_user_id dentro de seller_transferir_puntos
            PERFORM set_config('app.current_user_id', v_rec.id_usuario_origen::text, true);

            SELECT auth.seller_transferir_puntos(
                v_rec.id_usuario_receptor,
                v_rec.monto,
                COALESCE(v_rec.nota, 'Transferencia programada'),
                'prog-' || v_rec.id::text
            ) INTO v_result;

            IF (v_result ->> 'error') IS NOT NULL THEN
                UPDATE auth.transferencias_programadas
                SET intentos      = intentos + 1,
                    estado        = CASE WHEN intentos + 1 >= 3 THEN 'fallida' ELSE 'pendiente' END,
                    error_detalle = v_result ->> 'error',
                    resultado_jsonb = v_result
                WHERE id = v_rec.id;
                v_fail := v_fail + 1;
            ELSE
                UPDATE auth.transferencias_programadas
                SET estado       = 'ejecutada',
                    ejecutada_at = now(),
                    intentos     = intentos + 1,
                    resultado_jsonb = v_result
                WHERE id = v_rec.id;
                v_ok := v_ok + 1;
            END IF;

        EXCEPTION WHEN OTHERS THEN
            UPDATE auth.transferencias_programadas
            SET intentos      = intentos + 1,
                estado        = CASE WHEN intentos + 1 >= 3 THEN 'fallida' ELSE 'pendiente' END,
                error_detalle = SQLERRM
            WHERE id = v_rec.id;
            v_fail := v_fail + 1;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'ejecutadas', v_ok,
        'fallidas',   v_fail,
        'ts',         now()
    );
END;
$$;


--
-- Name: fn_procesar_ubicacion_graph_outbox(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_procesar_ubicacion_graph_outbox(p_batch_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $_$
DECLARE
  v_rec        auth.ubicacion_graph_outbox%ROWTYPE;
  v_graf_name  text;
  v_cyph       text;
  v_procesados integer := 0;
  v_errores    integer := 0;
  v_age_ok     boolean := false;
BEGIN
  -- Verificar AGE disponible
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'age') THEN
    v_age_ok := true;
    -- Obtener nombre real del grafo por introspección (CU-A-BS-001)
    SELECT name INTO v_graf_name
    FROM ag_catalog.ag_graph
    ORDER BY name LIMIT 1;
  END IF;

  FOR v_rec IN
    SELECT * FROM auth.ubicacion_graph_outbox
    WHERE procesado = false AND intentos < 3
    ORDER BY fecha_creacion ASC
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      IF v_age_ok AND v_graf_name IS NOT NULL THEN
        IF v_rec.operacion IN ('UPSERT') THEN
          v_cyph := format(
            $cyph$
              SELECT * FROM cypher('%s', $cypher$
                MERGE (u:User {id_usuario: '%s'})
                MERGE (loc:Ubicacion {id_ubicacion: '%s'})
                ON CREATE SET
                  loc.nombre   = '%s',
                  loc.tipo     = '%s',
                  loc.latitud  = %s,
                  loc.longitud = %s,
                  loc.estado   = '%s',
                  loc.sincronizado_en  = timestamp '%s'
                ON MATCH SET
                  loc.nombre   = '%s',
                  loc.estado   = '%s',
                  loc.sincronizado_en  = timestamp '%s'
                MERGE (u)-[:UBICADO_EN {es_principal: false}]->(loc)
              $cypher$) AS (result agtype)
            $cyph$,
            v_graf_name,
            v_rec.id_usuario,
            v_rec.id_ubicacion,
            COALESCE(v_rec.payload->>'nombre', ''),
            COALESCE(v_rec.payload->>'tipo', 'punto_venta'),
            COALESCE(v_rec.payload->>'latitud', '0'),
            COALESCE(v_rec.payload->>'longitud', '0'),
            COALESCE(v_rec.payload->>'estado', 'activo'),
            now(),
            COALESCE(v_rec.payload->>'nombre', ''),
            COALESCE(v_rec.payload->>'estado', 'activo'),
            now()
          );
          EXECUTE v_cyph;
        ELSIF v_rec.operacion = 'DEACTIVATE' THEN
          v_cyph := format(
            $cyph$
              SELECT * FROM cypher('%s', $cypher$
                MATCH (loc:Ubicacion {id_ubicacion: '%s'})
                SET loc.estado = 'inactivo', loc.sincronizado_en = timestamp '%s'
              $cypher$) AS (result agtype)
            $cyph$,
            v_graf_name, v_rec.id_ubicacion, now()
          );
          EXECUTE v_cyph;
        END IF;
      END IF;

      -- Marcar como procesado (incluso si AGE no estaba disponible)
      UPDATE auth.ubicacion_graph_outbox
      SET procesado = true, procesado_at = now(), intentos = intentos + 1
      WHERE id = v_rec.id;

      v_procesados := v_procesados + 1;

    EXCEPTION WHEN OTHERS THEN
      UPDATE auth.ubicacion_graph_outbox
      SET intentos = intentos + 1, error_msg = SQLERRM
      WHERE id = v_rec.id;
      v_errores := v_errores + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'procesados', v_procesados,
    'errores', v_errores,
    'age_disponible', v_age_ok
  );
END;
$_$;


--
-- Name: fn_propagate_softdelete_ubicaciones(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_propagate_softdelete_ubicaciones() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.activo = false AND (OLD.activo = true OR OLD.activo IS NULL) THEN
    UPDATE auth.ubicaciones
    SET estado = 'inactivo', fecha_eliminacion = now(), fecha_actualizacion = now()
    WHERE id_usuario = NEW.id AND fecha_eliminacion IS NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_purgar_historico_automatico(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_purgar_historico_automatico(p_actor_uid uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_count_purgados BIGINT := 0;
    v_preview        JSONB;
BEGIN
    -- Desglose antes de purgar (para log)
    SELECT jsonb_object_agg(tabla_origen, cnt)
    INTO v_preview
    FROM (
        SELECT tabla_origen, COUNT(*) AS cnt
        FROM auth.historial_eliminaciones
        WHERE NOT purgado
          AND retencion_hasta < now()
        GROUP BY tabla_origen
    ) t;

    DELETE FROM auth.historial_eliminaciones
    WHERE NOT purgado
      AND retencion_hasta < now();

    GET DIAGNOSTICS v_count_purgados = ROW_COUNT;

    IF v_count_purgados > 0 THEN
        INSERT INTO auth.log_mantenimiento (tipo, resultado, detalle_jsonb, ejecutado_por, archivado)
        VALUES (
            'PURGA_HISTORICO_AUTOMATICO',
            'EXITOSO',
            jsonb_build_object(
                'registros_purgados', v_count_purgados,
                'desglose',           COALESCE(v_preview, '{}'),
                'ejecutado_en',       now()
            ),
            p_actor_uid,
            false
        );
    END IF;

    RETURN jsonb_build_object(
        'registros_purgados', v_count_purgados,
        'desglose',           COALESCE(v_preview, '{}')
    );
END;
$$;


--
-- Name: fn_push_queue_updated_at(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_push_queue_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.fecha_actualizacion := now();
    RETURN NEW;
END;
$$;


--
-- Name: fn_queue_age_user_event(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_queue_age_user_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_event text;
BEGIN
  v_event := CASE TG_OP
    WHEN 'INSERT' THEN 'USER_CREATED'
    WHEN 'UPDATE' THEN 'USER_UPDATED'
    ELSE 'USER_DELETED_ATTEMPT'
  END;

  INSERT INTO auth.age_sync_outbox(aggregate_type, aggregate_id, tipo_evento, payload)
  VALUES (
    'auth.users',
    COALESCE(NEW.id, OLD.id),
    v_event,
    jsonb_build_object(
      'old', CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) ELSE NULL END,
      'new', CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) ELSE NULL END
    )
  );

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: fn_queue_producto_graph_event(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_queue_producto_graph_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_event_type text;

begin
  if tg_op = 'INSERT' then
    v_event_type := 'UPSERT';

  else
    if old.fecha_eliminacion is null and new.fecha_eliminacion is not null then
      v_event_type := 'SOFT_DELETE';

    elsif old.fecha_eliminacion is not null and new.fecha_eliminacion is null then
      v_event_type := 'RESTORE';

    elsif not coalesce(old.activo, false) and coalesce(new.activo, false) then
      v_event_type := 'ACTIVATE';

    elsif coalesce(old.activo, false) and not coalesce(new.activo, false) then
      v_event_type := 'DEACTIVATE';

    else
      v_event_type := 'UPSERT';

    end if;

  end if;


  insert into auth.productos_graph_outbox (id_producto, tipo_evento, payload)
  values (
    new.id,
    v_event_type,
    jsonb_build_object(
      'producto_id', new.id,
      'id_vendedor', new.id_vendedor,
      'nombre',      new.nombre,
      'activo',      new.activo,
      'deleted_at',  new.fecha_eliminacion,
      'event_type',  v_event_type,
      'queued_at',   now()
    )
  );

  return new;

end;
 $$;


--
-- Name: fn_recalc_inventory_product(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_recalc_inventory_product(p_producto_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_total integer;
    v_reserved integer;
BEGIN
    SELECT
        COALESCE(SUM(stock), 0),
        COALESCE(SUM(stock_reservado), 0)
    INTO v_total, v_reserved
    FROM auth.inventario_ubicacion
    WHERE id_producto = p_producto_id AND activo = true;

    UPDATE auth.inventario_producto
    SET total_stock = v_total,
        stock_reservado = v_reserved,
        fecha_modificacion = now()
    WHERE id_producto = p_producto_id;
END;
$$;


--
-- Name: fn_recalcular_geo_cache(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_recalcular_geo_cache(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_res jsonb;
BEGIN
  WITH clusters AS (
    SELECT ST_ClusterDBSCAN(geom, 0.01, 1) OVER () AS cid, geom
      FROM public.geo_zones
     WHERE is_active = true AND fecha_eliminacion IS NULL
  ), agg AS (
    SELECT cid, COUNT(*) AS n, ST_Centroid(ST_Collect(geom)) AS centroid
      FROM clusters WHERE cid IS NOT NULL GROUP BY cid
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'cluster_id', cid, 'n_zonas', n, 'centroid', ST_AsGeoJSON(centroid)::jsonb)),
    '[]'::jsonb)
  INTO v_res
  FROM agg;
  RETURN v_res;
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: fn_recalcular_nivel_lealtad(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_recalcular_nivel_lealtad() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_nivel_id    uuid;
    v_nivel_viejo uuid;
BEGIN
    SELECT id INTO v_nivel_id
    FROM auth.niveles_lealtad
    WHERE activo = true
      AND NEW.puntos_acumulados_historico >= puntos_minimos
      AND (puntos_maximos IS NULL OR NEW.puntos_acumulados_historico <= puntos_maximos)
    ORDER BY puntos_minimos DESC
    LIMIT 1;

    v_nivel_viejo := OLD.nivel_lealtad_id;

    IF v_nivel_id IS DISTINCT FROM v_nivel_viejo THEN
        NEW.nivel_lealtad_id := v_nivel_id;

        -- Auditoría de cambio de nivel
        INSERT INTO auth.h_vendedores_audit (
            id_usuario, campo_modificado, valor_anterior, valor_nuevo,
            modificado_por, motivo
        ) VALUES (
            NEW.id_usuario, 'nivel_lealtad',
            v_nivel_viejo::text, v_nivel_id::text,
            NEW.id_usuario, 'recalculo_automatico'
        );

        -- Outbox AGE para sync de nivel
        INSERT INTO auth.billetera_graph_outbox (
            tipo_evento, origen_id, payload
        ) VALUES (
            'LEVEL_CHANGED', NEW.id_usuario,
            jsonb_build_object(
                'nuevo_nivel_id', v_nivel_id,
                'puntos_historico', NEW.puntos_acumulados_historico
            )
        );
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: fn_recalcular_score_confianza_batch(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_recalcular_score_confianza_batch() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actualizados integer := 0;
BEGIN
    -- Actualiza score desde public.user_risk_scores (tabla real confirmada)
    UPDATE auth.membresias_vendedor mv
    SET score_confianza = GREATEST(0, LEAST(100,
        100.0 - COALESCE(urs.score, 0)::numeric
    ))
    FROM public.user_risk_scores urs
    WHERE urs.id_usuario = mv.id_vendedor
      AND mv.estado IN ('activo', 'grace_period')
      AND mv.fecha_eliminacion IS NULL
      AND ABS(mv.score_confianza - GREATEST(0, LEAST(100, 100.0 - COALESCE(urs.score, 0)::numeric))) > 0.01;

    GET DIAGNOSTICS v_actualizados = ROW_COUNT;

    RETURN jsonb_build_object(
        'actualizados', v_actualizados,
        'ejecutado_at', now()
    );
END;
$$;


--
-- Name: fn_recalcular_score_reputacion(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_recalcular_score_reputacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_avg   numeric(10,2);
  v_total integer;
BEGIN
  SELECT ROUND(AVG(calificacion)::numeric, 2), COUNT(*)
  INTO v_avg, v_total
  FROM auth.resenas
  WHERE id_vendedor = NEW.id_vendedor;

  UPDATE auth.perfiles_publicos_vendedor
  SET badge_confiable   = (v_avg >= 4.5 AND v_total >= 10),
      fecha_modificacion = now()
  WHERE id_vendedor = NEW.id_vendedor;

  RETURN NEW;
END;
$$;


--
-- Name: fn_reconcile_all_inventory_aggregates(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_reconcile_all_inventory_aggregates() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_producto_id uuid;
    v_count integer := 0;
BEGIN
    FOR v_producto_id IN
        SELECT id_producto FROM auth.inventario_producto WHERE activo = true
    LOOP
        PERFORM auth.fn_recalc_inventory_product(v_producto_id);
        v_count := v_count + 1;
    END LOOP;
    RETURN v_count;
END;
$$;


--
-- Name: fn_registrar_adjunto(uuid, text, text, text, text, bigint, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_registrar_adjunto(p_mensaje_id uuid, p_tipo_adjunto text, p_ruta_local text, p_nombre_original text, p_mime_type text, p_tamano_bytes bigint, p_hash_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor         uuid;
    v_adj_id        uuid;
    v_conv_id       uuid;
BEGIN
    v_actor := coalesce(
        (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')::uuid
    );
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Actor no resuelto desde JWT' USING ERRCODE = 'P0001';
    END IF;

    -- Obtener id_conversacion del mensaje
    SELECT id_conversacion INTO v_conv_id
    FROM auth.mensajes WHERE id = p_mensaje_id AND emisor_id = v_actor;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Mensaje no encontrado o no autorizado' USING ERRCODE = 'P0038';
    END IF;

    -- Validar plan: Silver+ para adjuntos
    IF NOT auth.fn_get_feature_flag(v_actor, 'mensajeria_adjuntos') THEN
        RAISE EXCEPTION 'Tu plan no incluye adjuntos en mensajes (Silver+)' USING ERRCODE = 'P0003';
    END IF;

    INSERT INTO auth.mensajes_adjuntos
        (mensaje_id, id_conversacion, tipo_adjunto, ruta_local,
         nombre_original, mime_type, tamano_bytes, hash_sha256, subido_by)
    VALUES
        (p_mensaje_id, v_conv_id, p_tipo_adjunto, p_ruta_local,
         p_nombre_original, p_mime_type, p_tamano_bytes, p_hash_sha256, v_actor)
    RETURNING id INTO v_adj_id;

    -- Actualizar tipo_contenido del mensaje
    UPDATE auth.mensajes
    SET tipo_contenido = p_tipo_adjunto,
        metadata       = metadata || jsonb_build_object('tiene_adjunto', true)
    WHERE id = p_mensaje_id;

    RETURN jsonb_build_object('ok', true, 'adjunto_id', v_adj_id);
END;
$$;


--
-- Name: fn_registrar_conversion_geo(uuid, uuid, uuid, public.geometry, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_registrar_conversion_geo(p_id_vendedor uuid, p_id_comprador uuid, p_id_orden uuid, p_geom public.geometry, p_source text DEFAULT 'geofence'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.order_geo_evidence
    (id, id_orden, id_comprador, id_vendedor, capture_source, geom, fecha_captura, metadata)
  VALUES (gen_random_uuid(), p_id_orden, p_id_comprador, p_id_vendedor,
          p_source, p_geom, now(), jsonb_build_object('tipo', 'conversion'))
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id, 'id_orden', p_id_orden, 'tipo', 'conversion');
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: fn_registrar_evento_ubicacion(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_registrar_evento_ubicacion(p_ubicacion_id uuid, p_tipo_evento text, p_id_comprador uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
BEGIN
  IF p_tipo_evento NOT IN (
    'vista_perfil','clic_mapa','ruta_iniciada','consulta_enviada','orden_generada'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'tipo_evento_invalido');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM auth.ubicaciones
    WHERE id = p_ubicacion_id AND estado = 'activo' AND fecha_eliminacion IS NULL
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ubicacion_no_encontrada_o_inactiva');
  END IF;

  INSERT INTO auth.ubicacion_analytics
    (id_ubicacion, id_usuario, tipo_evento, id_comprador, metadata)
  SELECT
    p_ubicacion_id,
    id_usuario,
    p_tipo_evento,
    p_id_comprador,
    p_metadata
  FROM auth.ubicaciones WHERE id = p_ubicacion_id;
  -- Trigger T-4 actualiza total_visitas y ultima_visita automáticamente

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: fn_registrar_visita_perfil(uuid, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_registrar_visita_perfil(p_id_vendedor uuid, p_visitor_hash text, p_fuente text DEFAULT 'direct'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
  -- FA-8: Si ya registró visita en la última hora, ignorar silenciosamente
  IF EXISTS (
    SELECT 1 FROM auth.perfil_visitas_analytics
    WHERE id_vendedor = p_id_vendedor
      AND visitor_hash = p_visitor_hash
      AND fecha >= now() - interval '1 hour'
  ) THEN
    RETURN;  -- Deduplicado, no error
  END IF;

  INSERT INTO auth.perfil_visitas_analytics
    (id_vendedor, visitor_hash, fuente, fecha)
  VALUES
    (p_id_vendedor, p_visitor_hash, p_fuente, now());
END;
$$;


--
-- Name: fn_registrar_ws_session(text, inet, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_registrar_ws_session(p_dispositivo_id text DEFAULT NULL::text, p_ip_origen inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor     uuid;
    v_channel   text;
    v_session_id uuid;
BEGIN
    v_actor := coalesce(
        (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')::uuid
    );
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Actor no resuelto desde JWT' USING ERRCODE = 'P0001';
    END IF;

    -- Canal único por usuario (el daemon escucha 'mensajes_kambalache' y enruta por id_usuario)
    v_channel := 'mensajes_kambalache';

    INSERT INTO auth.ws_sessions
        (id_usuario, channel_id, dispositivo_id, ip_origen, user_agent)
    VALUES (v_actor, v_channel, p_dispositivo_id, p_ip_origen, p_user_agent)
    ON CONFLICT (id_usuario, dispositivo_id) WHERE activa = true AND dispositivo_id IS NOT NULL
    DO UPDATE SET
        ultimo_ping_at = now(),
        ip_origen      = EXCLUDED.ip_origen,
        user_agent     = EXCLUDED.user_agent
    RETURNING id INTO v_session_id;

    -- Notificar al daemon que hay nueva sesión registrada
    PERFORM pg_notify(
        'mensajes_kambalache',
        json_build_object(
            'evento',        'sesion_registrada',
            'id_usuario',       v_actor,
            'session_id',    v_session_id,
            'dispositivo_id', p_dispositivo_id
        )::text
    );

    RETURN jsonb_build_object(
        'ok',          true,
        'session_id',  v_session_id,
        'channel',     v_channel
    );
END;
$$;


--
-- Name: fn_reportes_estadisticos_refresh(); Type: FUNCTION; Schema: auth; Owner: -
--

