--
-- Name: fn_request_claims(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_request_claims() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
declare v_claims jsonb;

begin
  begin
    v_claims := nullif(current_setting('request.jwt.claims', true), '')::jsonb;

  exception when others then v_claims := '{}'::jsonb;

  end;

  return coalesce(v_claims, '{}'::jsonb);

end;
 $$;


--
-- Name: fn_saldo_puntos_disponible(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_saldo_puntos_disponible(p_user_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
  SELECT COALESCE(
    (SELECT saldo_posterior FROM auth.movimientos_puntos
     WHERE id_usuario = p_user_id ORDER BY fecha_creacion DESC LIMIT 1),
    0
  ) - COALESCE(
    (SELECT SUM(puntos_reservados) FROM auth.escrow_puntos
     WHERE id_comprador = p_user_id AND estado = 'RESERVADO'),
    0
  );
$$;


--
-- Name: fn_slugify(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_slugify(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT trim(both '-' FROM regexp_replace(lower(coalesce(p_text, 'vendedor')), '[^a-z0-9]+', '-', 'g'));
$$;


--
-- Name: fn_slugify_text(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_slugify_text(p_input text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT COALESCE(
    NULLIF(
      regexp_replace(
        regexp_replace(
          lower(unaccent(coalesce(p_input, ''))),
          '[^a-z0-9]+', '-', 'g'
        ),
        '(^-+|-+$)', '', 'g'
      ),
      ''
    ),
    'vendedor'
  );
$_$;


--
-- Name: fn_solicitar_traduccion(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_solicitar_traduccion(p_mensaje_id uuid, p_locale_destino text DEFAULT 'en'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor   uuid;
    v_queue_id bigint;
BEGIN
    v_actor := coalesce(
        (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')::uuid
    );
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Actor no resuelto desde JWT' USING ERRCODE = 'P0001';
    END IF;

    -- Verificar participación
    IF NOT EXISTS (
        SELECT 1 FROM auth.mensajes m
        JOIN auth.conversaciones c ON c.id = m.id_conversacion
        WHERE m.id = p_mensaje_id
          AND (c.id_comprador = v_actor OR c.id_vendedor = v_actor)
    ) THEN
        RAISE EXCEPTION 'Mensaje no encontrado o no autorizado' USING ERRCODE = 'P0039';
    END IF;

    -- Si ya existe traducción, retornarla
    IF EXISTS (
        SELECT 1 FROM auth.mensajes_traducciones
        WHERE mensaje_id = p_mensaje_id AND locale_destino = p_locale_destino
    ) THEN
        RETURN jsonb_build_object(
            'ok',     true,
            'estado', 'ya_disponible',
            'texto',  (SELECT texto_traducido FROM auth.mensajes_traducciones
                       WHERE mensaje_id = p_mensaje_id AND locale_destino = p_locale_destino)
        );
    END IF;

    -- Encolar para proceso local
    INSERT INTO auth.traduccion_queue
        (mensaje_id, locale_destino, solicitado_by)
    VALUES (p_mensaje_id, p_locale_destino, v_actor)
    ON CONFLICT (mensaje_id, locale_destino) DO NOTHING
    RETURNING id INTO v_queue_id;

    -- Marcar en metadata del mensaje que traducción está pendiente
    UPDATE auth.mensajes
    SET metadata = metadata || jsonb_build_object('traduccion_lista', false)
    WHERE id = p_mensaje_id;

    -- Notify al daemon de traducción local
    PERFORM pg_notify(
        'traduccion_kambalache',
        json_build_object(
            'evento',        'nueva_solicitud',
            'mensaje_id',    p_mensaje_id,
            'locale_destino', p_locale_destino
        )::text
    );

    RETURN jsonb_build_object(
        'ok',         true,
        'estado',     'encolado',
        'queue_id',   v_queue_id
    );
END;
$$;


--
-- Name: fn_sugerir_bundles_automaticos(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_sugerir_bundles_automaticos(p_id_vendedor uuid) RETURNS TABLE(producto_a text, producto_b text, lift numeric, sugerencia text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        pa.nombre::text,
        pb.nombre::text,
        ap.lift,
        ('Bundle sugerido: "' || pa.nombre || ' + ' || pb.nombre ||
        '" (lift=' || ap.lift::text || ', frec=' || ap.frecuencia::text || ')')::text AS sugerencia
    FROM auth.afinidad_productos ap
    JOIN auth.productos pa ON pa.id = ap.producto_a_id
    JOIN auth.productos pb ON pb.id = ap.producto_b_id
    WHERE ap.id_vendedor = p_id_vendedor
      AND ap.tipo_correlacion = 'positiva'
      AND ap.lift > 1.5
      AND NOT EXISTS (
          SELECT 1 FROM auth.bundle_items bi1
          JOIN auth.bundle_items bi2 ON bi1.id_lote = bi2.id_lote
          JOIN auth.bundles_producto b ON b.id = bi1.id_lote
          WHERE b.id_vendedor = p_id_vendedor AND b.activo = true
            AND bi1.id_producto = ap.producto_a_id AND bi2.id_producto = ap.producto_b_id
      )
    ORDER BY ap.lift DESC LIMIT 10;
END;
$$;


--
-- Name: fn_sync_cerca_de_graph(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_sync_cerca_de_graph(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'ag_catalog'
    AS $$
DECLARE
  v_zonas integer; v_edges integer;
BEGIN
  LOAD 'age';
  SET LOCAL search_path = ag_catalog, public, pg_temp;
  -- limpiar subgrafo geo previo
  DELETE FROM smtp_posix_graph."NEAR";
  DELETE FROM smtp_posix_graph."SECOND_NEAR";
  DELETE FROM smtp_posix_graph."Zona";
  -- vértices Zona desde geo_zones activas
  INSERT INTO smtp_posix_graph."Zona" (properties)
  SELECT agtype_build_map('id_zona', id_zona::text, 'name', name, 'slug', slug)
    FROM public.geo_zones WHERE is_active = true AND fecha_eliminacion IS NULL;
  GET DIAGNOSTICS v_zonas = ROW_COUNT;
  -- edges NEAR entre zonas cercanas (ST_DWithin ~500m = 0.005 grados)
  INSERT INTO smtp_posix_graph."NEAR" (start_id, end_id)
  SELECT a.id, b.id
    FROM smtp_posix_graph."Zona" a
    JOIN smtp_posix_graph."Zona" b ON agtype_to_json(a.properties)->>'id_zona' < agtype_to_json(b.properties)->>'id_zona'
    JOIN public.geo_zones ga ON ga.id_zona::text = agtype_to_json(a.properties)->>'id_zona'
    JOIN public.geo_zones gb ON gb.id_zona::text = agtype_to_json(b.properties)->>'id_zona'
   WHERE ST_DWithin(ga.geom, gb.geom, 0.005);
  GET DIAGNOSTICS v_edges = ROW_COUNT;
  RETURN jsonb_build_object('zonas', v_zonas, 'edges_near', v_edges);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: fn_sync_comprado_junto_graph(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_sync_comprado_junto_graph(p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $_$
DECLARE
    v_graph_name text;
    v_rec        record;
BEGIN
    BEGIN
        SELECT name INTO v_graph_name FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;
        IF v_graph_name IS NULL THEN RETURN; END IF;

        FOR v_rec IN
            SELECT ap.producto_a_id, ap.producto_b_id,
                   ap.frecuencia, ap.lift, ap.tipo_correlacion,
                   pa.nombre AS nombre_a, pb.nombre AS nombre_b
            FROM auth.afinidad_productos ap
            JOIN auth.productos pa ON pa.id = ap.producto_a_id
            JOIN auth.productos pb ON pb.id = ap.producto_b_id
            WHERE (p_id_vendedor IS NULL OR ap.id_vendedor = p_id_vendedor)
              AND ap.tipo_correlacion IN ('positiva','negativa')
        LOOP
            -- Upsert nodos
            EXECUTE format('SELECT * FROM cypher(%L, $c$ MERGE (p:Producto {producto_id: %L}) SET p.nombre = %L $c$) AS (v agtype)',
                v_graph_name, v_rec.producto_a_id::text, v_rec.nombre_a);
            EXECUTE format('SELECT * FROM cypher(%L, $c$ MERGE (p:Producto {producto_id: %L}) SET p.nombre = %L $c$) AS (v agtype)',
                v_graph_name, v_rec.producto_b_id::text, v_rec.nombre_b);

            IF v_rec.tipo_correlacion = 'positiva' THEN
                EXECUTE format(
                    'SELECT * FROM cypher(%L, $c$ MATCH (pa:Producto {producto_id: %L}), (pb:Producto {producto_id: %L}) MERGE (pa)-[r:COMPRADO_JUNTO]-(pb) SET r.frecuencia = %s, r.lift = %s $c$) AS (v agtype)',
                    v_graph_name, v_rec.producto_a_id::text, v_rec.producto_b_id::text,
                    v_rec.frecuencia, v_rec.lift);
            ELSE
                EXECUTE format(
                    'SELECT * FROM cypher(%L, $c$ MATCH (pa:Producto {producto_id: %L}), (pb:Producto {producto_id: %L}) MERGE (pa)-[r:EXCLUYE_A]-(pb) SET r.lift = %s $c$) AS (v agtype)',
                    v_graph_name, v_rec.producto_a_id::text, v_rec.producto_b_id::text, v_rec.lift);
            END IF;
        END LOOP;

        -- Marcar outbox procesado
        UPDATE auth.afinidad_graph_outbox
        SET procesado = true, procesado_en = now()
        WHERE procesado = false
          AND (p_id_vendedor IS NULL OR id_vendedor = p_id_vendedor);

    EXCEPTION WHEN OTHERS THEN
        UPDATE auth.afinidad_graph_outbox
        SET error_msg = SQLERRM
        WHERE procesado = false AND (p_id_vendedor IS NULL OR id_vendedor = p_id_vendedor);
        RAISE WARNING 'AGE sync COMPRADO_JUNTO falló: %', SQLERRM;
    END;
END;
$_$;


--
-- Name: fn_sync_compro_en_graph_full(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_sync_compro_en_graph_full(p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_graph_name text;
    v_rec        record;
    v_count      integer := 0;
BEGIN
    BEGIN
        SELECT name INTO v_graph_name FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;
        IF v_graph_name IS NULL THEN RETURN 0; END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'AGE sync full: no disponible: %', SQLERRM;
        RETURN 0;
    END;

    -- Encolar en outbox para procesamiento asíncrono */2min
    INSERT INTO auth.clientes_graph_outbox (operacion, payload)
    SELECT
        'UPSERT_COMPRO_EN',
        jsonb_build_object(
            'id_comprador', id_comprador,
            'id_vendedor',  id_vendedor,
            'total',        total,
            'fecha',        fecha_creacion
        )
    FROM auth.ordenes
    WHERE estado = 'confirmada'
      AND (p_id_vendedor IS NULL OR id_vendedor = p_id_vendedor)
    ON CONFLICT DO NOTHING;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


