--
-- Name: fn_sync_plan_vendedor_en_perfiles(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_sync_plan_vendedor_en_perfiles() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_codigo text;
BEGIN
    SELECT pm.codigo INTO v_codigo
    FROM auth.planes_membresia pm
    WHERE pm.id = NEW.id_plan;

    UPDATE auth.perfiles_publicos_vendedor
    SET plan_vendedor = COALESCE(v_codigo, 'bronze'),
        fecha_modificacion = now()
    WHERE id_vendedor = NEW.id_vendedor;

    RETURN NEW;
END;
$$;


--
-- Name: fn_sync_segunda_vecindad_graph(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_sync_segunda_vecindad_graph(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'ag_catalog'
    AS $$
DECLARE
  v_edges integer;
BEGIN
  LOAD 'age';
  SET LOCAL search_path = ag_catalog, public, pg_temp;
  -- exige que la vecindad directa esté sincronizada
  PERFORM auth.fn_sync_cerca_de_graph(p_id_vendedor);
  DELETE FROM smtp_posix_graph."SECOND_NEAR";
  -- segunda vecindad: A-NEAR-B y B-NEAR-C => A-SECOND_NEAR-C
  INSERT INTO smtp_posix_graph."SECOND_NEAR" (start_id, end_id)
  SELECT DISTINCT e1.start_id, e2.end_id
    FROM smtp_posix_graph."NEAR" e1
    JOIN smtp_posix_graph."NEAR" e2 ON e1.end_id = e2.start_id
   WHERE e1.start_id <> e2.end_id;
  GET DIAGNOSTICS v_edges = ROW_COUNT;
  RETURN jsonb_build_object('edges_second_near', v_edges);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: fn_sync_ubicacion_punto(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_sync_ubicacion_punto() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.latitud IS NOT NULL AND NEW.longitud IS NOT NULL THEN
    NEW.punto := ST_SetSRID(ST_MakePoint(NEW.longitud, NEW.latitud), 4326)::geography;
  END IF;
  NEW.fecha_actualizacion := now();
  RETURN NEW;
END;
$$;


--
-- Name: fn_test_fa3_respuesta_sin_silver(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_test_fa3_respuesta_sin_silver() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE v_resena_id uuid;
BEGIN
    -- Precondición: vendedor Bronze sin feature flag 'respuesta_resenas'
    BEGIN
        PERFORM auth.seller_responder_resena(
            gen_random_uuid(),
            'Intento de respuesta sin Silver'
        );
        RAISE EXCEPTION 'FA-3 FAIL: debería rechazar sin Silver';
    EXCEPTION WHEN SQLSTATE 'P0003' THEN
        RAISE NOTICE 'FA-3 PASS: respuesta rechazada sin plan Silver+';
    END;
END;
$$;


--
-- Name: fn_test_fa6_riesgo_revoca_badge(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_test_fa6_riesgo_revoca_badge() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_vid  uuid := gen_random_uuid();
    v_badge_antes boolean;
    v_badge_despues boolean;
BEGIN
    -- Setup: vendedor con badge activo
    INSERT INTO auth.badge_confiable (id_vendedor, tiene_badge, calificacion, score_riesgo, total_resenas, cumple_criterio)
    VALUES (v_vid, true, 4.8, 20, 15, true)
    ON CONFLICT DO NOTHING;

    -- Simular aumento de riesgo
    INSERT INTO public.user_risk_scores (id_usuario, score, nivel_riesgo)
    VALUES (v_vid, 80, 'critico')
    ON CONFLICT (id_usuario) DO UPDATE SET score = 80, nivel_riesgo = 'critico';

    -- Trigger T-4 debería haber revocado el badge
    SELECT tiene_badge INTO v_badge_despues
    FROM auth.badge_confiable WHERE id_vendedor = v_vid;

    IF NOT COALESCE(v_badge_despues, true) THEN
        RAISE NOTICE 'FA-6 PASS: badge revocado por score > 75';
    ELSE
        RAISE NOTICE 'FA-6 INFO: badge pendiente de revisión (recalcular manualmente)';
    END IF;

    -- Cleanup
    DELETE FROM auth.badge_confiable WHERE id_vendedor = v_vid;
    DELETE FROM public.user_risk_scores WHERE id_usuario = v_vid;
END;
$$;


