--
-- Name: fn_trg_actualizar_conv_on_msg(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_actualizar_conv_on_msg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_conv   auth.conversaciones%ROWTYPE;
    v_receptor uuid;
BEGIN
    -- Verificar conversación activa
    SELECT * INTO v_conv FROM auth.conversaciones WHERE id = NEW.id_conversacion;
    IF v_conv.estado <> 'activa' THEN
        RAISE EXCEPTION 'No se puede enviar mensajes en una conversación cerrada'
            USING ERRCODE = 'P0030';
    END IF;

    -- Determinar receptor
    v_receptor := CASE
        WHEN NEW.emisor_id = v_conv.id_comprador THEN v_conv.id_vendedor
        ELSE v_conv.id_comprador
    END;

    -- Actualizar contadores y estado de lectura
    UPDATE auth.conversaciones SET
        ultimo_mensaje_at  = NEW.fecha_creacion,
        mensajes_count     = mensajes_count + 1,
        fecha_modificacion = now(),
        leido_vendedor     = CASE WHEN NEW.emisor_id = id_comprador THEN false ELSE leido_vendedor END,
        leido_comprador    = CASE WHEN NEW.emisor_id = id_vendedor  THEN false ELSE leido_comprador END
    WHERE id = NEW.id_conversacion;

    -- Notificación in-app al receptor
    INSERT INTO auth.notificaciones
        (id_usuario, tipo, titulo, cuerpo, referencia_tipo, referencia_id)
    VALUES (
        v_receptor,
        'mensaje',
        'Nuevo mensaje',
        LEFT(CASE WHEN NEW.tipo_contenido = 'texto' THEN NEW.cuerpo
                  WHEN NEW.tipo_contenido IN ('imagen','archivo') THEN '[Adjunto recibido]'
                  WHEN NEW.tipo_contenido = 'chatbot' THEN '[Respuesta automática]'
                  ELSE NEW.cuerpo END, 120),
        'conversacion',
        NEW.id_conversacion
    );

    -- CF-1: pg_notify al canal del receptor para WebSocket daemon
    -- El daemon kambalache-ws.service escucha 'mensajes_kambalache'
    -- y enruta al WebSocket del usuario por id_usuario
    PERFORM pg_notify(
        'mensajes_kambalache',
        json_build_object(
            'evento',           'nuevo_mensaje',
            'conversacion_id',  NEW.id_conversacion,
            'mensaje_id',       NEW.id,
            'emisor_id',        NEW.emisor_id,
            'receptor_id',      v_receptor,
            'tipo_contenido',   NEW.tipo_contenido,
            'preview',          LEFT(NEW.cuerpo, 80),
            'ts',               extract(epoch from NEW.fecha_creacion)
        )::text
    );

    -- CF-4: Evaluar chatbot si el mensaje es del comprador
    -- (el chatbot solo responde a compradores, no a sí mismo)
    IF NEW.emisor_id = v_conv.id_comprador
       AND NEW.tipo_contenido = 'texto'
       AND NEW.eliminado = false THEN
        PERFORM auth.fn_chatbot_evaluar_respuesta(
            NEW.id,
            NEW.id_conversacion,
            NEW.cuerpo,
            v_conv.id_vendedor
        );
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_aplicar_promo_automatica(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_aplicar_promo_automatica() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_prom   auth.promociones%ROWTYPE;
    v_desc   numeric;
    v_puntos numeric;
BEGIN
    -- Solo actuar cuando la orden pasa a 'confirmada'
    IF NEW.estado <> 'confirmada' OR OLD.estado = 'confirmada' THEN
        RETURN NEW;
    END IF;

    -- Buscar una promo automática activa del vendedor que el comprador no haya usado
    SELECT p.* INTO v_prom
    FROM auth.promociones p
    WHERE p.creado_por    = NEW.id_vendedor
      AND p.canal         = 'automatico'
      AND p.activo        = true
      AND now() BETWEEN p.fecha_inicio AND p.fecha_fin
      AND (p.max_usos IS NULL OR p.usos_actuales < p.max_usos)
      AND NOT EXISTS (
          SELECT 1 FROM auth.promociones_aplicadas pa
          WHERE pa.id_promocion = p.id AND pa.id_usuario = NEW.id_comprador
      )
    ORDER BY p.valor DESC   -- Aplicar la de mayor valor si hay varias
    LIMIT 1;

    -- Si no hay promo automática disponible, salir limpiamente
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    -- Calcular descuento
    v_desc := CASE v_prom.tipo
        WHEN 'porcentaje' THEN ROUND(NEW.total * v_prom.valor / 100, 2)
        WHEN 'monto_fijo' THEN LEAST(v_prom.valor, NEW.total)
        WHEN 'envio_gratis' THEN 0
        WHEN 'puntos'      THEN 0
        ELSE 0
    END;
    v_puntos := CASE v_prom.tipo WHEN 'puntos' THEN v_prom.puntos_otorgados ELSE 0 END;

    -- Registrar la aplicación automática
    INSERT INTO auth.promociones_aplicadas
        (id_orden, id_usuario, id_promocion, descripcion, monto_descuento, puntos_otorgados, metadata)
    VALUES (
        NEW.id, NEW.id_comprador, v_prom.id,
        v_prom.nombre || ' (Automática al confirmar)',
        v_desc, v_puntos,
        jsonb_build_object('origen', 'automatico', 'orden_total', NEW.total)
    )
    ON CONFLICT DO NOTHING;

    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_audit_conv_estado(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_audit_conv_estado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    IF OLD.estado IS DISTINCT FROM NEW.estado THEN
        INSERT INTO auth.h_vendedores_audit
            (id_usuario, operacion, datos_anteriores, datos_nuevos, modificado_por, motivo)
        VALUES (
            NEW.id_vendedor,
            'UPDATE',
            jsonb_build_object('conversacion_id', OLD.id, 'estado', OLD.estado),
            jsonb_build_object('conversacion_id', NEW.id, 'estado', NEW.estado),
            auth.uid(),
            'cambio_estado_conversacion'
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_audit_perfil_publico_vendedor(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_audit_perfil_publico_vendedor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_actor    uuid;
  v_reason   text;
  v_op       text;
BEGIN
  v_actor  := auth.current_jwt_user_id();
  v_reason := NULLIF(current_setting('app.audit_reason', true), '');

  v_op := CASE
    WHEN TG_OP = 'INSERT' THEN 'INSERT'
    WHEN TG_OP = 'UPDATE' AND OLD.activo = true AND NEW.activo = false THEN 'SUSPEND'
    ELSE 'UPDATE'
  END;

  INSERT INTO auth.h_vendedores_audit (
    id_usuario, operacion, datos_anteriores, datos_nuevos, modificado_por, motivo
  )
  VALUES (
    COALESCE(NEW.id_vendedor, OLD.id_vendedor),
    v_op,
    CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE NULL END,
    to_jsonb(NEW),
    v_actor,
    COALESCE(v_reason, CASE
      WHEN TG_OP = 'INSERT' THEN 'perfil_publico_creado'
      WHEN TG_OP = 'UPDATE' AND OLD.activo = true AND NEW.activo = false THEN 'perfil_publico_suspendido'
      ELSE 'perfil_publico_actualizado'
    END)
  );

  RETURN NEW;
END;
$$;


--
-- Name: fn_trg_audit_promocion(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_audit_promocion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    IF OLD.activo IS DISTINCT FROM NEW.activo
       OR OLD.tipo IS DISTINCT FROM NEW.tipo
       OR OLD.valor IS DISTINCT FROM NEW.valor
    THEN
        INSERT INTO auth.h_promociones_audit
            (id_promocion, actor_user_id, evento, payload_before, payload_after)
        VALUES (
            NEW.id,
            (nullif(current_setting('request.jwt.claims', true),'')::jsonb ->> 'sub')::uuid,
            CASE WHEN NOT NEW.activo AND OLD.activo THEN 'desactivada'
                 WHEN NEW.activo AND NOT OLD.activo THEN 'reactivada'
                 ELSE 'modificada' END,
            to_jsonb(OLD),
            to_jsonb(NEW)
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_audit_promocion_insert(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_audit_promocion_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    INSERT INTO auth.h_promociones_audit(id_promocion, actor_user_id, evento, payload_after)
    VALUES (NEW.id,
        (nullif(current_setting('request.jwt.claims', true),'')::jsonb ->> 'sub')::uuid,
        'creada', to_jsonb(NEW));
    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_auto_reserve_on_order_confirm(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_auto_reserve_on_order_confirm() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_item         record;
    v_ubicacion_id uuid;
BEGIN
    -- Solo actúa cuando orden pasa a 'confirmada'
    IF NEW.estado <> 'confirmada' OR OLD.estado = 'confirmada' THEN
        RETURN NEW;
    END IF;

    -- Para cada item de la orden, reservar en la ubicación con más
    -- stock disponible (acto del sistema: actor=comprador que
    -- confirmó, role='system'; independiente del JWT).
    FOR v_item IN
        SELECT oi.id_producto, oi.cantidad
        FROM auth.orden_items oi
        WHERE oi.id_orden = NEW.id
    LOOP
        SELECT iu.id_ubicacion INTO v_ubicacion_id
        FROM auth.inventario_ubicacion iu
        WHERE iu.id_vendedor = NEW.id_vendedor
          AND iu.id_producto = v_item.id_producto
          AND iu.activo = true
          AND iu.stock_disponible >= v_item.cantidad
        ORDER BY iu.stock_disponible DESC
        LIMIT 1;

        IF v_ubicacion_id IS NOT NULL THEN
            BEGIN
                PERFORM auth._reserve_for_order_internal(
                    NEW.id, v_item.id_producto, v_ubicacion_id, v_item.cantidad,
                    NEW.id_comprador, 'system'
                );
            EXCEPTION WHEN OTHERS THEN
                -- Degradación elegante: registrar el fallo respetando
                -- CHECK (cantidad <> 0): magnitud real del item, tipo
                -- system_auto_ajuste, referencia cf_reserva_automatica.
                BEGIN
                    INSERT INTO auth.movimientos_inventario(
                        id_producto, id_vendedor, id_ubicacion,
                        tipo_movimiento, cantidad, referencia_tipo, referencia_id,
                        motivo, actor_user_id, actor_role, metadata
                    )
                    VALUES (
                        v_item.id_producto, NEW.id_vendedor, v_ubicacion_id,
                        'system_auto_ajuste', v_item.cantidad, 'cf_reserva_automatica', NEW.id,
                        'CF-1: reserva automática falló — ' || SQLERRM,
                        NEW.id_comprador, 'system',
                        jsonb_build_object(
                            'error',       SQLERRM,
                            'orden_id',    NEW.id,
                            'producto_id', v_item.id_producto
                        )
                    );
                EXCEPTION WHEN OTHERS THEN
                    -- Última línea de defensa: jamás romper la
                    -- confirmación por el registro del fallo.
                    RAISE WARNING 'CF-1: reserva automática falló y el registro del fallo también (orden %, producto %): %',
                        NEW.id, v_item.id_producto, SQLERRM;
                END;
            END;
        END IF;
    END LOOP;

    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_trg_auto_reserve_on_order_confirm(); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.fn_trg_auto_reserve_on_order_confirm() IS 'Reserva automática al confirmar orden (trigger trg_auto_reserve_on_order_confirm sobre auth.ordenes). Acto del sistema: actor=NEW.id_comprador, role=system, sin depender del JWT. Fallo de reserva se registra como system_auto_ajuste/cf_reserva_automatica con cantidad real (nunca 0) o degrada a WARNING: la confirmación no se revierte.';


--
-- Name: fn_trg_badge_recalcular(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_badge_recalcular() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_avg_calif       numeric;
    v_total           integer;
    v_resenas_pos     integer;
    v_score_risk      integer;
    v_cumple          boolean;
BEGIN
    SELECT
        COALESCE(ROUND(AVG(calificacion)::numeric, 2), 0),
        COUNT(*)::integer,
        COUNT(*) FILTER (WHERE calificacion >= 4)::integer
    INTO v_avg_calif, v_total, v_resenas_pos
    FROM auth.resenas
    WHERE id_vendedor = NEW.id_vendedor
      AND verificada  = true
      AND moderada    = false;

    -- Score de riesgo: default 100 si no existe fila (máximo riesgo).
    -- Subconsulta con COALESCE: NULL solo si no hay fila, y lo cubrimos.
    v_score_risk := COALESCE(
        (SELECT score::integer FROM public.user_risk_scores
         WHERE id_usuario = NEW.id_vendedor LIMIT 1),
        100
    );

    v_cumple := (v_score_risk < 25 AND v_avg_calif > 4.5 AND v_total >= 10);

    INSERT INTO auth.badge_confiable (
        id_vendedor, tiene_badge, calificacion, score_riesgo,
        total_resenas, resenas_positivas, cumple_criterio,
        ultima_eval, otorgado_en, revocado_en
    ) VALUES (
        NEW.id_vendedor, v_cumple, v_avg_calif, v_score_risk,
        v_total, v_resenas_pos, v_cumple,
        now(),
        CASE WHEN v_cumple THEN now() ELSE NULL END,
        NULL
    )
    ON CONFLICT (id_vendedor) DO UPDATE SET
        tiene_badge       = v_cumple,
        calificacion      = v_avg_calif,
        score_riesgo      = v_score_risk,
        total_resenas     = v_total,
        resenas_positivas = v_resenas_pos,
        cumple_criterio   = v_cumple,
        ultima_eval       = now(),
        otorgado_en       = CASE
            WHEN v_cumple AND NOT COALESCE(auth.badge_confiable.tiene_badge, false)
            THEN now()
            ELSE auth.badge_confiable.otorgado_en
        END,
        revocado_en       = CASE
            WHEN NOT v_cumple AND COALESCE(auth.badge_confiable.tiene_badge, false)
            THEN now()
            ELSE auth.badge_confiable.revocado_en
        END,
        fecha_mod         = now();

    UPDATE auth.perfiles_publicos_vendedor SET
        score_reputacion           = v_avg_calif,
        total_resenas              = v_total,
        resenas_positivas          = v_resenas_pos,
        ultima_actualizacion_score = now()
    WHERE id_vendedor = NEW.id_vendedor;
    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Badge recalc falló para vendedor %: %', NEW.id_vendedor, SQLERRM;
    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_encolar_evento_orden(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_encolar_evento_orden() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_evento text;
BEGIN
    IF OLD.estado IS NOT DISTINCT FROM NEW.estado THEN
        RETURN NEW;
    END IF;

    IF NEW.estado = 'confirmada' THEN
        v_evento := 'orden_confirmada';
    ELSIF NEW.estado = 'cancelada' THEN
        v_evento := 'orden_cancelada';
    ELSE
        RETURN NEW;
    END IF;

    INSERT INTO auth.webhook_queue (evento, payload)
    VALUES (
        v_evento,
        jsonb_build_object(
            'orden_id',      NEW.id,
            'id_vendedor',   NEW.id_vendedor,
            'id_comprador',  NEW.id_comprador,
            'total',         NEW.total,
            'moneda',        NEW.moneda,
            'estado',        NEW.estado,
            'ts',            now()
        )
    );

    -- Notificación interna para kambalache-events.service
    PERFORM pg_notify(
        'webhook_kambalache',
        json_build_object('evento', v_evento, 'orden_id', NEW.id)::text
    );

    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_encolar_promo_aplicada(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_encolar_promo_aplicada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    INSERT INTO auth.webhook_queue(evento, payload, proximo_intento)
    VALUES (
        'promo_aplicada',
        jsonb_build_object(
            'aplicacion_id',  NEW.id,
            'orden_id',       NEW.id_orden,
            'id_usuario',     NEW.id_usuario,
            'promocion_id',   NEW.id_promocion,
            'monto_descuento',NEW.monto_descuento,
            'puntos_otorgados',NEW.puntos_otorgados,
            'timestamp',      now()
        ),
        now()
    );
    -- pg_notify despierta al daemon local sin llamar a externos
    PERFORM pg_notify('webhook_kambalache',
        json_build_object('tipo', 'promo_aplicada', 'id', NEW.id)::text);
    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_incrementar_usos_promo(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_incrementar_usos_promo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_usos int; v_max int;
BEGIN
    SELECT usos_actuales, max_usos INTO v_usos, v_max
    FROM auth.promociones WHERE id = NEW.id_promocion FOR UPDATE;

    IF v_max IS NOT NULL AND v_usos >= v_max THEN
        RAISE EXCEPTION 'La promoción ha alcanzado su límite de usos'
            USING ERRCODE = 'P0050';
    END IF;

    UPDATE auth.promociones
    SET usos_actuales = usos_actuales + 1
    WHERE id = NEW.id_promocion;

    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_perfil_graph_outbox(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_perfil_graph_outbox() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO auth.perfil_graph_outbox (id_vendedor, operacion, payload)
  VALUES (
    COALESCE(NEW.id_vendedor, OLD.id_vendedor),
    CASE
      WHEN TG_OP = 'DELETE' THEN 'DELETE'
      WHEN TG_OP = 'UPDATE' AND OLD.activo = true AND NEW.activo = false THEN 'SUSPEND'
      WHEN TG_OP = 'UPDATE' AND NEW.verificado = true AND (OLD.verificado IS DISTINCT FROM NEW.verificado) THEN 'VERIFY'
      ELSE 'UPSERT'
    END,
    jsonb_build_object(
      'id_usuario',         COALESCE(NEW.id_vendedor, OLD.id_vendedor),
      'slug_publico',    NEW.slug_publico,
      'nombre_marca',    NEW.nombre_marca,
      'activo',          NEW.activo,
      'verificado',      NEW.verificado,
      'badge_membresia', NEW.badge_membresia,
      'ts',              now()
    )
  );
  RETURN NEW;
END;
$$;


--
-- Name: fn_trg_prepare_perfil_publico_vendedor(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_prepare_perfil_publico_vendedor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_nombre_fallback text;
  v_slug_source     text;
BEGIN
  -- Nombre de marca con fallback
  SELECT NULLIF(btrim(concat_ws(' ', up.nombre, up.apellido)), '')
    INTO v_nombre_fallback
  FROM auth.user_profiles up
  WHERE up.id_usuario = NEW.id_vendedor;

  NEW.nombre_marca := COALESCE(NULLIF(btrim(NEW.nombre_marca), ''), v_nombre_fallback, 'Vendedor');
  NEW.metadata     := COALESCE(NEW.metadata, '{}'::jsonb);
  NEW.metricas_visibles := COALESCE(NEW.metricas_visibles, '{}'::jsonb);
  NEW.fecha_modificacion := now();

  -- Validar metadata es objeto
  IF jsonb_typeof(NEW.metadata) <> 'object' THEN
    RAISE EXCEPTION 'metadata_debe_ser_objeto_json' USING ERRCODE = '22023';
  END IF;

  -- Validar ubicacion_principal_id si se proporciona
  IF NEW.ubicacion_principal_id IS NOT NULL THEN
    PERFORM 1
    FROM auth.ubicaciones u
    WHERE u.id = NEW.ubicacion_principal_id
      AND u.id_usuario = NEW.id_vendedor
      AND u.estado = 'activo';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'ubicacion_principal_invalida'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Generar slug único
  v_slug_source := COALESCE(NULLIF(btrim(NEW.slug_publico), ''), NEW.nombre_marca);
  NEW.slug_publico := auth.fn_generate_unique_seller_slug(v_slug_source, NEW.id_vendedor);

  -- Preservar campos administrativos en UPDATE
  IF TG_OP = 'UPDATE' THEN
    NEW.activo    := OLD.activo;    -- Solo admin modifica
    NEW.verificado := OLD.verificado; -- Solo admin modifica
    NEW.verificado_at := OLD.verificado_at;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_trg_registrar_conversion_campana(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_registrar_conversion_campana() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    IF NEW.estado = 'confirmada' AND OLD.estado <> 'confirmada' THEN
        -- Marcar conversión para todas las campañas activas del vendedor
        -- donde el comprador haya recibido envío (deduplicación por UNIQUE INDEX)
        INSERT INTO auth.campana_log(id_campana, id_usuario, evento, canal, metadata)
        SELECT
            cl.id_campana,
            NEW.id_comprador,
            'convertido',
            'inapp',
            jsonb_build_object('orden_id', NEW.id, 'total', NEW.total)
        FROM auth.campana_log cl
        JOIN auth.campanas c ON c.id = cl.id_campana
        WHERE cl.id_usuario  = NEW.id_comprador
          AND cl.evento   = 'enviado'
          AND c.id_vendedor = NEW.id_vendedor
          AND c.estado    = 'activa'
          AND NOT EXISTS (
              SELECT 1 FROM auth.campana_log cl2
              WHERE cl2.id_campana = cl.id_campana
                AND cl2.id_usuario = NEW.id_comprador
                AND cl2.evento  = 'convertido'
          )
        ON CONFLICT DO NOTHING;

        -- Actualizar contador de conversiones en auth.campanas
        UPDATE auth.campanas c
        SET conversiones = conversiones + 1,
            fecha_modificacion = now()
        FROM auth.campana_log cl
        WHERE cl.id_campana = c.id
          AND cl.id_usuario    = NEW.id_comprador
          AND cl.evento     = 'convertido'
          AND c.id_vendedor = NEW.id_vendedor;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_resena_post_insert(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_resena_post_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_tiene_orden boolean;
BEGIN
    SELECT EXISTS(
        SELECT 1 FROM auth.ordenes
        WHERE id           = NEW.id_orden
          AND id_comprador = NEW.id_comprador
          AND id_vendedor  = NEW.id_vendedor
          AND estado       = 'confirmada'
    ) INTO v_tiene_orden;

    -- En AFTER INSERT no podemos modificar NEW; actualizamos la fila directamente.
    UPDATE auth.resenas SET verificada = v_tiene_orden WHERE id = NEW.id;

    IF NEW.comentario IS NOT NULL AND char_length(trim(NEW.comentario)) > 5 THEN
        INSERT INTO auth.nlp_queue (resena_id, estado)
        VALUES (NEW.id, 'pendiente')
        ON CONFLICT (resena_id) DO NOTHING;
        PERFORM pg_notify(
            'nlp_kambalache',
            json_build_object('evento','nueva_resena','resena_id', NEW.id)::text
        );
    END IF;

    INSERT INTO auth.resena_graph_outbox (resena_id, operacion, payload)
    VALUES (
        NEW.id,
        'MERGE',
        jsonb_build_object(
            'id_comprador', NEW.id_comprador,
            'id_vendedor',  NEW.id_vendedor,
            'orden_id',     NEW.id_orden,
            'calificacion', NEW.calificacion,
            'verificada',   v_tiene_orden
        )
    );
    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_risk_score_alert(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_risk_score_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_tipo_id integer;
BEGIN
    IF NEW.score > 75 AND (OLD IS NULL OR OLD.score <= 75) THEN
        BEGIN
            SELECT id INTO v_tipo_id FROM public.tipos_alerta
            WHERE nombre ILIKE '%riesgo%' LIMIT 1;
            INSERT INTO public.admin_alerts (
                tipo_alerta_id, severidad, titulo, descripcion,
                usuario_afectado_id, estado, payload
            ) VALUES (
                v_tipo_id,
                CASE WHEN NEW.score > 90 THEN 'critica' ELSE 'alta' END,
                'Vendedor con score de riesgo alto: ' || NEW.score::text,
                'Score de riesgo ' || NEW.score::text ||
                COALESCE(' (factores: ' || NEW.factores_riesgo::text || ')', ''),
                NEW.id_usuario,
                'abierta',
                jsonb_build_object(
                    'score',        NEW.score,
                    'nivel_riesgo', NEW.nivel_riesgo,
                    'factores',     NEW.factores_riesgo
                )
            );
            PERFORM auth.fn_calcular_badge_confiable(NEW.id_usuario);
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'Risk alert insert falló: %', SQLERRM;
        END;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_snapshot_orden_item(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_snapshot_orden_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    IF TG_TABLE_NAME = 'ordenes'
       AND OLD.estado IS DISTINCT FROM NEW.estado
       AND NEW.estado = 'confirmada'
    THEN
        UPDATE auth.orden_items oi
        SET
            nombre_producto_snapshot = COALESCE(p.nombre, 'Producto eliminado'),
            categoria_snapshot       = COALESCE(c.nombre, 'Sin categoría')
        FROM auth.productos p
        LEFT JOIN auth.categorias c ON c.id = p.id_categoria
        WHERE oi.id_orden     = NEW.id
          AND oi.id_producto  = p.id
          AND oi.nombre_producto_snapshot IS NULL;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_sync_badge_membresia(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_sync_badge_membresia() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_codigo text;
BEGIN
  -- FA-7: si id_plan es null o plan no existe → 'bronze' por defecto
  SELECT pm.codigo
    INTO v_codigo
  FROM auth.planes_membresia pm
  WHERE pm.id = NEW.id_plan
    AND pm.activo = true;

  -- Actualizar badge en perfil público del vendedor
  UPDATE auth.perfiles_publicos_vendedor
     SET badge_membresia = COALESCE(v_codigo, 'bronze'),
         fecha_modificacion = now()
   WHERE id_vendedor = NEW.id_vendedor;

  RETURN NEW;
END;
$$;


--
-- Name: fn_trg_sync_consulta_to_conv(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_sync_consulta_to_conv() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    IF OLD.estado IS DISTINCT FROM NEW.estado AND NEW.id_conversacion IS NOT NULL THEN
        -- Sincronizar estado_sync en consultas_escaladas
        UPDATE auth.consultas_escaladas
        SET estado_sync = CASE
                WHEN NEW.estado = 'cerrada'    THEN 'cerrado'
                WHEN NEW.estado = 'respondida' THEN 'resuelto'
                ELSE 'activo'
            END
        WHERE consulta_servicio_id = NEW.id;

        -- Notificar por pg_notify al WebSocket daemon
        PERFORM pg_notify(
            'mensajes_kambalache',
            json_build_object(
                'evento',            'consulta_actualizada',
                'consulta_id',       NEW.id,
                'conversacion_id',   NEW.id_conversacion,
                'estado_consulta',   NEW.estado
            )::text
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_trg_sync_perfil_por_cambio_ubicacion(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_trg_sync_perfil_por_cambio_ubicacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_replacement uuid;
  v_id_vendedor uuid;
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.estado = 'activo'
     AND NEW.estado <> 'activo' THEN

    -- Buscar reemplazo activo del mismo vendedor
    SELECT u2.id, u2.id_usuario
      INTO v_replacement, v_id_vendedor
    FROM auth.ubicaciones u2
    WHERE u2.id_usuario = NEW.id_usuario
      AND u2.estado = 'activo'
      AND u2.id <> NEW.id
    ORDER BY u2.es_principal DESC NULLS LAST,
             u2.fecha_actualizacion DESC NULLS LAST,
             u2.fecha_creacion DESC
    LIMIT 1;

    -- FA-4: actualizar perfil con reemplazo o null
    UPDATE auth.perfiles_publicos_vendedor pp
       SET ubicacion_principal_id = v_replacement,
           mostrar_ubicacion = CASE
             WHEN v_replacement IS NULL THEN false
             ELSE pp.mostrar_ubicacion
           END,
           fecha_modificacion = now()
     WHERE pp.id_vendedor = NEW.id_usuario
       AND pp.ubicacion_principal_id = NEW.id;

    IF FOUND THEN
      -- Log administrativo del cambio automático
      INSERT INTO auth.admin_acciones_vendedor
        (id_vendedor, id_admin, accion, motivo, metadata)
      VALUES (
        NEW.id_usuario,
        NULL,  -- sistema
        'ubicacion_principal_auto_reemplazada',
        FORMAT('Ubicacion %s quedo inactiva; reemplazada por %s',
               NEW.id::text, COALESCE(v_replacement::text, 'NULL')),
        jsonb_build_object(
          'ubicacion_anterior', NEW.id,
          'ubicacion_nueva', v_replacement,
          'mostrar_ubicacion_nuevo', v_replacement IS NOT NULL
        )
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


