--
-- Name: fn_ubicacion_principal_unica(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_ubicacion_principal_unica() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.es_principal = true THEN
    UPDATE auth.ubicaciones
    SET es_principal = false
    WHERE id_usuario = NEW.id_usuario
      AND id <> NEW.id
      AND es_principal = true
      AND fecha_eliminacion IS NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_update_producto_search_idx(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_update_producto_search_idx() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  insert into auth.productos_search_idx (id_producto, search_vec, fecha_actualizacion)
  values (
    new.id,
    setweight(to_tsvector('spanish', coalesce(new.nombre,       '')), 'A') ||
    setweight(to_tsvector('spanish', coalesce(new.descripcion,  '')), 'B'),
    now()
  )
  ON CONFLICT (id_producto) do update
  set search_vec = excluded.search_vec,
      fecha_actualizacion  = now();

  return new;

end;
 $$;


--
-- Name: fn_update_ubicacion_analytics_counter(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_update_ubicacion_analytics_counter() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE auth.ubicaciones
  SET total_visitas = total_visitas + 1,
      ultima_visita = NEW.fecha_creacion,
      fecha_actualizacion    = now()
  WHERE id = NEW.id_ubicacion;
  RETURN NEW;
END;
$$;


--
-- Name: fn_user_has_inventory_dependencies(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_user_has_inventory_dependencies(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
    SELECT
        EXISTS (SELECT 1 FROM auth.inventario_producto WHERE id_vendedor = p_user_id)
     OR EXISTS (SELECT 1 FROM auth.inventario_ubicacion WHERE id_vendedor = p_user_id)
     OR EXISTS (SELECT 1 FROM auth.movimientos_inventario WHERE id_vendedor = p_user_id)
     OR EXISTS (SELECT 1 FROM auth.alertas_inventario WHERE id_vendedor = p_user_id)
$$;


--
-- Name: fn_user_has_restrict_dependencies(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_user_has_restrict_dependencies(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN EXISTS (SELECT 1 FROM auth.ordenes WHERE id_comprador = p_user_id OR id_vendedor = p_user_id)
      OR EXISTS (SELECT 1 FROM auth.payment_transactions WHERE id_comprador = p_user_id OR id_vendedor = p_user_id)
      OR EXISTS (SELECT 1 FROM auth.envios WHERE id_comprador = p_user_id OR id_vendedor = p_user_id)
      OR EXISTS (SELECT 1 FROM auth.consultas_servicio WHERE id_comprador = p_user_id OR id_vendedor = p_user_id)
      OR EXISTS (SELECT 1 FROM auth.intercambio_negociaciones WHERE autor_user_id = p_user_id)
      OR EXISTS (SELECT 1 FROM auth.promociones WHERE creado_por = p_user_id)
      OR EXISTS (SELECT 1 FROM auth.promociones_aplicadas WHERE id_usuario = p_user_id)
      OR EXISTS (SELECT 1 FROM auth.canjes_puntos WHERE id_usuario = p_user_id);
END;
$$;


--
-- Name: fn_validar_coordenadas(double precision, double precision); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_validar_coordenadas(p_latitud double precision, p_longitud double precision) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT p_latitud  BETWEEN -90  AND 90
     AND p_longitud BETWEEN -180 AND 180;
$$;


--
-- Name: fn_validate_checkin_distance(uuid, double precision, double precision, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_validate_checkin_distance(p_id_vendedor uuid, p_lat double precision, p_lng double precision, p_max_distance_m integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_last_punto geography;
    v_distance_m double precision;
BEGIN
    SELECT punto INTO v_last_punto FROM auth.seller_checkin_log
    WHERE id_vendedor = p_id_vendedor ORDER BY fecha_creacion DESC LIMIT 1;

    IF v_last_punto IS NULL THEN
        RETURN jsonb_build_object('ok', true, 'reason', 'NO_PREVIOUS_CHECKIN');
    END IF;

    v_distance_m := ST_Distance(v_last_punto, ST_SetSRID(ST_MakePoint(p_lng, p_lat),4326)::geography);

    IF v_distance_m > p_max_distance_m THEN
        RETURN jsonb_build_object('ok', false, 'error', 'DISTANCE_TOO_LARGE', 'distance_m', v_distance_m);
    END IF;
    RETURN jsonb_build_object('ok', true, 'distance_m', v_distance_m);
END;
$$;


--
-- Name: fn_validate_seller_promo_zone(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_validate_seller_promo_zone() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'auth', 'public', 'ag_catalog', 'pg_catalog', 'extensions'
    AS $$
DECLARE
    v_area_m2 double precision;
BEGIN
    -- Validar geometría
    IF NOT ST_IsValid(NEW.poligono) THEN
        RAISE EXCEPTION 'P0200: El polígono no es geométricamente válido'
            USING ERRCODE = 'P0001';
    END IF;

    -- Validar tamaño máximo: 50,000 m² ≈ 5 hectáreas
    v_area_m2 := ST_Area(NEW.poligono::geography);
    IF v_area_m2 > 50000 THEN
        RAISE EXCEPTION 'P0201: El polígono excede el área máxima permitida (50,000 m²). Área actual: % m²',
            ROUND(v_area_m2::numeric, 0)
            USING ERRCODE = 'P0001';
    END IF;

    -- Validar que el vendedor esté activo
    IF NOT EXISTS (
        SELECT 1 FROM auth.users
        WHERE id = NEW.id_vendedor
          AND activo = true AND fecha_eliminacion IS NULL
    ) THEN
        RAISE EXCEPTION 'P0202: Vendedor inactivo o eliminado'
            USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: fn_write_merca_audit(uuid, text, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_write_merca_audit(p_id_vendedor uuid, p_accion text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog', 'pg_temp'
    AS $$
BEGIN
  -- PENDIENTE_INTROSPECCION: confirmar columnas reales de h_vendedores_audit
  -- Asumimos: actor_user_id, target_user_id, accion, metadata, fecha_creacion
  INSERT INTO auth.h_vendedores_audit (
    actor_user_id, target_user_id, accion, metadata, fecha_creacion
  ) VALUES (
    p_id_vendedor, p_id_vendedor, p_accion,
    coalesce(p_metadata, '{}'), now()
  );
EXCEPTION WHEN others THEN
  -- Si las columnas difieren, no bloquear el flujo principal
  RAISE WARNING 'fn_write_merca_audit: % — PENDIENTE_INTROSPECCION columnas h_vendedores_audit', SQLERRM;
END; $$;


