-- Name: fn_write_publicacion_audit(uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_write_publicacion_audit(p_producto_id uuid, p_evento text, p_motivo text, p_before jsonb, p_after jsonb) RETURNS void
