--
-- Name: get_current_seller_profile(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.get_current_seller_profile() RETURNS TABLE(id uuid, id_usuario uuid, nombre_negocio character varying, is_verified boolean, business_category character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    id_vendedor UUID;
BEGIN
    SELECT auth.jwt_user_id_safe() INTO id_vendedor;
    
    IF id_vendedor IS NULL THEN
        RAISE EXCEPTION 'No authenticated user';
    END IF;
    
    RETURN QUERY
    SELECT 
        p.id,
        p.id_usuario,
        p.nombre_negocio,
        p.is_verified,
        p.business_category
    FROM seller.profiles p
    WHERE p.id_usuario = id_vendedor;
END;
$$;


