--
-- Name: get_my_identity_verification_status(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.get_my_identity_verification_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_uid UUID;
    v_request auth.identity_verification_requests%ROWTYPE;
BEGIN
    v_uid := auth.current_jwt_user_id();

    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'jwt requerido';
    END IF;

    SELECT * INTO v_request
    FROM auth.identity_verification_requests
    WHERE id_usuario = v_uid
    ORDER BY requested_at DESC
    LIMIT 1;

    IF NOT FOUND AND v_request.id IS NULL THEN
        RETURN jsonb_build_object(
            'tiene_solicitud', FALSE,
            'estado', 'not_requested'
        );
    END IF;

    RETURN jsonb_build_object(
        'tiene_solicitud', TRUE,
        'id_solicitud', v_request.id,
        'id_usuario', v_request.id_usuario,
        'estado', v_request.estado,
        'tipo_documento', v_request.document_type,
        'numero_documento_enmascarado', v_request.document_number_masked,
        'notas', v_request.notes,
        'notas_revision', v_request.review_notes,
        'fecha_solicitud', v_request.requested_at,
        'fecha_resolucion', v_request.resolved_at,
        'resuelto_por', v_request.resolved_by
    );
END;
$$;


--
-- Name: FUNCTION get_my_identity_verification_status(); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.get_my_identity_verification_status() IS 'Contrato canonico CU104 para consultar el estado de verificacion propio.';


--
-- Name: get_my_profile(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.get_my_profile() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_uid UUID;
    v_user auth.users%ROWTYPE;
    v_profile auth.user_profiles%ROWTYPE;
BEGIN
    v_uid := auth.current_jwt_user_id();

    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'jwt requerido';
    END IF;

    SELECT * INTO v_user
    FROM auth.users
    WHERE id = v_uid;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'usuario no encontrado';
    END IF;

    SELECT * INTO v_profile
    FROM auth.user_profiles
    WHERE id_usuario = v_uid;

    RETURN jsonb_build_object(
        'id_usuario', v_user.id,
        'email', v_user.email,
        'nombre_usuario', v_user.username,
        'rol', v_user.role,
        'verificado', v_user.is_verified,
        'nombre', v_profile.nombre,
        'apellido', v_profile.apellido,
        'telefono', v_profile.telefono,
        'url_avatar', v_profile.url_avatar,
        'bio', v_profile.bio,
        'idioma', COALESCE(v_profile.language, 'es'),
        'zona_horaria', COALESCE(v_profile.timezone, 'America/Mexico_City'),
        'fecha_creacion', COALESCE(v_profile.fecha_creacion, v_user.fecha_creacion),
        'fecha_actualizacion', COALESCE(v_profile.fecha_actualizacion, v_user.fecha_actualizacion)
    );
END;
$$;


--
-- Name: FUNCTION get_my_profile(); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.get_my_profile() IS 'Contrato canonico CU103 para lectura de perfil propio via PostgREST RPC.';


--
-- Name: get_planes(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.get_planes() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
BEGIN
    RETURN COALESCE(
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id',             id,
                    'nombre',         nombre,
                    'puntos_minimos', puntos_minimos,
                    'multiplicador',  multiplicador,
                    'descripcion',    descripcion,
                    'beneficios',     beneficios_json,
                    'orden',          orden
                ) ORDER BY orden ASC
            )
            FROM auth.niveles_fidelidad
            WHERE activo = true
        ),
        '[]'::jsonb
    );
END;
$$;


--
-- Name: get_producto_detalle(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.get_producto_detalle(p_producto_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    resultado jsonb;
BEGIN
    SELECT jsonb_build_object(
        'id_producto', v.id_producto,
        'id_vendedor', v.id_vendedor,
        'slug_publico', v.slug_publico,
        'nombre_marca', v.nombre_marca,
        'nombre', v.nombre,
        'descripcion', v.descripcion,
        'precio', v.precio,
        'descuento_porcentaje', v.descuento_porcentaje,
        'puntos_recompensa', v.puntos_recompensa,
        'condicion', v.condicion,
        'id_categoria', v.id_categoria,
        'categoria_nombre', v.categoria_nombre,
        'subcategoria_nombre', v.subcategoria_nombre,
        'total_stock', COALESCE(v.total_stock, 0),
        'stock_reservado', COALESCE(v.stock_reservado, 0),
        'stock_disponible', COALESCE(v.stock_disponible, 0),
        'foto_portada_url', v.foto_portada_url,
        'latitud', v.latitud,
        'longitud', v.longitud,
        'fecha_creacion', v.fecha_creacion,
        'fotos', COALESCE(
            (SELECT jsonb_agg(jsonb_build_object(
                'id', gf.id,
                'url', gf.url,
                'es_portada', gf.es_portada,
                'descripcion', gf.descripcion,
                'mime_type', gf.mime_type,
                'contenido_base64', CASE WHEN gf.data_bytea IS NOT NULL
                                        THEN encode(gf.data_bytea, 'base64')
                                        ELSE NULL END
            ) ORDER BY gf.orden, gf.fecha_creacion)
             FROM auth.galeria_fotos gf
             WHERE gf.id_producto = p_producto_id
               AND gf.activo = true
               AND gf.fecha_eliminacion IS NULL),
            '[]'::jsonb)
    ) INTO resultado
    FROM auth.v_productos_publicados v
    WHERE v.id_producto = p_producto_id;

    IF resultado IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN resultado;
END;
$$;


