--
-- Name: inventory_consume_reservation(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.inventory_consume_reservation(p_orden_id uuid, p_producto_id uuid, p_ubicacion_id uuid, p_cantidad integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := auth.fn_current_user_id();
    v_order record;
    v_stock_antes integer;
    v_reservado_antes integer;
BEGIN
    SELECT id, id_vendedor INTO v_order FROM auth.ordenes WHERE id = p_orden_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Orden inexistente'; END IF;

    IF auth.fn_current_role() NOT IN ('db_admin','system')
    AND v_actor <> v_order.id_vendedor THEN
        RAISE EXCEPTION 'Sin permiso para consumir reserva' USING ERRCODE = '42501';
    END IF;

    SELECT stock, stock_reservado INTO v_stock_antes, v_reservado_antes
    FROM auth.inventario_ubicacion
    WHERE id_producto = p_producto_id AND id_ubicacion = p_ubicacion_id
    FOR UPDATE;

    IF COALESCE(v_reservado_antes, 0) < p_cantidad THEN
        RAISE EXCEPTION 'Reserva insuficiente para consumir (reservado: %, solicitado: %)',
            COALESCE(v_reservado_antes, 0), p_cantidad;
    END IF;

    -- Consumo: reduce stock físico Y reserva
    UPDATE auth.inventario_ubicacion
    SET stock = stock - p_cantidad,
        stock_reservado = stock_reservado - p_cantidad,
        fecha_modificacion = now()
    WHERE id_producto = p_producto_id AND id_ubicacion = p_ubicacion_id;

    INSERT INTO auth.movimientos_inventario(
        id_producto, id_vendedor, id_ubicacion, tipo_movimiento,
        cantidad, stock_anterior, stock_posterior,
        stock_reservado_anterior, stock_reservado_posterior,
        referencia_tipo, referencia_id, motivo, actor_user_id, actor_role
    )
    VALUES (
        p_producto_id, v_order.id_vendedor, p_ubicacion_id, 'consumo_reserva',
        -p_cantidad, v_stock_antes, v_stock_antes - p_cantidad,
        v_reservado_antes, v_reservado_antes - p_cantidad,
        'orden', p_orden_id, 'consumo por entrega de orden',
        v_actor, auth.fn_current_role()
    );

    PERFORM auth.fn_recalc_inventory_product(p_producto_id);
    PERFORM auth.fn_inventory_alert_check(p_producto_id);

    RETURN jsonb_build_object('ok', true, 'orden_id', p_orden_id, 'consumido', p_cantidad);
END;
$$;


--
-- Name: inventory_release_reservation(uuid, uuid, uuid, integer, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.inventory_release_reservation(p_orden_id uuid, p_producto_id uuid, p_ubicacion_id uuid, p_cantidad integer, p_motivo text DEFAULT 'liberación por cancelación de orden'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := auth.fn_current_user_id();
    v_order record;
BEGIN
    SELECT id, id_vendedor INTO v_order FROM auth.ordenes WHERE id = p_orden_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Orden inexistente'; END IF;

    IF auth.fn_current_role() NOT IN ('db_admin','system')
    AND v_actor NOT IN (v_order.id_vendedor) THEN
        RAISE EXCEPTION 'Sin permiso para liberar reserva' USING ERRCODE = '42501';
    END IF;

    UPDATE auth.inventario_ubicacion
    SET stock_reservado = GREATEST(0, stock_reservado - p_cantidad),
        fecha_modificacion = now()
    WHERE id_producto = p_producto_id AND id_ubicacion = p_ubicacion_id;

    INSERT INTO auth.movimientos_inventario(
        id_producto, id_vendedor, id_ubicacion, tipo_movimiento,
        cantidad, referencia_tipo, referencia_id, motivo, actor_user_id, actor_role
    )
    VALUES (
        p_producto_id, v_order.id_vendedor, p_ubicacion_id, 'liberacion_reserva',
        p_cantidad, 'orden', p_orden_id, p_motivo, v_actor, auth.fn_current_role()
    );

    PERFORM auth.fn_recalc_inventory_product(p_producto_id);
    PERFORM auth.fn_inventory_alert_check(p_producto_id);

    RETURN jsonb_build_object('ok', true, 'orden_id', p_orden_id, 'liberado', p_cantidad);
END;
$$;


--
-- Name: inventory_reserve_for_order(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.inventory_reserve_for_order(p_orden_id uuid, p_producto_id uuid, p_ubicacion_id uuid, p_cantidad integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_order       record;
    v_actor       uuid;
    v_role        text;
    v_role_audit  text;
BEGIN
    IF p_cantidad <= 0 THEN
        RAISE EXCEPTION 'Cantidad de reserva debe ser positiva [RN-023]';
    END IF;

    -- RN-024: Orden debe existir
    SELECT id, id_comprador, id_vendedor INTO v_order
    FROM auth.ordenes WHERE id = p_orden_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden inexistente [RN-024]';
    END IF;

    -- Resolución de actor robusta: fn_current_user_id() puede lanzar
    -- 'unable_to_resolve_current_user' fuera de contexto JWT (jobs,
    -- triggers de sistema). Aquí se captura y se degrada a NULL para
    -- que RN-025 decida (fail-closed), en vez de romper el flujo.
    BEGIN
        v_actor := auth.fn_current_user_id();
    EXCEPTION WHEN OTHERS THEN
        v_actor := NULL;
    END;
    v_role := auth.fn_current_role();

    -- RN-025 fail-closed: sin JWT (role 'anon', actor NULL) se
    -- rechaza explícitamente. El NOT IN original con actor NULL
    -- evaluaba a NULL (three-valued logic) y dejaba pasar el flujo.
    IF v_role NOT IN ('db_admin', 'system')
       AND (v_actor IS NULL OR v_actor NOT IN (v_order.id_comprador, v_order.id_vendedor)) THEN
        RAISE EXCEPTION 'Sin permiso sobre esta orden [RN-025]' USING ERRCODE = '42501';
    END IF;

    -- Normalizar rol de auditoría al enum de movimientos_inventario
    -- (el claim role del JWT puede ser p.ej. 'authenticated' y
    -- violaría CHECK actor_role si se insertara crudo).
    IF v_role IN ('seller', 'buyer', 'db_admin', 'system') THEN
        v_role_audit := v_role;
    ELSIF v_actor = v_order.id_vendedor THEN
        v_role_audit := 'seller';
    ELSE
        v_role_audit := 'buyer';
    END IF;

    RETURN auth._reserve_for_order_internal(
        p_orden_id, p_producto_id, p_ubicacion_id, p_cantidad,
        v_actor, v_role_audit
    );
END;
$$;


--
-- Name: FUNCTION inventory_reserve_for_order(p_orden_id uuid, p_producto_id uuid, p_ubicacion_id uuid, p_cantidad integer); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.inventory_reserve_for_order(p_orden_id uuid, p_producto_id uuid, p_ubicacion_id uuid, p_cantidad integer) IS 'RPC pública de reserva (firma intacta). RN-025 fail-closed (actor NULL sin rol autorizado → 42501), captura unable_to_resolve_current_user, normaliza actor_role al enum de auditoría y delega en _reserve_for_order_internal.';


