--
-- Name: is_seller_authenticated(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.is_seller_authenticated() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    id_vendedor UUID;
    seller_exists BOOLEAN;
BEGIN
    SELECT auth.jwt_user_id_safe() INTO id_vendedor;
    
    IF id_vendedor IS NULL THEN
        RETURN FALSE;
    END IF;
    
    SELECT EXISTS(
        SELECT 1 FROM seller.profiles 
        WHERE id_usuario = id_vendedor AND is_verified = TRUE
    ) INTO seller_exists;
    
    RETURN seller_exists;
END;
$$;


