--
-- Name: jwt_claims(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.jwt_claims() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
declare v_claims jsonb;

begin
  begin
    v_claims := nullif(current_setting('request.jwt.claims', true), '')::jsonb;

  exception when others then v_claims := '{}'::jsonb;

  end;

  return coalesce(v_claims, '{}'::jsonb);

end;

$$;


--
-- Name: jwt_user_id(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.jwt_user_id() RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  select coalesce(
    nullif(current_setting('request.jwt.claim.sub', true), '')::uuid,
    nullif((auth.jwt_claims() ->> 'sub'), '')::uuid,
    nullif((auth.jwt_claims() ->> 'user_id'), '')::uuid
  );

$$;


--
-- Name: jwt_user_id_safe(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.jwt_user_id_safe() RETURNS uuid
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE v_claims jsonb; v_user text;
BEGIN
  BEGIN
    v_claims := NULLIF(current_setting('request.jwt.claims', true), '')::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_claims := '{}'::jsonb;
  END;
  v_user := COALESCE(v_claims->>'user_id', v_claims->>'sub', NULL);
  IF v_user IS NULL OR btrim(v_user)='' THEN RETURN NULL; END IF;
  RETURN v_user::uuid;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$$;


--
-- Name: lifecycle_log_event(text, text, uuid, text, jsonb, jsonb, text, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.lifecycle_log_event(p_action text, p_severity text, p_target_user_id uuid, p_reason text, p_before jsonb, p_after jsonb, p_state_before text, p_state_after text, p_source text DEFAULT 'rpc'::text, p_error_message text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
declare
  v_actor      uuid := auth.fn_current_user_id();
  v_actor_role text := auth.current_app_role();
  v_target_role text;
  v_target_tier text;
begin
  select u.role, auth.resolve_effective_tier(u.id,now())
    into v_target_role, v_target_tier
  from auth.users u where u.id = p_target_user_id;

  insert into auth.user_lifecycle_audit(
    action,severity,actor_user_id,actor_role,target_user_id,target_role,
    target_effective_tier,reason,lifecycle_state_before,lifecycle_state_after,
    before_state,after_state,request_claims,request_id,correlation_id,source,error_message
  ) values (
    p_action, coalesce(p_severity,'info'), v_actor, v_actor_role,
    p_target_user_id, v_target_role, v_target_tier, p_reason,
    p_state_before, p_state_after, p_before, p_after, auth.jwt_claims(),
    coalesce(coalesce(nullif(current_setting('request.headers.x-request-id',true),''), nullif(current_setting('request.request_id',true),'')), nullif(current_setting('request.request_id',true),'')),
    nullif(current_setting('request.headers.x-correlation-id',true),''),
    p_source, p_error_message
  );

  insert into auth.user_lifecycle_transitions(target_user_id,previous_state,new_state,actor_user_id,reason)
  values (p_target_user_id, p_state_before, p_state_after, v_actor, p_reason);

  -- FIX: columnas canonicas NOT NULL = action, target_kind, id_objetivo (drift legacy accion/entidad)
  insert into auth.auditoria(action, target_kind, id_objetivo, actor, entidad, payload, tipo_accion, before, after, motivo, activo)
  values (p_action, 'user', p_target_user_id::text, v_actor, 'auth.users',
    jsonb_build_object('target_user_id',p_target_user_id),'USER_LIFECYCLE',p_before,p_after,p_reason,true);

  insert into auth.superset_audit_log(actor_role,tipo_evento,event_payload)
  values (coalesce(v_actor_role,'system'),p_action,
    jsonb_build_object('target_user_id',p_target_user_id,'reason',p_reason,
      'state_before',p_state_before,'state_after',p_state_after));

  if v_target_role = 'seller' then
    insert into auth.h_vendedores_audit(id_usuario,operacion,datos_anteriores,datos_nuevos,modificado_por,motivo)
    values (p_target_user_id,
      case when p_action in ('SOFT_DELETE','LEGAL_HOLD_SET') then 'SUSPEND' else 'UPDATE' end,
      p_before, p_after, v_actor, p_action||coalesce(':'||p_reason,''));
  elsif v_target_role = 'buyer' then
    insert into auth.h_usuarios_audit_compradores(id_usuario,operacion,datos_anteriores,datos_nuevos,modificado_por,motivo)
    values (p_target_user_id,'UPDATE',p_before,p_after,v_actor,p_action||coalesce(':'||p_reason,''));
  end if;
end;
$$;


--
-- Name: listar_billetera(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.listar_billetera() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_user_id  uuid := auth.current_jwt_user_id();
    v_billetera jsonb;
    v_movs      jsonb;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Autenticación requerida' USING ERRCODE = 'P0001';
    END IF;

    SELECT to_jsonb(b) INTO v_billetera
    FROM auth.billetera b
    WHERE b.id_usuario = v_user_id AND b.activo = true
    LIMIT 1;

    SELECT COALESCE(jsonb_agg(m ORDER BY m.fecha_creacion DESC), '[]'::jsonb) INTO v_movs
    FROM (
        SELECT mp.*
        FROM auth.movimientos_puntos mp
        WHERE mp.id_usuario = v_user_id
        ORDER BY mp.fecha_creacion DESC
        LIMIT 20
    ) m;

    RETURN jsonb_build_object(
        'billetera',    v_billetera,
        'movimientos',  v_movs
    );
END;
$$;


