--
-- Name: log_superset_audit_event(text, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.log_superset_audit_event(p_event_type text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_claims JSONB;
    v_actor_role TEXT;
BEGIN
    v_claims := COALESCE(current_setting('request.jwt.claims', true), '{}')::JSONB;
    v_actor_role := COALESCE(v_claims ->> 'role', current_user::TEXT);

    INSERT INTO auth.superset_audit_log (actor_role, event_type, event_payload)
    VALUES (v_actor_role, p_event_type, COALESCE(p_payload, '{}'::JSONB));
END;
$$;


--
-- Name: login_user(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.login_user(p_email text, p_password text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_user            auth.users%ROWTYPE;
    v_token           TEXT;
    v_refresh_token   TEXT;
    v_tier            TEXT;
    v_failed_count    INT;
    v_failed_ip       INT;
    v_max_attempts    INT;
    v_max_attempts_ip INT;
    v_lock_minutes     INT;
    v_lock_minutes_ip  INT;
    v_attempt         INT := 0;
    v_ip              inet;
    v_headers         jsonb;
BEGIN
    -- Validación de entrada
    IF p_email IS NULL OR trim(p_email) = '' THEN
        RAISE EXCEPTION 'email requerido';
    END IF;
    IF p_password IS NULL OR trim(p_password) = '' THEN
        RAISE EXCEPTION 'password requerido';
    END IF;

    -- Umbrales desde config_seguridad (0 hardcodeo; default si falta config)
    v_max_attempts    := auth.get_config_int('max_login_attempts', 5);
    v_max_attempts_ip := auth.get_config_int('max_login_attempts_ip', 20);
    v_lock_minutes    := GREATEST(auth.get_config_int('lockout_minutes', 15), 1);
    v_lock_minutes_ip := GREATEST(auth.get_config_int('lockout_minutes_ip', 30), 1);

    v_ip      := NULLIF(current_setting('request.headers.x-forwarded-for', true), '')::inet;
    v_headers := NULLIF(current_setting('request.headers', true), '')::jsonb;

    SELECT u.* INTO v_user
      FROM auth.users u
     WHERE lower(u.email) = lower(btrim(p_email));

    -- Gate de credencial. FIX 102-e: COALESCE explícito para password_hash NULL:
    -- un hash ausente NO puede autenticar nunca (antes: NULL <> crypt() = NULL
    -- y la rama OR no se disparaba ⇒ login válido con CUALQUIER contraseña).
    -- FIX 97 (se conserva): NOT v_user.activo rechaza cuentas soft-deleted.
    -- Mismo mensaje para no enumerar cuentas.
    IF NOT FOUND
       OR v_user.password_hash IS NULL
       OR v_user.password_hash <> crypt(p_password, v_user.password_hash)
       OR NOT v_user.is_verified
       OR NOT v_user.activo THEN
        PERFORM auth.record_login_attempt(p_email, FALSE, v_ip);
        RAISE EXCEPTION 'Usuario o contraseña incorrectos.'
            USING ERRCODE = 'P0001';
    END IF;

    -- Resolver tier efectivo (fuente única SCD2; nunca NULL → fallback default_tier_code → 'bronze')
    v_tier := auth.resolve_effective_tier(v_user.id, now());

    -- Generar JWT (incluye claim profile_tier)
    v_token := auth.generate_jwt(v_user.email, v_user.role, v_user.id, 3600, v_tier);

    -- Crear sesión con refresh_token (reintentos por colisión de unicidad)
    LOOP
        v_refresh_token := encode(gen_random_bytes(32), 'hex');
        BEGIN
            INSERT INTO auth.sesiones_tokens (
                id_usuario, token_hash, refresh_token_hash,
                expires_at, refresh_expires_at, revocado
            ) VALUES (
                v_user.id,
                encode(digest(v_token, 'sha256'), 'hex'),
                encode(digest(v_refresh_token, 'sha256'), 'hex'),
                now() + INTERVAL '1 hour',
                now() + INTERVAL '30 days',
                FALSE
            );
            EXIT;
        EXCEPTION
            WHEN unique_violation THEN
                v_attempt := v_attempt + 1;
                IF v_attempt >= 3 THEN
                    RAISE EXCEPTION 'Error al crear sesión. Intente nuevamente.'
                        USING ERRCODE = 'P0002';
                END IF;
        END;
    END LOOP;

    PERFORM auth.record_login_attempt(p_email, TRUE, v_ip);

    RETURN jsonb_build_object(
        'token',             v_token,
        'refresh_token',     v_refresh_token,
        'role',              v_user.role,
        'email',             v_user.email,
        'user_id',           v_user.id,
        'id_usuario',        v_user.id,
        'profile_tier',      v_tier,
        'token_expires_in',  3600,
        'refresh_expires_in', 2592000
    );
END;
$$;


--
-- Name: FUNCTION login_user(p_email text, p_password text); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.login_user(p_email text, p_password text) IS 'CU001 — Autentica usuario. Verifica lockout (3 intentos/15min), valida credenciales, crea sesión en sesiones_tokens y retorna JWT + refresh_token.';


--
-- Name: map_tier_plan_to_catalog(auth.tier_plan); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.map_tier_plan_to_catalog(p auth.tier_plan) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p::text
    WHEN 'BRONCE' THEN 'bronze'
    WHEN 'PLATA'  THEN 'silver'
    WHEN 'ORO'    THEN 'gold'
    ELSE 'bronze'
  END;
$$;


