--
-- Name: proponer_intercambio(uuid, uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.proponer_intercambio(p_producto_ofertado uuid, p_producto_solicitado uuid, p_mensaje text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_actor UUID;
    v_solicitante UUID;
    v_receptor UUID;
    v_intercambio_id UUID;
BEGIN
    v_actor := auth.current_jwt_user_id();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'jwt requerido para proponer intercambio';
    END IF;

    IF p_producto_ofertado IS NULL OR p_producto_solicitado IS NULL THEN
        RAISE EXCEPTION 'productos ofertado y solicitado son obligatorios';
    END IF;

    IF p_producto_ofertado = p_producto_solicitado THEN
        RAISE EXCEPTION 'los productos deben ser distintos';
    END IF;

    SELECT p.id_vendedor
    INTO v_solicitante
    FROM auth.productos p
    WHERE p.id = p_producto_ofertado
      AND p.activo = TRUE;

    IF v_solicitante IS NULL THEN
        RAISE EXCEPTION 'producto ofertado no existe o no esta activo';
    END IF;

    IF v_solicitante <> v_actor THEN
        RAISE EXCEPTION 'solo el propietario del producto ofertado puede proponer intercambio';
    END IF;

    SELECT p.id_vendedor
    INTO v_receptor
    FROM auth.productos p
    WHERE p.id = p_producto_solicitado
      AND p.activo = TRUE;

    IF v_receptor IS NULL THEN
        RAISE EXCEPTION 'producto solicitado no existe o no esta activo';
    END IF;

    IF v_receptor = v_solicitante THEN
        RAISE EXCEPTION 'el intercambio requiere productos de propietarios distintos';
    END IF;

    INSERT INTO auth.intercambios (solicitante_id, receptor_id, estado, mensaje)
    VALUES (v_solicitante, v_receptor, 'propuesta', NULLIF(BTRIM(p_mensaje), ''))
    RETURNING id INTO v_intercambio_id;

    INSERT INTO auth.intercambio_articulos (intercambio_id, producto_id, rol_en_intercambio)
    VALUES
        (v_intercambio_id, p_producto_ofertado, 'solicitante'),
        (v_intercambio_id, p_producto_solicitado, 'receptor');

    RETURN jsonb_build_object(
        'ok', TRUE,
        'intercambio_id', v_intercambio_id,
        'estado', 'propuesta',
        'solicitante_id', v_solicitante,
        'receptor_id', v_receptor,
        'producto_ofertado_id', p_producto_ofertado,
        'producto_solicitado_id', p_producto_solicitado
    );
END;
$$;


--
-- Name: public_get_planes_disponibles(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.public_get_planes_disponibles() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
BEGIN
    RETURN (
        SELECT jsonb_agg(
            jsonb_build_object(
                'codigo',          pm.codigo,
                'nombre',          pm.nombre,
                'precio_mensual',  pm.precio_mensual,
                'precio_anual',    pm.precio_anual,
                'ahorro_anual',    pm.precio_mensual * 12 - pm.precio_anual,
                'max_productos',   pm.max_productos,
                'max_ubicaciones', pm.max_ubicaciones,
                'max_promociones', pm.max_promociones,
                'tiene_analytics', pm.tiene_analytics,
                'tiene_analytics_ml', pm.tiene_analytics_ml,
                'tiene_campanas_geo', pm.tiene_campanas_geo,
                'feature_flags',   pm.feature_flags
            ) ORDER BY pm.precio_mensual ASC
        )
        FROM auth.planes_membresia pm
        WHERE pm.activo = true
    );
END;
$$;


--
-- Name: public_get_vendedores_en_zona(double precision, double precision); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.public_get_vendedores_en_zona(p_latitud double precision, p_longitud double precision) RETURNS TABLE(id_usuario uuid, nombre_marca text, slug_publico text, id_ubicacion uuid, nombre_ubicacion text, tipo text, distancia_m double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
  SELECT
    u.id,
    p.nombre_marca,
    p.slug_publico,
    loc.id,
    loc.nombre,
    loc.tipo,
    ST_Distance(
      loc.punto,
      ST_SetSRID(ST_MakePoint(p_longitud, p_latitud), 4326)::geography
    ) AS distancia_m
  FROM auth.ubicaciones loc
  JOIN auth.users u ON u.id = loc.id_usuario
  JOIN auth.perfiles_publicos_vendedor p ON p.id_vendedor = u.id
  WHERE loc.estado = 'activo'
    AND loc.fecha_eliminacion IS NULL
    AND loc.zona_cobertura IS NOT NULL
    AND ST_Within(
      ST_SetSRID(ST_MakePoint(p_longitud, p_latitud), 4326),
      loc.zona_cobertura
    )
    AND p.activo = true
    AND u.activo IS DISTINCT FROM false
  ORDER BY distancia_m ASC;
$$;


--
-- Name: purge_user_lifecycle_projection(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.purge_user_lifecycle_projection(p_target_user_id uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
begin
  delete from auth.query_graph_nodes where id_usuario=p_target_user_id;

  perform auth.ensure_age_lifecycle_labels();

  perform set_config('search_path','ag_catalog,auth,public',true);

  execute format($f$
    select * from cypher('smtp_posix_graph', $cypher$
      match (u:UserLifecycleMirror {auth_user_id: '%s'})-[r]-() delete r
    $cypher$) as (v agtype)
  $f$, p_target_user_id);

  execute format($f$
    select * from cypher('smtp_posix_graph', $cypher$
      match (u:UserLifecycleMirror {auth_user_id: '%s'}) delete u
    $cypher$) as (v agtype)
  $f$, p_target_user_id);

end;

$_$;


