--
-- Name: reactivar_usuario(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.reactivar_usuario(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_caller_role text := auth.current_jwt_role();
BEGIN
    IF v_caller_role NOT IN ('db_admin') THEN
        RAISE EXCEPTION 'Operación restringida a administradores'
            USING ERRCODE = '42501';
    END IF;

    UPDATE auth.users
    SET is_verified = true,
        fecha_actualizacion = now()
    WHERE id = p_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Usuario no encontrado: %', p_user_id
            USING ERRCODE = 'P0002';
    END IF;

    -- Registrar en auditoría
    INSERT INTO auth.logs_acceso (id_usuario, evento, ip)
    VALUES (p_user_id, 'reactivar_usuario',
            current_setting('request.headers', true)::jsonb->>'x-real-ip');

    RETURN jsonb_build_object(
        'id_usuario', p_user_id,
        'estado',  'activo',
        'mensaje', 'Usuario reactivado exitosamente'
    );
END;
$$;


--
-- Name: recomendaciones_por_grafo(uuid, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.recomendaciones_por_grafo(p_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 10) RETURNS TABLE(articulo_id uuid, nombre text, descripcion text, score numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_uid UUID := COALESCE(p_user_id, auth.current_jwt_user_id());
BEGIN
    RETURN QUERY
    WITH trusted_users AS (
        SELECT
            CASE
                WHEN i.solicitante_id = v_uid THEN i.receptor_id
                ELSE i.solicitante_id
            END AS trusted_user_id,
            COUNT(*)::NUMERIC AS trust_score
        FROM auth.intercambios i
        WHERE v_uid IN (i.solicitante_id, i.receptor_id)
          AND i.estado IN ('aceptado', 'en_negociacion', 'completado', 'activo')
        GROUP BY 1
    ), candidates AS (
        SELECT
            p.id,
            p.nombre,
            p.descripcion,
            COALESCE(tu.trust_score, 0) AS trust_score,
            EXTRACT(EPOCH FROM (NOW() - COALESCE(p.fecha_modificacion, p.fecha_creacion))) / 86400.0 AS age_days
        FROM auth.productos p
        LEFT JOIN trusted_users tu ON tu.trusted_user_id = p.id_vendedor
        WHERE p.activo = TRUE
          AND p.id_vendedor <> v_uid
    )
    SELECT
        c.id AS articulo_id,
        c.nombre,
        c.descripcion,
        ROUND((c.trust_score + GREATEST(0.0, 30.0 - c.age_days) / 30.0)::numeric, 3) AS score
    FROM candidates c
    ORDER BY score DESC, c.id
    LIMIT GREATEST(COALESCE(p_limit, 10), 1);
END;
$$;


--
-- Name: record_login_attempt(text, boolean, inet); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.record_login_attempt(p_email text, p_exitoso boolean, p_ip_origen inet DEFAULT NULL::inet) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
BEGIN
    INSERT INTO auth.login_attempts (email, ip_origen, exitoso, fecha)
    VALUES (lower(trim(p_email)), p_ip_origen, p_exitoso, now());
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'record_login_attempt: % - %', SQLERRM, p_email;
END;
$$;


--
-- Name: register_user(text, text, text, text, auth.tier_plan); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.register_user(p_email text, p_password text, p_role text DEFAULT 'buyer'::text, p_username text DEFAULT NULL::text, p_tier auth.tier_plan DEFAULT 'BRONCE'::auth.tier_plan) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_user_id UUID;
    v_otp     TEXT;
BEGIN
    IF p_role NOT IN ('buyer', 'seller', 'db_admin') THEN
        RAISE EXCEPTION 'Invalid role';
    END IF;
    IF EXISTS (SELECT 1 FROM auth.users WHERE email = p_email) THEN
        RAISE EXCEPTION 'Email already exists';
    END IF;
    v_otp := LPAD((FLOOR(RANDOM() * 1000000))::INT::TEXT, 6, '0');
    INSERT INTO auth.users (email, username, password_hash, role, is_verified, otp_code, otp_expiry, default_tier_code)
    VALUES (
        p_email,
        p_username,
        crypt(p_password, gen_salt('bf')),
        p_role,
        FALSE,
        v_otp,
        NOW() + INTERVAL '15 minutes',
        auth.map_tier_plan_to_catalog(p_tier)
    )
    RETURNING id INTO v_user_id;
    -- Encola email de confirmacion (codigo OTP) en auth.mail_queue
    PERFORM auth.enqueue_mail(
        p_email,
        'Codigo de verificacion',
        'Tu codigo OTP es: ' || v_otp,
        v_user_id
    );
    RETURN jsonb_build_object(
        'id_usuario',     v_user_id,
        'email',       p_email,
        'role',        p_role,
        'tier',        auth.map_tier_plan_to_catalog(p_tier),
        'is_verified', FALSE
    );
END;
$$;


--
-- Name: registrar_consulta_saldo_grafo(uuid, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.registrar_consulta_saldo_grafo(p_user_id uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_user_node_id BIGINT;
    v_edge_type TEXT;
BEGIN
    IF p_user_id IS NULL THEN
        RETURN;
    END IF;

    v_user_node_id := auth.ensure_query_graph_node(
        'user',
        p_user_id,
        NULL,
        NULL,
        p_user_id,
        'user:' || p_user_id::TEXT,
        '{}'::JSONB
    );

    v_edge_type := 'POINTS_BALANCE_VIEW:' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSUS');

    PERFORM auth.ensure_query_graph_edge(
        v_user_node_id,
        v_user_node_id,
        v_edge_type,
        p_user_id,
        jsonb_build_object(
            'cu', 'CU134',
            'action', 'consultar_saldo_puntos',
            'ts', NOW()
        ) || COALESCE(p_payload, '{}'::JSONB)
    );
END;
$$;


--
-- Name: registrar_evento_seguridad(text, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.registrar_evento_seguridad(p_tipo_evento text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_user_id   uuid := auth.current_jwt_user_id();
    v_ip        text;
    v_ua        text;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Autenticación requerida' USING ERRCODE = 'P0001';
    END IF;

    v_ip := COALESCE(
        p_metadata->>'ip',
        current_setting('request.headers', true)::jsonb->>'x-real-ip',
        '0.0.0.0'
    );
    v_ua := COALESCE(
        p_metadata->>'user_agent',
        current_setting('request.headers', true)::jsonb->>'user-agent',
        'unknown'
    );

    INSERT INTO auth.logs_acceso(id_usuario, evento, ip, user_agent, fecha)
    VALUES (v_user_id, p_tipo_evento, v_ip, v_ua, NOW());

    RETURN jsonb_build_object(
        'registrado',   true,
        'tipo_evento',  p_tipo_evento,
        'id_usuario',   v_user_id
    );
EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Error registrando evento: %', SQLERRM USING ERRCODE = 'P0001';
END;
$$;


--
-- Name: registrar_ubicacion_usuario(double precision, double precision); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.registrar_ubicacion_usuario(p_latitud double precision, p_longitud double precision) RETURNS TABLE(id uuid, user_id uuid, latitud double precision, longitud double precision, punto public.geography, estado text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID := auth.current_jwt_user_id();
BEGIN
    RETURN QUERY
    INSERT INTO auth.ubicaciones (id_usuario, latitud, longitud)
    VALUES (v_user_id, p_latitud, p_longitud)
    RETURNING
        auth.ubicaciones.id,
        auth.ubicaciones.id_usuario,
        auth.ubicaciones.latitud,
        auth.ubicaciones.longitud,
        auth.ubicaciones.punto,
        auth.ubicaciones.estado,
        auth.ubicaciones.fecha_creacion,
        auth.ubicaciones.fecha_actualizacion;
END;
$$;


--
-- Name: reordenar_fotos(uuid, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.reordenar_fotos(p_id_producto uuid, p_ids jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_actor UUID := auth.current_jwt_user_id();
    v_role  TEXT := auth.current_jwt_role();
    v_fila  UUID;
    i       INT  := 0;
BEGIN
    -- Solo el dueño del producto o db_admin puede reordenar
    IF v_role <> 'db_admin' THEN
        PERFORM 1 FROM auth.productos
        WHERE id = p_id_producto
          AND id_vendedor = v_actor;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'No autorizado para reordenar fotos de este producto'
                USING ERRCODE = 'insufficient_privilege';
        END IF;
    END IF;

    -- Validar que el array no sea nulo
    IF p_ids IS NULL OR jsonb_array_length(p_ids) = 0 THEN
        RETURN;
    END IF;

    -- Actualizar orden posicionalmente
    FOR i IN 0 .. jsonb_array_length(p_ids) - 1 LOOP
        v_fila := (p_ids ->> i)::UUID;
        UPDATE auth.galeria_fotos
        SET orden              = i,
            fecha_modificacion = now()
        WHERE id          = v_fila
          AND id_producto = p_id_producto;
    END LOOP;
END;
$$;


--
-- Name: request_identity_verification(jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.request_identity_verification(p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_uid UUID;
    v_role TEXT;
    v_request auth.identity_verification_requests%ROWTYPE;
    v_document_type TEXT := lower(NULLIF(trim(COALESCE(p_payload->>'documentType', p_payload->>'document_type', '')), ''));
    v_document_number_masked TEXT := NULLIF(trim(COALESCE(p_payload->>'documentNumberMasked', p_payload->>'document_number_masked', '')), '');
    v_notes TEXT := NULLIF(trim(COALESCE(p_payload->>'notes', '')), '');
BEGIN
    v_uid := auth.current_jwt_user_id();
    v_role := auth.current_jwt_role();

    IF v_uid IS NULL OR v_role IS NULL THEN
        RAISE EXCEPTION 'jwt requerido';
    END IF;

    IF v_document_type IS NULL THEN
        RAISE EXCEPTION 'documentType es requerido';
    END IF;

    IF v_document_type NOT IN ('ine', 'pasaporte', 'licencia', 'curp', 'otro') THEN
        RAISE EXCEPTION 'documentType invalido';
    END IF;

    IF v_document_number_masked IS NULL THEN
        RAISE EXCEPTION 'documentNumberMasked es requerido';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM auth.identity_verification_requests
        WHERE id_usuario = v_uid
          AND estado = 'pending'
    ) THEN
        RAISE EXCEPTION 'ya existe una solicitud pendiente';
    END IF;

    INSERT INTO auth.identity_verification_requests (
        id_usuario,
        document_type,
        document_number_masked,
        notes,
        estado
    ) VALUES (
        v_uid,
        v_document_type,
        v_document_number_masked,
        v_notes,
        'pending'
    ) RETURNING * INTO v_request;

    RETURN jsonb_build_object(
        'id_solicitud', v_request.id,
        'id_usuario', v_request.id_usuario,
        'estado', v_request.estado,
        'tipo_documento', v_request.document_type,
        'numero_documento_enmascarado', v_request.document_number_masked,
        'notas', v_request.notes,
        'notas_revision', v_request.review_notes,
        'fecha_solicitud', v_request.requested_at,
        'fecha_resolucion', v_request.resolved_at,
        'resuelto_por', v_request.resolved_by,
        'tiene_solicitud_pendiente', TRUE
    );
END;
$$;


--
-- Name: FUNCTION request_identity_verification(p_payload jsonb); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.request_identity_verification(p_payload jsonb) IS 'Contrato canonico CU104 para crear solicitud de verificacion de identidad.';


--
-- Name: request_password_reset(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.request_password_reset(p_email text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_user auth.users%ROWTYPE;
    v_otp  TEXT;
BEGIN
    -- Mantener respuesta uniforme para no filtrar existencia de cuentas
    IF p_email IS NULL OR trim(p_email) = '' THEN
        RETURN TRUE;
    END IF;

    SELECT * INTO v_user
    FROM auth.users
    WHERE email = lower(trim(p_email));

    IF NOT FOUND THEN
        RETURN TRUE;
    END IF;

    v_otp := LPAD((FLOOR(RANDOM() * 1000000))::INT::TEXT, 6, '0');

    UPDATE auth.users
    SET otp_code = v_otp,
        otp_expiry = NOW() + INTERVAL '15 minutes'
    WHERE id = v_user.id;

    -- Camino canónico CU002: insertar en password_resets para activar trigger SMTP
    INSERT INTO auth.password_resets (id_usuario, token, otp_code, expiration_date, usado)
    VALUES (
        v_user.id,
        encode(gen_random_bytes(32), 'hex'),
        v_otp,
        NOW() + INTERVAL '15 minutes',
        FALSE
    );

    RETURN TRUE;
END;
$$;


--
-- Name: FUNCTION request_password_reset(p_email text); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.request_password_reset(p_email text) IS 'CU002: Solicita recuperación de contraseña sin filtrar existencia de cuenta. Inserta OTP en users (compat) y crea registro en password_resets para activar trigger SMTP + auditoría.';


--
-- Name: resolve_effective_tier(uuid, timestamp with time zone); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.resolve_effective_tier(p_user_id uuid, p_at timestamp with time zone DEFAULT now()) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  with active_membership as (
    select m.tier_code from auth.user_service_memberships m
    where m.id_usuario=p_user_id and m.estado='active'
      and m.inicia_en<=p_at and (m.ends_at is null or m.ends_at>p_at)
    order by m.inicia_en desc limit 1
  )
  select coalesce(
    (select tier_code from active_membership),
    (select u.default_tier_code from auth.users u where u.id=p_user_id),
    'bronze'
  );

$$;


--
-- Name: resolve_identity_verification(uuid, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.resolve_identity_verification(p_user_id uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_actor_id UUID;
    v_role TEXT;
    v_status TEXT := lower(NULLIF(trim(COALESCE(p_payload->>'status', '')), ''));
    v_review_notes TEXT := NULLIF(trim(COALESCE(p_payload->>'notes', p_payload->>'reviewNotes', '')), '');
    v_request auth.identity_verification_requests%ROWTYPE;
BEGIN
    v_role := auth.current_jwt_role();
    v_actor_id := auth.current_jwt_user_id();

    IF NOT (v_role = 'db_admin' OR current_user = 'postgres') THEN
        RAISE EXCEPTION 'permiso denegado';
    END IF;

    IF p_user_id IS NULL THEN
        RAISE EXCEPTION 'p_user_id es requerido';
    END IF;

    IF v_status NOT IN ('approved', 'rejected') THEN
        RAISE EXCEPTION 'status invalido';
    END IF;

    IF current_user = 'postgres' AND v_actor_id IS NULL THEN
        SELECT id INTO v_actor_id
        FROM auth.users
        WHERE role = 'db_admin'
        ORDER BY fecha_creacion
        LIMIT 1;
    END IF;

    SELECT * INTO v_request
    FROM auth.identity_verification_requests
    WHERE id_usuario = p_user_id
      AND estado = 'pending'
    ORDER BY requested_at DESC
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'no existe solicitud pendiente para el usuario';
    END IF;

    UPDATE auth.identity_verification_requests
    SET estado = v_status,
        review_notes = v_review_notes,
        resolved_at = NOW(),
        resolved_by = v_actor_id
    WHERE id = v_request.id
    RETURNING * INTO v_request;

    RETURN jsonb_build_object(
        'id_solicitud', v_request.id,
        'id_usuario', v_request.id_usuario,
        'estado', v_request.estado,
        'tipo_documento', v_request.document_type,
        'numero_documento_enmascarado', v_request.document_number_masked,
        'notas', v_request.notes,
        'notas_revision', v_request.review_notes,
        'fecha_solicitud', v_request.requested_at,
        'fecha_resolucion', v_request.resolved_at,
        'resuelto_por', v_request.resolved_by,
        'tiene_solicitud_pendiente', FALSE
    );
END;
$$;


--
-- Name: FUNCTION resolve_identity_verification(p_user_id uuid, p_payload jsonb); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.resolve_identity_verification(p_user_id uuid, p_payload jsonb) IS 'Contrato canonico CU104 para resolver una solicitud pendiente por usuario.';


--
-- Name: responder_intercambio(uuid, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.responder_intercambio(p_intercambio_id uuid, p_decision text, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_actor UUID;
    v_role TEXT;
    v_estado_actual TEXT;
    v_estado_objetivo TEXT;
    v_solicitante UUID;
    v_receptor UUID;
BEGIN
    v_actor := auth.current_jwt_user_id();
    v_role := auth.current_jwt_role();

    IF v_actor IS NULL AND v_role <> 'db_admin' THEN
        RAISE EXCEPTION 'jwt requerido para responder intercambio';
    END IF;

    IF p_intercambio_id IS NULL THEN
        RAISE EXCEPTION 'p_intercambio_id es obligatorio';
    END IF;

    p_decision := LOWER(BTRIM(COALESCE(p_decision, '')));

    IF p_decision IN ('aceptar', 'aceptada') THEN
        v_estado_objetivo := 'aceptada';
    ELSIF p_decision IN ('rechazar', 'rechazada') THEN
        v_estado_objetivo := 'rechazada';
    ELSE
        RAISE EXCEPTION 'p_decision invalida, use aceptar o rechazar';
    END IF;

    SELECT i.estado, i.solicitante_id, i.receptor_id
    INTO v_estado_actual, v_solicitante, v_receptor
    FROM auth.intercambios i
    WHERE i.id = p_intercambio_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'intercambio no encontrado';
    END IF;

    IF v_role <> 'db_admin' AND v_actor <> v_receptor THEN
        RAISE EXCEPTION 'solo el receptor puede aceptar o rechazar la propuesta';
    END IF;

    IF v_estado_actual <> 'propuesta' THEN
        RAISE EXCEPTION 'solo propuestas en estado propuesta pueden responderse';
    END IF;

    INSERT INTO auth.h_intercambios_audit (
        intercambio_id,
        actor_user_id,
        evento,
        payload
    ) VALUES (
        p_intercambio_id,
        COALESCE(v_actor, v_receptor),
        'exchange_response_intent',
        jsonb_build_object(
            'decision', v_estado_objetivo,
            'motivo', NULLIF(BTRIM(p_motivo), ''),
            'from_estado', v_estado_actual
        )
    );

    UPDATE auth.intercambios
    SET estado = v_estado_objetivo,
        mensaje = COALESCE(NULLIF(BTRIM(p_motivo), ''), mensaje)
    WHERE id = p_intercambio_id;

    RETURN jsonb_build_object(
        'ok', TRUE,
        'intercambio_id', p_intercambio_id,
        'estado_old', v_estado_actual,
        'estado_new', v_estado_objetivo,
        'receptor_id', v_receptor,
        'solicitante_id', v_solicitante
    );
END;
$$;


--
-- Name: role(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.role() RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT auth.current_jwt_role();
$$;


--
-- Name: rpc_abrir_disputa(uuid, text, text, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.rpc_abrir_disputa(p_intercambio_id uuid, p_tipo_disputa text, p_descripcion text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_user_id     UUID;
  v_intercambio auth.intercambios%ROWTYPE;
  v_disputa_id  UUID;
BEGIN
  v_user_id := auth.current_jwt_user_id();

  SELECT * INTO v_intercambio FROM auth.intercambios WHERE id = p_intercambio_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Intercambio no encontrado' USING ERRCODE = 'P0001';
  END IF;

  IF v_intercambio.solicitante_id <> v_user_id AND v_intercambio.receptor_id <> v_user_id
     AND auth.current_jwt_role() <> 'db_admin' THEN
    RAISE EXCEPTION 'No participas en este intercambio' USING ERRCODE = '42501';
  END IF;

  IF p_descripcion IS NULL OR trim(p_descripcion) = '' THEN
    RAISE EXCEPTION 'descripcion es obligatoria' USING ERRCODE = '22023';
  END IF;

  IF p_tipo_disputa NOT IN ('no_entrega','producto_defectuoso','fraude','incumplimiento','otro') THEN
    RAISE EXCEPTION 'tipo_disputa inválido: %', p_tipo_disputa USING ERRCODE = '22023';
  END IF;

  -- Solo se puede abrir una disputa activa por intercambio (validado por UNIQUE INDEX)
  INSERT INTO auth.disputas
    (intercambio_id, id_comprador, id_vendedor, iniciada_por,
     tipo_disputa, estado, descripcion, metadata)
  VALUES (
    p_intercambio_id,
    v_intercambio.solicitante_id,
    v_intercambio.receptor_id,
    v_user_id,
    p_tipo_disputa,
    'abierta',
    p_descripcion,
    COALESCE(p_metadata,'{}')
  )
  RETURNING id INTO v_disputa_id;

  -- Marcar escrow como DISPUTADO si existe
  UPDATE auth.escrow_puntos
    SET estado = 'DISPUTADO'
    WHERE intercambio_id = p_intercambio_id AND estado = 'RESERVADO';

  RETURN jsonb_build_object(
    'disputa_id',     v_disputa_id,
    'intercambio_id', p_intercambio_id,
    'tipo_disputa',   p_tipo_disputa,
    'estado',         'abierta',
    'mensaje',        'Disputa abierta. Un árbitro revisará el caso.'
  );
END;
$$;


--
-- Name: rpc_access_token_revoked(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.rpc_access_token_revoked(p_token text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_hash TEXT;
    v_revoked BOOLEAN;
BEGIN
    IF p_token IS NULL OR length(trim(p_token)) < 20 THEN
        RETURN TRUE;
    END IF;
    v_hash := encode(digest(trim(p_token), 'sha256'), 'hex');
    SELECT s.revocado OR s.expires_at <= now()
      INTO v_revoked
      FROM auth.sesiones_tokens s
     WHERE s.token_hash = v_hash
     LIMIT 1;
    -- denylist: sin fila → no revocado (JWT admin/stateless sigue)
    RETURN COALESCE(v_revoked, FALSE);
END;
$$;


--
-- Name: rpc_activar_campania_vendedor(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.rpc_activar_campania_vendedor(p_campania_id uuid, p_accion text DEFAULT 'ACTIVAR'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_campania auth.campanias_vendedor%ROWTYPE;
  v_nuevo_estado TEXT;
BEGIN
  v_user_id := auth.current_jwt_user_id();

  SELECT * INTO v_campania FROM auth.campanias_vendedor WHERE id = p_campania_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Campana no encontrada' USING ERRCODE = 'P0001';
  END IF;

  IF v_campania.id_vendedor <> v_user_id AND auth.current_jwt_role() <> 'db_admin' THEN
    RAISE EXCEPTION 'No puedes modificar esta campana' USING ERRCODE = '42501';
  END IF;

  IF p_accion NOT IN ('ACTIVAR', 'PAUSAR', 'CANCELAR') THEN
    RAISE EXCEPTION 'accion invalida: %', p_accion USING ERRCODE = 'P0001';
  END IF;

  v_nuevo_estado := CASE p_accion
    WHEN 'ACTIVAR'   THEN 'ACTIVA'
    WHEN 'PAUSAR'    THEN 'PAUSADA'
    WHEN 'CANCELAR'  THEN 'CANCELADA'
  END;

  IF p_accion = 'ACTIVAR' AND v_campania.fecha_fin IS NOT NULL AND v_campania.fecha_fin < now() THEN
    RAISE EXCEPTION 'No se puede activar una campana con fecha_fin pasada' USING ERRCODE = '22023';
  END IF;

  UPDATE auth.campanias_vendedor
    SET estado = v_nuevo_estado, updated_at = now()
    WHERE id = p_campania_id;

  RETURN jsonb_build_object(
    'campania_id', p_campania_id,
    'estado', v_nuevo_estado,
    'accion', p_accion,
    'mensaje', 'Estado actualizado correctamente.'
  );
END;
$$;


--
-- Name: rpc_actualizar_estado_disputa(uuid, text, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.rpc_actualizar_estado_disputa(p_disputa_id uuid, p_nuevo_estado text, p_arbitro_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_disputa auth.disputas%ROWTYPE;
BEGIN
  IF auth.current_jwt_role() <> 'db_admin' THEN
    RAISE EXCEPTION 'Solo admin puede cambiar estado de disputa' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_disputa FROM auth.disputas WHERE id = p_disputa_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Disputa no encontrada' USING ERRCODE = 'P0001'; END IF;

  IF p_nuevo_estado NOT IN ('abierta','en_revision','evidencia_pendiente','escalada','resuelta','cerrada') THEN
    RAISE EXCEPTION 'Estado inválido: %', p_nuevo_estado USING ERRCODE = '22023';
  END IF;

  UPDATE auth.disputas
    SET estado = p_nuevo_estado,
        arbitro_id = COALESCE(p_arbitro_id, arbitro_id),
        updated_at = now()
    WHERE id = p_disputa_id;

  RETURN jsonb_build_object('disputa_id', p_disputa_id, 'estado', p_nuevo_estado, 'mensaje', 'Estado actualizado.');
END;
$$;


--
-- Name: rpc_admin_anonymize_user(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.rpc_admin_anonymize_user(p_user_id uuid, p_reason text DEFAULT 'retention_anonymization'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_admin_id uuid := auth.fn_current_user_id();
  v_user record;
  v_token text;
BEGIN
  IF NOT auth.fn_is_admin() THEN
    RAISE EXCEPTION 'Solo db_admin puede anonimizar usuarios' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_user FROM auth.users WHERE id = p_user_id FOR UPDATE;
  IF v_user IS NULL THEN RAISE EXCEPTION 'Usuario no encontrado' USING ERRCODE = 'P0002'; END IF;

  -- RN-023: legal_hold bloquea anonimización
  IF v_user.legal_hold THEN
    RAISE EXCEPTION 'Usuario con legal_hold activo no puede anonimizarse' USING ERRCODE = 'P0003';
  END IF;

  -- RN-024: Solo soft_deleted o purge_blocked pueden anonimizarse
  IF v_user.lifecycle_state NOT IN ('soft_deleted','purge_blocked') THEN
    RAISE EXCEPTION 'Usuario debe estar en soft_deleted o purge_blocked para anonimizarse'
      USING ERRCODE = 'P0004';
  END IF;

  v_token := replace(p_user_id::text, '-', '');

  UPDATE auth.users
  SET email = 'anon+' || v_token || '@kambalache.local',
      username = 'anon_' || left(v_token, 16),
      password_hash = 'DISABLED_ANONYMIZED_' || v_token,
      otp_code = NULL, otp_expiry = NULL,
      lifecycle_state = 'anonymized', activo = false, fecha_actualizacion = now()
  WHERE id = p_user_id;

  UPDATE auth.user_profiles
  SET nombre = NULL, apellido = NULL, phone = NULL,
      url_avatar = NULL, bio = NULL, fecha_actualizacion = now()
  WHERE id_usuario = p_user_id;

  UPDATE auth.perfiles_publicos_vendedor
  SET nombre_marca = 'Vendedor anonimizado',
      biografia = NULL, url_logo = NULL, activo = false,
      metadata = metadata || jsonb_build_object('anonymized', true, 'anonymized_at', now()),
      fecha_modificacion = now()
  WHERE id_vendedor = p_user_id;

  INSERT INTO auth.user_lifecycle_audit(id_usuario, actor_user_id, tipo_evento, before_state, after_state, reason)
  VALUES (p_user_id, v_admin_id, 'ANONYMIZE', to_jsonb(v_user),
          jsonb_build_object('lifecycle_state','anonymized'), p_reason);

  RETURN jsonb_build_object('ok', true, 'id_usuario', p_user_id, 'state', 'anonymized');
END;
$$;


--
-- Name: rpc_admin_physical_purge_user(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.rpc_admin_physical_purge_user(p_user_id uuid, p_reason text DEFAULT 'physical_purge'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_admin_id uuid := auth.fn_current_user_id();
  v_user record;
BEGIN
  IF NOT auth.fn_is_admin() THEN
    RAISE EXCEPTION 'Solo db_admin puede purgar usuarios' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_user FROM auth.users WHERE id = p_user_id FOR UPDATE;
  IF v_user IS NULL THEN RAISE EXCEPTION 'Usuario no encontrado' USING ERRCODE = 'P0002'; END IF;

  -- RN-025: legal_hold bloquea purge
  IF v_user.legal_hold THEN
    RAISE EXCEPTION 'Usuario con legal_hold activo no puede purgarse' USING ERRCODE = 'P0003';
  END IF;

  -- RN-026: elegible_purga_en debe haber vencido
  IF v_user.elegible_purga_en IS NULL OR v_user.elegible_purga_en > now() THEN
    RAISE EXCEPTION 'Usuario no elegible para purge físico (purge_eligible_at: %)',
      v_user.elegible_purga_en USING ERRCODE = 'P0004';
  END IF;

  -- RN-027: Verificar dependencias transaccionales ON DELETE RESTRICT
  IF auth.fn_user_has_restrict_dependencies(p_user_id) THEN
    UPDATE auth.users SET lifecycle_state = 'purge_blocked', fecha_actualizacion = now()
    WHERE id = p_user_id;

    INSERT INTO auth.user_lifecycle_audit(id_usuario, actor_user_id, tipo_evento, before_state, after_state, reason)
    VALUES (p_user_id, v_admin_id, 'PURGE_BLOCKED', to_jsonb(v_user),
            jsonb_build_object('has_restrict_dependencies', true), p_reason);

    RETURN jsonb_build_object('ok', false, 'state', 'purge_blocked',
                               'reason', 'Usuario tiene dependencias transaccionales activas');
  END IF;

  -- Registrar auditoría ANTES del delete (después no existe el usuario)
  INSERT INTO auth.user_lifecycle_audit(id_usuario, actor_user_id, tipo_evento, before_state, after_state, reason)
  VALUES (p_user_id, v_admin_id, 'PHYSICAL_PURGE', to_jsonb(v_user),
          jsonb_build_object('purged', true), p_reason);

  -- RN-028: Bypass del trigger defensivo solo para este contexto
  PERFORM set_config('app.allow_physical_purge', 'true', true);
  DELETE FROM auth.users WHERE id = p_user_id;
  PERFORM set_config('app.allow_physical_purge', 'false', true);

  RETURN jsonb_build_object('ok', true, 'id_usuario', p_user_id, 'state', 'purged');
END;
$$;


--
-- Name: rpc_admin_resolve_seller_activation(uuid, boolean, text, text, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.rpc_admin_resolve_seller_activation(p_request_id uuid, p_approved boolean, p_review_notes text DEFAULT NULL::text, p_initial_tier text DEFAULT 'bronze'::text, p_tier_duration_days integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_admin_id uuid := auth.fn_current_user_id();
  v_req record;
  v_user record;
  v_slug_base text;
  v_slug text;
  v_suffix integer := 0;
  v_profile record;
  v_membership jsonb;
BEGIN
  IF NOT auth.fn_is_admin() THEN
    RAISE EXCEPTION 'Solo db_admin puede resolver solicitudes de activación'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_req
  FROM auth.identity_verification_requests
  WHERE id = p_request_id FOR UPDATE;

  IF v_req IS NULL THEN
    RAISE EXCEPTION 'Solicitud no encontrada' USING ERRCODE = 'P0002';
  END IF;
  IF v_req.estado <> 'pending' THEN
    RAISE EXCEPTION 'La solicitud ya fue resuelta (estado: %)', v_req.estado USING ERRCODE = 'P0003';
  END IF;

  SELECT * INTO v_user FROM auth.users WHERE id = v_req.id_usuario FOR UPDATE;

  IF v_user.fecha_eliminacion IS NOT NULL OR v_user.lifecycle_state <> 'active' OR v_user.activo IS NOT TRUE THEN
    RAISE EXCEPTION 'Usuario no activo al momento de resolución' USING ERRCODE = 'P0004';
  END IF;

  IF p_approved IS NOT TRUE THEN
    UPDATE auth.identity_verification_requests
    SET estado = 'rejected', resolved_by = v_admin_id, resuelto_en = now(),
        review_notes = p_review_notes, fecha_actualizacion = now()
    WHERE id = p_request_id;

    INSERT INTO auth.identity_verification_audit(request_id, actor_user_id, action, before_state, after_state)
    VALUES (p_request_id, v_admin_id, 'resolved', to_jsonb(v_req), jsonb_build_object('status','rejected'));

    INSERT INTO auth.user_lifecycle_audit(id_usuario, actor_user_id, tipo_evento, before_state, after_state, reason)
    VALUES (v_req.id_usuario, v_admin_id, 'SELLER_ACTIVATION_REJECTED',
            to_jsonb(v_req), jsonb_build_object('status','rejected'), p_review_notes);

    RETURN jsonb_build_object('ok', true, 'status', 'rejected');
  END IF;

  UPDATE auth.identity_verification_requests
  SET estado = 'approved', resolved_by = v_admin_id, resuelto_en = now(),
      review_notes = p_review_notes, fecha_actualizacion = now()
  WHERE id = p_request_id;

  UPDATE auth.users
  SET role = 'seller', fecha_actualizacion = now()
  WHERE id = v_req.id_usuario;

  INSERT INTO auth.user_role_change_audit(
    target_user_id, old_role, new_role, changed_by, change_source, change_reason
  )
  VALUES (v_req.id_usuario, v_user.role, 'seller', v_admin_id, 'rpc_admin_change',
          COALESCE(p_review_notes, 'seller_activation_approved'));

  v_slug_base := auth.fn_slugify(
    COALESCE(
      (SELECT nombre || '-' || apellido FROM auth.user_profiles WHERE id_usuario = v_req.id_usuario),
      v_user.username,
      split_part(v_user.email, '@', 1),
      'vendedor'
    )
  );
  v_slug := v_slug_base;

  WHILE EXISTS (
    SELECT 1 FROM auth.perfiles_publicos_vendedor
    WHERE slug_publico = v_slug AND id_vendedor <> v_req.id_usuario
  ) LOOP
    v_suffix := v_suffix + 1;
    v_slug := v_slug_base || '-' || v_suffix::text;
  END LOOP;

  INSERT INTO auth.perfiles_publicos_vendedor(
    id_vendedor, slug_publico, nombre_marca, activo, metadata
  )
  VALUES (
    v_req.id_usuario,
    v_slug,
    COALESCE(
      (SELECT NULLIF(trim(nombre || ' ' || COALESCE(apellido,'')), '')
       FROM auth.user_profiles WHERE id_usuario = v_req.id_usuario),
      v_user.username,
      split_part(v_user.email, '@', 1)
    ),
    true,
    jsonb_build_object('seller_activation_request_id', p_request_id)
  )
  ON CONFLICT (id_vendedor) DO UPDATE SET
    activo = true,
    metadata = auth.perfiles_publicos_vendedor.metadata ||
               jsonb_build_object('seller_activation_request_id', p_request_id),
    fecha_modificacion = now()
  RETURNING * INTO v_profile;

  INSERT INTO auth.billetera(id_usuario, saldo, moneda, activo)
  VALUES (v_req.id_usuario, 0, 'Puntos', true)
  ON CONFLICT (id_usuario) DO UPDATE SET activo = true, fecha_modificacion = now();

  v_membership := auth.fn_assign_membership(
    v_req.id_usuario,
    COALESCE(p_initial_tier, 'bronze'),
    v_admin_id,
    p_tier_duration_days,
    'seller_activation'
  );

  INSERT INTO auth.identity_verification_audit(request_id, actor_user_id, action, before_state, after_state)
  VALUES (p_request_id, v_admin_id, 'resolved', to_jsonb(v_req), jsonb_build_object('status','approved'));

  INSERT INTO auth.user_lifecycle_audit(
    id_usuario, actor_user_id, tipo_evento, before_state, after_state, reason
  )
  VALUES (v_req.id_usuario, v_admin_id, 'SELLER_ACTIVATION_APPROVED', to_jsonb(v_user),
          jsonb_build_object(
            'role','seller','profile_id', v_profile.id,
            'slug', v_profile.slug_publico, 'membership', v_membership
          ),
          p_review_notes);

  INSERT INTO auth.h_vendedores_audit(
    id_usuario, operacion, datos_anteriores, datos_nuevos, modificado_por, motivo
  )
  VALUES (v_req.id_usuario, 'INSERT', jsonb_build_object('role', v_user.role),
          jsonb_build_object('role','seller','profile_id', v_profile.id,
                             'tier', COALESCE(p_initial_tier,'bronze')),
          v_admin_id, 'seller_activation');

  RETURN jsonb_build_object(
    'ok', true, 'status', 'approved',
    'id_vendedor', v_req.id_usuario,
    'profile_id', v_profile.id,
    'slug', v_profile.slug_publico,
    'membership', v_membership
  );
END;
$$;


