--
-- Name: v_productos_publicados; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_productos_publicados AS
 SELECT p.id AS id_producto,
    p.id_vendedor,
    ppv.slug_publico,
    ppv.nombre_marca,
    p.id_categoria,
    c.nombre AS categoria_nombre,
    p.id_subcategoria,
    s.nombre AS subcategoria_nombre,
    p.nombre,
    p.descripcion,
    p.precio,
    p.descuento_porcentaje,
    p.puntos_recompensa,
    p.condicion,
    inv.total_stock,
    inv.stock_reservado,
    inv.stock_disponible,
    foto_portada.url AS foto_portada_url,
    pg.latitud,
    pg.longitud,
    COALESCE(cg_agg.categorias_globales, '[]'::jsonb) AS categorias_globales,
    p.fecha_creacion,
    p.fecha_modificacion
   FROM (((((((auth.productos p
     JOIN auth.perfiles_publicos_vendedor ppv ON (((ppv.id_vendedor = p.id_vendedor) AND (ppv.activo = true))))
     JOIN auth.categorias c ON (((c.id = p.id_categoria) AND (c.activo = true) AND (c.fecha_eliminacion IS NULL))))
     LEFT JOIN auth.subcategorias s ON (((s.id = p.id_subcategoria) AND (s.activo = true) AND (s.fecha_eliminacion IS NULL))))
     LEFT JOIN auth.inventario_producto inv ON ((inv.id_producto = p.id)))
     LEFT JOIN LATERAL ( SELECT gf.url
           FROM auth.galeria_fotos gf
          WHERE ((gf.id_producto = p.id) AND (gf.activo = true) AND (gf.fecha_eliminacion IS NULL))
          ORDER BY gf.orden, gf.fecha_creacion
         LIMIT 1) foto_portada ON (true))
     LEFT JOIN auth.productos_geo pg ON ((pg.id_producto = p.id)))
     LEFT JOIN LATERAL ( SELECT jsonb_agg(jsonb_build_object('id', cg.id, 'nombre', cg.nombre, 'slug', cg.slug, 'nivel', cg.nivel) ORDER BY cg.nivel, cg.nombre) AS categorias_globales
           FROM (auth.producto_categorias_globales pcg
             JOIN auth.categorias_globales cg ON (((cg.id = pcg.categoria_global_id) AND (cg.activo = true) AND (cg.fecha_eliminacion IS NULL))))
          WHERE ((pcg.id_producto = p.id) AND (pcg.fecha_eliminacion IS NULL))) cg_agg ON (true))
  WHERE ((p.activo = true) AND (p.fecha_eliminacion IS NULL));


--
-- Name: search_public_products(text, uuid, integer, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.search_public_products(p_search_text text DEFAULT NULL::text, p_categoria_global_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS SETOF auth.v_productos_publicados
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
  select v.*
  from auth.v_productos_publicados v
  left join auth.productos_search_idx psi on psi.id_producto = v.id_producto
  where (
    p_search_text is null
    or (psi.search_vec @@ plainto_tsquery('spanish', p_search_text))
    or v.nombre        ilike '%' || p_search_text || '%'      or v.categoria_nombre ilike '%' || p_search_text || '%'
  )
    and (
      p_categoria_global_id is null
      or exists (
        select 1 from jsonb_array_elements(v.categorias_globales) e
        where (e ->> 'id')::uuid = p_categoria_global_id
      )
    )
  order by
    case when p_search_text is not null and psi.search_vec is not null
         then ts_rank(psi.search_vec, plainto_tsquery('spanish', p_search_text))
         else 0 end desc,
    v.fecha_creacion desc
  limit greatest(coalesce(p_limit, 20), 1)
  offset greatest(coalesce(p_offset, 0), 0);

$$;


--
-- Name: search_sellers_nearby(double precision, double precision, integer, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.search_sellers_nearby(p_latitud double precision, p_longitud double precision, p_radius_mts integer DEFAULT 1200, p_limit integer DEFAULT 50) RETURNS TABLE(id_vendedor uuid, slug_publico text, nombre_marca text, distancia_mts numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog', 'pg_catalog', 'extensions'
    AS $$
DECLARE
  v_actor  uuid;
  v_radius integer;
  v_lim    integer;
  v_anchor geography;
  v_count  integer := 0;
BEGIN
  v_actor  := auth.fn_current_user_id();  -- puede ser NULL (buyer anónimo)
  v_radius := GREATEST(100, LEAST(COALESCE(p_radius_mts, 1200), 10000));
  v_lim    := GREATEST(1,   LEAST(COALESCE(p_limit, 50), 200));
  v_anchor := ST_SetSRID(ST_MakePoint(p_longitud, p_latitud), 4326)::geography;

  RETURN QUERY
  WITH spots AS (
    SELECT
      u.id_usuario,
      COALESCE(u.punto,
        ST_SetSRID(ST_MakePoint(u.longitud, u.latitud), 4326)::geography) AS g
    FROM auth.ubicaciones u
    WHERE u.estado = 'activo'
  )
  SELECT
    v.id_vendedor,
    v.slug_publico,
    v.nombre_marca,
    ROUND(ST_Distance(s.g, v_anchor)::numeric, 2) AS distancia_mts
  FROM auth.v_sellers_discoverable v
  JOIN spots s ON s.id_usuario = v.id_vendedor
  WHERE ST_DWithin(s.g, v_anchor, v_radius)
  ORDER BY ST_Distance(s.g, v_anchor)
  LIMIT v_lim;

  -- Telemetría (no bloquea si falla)
  GET DIAGNOSTICS v_count = ROW_COUNT;
  BEGIN
    INSERT INTO auth.product_search_audit (id_actor, latitud, longitud, radius_mts, resultados)
    VALUES (v_actor, p_latitud, p_longitud, v_radius, v_count);
  EXCEPTION WHEN OTHERS THEN
    -- Silencioso: telemetría no debe bloquear búsqueda
    NULL;
  END;
END;
$$;


--
-- Name: seed_query_graph_nodes_after_sanity(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seed_query_graph_nodes_after_sanity() RETURNS TABLE(users_processed integer, nodes_upserted integer, use_case_nodes_upserted integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
  r_user RECORD;
  v_node_id BIGINT;
  v_uc_register INTEGER;
  v_uc_login INTEGER;
  v_uc_verify INTEGER;
  v_count_users INTEGER := 0;
  v_count_nodes INTEGER := 0;
  v_count_use_case_nodes INTEGER := 0;
BEGIN
  -- Garantizar tabla sana antes del seed.
  PERFORM auth.sanitize_query_graph_nodes();

  SELECT id INTO v_uc_register FROM auth.use_cases WHERE slug = 'register_user';
  SELECT id INTO v_uc_login FROM auth.use_cases WHERE slug = 'login_user';
  SELECT id INTO v_uc_verify FROM auth.use_cases WHERE slug = 'verify_otp';

  FOR r_user IN
    SELECT id, email, username, role, is_verified
    FROM auth.users
  LOOP
    v_count_users := v_count_users + 1;

    v_node_id := auth.ensure_query_graph_node(
      'user',
      r_user.id,
      NULL,
      NULL,
      r_user.id,
      COALESCE(r_user.username, r_user.email, 'user:' || r_user.id::TEXT),
      jsonb_build_object(
        'email', r_user.email,
        'role', r_user.role,
        'is_verified', r_user.is_verified,
        'seeded_by', 'seed_query_graph_nodes_after_sanity'
      )
    );

    IF v_node_id IS NOT NULL THEN
      v_count_nodes := v_count_nodes + 1;
    END IF;

    IF v_uc_login IS NOT NULL THEN
      PERFORM auth.ensure_query_graph_node('use_case', NULL, NULL, v_uc_login, NULL, 'login_user', '{}'::JSONB);
      v_count_use_case_nodes := v_count_use_case_nodes + 1;
    END IF;

    IF v_uc_register IS NOT NULL THEN
      PERFORM auth.ensure_query_graph_node('use_case', NULL, NULL, v_uc_register, NULL, 'register_user', '{}'::JSONB);
      v_count_use_case_nodes := v_count_use_case_nodes + 1;
    END IF;

    IF r_user.is_verified IS TRUE AND v_uc_verify IS NOT NULL THEN
      PERFORM auth.ensure_query_graph_node('use_case', NULL, NULL, v_uc_verify, NULL, 'verify_otp', '{}'::JSONB);
      v_count_use_case_nodes := v_count_use_case_nodes + 1;
    END IF;
  END LOOP;

  RETURN QUERY SELECT v_count_users, v_count_nodes, v_count_use_case_nodes;
END;
$$;


--
-- Name: seller_add_product_quick(uuid, text, text, numeric, text, uuid, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_add_product_quick(p_categoria_id uuid, p_nombre text, p_descripcion text DEFAULT NULL::text, p_precio numeric DEFAULT 0, p_condicion text DEFAULT 'buen_estado'::text, p_subcategoria_id uuid DEFAULT NULL::uuid, p_foto_url text DEFAULT NULL::text, p_foto_descripcion text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog', 'pg_catalog', 'extensions'
    AS $$
DECLARE
  v_caller  uuid;
  v_ok_cat  boolean;
  v_prod_id uuid;
  v_lat     double precision;
  v_lon     double precision;
  v_geo_ok  boolean := false;
BEGIN
  v_caller := auth.fn_current_user_id();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'JWT requerido' USING ERRCODE = 'P0001';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id=v_caller AND role='seller') THEN
    RAISE EXCEPTION 'Actor no es vendedor' USING ERRCODE = 'P0301';
  END IF;

  -- Validar categoría del vendedor
  SELECT EXISTS (
    SELECT 1 FROM auth.categorias c
    WHERE c.id = p_categoria_id AND c.id_vendedor = v_caller AND c.activo = true
  ) INTO v_ok_cat;

  IF v_ok_cat IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'Categoría inválida o no pertenece al vendedor' USING ERRCODE = 'P0400';
  END IF;

  -- Ubicación activa para geotag (no bloquea si no existe)
  SELECT u.latitud, u.longitud INTO v_lat, v_lon
  FROM auth.ubicaciones u
  WHERE u.id_usuario = v_caller AND u.estado = 'activo'
  ORDER BY u.fecha_actualizacion DESC LIMIT 1;

  -- Crear producto
  INSERT INTO auth.productos (
    id_vendedor, id_categoria, id_subcategoria,
    nombre, descripcion, precio, condicion, activo
  ) VALUES (
    v_caller, p_categoria_id, p_subcategoria_id,
    p_nombre, p_descripcion, COALESCE(p_precio, 0), p_condicion, true
  ) RETURNING id INTO v_prod_id;

  -- Auditoría creación
  INSERT INTO auth.h_productos_audit (
    id_producto, operacion, datos_anteriores, datos_nuevos, modificado_por
  ) VALUES (
    v_prod_id, 'INSERT', NULL,
    jsonb_build_object('nombre', p_nombre, 'precio', p_precio, 'categoria_id', p_categoria_id),
    v_caller
  );

  -- Foto opcional
  IF p_foto_url IS NOT NULL AND length(btrim(p_foto_url)) > 0 THEN
    INSERT INTO auth.galeria_fotos (id_producto, url, descripcion, metadata, orden, activo)
    VALUES (
      v_prod_id, p_foto_url,
      COALESCE(p_foto_descripcion, ''),
      jsonb_build_object('source', 'mobile_camera'),
      0, true
    );
  END IF;

  -- Geo: solo si hay ubicación activa
  IF v_lat IS NOT NULL AND v_lon IS NOT NULL THEN
    INSERT INTO auth.productos_geo (id_producto, id_vendedor, latitud, longitud, punto)
    VALUES (
      v_prod_id, v_caller, v_lat, v_lon,
      ST_SetSRID(ST_MakePoint(v_lon, v_lat), 4326)::geography
    )
    ON CONFLICT (id_producto) DO UPDATE
      SET latitud   = excluded.latitud,
          longitud  = excluded.longitud,
          punto     = excluded.punto,
          fecha_actualizacion = now();
    v_geo_ok := true;
  END IF;

  RETURN jsonb_build_object(
    'producto_id',   v_prod_id,
    'foto_adjunta',  (p_foto_url IS NOT NULL AND length(btrim(COALESCE(p_foto_url,''))) > 0),
    'geolocalizacion', v_geo_ok,
    'geotag', CASE WHEN v_geo_ok THEN jsonb_build_object('latitud', v_lat, 'longitud', v_lon) ELSE NULL END,
    'created_at',    now()
  );
END;
$$;


--
-- Name: seller_agregar_video_producto(uuid, text, text, text, integer, smallint); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_agregar_video_producto(p_producto_id uuid, p_url text, p_thumbnail text DEFAULT NULL::text, p_descripcion text DEFAULT NULL::text, p_duracion_seg integer DEFAULT NULL::integer, p_orden smallint DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
declare v_actor_id uuid;
 v_id uuid;

begin
  v_actor_id := auth.fn_current_user_id();

  if auth.fn_current_user_role() <> 'seller' then raise exception 'seller_role_required';
 end if;


    if not auth.fn_get_feature_flag(v_actor_id, 'videos_producto') then
    raise exception 'feature_videos_producto_requires_gold_plan';

  end if;


    if not exists (select 1 from auth.productos p where p.id = p_producto_id and p.id_vendedor = v_actor_id and p.fecha_eliminacion is null) then
    raise exception 'producto_not_found_for_seller';

  end if;


  if p_url is null or btrim(p_url) = '' then raise exception 'url_required';
 end if;


    if (select count(*) from auth.galeria_videos where id_producto = p_producto_id and activo = true and fecha_eliminacion is null) >= 3 then
    raise exception 'max_3_videos_por_producto';

  end if;


  insert into auth.galeria_videos (id_producto, url, thumbnail, descripcion, duracion_seg, orden)
  values (p_producto_id, btrim(p_url), p_thumbnail, nullif(btrim(coalesce(p_descripcion,'')), ''),
          p_duracion_seg, coalesce(p_orden, 0))
  returning id into v_id;


  return jsonb_build_object('video_id', v_id, 'producto_id', p_producto_id);

end;
 $$;


--
-- Name: seller_aprobar_pool_colaborativo(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_aprobar_pool_colaborativo(p_pool_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := auth.fn_current_user_id();
BEGIN
    PERFORM auth.fn_assert_seller_operable(v_actor);

    UPDATE auth.inventario_pool_colaborativo
    SET aprobado = true
    WHERE id = p_pool_id AND id_vendedor_propietario = v_actor;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Pool no encontrado o no eres el propietario';
    END IF;

    RETURN jsonb_build_object('ok', true, 'pool_id', p_pool_id);
END;
$$;


--
-- Name: seller_borrar_categoria(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_borrar_categoria(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.current_jwt_user_id();
  v_role  text := auth.current_jwt_role();
BEGIN
  IF v_actor IS NULL OR v_role NOT IN ('seller','db_admin') THEN
    RAISE EXCEPTION 'No autenticado como vendedor' USING ERRCODE = 'PT401';
  END IF;

  UPDATE auth.categorias
     SET activo = false,
         fecha_eliminacion = now(),
         deleted_by = v_actor,
         delete_reason = 'seller_borrar_categoria'
   WHERE id = p_id AND id_vendedor = v_actor;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Categoría no encontrada o no pertenece al vendedor actual.' USING ERRCODE = 'P0404';
  END IF;

  -- Desactivar subcategorías dependientes.
  UPDATE auth.subcategorias
     SET activo = false,
         fecha_eliminacion = now(),
         deleted_by = v_actor,
         delete_reason = 'categoria_eliminada'
   WHERE id_categoria = p_id;
END;
$$;


--
-- Name: seller_borrar_imagen(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_borrar_imagen(p_imagen_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.current_jwt_user_id();
  v_role  text := auth.current_jwt_role();
BEGIN
  IF v_actor IS NULL OR v_role NOT IN ('seller','db_admin') THEN
    RAISE EXCEPTION 'No autenticado como vendedor' USING ERRCODE = 'PT401';
  END IF;

  IF v_role <> 'db_admin' THEN
    IF NOT EXISTS (
      SELECT 1 FROM auth.galeria_fotos g
        JOIN auth.productos p ON p.id = g.id_producto
       WHERE g.id = p_imagen_id AND p.id_vendedor = v_actor
    ) THEN
      RAISE EXCEPTION 'Imagen no encontrada o no pertenece al vendedor actual.' USING ERRCODE = 'PT403';
    END IF;
  END IF;

  UPDATE auth.galeria_fotos
     SET activo = false,
         fecha_eliminacion = now(),
         deleted_by = v_actor,
         fecha_modificacion = now()
   WHERE id = p_imagen_id;
END;
$$;


--
-- Name: seller_borrar_subcategoria(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_borrar_subcategoria(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.current_jwt_user_id();
  v_role  text := auth.current_jwt_role();
BEGIN
  IF v_actor IS NULL OR v_role NOT IN ('seller','db_admin') THEN
    RAISE EXCEPTION 'No autenticado como vendedor' USING ERRCODE = 'PT401';
  END IF;

  UPDATE auth.subcategorias s
     SET activo = false,
         fecha_eliminacion = now(),
         deleted_by = v_actor,
         delete_reason = 'seller_borrar_subcategoria'
   WHERE s.id = p_id
     AND (v_role = 'db_admin' OR EXISTS (
            SELECT 1 FROM auth.categorias c
             WHERE c.id = s.id_categoria AND c.id_vendedor = v_actor
          ));

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Subcategoría no encontrada o no pertenece al vendedor actual.' USING ERRCODE = 'P0404';
  END IF;
END;
$$;


--
-- Name: seller_buscar_mensajes(text, integer, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_buscar_mensajes(p_query text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_actor uuid := auth.uid();
BEGIN
    -- Gold+ para búsqueda full-text
    IF NOT auth.fn_get_feature_flag(v_actor, 'busqueda_mensajes') THEN
        RAISE EXCEPTION 'Tu plan no incluye búsqueda en mensajes (Gold+)' USING ERRCODE = 'P0003';
    END IF;

    RETURN QUERY
    SELECT jsonb_build_object(
        'mensaje_id',      m.id,
        'conversacion_id', m.id_conversacion,
        'emisor_id',       m.emisor_id,
        'emisor_nombre',   COALESCE(up.nombre || ' ' || up.apellido, 'N/D'),
        'cuerpo',          m.cuerpo,
        'similitud',       similarity(m.cuerpo, p_query),
        'fecha',           m.fecha_creacion,
        'id_comprador',    c.id_comprador,
        'asunto',          c.asunto
    )
    FROM auth.mensajes m
    JOIN auth.conversaciones c ON c.id = m.id_conversacion
    LEFT JOIN auth.user_profiles up ON up.id_usuario = m.emisor_id
    WHERE c.id_vendedor = v_actor
      AND m.eliminado = false
      AND m.cuerpo % p_query   -- operador pg_trgm similarity
    ORDER BY similarity(m.cuerpo, p_query) DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: seller_cancelar_membresia(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_cancelar_membresia(p_motivo text DEFAULT 'Cancelado por vendedor'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid;
    v_rows  integer;
BEGIN
    v_actor := auth.fn_current_user_id();

    UPDATE auth.membresias_vendedor
    SET estado       = 'cancelada',
        auto_renovar = false
    WHERE id_vendedor = v_actor
      AND estado IN ('activo', 'grace_period')
      AND fecha_eliminacion IS NULL;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        RAISE EXCEPTION 'sin_membresia_activa_para_cancelar' USING ERRCODE = 'P0001';
    END IF;

    RETURN jsonb_build_object('cancelado', true, 'motivo', p_motivo);
END;
$$;


--
-- Name: seller_cancelar_transferencia_programada(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_cancelar_transferencia_programada(p_tp_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor_id uuid;
    v_tp       record;
BEGIN
    v_actor_id := auth.fn_current_user_id();

    SELECT * INTO v_tp FROM auth.transferencias_programadas
    WHERE id = p_tp_id AND id_usuario_origen = v_actor_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'no_encontrada', 'codigo', 'WALLET_072');
    END IF;

    IF v_tp.estado <> 'pendiente' THEN
        RETURN jsonb_build_object(
            'error',  'no_cancelable', 'codigo', 'WALLET_073',
            'estado_actual', v_tp.estado
        );
    END IF;

    UPDATE auth.transferencias_programadas
    SET estado = 'cancelada'
    WHERE id = p_tp_id;

    RETURN jsonb_build_object('cancelada', true, 'id', p_tp_id);
END;
$$;


--
-- Name: seller_carga_rapida_producto(text, numeric, uuid, text, text, text, uuid, boolean, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_carga_rapida_producto(p_nombre text, p_precio numeric, p_id_categoria uuid, p_condicion text DEFAULT 'nuevo'::text, p_descripcion text DEFAULT NULL::text, p_storage_path text DEFAULT NULL::text, p_ubicacion_id uuid DEFAULT NULL::uuid, p_como_borrador boolean DEFAULT false, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_actor   uuid;
  v_ub_id   uuid;
  v_prod_id uuid;
  v_foto_id uuid;
BEGIN
  -- V2: fn_current_user_id() canónico
  v_actor := COALESCE(p_user_id, auth.fn_current_user_id());
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Actor no resuelto' USING ERRCODE='P0001'; END IF;

  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id=v_actor AND role='seller'
      AND is_verified=true AND activo=true AND fecha_eliminacion IS NULL) THEN
    RAISE EXCEPTION 'Cuenta inactiva o no autorizada' USING ERRCODE='P0002';
  END IF;

  -- FA-2: Validaciones de parámetros
  IF trim(COALESCE(p_nombre,'')) = '' THEN
    RAISE EXCEPTION 'Nombre de producto requerido' USING ERRCODE='P0003';
  END IF;
  IF p_precio < 0 THEN
    RAISE EXCEPTION 'Precio no puede ser negativo' USING ERRCODE='P0004';
  END IF;
  IF p_condicion NOT IN ('nuevo','como_nuevo','buen_estado','regular','requiere_reparacion') THEN
    RAISE EXCEPTION 'Condición inválida: %', p_condicion USING ERRCODE='P0005';
  END IF;

  -- Resolver ubicación
  IF p_ubicacion_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM auth.ubicaciones
        WHERE id=p_ubicacion_id AND id_usuario=v_actor AND estado='activo') THEN
      RAISE EXCEPTION 'Ubicación inválida' USING ERRCODE='P0006';
    END IF;
    v_ub_id := p_ubicacion_id;
  ELSE
    SELECT ubicacion_activa_id INTO v_ub_id
    FROM auth.perfiles_publicos_vendedor WHERE id_vendedor=v_actor AND activo=true;
    IF v_ub_id IS NULL THEN
      SELECT id INTO v_ub_id FROM auth.ubicaciones
      WHERE id_usuario=v_actor AND estado='activo' AND es_principal=true LIMIT 1;
    END IF;
  END IF;

  INSERT INTO auth.productos(
    id_vendedor,id_categoria,nombre,descripcion,precio,condicion,
    activo,borrador,ubicacion_carga_id,origen_carga,fecha_creacion,fecha_modificacion)
  VALUES (
    v_actor,p_id_categoria,trim(p_nombre),p_descripcion,p_precio,p_condicion,
    NOT p_como_borrador,p_como_borrador,v_ub_id,'movil',now(),now())
  RETURNING id INTO v_prod_id;

  IF p_storage_path IS NOT NULL THEN
    INSERT INTO auth.galeria_fotos(id_producto,url_foto,storage_path,es_portada,orden)
    VALUES (v_prod_id,p_storage_path,p_storage_path,true,1)
    RETURNING id INTO v_foto_id;
  END IF;

  -- Inventario inicial (FA-4: falla silenciosa)
  IF v_ub_id IS NOT NULL THEN
    BEGIN
      INSERT INTO auth.inventario_ubicacion(id_producto,id_ubicacion,stock,stock_minimo)
      VALUES (v_prod_id,v_ub_id,1,0)
      ON CONFLICT (id_producto,id_ubicacion) DO NOTHING;
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  -- Auditoría real con h_productos_audit
  INSERT INTO auth.h_productos_audit(id_producto,operacion,datos_nuevos,modificado_por,motivo)
  VALUES (v_prod_id,'INSERT',
    jsonb_build_object('nombre',p_nombre,'precio',p_precio,'origen','movil','borrador',p_como_borrador),
    v_actor,'Carga rápida móvil');

  RETURN jsonb_build_object(
    'producto_id',v_prod_id,'foto_id',v_foto_id,
    'ubicacion_id',v_ub_id,'borrador',p_como_borrador,'timestamp',now());
END;
$$;


--
-- Name: seller_check_in(double precision, double precision); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_check_in(p_latitud double precision, p_longitud double precision) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog', 'pg_catalog', 'extensions'
    AS $$
DECLARE
  v_caller  uuid;
  v_role    text;
  v_new_id  uuid;
  v_punto   geography;
BEGIN
  v_caller := auth.fn_current_user_id();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'JWT requerido' USING ERRCODE = 'P0001';
  END IF;

  SELECT role INTO v_role FROM auth.users WHERE id = v_caller;
  IF NOT FOUND OR v_role IS DISTINCT FROM 'seller' THEN
    RAISE EXCEPTION 'Usuario no es vendedor o no existe' USING ERRCODE = 'P0301';
  END IF;

  IF p_latitud NOT BETWEEN -90 AND 90 OR p_longitud NOT BETWEEN -180 AND 180 THEN
    RAISE EXCEPTION 'Coordenadas inválidas' USING ERRCODE = 'P0302';
  END IF;

  v_punto := ST_SetSRID(ST_MakePoint(p_longitud, p_latitud), 4326)::geography;

  -- Desactivar ubicaciones previas (idempotente)
  UPDATE auth.ubicaciones
  SET estado    = 'inactivo',
      fecha_actualizacion = now()
  WHERE id_usuario = v_caller
    AND estado  = 'activo';

  -- Insertar nueva ubicación activa con punto geography
  INSERT INTO auth.ubicaciones (id_usuario, latitud, longitud, punto, estado)
  VALUES (v_caller, p_latitud, p_longitud, v_punto, 'activo')
  RETURNING id INTO v_new_id;

  -- Log inmutable de check-in
  INSERT INTO auth.checkins_vendedor (id_usuario, latitud, longitud)
  VALUES (v_caller, p_latitud, p_longitud);

  RETURN jsonb_build_object(
    'ubicacion_id', v_new_id,
    'latitud',      p_latitud,
    'longitud',     p_longitud,
    'estado',       'activo',
    'checked_in_at', now()
  );
END;
$$;


--
-- Name: seller_checkin(double precision, double precision, real, uuid, text, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_checkin(p_latitud double precision, p_longitud double precision, p_precision_metros real DEFAULT NULL::real, p_ubicacion_id uuid DEFAULT NULL::uuid, p_dispositivo_id text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_actor      uuid;
  v_ub_id      uuid;
  v_punto      geography;
  v_checkin_id uuid;
  v_result     jsonb;
BEGIN
  -- V2: fn_current_user_id() canónico
  v_actor := COALESCE(p_user_id, auth.fn_current_user_id());
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Actor no resuelto' USING ERRCODE='P0001'; END IF;

  -- FA-2: Coordenadas inválidas
  IF p_latitud NOT BETWEEN -90 AND 90 OR p_longitud NOT BETWEEN -180 AND 180 THEN
    RAISE EXCEPTION 'Coordenadas inválidas: lat=%, lon=%', p_latitud, p_longitud USING ERRCODE='P0002';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id=v_actor AND role='seller'
      AND is_verified=true AND activo=true AND fecha_eliminacion IS NULL) THEN
    RAISE EXCEPTION 'Cuenta inactiva o no autorizada' USING ERRCODE='P0003';
  END IF;

  v_punto := ST_SetSRID(ST_MakePoint(p_longitud, p_latitud), 4326)::geography;

  IF p_ubicacion_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM auth.ubicaciones
        WHERE id=p_ubicacion_id AND id_usuario=v_actor AND estado='activo') THEN
      RAISE EXCEPTION 'Ubicación no válida para este vendedor' USING ERRCODE='P0004';
    END IF;
    v_ub_id := p_ubicacion_id;
  ELSE
    SELECT id INTO v_ub_id FROM auth.ubicaciones
    WHERE id_usuario=v_actor AND estado='activo'
    ORDER BY ST_Distance(punto, v_punto) ASC NULLS LAST, es_principal DESC NULLS LAST LIMIT 1;
    IF v_ub_id IS NULL THEN
      RAISE EXCEPTION 'No existe ubicación activa para check-in' USING ERRCODE='P0005';
    END IF;
  END IF;

  -- FA-3: Check-in idempotente — actualiza ubicación existente
  UPDATE auth.ubicaciones
  SET latitud=p_latitud, longitud=p_longitud, punto=v_punto,
      ultimo_checkin_at=now(), checkin_count=checkin_count+1,
      dispositivo_id=COALESCE(p_dispositivo_id,dispositivo_id), fecha_actualizacion=now()
  WHERE id=v_ub_id;

  -- Registrar historial
  INSERT INTO auth.checkins_vendedor
    (id_vendedor,id_ubicacion,latitud,longitud,punto,precision_metros,dispositivo_id)
  VALUES (v_actor,v_ub_id,p_latitud,p_longitud,v_punto,p_precision_metros,p_dispositivo_id)
  RETURNING id INTO v_checkin_id;

  -- Activar disponibilidad automáticamente (CU-V-MOB-001 V2.0)
  BEGIN
    v_result := auth.seller_set_availability(true, v_ub_id, v_actor);
  EXCEPTION WHEN OTHERS THEN
    v_result := jsonb_build_object('disponibilidad_error',SQLERRM);
  END;

  INSERT INTO auth.h_vendedores_audit(id_usuario,operacion,datos_anteriores,datos_nuevos,modificado_por,motivo)
  VALUES (v_actor,'UPDATE',
    jsonb_build_object('accion','checkin'),
    jsonb_build_object('ubicacion_id',v_ub_id,'latitud',p_latitud,'longitud',p_longitud,'checkin_id',v_checkin_id),
    v_actor,'Check-in desde app móvil');

  RETURN jsonb_build_object(
    'checkin_id',v_checkin_id,'ubicacion_id',v_ub_id,
    'latitud',p_latitud,'longitud',p_longitud,
    'disponibilidad',v_result,'timestamp',now());
END;
$$;


--
-- Name: seller_clientes_fieles_influencia(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_clientes_fieles_influencia(p_limit integer DEFAULT 20) RETURNS TABLE(id_comprador uuid, total_compras bigint, total numeric, ultima_compra timestamp with time zone, score_rfm numeric, influencia_red bigint, loyalty_score numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'ag_catalog'
    AS $_$
DECLARE
    v_actor_id uuid := auth.fn_current_user_id();
BEGIN
    RETURN QUERY
    WITH compras AS (
        -- Fuente de verdad: auth.ordenes con columnas reales
        SELECT
            o.id_comprador                          AS id_comprador,
            COUNT(*)::bigint                        AS total_compras,
            COALESCE(SUM(o.total), 0)::numeric      AS total,
            MAX(o.fecha_creacion)                       AS ultima_compra
        FROM auth.ordenes o
        JOIN auth.users b
            ON b.id = o.id_comprador
           AND b.activo = true AND b.fecha_eliminacion IS NULL
        WHERE o.id_vendedor = v_actor_id
          AND o.estado NOT IN ('cancelada', 'rechazada')
        GROUP BY o.id_comprador
    ),
    rfm AS (
        -- RFM snapshot si existe (CU-V-010)
        SELECT
            rs.id_comprador,
            (COALESCE(rs.score_r, 0) + COALESCE(rs.score_f, 0) + COALESCE(rs.score_m, 0))::numeric AS score_rfm
        FROM auth.rfm_snapshots rs
        WHERE rs.id_vendedor = v_actor_id
    ),
    influencia AS (
        -- AGE: centralidad de grado. Fallback elegante si falla.
        SELECT
            t.id_comprador::uuid    AS id_comprador,
            t.influencia_red::bigint AS influencia_red
        FROM cypher('smtp_posix_graph', $cypher$
            MATCH (u:User)
            RETURN u.id_sql, size((u)--()) AS grado
        $cypher$) AS t(id_comprador, influencia_red)
    )
    SELECT
        c.id_comprador,
        c.total_compras,
        c.total,
        c.ultima_compra,
        COALESCE(r.score_rfm, 0)                    AS score_rfm,
        COALESCE(i.influencia_red, 0)               AS influencia_red,
        ROUND(
            (c.total_compras * 0.4)::numeric
            + (LEAST(c.total, 10000) / 1000.0)::numeric
            + (COALESCE(r.score_rfm, 0) * 0.3)::numeric
            + (COALESCE(i.influencia_red, 0) * 0.2)::numeric,
            2
        )                                           AS loyalty_score
    FROM compras c
    LEFT JOIN rfm r       ON r.id_comprador = c.id_comprador
    LEFT JOIN influencia i ON i.id_comprador = c.id_comprador
    ORDER BY loyalty_score DESC, c.ultima_compra DESC
    LIMIT p_limit;

EXCEPTION WHEN OTHERS THEN
    -- Si AGE falla, retornar solo SQL sin centralidad
    RETURN QUERY
    WITH compras AS (
        SELECT
            o.id_comprador,
            COUNT(*)::bigint            AS total_compras,
            COALESCE(SUM(o.total), 0)   AS total,
            MAX(o.fecha_creacion)           AS ultima_compra
        FROM auth.ordenes o
        WHERE o.id_vendedor = v_actor_id
          AND o.estado NOT IN ('cancelada', 'rechazada')
        GROUP BY o.id_comprador
    )
    SELECT
        c.id_comprador,
        c.total_compras,
        c.total::numeric,
        c.ultima_compra,
        0::numeric, 0::bigint,
        ROUND((c.total_compras * 0.4 + LEAST(c.total, 10000)/1000.0)::numeric, 2)
    FROM compras c
    ORDER BY 7 DESC
    LIMIT p_limit;
END;
$_$;


--
-- Name: seller_configurar_alerta_ventas(numeric, integer, boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_configurar_alerta_ventas(p_umbral_pct numeric DEFAULT '-20.0'::numeric, p_ventana_dias integer DEFAULT 7, p_activa boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_vid uuid := auth.uid();
BEGIN
    IF NOT auth.fn_get_feature_flag(v_vid, 'alertas_ventas') THEN
        RAISE EXCEPTION 'Alertas de ventas requieren plan Gold o superior'
            USING ERRCODE = 'P0047';
    END IF;

    IF p_umbral_pct >= 0 OR p_umbral_pct < -100 THEN
        RAISE EXCEPTION 'umbral_pct debe estar entre -100 y -1 (e.g., -20 = alerta si cae 20%%)'
            USING ERRCODE = 'P0048';
    END IF;

    INSERT INTO auth.alertas_ventas
        (id_vendedor, umbral_pct, ventana_dias, activa)
    VALUES (v_vid, p_umbral_pct, p_ventana_dias, p_activa)
    ON CONFLICT (id_vendedor) DO UPDATE
        SET umbral_pct   = EXCLUDED.umbral_pct,
            ventana_dias = EXCLUDED.ventana_dias,
            activa       = EXCLUDED.activa;

    RETURN jsonb_build_object(
        'ok',            true,
        'umbral_pct',    p_umbral_pct,
        'ventana_dias',  p_ventana_dias,
        'activa',        p_activa,
        'mensaje',       format('Recibirás una alerta si tus ventas caen más del %s%% en %s días',
                                ABS(p_umbral_pct), p_ventana_dias)
    );
END;
$$;


--
-- Name: seller_convertir_puntos_a_mxn(numeric); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_convertir_puntos_a_mxn(p_puntos numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor_id    uuid;
    v_billetera   record;
    v_beneficio   record;
    v_limites     jsonb;
    v_monto_mxn   numeric;
    v_canje_id    uuid;
BEGIN
    v_actor_id := auth.fn_current_user_id();

    v_limites := auth.fn_get_wallet_limits(v_actor_id);
    IF NOT COALESCE((v_limites ->> 'conversion_disponible')::boolean, false) THEN
        RETURN jsonb_build_object(
            'error',  'plan_insuficiente', 'codigo', 'WALLET_050',
            'detalle', 'La conversión a MXN requiere plan Silver o superior'
        );
    END IF;

    IF p_puntos < 100 THEN
        RETURN jsonb_build_object(
            'error',  'minimo_conversion', 'codigo', 'WALLET_051',
            'detalle', 'El mínimo para conversión es 100 puntos'
        );
    END IF;

    SELECT * INTO v_beneficio FROM auth.beneficios_catalogo
    WHERE codigo = 'CONV_PUNTOS_MXN' AND activo = true;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'conversion_no_disponible', 'codigo', 'WALLET_030');
    END IF;
    IF v_beneficio.tasa_conversion_mxn IS NULL OR v_beneficio.tasa_conversion_mxn <= 0 THEN
        RETURN jsonb_build_object('error', 'tasa_no_configurada', 'codigo', 'WALLET_031');
    END IF;

    SELECT * INTO v_billetera FROM auth.billetera
    WHERE id_usuario = v_actor_id FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'billetera_no_encontrada', 'codigo', 'WALLET_001');
    END IF;
    IF NOT v_billetera.activo THEN
        RETURN jsonb_build_object('error', 'billetera_suspendida', 'codigo', 'WALLET_003');
    END IF;
    IF v_billetera.saldo < p_puntos THEN
        RETURN jsonb_build_object(
            'error',        'saldo_insuficiente', 'codigo', 'WALLET_002',
            'saldo_actual', v_billetera.saldo, 'requerido', p_puntos
        );
    END IF;

    v_monto_mxn := ROUND(p_puntos * v_beneficio.tasa_conversion_mxn, 2);

    UPDATE auth.billetera
    SET saldo = saldo - p_puntos, fecha_modificacion = now()
    WHERE id_usuario = v_actor_id;

    INSERT INTO auth.canjes_puntos (
        id_usuario, beneficio_id, puntos_debitados, saldo_anterior, saldo_posterior,
        estado, detalle
    ) VALUES (
        v_actor_id, v_beneficio.id, p_puntos, v_billetera.saldo,
        v_billetera.saldo - p_puntos, 'aprobado',
        jsonb_build_object('tipo', 'conversion_mxn', 'monto_mxn', v_monto_mxn,
                           'tasa', v_beneficio.tasa_conversion_mxn)
    ) RETURNING id INTO v_canje_id;

    INSERT INTO auth.movimientos_puntos (
        id_usuario, tipo_movimiento, monto, saldo_anterior, saldo_posterior, referencia, detalle
    ) VALUES (
        v_actor_id, 'conversion_mxn', -p_puntos, v_billetera.saldo,
        v_billetera.saldo - p_puntos, v_canje_id::text,
        jsonb_build_object('monto_mxn', v_monto_mxn, 'tasa', v_beneficio.tasa_conversion_mxn)
    );

    INSERT INTO auth.payment_transactions (
        id_orden, id_comprador, id_vendedor, metodo, monto, estado, gateway_response
    )
    SELECT
        o.id, v_actor_id, v_actor_id,
        'puntos_conversion', v_monto_mxn, 'completed'::text,
        jsonb_build_object('canje_id', v_canje_id, 'puntos', p_puntos,
                           'tasa', v_beneficio.tasa_conversion_mxn)
    FROM auth.ordenes o
    WHERE o.id_vendedor = v_actor_id
      AND o.estado = 'confirmada'
    ORDER BY o.fecha_creacion DESC
    LIMIT 1;

    RETURN jsonb_build_object(
        'canje_id',           v_canje_id,
        'puntos_convertidos', p_puntos,
        'monto_mxn',          v_monto_mxn,
        'tasa',               v_beneficio.tasa_conversion_mxn,
        'saldo_nuevo',        v_billetera.saldo - p_puntos
    );
END;
$$;


--
-- Name: seller_crear_bundle(text, text, numeric, uuid[]); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_crear_bundle(p_nombre text, p_descripcion text DEFAULT NULL::text, p_descuento_pct numeric DEFAULT 0, p_producto_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor     uuid;
    v_plan_cod  text;
    v_bundle_id uuid;
    v_pid       uuid;
BEGIN
    v_actor := auth.fn_current_user_id();

    IF array_length(p_producto_ids, 1) < 2 THEN
        RAISE EXCEPTION 'Un bundle requiere al menos 2 productos' USING ERRCODE = '22023';
    END IF;

    SELECT pm.codigo INTO v_plan_cod
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.id_vendedor = v_actor AND mv.estado IN ('activo','grace_period')
    LIMIT 1;

    IF coalesce(v_plan_cod,'bronze') = 'bronze' THEN
        RAISE EXCEPTION 'Crear bundles requiere plan Silver o superior' USING ERRCODE = '42501';
    END IF;

    INSERT INTO auth.bundles_producto (id_vendedor, nombre, descripcion, descuento_pct)
    VALUES (v_actor, p_nombre, p_descripcion, p_descuento_pct)
    RETURNING id INTO v_bundle_id;

    FOREACH v_pid IN ARRAY p_producto_ids LOOP
        INSERT INTO auth.bundle_items (id_lote, id_producto) VALUES (v_bundle_id, v_pid);
    END LOOP;

    INSERT INTO auth.h_vendedores_audit (id_usuario, operacion, datos_nuevos, motivo)
    VALUES (v_actor, 'INSERT',
            jsonb_build_object('bundle_id',v_bundle_id,'nombre',p_nombre,
                               'productos',p_producto_ids),
            'Bundle creado: ' || p_nombre);

    RETURN jsonb_build_object('bundle_id',v_bundle_id,'nombre',p_nombre,'status','created');
END;
$$;


--
-- Name: seller_crear_campana(text, text, uuid, text, timestamp with time zone, timestamp with time zone, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_crear_campana(p_nombre text, p_tipo text, p_promocion_id uuid DEFAULT NULL::uuid, p_descripcion text DEFAULT NULL::text, p_fecha_inicio timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_fin timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor   uuid;
    v_plan    text;
    v_camp_id uuid;
BEGIN
    v_actor := (nullif(current_setting('request.jwt.claims', true),'')::jsonb ->> 'sub')::uuid;
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Actor no resuelto desde JWT' USING ERRCODE = 'P0001';
    END IF;

    IF p_tipo NOT IN ('general','geo','rfm','push','bundle','ab') THEN
        RAISE EXCEPTION 'Tipo de campaña inválido: %', p_tipo USING ERRCODE = 'P0072';
    END IF;

    SELECT pm.nombre INTO v_plan
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.id_vendedor = v_actor AND mv.estado = 'activa';

    IF p_tipo IN ('geo','rfm') AND COALESCE(v_plan,'bronze') NOT IN ('silver','gold','platinum') THEN
        RAISE EXCEPTION 'Campañas % requieren plan Silver o superior', p_tipo USING ERRCODE = 'P0073';
    END IF;
    IF p_tipo = 'push' AND COALESCE(v_plan,'bronze') NOT IN ('gold','platinum') THEN
        RAISE EXCEPTION 'Campañas push requieren plan Gold' USING ERRCODE = 'P0074';
    END IF;
    IF p_tipo IN ('ab','bundle') AND COALESCE(v_plan,'bronze') NOT IN ('gold','platinum') THEN
        RAISE EXCEPTION 'Campañas A/B y bundle requieren plan Gold' USING ERRCODE = 'P0075';
    END IF;

    IF p_promocion_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM auth.promociones
            WHERE id = p_promocion_id AND creado_por = v_actor AND activo = true
        ) THEN
            RAISE EXCEPTION 'Promoción no encontrada, no pertenece al vendedor o está inactiva'
                USING ERRCODE = 'P0076';
        END IF;
    END IF;

    IF p_metadata IS NULL OR jsonb_typeof(p_metadata) <> 'object' THEN
        RAISE EXCEPTION 'metadata debe ser un objeto JSON' USING ERRCODE = 'P0077';
    END IF;

    INSERT INTO auth.campanas
        (id_vendedor, nombre, descripcion, tipo, id_promocion,
         estado, fecha_inicio, fecha_fin, metadata)
    VALUES (
        v_actor, p_nombre, p_descripcion, p_tipo, p_promocion_id,
        'borrador', p_fecha_inicio, p_fecha_fin, p_metadata
    )
    RETURNING id INTO v_camp_id;

    INSERT INTO auth.h_vendedores_audit
        (id_usuario, operacion, datos_nuevos, modificado_por, motivo)
    VALUES (v_actor, 'INSERT',
        jsonb_build_object('campana_id', v_camp_id, 'tipo', p_tipo, 'nombre', p_nombre),
        v_actor, 'creacion_campana');

    RETURN jsonb_build_object('ok', true, 'campana_id', v_camp_id, 'tipo', p_tipo);
END;
$$;


--
-- Name: seller_crear_campana_ab(uuid, numeric, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_crear_campana_ab(p_campana_id uuid, p_pct_test numeric DEFAULT 50.0, p_nombre_control text DEFAULT 'Control'::text, p_nombre_test text DEFAULT 'Test'::text, p_metrica_objetivo text DEFAULT 'conversion'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor         uuid;
    v_campana       auth.campanas%ROWTYPE;
    v_compradores   uuid[];
    v_control       uuid[] := '{}';
    v_test          uuid[] := '{}';
    v_ab_id         uuid;
    v_uid           uuid;
    v_hash_val      int;
BEGIN
    v_actor := (nullif(current_setting('request.jwt.claims', true),'')::jsonb ->> 'sub')::uuid;

    SELECT * INTO v_campana FROM auth.campanas
    WHERE id = p_campana_id AND id_vendedor = v_actor;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Campaña no encontrada' USING ERRCODE = 'P0085';
    END IF;
    IF v_campana.estado <> 'borrador' THEN
        RAISE EXCEPTION 'El experimento A/B debe configurarse antes de lanzar la campaña'
            USING ERRCODE = 'P0086';
    END IF;
    IF p_pct_test <= 0 OR p_pct_test >= 100 THEN
        RAISE EXCEPTION 'pct_test debe estar entre 1 y 99' USING ERRCODE = 'P0087';
    END IF;
    IF p_metrica_objetivo NOT IN ('conversion','apertura','click') THEN
        RAISE EXCEPTION 'metrica_objetivo inválida' USING ERRCODE = 'P0088';
    END IF;

    -- Obtener compradores históricos
    SELECT ARRAY_AGG(DISTINCT o.id_comprador) INTO v_compradores
    FROM auth.ordenes o
    WHERE o.id_vendedor = v_actor AND o.estado = 'confirmada';

    -- Split determinístico: abs(hashtext(id_usuario::text)) % 100 < pct_test → grupo test
    FOREACH v_uid IN ARRAY COALESCE(v_compradores, '{}') LOOP
        v_hash_val := abs(hashtext(v_uid::text)) % 100;
        IF v_hash_val < p_pct_test THEN
            v_test    := array_append(v_test, v_uid);
        ELSE
            v_control := array_append(v_control, v_uid);
        END IF;
    END LOOP;

    -- Guardar config A/B
    INSERT INTO auth.campana_ab_config
        (id_campana, nombre_control, nombre_test, pct_test, metrica_objetivo)
    VALUES (p_campana_id, p_nombre_control, p_nombre_test, p_pct_test, p_metrica_objetivo)
    RETURNING id INTO v_ab_id;

    -- Guardar segmentos control y test
    INSERT INTO auth.campana_segmentos
        (id_campana, tipo_segmento, criterios, compradores_ids, total_objetivo)
    VALUES
        (p_campana_id, 'ab_control',
         jsonb_build_object('variante', 'control', 'ab_config_id', v_ab_id),
         v_control, array_length(v_control, 1)),
        (p_campana_id, 'ab_test',
         jsonb_build_object('variante', 'test', 'ab_config_id', v_ab_id),
         v_test, array_length(v_test, 1));

    -- Actualizar tipo de campaña a 'ab'
    UPDATE auth.campanas SET tipo = 'ab', fecha_modificacion = now()
    WHERE id = p_campana_id;

    RETURN jsonb_build_object(
        'ok', true,
        'ab_config_id', v_ab_id,
        'grupo_control', array_length(v_control, 1),
        'grupo_test',    array_length(v_test, 1),
        'pct_test',      p_pct_test,
        'metrica_objetivo', p_metrica_objetivo
    );
END;
$$;


--
-- Name: seller_crear_campana_bundle(uuid, text, uuid, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_crear_campana_bundle(p_bundle_id uuid, p_nombre text, p_promocion_id uuid DEFAULT NULL::uuid, p_descripcion text DEFAULT NULL::text, p_fecha_inicio timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_fin timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor   uuid;
    v_camp_id uuid;
BEGIN
    v_actor := (nullif(current_setting('request.jwt.claims', true),'')::jsonb ->> 'sub')::uuid;
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Actor no resuelto desde JWT' USING ERRCODE = 'P0001';
    END IF;

    -- Validar que el bundle pertenece al vendedor (cuando CU-V-013 está deployado)
    IF EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema='auth' AND table_name='bundles_producto'
    ) THEN
        IF NOT EXISTS (
            SELECT 1 FROM auth.bundles_producto
            WHERE id = p_bundle_id AND id_vendedor = v_actor AND activo = true
        ) THEN
            RAISE EXCEPTION 'Bundle no encontrado o no pertenece al vendedor' USING ERRCODE = 'P0084';
        END IF;
    END IF;

    INSERT INTO auth.campanas
        (id_vendedor, nombre, descripcion, tipo, id_lote,
         id_promocion, estado, fecha_inicio, fecha_fin)
    VALUES (
        v_actor, p_nombre, p_descripcion, 'bundle', p_bundle_id,
        p_promocion_id, 'borrador', p_fecha_inicio, p_fecha_fin
    )
    RETURNING id INTO v_camp_id;

    RETURN jsonb_build_object(
        'ok', true, 'campana_id', v_camp_id,
        'bundle_id', p_bundle_id, 'tipo', 'bundle'
    );
END;
$$;


--
-- Name: seller_crear_chatbot_regla(text, text, numeric, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_crear_chatbot_regla(p_patron text, p_respuesta text, p_umbral numeric DEFAULT 0.35, p_prioridad integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor  uuid;
    v_reg_id uuid;
BEGIN
    v_actor := coalesce(
        (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')::uuid
    );
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Actor no resuelto desde JWT' USING ERRCODE = 'P0001';
    END IF;

    -- Gold+ para chatbot personalizado
    IF NOT auth.fn_get_feature_flag(v_actor, 'chatbot_soporte') THEN
        RAISE EXCEPTION 'Tu plan no incluye chatbot de soporte (Gold+)' USING ERRCODE = 'P0003';
    END IF;

    -- Max 50 reglas por vendedor
    IF (SELECT COUNT(*) FROM auth.chatbot_reglas WHERE id_vendedor = v_actor AND activa = true) >= 50 THEN
        RAISE EXCEPTION 'Límite de 50 reglas de chatbot alcanzado' USING ERRCODE = 'P0040';
    END IF;

    INSERT INTO auth.chatbot_reglas
        (id_vendedor, patron, respuesta, umbral_sim, prioridad)
    VALUES (v_actor, p_patron, p_respuesta, p_umbral, p_prioridad)
    RETURNING id INTO v_reg_id;

    RETURN jsonb_build_object('ok', true, 'regla_id', v_reg_id);
END;
$$;


--
-- Name: seller_crear_promo_zone(text, text, numeric, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_crear_promo_zone(p_nombre text, p_poligono_wkt text, p_descuento_pct numeric, p_inicia_en timestamp with time zone, p_vence_en timestamp with time zone, p_promocion_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'ag_catalog', 'public'
    AS $$
DECLARE
    v_actor_id  uuid := auth.fn_current_user_id();
    v_id        uuid;
    v_geom      geometry;
BEGIN
    -- Validar vendedor activo con membresía
    IF NOT EXISTS (
        SELECT 1 FROM auth.users u
        JOIN auth.membresias_vendedor mv ON mv.id_vendedor = u.id AND mv.estado = 'activa'
        WHERE u.id = v_actor_id
          AND u.activo = true AND u.fecha_eliminacion IS NULL
    ) THEN
        RAISE EXCEPTION 'P0206: Vendedor sin membresía activa' USING ERRCODE = 'P0001';
    END IF;

    -- Parsear WKT
    BEGIN
        v_geom := ST_GeomFromText(p_poligono_wkt, 4326);
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'P0207: WKT inválido para polígono' USING ERRCODE = 'P0001';
    END;

    INSERT INTO auth.seller_promo_zones (
        id_vendedor, id_promocion, nombre, poligono,
        descuento_pct, inicia_en, vence_en
    ) VALUES (
        v_actor_id, p_promocion_id, p_nombre, v_geom,
        p_descuento_pct, p_inicia_en, p_vence_en
    ) RETURNING id INTO v_id;

    RETURN jsonb_build_object('status', 'OK', 'promo_zone_id', v_id);
END;
$$;


--
-- Name: seller_crear_promocion(text, text, text, numeric, timestamp with time zone, timestamp with time zone, integer, text, jsonb, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_crear_promocion(p_codigo text, p_nombre text, p_tipo text, p_valor numeric, p_fecha_inicio timestamp with time zone, p_fecha_fin timestamp with time zone, p_max_usos integer DEFAULT NULL::integer, p_canal text DEFAULT 'codigo'::text, p_condiciones jsonb DEFAULT '{}'::jsonb, p_descripcion text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $_$
DECLARE
    v_actor   uuid;
    v_prom_id uuid;
BEGIN
    v_actor := (nullif(current_setting('request.jwt.claims', true),'')::jsonb ->> 'sub')::uuid;
    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Actor no resuelto desde JWT' USING ERRCODE = 'P0001';
    END IF;

    -- Validaciones de entrada (anti-inyección: parámetros tipados, nunca concatenados)
    IF p_tipo NOT IN ('porcentaje','monto_fijo','envio_gratis','puntos') THEN
        RAISE EXCEPTION 'Tipo inválido: %. Use: porcentaje, monto_fijo, envio_gratis, puntos', p_tipo
            USING ERRCODE = 'P0051';
    END IF;
    IF p_tipo = 'porcentaje' AND (p_valor <= 0 OR p_valor > 100) THEN
        RAISE EXCEPTION 'Para tipo porcentaje, valor debe estar entre 0.01 y 100'
            USING ERRCODE = 'P0052';
    END IF;
    IF p_valor <= 0 THEN
        RAISE EXCEPTION 'El valor de la promoción debe ser positivo' USING ERRCODE = 'P0053';
    END IF;
    IF p_fecha_fin <= p_fecha_inicio THEN
        RAISE EXCEPTION 'fecha_fin debe ser posterior a fecha_inicio' USING ERRCODE = 'P0054';
    END IF;
    IF p_canal NOT IN ('codigo','automatico','campaña','bundle') THEN
        RAISE EXCEPTION 'Canal inválido: %', p_canal USING ERRCODE = 'P0055';
    END IF;
    IF EXISTS (SELECT 1 FROM auth.promociones WHERE codigo = upper(trim(p_codigo))) THEN
        RAISE EXCEPTION 'El código % ya existe', p_codigo USING ERRCODE = 'P0056';
    END IF;
    -- Validar longitud del código para evitar desbordamientos
    IF length(trim(p_codigo)) < 3 OR length(trim(p_codigo)) > 30 THEN
        RAISE EXCEPTION 'El código debe tener entre 3 y 30 caracteres' USING ERRCODE = 'P0057';
    END IF;
    -- Validar que el código solo contenga caracteres alfanuméricos y guiones
    IF NOT (upper(trim(p_codigo)) ~ '^[A-Z0-9_-]+$') THEN
        RAISE EXCEPTION 'El código solo puede contener letras, números, guiones y guiones bajos'
            USING ERRCODE = 'P0058';
    END IF;

    INSERT INTO auth.promociones
        (codigo, nombre, descripcion, tipo, valor, fecha_inicio, fecha_fin,
         max_usos, condiciones, canal, activo, creado_por)
    VALUES (
        upper(trim(p_codigo)), p_nombre, p_descripcion, p_tipo, p_valor,
        p_fecha_inicio, p_fecha_fin, p_max_usos,
        COALESCE(p_condiciones, '{}'), p_canal, true, v_actor
    )
    RETURNING id INTO v_prom_id;

    RETURN jsonb_build_object(
        'ok',           true,
        'promocion_id', v_prom_id,
        'codigo',       upper(trim(p_codigo))
    );
END;
$_$;


--
-- Name: seller_crear_transferencia_programada(uuid, numeric, timestamp with time zone, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_crear_transferencia_programada(p_receptor_id uuid, p_monto numeric, p_ejecutar_en timestamp with time zone, p_nota text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor_id uuid;
    v_limites  jsonb;
    v_tp_id    uuid;
BEGIN
    v_actor_id := auth.fn_current_user_id();

    -- Verificar plan Gold
    v_limites := auth.fn_get_wallet_limits(v_actor_id);
    IF NOT COALESCE((v_limites ->> 'transferencias_programadas')::boolean, false) THEN
        RETURN jsonb_build_object(
            'error',  'plan_insuficiente', 'codigo', 'WALLET_070',
            'detalle', 'Las transferencias programadas requieren plan Gold o superior'
        );
    END IF;

    IF p_monto < 10 THEN
        RETURN jsonb_build_object('error', 'monto_minimo_10', 'codigo', 'WALLET_041');
    END IF;

    IF p_ejecutar_en <= now() THEN
        RETURN jsonb_build_object(
            'error',  'fecha_invalida', 'codigo', 'WALLET_071',
            'detalle', 'La fecha de ejecución debe ser futura'
        );
    END IF;

    -- Verificar receptor válido
    IF NOT EXISTS (
        SELECT 1 FROM auth.users
        WHERE id = p_receptor_id
          AND COALESCE(activo, true) = true
          AND fecha_eliminacion IS NULL
          AND role IN ('buyer', 'seller')
    ) THEN
        RETURN jsonb_build_object('error', 'receptor_invalido', 'codigo', 'WALLET_023');
    END IF;

    INSERT INTO auth.transferencias_programadas (
        id_usuario_origen, id_usuario_receptor, monto, nota, estado, ejecutar_en
    ) VALUES (
        v_actor_id, p_receptor_id, p_monto, p_nota, 'pendiente', p_ejecutar_en
    ) RETURNING id INTO v_tp_id;

    RETURN jsonb_build_object(
        'transferencia_programada_id', v_tp_id,
        'ejecutar_en',                 p_ejecutar_en,
        'estado',                       'pendiente'
    );
END;
$$;


--
-- Name: seller_crear_trigger_contexto_custom(text, text, jsonb, numeric, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_crear_trigger_contexto_custom(p_nombre text, p_tipo_contexto text, p_condicion_jsonb jsonb, p_recompensa_puntos numeric, p_plan_minimo text) RETURNS jsonb
