--
-- Name: seller_create_ubicacion(text, text, text, double precision, double precision, boolean, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_create_ubicacion(p_nombre text, p_direccion_texto text DEFAULT NULL::text, p_tipo text DEFAULT 'punto_venta'::text, p_latitud double precision DEFAULT NULL::double precision, p_longitud double precision DEFAULT NULL::double precision, p_es_principal boolean DEFAULT false, p_horarios jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_user_id   uuid := (nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid;
  v_limits    jsonb;
  v_new_id    uuid;
BEGIN
  -- RN-001: Resolver actor desde JWT
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unable_to_resolve_current_user');
  END IF;

  -- RN-002: Validar tipo permitido (también capturado por CHECK constraint)
  IF p_tipo NOT IN ('punto_venta','almacen','punto_entrega','oficina','otro') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'tipo_ubicacion_invalido');
  END IF;

  -- RN-003: Obtener límites del plan actual
  v_limits := auth.fn_get_location_limits(v_user_id);

  IF (v_limits->>'activas_actuales')::integer >= (v_limits->>'max_ubicaciones')::integer THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'limite_ubicaciones_alcanzado',
      'max', (v_limits->>'max_ubicaciones')::integer,
      'actuales', (v_limits->>'activas_actuales')::integer
    );
  END IF;

  -- RN-004: Si p_es_principal, desmarcar otras (también lo hace trigger)
  IF p_es_principal THEN
    UPDATE auth.ubicaciones SET es_principal = false
    WHERE id_usuario = v_user_id AND es_principal = true AND fecha_eliminacion IS NULL;
  END IF;

  -- INSERT principal
  INSERT INTO auth.ubicaciones (
    id_usuario, nombre, direccion_texto, tipo,
    latitud, longitud, punto, es_principal, horarios, estado
  ) VALUES (
    v_user_id, p_nombre, p_direccion_texto, p_tipo,
    p_latitud, p_longitud,
    CASE WHEN p_latitud IS NOT NULL AND p_longitud IS NOT NULL
         THEN ST_SetSRID(ST_MakePoint(p_longitud, p_latitud), 4326)::geography
         ELSE NULL END,
    p_es_principal, p_horarios, 'activo'
  )
  RETURNING id INTO v_new_id;

  -- Auditoría — operacion SOLO puede ser 'INSERT','UPDATE','SUSPEND'
  INSERT INTO auth.h_vendedores_audit (id_usuario, operacion, datos_nuevos, modificado_por, motivo)
  VALUES (v_user_id, 'INSERT',
    jsonb_build_object(
      'ubicacion_id', v_new_id, 'nombre', p_nombre,
      'tipo', p_tipo, 'latitud', p_latitud, 'longitud', p_longitud
    ),
    v_user_id, 'seller_create_ubicacion');

  -- Outbox AGE async (RN-005: no bloquear RPC principal)
  INSERT INTO auth.ubicacion_graph_outbox (id_ubicacion, id_usuario, operacion, payload)
  VALUES (v_new_id, v_user_id, 'UPSERT',
    jsonb_build_object(
      'nombre', p_nombre, 'tipo', p_tipo,
      'latitud', p_latitud, 'longitud', p_longitud,
      'es_principal', p_es_principal, 'estado', 'activo'
    ));

  RETURN jsonb_build_object('ok', true, 'ubicacion_id', v_new_id);
END;
$$;


--
-- Name: seller_deactivate_ubicacion(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_deactivate_ubicacion(p_ubicacion_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_user_id    uuid := (nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid;
  v_ub         auth.ubicaciones%ROWTYPE;
  v_stock      integer;
  v_activas    integer;
BEGIN
  SELECT * INTO v_ub FROM auth.ubicaciones
  WHERE id = p_ubicacion_id AND id_usuario = v_user_id
    AND fecha_eliminacion IS NULL;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ubicacion_no_encontrada_o_sin_permiso');
  END IF;

  IF v_ub.estado = 'inactivo' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ubicacion_ya_inactiva');
  END IF;

  -- RN-007: Verificar stock en auth.inventario_ubicacion (CU-V-003)
  SELECT COALESCE(SUM(stock_disponible), 0) INTO v_stock
  FROM auth.inventario_ubicacion
  WHERE id_ubicacion = p_ubicacion_id;

  IF v_stock > 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'ubicacion_tiene_stock_asignado',
      'stock_disponible', v_stock,
      'accion_requerida', 'Transferir o consumir stock antes de desactivar (CU-V-003)'
    );
  END IF;

  -- RN-008: Mantener mínimo 1 ubicación activa
  SELECT COUNT(*) INTO v_activas
  FROM auth.ubicaciones
  WHERE id_usuario = v_user_id AND estado = 'activo' AND fecha_eliminacion IS NULL;

  IF v_activas <= 1 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'unica_ubicacion_activa',
      'mensaje', 'Debe mantener al menos una ubicación activa para vender'
    );
  END IF;

  UPDATE auth.ubicaciones
  SET estado = 'inactivo', es_principal = false, fecha_actualizacion = now()
  WHERE id = p_ubicacion_id;

  -- RN-009: Si era principal, promover la más reciente activa
  IF v_ub.es_principal THEN
    UPDATE auth.ubicaciones SET es_principal = true, fecha_actualizacion = now()
    WHERE id = (
      SELECT id FROM auth.ubicaciones
      WHERE id_usuario = v_user_id AND estado = 'activo' AND fecha_eliminacion IS NULL
      ORDER BY fecha_creacion DESC LIMIT 1
    );
  END IF;

  INSERT INTO auth.h_vendedores_audit (id_usuario, operacion, datos_nuevos, modificado_por, motivo)
  VALUES (v_user_id, 'UPDATE',
    jsonb_build_object('ubicacion_id', p_ubicacion_id, 'nuevo_estado', 'inactivo'),
    v_user_id, 'seller_deactivate_ubicacion');

  -- Outbox AGE: marcar nodo como inactivo
  INSERT INTO auth.ubicacion_graph_outbox (id_ubicacion, id_usuario, operacion, payload)
  VALUES (p_ubicacion_id, v_user_id, 'DEACTIVATE',
    jsonb_build_object('estado', 'inactivo'));

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: seller_decidir_ganador_ab(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_decidir_ganador_ab(p_campana_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor    uuid;
    v_ab       auth.campana_ab_config%ROWTYPE;
    v_n_ctrl   bigint; v_conv_ctrl   bigint;
    v_n_test   bigint; v_conv_test   bigint;
    v_rate_ctrl numeric; v_rate_test   numeric;
    v_z        numeric; v_se          numeric;
    v_ganador  text;
    v_conf     numeric;
BEGIN
    v_actor := (nullif(current_setting('request.jwt.claims', true),'')::jsonb ->> 'sub')::uuid;

    IF NOT EXISTS (SELECT 1 FROM auth.campanas WHERE id = p_campana_id AND id_vendedor = v_actor) THEN
        RAISE EXCEPTION 'Campaña no encontrada' USING ERRCODE = 'P0089';
    END IF;

    SELECT * INTO v_ab FROM auth.campana_ab_config WHERE id_campana = p_campana_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'No hay configuración A/B para esta campaña' USING ERRCODE = 'P0090';
    END IF;

    -- Contar enviados y conversiones por variante
    SELECT COUNT(*) FILTER (WHERE cl.evento = 'enviado'),
           COUNT(*) FILTER (WHERE cl.evento = 'convertido')
    INTO v_n_ctrl, v_conv_ctrl
    FROM auth.campana_log cl
    WHERE cl.id_campana = p_campana_id AND cl.variante_ab = 'control';

    SELECT COUNT(*) FILTER (WHERE cl.evento = 'enviado'),
           COUNT(*) FILTER (WHERE cl.evento = 'convertido')
    INTO v_n_test, v_conv_test
    FROM auth.campana_log cl
    WHERE cl.id_campana = p_campana_id AND cl.variante_ab = 'test';

    IF v_n_ctrl < 30 OR v_n_test < 30 THEN
        RETURN jsonb_build_object(
            'ok', false, 'mensaje', 'Muestra insuficiente para decidir (mínimo 30 por grupo)',
            'n_control', v_n_ctrl, 'n_test', v_n_test
        );
    END IF;

    v_rate_ctrl := v_conv_ctrl::numeric / NULLIF(v_n_ctrl, 0);
    v_rate_test := v_conv_test::numeric / NULLIF(v_n_test, 0);

    -- Z-score para diferencia de proporciones
    v_se := SQRT(
        (v_rate_ctrl * (1 - v_rate_ctrl) / NULLIF(v_n_ctrl,0)) +
        (v_rate_test  * (1 - v_rate_test)  / NULLIF(v_n_test, 0))
    );
    v_z := CASE WHEN v_se > 0 THEN ABS(v_rate_test - v_rate_ctrl) / v_se ELSE 0 END;

    -- Mapeo aproximado Z → confianza (1-tailed)
    v_conf := CASE
        WHEN v_z >= 2.576 THEN 99.0
        WHEN v_z >= 1.960 THEN 95.0
        WHEN v_z >= 1.645 THEN 90.0
        WHEN v_z >= 1.282 THEN 80.0
        ELSE ROUND(50 + v_z * 15, 1)
    END;

    v_ganador := CASE
        WHEN v_conf >= 95 AND v_rate_test > v_rate_ctrl THEN 'test'
        WHEN v_conf >= 95 AND v_rate_ctrl > v_rate_test THEN 'control'
        ELSE NULL
    END;

    IF v_ganador IS NOT NULL THEN
        UPDATE auth.campana_ab_config SET
            ganador = v_ganador,
            confianza_pct = v_conf,
            decidido_en = now()
        WHERE id_campana = p_campana_id;
    END IF;

    RETURN jsonb_build_object(
        'ok', true,
        'n_control',     v_n_ctrl,    'conversiones_control', v_conv_ctrl,
        'tasa_control',  ROUND(v_rate_ctrl * 100, 2),
        'n_test',        v_n_test,    'conversiones_test', v_conv_test,
        'tasa_test',     ROUND(v_rate_test  * 100, 2),
        'z_score',       ROUND(v_z, 4),
        'confianza_pct', v_conf,
        'ganador',       v_ganador,
        'decidido',      v_ganador IS NOT NULL
    );
END;
$$;


--
-- Name: seller_desactivar_bundle(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_desactivar_bundle(p_bundle_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid;
    v_rows  integer;
BEGIN
    v_actor := auth.fn_current_user_id();

    UPDATE auth.bundles_producto
    SET activo = false
    WHERE id = p_bundle_id AND id_vendedor = v_actor;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        RAISE EXCEPTION 'Bundle no encontrado o no autorizado' USING ERRCODE = 'P0002';
    END IF;

    RETURN jsonb_build_object('bundle_id',p_bundle_id,'status','deactivated');
END;
$$;


--
-- Name: seller_detener_venta(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_detener_venta(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_caller_id UUID;
    v_rows_ppv  INT;
BEGIN
    v_caller_id := auth.jwt_user_id();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'No autenticado' USING ERRCODE = 'PT401';
    END IF;

    IF v_caller_id <> p_id_vendedor THEN
        RAISE EXCEPTION 'Solo el propio vendedor puede detener su sesión de venta'
            USING ERRCODE = 'PT403';
    END IF;

    -- Desactivar ubicación
    UPDATE auth.ubicaciones
    SET estado = 'inactivo', fecha_actualizacion = now()
    WHERE id_usuario = p_id_vendedor;

    -- Desactivar disponibilidad en perfil público
    UPDATE auth.perfiles_publicos_vendedor
    SET
        is_disponible      = false,
        spot_label         = NULL,
        fecha_modificacion = now()
    WHERE id_vendedor = p_id_vendedor;
    GET DIAGNOSTICS v_rows_ppv = ROW_COUNT;

    IF v_rows_ppv = 0 THEN
        RAISE EXCEPTION 'Vendedor no tiene perfil público registrado'
            USING ERRCODE = 'P0002';
    END IF;

    -- Auditoría
    INSERT INTO auth.h_vendedores_audit (
        id_usuario, modificado_por, evento, datos_nuevos, fecha_cambio
    ) VALUES (
        p_id_vendedor, v_caller_id, 'SELLER_STOPPED_SELLING',
        jsonb_build_object('stopped_at', now()),
        now()
    );

    RETURN jsonb_build_object(
        'status',           'OK',
        'id_vendedor',   p_id_vendedor,
        'is_disponible',    false,
        'estado_ubicacion', 'inactivo',
        'ts',               now()
    );
END;
$$;


--
-- Name: seller_get_abc_inventario(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_abc_inventario() RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := auth.fn_current_user_id();
    v_limits jsonb;
BEGIN
    v_limits := auth.fn_get_inventory_limits(v_actor);
    IF (v_limits ->> 'inventory_abc_analysis')::boolean IS NOT TRUE THEN
        RAISE EXCEPTION 'Análisis ABC solo disponible para Silver+';
    END IF;

    -- Recalcular si último cálculo > 24h
    PERFORM auth.fn_calcular_abc_inventario(v_actor)
    WHERE NOT EXISTS (
        SELECT 1 FROM auth.inventario_abc_analysis
        WHERE id_vendedor = v_actor AND calculado_en > now() - interval '24 hours'
    );

    RETURN QUERY
    SELECT jsonb_build_object(
        'producto_id', abc.id_producto,
        'producto_nombre', p.nombre,
        'clasificacion', abc.clasificacion,
        'movimientos_90d', abc.movimientos_90d,
        'porcentaje_acumulado', abc.porcentaje_acumulado,
        'unidades_movidas_90d', abc.unidades_movidas_90d,
        'valor_movido_90d', abc.valor_movido_90d,
        'calculado_en', abc.calculado_en
    )
    FROM auth.inventario_abc_analysis abc
    JOIN auth.productos p ON p.id = abc.id_producto
    WHERE abc.id_vendedor = v_actor
    ORDER BY abc.porcentaje_acumulado;
END;
$$;


--
-- Name: seller_get_afinidad_productos(uuid, text, integer, boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_afinidad_productos(p_producto_id uuid DEFAULT NULL::uuid, p_tipo text DEFAULT 'positiva'::text, p_limit integer DEFAULT 20, p_recalcular boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $_$
DECLARE
    v_actor      uuid;
    v_plan_cod   text;
    v_result     jsonb;
    v_graph_name text;
BEGIN
    v_actor := auth.fn_current_user_id();

    SELECT pm.codigo INTO v_plan_cod
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.id_vendedor = v_actor AND mv.estado IN ('activo','grace_period')
    LIMIT 1;

    -- Recalcular si solicitado o sin datos
    IF p_recalcular OR NOT EXISTS(
        SELECT 1 FROM auth.afinidad_productos WHERE id_vendedor = v_actor LIMIT 1
    ) THEN
        PERFORM auth.fn_calcular_afinidad(v_actor);
    END IF;

    -- Intento AGE primero
    BEGIN
        SELECT name INTO v_graph_name FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;
        IF v_graph_name IS NOT NULL AND p_producto_id IS NOT NULL THEN
            EXECUTE format(
                $age$SELECT jsonb_agg(row_to_json(t)) FROM (
                SELECT * FROM cypher(%L, $c$
                MATCH (p:Producto {id_producto: %L})-[r:COMPRADO_JUNTO]-(otro:Producto)
                WHERE r.frecuencia >= 2
                RETURN otro.id_producto AS id, otro.nombre AS nombre,
                       otro.precio AS precio, r.frecuencia AS frecuencia,
                       r.lift AS lift
                ORDER BY r.lift DESC LIMIT %s $c$)
                AS (id agtype, nombre agtype, precio agtype, frecuencia agtype, lift agtype)) t$age$,
                v_graph_name, p_producto_id::text, p_limit
            ) INTO v_result;

            IF v_result IS NOT NULL AND jsonb_array_length(v_result) > 0 THEN
                RETURN jsonb_build_object('fuente','age_graph','plan',coalesce(v_plan_cod,'bronze'),'datos',v_result);
            END IF;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'AGE query falló, usando SQL fallback: %', SQLERRM;
    END;

    -- Fallback SQL
    SELECT jsonb_agg(row_to_json(t)) INTO v_result
    FROM (
        SELECT
            CASE WHEN ap.producto_a_id = p_producto_id THEN ap.producto_b_id
                 ELSE ap.producto_a_id END AS id_producto,
            CASE WHEN ap.producto_a_id = p_producto_id THEN pb.nombre
                 ELSE pa.nombre END AS nombre,
            ap.frecuencia, ap.confianza, ap.lift, ap.tipo_correlacion
        FROM auth.afinidad_productos ap
        JOIN auth.productos pa ON pa.id = ap.producto_a_id
        JOIN auth.productos pb ON pb.id = ap.producto_b_id
        WHERE ap.id_vendedor = v_actor
          AND (p_producto_id IS NULL
               OR ap.producto_a_id = p_producto_id
               OR ap.producto_b_id = p_producto_id)
          AND ap.tipo_correlacion = p_tipo
        ORDER BY ap.lift DESC, ap.frecuencia DESC
        LIMIT p_limit
    ) t;

    RETURN jsonb_build_object(
        'fuente','sql_cache',
        'plan',coalesce(v_plan_cod,'bronze'),
        'tipo',p_tipo,
        'datos',coalesce(v_result,'[]')
    );
END;
$_$;


--
-- Name: seller_get_analytics_billetera(date, date, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_analytics_billetera(p_desde date DEFAULT (CURRENT_DATE - 30), p_hasta date DEFAULT CURRENT_DATE, p_tipo_periodo text DEFAULT 'dia'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor_id uuid;
    v_limites  jsonb;
    v_rows     jsonb;
BEGIN
    v_actor_id := auth.fn_current_user_id();

    v_limites := auth.fn_get_wallet_limits(v_actor_id);
    IF NOT COALESCE((v_limites ->> 'analytics_billetera')::boolean, false) THEN
        RETURN jsonb_build_object(
            'error',  'plan_insuficiente', 'codigo', 'WALLET_060',
            'detalle', 'Analytics de billetera requiere plan Silver o superior'
        );
    END IF;

    SELECT jsonb_agg(jsonb_build_object(
        'periodo',              ba.periodo,
        'total_ganado',         ba.total_ganado,
        'total_canjeado',       ba.total_canjeado,
        'total_expirado',       ba.total_expirado,
        'total_transferido_out',ba.total_transferido_out,
        'total_transferido_in', ba.total_transferido_in,
        'total_cashback',       ba.total_cashback,
        'num_movimientos',      ba.num_movimientos,
        'saldo_neto_periodo',
            ba.total_ganado + ba.total_transferido_in + ba.total_cashback
            - ba.total_canjeado - ba.total_expirado - ba.total_transferido_out
    ) ORDER BY ba.periodo ASC)
    INTO v_rows
    FROM auth.billetera_analytics ba
    WHERE ba.id_usuario = v_actor_id
      AND ba.tipo_periodo = p_tipo_periodo
      AND ba.periodo BETWEEN p_desde AND p_hasta;

    -- Resumen del período
    RETURN jsonb_build_object(
        'periodos',           COALESCE(v_rows, '[]'::jsonb),
        'totales', (
            SELECT jsonb_build_object(
                'total_ganado',         COALESCE(SUM(total_ganado), 0),
                'total_canjeado',       COALESCE(SUM(total_canjeado), 0),
                'total_expirado',       COALESCE(SUM(total_expirado), 0),
                'total_cashback',       COALESCE(SUM(total_cashback), 0),
                'num_movimientos',      COALESCE(SUM(num_movimientos), 0)
            )
            FROM auth.billetera_analytics
            WHERE id_usuario = v_actor_id
              AND tipo_periodo = p_tipo_periodo
              AND periodo BETWEEN p_desde AND p_hasta
        ),
        'rango', jsonb_build_object('desde', p_desde, 'hasta', p_hasta)
    );
END;
$$;


--
-- Name: seller_get_analytics_ubicaciones(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_analytics_ubicaciones(p_dias integer DEFAULT 30) RETURNS TABLE(id_ubicacion uuid, nombre text, tipo text, total_vistas bigint, total_rutas bigint, total_consultas bigint, total_ordenes bigint, conversion_pct numeric, ultimo_evento timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_user_id uuid := (nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid;
  v_limits  jsonb;
BEGIN
  v_limits := auth.fn_get_location_limits(v_user_id);
  IF NOT (v_limits->>'analytics_ubicacion')::boolean THEN
    RAISE EXCEPTION 'feature_requiere_plan_silver_o_superior';
  END IF;

  RETURN QUERY
  SELECT
    loc.id,
    loc.nombre,
    loc.tipo,
    COUNT(*) FILTER (WHERE a.tipo_evento = 'vista_perfil')    AS total_vistas,
    COUNT(*) FILTER (WHERE a.tipo_evento = 'ruta_iniciada')   AS total_rutas,
    COUNT(*) FILTER (WHERE a.tipo_evento = 'consulta_enviada') AS total_consultas,
    COUNT(*) FILTER (WHERE a.tipo_evento = 'orden_generada')  AS total_ordenes,
    CASE
      WHEN COUNT(*) FILTER (WHERE a.tipo_evento = 'vista_perfil') > 0
      THEN ROUND(
        100.0 * COUNT(*) FILTER (WHERE a.tipo_evento = 'orden_generada') /
        NULLIF(COUNT(*) FILTER (WHERE a.tipo_evento = 'vista_perfil'), 0),
        2)
      ELSE 0
    END AS conversion_pct,
    MAX(a.fecha_creacion) AS ultimo_evento
  FROM auth.ubicaciones loc
  LEFT JOIN auth.ubicacion_analytics a
    ON a.id_ubicacion = loc.id
    AND a.fecha_creacion >= now() - (p_dias || ' days')::interval
  WHERE loc.id_usuario = v_user_id
    AND loc.fecha_eliminacion IS NULL
  GROUP BY loc.id, loc.nombre, loc.tipo
  ORDER BY total_ordenes DESC, total_vistas DESC;
END;
$$;


--
-- Name: seller_get_analytics_visitas_perfil(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_analytics_visitas_perfil(p_desde timestamp with time zone DEFAULT (now() - '30 days'::interval), p_hasta timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
BEGIN
  v_actor := auth.current_jwt_user_id();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'actor_no_autenticado'; END IF;

  -- CF-5: requiere Silver+
  IF NOT auth.fn_get_feature_flag(v_actor, 'perfil_analytics') THEN
    RAISE EXCEPTION 'feature_not_available_for_plan'
      USING HINT = 'Requiere membresía Silver o superior';
  END IF;

  RETURN (
    SELECT jsonb_build_object(
      'total_visitas',          COUNT(*),
      'visitantes_unicos',      COUNT(DISTINCT visitor_hash),
      'por_fuente', jsonb_object_agg(
        fuente, cnt
      ),
      'por_dia', jsonb_agg(
        jsonb_build_object('fecha', dia, 'visitas', visitas)
        ORDER BY dia
      )
    )
    FROM (
      SELECT
        fuente,
        COUNT(*) AS cnt,
        date_trunc('day', fecha) AS dia,
        COUNT(*) OVER (PARTITION BY date_trunc('day', fecha)) AS visitas
      FROM auth.perfil_visitas_analytics
      WHERE id_vendedor = v_actor
        AND fecha BETWEEN p_desde AND p_hasta
      GROUP BY fuente, dia
    ) sub
  );
END;
$$;


--
-- Name: seller_get_beneficios_disponibles(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_beneficios_disponibles() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor_id uuid;
    v_saldo    numeric;
    v_rows     jsonb;
BEGIN
    v_actor_id := auth.fn_current_user_id();

    SELECT saldo INTO v_saldo
    FROM auth.billetera WHERE id_usuario = v_actor_id;

    SELECT jsonb_agg(jsonb_build_object(
        'id',                  bc.id,
        'codigo',              bc.codigo,
        'nombre',              bc.nombre,
        'descripcion',         bc.descripcion,
        'costo_puntos',        bc.costo_puntos,
        'tasa_conversion_mxn', bc.tasa_conversion_mxn,
        'puede_canjear',       (COALESCE(v_saldo, 0) >= bc.costo_puntos),
        'mxn_equivalente',
            CASE WHEN bc.tasa_conversion_mxn IS NOT NULL
                 THEN bc.costo_puntos * bc.tasa_conversion_mxn
                 ELSE NULL END
    ) ORDER BY bc.costo_puntos ASC)
    INTO v_rows
    FROM auth.beneficios_catalogo bc
    WHERE bc.activo = true;

    RETURN jsonb_build_object(
        'beneficios', COALESCE(v_rows, '[]'::jsonb),
        'saldo_actual', COALESCE(v_saldo, 0)
    );
END;
$$;


--
-- Name: seller_get_billetera(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_billetera() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor_id uuid;
    v_result   jsonb;
BEGIN
    v_actor_id := auth.fn_current_user_id();

    SELECT jsonb_build_object(
        'saldo',                       b.saldo,
        'moneda',                      b.moneda,
        'activo',                      b.activo,
        'puntos_acumulados_historico', b.puntos_acumulados_historico,
        'nivel_codigo',                nl.codigo,
        'nivel_nombre',                nl.nombre,
        'nivel_color',                 nl.color_hex,
        'multiplicador_ganancia',      nl.multiplicador_ganancia,
        'progreso_siguiente_nivel',
            CASE WHEN nl.puntos_maximos IS NULL THEN 100
                 ELSE ROUND(
                     (b.puntos_acumulados_historico - nl.puntos_minimos)::numeric /
                     NULLIF(nl.puntos_maximos - nl.puntos_minimos, 0) * 100, 1
                 )
            END,
        'puntos_por_expirar_30d',
            (SELECT COALESCE(SUM(ABS(monto)), 0)
             FROM auth.movimientos_puntos
             WHERE id_usuario = v_actor_id
               AND expira_en BETWEEN now() AND now() + INTERVAL '30 days'
               AND tipo_movimiento IN ('ganado_venta', 'ganado_bienvenida', 'cashback')),
        'wallet_limits', auth.fn_get_wallet_limits(v_actor_id)
    ) INTO v_result
    FROM auth.billetera b
    LEFT JOIN auth.niveles_lealtad nl ON nl.id = b.nivel_lealtad_id
    WHERE b.id_usuario = v_actor_id;

    IF v_result IS NULL THEN
        RETURN jsonb_build_object('error', 'billetera_no_encontrada', 'codigo', 'WALLET_001');
    END IF;
    RETURN v_result;
END;
$$;


--
-- Name: seller_get_campana_geo_metricas(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_campana_geo_metricas(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
             'id', c.id, 'nombre', c.nombre, 'tipo_incentivo', c.tipo_incentivo,
             'valor_incentivo', c.valor_incentivo, 'estado', c.estado,
             'max_conversiones', c.max_conversiones, 'presupuesto_puntos', c.presupuesto_puntos,
             'radio_metros', c.segmento_objetivo->>'radio_metros',
             'fecha_inicio', c.fecha_inicio, 'fecha_fin', c.fecha_fin,
             'eventos', COALESCE(ev.n, 0))
           ORDER BY c.fecha_inicio DESC NULLS LAST)
      FROM auth.campanias_vendedor c
      LEFT JOIN LATERAL (
        SELECT count(*) AS n FROM auth.eventos_campania e WHERE e.campania_id = c.id
      ) ev ON true
     WHERE c.id_vendedor = p_id_vendedor
  ), '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END;
$$;


--
-- Name: seller_get_cercanos_desde_graph(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_cercanos_desde_graph(p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'ag_catalog'
    AS $$
DECLARE v_res jsonb;
BEGIN
  LOAD 'age';
  SET LOCAL search_path = ag_catalog, public, pg_temp;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id_zona_a', agtype_to_json(a.properties)->>'id_zona',
           'id_zona_b', agtype_to_json(b.properties)->>'id_zona',
           'zona_a', agtype_to_json(a.properties)->>'name',
           'zona_b', agtype_to_json(b.properties)->>'name')
         ORDER BY agtype_to_json(a.properties)->>'name'), '[]'::jsonb)
    INTO v_res
    FROM smtp_posix_graph."NEAR" e
    JOIN smtp_posix_graph."Zona" a ON a.id = e.start_id
    JOIN smtp_posix_graph."Zona" b ON b.id = e.end_id
    LEFT JOIN public.geo_zones gz
      ON gz.id_zona::text = agtype_to_json(a.properties)->>'id_zona'
   WHERE p_id_vendedor IS NULL OR gz.metadata->>'id_vendedor' = p_id_vendedor::text;
  RETURN v_res;
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: seller_get_chatbot_stats(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_chatbot_stats() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_actor uuid := auth.uid();
BEGIN
    RETURN (
        SELECT jsonb_build_object(
            'total_reglas',      COUNT(DISTINCT r.id),
            'total_respuestas',  COUNT(cl.id),
            'respuestas_7d',     COUNT(cl.id) FILTER (WHERE cl.fecha_creacion >= now() - interval '7 days'),
            'tasa_escalamiento', ROUND(
                COUNT(cl.id) FILTER (WHERE cl.escalado)::numeric /
                NULLIF(COUNT(cl.id), 0) * 100, 2
            ),
            'regla_mas_usada',   (
                SELECT jsonb_build_object('id', r2.id, 'patron', r2.patron, 'usos', r2.usos_count)
                FROM auth.chatbot_reglas r2
                WHERE r2.id_vendedor = v_actor AND r2.activa = true
                ORDER BY r2.usos_count DESC LIMIT 1
            )
        )
        FROM auth.chatbot_reglas r
        LEFT JOIN auth.chatbot_log cl ON cl.regla_id = r.id
        WHERE r.id_vendedor = v_actor
    );
END;
$$;


--
-- Name: seller_get_churn_risk(text, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_churn_risk(p_nivel text DEFAULT 'alto'::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor  uuid;
    v_result jsonb;
BEGIN
    v_actor := auth.fn_current_user_id();

    -- RN-011: Feature flag acceso_churn (Gold+)
    IF NOT auth.fn_get_feature_flag(v_actor, 'acceso_churn') THEN
        RAISE EXCEPTION 'feature_not_available_for_plan'
            USING DETAIL = 'acceso_churn requiere plan Gold o superior',
                  ERRCODE = '42501';
    END IF;

    -- Validar nivel
    IF p_nivel NOT IN ('bajo','medio','alto','critico','todos') THEN
        RAISE EXCEPTION 'nivel_riesgo_invalido' USING ERRCODE = '22023';
    END IF;

    -- FA-7: recalcular heurístico local con regresión PostgreSQL
    -- RN-012: modelo v2_regr_local usa regr_slope sobre intervalos entre compras
    INSERT INTO auth.churn_predictions (
        id_vendedor, id_comprador,
        probabilidad_churn, nivel_riesgo, dias_sin_compra,
        tendencia_monto, tendencia_frecuencia, r2_confianza,
        modelo_version, features_jsonb
    )
    SELECT
        v_actor,
        id_comprador,
        -- Probabilidad basada en recencia + tendencia
        LEAST(0.99, GREATEST(0.01,
            CASE
                WHEN dias > 180 THEN 0.92
                WHEN dias > 120 THEN 0.72
                WHEN dias > 60  THEN 0.42
                ELSE 0.12
            END
            -- Ajuste por tendencia de monto negativa
            + CASE WHEN slope_monto < 0 THEN 0.08 ELSE 0 END
        ))::numeric(5,4),
        CASE
            WHEN dias > 180 THEN 'critico'
            WHEN dias > 120 THEN 'alto'
            WHEN dias > 60  THEN 'medio'
            ELSE 'bajo'
        END,
        dias,
        slope_monto,
        slope_intervalo,
        r2_val,
        'v2_regr_local',
        jsonb_build_object(
            'dias_sin_compra',   dias,
            'total_ordenes',     total_ord,
            'monto_total',       monto,
            'slope_monto',       slope_monto,
            'slope_intervalo',   slope_intervalo,
            'r2',                r2_val
        )
    FROM (
        SELECT
            id_comprador,
            EXTRACT(DAY FROM (now() - MAX(fecha_creacion)))::integer AS dias,
            COUNT(*)::integer                                         AS total_ord,
            SUM(total)                                                AS monto,
            -- regr_slope de montos vs número de orden (tendencia creciente=positivo)
            regr_slope(total::float8, ROW_NUMBER() OVER (
                PARTITION BY id_comprador ORDER BY fecha_creacion
            )::float8)                                                AS slope_monto,
            -- regr_slope de intervalos entre compras vs orden (crece=se aleja más)
            regr_slope(
                EXTRACT(DAY FROM (fecha_creacion -
                    LAG(fecha_creacion) OVER (PARTITION BY id_comprador ORDER BY fecha_creacion)
                ))::float8,
                ROW_NUMBER() OVER (
                    PARTITION BY id_comprador ORDER BY fecha_creacion
                )::float8
            )                                                         AS slope_intervalo,
            COALESCE(regr_r2(total::float8, ROW_NUMBER() OVER (
                PARTITION BY id_comprador ORDER BY fecha_creacion
            )::float8), 0)                                            AS r2_val
        FROM auth.ordenes
        WHERE id_vendedor = v_actor AND estado = 'confirmada'
        GROUP BY id_comprador
    ) sq
    ON CONFLICT (id_vendedor, id_comprador)
    DO UPDATE SET
        probabilidad_churn   = EXCLUDED.probabilidad_churn,
        nivel_riesgo         = EXCLUDED.nivel_riesgo,
        dias_sin_compra      = EXCLUDED.dias_sin_compra,
        tendencia_monto      = EXCLUDED.tendencia_monto,
        tendencia_frecuencia = EXCLUDED.tendencia_frecuencia,
        r2_confianza         = EXCLUDED.r2_confianza,
        features_jsonb       = EXCLUDED.features_jsonb,
        calculado_en         = now();

    -- Retornar lista filtrada
    SELECT jsonb_agg(row_to_json(t)) INTO v_result
    FROM (
        SELECT
            cp.id_comprador,
            up.nombre       AS nombre,
            cp.probabilidad_churn,
            cp.nivel_riesgo,
            cp.dias_sin_compra,
            cp.tendencia_monto,
            cp.r2_confianza,
            cp.modelo_version,
            cp.calculado_en
        FROM auth.churn_predictions cp
        JOIN auth.user_profiles up ON up.id_usuario = cp.id_comprador
        WHERE cp.id_vendedor = v_actor
          AND (p_nivel = 'todos' OR cp.nivel_riesgo IN (p_nivel, 'critico'))
        ORDER BY cp.probabilidad_churn DESC
        LIMIT LEAST(p_limit, 100)
    ) t;

    RETURN jsonb_build_object(
        'nivel_filtro', p_nivel,
        'modelo',       'v2_regr_local',
        'calculado_en', now(),
        'datos',        coalesce(v_result, '[]'::jsonb)
    );
END;
$$;


--
-- Name: seller_get_clientes_frecuentes(integer, boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_clientes_frecuentes(p_limit integer DEFAULT 20, p_use_age boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $_$
DECLARE
    v_actor       uuid;
    v_plan_codigo text;
    v_limit_real  integer;
    v_result      jsonb;
    v_graph_name  text;
BEGIN
    -- RN-001: Actor siempre desde JWT, nunca parámetro frontend
    v_actor := auth.fn_current_user_id();

    -- RN-002: Verificar que es seller activo
    IF NOT EXISTS (
        SELECT 1 FROM auth.users
        WHERE id = v_actor AND role = 'seller'
          AND is_verified = true AND (activo IS NOT FALSE) AND fecha_eliminacion IS NULL
    ) THEN
        RAISE EXCEPTION 'seller_not_active' USING ERRCODE = '42501';
    END IF;

    -- RN-003: Obtener plan membresía para límite de registros
    SELECT pm.codigo INTO v_plan_codigo
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.id_vendedor = v_actor
      AND mv.estado IN ('activa','trial')
    ORDER BY mv.ciclo_fin DESC LIMIT 1;

    -- RN-004: Límite diferenciado por plan
    v_limit_real := CASE
        WHEN v_plan_codigo IN ('gold','platinum') THEN LEAST(p_limit, 100)
        WHEN v_plan_codigo = 'silver'             THEN LEAST(p_limit, 20)
        ELSE 5  -- bronze o sin membresía activa
    END;

    -- RN-005: Intentar AGE con degradación elegante; edge canónico = COMPRO_EN
    IF p_use_age THEN
        BEGIN
            SELECT name INTO v_graph_name FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;

            IF v_graph_name IS NOT NULL THEN
                EXECUTE format(
                    $age$
                    SELECT jsonb_agg(row_to_json(t))
                    FROM (
                        SELECT * FROM cypher(%L, $c$
                            MATCH (b:Buyer)-[r:COMPRO_EN]->(s:Seller {id_usuario: %L})
                            RETURN
                                b.id_usuario       AS id_comprador,
                                b.nombre        AS nombre,
                                r.total_ordenes AS ordenes,
                                r.total   AS monto,
                                r.ultima_compra AS ultima_compra,
                                r.calificacion_avg AS calificacion
                            ORDER BY r.total_ordenes DESC
                            LIMIT %s
                        $c$) AS (
                            id_comprador agtype, nombre agtype,
                            ordenes agtype, monto agtype,
                            ultima_compra agtype, calificacion agtype
                        )
                    ) t
                    $age$,
                    v_graph_name, v_actor::text, v_limit_real
                ) INTO v_result;

                IF v_result IS NOT NULL AND jsonb_array_length(v_result) > 0 THEN
                    RETURN jsonb_build_object(
                        'fuente',       'age_graph',
                        'limite_plan',  v_limit_real,
                        'plan',         coalesce(v_plan_codigo, 'bronze'),
                        'datos',        v_result
                    );
                END IF;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            NULL; -- FA-2: degradación elegante → fallback SQL
        END;
    END IF;

    -- FA-2 / Fallback SQL: ordenes + user_profiles + resenas
    SELECT jsonb_agg(row_to_json(t)) INTO v_result
    FROM (
        SELECT
            o.id_comprador                          AS id_comprador,
            up.nombre                           AS nombre,
            COUNT(*)::integer                       AS ordenes,
            SUM(o.total)                            AS monto,
            MAX(o.fecha_creacion)                   AS ultima_compra,
            COALESCE(ROUND(AVG(r.calificacion)::numeric, 2), 0) AS calificacion
        FROM auth.ordenes o
        JOIN auth.user_profiles up ON up.id_usuario = o.id_comprador
        LEFT JOIN auth.resenas r
            ON r.id_orden = o.id AND r.id_vendedor = v_actor
        WHERE o.id_vendedor = v_actor
          AND o.estado = 'confirmada'
        GROUP BY o.id_comprador, up.nombre
        ORDER BY COUNT(*) DESC
        LIMIT v_limit_real
    ) t;

    RETURN jsonb_build_object(
        'fuente',       'sql_fallback',
        'limite_plan',  v_limit_real,
        'plan',         coalesce(v_plan_codigo, 'bronze'),
        'datos',        coalesce(v_result, '[]'::jsonb)
    );
END;
$_$;


--
-- Name: seller_get_compradores_cercanos(uuid, double precision); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_compradores_cercanos(p_id_vendedor uuid, p_radio_metros double precision DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_punto geography; v_res jsonb;
BEGIN
  SELECT punto INTO v_punto FROM auth.ubicaciones
   WHERE id_usuario = p_id_vendedor AND is_active = true
   ORDER BY es_principal DESC, is_merchant_spot DESC LIMIT 1;
  IF v_punto IS NULL THEN
    RETURN jsonb_build_object('error', 'vendedor sin ubicación activa');
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id_comprador', ub.id_usuario, 'nombre', u.nombre_visible,
           'distancia_m', ROUND(ST_Distance(v_punto, ub.punto)::numeric, 1),
           'latitud', ub.latitud, 'longitud', ub.longitud)
         ORDER BY ST_Distance(v_punto, ub.punto)), '[]'::jsonb)
    INTO v_res
    FROM auth.ubicaciones ub
    JOIN auth.users u ON u.id = ub.id_usuario
   WHERE u.role = 'buyer' AND ub.is_active = true
     AND ST_DWithin(v_punto, ub.punto, p_radio_metros);
  RETURN v_res;
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: seller_get_comunidades_compradores(integer, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_comunidades_compradores(p_num_clusters integer DEFAULT 4, p_algoritmo text DEFAULT 'rfm_quartil'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor    uuid;
    v_result   jsonb;
    v_max_snap date;
BEGIN
    v_actor := auth.fn_current_user_id();

    -- RN-013: Feature flag acceso_churn habilita comunidades (Gold)
    IF NOT auth.fn_get_feature_flag(v_actor, 'acceso_churn') THEN
        RAISE EXCEPTION 'feature_not_available_for_plan' USING ERRCODE = '42501';
    END IF;

    -- RN-014: Validar algoritmo permitido (local únicamente)
    IF p_algoritmo NOT IN ('rfm_quartil','kmeans_postgis','heuristico_sql') THEN
        RAISE EXCEPTION 'algoritmo_no_disponible'
            USING DETAIL = 'Algoritmos locales: rfm_quartil, kmeans_postgis, heuristico_sql',
                  ERRCODE = '22023';
    END IF;

    -- FA-8: Si < 10 compradores, no aplica clustering
    SELECT MAX(snapshot_date) INTO v_max_snap
    FROM auth.rfm_snapshots WHERE id_vendedor = v_actor;

    IF (SELECT COUNT(DISTINCT id_comprador) FROM auth.rfm_snapshots
        WHERE id_vendedor = v_actor AND snapshot_date = v_max_snap) < 10 THEN
        RETURN jsonb_build_object(
            'error',   'insufficient_buyers',
            'mensaje', 'Se requieren al menos 10 compradores para clustering',
            'datos',   '[]'::jsonb
        );
    END IF;

    -- CF-010-A Local: Clustering por cuartiles RFM (no requiere extensión externa)
    IF p_algoritmo = 'rfm_quartil' THEN
        INSERT INTO auth.buyer_comunidades (
            id_vendedor, comunidad_id, id_comprador, algoritmo, score_pertenencia
        )
        SELECT
            v_actor,
            -- Cluster 0=alto_valor, 1=leal, 2=riesgo, 3=inactivo
            CASE
                WHEN score_rfm >= percentil_75 THEN 0
                WHEN score_rfm >= percentil_50 THEN 1
                WHEN score_rfm >= percentil_25 THEN 2
                ELSE 3
            END               AS comunidad_id,
            id_comprador,
            'rfm_quartil',
            score_rfm / 100.0 AS score_pertenencia
        FROM (
            SELECT
                id_comprador,
                score_rfm,
                PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY score_rfm)
                    OVER (PARTITION BY id_vendedor) AS percentil_75,
                PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY score_rfm)
                    OVER (PARTITION BY id_vendedor) AS percentil_50,
                PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY score_rfm)
                    OVER (PARTITION BY id_vendedor) AS percentil_25
            FROM auth.rfm_snapshots
            WHERE id_vendedor = v_actor AND snapshot_date = v_max_snap
        ) rfm_data
        ON CONFLICT (id_vendedor, id_comprador, algoritmo)
        DO UPDATE SET
            comunidad_id     = EXCLUDED.comunidad_id,
            score_pertenencia = EXCLUDED.score_pertenencia,
            calculado_en     = now();
    END IF;

    -- CF-010-A Local (geo): ST_ClusterKMeans si compradores tienen ubicación
    IF p_algoritmo = 'kmeans_postgis' THEN
        INSERT INTO auth.buyer_comunidades (
            id_vendedor, comunidad_id, id_comprador, algoritmo,
            centroide_lat, centroide_lon, score_pertenencia
        )
        SELECT
            v_actor,
            ST_ClusterKMeans(u.punto, LEAST(p_num_clusters, 8))
                OVER (PARTITION BY o.id_vendedor) AS comunidad_id,
            o.id_comprador                         AS id_comprador,
            'kmeans_postgis',
            ST_Y(u.punto::geometry)                AS centroide_lat,
            ST_X(u.punto::geometry)                AS centroide_lon,
            1.0
        FROM (
            SELECT DISTINCT id_comprador, id_vendedor
            FROM auth.ordenes
            WHERE id_vendedor = v_actor AND estado = 'confirmada'
        ) o
        JOIN auth.ubicaciones u ON u.id_usuario = o.id_comprador AND u.estado = 'activo'
        WHERE u.punto IS NOT NULL
        ON CONFLICT (id_vendedor, id_comprador, algoritmo)
        DO UPDATE SET
            comunidad_id  = EXCLUDED.comunidad_id,
            centroide_lat = EXCLUDED.centroide_lat,
            centroide_lon = EXCLUDED.centroide_lon,
            calculado_en  = now();
    END IF;

    -- Retornar resumen de comunidades
    SELECT jsonb_agg(row_to_json(t)) INTO v_result
    FROM (
        SELECT
            comunidad_id,
            algoritmo,
            COUNT(*)                              AS compradores,
            ROUND(AVG(score_pertenencia)::numeric, 4) AS cohesion_promedio,
            MAX(calculado_en)                     AS calculado_en
        FROM auth.buyer_comunidades
        WHERE id_vendedor = v_actor AND algoritmo = p_algoritmo
        GROUP BY comunidad_id, algoritmo
        ORDER BY compradores DESC
    ) t;

    RETURN jsonb_build_object(
        'algoritmo',      p_algoritmo,
        'num_clusters',   p_num_clusters,
        'snapshot_date',  v_max_snap,
        'comunidades',    coalesce(v_result, '[]'::jsonb)
    );
END;
$$;


--
-- Name: seller_get_consultas_escaladas(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_consultas_escaladas() RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_actor uuid := auth.uid();
BEGIN
    RETURN QUERY
    SELECT jsonb_build_object(
        'escalada_id',       ce.id,
        'conversacion_id',   ce.id_conversacion,
        'consulta_id',       ce.consulta_servicio_id,
        'estado_consulta',   cs.estado,
        'tipo_consulta',     cs.tipo,
        'prioridad',         cs.prioridad,
        'motivo',            ce.motivo_escalamiento,
        'estado_sync',       ce.estado_sync,
        'escalado_at',       ce.fecha_creacion
    )
    FROM auth.consultas_escaladas ce
    JOIN auth.consultas_servicio cs ON cs.id = ce.consulta_servicio_id
    JOIN auth.conversaciones c ON c.id = ce.id_conversacion
    WHERE c.id_vendedor = v_actor
    ORDER BY ce.fecha_creacion DESC;
END;
$$;


--
-- Name: seller_get_correlaciones_negativas(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_correlaciones_negativas() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor  uuid;
    v_result jsonb;
BEGIN
    v_actor := auth.fn_current_user_id();

    SELECT jsonb_agg(row_to_json(t)) INTO v_result
    FROM (
        SELECT
            pa.nombre AS producto_a,
            pb.nombre AS producto_b,
            ap.lift, ap.confianza, ap.frecuencia,
            'Estos productos rara vez se compran juntos — evitar bundlearlos' AS recomendacion
        FROM auth.afinidad_productos ap
        JOIN auth.productos pa ON pa.id = ap.producto_a_id
        JOIN auth.productos pb ON pb.id = ap.producto_b_id
        WHERE ap.id_vendedor = v_actor
          AND ap.tipo_correlacion = 'negativa'
        ORDER BY ap.lift ASC
        LIMIT 20
    ) t;

    RETURN jsonb_build_object(
        'correlaciones_negativas', coalesce(v_result,'[]'),
        'descripcion', 'Productos con lift < 0.8: comprarlos juntos ocurre menos de lo esperado'
    );
END;
$$;


--
-- Name: seller_get_export_estado(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_export_estado(p_exportacion_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_vid uuid := auth.uid();
    v_rec record;
BEGIN
    SELECT * INTO v_rec
    FROM auth.exportaciones_historial
    WHERE id = p_exportacion_id
      AND id_vendedor = v_vid;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Exportación no encontrada o sin permisos'
            USING ERRCODE = 'P0045';
    END IF;

    RETURN jsonb_build_object(
        'exportacion_id',  v_rec.id,
        'estado',          v_rec.estado,
        'ruta_local',      v_rec.ruta_local,
        'filas_exportadas',v_rec.filas_exportadas,
        'error_detalle',   v_rec.error_detalle,
        'solicitado_at',   v_rec.solicitado_at,
        'procesado_at',    v_rec.procesado_at,
        'expira_at',       v_rec.expira_at
    );
END;
$$;


--
-- Name: seller_get_forecast_inventario(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_forecast_inventario() RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := auth.fn_current_user_id();
    v_limits jsonb;
BEGIN
    v_limits := auth.fn_get_inventory_limits(v_actor);
    IF (v_limits ->> 'inventory_forecasting')::boolean IS NOT TRUE THEN
        RAISE EXCEPTION 'Forecasting de inventario solo disponible para Gold';
    END IF;

    PERFORM auth.fn_calcular_forecast_inventario(v_actor)
    WHERE NOT EXISTS (
        SELECT 1 FROM auth.inventario_forecast
        WHERE id_vendedor = v_actor AND calculado_en > now() - interval '6 hours'
    );

    RETURN QUERY
    SELECT jsonb_build_object(
        'producto_id', f.id_producto,
        'producto_nombre', p.nombre,
        'dias_para_agotamiento', f.dias_para_agotamiento,
        'tasa_consumo_diaria', f.tasa_consumo_diaria,
        'stock_actual', f.stock_actual,
        'r2_ajuste', f.r2_ajuste,
        'puntos_datos', f.puntos_datos,
        'confianza', f.confianza,
        'recomendacion', f.recomendacion,
        'calculado_en', f.calculado_en
    )
    FROM auth.inventario_forecast f
    JOIN auth.productos p ON p.id = f.id_producto
    WHERE f.id_vendedor = v_actor
    ORDER BY COALESCE(f.dias_para_agotamiento, 9999);
END;
$$;


--
-- Name: seller_get_geo_fence_events(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_geo_fence_events(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
             'id',             e.id,
             'id_orden',       e.id_orden,
             'id_comprador',   e.id_comprador,
             'capture_source', e.capture_source,
             'fecha_captura',  e.fecha_captura
           ) ORDER BY e.fecha_captura DESC)
      FROM public.order_geo_evidence e
     WHERE e.id_vendedor = p_id_vendedor
  ), '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: seller_get_heatmap_demanda(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_heatmap_demanda(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN COALESCE((
    WITH grp AS (
      SELECT ST_Centroid(ST_Collect(o.location_delivery)) AS centroid,
             count(*) AS n, COALESCE(sum(o.total), 0) AS total
        FROM auth.ordenes o
       WHERE o.id_vendedor = p_id_vendedor
         AND o.estado = 'completada' AND o.fecha_eliminacion IS NULL
         AND o.location_delivery IS NOT NULL
       GROUP BY ST_SnapToGrid(o.location_delivery, 0.01)
    )
    SELECT jsonb_agg(jsonb_build_object(
             'lng', ROUND(ST_X(centroid)::numeric, 4),
             'lat', ROUND(ST_Y(centroid)::numeric, 4),
             'centroid', ST_AsGeoJSON(centroid)::jsonb,
             'ordenes', n, 'total', total)
           ORDER BY n DESC)
      FROM grp
  ), '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: seller_get_historial_membresia(integer, timestamp with time zone); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_historial_membresia(p_limit integer DEFAULT 20, p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid;
    v_rows  jsonb;
BEGIN
    v_actor := auth.fn_current_user_id();

    SELECT jsonb_agg(
        jsonb_build_object(
            'id',            h.id,
            'evento',        h.evento,
            'plan_anterior', h.plan_anterior,
            'plan_nuevo',    h.plan_nuevo,
            'motivo',        h.motivo,
            'metadata',      h.metadata,
            'created_at',    h.fecha_creacion
        ) ORDER BY h.fecha_creacion DESC
    ) INTO v_rows
    FROM auth.membresias_historial h
    WHERE h.id_vendedor = v_actor
      AND (p_cursor IS NULL OR h.fecha_creacion < p_cursor)
    ORDER BY h.fecha_creacion DESC
    LIMIT LEAST(p_limit, 50);

    RETURN jsonb_build_object(
        'historial',     COALESCE(v_rows, '[]'::jsonb),
        'next_cursor',   (
            SELECT fecha_creacion FROM auth.membresias_historial
            WHERE id_vendedor = v_actor
              AND (p_cursor IS NULL OR fecha_creacion < p_cursor)
            ORDER BY fecha_creacion DESC
            LIMIT 1 OFFSET LEAST(p_limit, 50) - 1
        ),
        'total_returned', COALESCE(jsonb_array_length(v_rows), 0)
    );
END;
$$;


--
-- Name: seller_get_historial_ventas(date, date, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_historial_ventas(p_desde date DEFAULT ((CURRENT_DATE - '30 days'::interval))::date, p_hasta date DEFAULT CURRENT_DATE, p_agrupacion text DEFAULT 'dia'::text) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $_$
DECLARE
    v_vid   uuid := auth.uid();
    v_trunc text;
    v_ts    timestamptz := clock_timestamp();
    v_rows  int := 0;
    v_row   jsonb;
BEGIN
    -- Validar rango
    IF (p_hasta - p_desde) > 366 THEN
        RAISE EXCEPTION 'Rango máximo de consulta: 366 días' USING ERRCODE = 'P0040';
    END IF;

    -- Whitelist de agrupaciones (previene inyección)
    v_trunc := CASE p_agrupacion
        WHEN 'dia'    THEN 'day'
        WHEN 'semana' THEN 'week'
        WHEN 'mes'    THEN 'month'
        WHEN 'anio'   THEN 'year'
        ELSE NULL
    END;
    IF v_trunc IS NULL THEN
        RAISE EXCEPTION 'Agrupación inválida. Use: dia, semana, mes, anio'
            USING ERRCODE = 'P0041';
    END IF;

    -- Servir desde MV (rápido) si agrupación = día
    IF p_agrupacion = 'dia' THEN
        FOR v_row IN
            SELECT jsonb_build_object(
                'periodo',            mv.fecha_venta,
                'total_ordenes',      mv.total_ordenes,
                'ingresos_brutos',    mv.ingresos_brutos,
                'total_descuentos',   mv.total_descuentos,
                'ingresos_netos',     mv.ingresos_netos,
                'compradores_unicos', mv.compradores_unicos,
                'unidades_vendidas',  mv.unidades_vendidas,
                'ticket_promedio',    mv.ticket_promedio,
                'fuente',             'mv_cache'
            )
            FROM auth.mv_ventas_vendedor mv
            WHERE mv.id_vendedor = v_vid
              AND mv.fecha_venta BETWEEN p_desde AND p_hasta
            ORDER BY mv.fecha_venta ASC
        LOOP
            v_rows := v_rows + 1;
            RETURN NEXT v_row;
        END LOOP;

        IF v_rows > 0 THEN
            INSERT INTO auth.superset_audit_log
                (cu_origen, id_vendedor, rpc_nombre, query_ms, resultado_filas, actor_role, tipo_evento, event_payload)
            VALUES ('CU-V-008', v_vid, 'seller_get_historial_ventas',
                    EXTRACT(MILLISECONDS FROM clock_timestamp() - v_ts)::int, v_rows,
                    COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', 'seller'), 'consulta', '{}');
            RETURN;
        END IF;
    END IF;

    -- Fallback: query directo con parámetros $N (sin concatenación de strings de usuario)
    FOR v_row IN
        EXECUTE format($q$
            SELECT jsonb_build_object(
                'periodo',            DATE_TRUNC(%L, o.fecha_creacion)::date,
                'total_ordenes',      COUNT(DISTINCT o.id),
                'ingresos_brutos',    COALESCE(SUM(o.total), 0),
                'total_descuentos',   COALESCE(SUM(oi_agg.total_desc), 0),
                'ingresos_netos',     COALESCE(SUM(o.total), 0) - COALESCE(SUM(oi_agg.total_desc), 0),
                'compradores_unicos', COUNT(DISTINCT o.id_comprador),
                'unidades_vendidas',  COALESCE(SUM(oi_agg.unidades), 0),
                'ticket_promedio',    ROUND(AVG(o.total), 2),
                'fuente',             'query_directo'
            )
            FROM auth.ordenes o
            LEFT JOIN LATERAL (
                SELECT SUM(oi.descuento_monto) AS total_desc,
                       SUM(oi.cantidad)        AS unidades
                FROM auth.orden_items oi
                WHERE oi.id_orden = o.id
            ) oi_agg ON true
            WHERE o.id_vendedor = $1
              AND o.estado = 'confirmada'
              AND o.fecha_creacion::date BETWEEN $2 AND $3
            GROUP BY DATE_TRUNC(%L, o.fecha_creacion)
            ORDER BY DATE_TRUNC(%L, o.fecha_creacion) ASC
        $q$, v_trunc, v_trunc, v_trunc)
        USING v_vid, p_desde, p_hasta
    LOOP
        v_rows := v_rows + 1;
        RETURN NEXT v_row;
    END LOOP;

    INSERT INTO auth.superset_audit_log
        (cu_origen, id_vendedor, rpc_nombre, query_ms, resultado_filas, actor_role, tipo_evento, event_payload)
    VALUES ('CU-V-008', v_vid, 'seller_get_historial_ventas',
            EXTRACT(MILLISECONDS FROM clock_timestamp() - v_ts)::int, v_rows,
                    COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', 'seller'), 'consulta', '{}');
END;
$_$;


--
-- Name: seller_get_horarios_optimos(uuid, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_horarios_optimos(p_ubicacion_id uuid, p_dias_analisis integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_user_id  uuid := (nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid;
  v_limits   jsonb;
  v_horarios jsonb := '{}';
  v_dia      integer;
  v_hora_pico text;
  v_hora_ini  text;
  v_hora_fin  text;
  dia_nombres text[] := ARRAY['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];
BEGIN
  v_limits := auth.fn_get_location_limits(v_user_id);
  IF NOT (v_limits->>'horarios_inteligentes')::boolean THEN
    RAISE EXCEPTION 'feature_requiere_plan_gold_o_superior';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM auth.ubicaciones
    WHERE id = p_ubicacion_id AND id_usuario = v_user_id AND fecha_eliminacion IS NULL
  ) THEN
    RAISE EXCEPTION 'ubicacion_no_encontrada_o_sin_permiso';
  END IF;

  -- Analizar patrones por día de semana y hora
  FOR v_dia IN 0..6 LOOP
    SELECT
      to_char(
        to_timestamp(
          PERCENTILE_CONT(0.15) WITHIN GROUP (
            ORDER BY EXTRACT(HOUR FROM fecha_creacion)
          )::double precision * 3600
        ),
        'HH24:MI'
      ),
      to_char(
        to_timestamp(
          PERCENTILE_CONT(0.85) WITHIN GROUP (
            ORDER BY EXTRACT(HOUR FROM fecha_creacion)
          )::double precision * 3600
        ),
        'HH24:MI'
      )
    INTO v_hora_ini, v_hora_fin
    FROM auth.ubicacion_analytics
    WHERE id_ubicacion = p_ubicacion_id
      AND tipo_evento IN ('vista_perfil','clic_mapa','consulta_enviada')
      AND EXTRACT(DOW FROM fecha_creacion) = v_dia
      AND fecha_creacion >= now() - (p_dias_analisis || ' days')::interval;

    IF v_hora_ini IS NOT NULL THEN
      v_horarios := v_horarios || jsonb_build_object(
        dia_nombres[v_dia + 1],
        jsonb_build_object(
          'apertura_sugerida', v_hora_ini,
          'cierre_sugerido', v_hora_fin,
          'metodo', 'percentil_15_85_eventos',
          'dias_analizados', p_dias_analisis
        )
      );
    END IF;
  END LOOP;

  IF v_horarios = '{}' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'datos_insuficientes',
      'mensaje', 'Se requieren al menos 30 eventos para generar sugerencias'
    );
  END IF;

  RETURN jsonb_build_object('ok', true, 'horarios_sugeridos', v_horarios);
END;
$$;


--
-- Name: seller_get_kpis_tendencia(date, date); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_kpis_tendencia(p_desde date DEFAULT ((CURRENT_DATE - '30 days'::interval))::date, p_hasta date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_vid        uuid := auth.uid();
    v_dias       int  := (p_hasta - p_desde) + 1;
    v_prev_desde date := p_desde - v_dias;
    v_prev_hasta date := p_desde - 1;
    r_actual     record;
    r_previo     record;
BEGIN
    SELECT COUNT(DISTINCT id)           AS ordenes,
           COALESCE(SUM(total), 0)      AS ingresos,
           COUNT(DISTINCT id_comprador) AS compradores
    INTO r_actual
    FROM auth.ordenes
    WHERE id_vendedor = v_vid AND estado = 'confirmada'
      AND fecha_creacion::date BETWEEN p_desde AND p_hasta;

    SELECT COUNT(DISTINCT id)           AS ordenes,
           COALESCE(SUM(total), 0)      AS ingresos,
           COUNT(DISTINCT id_comprador) AS compradores
    INTO r_previo
    FROM auth.ordenes
    WHERE id_vendedor = v_vid AND estado = 'confirmada'
      AND fecha_creacion::date BETWEEN v_prev_desde AND v_prev_hasta;

    RETURN jsonb_build_object(
        'periodo_actual', jsonb_build_object(
            'desde', p_desde, 'hasta', p_hasta,
            'ordenes',       r_actual.ordenes,
            'ingresos',      r_actual.ingresos,
            'compradores',   r_actual.compradores,
            'ticket_promedio', ROUND(
                CASE WHEN r_actual.ordenes > 0
                     THEN r_actual.ingresos / r_actual.ordenes
                     ELSE 0 END, 2)
        ),
        'periodo_previo', jsonb_build_object(
            'desde', v_prev_desde, 'hasta', v_prev_hasta,
            'ordenes',     r_previo.ordenes,
            'ingresos',    r_previo.ingresos,
            'compradores', r_previo.compradores
        ),
        'variacion', jsonb_build_object(
            'ordenes_pct',     ROUND(CASE WHEN r_previo.ordenes > 0
                THEN ((r_actual.ordenes - r_previo.ordenes)::numeric / r_previo.ordenes * 100)
                ELSE NULL END, 1),
            'ingresos_pct',    ROUND(CASE WHEN r_previo.ingresos > 0
                THEN ((r_actual.ingresos - r_previo.ingresos) / r_previo.ingresos * 100)
                ELSE NULL END, 1),
            'compradores_pct', ROUND(CASE WHEN r_previo.compradores > 0
                THEN ((r_actual.compradores - r_previo.compradores)::numeric / r_previo.compradores * 100)
                ELSE NULL END, 1)
        )
    );
END;
$$;


--
-- Name: seller_get_market_basket(numeric, numeric, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_market_basket(p_min_soport numeric DEFAULT 0.02, p_min_conf numeric DEFAULT 0.3, p_top_n integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor    uuid;
    v_plan_cod text;
    v_result   jsonb;
    v_total_tr integer;
BEGIN
    v_actor := auth.fn_current_user_id();

    SELECT pm.codigo INTO v_plan_cod
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.id_vendedor = v_actor AND mv.estado IN ('activo','grace_period')
    LIMIT 1;

    IF coalesce(v_plan_cod,'bronze') != 'gold' THEN
        RAISE EXCEPTION 'Market Basket Analysis completo requiere plan Gold' USING ERRCODE = '42501';
    END IF;

    SELECT COUNT(DISTINCT o.id) INTO v_total_tr
    FROM auth.ordenes o WHERE o.id_vendedor = v_actor AND o.estado = 'confirmada';

    SELECT jsonb_agg(row_to_json(t)) INTO v_result
    FROM (
        SELECT
            pa.nombre AS antecedente,
            pb.nombre AS consecuente,
            ap.frecuencia,
            ROUND((ap.frecuencia::numeric / v_total_tr), 4)  AS soporte,
            ap.confianza, ap.lift,
            CASE
                WHEN ap.lift > 2   THEN 'Muy fuerte'
                WHEN ap.lift > 1.2 THEN 'Fuerte'
                WHEN ap.lift > 0.8 THEN 'Neutral'
                ELSE 'Negativa'
            END AS intensidad,
            'Si compra ' || pa.nombre || ' → ' ||
            ROUND(ap.confianza*100,1)::text || '% prob. de comprar ' || pb.nombre AS insight
        FROM auth.afinidad_productos ap
        JOIN auth.productos pa ON pa.id = ap.producto_a_id
        JOIN auth.productos pb ON pb.id = ap.producto_b_id
        WHERE ap.id_vendedor = v_actor
          AND (ap.frecuencia::numeric / v_total_tr) >= p_min_soport
          AND ap.confianza >= p_min_conf
        ORDER BY ap.lift DESC, ap.confianza DESC
        LIMIT p_top_n
    ) t;

    INSERT INTO auth.market_basket_snapshots (
        id_vendedor, total_transacciones, reglas_count, top_reglas
    ) VALUES (
        v_actor, v_total_tr,
        (SELECT COUNT(*) FROM auth.afinidad_productos
         WHERE id_vendedor = v_actor AND tipo_correlacion = 'positiva'),
        coalesce(v_result,'[]')
    )
    ON CONFLICT (id_vendedor, snapshot_date) DO UPDATE SET
        total_transacciones = EXCLUDED.total_transacciones,
        reglas_count        = EXCLUDED.reglas_count,
        top_reglas          = EXCLUDED.top_reglas;

    RETURN jsonb_build_object(
        'total_transacciones',v_total_tr,
        'min_soporte',p_min_soport,
        'min_confianza',p_min_conf,
        'reglas',coalesce(v_result,'[]')
    );
END;
$$;


--
-- Name: seller_get_market_pulse(double precision); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_market_pulse(p_radius_meters double precision DEFAULT 1200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor_id          uuid;
  v_seller_punto      geography;
  v_is_disponible     boolean;
  v_nearby_buyers     bigint := 0;
  v_active_competitors bigint := 0;
  v_result            jsonb;
BEGIN
  v_actor_id := auth.fn_current_user_id();

  IF auth.fn_current_user_role() <> 'seller' THEN
    RAISE EXCEPTION 'seller_role_required';
  END IF;

  -- RN-002: radio entre 100 m y 5000 m
  IF coalesce(p_radius_meters, 1200) < 100 THEN
    RAISE EXCEPTION 'radio_minimo_100m';
  END IF;
  IF coalesce(p_radius_meters, 1200) > 5000 THEN
    RAISE EXCEPTION 'radio_maximo_5000m';
  END IF;

  -- Obtener ubicación y disponibilidad del vendedor
  SELECT u.punto, ppv.is_disponible
  INTO v_seller_punto, v_is_disponible
  FROM auth.ubicaciones u
  JOIN auth.perfiles_publicos_vendedor ppv ON ppv.id_vendedor = u.id_usuario
  WHERE u.id_usuario = v_actor_id AND u.estado = 'activo'
  ORDER BY u.fecha_actualizacion DESC NULLS LAST LIMIT 1;

  IF v_seller_punto IS NULL THEN
    RAISE EXCEPTION 'ubicacion_operativa_no_encontrada';
  END IF;

  -- Compradores cercanos: usuarios sin productos activos, ubicados en radio, presentes < 30 min
  -- RN-003: solo conteo, sin exponer identidades
  SELECT COUNT(*) INTO v_nearby_buyers
  FROM auth.ubicaciones u
  JOIN auth.users usr ON usr.id = u.id_usuario
  WHERE u.id_usuario <> v_actor_id
    AND u.estado = 'activo'
    AND u.fecha_actualizacion >= now() - interval '30 minutes'
    AND usr.role = 'buyer'
    AND ST_DWithin(u.punto, v_seller_punto, p_radius_meters);

  -- Competidores activos: vendedores disponibles con productos activos en radio
  SELECT COUNT(*) INTO v_active_competitors
  FROM auth.ubicaciones u
  JOIN auth.perfiles_publicos_vendedor ppv ON ppv.id_vendedor = u.id_usuario AND ppv.is_disponible = true
  WHERE u.id_usuario <> v_actor_id
    AND u.estado = 'activo'
    AND u.fecha_actualizacion >= now() - interval '30 minutes'
    AND EXISTS (
      SELECT 1 FROM auth.productos p
      WHERE p.id_vendedor = u.id_usuario
        AND p.activo = true
        AND p.fecha_eliminacion IS NULL
    )
    AND ST_DWithin(u.punto, v_seller_punto, p_radius_meters);

  -- Construir resultado
  v_result := jsonb_build_object(
    'is_disponible',   coalesce(v_is_disponible, false),
    'market_pulse', jsonb_build_object(
      'nearby_buyers',              coalesce(v_nearby_buyers, 0),
      'active_competitors',         coalesce(v_active_competitors, 0),
      'potential_reach_radius_km',  round((p_radius_meters / 1000.0)::numeric, 2)
    ),
    'recent_activity', coalesce(
      (
        SELECT jsonb_agg(x ORDER BY x->>'count' DESC)
        FROM (
          SELECT
            il.tipo_evento AS event,
            COUNT(*)::int  AS count,
            '1h'           AS time_window
          FROM auth.interaction_logs il
          WHERE il.id_objetivo = v_actor_id
            AND il.fecha_creacion >= now() - interval '1 hour'
            AND il.tipo_evento IN ('PROFILE_VIEW','PRODUCT_SAVED','PRODUCT_VIEW','STORE_VIEW')
          GROUP BY il.tipo_evento
        ) x
      ),
      '[]'::jsonb
    ),
    'snapshot_at', now()
  );

  RETURN v_result;
END; $$;


--
-- Name: seller_get_metricas_campana(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_metricas_campana(p_campana_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_vid uuid := (nullif(current_setting('request.jwt.claims', true),'')::jsonb ->> 'sub')::uuid;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM auth.campanas WHERE id = p_campana_id AND id_vendedor = v_vid
    ) THEN
        RAISE EXCEPTION 'Campaña no encontrada' USING ERRCODE = 'P0097';
    END IF;

    RETURN (
        WITH stats AS (
            SELECT
                COUNT(*) FILTER (WHERE evento = 'enviado')    AS enviados,
                COUNT(*) FILTER (WHERE evento = 'visto')      AS vistos,
                COUNT(*) FILTER (WHERE evento = 'click')      AS clicks,
                COUNT(*) FILTER (WHERE evento = 'convertido') AS convertidos,
                COUNT(*) FILTER (WHERE evento = 'rebotado')   AS rebotados,
                COUNT(*) FILTER (WHERE variante_ab = 'control' AND evento = 'convertido') AS conv_control,
                COUNT(*) FILTER (WHERE variante_ab = 'test'    AND evento = 'convertido') AS conv_test,
                COUNT(*) FILTER (WHERE variante_ab = 'control' AND evento = 'enviado')    AS env_control,
                COUNT(*) FILTER (WHERE variante_ab = 'test'    AND evento = 'enviado')    AS env_test
            FROM auth.campana_log WHERE id_campana = p_campana_id
        )
        SELECT jsonb_build_object(
            'campana_id',       p_campana_id,
            'enviados',         s.enviados,
            'vistos',           s.vistos,
            'clicks',           s.clicks,
            'convertidos',      s.convertidos,
            'rebotados',        s.rebotados,
            'tasa_apertura',    ROUND(s.vistos::numeric / NULLIF(s.enviados,0) * 100, 1),
            'tasa_click',       ROUND(s.clicks::numeric / NULLIF(s.vistos,0) * 100, 1),
            'tasa_conversion',  ROUND(s.convertidos::numeric / NULLIF(s.enviados,0) * 100, 1),
            'ab_control_conv',  ROUND(s.conv_control::numeric / NULLIF(s.env_control,0) * 100, 1),
            'ab_test_conv',     ROUND(s.conv_test::numeric / NULLIF(s.env_test,0) * 100, 1)
        )
        FROM stats s
    );
END;
$$;


--
-- Name: seller_get_mi_membresia(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_mi_membresia() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor  uuid;
    v_result jsonb;
BEGIN
    v_actor := auth.fn_current_user_id();

    SELECT jsonb_build_object(
        'membresia', jsonb_build_object(
            'id',               mv.id,
            'estado',           mv.estado,
            'ciclo_pago',       mv.ciclo_pago,
            'fecha_inicio',     mv.fecha_inicio,
            'fecha_expiracion', mv.fecha_expiracion,
            'auto_renovar',     mv.auto_renovar,
            'es_trial',         mv.es_trial,
            'trial_expiracion', mv.trial_expiracion,
            'score_confianza',  mv.score_confianza,
            'descuento_pct',    mv.descuento_anual_pct
        ),
        'plan', jsonb_build_object(
            'codigo',         pm.codigo,
            'nombre',         pm.nombre,
            'precio_mensual', pm.precio_mensual,
            'precio_anual',   pm.precio_anual,
            'max_productos',  pm.max_productos,
            'max_ubicaciones',pm.max_ubicaciones,
            'max_promociones',pm.max_promociones
        ),
        'uso', jsonb_build_object(
            'productos_activos',
                (SELECT COUNT(*) FROM auth.productos WHERE id_vendedor = v_actor AND activo = true),
            'ubicaciones_activas',
                (SELECT COUNT(*) FROM auth.ubicaciones WHERE id_usuario = v_actor AND estado = 'activo'),
            'promociones_activas',
                (SELECT COUNT(*) FROM auth.promociones WHERE creado_por = v_actor AND activo = true),
            'max_productos',   pm.max_productos,
            'max_ubicaciones', pm.max_ubicaciones,
            'max_promociones', pm.max_promociones
        ),
        'feature_flags', pm.feature_flags || mv.override_flags,
        'visibilidad_reducida',
            COALESCE((SELECT visibilidad_reducida FROM auth.perfiles_publicos_vendedor
                      WHERE id_vendedor = v_actor), false),
        'badge',
            COALESCE((SELECT badge_membresia FROM auth.perfiles_publicos_vendedor
                      WHERE id_vendedor = v_actor), 'bronze')
    ) INTO v_result
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.id_vendedor = v_actor
      AND mv.estado IN ('activo', 'grace_period', 'suspendida')
      AND mv.fecha_eliminacion IS NULL
    ORDER BY mv.fecha_creacion DESC
    LIMIT 1;

    RETURN coalesce(v_result, jsonb_build_object(
        'error', 'sin_membresia_activa',
        'hint',  'El vendedor no tiene membresía activa o grace_period'
    ));
END;
$$;


--
-- Name: seller_get_mi_perfil_publico(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_mi_perfil_publico() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_actor  uuid;
  v_payload jsonb;
BEGIN
  v_actor := auth.current_jwt_user_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'actor_no_autenticado';
  END IF;

  SELECT jsonb_build_object(
    'perfil', to_jsonb(pp),
    'identidad', jsonb_build_object(
      'nombre', up.nombre,
      'apellido',  up.apellido,
      'telefono',      up.telefono,
      'avatar_url', up.url_avatar,
      'bio',        up.bio
    ),
    'estadisticas', jsonb_build_object(
      'rating_promedio',          COALESCE(stats.rating_promedio, 0),
      'total_resenas',            COALESCE(stats.total_resenas, 0),
      'total_productos_activos',  COALESCE(stats.total_productos_activos, 0),
      'total_ventas_confirmadas', COALESCE(stats.total_ventas_confirmadas, 0)
    ),
    'membresia', jsonb_build_object(
      'codigo', pm.codigo,
      'estado', mv.estado
    ),
    'verificado',      pp.verificado,
    'verificado_at',   pp.verificado_at,
    'badge_membresia', pp.badge_membresia,
    'ubicacion_principal', CASE
      WHEN loc.id IS NULL THEN NULL
      ELSE jsonb_build_object(
        'id', loc.id, 'latitud', loc.latitud,
        'longitud', loc.longitud, 'estado', loc.estado
      )
    END,
    'miembro_desde', u.fecha_creacion
  )
  INTO v_payload
  FROM auth.users u
  LEFT JOIN auth.user_profiles up ON up.id_usuario = u.id
  LEFT JOIN auth.perfiles_publicos_vendedor pp ON pp.id_vendedor = u.id
  LEFT JOIN auth.membresias_vendedor mv ON mv.id_vendedor = u.id
  LEFT JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
  LEFT JOIN LATERAL (
    SELECT AVG(r.calificacion)::numeric(10,2) AS rating_promedio,
           COUNT(*)::integer AS total_resenas,
           (SELECT COUNT(*)::integer FROM auth.productos p
            WHERE p.id_vendedor = u.id AND p.activo = true AND p.fecha_eliminacion IS NULL)
             AS total_productos_activos,
           (SELECT COUNT(*)::integer FROM auth.ordenes o
            WHERE o.id_vendedor = u.id AND o.estado = 'confirmada')
             AS total_ventas_confirmadas
    FROM auth.resenas r
    WHERE r.id_vendedor = u.id
  ) stats ON true
  LEFT JOIN LATERAL (
    SELECT ub.id, ub.latitud, ub.longitud, ub.estado
    FROM auth.ubicaciones ub
    WHERE ub.id = pp.ubicacion_principal_id
  ) loc ON true
  WHERE u.id = v_actor;

  RETURN COALESCE(v_payload, jsonb_build_object('perfil', NULL));
END;
$$;


--
-- Name: seller_get_mi_reputacion(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_mi_reputacion(p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_actor uuid;
  v_result jsonb;
BEGIN
  v_actor := COALESCE(p_user_id, auth.fn_current_user_id());

  SELECT jsonb_build_object(
    'score_reputacion',ppv.score_reputacion,
    'total_resenas',ppv.total_resenas,
    'resenas_positivas',ppv.resenas_positivas,
    'ultima_actualizacion_score',ppv.ultima_actualizacion_score,
    'distribucion',dist.distribucion,
    'ultimas_resenas',ultimas.resenas)
  INTO v_result
  FROM auth.perfiles_publicos_vendedor ppv
  LEFT JOIN LATERAL (
    SELECT jsonb_object_agg(calificacion::text,cnt) AS distribucion
    FROM (SELECT calificacion,count(*) AS cnt FROM auth.resenas
      WHERE id_vendedor=v_actor GROUP BY calificacion) d) dist ON true
  LEFT JOIN LATERAL (
    SELECT jsonb_agg(jsonb_build_object(
      'calificacion',calificacion,'comentario',comentario,'fecha',fecha_creacion)
      ORDER BY fecha_creacion DESC) AS resenas
    FROM auth.resenas WHERE id_vendedor=v_actor LIMIT 5) ultimas ON true
  WHERE ppv.id_vendedor=v_actor;

  RETURN COALESCE(v_result,'{"error":"perfil_no_encontrado"}');
END;
$$;


--
-- Name: seller_get_mis_bundles(boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_mis_bundles(p_activos_only boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor  uuid;
    v_result jsonb;
BEGIN
    v_actor := auth.fn_current_user_id();

    SELECT jsonb_agg(row_to_json(b)) INTO v_result
    FROM (
        SELECT
            bp.id, bp.nombre, bp.descripcion,
            bp.descuento_pct, bp.activo, bp.fecha_creacion,
            (
                SELECT jsonb_agg(jsonb_build_object(
                    'producto_id',bi.id_producto,
                    'nombre',p.nombre,
                    'precio',p.precio,
                    'cantidad',bi.cantidad
                ))
                FROM auth.bundle_items bi
                JOIN auth.productos p ON p.id = bi.id_producto
                WHERE bi.id_lote = bp.id
            ) AS items
        FROM auth.bundles_producto bp
        WHERE bp.id_vendedor = v_actor
          AND (NOT p_activos_only OR bp.activo = true)
        ORDER BY bp.fecha_creacion DESC
    ) b;

    RETURN jsonb_build_object('bundles', coalesce(v_result,'[]'));
END;
$$;


--
-- Name: seller_get_mis_clusters_ubicaciones(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_mis_clusters_ubicaciones() RETURNS TABLE(id_cluster integer, centroid_lat double precision, centroid_lon double precision, radio_km numeric, num_ubicaciones integer, ubicacion_ids uuid[], calculado_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_user_id uuid := (nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid;
  v_limits  jsonb;
BEGIN
  v_limits := auth.fn_get_location_limits(v_user_id);
  IF NOT (v_limits->>'clusters_geo')::boolean THEN
    RAISE EXCEPTION 'feature_requiere_plan_gold_o_superior';
  END IF;

  RETURN QUERY
  SELECT
    c.id_cluster,
    ST_Y(c.cluster_centroid::geometry)::double precision,
    ST_X(c.cluster_centroid::geometry)::double precision,
    c.radio_km,
    array_length(c.ubicacion_ids, 1),
    c.ubicacion_ids,
    c.calculado_at
  FROM auth.ubicacion_clusters c
  WHERE c.id_usuario = v_user_id
  ORDER BY c.id_cluster;
END;
$$;


--
-- Name: seller_get_mis_conversaciones(integer, integer, boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_mis_conversaciones(p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_solo_no_leidas boolean DEFAULT false) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_vid uuid := auth.uid();
BEGIN
    RETURN QUERY
    SELECT jsonb_build_object(
        'conversacion_id',   c.id,
        'id_comprador',      c.id_comprador,
        'comprador_nombre',  COALESCE(up.nombre || ' ' || up.apellido, 'N/D'),
        'comprador_avatar',  up.url_avatar,
        'asunto',            c.asunto,
        'tipo',              c.tipo,
        'estado',            c.estado,
        'ultimo_mensaje',    (
            SELECT jsonb_build_object(
                'cuerpo',    LEFT(m.cuerpo, 80),
                'emisor_id', m.emisor_id,
                'tipo',      m.tipo_contenido,
                'fecha',     m.fecha_creacion
            )
            FROM auth.mensajes m
            WHERE m.id_conversacion = c.id AND m.eliminado = false
            ORDER BY m.fecha_creacion DESC LIMIT 1
        ),
        'mensajes_count',    c.mensajes_count,
        'no_leidos',         NOT c.leido_vendedor,
        'ultimo_mensaje_at', c.ultimo_mensaje_at,
        'producto_nombre',   p.nombre,
        'orden_id',          c.id_orden,
        'escalada',          EXISTS (
            SELECT 1 FROM auth.consultas_escaladas ce
            WHERE ce.id_conversacion = c.id AND ce.estado_sync = 'activo'
        )
    )
    FROM auth.conversaciones c
    LEFT JOIN auth.user_profiles up ON up.id_usuario = c.id_comprador
    LEFT JOIN auth.productos p ON p.id = c.id_producto
    WHERE c.id_vendedor = v_vid
      AND (NOT p_solo_no_leidas OR c.leido_vendedor = false)
    ORDER BY c.ultimo_mensaje_at DESC NULLS LAST
    LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: seller_get_mis_productos(boolean, boolean, integer, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_mis_productos(p_activo boolean DEFAULT NULL::boolean, p_deleted boolean DEFAULT false, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
declare v_actor_id uuid;
begin
  v_actor_id := auth.fn_current_user_id();

  if auth.fn_current_user_role() <> 'seller' then raise exception 'seller_role_required';
  end if;

  return (
    select jsonb_build_object(
      'total', (select count(*) from auth.productos p
                where p.id_vendedor = v_actor_id
                  and (p_activo is null or p.activo = p_activo)
                  and (not coalesce(p_deleted, false) and p.fecha_eliminacion is null
                       or coalesce(p_deleted, false) and p.fecha_eliminacion is not null)),
      'items', coalesce((select jsonb_agg(rows.item) from (
                select jsonb_build_object(
                  'producto_id', p.id,
                  'nombre',      p.nombre,
                  'precio',      p.precio,
                  'descuento_porcentaje', p.descuento_porcentaje,
                  'condicion',   p.condicion,
                  'activo',      p.activo,
                  'deleted_at',  p.fecha_eliminacion,
                  'categoria',   c.nombre,
                  'subcategoria', s.nombre,
                  'stock_disponible', inv.stock_disponible,
                  'foto_portada', (select gf.url from auth.galeria_fotos gf
                                   where gf.id_producto = p.id and gf.activo = true and gf.fecha_eliminacion is null
                                   order by gf.orden asc limit 1),
                  'fecha_creacion', p.fecha_creacion,
                  'fecha_modificacion', p.fecha_modificacion
                ) as item
                from auth.productos p
                left join auth.categorias c   on c.id = p.id_categoria
                left join auth.subcategorias s on s.id = p.id_subcategoria
                left join auth.inventario_producto inv on inv.id_producto = p.id
                where p.id_vendedor = v_actor_id
                  and (p_activo is null or p.activo = p_activo)
                  and (not coalesce(p_deleted, false) and p.fecha_eliminacion is null
                       or coalesce(p_deleted, false) and p.fecha_eliminacion is not null)
                order by p.fecha_creacion desc
                limit greatest(coalesce(p_limit, 20), 1)
                offset greatest(coalesce(p_offset, 0), 0)
              ) rows), '[]'::jsonb)
    )
  );

end;
$$;


--
-- Name: seller_get_mis_promociones(boolean, integer, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_mis_promociones(p_activas_only boolean DEFAULT false, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_vid uuid := (nullif(current_setting('request.jwt.claims', true),'')::jsonb ->> 'sub')::uuid;
BEGIN
    -- Validar paginación para evitar consultas abusivas
    IF p_limit > 100 OR p_limit < 1 THEN
        RAISE EXCEPTION 'limit debe estar entre 1 y 100' USING ERRCODE = 'P0070';
    END IF;
    IF p_offset < 0 THEN
        RAISE EXCEPTION 'offset debe ser >= 0' USING ERRCODE = 'P0071';
    END IF;

    RETURN QUERY
    SELECT jsonb_build_object(
        'promocion_id',       p.id,
        'codigo',             p.codigo,
        'nombre',             p.nombre,
        'tipo',               p.tipo,
        'valor',              p.valor,
        'canal',              p.canal,
        'estado',             CASE
            WHEN NOT p.activo          THEN 'inactiva'
            WHEN p.fecha_fin < now()   THEN 'vencida'
            WHEN p.fecha_inicio > now() THEN 'programada'
            ELSE 'activa' END,
        'activo',             p.activo,
        'fecha_inicio',       p.fecha_inicio,
        'fecha_fin',          p.fecha_fin,
        'usos_actuales',      p.usos_actuales,
        'max_usos',           p.max_usos,
        'pct_uso',            CASE WHEN p.max_usos > 0
            THEN ROUND(p.usos_actuales::numeric / p.max_usos * 100, 1)
            ELSE NULL END,
        'campanas_count',     (SELECT COUNT(*) FROM auth.campanas c WHERE c.id_promocion = p.id),
        'aplicaciones_count', (SELECT COUNT(*) FROM auth.promociones_aplicadas pa WHERE pa.id_promocion = p.id)
    )
    FROM auth.promociones p
    WHERE p.creado_por = v_vid
      AND (NOT p_activas_only OR (p.activo = true AND p.fecha_fin > now()))
    ORDER BY p.fecha_creacion DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: seller_get_mis_resenas(boolean, integer, timestamp with time zone); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_mis_resenas(p_solo_public boolean DEFAULT false, p_limit integer DEFAULT 20, p_antes_de timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor  uuid;
    v_resenas jsonb;
    v_stats   jsonb;
    v_badge   jsonb;
BEGIN
    v_actor := auth.fn_current_user_id();

    -- Estadísticas completas
    SELECT jsonb_build_object(
        'total',           COUNT(*),
        'verificadas',     COUNT(*) FILTER (WHERE verificada = true),
        'promedio',        ROUND(AVG(calificacion)::numeric, 2),
        'positivas',       COUNT(*) FILTER (WHERE calificacion >= 4),
        'neutras',         COUNT(*) FILTER (WHERE calificacion = 3),
        'negativas',       COUNT(*) FILTER (WHERE calificacion <= 2),
        'con_respuesta',   COUNT(*) FILTER (WHERE respuesta_publica IS NOT NULL),
        'distribucion',    jsonb_build_object(
            '5', COUNT(*) FILTER (WHERE calificacion = 5),
            '4', COUNT(*) FILTER (WHERE calificacion = 4),
            '3', COUNT(*) FILTER (WHERE calificacion = 3),
            '2', COUNT(*) FILTER (WHERE calificacion = 2),
            '1', COUNT(*) FILTER (WHERE calificacion = 1)
        ),
        'sentimiento_summary', jsonb_build_object(
            'positivo', COUNT(*) FILTER (WHERE sentimiento = 'positivo'),
            'neutro',   COUNT(*) FILTER (WHERE sentimiento = 'neutro'),
            'negativo', COUNT(*) FILTER (WHERE sentimiento = 'negativo'),
            'mixto',    COUNT(*) FILTER (WHERE sentimiento = 'mixto')
        )
    ) INTO v_stats
    FROM auth.resenas
    WHERE id_vendedor = v_actor
      AND (NOT p_solo_public OR verificada = true)
      AND moderada = false;

    -- Lista con cursor
    SELECT jsonb_agg(jsonb_build_object(
        'resena_id',            r.id,
        'calificacion',         r.calificacion,
        'comentario',           r.comentario,
        'verificada',           r.verificada,
        'respuesta_publica',    r.respuesta_publica,
        'respuesta_fecha',      r.respuesta_fecha,
        'respuesta_modificada', r.respuesta_modificada_at,
        'sentimiento',          r.sentimiento,
        'sentimiento_score',    r.sentimiento_score,
        'comprador_nombre',     up.nombre,
        'comprador_avatar',     up.url_avatar,
        'orden_id',             r.id_orden,
        'fecha',                r.fecha_creacion
    ) ORDER BY r.fecha_creacion DESC)
    INTO v_resenas
    FROM auth.resenas r
    LEFT JOIN auth.user_profiles up ON up.id_usuario = r.id_comprador
    WHERE r.id_vendedor = v_actor
      AND (NOT p_solo_public OR r.verificada = true)
      AND r.moderada     = false
      AND r.fecha_creacion < p_antes_de
    LIMIT p_limit;

    -- Badge actual
    SELECT row_to_json(b)::jsonb INTO v_badge
    FROM auth.badge_confiable b WHERE b.id_vendedor = v_actor;

    RETURN jsonb_build_object(
        'estadisticas', v_stats,
        'resenas',      COALESCE(v_resenas, '[]'::jsonb),
        'badge',        v_badge,
        'cursor_next',  (
            SELECT r2.fecha_creacion FROM auth.resenas r2
            WHERE r2.id_vendedor = v_actor
              AND r2.moderada = false
              AND r2.fecha_creacion < p_antes_de
            ORDER BY r2.fecha_creacion DESC
            OFFSET p_limit LIMIT 1
        )
    );
END;
$$;


--
-- Name: seller_get_mis_ubicaciones(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_mis_ubicaciones() RETURNS TABLE(id uuid, nombre text, direccion_texto text, tipo text, latitud double precision, longitud double precision, es_principal boolean, estado text, horarios jsonb, fotos jsonb, total_visitas integer, ultima_visita timestamp with time zone, fecha_creacion timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
  SELECT id, nombre, direccion_texto, tipo, latitud, longitud,
         es_principal, estado, horarios, fotos,
         total_visitas, ultima_visita, fecha_creacion
  FROM auth.ubicaciones
  WHERE id_usuario = (nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid
    AND fecha_eliminacion IS NULL
  ORDER BY es_principal DESC, fecha_creacion DESC;
$$;


--
-- Name: seller_get_movimientos(integer, uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_movimientos(p_limit integer DEFAULT 20, p_cursor uuid DEFAULT NULL::uuid, p_tipo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor_id uuid;
    v_rows     jsonb;
    v_next_cursor uuid;
BEGIN
    v_actor_id := auth.fn_current_user_id();
    p_limit := LEAST(p_limit, 100);

    SELECT jsonb_agg(t ORDER BY t.fecha_creacion DESC)
    INTO v_rows
    FROM (
        SELECT
            mp.id, mp.tipo_movimiento, mp.monto,
            mp.saldo_anterior, mp.saldo_posterior,
            mp.referencia, mp.detalle, mp.expira_en,
            mp.fecha_creacion
        FROM auth.movimientos_puntos mp
        WHERE mp.id_usuario = v_actor_id
          AND (p_tipo IS NULL OR mp.tipo_movimiento = p_tipo)
          AND (p_cursor IS NULL OR mp.fecha_creacion <
               (SELECT fecha_creacion FROM auth.movimientos_puntos
                WHERE id = p_cursor LIMIT 1))
        ORDER BY mp.fecha_creacion DESC
        LIMIT p_limit + 1
    ) t;

    -- Extraer cursor siguiente
    IF jsonb_array_length(COALESCE(v_rows, '[]'::jsonb)) > p_limit THEN
        v_next_cursor := (v_rows -> p_limit ->> 'id')::uuid;
        v_rows := v_rows - p_limit;
    END IF;

    RETURN jsonb_build_object(
        'movimientos',  COALESCE(v_rows, '[]'::jsonb),
        'next_cursor',  v_next_cursor,
        'has_more',     v_next_cursor IS NOT NULL
    );
END;
$$;


--
-- Name: seller_get_nivel_lealtad(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_nivel_lealtad() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor_id uuid;
    v_result   jsonb;
BEGIN
    v_actor_id := auth.fn_current_user_id();

    SELECT jsonb_build_object(
        'nivel_codigo',              nl.codigo,
        'nivel_nombre',              nl.nombre,
        'nivel_color',               nl.color_hex,
        'puntos_acumulados',         b.puntos_acumulados_historico,
        'puntos_minimos_nivel',      nl.puntos_minimos,
        'puntos_maximos_nivel',      nl.puntos_maximos,
        'multiplicador_ganancia',    nl.multiplicador_ganancia,
        'progreso_pct',
            CASE WHEN nl.puntos_maximos IS NULL THEN 100
                 ELSE ROUND(
                     (b.puntos_acumulados_historico - nl.puntos_minimos)::numeric /
                     NULLIF(nl.puntos_maximos - nl.puntos_minimos, 0) * 100, 1
                 )
            END,
        'puntos_para_subir',
            CASE WHEN nl.puntos_maximos IS NULL THEN 0
                 ELSE GREATEST(0, nl.puntos_maximos + 1 - b.puntos_acumulados_historico)
            END,
        'siguiente_nivel',
            (SELECT jsonb_build_object(
                'codigo', nl2.codigo,
                'nombre', nl2.nombre,
                'puntos_minimos', nl2.puntos_minimos,
                'multiplicador', nl2.multiplicador_ganancia
             )
             FROM auth.niveles_lealtad nl2
             WHERE nl2.activo = true
               AND nl2.puntos_minimos > nl.puntos_minimos
             ORDER BY nl2.puntos_minimos ASC
             LIMIT 1)
    ) INTO v_result
    FROM auth.billetera b
    LEFT JOIN auth.niveles_lealtad nl ON nl.id = b.nivel_lealtad_id
    WHERE b.id_usuario = v_actor_id;

    IF v_result IS NULL THEN
        RETURN jsonb_build_object('error', 'billetera_no_encontrada', 'codigo', 'WALLET_001');
    END IF;
    RETURN v_result;
END;
$$;


--
-- Name: seller_get_perfil_comprador(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_perfil_comprador(p_id_comprador uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor  uuid;
    v_result jsonb;
BEGIN
    v_actor := auth.fn_current_user_id();

    IF NOT auth.fn_get_feature_flag(v_actor, 'acceso_rfm') THEN
        RAISE EXCEPTION 'feature_not_available_for_plan' USING ERRCODE = '42501';
    END IF;

    -- RN-019: Solo compradores que han comprado al vendedor
    IF NOT EXISTS (
        SELECT 1 FROM auth.ordenes
        WHERE id_vendedor = v_actor AND id_comprador = p_id_comprador
          AND estado = 'confirmada'
    ) THEN
        RAISE EXCEPTION 'comprador_no_encontrado'
            USING DETAIL = 'El comprador no tiene órdenes confirmadas con este vendedor',
                  ERRCODE = '22023';
    END IF;

    SELECT jsonb_build_object(
        'id_comprador',    up.id_usuario,
        'nombre',          up.nombre,
        'total_ordenes',   stats.total_ordenes,
        'monto_total',     stats.total,
        'primera_compra',  stats.primera_compra,
        'ultima_compra',   stats.ultima_compra,
        'calificacion_avg', COALESCE(ROUND(stats.cal_avg::numeric, 2), 0),
        'segmento_rfm',    rfm.segmento,
        'score_rfm',       rfm.score_rfm,
        'churn_riesgo',    churn.nivel_riesgo,
        'ordenes_recientes', (
            SELECT jsonb_agg(row_to_json(o))
            FROM (
                SELECT id, total, estado, fecha_creacion
                FROM auth.ordenes
                WHERE id_vendedor = v_actor AND id_comprador = p_id_comprador
                ORDER BY fecha_creacion DESC
                LIMIT 5
            ) o
        )
    ) INTO v_result
    FROM auth.user_profiles up
    CROSS JOIN (
        SELECT
            COUNT(*)::integer        AS total_ordenes,
            SUM(total)               AS total,
            MIN(fecha_creacion)      AS primera_compra,
            MAX(fecha_creacion)      AS ultima_compra,
            AVG(r.calificacion)      AS cal_avg
        FROM auth.ordenes o
        LEFT JOIN auth.resenas r ON r.id_orden = o.id AND r.id_vendedor = v_actor
        WHERE o.id_vendedor = v_actor AND o.id_comprador = p_id_comprador
          AND o.estado = 'confirmada'
    ) stats
    LEFT JOIN LATERAL (
        SELECT segmento, score_rfm
        FROM auth.rfm_snapshots
        WHERE id_vendedor = v_actor AND id_comprador = p_id_comprador
        ORDER BY snapshot_date DESC LIMIT 1
    ) rfm ON true
    LEFT JOIN auth.churn_predictions churn
        ON churn.id_vendedor = v_actor AND churn.id_comprador = p_id_comprador
    WHERE up.id_usuario = p_id_comprador;

    RETURN coalesce(v_result, '{}'::jsonb);
END;
$$;


--
-- Name: seller_get_prediccion_ventas(integer, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_prediccion_ventas(p_dias_historico integer DEFAULT 60, p_dias_futuro integer DEFAULT 14) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_vid          uuid    := auth.uid();
    v_slope        float8;
    v_intercept    float8;
    v_r2           float8;
    v_regr_count   int;
    v_base_date    date    := CURRENT_DATE - p_dias_historico;
    v_dia_offset   int;
    v_pred_ingresos numeric(14,2);
    v_pred_ordenes  numeric(14,2);
    v_fecha_pred    date;
BEGIN
    -- Plan Silver+ requerido para predicción ML
    IF NOT auth.fn_get_feature_flag(v_vid, 'prediccion_ventas') THEN
        RAISE EXCEPTION 'Predicción de ventas requiere plan Silver o superior'
            USING ERRCODE = 'P0046';
    END IF;

    -- Calcular regresión sobre series temporales de la MV
    -- x = días transcurridos desde v_base_date, y = ingresos_netos
    SELECT
        regr_count(ingresos_netos, fecha_venta - v_base_date),
        regr_slope(ingresos_netos, fecha_venta - v_base_date),
        regr_intercept(ingresos_netos, fecha_venta - v_base_date),
        regr_r2(ingresos_netos, fecha_venta - v_base_date)
    INTO v_regr_count, v_slope, v_intercept, v_r2
    FROM auth.mv_ventas_vendedor
    WHERE id_vendedor = v_vid
      AND fecha_venta BETWEEN v_base_date AND CURRENT_DATE;

    -- Mínimo 7 puntos de datos para regresión confiable
    IF v_regr_count < 7 THEN
        RETURN QUERY
        SELECT jsonb_build_object(
            'error',        'Datos insuficientes para predicción',
            'datos_reales', v_regr_count,
            'minimo',       7,
            'sugerencia',   'Necesitas al menos 7 días de ventas confirmadas'
        );
        RETURN;
    END IF;

    -- Generar predicciones día a día
    FOR v_dia_offset IN 1..p_dias_futuro LOOP
        v_fecha_pred    := CURRENT_DATE + v_dia_offset;
        v_pred_ingresos := GREATEST(0,
            ROUND((v_slope * (v_fecha_pred - v_base_date) + v_intercept)::numeric, 2)
        );

        RETURN NEXT jsonb_build_object(
            'fecha',           v_fecha_pred,
            'ingresos_pred',   v_pred_ingresos,
            'tipo',            'prediccion',
            'modelo',          'regresion_lineal_pg',
            'r2',              ROUND(v_r2::numeric, 4),
            'confianza',       CASE
                                   WHEN v_r2 >= 0.85 THEN 'alta'
                                   WHEN v_r2 >= 0.60 THEN 'media'
                                   ELSE 'baja'
                               END,
            'datos_entrenamiento', v_regr_count
        );
    END LOOP;
END;
$$;


--
-- Name: seller_get_predicciones_demanda(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_predicciones_demanda(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_ml jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'prediction_id', m.prediction_id, 'model_name', m.model_name,
           'prediction_type', m.prediction_type, 'prediction_score', m.prediction_score,
           'confidence', m.confidence, 'fecha_expiracion', m.fecha_expiracion)),
         '[]'::jsonb)
    INTO v_ml
    FROM analytics.predicciones_ml m
   WHERE m.fecha_expiracion > now() AND m.prediction_type ILIKE '%demanda%';
  RETURN jsonb_build_object('ml_predictions', v_ml,
                            'forecast', auth.fn_calcular_prediccion_demanda(p_id_vendedor));
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: seller_get_recomendacion_checkout(uuid, uuid[], integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_recomendacion_checkout(p_id_vendedor uuid, p_producto_ids uuid[], p_limit integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $_$
DECLARE
    v_result     jsonb;
    v_graph_name text;
    v_pid        uuid;
    v_age_rows   jsonb := '[]';
    v_age_row    jsonb;
BEGIN
    -- Intentar AGE para cada producto en carrito
    BEGIN
        SELECT name INTO v_graph_name FROM ag_catalog.ag_graph ORDER BY name LIMIT 1;
        IF v_graph_name IS NOT NULL THEN
            FOREACH v_pid IN ARRAY p_producto_ids LOOP
                EXECUTE format(
                    $age$SELECT jsonb_agg(row_to_json(t)) FROM (
                    SELECT * FROM cypher(%L, $c$
                    MATCH (p:Producto {id_producto: %L})-[r:COMPRADO_JUNTO]-(rec:Producto)
                    WHERE r.lift > 1.2 AND r.frecuencia >= 3
                    RETURN rec.id_producto AS id, rec.nombre AS nombre,
                           rec.precio AS precio, r.lift AS lift
                    ORDER BY r.lift DESC LIMIT %s $c$)
                    AS (id agtype, nombre agtype, precio agtype, lift agtype)) t$age$,
                    v_graph_name, v_pid::text, p_limit
                ) INTO v_age_row;
                IF v_age_row IS NOT NULL THEN
                    v_age_rows := v_age_rows || v_age_row;
                END IF;
            END LOOP;
            IF jsonb_array_length(v_age_rows) > 0 THEN
                RETURN jsonb_build_object('fuente','age_graph','recomendaciones',v_age_rows);
            END IF;
        END IF;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    -- Fallback SQL
    SELECT jsonb_agg(DISTINCT row_to_json(t)) INTO v_result
    FROM (
        SELECT
            CASE WHEN ap.producto_a_id = ANY(p_producto_ids) THEN ap.producto_b_id
                 ELSE ap.producto_a_id END AS id_producto,
            CASE WHEN ap.producto_a_id = ANY(p_producto_ids) THEN pb.nombre
                 ELSE pa.nombre END AS nombre,
            CASE WHEN ap.producto_a_id = ANY(p_producto_ids) THEN pb.precio
                 ELSE pa.precio END AS precio,
            ap.lift, ap.frecuencia
        FROM auth.afinidad_productos ap
        JOIN auth.productos pa ON pa.id = ap.producto_a_id
        JOIN auth.productos pb ON pb.id = ap.producto_b_id
        WHERE ap.id_vendedor = p_id_vendedor
          AND ap.tipo_correlacion = 'positiva'
          AND ap.lift > 1.2
          AND (ap.producto_a_id = ANY(p_producto_ids) OR ap.producto_b_id = ANY(p_producto_ids))
          AND NOT (ap.producto_a_id = ANY(p_producto_ids) AND ap.producto_b_id = ANY(p_producto_ids))
        ORDER BY ap.lift DESC, ap.frecuencia DESC
        LIMIT p_limit
    ) t;

    RETURN jsonb_build_object('fuente','sql_cache','recomendaciones',coalesce(v_result,'[]'));
END;
$_$;


--
-- Name: seller_get_rentabilidad_productos(date, date, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_rentabilidad_productos(p_desde date DEFAULT ((CURRENT_DATE - '30 days'::interval))::date, p_hasta date DEFAULT CURRENT_DATE, p_limit integer DEFAULT 20) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_vid uuid := auth.uid();
BEGIN
    IF NOT auth.fn_get_feature_flag(v_vid, 'reporte_rentabilidad') THEN
        RAISE EXCEPTION 'Reporte de rentabilidad requiere plan Gold o superior'
            USING ERRCODE = 'P0051';
    END IF;

    p_limit := GREATEST(1, LEAST(p_limit, 200));

    RETURN QUERY
    SELECT jsonb_build_object(
        'producto_id',       COALESCE(oi.id_producto::text, 'eliminado'),
        'nombre_producto',   COALESCE(p.nombre, oi.nombre_producto_snapshot, 'Producto eliminado'),
        'categoria',         COALESCE(c.nombre, oi.categoria_snapshot, 'Sin categoría'),
        'unidades_vendidas', SUM(oi.cantidad),
        'ingresos_totales',  ROUND(SUM(oi.total_linea), 2),
        'costo_total',       ROUND(SUM(oi.cantidad *
            COALESCE(
                -- Costo vigente más reciente en la fecha de venta
                (SELECT cp.costo_unitario
                 FROM auth.costos_producto cp
                 WHERE cp.id_producto = oi.id_producto
                   AND cp.vigente_desde <= o.fecha_creacion::date
                 ORDER BY cp.vigente_desde DESC
                 LIMIT 1),
                0
            )
        ), 2),
        'margen_bruto', ROUND(
            SUM(oi.total_linea) - SUM(oi.cantidad *
                COALESCE(
                    (SELECT cp.costo_unitario
                     FROM auth.costos_producto cp
                     WHERE cp.id_producto = oi.id_producto
                       AND cp.vigente_desde <= o.fecha_creacion::date
                     ORDER BY cp.vigente_desde DESC
                     LIMIT 1),
                    0
                )
            ), 2),
        'margen_pct', ROUND(
            CASE WHEN SUM(oi.total_linea) > 0
                 THEN (1 - SUM(oi.cantidad *
                    COALESCE(
                        (SELECT cp.costo_unitario
                         FROM auth.costos_producto cp
                         WHERE cp.id_producto = oi.id_producto
                           AND cp.vigente_desde <= o.fecha_creacion::date
                         ORDER BY cp.vigente_desde DESC LIMIT 1),
                        0
                    )
                 ) / SUM(oi.total_linea)) * 100
                 ELSE NULL
            END, 2),
        'tiene_costo_registrado', EXISTS (
            SELECT 1 FROM auth.costos_producto cp
            WHERE cp.id_producto = oi.id_producto
        )
    )
    FROM auth.orden_items oi
    JOIN auth.ordenes o ON o.id = oi.id_orden
    LEFT JOIN auth.productos p   ON p.id = oi.id_producto
    LEFT JOIN auth.categorias c  ON c.id = p.id_categoria
    WHERE o.id_vendedor = v_vid
      AND o.estado = 'confirmada'
      AND o.fecha_creacion::date BETWEEN p_desde AND p_hasta
    GROUP BY oi.id_producto, p.nombre, oi.nombre_producto_snapshot, c.nombre, oi.categoria_snapshot
    ORDER BY SUM(oi.total_linea) - SUM(oi.cantidad *
        COALESCE(
            (SELECT cp.costo_unitario
             FROM auth.costos_producto cp
             WHERE cp.id_producto = oi.id_producto
               AND cp.vigente_desde <= MIN(o.fecha_creacion)::date
             ORDER BY cp.vigente_desde DESC LIMIT 1),
            0
        )
    ) DESC
    LIMIT p_limit;
END;
$$;


--
-- Name: seller_get_resumen_analytics_clientes(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_resumen_analytics_clientes() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor     uuid;
    v_plan      text;
    v_max_snap  date;
BEGIN
    v_actor := auth.fn_current_user_id();

    SELECT pm.codigo INTO v_plan
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.id_vendedor = v_actor AND mv.estado IN ('activa','trial')
    ORDER BY mv.ciclo_fin DESC LIMIT 1;

    SELECT MAX(snapshot_date) INTO v_max_snap
    FROM auth.rfm_snapshots WHERE id_vendedor = v_actor;

    RETURN jsonb_build_object(
        'plan',               coalesce(v_plan, 'bronze'),
        'snapshot_date',      v_max_snap,
        'total_compradores',  (
            SELECT COUNT(DISTINCT id_comprador) FROM auth.ordenes
            WHERE id_vendedor = v_actor AND estado = 'confirmada'
        ),
        'nuevos_ultimo_mes',  (
            SELECT COUNT(DISTINCT id_comprador) FROM auth.ordenes
            WHERE id_vendedor = v_actor AND estado = 'confirmada'
              AND fecha_creacion >= now() - interval '30 days'
        ),
        'top_segmento',       (
            SELECT segmento FROM auth.rfm_snapshots
            WHERE id_vendedor = v_actor AND snapshot_date = v_max_snap
            GROUP BY segmento ORDER BY COUNT(*) DESC LIMIT 1
        ),
        'compradores_churn_alto', (
            SELECT COUNT(*) FROM auth.churn_predictions
            WHERE id_vendedor = v_actor
              AND nivel_riesgo IN ('alto','critico')
        ),
        'push_pendientes',    (
            SELECT COUNT(*) FROM auth.push_notification_queue
            WHERE id_vendedor = v_actor AND estado = 'pendiente'
        )
    );
END;
$$;


--
-- Name: seller_get_rfm_segmentos(date); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_rfm_segmentos(p_snapshot_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor  uuid;
    v_result jsonb;
    v_max_snap date;
BEGIN
    v_actor := auth.fn_current_user_id();

    -- RN-006: Feature flag acceso_rfm (Silver+)
    IF NOT auth.fn_get_feature_flag(v_actor, 'acceso_rfm') THEN
        RAISE EXCEPTION 'feature_not_available_for_plan'
            USING DETAIL = 'acceso_rfm requiere plan Silver o superior',
                  ERRCODE = '42501';
    END IF;

    -- Obtener snapshot más reciente disponible
    SELECT MAX(snapshot_date) INTO v_max_snap
    FROM auth.rfm_snapshots
    WHERE id_vendedor = v_actor;

    -- FA-3: Si no hay snapshot reciente (> 7 días), recalcular
    IF v_max_snap IS NULL OR v_max_snap < CURRENT_DATE - 7 THEN
        PERFORM auth.fn_calcular_rfm_snapshot(v_actor);
        v_max_snap := CURRENT_DATE;
    END IF;

    SELECT jsonb_agg(row_to_json(t)) INTO v_result
    FROM (
        SELECT
            segmento,
            COUNT(*)                        AS compradores,
            ROUND(AVG(score_rfm)::numeric, 2) AS score_promedio,
            ROUND(AVG(recencia_dias)::numeric, 0) AS recencia_promedio,
            ROUND(AVG(frecuencia)::numeric, 1)    AS frecuencia_promedio,
            ROUND(SUM(total)::numeric, 2)   AS monto_total_segmento
        FROM auth.rfm_snapshots
        WHERE id_vendedor = v_actor
          AND snapshot_date = v_max_snap
        GROUP BY segmento
        ORDER BY score_promedio DESC
    ) t;

    RETURN jsonb_build_object(
        'snapshot_date', v_max_snap,
        'total_compradores', (
            SELECT COUNT(*) FROM auth.rfm_snapshots
            WHERE id_vendedor = v_actor AND snapshot_date = v_max_snap
        ),
        'segmentos', coalesce(v_result, '[]'::jsonb)
    );
END;
$$;


--
-- Name: seller_get_segmento_detalle(text, integer, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_segmento_detalle(p_segmento text, p_limit integer DEFAULT 50, p_cursor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor    uuid;
    v_max_snap date;
    v_result   jsonb;
BEGIN
    v_actor := auth.fn_current_user_id();

    IF NOT auth.fn_get_feature_flag(v_actor, 'acceso_rfm') THEN
        RAISE EXCEPTION 'feature_not_available_for_plan' USING ERRCODE = '42501';
    END IF;

    -- RN-010: Validar segmento
    IF p_segmento NOT IN ('champion','loyal','at_risk','hibernating','new','lost') THEN
        RAISE EXCEPTION 'segmento_invalido' USING ERRCODE = '22023';
    END IF;

    SELECT MAX(snapshot_date) INTO v_max_snap
    FROM auth.rfm_snapshots WHERE id_vendedor = v_actor;

    -- FA-5: Segmento sin compradores retorna vacío estructurado
    IF v_max_snap IS NULL THEN
        RETURN jsonb_build_object('segmento', p_segmento, 'datos', '[]'::jsonb, 'total', 0);
    END IF;

    SELECT jsonb_agg(row_to_json(t)) INTO v_result
    FROM (
        SELECT
            rs.id_comprador,
            up.nombre                 AS nombre,
            rs.recencia_dias,
            rs.frecuencia,
            rs.total,
            rs.score_rfm,
            rs.snapshot_date
        FROM auth.rfm_snapshots rs
        JOIN auth.user_profiles up ON up.id_usuario = rs.id_comprador
        WHERE rs.id_vendedor = v_actor
          AND rs.snapshot_date = v_max_snap
          AND rs.segmento = p_segmento
          AND (p_cursor IS NULL OR rs.id_comprador > p_cursor)
        ORDER BY rs.score_rfm DESC, rs.id_comprador
        LIMIT LEAST(p_limit, 100)
    ) t;

    RETURN jsonb_build_object(
        'segmento',      p_segmento,
        'snapshot_date', v_max_snap,
        'datos',         coalesce(v_result, '[]'::jsonb),
        'total',         (
            SELECT COUNT(*) FROM auth.rfm_snapshots
            WHERE id_vendedor = v_actor
              AND snapshot_date = v_max_snap
              AND segmento = p_segmento
        )
    );
END;
$$;


--
-- Name: seller_get_segunda_vecindad(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_segunda_vecindad(p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'ag_catalog'
    AS $$
DECLARE v_res jsonb;
BEGIN
  LOAD 'age';
  SET LOCAL search_path = ag_catalog, public, pg_temp;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id_zona_a', agtype_to_json(a.properties)->>'id_zona',
           'id_zona_c', agtype_to_json(c.properties)->>'id_zona',
           'zona_a', agtype_to_json(a.properties)->>'name',
           'zona_c', agtype_to_json(c.properties)->>'name')
         ORDER BY agtype_to_json(a.properties)->>'name'), '[]'::jsonb)
    INTO v_res
    FROM smtp_posix_graph."SECOND_NEAR" e
    JOIN smtp_posix_graph."Zona" a ON a.id = e.start_id
    JOIN smtp_posix_graph."Zona" c ON c.id = e.end_id
    LEFT JOIN public.geo_zones gz
      ON gz.id_zona::text = agtype_to_json(a.properties)->>'id_zona'
   WHERE p_id_vendedor IS NULL OR gz.metadata->>'id_vendedor' = p_id_vendedor::text;
  RETURN v_res;
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: seller_get_sentimiento_historico(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_sentimiento_historico(p_dias integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor uuid;
    v_result jsonb;
BEGIN
    v_actor := auth.fn_current_user_id();

    -- Gold+ para historial de sentimiento
    IF NOT auth.fn_get_feature_flag(v_actor, 'respuesta_resenas') THEN
        RAISE EXCEPTION 'Tu plan no incluye análisis de sentimiento (Silver+)'
            USING ERRCODE = 'P0003';
    END IF;

    SELECT jsonb_agg(jsonb_build_object(
        'semana',         date_trunc('week', r.fecha_creacion),
        'positivos',      COUNT(*) FILTER (WHERE r.sentimiento = 'positivo'),
        'neutros',        COUNT(*) FILTER (WHERE r.sentimiento = 'neutro'),
        'negativos',      COUNT(*) FILTER (WHERE r.sentimiento = 'negativo'),
        'mixtos',         COUNT(*) FILTER (WHERE r.sentimiento = 'mixto'),
        'sin_analizar',   COUNT(*) FILTER (WHERE r.sentimiento IS NULL),
        'score_promedio', ROUND(AVG(r.sentimiento_score)::numeric, 3)
    ) ORDER BY date_trunc('week', r.fecha_creacion))
    INTO v_result
    FROM auth.resenas r
    WHERE r.id_vendedor = v_actor
      AND r.verificada  = true
      AND r.moderada    = false
      AND r.fecha_creacion >= now() - (p_dias || ' days')::interval
    GROUP BY date_trunc('week', r.fecha_creacion);

    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


--
-- Name: seller_get_sugerencias_puntos_venta(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_sugerencias_puntos_venta(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
             'geohash', d.geohash,
             'lng', ROUND(ST_X(d.centroid::geometry)::numeric, 4),
             'lat', ROUND(ST_Y(d.centroid::geometry)::numeric, 4),
             'order_count', d.order_count, 'density_score', d.density_score,
             'total', d.total, 'unique_buyers', d.unique_buyers)
           ORDER BY d.density_score DESC)
      FROM public.market_density_snapshots d
     WHERE d.is_anomaly = false
     LIMIT 20
  ), '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: seller_get_tasa_conversion(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_tasa_conversion() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_bc record;
BEGIN
    SELECT * INTO v_bc FROM auth.beneficios_catalogo
    WHERE codigo = 'CONV_PUNTOS_MXN' AND activo = true;

    IF NOT FOUND OR v_bc.tasa_conversion_mxn IS NULL THEN
        RETURN jsonb_build_object('disponible', false);
    END IF;

    RETURN jsonb_build_object(
        'disponible',          true,
        'tasa_mxn_por_punto',  v_bc.tasa_conversion_mxn,
        'ejemplo_100_puntos',  100 * v_bc.tasa_conversion_mxn,
        'minimo_puntos',       100
    );
END;
$$;


--
-- Name: seller_get_tendencias_rfm(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_tendencias_rfm(p_dias_atras integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor  uuid;
    v_result jsonb;
BEGIN
    v_actor := auth.fn_current_user_id();

    IF NOT auth.fn_get_feature_flag(v_actor, 'acceso_rfm') THEN
        RAISE EXCEPTION 'feature_not_available_for_plan'
            USING ERRCODE = '42501';
    END IF;

    -- RN-009: Tendencia por semana para cada segmento
    SELECT jsonb_agg(row_to_json(t)) INTO v_result
    FROM (
        SELECT
            date_trunc('week', snapshot_date::timestamptz)::date AS semana,
            segmento,
            COUNT(DISTINCT id_comprador)                          AS compradores,
            ROUND(AVG(score_rfm)::numeric, 2)                     AS score_prom
        FROM auth.rfm_snapshots
        WHERE id_vendedor = v_actor
          AND snapshot_date >= CURRENT_DATE - p_dias_atras
        GROUP BY 1, 2
        ORDER BY 1 DESC, 4 DESC
    ) t;

    RETURN jsonb_build_object(
        'dias_analizados', p_dias_atras,
        'tendencias',      coalesce(v_result, '[]'::jsonb)
    );
END;
$$;


--
-- Name: seller_get_transferencias_programadas(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_transferencias_programadas() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor_id uuid;
    v_limites  jsonb;
    v_rows     jsonb;
BEGIN
    v_actor_id := auth.fn_current_user_id();

    v_limites := auth.fn_get_wallet_limits(v_actor_id);
    IF NOT COALESCE((v_limites ->> 'transferencias_programadas')::boolean, false) THEN
        RETURN jsonb_build_object('error', 'plan_insuficiente', 'codigo', 'WALLET_070');
    END IF;

    SELECT jsonb_agg(jsonb_build_object(
        'id',            tp.id,
        'receptor_id',   tp.id_usuario_receptor,
        'monto',         tp.monto,
        'nota',          tp.nota,
        'estado',        tp.estado,
        'ejecutar_en',   tp.ejecutar_en,
        'ejecutada_at',  tp.ejecutada_at,
        'intentos',      tp.intentos,
        'error_detalle', tp.error_detalle
    ) ORDER BY tp.ejecutar_en ASC)
    INTO v_rows
    FROM auth.transferencias_programadas tp
    WHERE tp.id_usuario_origen = v_actor_id;

    RETURN jsonb_build_object(
        'transferencias_programadas', COALESCE(v_rows, '[]'::jsonb)
    );
END;
$$;


--
-- Name: seller_get_trigger_contexto_activos(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_trigger_contexto_activos() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
             'id',                r.id,
             'nombre',            r.nombre,
             'tipo_contexto',     r.tipo_contexto,
             'recompensa_puntos', r.recompensa_puntos,
             'plan_minimo',       r.plan_minimo
           ) ORDER BY r.nombre)
      FROM auth.reglas_recompensa_contexto r
     WHERE r.activo = true
  ), '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: seller_get_ventas_por_producto(date, date, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_ventas_por_producto(p_desde date DEFAULT ((CURRENT_DATE - '30 days'::interval))::date, p_hasta date DEFAULT CURRENT_DATE, p_limit integer DEFAULT 20) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_vid uuid := auth.uid();
BEGIN
    p_limit := GREATEST(1, LEAST(p_limit, 200)); -- clamp anti-DoS

    RETURN QUERY
    SELECT jsonb_build_object(
        'producto_id',        COALESCE(oi.id_producto::text, 'eliminado'),
        'nombre_producto',    COALESCE(p.nombre,
                                       oi.nombre_producto_snapshot,
                                       oi.detalle_jsonb->>'nombre',
                                       'Producto eliminado'),
        'categoria',          COALESCE(c.nombre, oi.categoria_snapshot, 'Sin categoría'),
        'unidades_vendidas',  SUM(oi.cantidad),
        'ingresos_totales',   ROUND(SUM(oi.total_linea), 2),
        'descuentos_totales', ROUND(SUM(oi.descuento_monto), 2),
        'precio_promedio',    ROUND(AVG(oi.precio_unitario), 2),
        'ordenes_count',      COUNT(DISTINCT o.id),
        'porcentaje_ingresos', ROUND(
            SUM(oi.total_linea) * 100.0 /
            NULLIF(SUM(SUM(oi.total_linea)) OVER (), 0), 2
        )
    )
    FROM auth.orden_items oi
    JOIN auth.ordenes o ON o.id = oi.id_orden
    LEFT JOIN auth.productos p   ON p.id = oi.id_producto
    LEFT JOIN auth.categorias c  ON c.id = p.id_categoria
    WHERE o.id_vendedor = v_vid
      AND o.estado = 'confirmada'
      AND o.fecha_creacion::date BETWEEN p_desde AND p_hasta
    GROUP BY oi.id_producto, p.nombre, oi.nombre_producto_snapshot,
             oi.detalle_jsonb->>'nombre', c.nombre, oi.categoria_snapshot
    ORDER BY SUM(oi.total_linea) DESC
    LIMIT p_limit;
END;
$$;


--
-- Name: seller_get_ventas_por_ubicacion(date, date); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_get_ventas_por_ubicacion(p_desde date DEFAULT ((CURRENT_DATE - '30 days'::interval))::date, p_hasta date DEFAULT CURRENT_DATE) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_vid uuid := auth.uid();
BEGIN
    IF NOT auth.fn_get_feature_flag(v_vid, 'historial_por_ubicacion') THEN
        RETURN QUERY
        SELECT jsonb_build_object(
            'ubicacion_id',      NULL,
            'ubicacion_nombre',  'Total (desglose por ubicación disponible en Silver+)',
            'total_ordenes',     COUNT(DISTINCT o.id),
            'ingresos_totales',  ROUND(SUM(o.total), 2)
        )
        FROM auth.ordenes o
        WHERE o.id_vendedor = v_vid AND o.estado = 'confirmada'
          AND o.fecha_creacion::date BETWEEN p_desde AND p_hasta;
        RETURN;
    END IF;

    RETURN QUERY
    SELECT jsonb_build_object(
        'ubicacion_id',      ub.id,
        'ubicacion_nombre',  COALESCE(ub.nombre, 'Ubicación sin nombre'),
        'tipo_ubicacion',    ub.tipo,
        'es_principal',      ub.es_principal,
        'total_ordenes',     COUNT(DISTINCT o.id),
        'ingresos_totales',  ROUND(SUM(o.total), 2),
        'compradores_unicos',COUNT(DISTINCT o.id_comprador),
        'ticket_promedio',   ROUND(AVG(o.total), 2)
    )
    FROM auth.ordenes o
    JOIN auth.ubicaciones ub
        ON ub.id = (o.metadata->>'ubicacion_id')::uuid
       AND ub.id_usuario = v_vid
    WHERE o.id_vendedor = v_vid
      AND o.estado = 'confirmada'
      AND o.fecha_creacion::date BETWEEN p_desde AND p_hasta
    GROUP BY ub.id, ub.nombre, ub.tipo, ub.es_principal
    ORDER BY SUM(o.total) DESC;
END;
$$;


--
-- Name: seller_heatmap_demanda_insatisfecha(integer, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_heatmap_demanda_insatisfecha(p_days_back integer DEFAULT 7, p_min_demandas integer DEFAULT 3) RETURNS TABLE(query_text text, demandas bigint, centroid_lat double precision, centroid_lng double precision, distancia_km numeric, id_categoria uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'ag_catalog', 'public'
    AS $$
DECLARE
    v_actor_id  uuid := auth.fn_current_user_id();
    v_punto     geography;
BEGIN
    -- Obtener punto activo del vendedor
    SELECT u.punto INTO v_punto
    FROM auth.ubicaciones u
    WHERE u.id_usuario = v_actor_id
      AND u.estado = 'activo'
      AND u.fecha_eliminacion IS NULL
    ORDER BY u.fecha_actualizacion DESC
    LIMIT 1;

    IF v_punto IS NULL THEN
        RAISE EXCEPTION 'P0204: El vendedor no tiene ubicación activa'
            USING ERRCODE = 'P0001';
    END IF;

    RETURN QUERY
    WITH demanda AS (
        SELECT
            se.query_text,
            se.id_categoria,
            COUNT(*)                                        AS demandas,
            ST_Centroid(ST_Collect(se.punto::geometry))     AS centroide_geom
        FROM auth.search_events se
        JOIN auth.users b
            ON b.id = se.id_comprador
           AND b.activo = true AND b.fecha_eliminacion IS NULL
        WHERE se.results_count = 0
          AND se.consentimiento = true
          AND se.fecha_creacion >= now() - make_interval(days => p_days_back)
        GROUP BY se.query_text, se.id_categoria
        HAVING COUNT(*) >= p_min_demandas  -- k-anonimato básico
    )
    SELECT
        d.query_text,
        d.demandas,
        ST_Y(d.centroide_geom)::double precision    AS centroid_lat,
        ST_X(d.centroide_geom)::double precision    AS centroid_lng,
        ROUND(
            ST_Distance(d.centroide_geom::geography, v_punto) / 1000.0,
            2
        )::numeric                                  AS distancia_km,
        d.id_categoria
    FROM demanda d
    ORDER BY d.demandas DESC, distancia_km ASC;
END;
$$;


--
-- Name: seller_iniciar_importacion_lote(jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_iniciar_importacion_lote(p_payload_jsonb jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
declare
  v_actor_id   uuid;

  v_batch_id   uuid;

  v_total_rows integer;

begin
  v_actor_id := auth.fn_current_user_id();

  if auth.fn_current_user_role() <> 'seller' then raise exception 'seller_role_required';
 end if;

  perform auth.fn_assert_seller_operable(v_actor_id);


    if not auth.fn_get_feature_flag(v_actor_id, 'importacion_masiva') then
    raise exception 'feature_importacion_masiva_requires_silver_plan';

  end if;


  if p_payload_jsonb is null or jsonb_typeof(p_payload_jsonb) <> 'array' then
    raise exception 'payload_must_be_json_array';

  end if;


  v_total_rows := jsonb_array_length(p_payload_jsonb);

  if v_total_rows > 200 then raise exception 'max_200_filas_por_lote';
 end if;


  insert into auth.productos_import_batch (id_vendedor, total_filas, payload_jsonb, estado)
  values (v_actor_id, v_total_rows, p_payload_jsonb, 'pendiente')
  returning id into v_batch_id;


    return jsonb_build_object('batch_id', v_batch_id, 'total_filas', v_total_rows, 'estado', 'pendiente');

end;
 $$;


--
-- Name: seller_iniciar_trial(text, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_iniciar_trial(p_plan_codigo text DEFAULT 'silver'::text, p_dias_trial integer DEFAULT 14) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor         uuid;
    v_plan_id       uuid;
    v_plan_actual   text;
    v_ya_uso_trial  boolean := false;
    v_trial_dispon  boolean;
BEGIN
    v_actor := auth.fn_current_user_id();

    -- Verificar que el plan objetivo tiene trial disponible
    SELECT (feature_flags ->> 'trial_disponible')::boolean, id
    INTO v_trial_dispon, v_plan_id
    FROM auth.planes_membresia WHERE codigo = p_plan_codigo AND activo = true;

    IF NOT COALESCE(v_trial_dispon, false) THEN
        RAISE EXCEPTION 'plan_sin_trial: el plan % no tiene trial disponible', p_plan_codigo
        USING ERRCODE = 'P0001';
    END IF;

    -- Verificar que no usó trial antes para este plan
    SELECT EXISTS(
        SELECT 1 FROM auth.membresias_historial
        WHERE id_vendedor = v_actor AND evento = 'trial_inicio'
          AND plan_nuevo = p_plan_codigo
    ) INTO v_ya_uso_trial;

    IF v_ya_uso_trial THEN
        RAISE EXCEPTION 'trial_ya_usado: ya usaste el trial del plan %', p_plan_codigo
        USING ERRCODE = 'P0001';
    END IF;

    -- Verificar que es upgrade vs plan actual
    SELECT pm.codigo INTO v_plan_actual
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.id_vendedor = v_actor AND mv.estado IN ('activo', 'grace_period')
    LIMIT 1;

    IF v_plan_actual = p_plan_codigo THEN
        RAISE EXCEPTION 'ya_tienes_este_plan: no necesitas trial de %', p_plan_codigo
        USING ERRCODE = 'P0001';
    END IF;

    -- Activar trial
    UPDATE auth.membresias_vendedor
    SET id_plan          = v_plan_id,
        es_trial         = true,
        trial_expiracion = now() + (p_dias_trial || ' days')::interval,
        auto_renovar     = false
    WHERE id_vendedor = v_actor
      AND estado IN ('activo', 'grace_period')
      AND fecha_eliminacion IS NULL;

    RETURN jsonb_build_object(
        'trial_iniciado', true,
        'plan',           p_plan_codigo,
        'dias',           p_dias_trial,
        'expira_en',      now() + (p_dias_trial || ' days')::interval
    );
END;
$$;


--
-- Name: seller_iniciar_venta(uuid, double precision, double precision, double precision, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_iniciar_venta(p_id_vendedor uuid, p_lat double precision, p_lng double precision, p_visibility_radius_meters double precision DEFAULT 1200, p_spot_label text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_caller_id   UUID;
    v_new_punto   GEOGRAPHY;
    v_rows_ub     INT;
    v_rows_ppv    INT;
BEGIN
    -- Autenticación
    v_caller_id := auth.jwt_user_id();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'No autenticado' USING ERRCODE = 'PT401';
    END IF;

    -- Autorización: solo el propio vendedor
    IF v_caller_id <> p_id_vendedor THEN
        RAISE EXCEPTION 'Solo el propio vendedor puede iniciar su sesión de venta'
            USING ERRCODE = 'PT403';
    END IF;

    -- Validaciones (RN-04)
    IF p_visibility_radius_meters <= 0 OR p_visibility_radius_meters > 5000 THEN
        RAISE EXCEPTION 'El radio de visibilidad debe estar entre 1 y 5000 metros'
            USING ERRCODE = 'P0001';
    END IF;
    IF p_lat < -90 OR p_lat > 90 THEN
        RAISE EXCEPTION 'Latitud inválida: debe estar entre -90 y 90'
            USING ERRCODE = 'P0001';
    END IF;
    IF p_lng < -180 OR p_lng > 180 THEN
        RAISE EXCEPTION 'Longitud inválida: debe estar entre -180 y 180'
            USING ERRCODE = 'P0001';
    END IF;

    -- Construir punto geography (4326)
    v_new_punto := ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography;

    -- Actualizar auth.ubicaciones (estado='activo', punto actualizado)
    UPDATE auth.ubicaciones
    SET
        punto      = v_new_punto,
        latitud    = p_lat,
        longitud   = p_lng,
        estado     = 'activo',
        fecha_actualizacion = now()
    WHERE id_usuario = p_id_vendedor;
    GET DIAGNOSTICS v_rows_ub = ROW_COUNT;

    IF v_rows_ub = 0 THEN
        -- Si no existe registro de ubicación, insertar
        INSERT INTO auth.ubicaciones (id_usuario, latitud, longitud, punto, estado, fecha_creacion, fecha_actualizacion)
        VALUES (p_id_vendedor, p_lat, p_lng, v_new_punto, 'activo', now(), now());
    END IF;

    -- Actualizar auth.perfiles_publicos_vendedor
    UPDATE auth.perfiles_publicos_vendedor
    SET
        is_disponible          = true,
        visibility_radius_meters = p_visibility_radius_meters,
        spot_label             = p_spot_label,
        fecha_modificacion     = now()
    WHERE id_vendedor = p_id_vendedor;
    GET DIAGNOSTICS v_rows_ppv = ROW_COUNT;

    IF v_rows_ppv = 0 THEN
        RAISE EXCEPTION 'Vendedor no tiene perfil público. Crear perfil antes de iniciar venta.'
            USING ERRCODE = 'P0002';
    END IF;

    -- Auditoría en auth.h_vendedores_audit (RN-08)
    -- PENDIENTE_INTROSPECCION: verificar columnas reales de h_vendedores_audit
    INSERT INTO auth.h_vendedores_audit (
        id_usuario,
        modificado_por,
        evento,
        datos_nuevos,
        fecha_cambio
    ) VALUES (
        p_id_vendedor,
        v_caller_id,
        'SELLER_STARTED_SELLING',
        jsonb_build_object(
            'spot_label',               p_spot_label,
            'visibility_radius_meters', p_visibility_radius_meters,
            'lat',                      p_lat,
            'lng',                      p_lng
        ),
        now()
    );

    RETURN jsonb_build_object(
        'status',                    'OK',
        'id_vendedor',            p_id_vendedor,
        'is_disponible',             true,
        'estado_ubicacion',          'activo',
        'visibility_radius_meters',  p_visibility_radius_meters,
        'spot_label',                p_spot_label,
        'lat',                       p_lat,
        'lng',                       p_lng,
        'ts',                        now()
    );
END;
$$;


--
-- Name: seller_inventory_adjust(uuid, uuid, integer, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_inventory_adjust(p_producto_id uuid, p_ubicacion_id uuid, p_delta integer, p_tipo_movimiento text, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := auth.fn_current_user_id();
    v_limits jsonb;
    v_ubicaciones_actuales integer;
    v_max_locations integer;
    v_max_adjustments integer;
    v_ajustes_hoy integer;
    v_producto record;
    v_ubic record;
    v_stock_antes integer;
    v_stock_despues integer;
BEGIN
    -- RN-004: Cantidad no puede ser cero
    IF p_delta = 0 THEN
        RAISE EXCEPTION 'La cantidad del movimiento no puede ser cero [RN-004]';
    END IF;

    -- RN-005: Tipos de movimiento válidos para ajuste manual
    IF p_tipo_movimiento NOT IN ('entrada','salida','ajuste_positivo','ajuste_negativo') THEN
        RAISE EXCEPTION 'Tipo de movimiento inválido para ajuste manual [RN-005]. Válidos: entrada, salida, ajuste_positivo, ajuste_negativo';
    END IF;

    -- RN-006: Motivo obligatorio para ajuste negativo (min 5 chars)
    IF p_tipo_movimiento = 'ajuste_negativo' AND length(trim(coalesce(p_motivo,''))) < 5 THEN
        RAISE EXCEPTION 'Motivo requerido para ajuste negativo (mínimo 5 caracteres) [RN-006]';
    END IF;

    -- RN-001: Vendedor operable
    PERFORM auth.fn_assert_seller_operable(v_actor);

    -- RN-007: Producto pertenece al vendedor
    SELECT id, id_vendedor, activo INTO v_producto
    FROM auth.productos WHERE id = p_producto_id AND id_vendedor = v_actor;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Producto no pertenece al vendedor [RN-007]' USING ERRCODE = '42501';
    END IF;

    -- RN-008: Ubicación activa pertenece al vendedor
    SELECT id, id_usuario, latitud, longitud, estado INTO v_ubic
    FROM auth.ubicaciones
    WHERE id = p_ubicacion_id AND id_usuario = v_actor AND estado = 'activo';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ubicación activa no pertenece al vendedor [RN-008]' USING ERRCODE = '42501';
    END IF;

    -- RN-009: Límite de ubicaciones por plan
    v_limits := auth.fn_get_inventory_limits(v_actor);
    v_max_locations := (v_limits ->> 'max_inventory_locations')::integer;

    SELECT count(DISTINCT id_ubicacion) INTO v_ubicaciones_actuales
    FROM auth.inventario_ubicacion
    WHERE id_vendedor = v_actor AND activo = true;

    IF NOT EXISTS (
        SELECT 1 FROM auth.inventario_ubicacion
        WHERE id_producto = p_producto_id AND id_ubicacion = p_ubicacion_id
    ) AND v_ubicaciones_actuales >= v_max_locations THEN
        -- Generar alerta de límite de plan
        INSERT INTO auth.alertas_inventario(id_vendedor, tipo_alerta, severidad, mensaje, metadata)
        VALUES (v_actor, 'limite_plan_alcanzado', 'media',
                format('Límite de %s ubicaciones alcanzado para tu plan. Actualiza tu membresía.', v_max_locations),
                jsonb_build_object('max_locations', v_max_locations, 'actuales', v_ubicaciones_actuales))
        ON CONFLICT DO NOTHING;
        RAISE EXCEPTION 'Límite de ubicaciones de inventario alcanzado para tu plan (máx: %) [RN-009]. Actualiza tu membresía.', v_max_locations;
    END IF;

    -- RN-010: Límite de ajustes diarios por plan
    v_max_adjustments := (v_limits ->> 'max_daily_adjustments')::integer;
    SELECT count(*) INTO v_ajustes_hoy
    FROM auth.movimientos_inventario
    WHERE id_vendedor = v_actor
      AND actor_role = 'seller'
      AND tipo_movimiento IN ('entrada','salida','ajuste_positivo','ajuste_negativo')
      AND fecha_movimiento >= current_date
      AND fecha_movimiento < current_date + interval '1 day';

    IF v_ajustes_hoy >= v_max_adjustments THEN
        RAISE EXCEPTION 'Límite diario de ajustes alcanzado (% de %) [RN-010]. Se reinicia a medianoche.', v_ajustes_hoy, v_max_adjustments;
    END IF;

    -- Upsert inventario_producto (puede no existir si se usa antes de init)
    INSERT INTO auth.inventario_producto(id_producto, id_vendedor)
    VALUES (p_producto_id, v_actor)
    ON CONFLICT (id_producto) DO NOTHING;

    -- Upsert inventario_ubicacion
    INSERT INTO auth.inventario_ubicacion(id_producto, id_vendedor, id_ubicacion, stock)
    VALUES (p_producto_id, v_actor, p_ubicacion_id, 0)
    ON CONFLICT (id_producto, id_ubicacion) DO NOTHING;

    -- RN-011: Lock optimista sobre la fila de ubicación
    SELECT stock INTO v_stock_antes
    FROM auth.inventario_ubicacion
    WHERE id_producto = p_producto_id AND id_ubicacion = p_ubicacion_id
    FOR UPDATE;

    v_stock_despues := v_stock_antes + p_delta;

    -- RN-012: Stock no puede quedar negativo
    IF v_stock_despues < 0 THEN
        RAISE EXCEPTION 'Stock resultante negativo (actual: %, delta: %) [RN-012]', v_stock_antes, p_delta;
    END IF;

    UPDATE auth.inventario_ubicacion
    SET stock = v_stock_despues, fecha_modificacion = now()
    WHERE id_producto = p_producto_id AND id_ubicacion = p_ubicacion_id;

    -- RN-013: Registrar movimiento inmutable
    INSERT INTO auth.movimientos_inventario(
        id_producto, id_vendedor, id_ubicacion, tipo_movimiento,
        cantidad, stock_anterior, stock_posterior, motivo, actor_user_id, actor_role
    )
    VALUES (
        p_producto_id, v_actor, p_ubicacion_id, p_tipo_movimiento,
        p_delta, v_stock_antes, v_stock_despues, p_motivo, v_actor, 'seller'
    );

    -- Recalcular agregado
    PERFORM auth.fn_recalc_inventory_product(p_producto_id);

    -- RN-014: Verificar alertas
    PERFORM auth.fn_inventory_alert_check(p_producto_id);

    -- RN-015: Sincronizar productos_geo con ubicación principal de stock
    INSERT INTO auth.productos_geo(id_producto, id_vendedor, latitud, longitud, punto)
    VALUES (
        p_producto_id, v_actor, v_ubic.latitud, v_ubic.longitud,
        ST_SetSRID(ST_MakePoint(v_ubic.longitud, v_ubic.latitud), 4326)::geography
    )
    ON CONFLICT (id_producto) DO UPDATE SET
        latitud = EXCLUDED.latitud,
        longitud = EXCLUDED.longitud,
        punto = EXCLUDED.punto,
        fecha_actualizacion = now();

    -- RN-016: Encolar evento AGE
    INSERT INTO auth.inventario_graph_outbox(evento, id_producto, id_vendedor, id_ubicacion, payload)
    SELECT
        CASE WHEN v_stock_despues = 0 THEN 'ubicacion_sin_stock' ELSE 'stock_actualizado' END,
        p_producto_id, v_actor, p_ubicacion_id,
        jsonb_build_object(
            'stock_disponible', ip.stock_disponible,
            'stock_total', ip.total_stock,
            'tipo_movimiento', p_tipo_movimiento
        )
    FROM auth.inventario_producto ip WHERE ip.id_producto = p_producto_id;

    RETURN jsonb_build_object(
        'ok', true,
        'producto_id', p_producto_id,
        'ubicacion_id', p_ubicacion_id,
        'stock_anterior', v_stock_antes,
        'stock_posterior', v_stock_despues,
        'tipo_movimiento', p_tipo_movimiento
    );
END;
$$;


--
-- Name: seller_inventory_get_movimientos(uuid, text, integer, timestamp with time zone); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_inventory_get_movimientos(p_producto_id uuid DEFAULT NULL::uuid, p_tipo text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := auth.fn_current_user_id();
BEGIN
    RETURN QUERY
    SELECT jsonb_build_object(
        'id', m.id,
        'producto_id', m.id_producto,
        'producto_nombre', p.nombre,
        'ubicacion_id', m.id_ubicacion,
        'tipo_movimiento', m.tipo_movimiento,
        'cantidad', m.cantidad,
        'stock_anterior', m.stock_anterior,
        'stock_posterior', m.stock_posterior,
        'motivo', m.motivo,
        'referencia_tipo', m.referencia_tipo,
        'referencia_id', m.referencia_id,
        'fecha_movimiento', m.fecha_movimiento
    )
    FROM auth.movimientos_inventario m
    JOIN auth.productos p ON p.id = m.id_producto
    WHERE m.id_vendedor = v_actor
      AND (p_producto_id IS NULL OR m.id_producto = p_producto_id)
      AND (p_tipo IS NULL OR m.tipo_movimiento = p_tipo)
      AND (p_cursor IS NULL OR m.fecha_movimiento < p_cursor)
    ORDER BY m.fecha_movimiento DESC
    LIMIT LEAST(p_limit, 200);
END;
$$;


--
-- Name: seller_inventory_get_resumen(boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_inventory_get_resumen(p_solo_activos boolean DEFAULT true) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := auth.fn_current_user_id();
BEGIN
    RETURN QUERY
    SELECT jsonb_build_object(
        'producto_id', ip.id_producto,
        'producto_nombre', p.nombre,
        'producto_activo', p.activo,
        'sku', ip.sku,
        'stock_total', ip.total_stock,
        'stock_reservado', ip.stock_reservado,
        'stock_disponible', ip.stock_disponible,
        'umbral_alerta', ip.umbral_alerta,
        'permite_backorder', ip.permite_backorder,
        'estado_stock', CASE
            WHEN ip.stock_disponible <= 0 THEN 'sin_stock'
            WHEN ip.stock_disponible <= ip.umbral_alerta THEN 'stock_bajo'
            ELSE 'normal'
        END,
        'ubicaciones_con_stock', (
            SELECT count(*) FROM auth.inventario_ubicacion iu
            WHERE iu.id_producto = ip.id_producto AND iu.activo = true AND iu.stock > 0
        ),
        'alertas_no_leidas', (
            SELECT count(*) FROM auth.alertas_inventario ai
            WHERE ai.id_producto = ip.id_producto AND ai.leida = false AND ai.resuelta = false
        ),
        'actualizado_en', ip.fecha_modificacion
    )
    FROM auth.inventario_producto ip
    JOIN auth.productos p ON p.id = ip.id_producto
    WHERE ip.id_vendedor = v_actor
      AND (NOT p_solo_activos OR p.activo = true)
    ORDER BY
        CASE WHEN ip.stock_disponible <= 0 THEN 0
             WHEN ip.stock_disponible <= ip.umbral_alerta THEN 1
             ELSE 2 END,
        ip.fecha_modificacion DESC;
END;
$$;


--
-- Name: seller_inventory_init(uuid, text, integer, boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_inventory_init(p_producto_id uuid, p_sku text DEFAULT NULL::text, p_umbral_alerta integer DEFAULT 1, p_permite_backorder boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := auth.fn_current_user_id();
    v_producto record;
BEGIN
    -- RN-001: Actor debe ser vendedor operable
    PERFORM auth.fn_assert_seller_operable(v_actor);

    -- RN-002: El producto debe pertenecer al vendedor y estar activo
    SELECT id, id_vendedor, activo INTO v_producto
    FROM auth.productos
    WHERE id = p_producto_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Producto inexistente [RN-002]' USING ERRCODE = '42501';
    END IF;
    IF v_producto.id_vendedor <> v_actor THEN
        RAISE EXCEPTION 'Producto no pertenece al vendedor [RN-002]' USING ERRCODE = '42501';
    END IF;
    IF v_producto.activo IS DISTINCT FROM true THEN
        RAISE EXCEPTION 'Solo se puede inicializar inventario para productos activos [RN-002]';
    END IF;

    -- RN-003: SKU único por vendedor si se proporciona
    IF p_sku IS NOT NULL AND EXISTS (
        SELECT 1 FROM auth.inventario_producto
        WHERE id_vendedor = v_actor AND sku = trim(p_sku) AND id_producto <> p_producto_id
    ) THEN
        RAISE EXCEPTION 'SKU ya existe para este vendedor [RN-003]';
    END IF;

    INSERT INTO auth.inventario_producto(
        id_producto, id_vendedor, sku, umbral_alerta, permite_backorder
    )
    VALUES (
        p_producto_id, v_actor,
        NULLIF(trim(p_sku),''),
        GREATEST(p_umbral_alerta, 0),
        p_permite_backorder
    )
    ON CONFLICT (id_producto) DO UPDATE SET
        sku = COALESCE(EXCLUDED.sku, auth.inventario_producto.sku),
        umbral_alerta = EXCLUDED.umbral_alerta,
        permite_backorder = EXCLUDED.permite_backorder,
        fecha_modificacion = now();

    RETURN jsonb_build_object('ok', true, 'producto_id', p_producto_id, 'sku', NULLIF(trim(p_sku),''));
END;
$$;


--
-- Name: seller_inventory_marcar_alerta_leida(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_inventory_marcar_alerta_leida(p_alerta_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := auth.fn_current_user_id();
    v_updated integer;
BEGIN
    UPDATE auth.alertas_inventario
    SET leida = true
    WHERE id = p_alerta_id AND id_vendedor = v_actor;

    GET DIAGNOSTICS v_updated = ROW_COUNT;

    IF v_updated = 0 THEN
        RAISE EXCEPTION 'Alerta no encontrada o no pertenece al vendedor';
    END IF;

    RETURN jsonb_build_object('ok', true, 'alerta_id', p_alerta_id);
END;
$$;


--
-- Name: seller_inventory_transfer(uuid, uuid, uuid, integer, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_inventory_transfer(p_producto_id uuid, p_origen_ubicacion_id uuid, p_destino_ubicacion_id uuid, p_cantidad integer, p_motivo text DEFAULT 'transferencia entre ubicaciones'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid := auth.fn_current_user_id();
    v_limits jsonb;
    v_stock_origen integer;
    v_stock_destino integer;
BEGIN
    -- RN-017: Cantidad positiva
    IF p_cantidad <= 0 THEN
        RAISE EXCEPTION 'La cantidad a transferir debe ser positiva [RN-017]';
    END IF;

    -- RN-018: Origen ≠ Destino
    IF p_origen_ubicacion_id = p_destino_ubicacion_id THEN
        RAISE EXCEPTION 'Origen y destino deben ser ubicaciones distintas [RN-018]';
    END IF;

    -- RN-001: Vendedor operable
    PERFORM auth.fn_assert_seller_operable(v_actor);

    -- RN-019: Solo Silver+ puede transferir (feature flag)
    v_limits := auth.fn_get_inventory_limits(v_actor);
    IF (v_limits ->> 'inventory_transfers')::boolean IS NOT TRUE THEN
        RAISE EXCEPTION 'Tu plan no incluye transferencias de inventario entre ubicaciones [RN-019]. Actualiza a Silver o Gold.';
    END IF;

    -- RN-020: Producto pertenece al vendedor
    IF NOT EXISTS (
        SELECT 1 FROM auth.productos WHERE id = p_producto_id AND id_vendedor = v_actor
    ) THEN
        RAISE EXCEPTION 'Producto no pertenece al vendedor [RN-020]' USING ERRCODE = '42501';
    END IF;

    -- RN-021: Ambas ubicaciones activas pertenecen al vendedor
    IF (
        SELECT count(*) FROM auth.ubicaciones
        WHERE id IN (p_origen_ubicacion_id, p_destino_ubicacion_id)
          AND id_usuario = v_actor AND estado = 'activo'
    ) < 2 THEN
        RAISE EXCEPTION 'Ambas ubicaciones deben ser activas y pertenecer al vendedor [RN-021]' USING ERRCODE = '42501';
    END IF;

    -- Upsert destino si no existe
    INSERT INTO auth.inventario_ubicacion(id_producto, id_vendedor, id_ubicacion, stock)
    VALUES (p_producto_id, v_actor, p_destino_ubicacion_id, 0)
    ON CONFLICT (id_producto, id_ubicacion) DO NOTHING;

    -- Lock en orden determinístico para evitar deadlock
    IF p_origen_ubicacion_id < p_destino_ubicacion_id THEN
        SELECT stock_disponible INTO v_stock_origen
        FROM auth.inventario_ubicacion
        WHERE id_producto = p_producto_id AND id_ubicacion = p_origen_ubicacion_id FOR UPDATE;

        SELECT stock INTO v_stock_destino
        FROM auth.inventario_ubicacion
        WHERE id_producto = p_producto_id AND id_ubicacion = p_destino_ubicacion_id FOR UPDATE;
    ELSE
        SELECT stock INTO v_stock_destino
        FROM auth.inventario_ubicacion
        WHERE id_producto = p_producto_id AND id_ubicacion = p_destino_ubicacion_id FOR UPDATE;

        SELECT stock_disponible INTO v_stock_origen
        FROM auth.inventario_ubicacion
        WHERE id_producto = p_producto_id AND id_ubicacion = p_origen_ubicacion_id FOR UPDATE;
    END IF;

    -- RN-022: Stock disponible en origen suficiente
    IF COALESCE(v_stock_origen, 0) < p_cantidad THEN
        RAISE EXCEPTION 'Stock disponible en origen insuficiente (disponible: %, solicitado: %) [RN-022]',
            COALESCE(v_stock_origen, 0), p_cantidad;
    END IF;

    UPDATE auth.inventario_ubicacion
    SET stock = stock - p_cantidad, fecha_modificacion = now()
    WHERE id_producto = p_producto_id AND id_ubicacion = p_origen_ubicacion_id;

    UPDATE auth.inventario_ubicacion
    SET stock = stock + p_cantidad, fecha_modificacion = now()
    WHERE id_producto = p_producto_id AND id_ubicacion = p_destino_ubicacion_id;

    -- RN-013: Dos movimientos inmutables (salida + entrada)
    INSERT INTO auth.movimientos_inventario(
        id_producto, id_vendedor, id_ubicacion, ubicacion_destino_id,
        tipo_movimiento, cantidad, motivo, actor_user_id, actor_role
    )
    VALUES
    (p_producto_id, v_actor, p_origen_ubicacion_id, p_destino_ubicacion_id,
     'transferencia_salida', -p_cantidad, p_motivo, v_actor, 'seller'),
    (p_producto_id, v_actor, p_destino_ubicacion_id, p_origen_ubicacion_id,
     'transferencia_entrada', p_cantidad, p_motivo, v_actor, 'seller');

    PERFORM auth.fn_recalc_inventory_product(p_producto_id);
    PERFORM auth.fn_inventory_alert_check(p_producto_id);

    -- Encolar AGE
    INSERT INTO auth.inventario_graph_outbox(evento, id_producto, id_vendedor, id_ubicacion, payload)
    VALUES (
        'stock_actualizado', p_producto_id, v_actor, p_destino_ubicacion_id,
        jsonb_build_object('tipo', 'transferencia', 'cantidad', p_cantidad)
    );

    RETURN jsonb_build_object(
        'ok', true,
        'producto_id', p_producto_id,
        'cantidad_transferida', p_cantidad,
        'origen', p_origen_ubicacion_id,
        'destino', p_destino_ubicacion_id
    );
END;
$$;


--
-- Name: seller_keepalive(double precision, double precision); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_keepalive(p_lat double precision, p_lon double precision) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor_id      uuid;
  v_prev_punto    geography;
  v_new_punto     geography;
  v_distance_m    double precision := 0;
  v_is_disponible boolean;
  v_last_ka       timestamptz;
BEGIN
  v_actor_id := auth.fn_current_user_id();

  IF auth.fn_current_user_role() <> 'seller' THEN
    RAISE EXCEPTION 'seller_role_required';
  END IF;

  -- Throttle: máximo 1 keepalive cada 10 segundos por vendedor
  SELECT ppv.is_disponible, ppv.last_keepalive_at
  INTO v_is_disponible, v_last_ka
  FROM auth.perfiles_publicos_vendedor ppv
  WHERE ppv.id_vendedor = v_actor_id AND ppv.activo = true
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'seller_public_profile_not_found';
  END IF;

  IF v_last_ka IS NOT NULL AND (now() - v_last_ka) < interval '10 seconds' THEN
    RAISE EXCEPTION 'keepalive_throttled_wait_10s';
  END IF;

  -- Validar coordenadas
  IF p_lat IS NULL OR p_lon IS NULL THEN
    RAISE EXCEPTION 'lat_lon_required';
  END IF;
  IF p_lat NOT BETWEEN -90 AND 90 THEN
    RAISE EXCEPTION 'lat_fuera_de_rango';
  END IF;
  IF p_lon NOT BETWEEN -180 AND 180 THEN
    RAISE EXCEPTION 'lon_fuera_de_rango';
  END IF;

  v_new_punto := ST_SetSRID(ST_MakePoint(p_lon, p_lat), 4326)::geography;

  -- Obtener punto previo para calcular desplazamiento
  SELECT u.punto INTO v_prev_punto
  FROM auth.ubicaciones u
  WHERE u.id_usuario = v_actor_id AND u.estado = 'activo'
  ORDER BY u.fecha_actualizacion DESC NULLS LAST LIMIT 1;

  IF v_prev_punto IS NOT NULL THEN
    v_distance_m := ST_Distance(v_new_punto, v_prev_punto);
  END IF;

  -- Actualizar ubicación activa (UPSERT: actualiza la fila más reciente activa)
  UPDATE auth.ubicaciones
  SET punto      = v_new_punto,
      latitud    = p_lat,
      longitud   = p_lon,
      estado     = 'activo',
      fecha_actualizacion = now()
  WHERE id_usuario = v_actor_id AND estado = 'activo';

  -- Si no hay fila activa, insertar nueva
  IF NOT FOUND THEN
    INSERT INTO auth.ubicaciones (id_usuario, latitud, longitud, punto, estado)
    VALUES (v_actor_id, p_lat, p_lon, v_new_punto, 'activo');
  END IF;

  -- Actualizar presencia en perfil
  UPDATE auth.perfiles_publicos_vendedor
  SET is_disponible     = true,
      last_seen         = now(),
      last_keepalive_at = now()
  WHERE id_vendedor = v_actor_id;

  -- Auditoría si desplazamiento > 100 m (RN-004)
  IF v_distance_m > 100 THEN
    PERFORM auth.fn_write_merca_audit(
      v_actor_id,
      'SELLER_LOCATION_UPDATED',
      jsonb_build_object(
        'lat', p_lat,
        'lon', p_lon,
        'distance_m', round(v_distance_m::numeric, 2)
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'status',        'OK',
    'last_seen',     now(),
    'lat',           p_lat,
    'lon',           p_lon,
    'distance_m',    round(v_distance_m::numeric, 2),
    'pulse_refresh', v_distance_m > 100,
    'is_disponible', true
  );
END; $$;


--
-- Name: seller_lanzar_campana_general(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_lanzar_campana_general(p_campana_id uuid, p_segmento text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor      uuid;
    v_campana    auth.campanas%ROWTYPE;
    v_compradores uuid[];
    v_enviados   int := 0;
    r            record;
BEGIN
    v_actor := (nullif(current_setting('request.jwt.claims', true),'')::jsonb ->> 'sub')::uuid;

    SELECT * INTO v_campana FROM auth.campanas
    WHERE id = p_campana_id AND id_vendedor = v_actor;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Campaña no encontrada' USING ERRCODE = 'P0078';
    END IF;
    IF v_campana.estado NOT IN ('borrador','pausada') THEN
        RAISE EXCEPTION 'La campaña debe estar en borrador o pausada' USING ERRCODE = 'P0079';
    END IF;
    IF v_campana.tipo NOT IN ('general','rfm') THEN
        RAISE EXCEPTION 'Use la RPC específica para campañas de tipo %', v_campana.tipo
            USING ERRCODE = 'P0080';
    END IF;

    SELECT ARRAY_AGG(DISTINCT o.id_comprador) INTO v_compradores
    FROM auth.ordenes o
    LEFT JOIN auth.rfm_snapshots rfm
        ON rfm.id_vendedor = v_actor AND rfm.id_comprador = o.id_comprador
    WHERE o.id_vendedor = v_actor
      AND o.estado = 'confirmada'
      AND (p_segmento IS NULL OR rfm.segmento_rfm = p_segmento);

    INSERT INTO auth.campana_segmentos
        (id_campana, tipo_segmento, criterios, compradores_ids, total_objetivo)
    VALUES (
        p_campana_id,
        CASE WHEN p_segmento IS NOT NULL THEN 'rfm' ELSE 'todos' END,
        jsonb_build_object('segmento_rfm', p_segmento),
        COALESCE(v_compradores, '{}'),
        COALESCE(array_length(v_compradores, 1), 0)
    );

    FOR r IN SELECT unnest(v_compradores) AS id_comprador LOOP
        INSERT INTO auth.notificaciones
            (id_usuario, tipo, titulo, cuerpo, referencia_tipo, referencia_id)
        SELECT
            r.id_comprador, 'campana',
            COALESCE(p.nombre, v_campana.nombre),
            COALESCE(p.descripcion, v_campana.descripcion, 'Oferta especial para ti'),
            'campana', p_campana_id
        FROM auth.campanas ca
        LEFT JOIN auth.promociones p ON p.id = ca.id_promocion
        WHERE ca.id = p_campana_id
        ON CONFLICT DO NOTHING;

        INSERT INTO auth.push_notification_queue
            (id_vendedor, id_comprador, tipo, titulo, cuerpo, metadata, estado)
        SELECT v_actor, r.id_comprador, 'campana_general',
            COALESCE(p.nombre, v_campana.nombre),
            COALESCE(p.descripcion, 'Tienes una oferta'),
            jsonb_build_object('campana_id', p_campana_id),
            'pendiente'
        FROM auth.campanas ca
        LEFT JOIN auth.promociones p ON p.id = ca.id_promocion
        WHERE ca.id = p_campana_id;

        INSERT INTO auth.campana_log(id_campana, id_usuario, evento, canal)
        VALUES (p_campana_id, r.id_comprador, 'enviado', 'push')
        ON CONFLICT DO NOTHING;

        v_enviados := v_enviados + 1;
    END LOOP;

    UPDATE auth.campanas SET
        estado = 'activa',
        alcance_total = COALESCE(array_length(v_compradores, 1), 0),
        fecha_modificacion = now()
    WHERE id = p_campana_id;

    RETURN jsonb_build_object(
        'ok', true, 'campana_id', p_campana_id,
        'compradores_alcanzados', v_enviados,
        'segmento', p_segmento
    );
END;
$$;


--
-- Name: seller_lanzar_campana_geo(uuid, numeric); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_lanzar_campana_geo(p_campana_id uuid, p_radio_km numeric DEFAULT 5.0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor       uuid;
    v_campana     auth.campanas%ROWTYPE;
    v_compradores uuid[];
    v_enviados    int := 0;
    r             record;
BEGIN
    v_actor := (nullif(current_setting('request.jwt.claims', true),'')::jsonb ->> 'sub')::uuid;

    SELECT * INTO v_campana FROM auth.campanas
    WHERE id = p_campana_id AND id_vendedor = v_actor;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Campaña no encontrada' USING ERRCODE = 'P0081';
    END IF;
    IF v_campana.tipo <> 'geo' THEN
        RAISE EXCEPTION 'Esta RPC es solo para campañas tipo geo' USING ERRCODE = 'P0082';
    END IF;
    IF p_radio_km <= 0 OR p_radio_km > 200 THEN
        RAISE EXCEPTION 'radio_km debe estar entre 0.1 y 200' USING ERRCODE = 'P0083';
    END IF;

    -- Compradores que compraron al vendedor Y tienen ubicación dentro del radio
    -- Usa ST_DWithin de PostGIS (distancia en metros = km * 1000)
    -- auth.user_profiles.ultima_ubicacion es geometry(Point,4326) (CU-V-004)
    SELECT ARRAY_AGG(DISTINCT o.id_comprador) INTO v_compradores
    FROM auth.ordenes o
    JOIN auth.user_profiles up ON up.id_usuario = o.id_comprador
    JOIN auth.ubicaciones uv ON uv.id_vendedor = v_actor AND uv.activa = true
    WHERE o.id_vendedor = v_actor
      AND o.estado = 'confirmada'
      AND up.ultima_ubicacion IS NOT NULL
      AND ST_DWithin(
          up.ultima_ubicacion::geography,
          uv.coordenadas::geography,
          p_radio_km * 1000
      );

    -- Guardar segmento geo
    INSERT INTO auth.campana_segmentos
        (id_campana, tipo_segmento, criterios, compradores_ids, total_objetivo)
    VALUES (
        p_campana_id, 'geo',
        jsonb_build_object('radio_km', p_radio_km, 'id_vendedor', v_actor),
        COALESCE(v_compradores, '{}'),
        COALESCE(array_length(v_compradores, 1), 0)
    );

    FOR r IN SELECT unnest(v_compradores) AS id_comprador LOOP
        INSERT INTO auth.notificaciones
            (id_usuario, tipo, titulo, cuerpo, referencia_tipo, referencia_id)
        SELECT r.id_comprador, 'campana_geo',
            COALESCE(p.nombre, v_campana.nombre),
            'Estás cerca de un vendedor con oferta especial',
            'campana', p_campana_id
        FROM auth.campanas ca
        LEFT JOIN auth.promociones p ON p.id = ca.id_promocion
        WHERE ca.id = p_campana_id
        ON CONFLICT DO NOTHING;

        INSERT INTO auth.campana_log(id_campana, id_usuario, evento, canal, metadata)
        VALUES (p_campana_id, r.id_comprador, 'enviado', 'push',
            jsonb_build_object('origen', 'geo', 'radio_km', p_radio_km))
        ON CONFLICT DO NOTHING;

        v_enviados := v_enviados + 1;
    END LOOP;

    UPDATE auth.campanas SET
        estado = 'activa',
        alcance_total = COALESCE(array_length(v_compradores, 1), 0),
        fecha_modificacion = now()
    WHERE id = p_campana_id;

    RETURN jsonb_build_object(
        'ok', true, 'campana_id', p_campana_id,
        'compradores_en_radio', v_enviados,
        'radio_km', p_radio_km
    );
END;
$$;


--
-- Name: seller_lanzar_campana_proximidad(uuid, text, text, numeric, jsonb, timestamp with time zone, timestamp with time zone, double precision, public.geometry); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_lanzar_campana_proximidad(p_id_vendedor uuid, p_nombre text, p_tipo_incentivo text, p_valor_incentivo numeric, p_segmento_objetivo jsonb, p_fecha_inicio timestamp with time zone DEFAULT now(), p_fecha_fin timestamp with time zone DEFAULT NULL::timestamp with time zone, p_radio_metros double precision DEFAULT NULL::double precision, p_geom public.geometry DEFAULT NULL::public.geometry) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  INSERT INTO auth.campanias_vendedor
    (id_vendedor, nombre, tipo_incentivo, valor_incentivo, segmento_objetivo,
     fecha_inicio, fecha_fin, estado, metadata, created_at, updated_at)
  VALUES (p_id_vendedor, p_nombre, p_tipo_incentivo, p_valor_incentivo,
     COALESCE(p_segmento_objetivo, '{}'::jsonb) || jsonb_build_object('radio_metros', p_radio_metros),
     p_fecha_inicio, p_fecha_fin, 'ACTIVA',
     jsonb_build_object('geo', CASE WHEN p_geom IS NULL THEN NULL ELSE ST_AsGeoJSON(p_geom)::jsonb END),
     now(), now())
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id, 'nombre', p_nombre, 'estado', 'ACTIVA');
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END;
$$;


--
-- Name: seller_listar_categorias_propias(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_listar_categorias_propias() RETURNS TABLE(id uuid, nombre text, descripcion text, id_tipo_producto uuid, subcategorias jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
  SELECT c.id,
         c.nombre,
         c.descripcion,
         c.id_tipo_producto,
         COALESCE(
           (SELECT jsonb_agg(
                     jsonb_build_object(
                       'id', s.id, 'nombre', s.nombre, 'descripcion', s.descripcion
                     ) ORDER BY s.nombre
                   )
              FROM auth.subcategorias s
             WHERE s.id_categoria = c.id
               AND s.fecha_eliminacion IS NULL
               AND coalesce(s.activo, true)),
           '[]'::jsonb
         ) AS subcategorias
    FROM auth.categorias c
   WHERE c.id_vendedor = auth.current_jwt_user_id()
     AND c.fecha_eliminacion IS NULL
     AND coalesce(c.activo, true)
   ORDER BY c.nombre;
$$;


--
-- Name: seller_listar_imagenes(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_listar_imagenes(p_id_producto uuid) RETURNS TABLE(id uuid, url text, es_portada boolean, descripcion text, mime_type text, contenido_base64 text, orden integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
  SELECT gf.id,
         gf.url,
         gf.es_portada,
         gf.descripcion,
         gf.mime_type,
         CASE WHEN gf.data_bytea IS NOT NULL THEN encode(gf.data_bytea, 'base64') ELSE NULL END,
         COALESCE(gf.orden, 0)
    FROM auth.galeria_fotos gf
   WHERE gf.id_producto = p_id_producto
     AND gf.id_vendedor = auth.current_jwt_user_id()
     AND COALESCE(gf.activo, true)
     AND gf.fecha_eliminacion IS NULL
   ORDER BY gf.orden, gf.fecha_creacion;
$$;


--
