--
-- Name: seller_marcar_geofence_procesado(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_marcar_geofence_procesado(p_id_evidence uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_updated integer;
BEGIN
  UPDATE public.order_geo_evidence
     SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('procesado', true, 'procesado_en', now())
   WHERE id = p_id_evidence;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RETURN jsonb_build_object('error', 'no existe el evento de geofence');
  END IF;
  RETURN jsonb_build_object('id', p_id_evidence, 'procesado', true);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: seller_market_pulse(integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_market_pulse(p_radius_mts integer DEFAULT 1200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog', 'pg_catalog', 'extensions'
    AS $$
DECLARE
  v_caller           uuid;
  v_radius           integer;
  v_lat              double precision;
  v_lon              double precision;
  v_updated_at       timestamptz;
  v_anchor           geography;
  v_nearby_buyers    integer := 0;
  v_active_comps     integer := 0;
  v_avg_rating       numeric(10,2) := 0;
  v_total_resenas    integer := 0;
  v_favoritos_7d     integer := 0;
  v_ordenes_30d      integer := 0;
  v_resenas_30d      integer := 0;
  v_disponible       boolean := false;
  v_confidence       text    := 'baja';
BEGIN
  v_caller := auth.fn_current_user_id();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'JWT requerido' USING ERRCODE = 'P0001';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id=v_caller AND role='seller') THEN
    RAISE EXCEPTION 'Actor no es vendedor' USING ERRCODE = 'P0301';
  END IF;

  v_radius := GREATEST(100, LEAST(COALESCE(p_radius_mts, 1200), 10000));

  SELECT ppv.disponible_ahora INTO v_disponible
  FROM auth.perfiles_publicos_vendedor ppv
  WHERE ppv.id_vendedor = v_caller;

  -- Anchor: ubicación activa más reciente
  SELECT u.latitud, u.longitud, u.fecha_actualizacion,
         COALESCE(u.punto,
           ST_SetSRID(ST_MakePoint(u.longitud, u.latitud), 4326)::geography)
  INTO v_lat, v_lon, v_updated_at, v_anchor
  FROM auth.ubicaciones u
  WHERE u.id_usuario = v_caller AND u.estado = 'activo'
  ORDER BY u.fecha_actualizacion DESC LIMIT 1;

  IF v_anchor IS NULL THEN
    v_confidence := 'sin_ubicacion';
  ELSE
    v_confidence := 'normal';

    -- Compradores cercanos (solo conteo, nunca IDs)
    SELECT COUNT(*)::int INTO v_nearby_buyers
    FROM auth.ubicaciones u
    JOIN auth.users us ON us.id = u.id_usuario
    WHERE us.role = 'buyer'
      AND u.estado = 'activo'
      AND ST_DWithin(
        COALESCE(u.punto, ST_SetSRID(ST_MakePoint(u.longitud, u.latitud), 4326)::geography),
        v_anchor, v_radius
      );

    -- Competidores activos cercanos (solo conteo)
    SELECT COUNT(*)::int INTO v_active_comps
    FROM auth.ubicaciones u
    JOIN auth.users us ON us.id = u.id_usuario
    JOIN auth.perfiles_publicos_vendedor ppv ON ppv.id_vendedor = us.id
    WHERE us.role = 'seller'
      AND us.id <> v_caller
      AND ppv.activo = true
      AND ppv.disponible_ahora = true
      AND u.estado = 'activo'
      AND ST_DWithin(
        COALESCE(u.punto, ST_SetSRID(ST_MakePoint(u.longitud, u.latitud), 4326)::geography),
        v_anchor, v_radius
      );

    IF v_nearby_buyers = 0 AND v_active_comps = 0 THEN
      v_confidence := 'baja';
    END IF;
  END IF;

  -- Reputación observable
  SELECT COALESCE(ROUND(AVG(r.calificacion)::numeric, 2), 0),
         COUNT(*)::int
  INTO v_avg_rating, v_total_resenas
  FROM auth.resenas r
  WHERE r.id_vendedor = v_caller;

  -- Actividad reciente (fuentes confirmadas)
  SELECT COUNT(*)::int INTO v_favoritos_7d
  FROM auth.favoritos f
  JOIN auth.productos p ON p.id = f.id_producto
  WHERE p.id_vendedor = v_caller
    AND f.fecha_creacion >= now() - interval '7 days';

  SELECT COUNT(*)::int INTO v_ordenes_30d
  FROM auth.ordenes o
  WHERE o.id_vendedor = v_caller
    AND o.estado <> 'cancelada'
    AND o.fecha_creacion >= now() - interval '30 days';

  SELECT COUNT(*)::int INTO v_resenas_30d
  FROM auth.resenas r
  WHERE r.id_vendedor = v_caller
    AND r.fecha_creacion >= now() - interval '30 days';

  RETURN jsonb_build_object(
    'disponible_ahora', COALESCE(v_disponible, false),
    'current_spot', CASE
      WHEN v_anchor IS NULL THEN NULL
      ELSE jsonb_build_object('latitud', v_lat, 'longitud', v_lon, 'updated_at', v_updated_at)
    END,
    'market_pulse', jsonb_build_object(
      'nearby_buyers',          v_nearby_buyers,
      'active_competitors',     v_active_comps,
      'potential_reach_radius_km', ROUND((v_radius::numeric / 1000.0), 2),
      'confidence',             v_confidence
    ),
    'reputacion', jsonb_build_object(
      'avg_rating',    v_avg_rating,
      'total_resenas', v_total_resenas
    ),
    'recent_activity', jsonb_build_array(
      jsonb_build_object('event', 'favoritos_7d',  'count', v_favoritos_7d,  'time_window', '7d'),
      jsonb_build_object('event', 'ordenes_30d',   'count', v_ordenes_30d,   'time_window', '30d'),
      jsonb_build_object('event', 'resenas_30d',   'count', v_resenas_30d,   'time_window', '30d')
    )
  );
END;
$$;


--
-- Name: seller_market_pulse_snapshot(uuid, double precision); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_market_pulse_snapshot(p_id_vendedor uuid, p_radius_meters double precision DEFAULT 1200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_caller_id           UUID;
    v_seller_punto        GEOGRAPHY;
    v_is_disponible       BOOLEAN;
    v_spot_label          TEXT;
    v_visibility_radius   DOUBLE PRECISION;
    v_nearby_buyers       BIGINT;
    v_active_competitors  BIGINT;
    v_unique_buyers_30d   BIGINT;
    v_orders_7d           BIGINT;
    v_reputation_score    NUMERIC;
    v_result              JSONB;
BEGIN
    -- Validación de autorización
    v_caller_id := auth.jwt_user_id();  -- PENDIENTE_INTROSPECCION: confirmar función
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'No autenticado' USING ERRCODE = 'PT401';
    END IF;

    -- Solo el propio vendedor o admin/superadmin
    IF v_caller_id <> p_id_vendedor THEN
        IF NOT EXISTS (
            SELECT 1 FROM auth.users u
            WHERE u.id = v_caller_id AND u.role IN ('db_admin','superadmin')
        ) THEN
            RAISE EXCEPTION 'Acceso denegado: solo el propio vendedor puede consultar su pulso'
                USING ERRCODE = 'PT403';
        END IF;
    END IF;

    -- Validar radio (RN-04: máximo 5000 m)
    IF p_radius_meters <= 0 OR p_radius_meters > 5000 THEN
        RAISE EXCEPTION 'Radio debe estar entre 1 y 5000 metros'
            USING ERRCODE = 'P0001';
    END IF;

    -- Obtener ubicación actual del vendedor
    SELECT ub.punto::geography, ppv.is_disponible, ppv.spot_label, ppv.visibility_radius_meters
    INTO v_seller_punto, v_is_disponible, v_spot_label, v_visibility_radius
    FROM auth.ubicaciones ub
    JOIN auth.perfiles_publicos_vendedor ppv ON ppv.id_vendedor = ub.id_usuario
    WHERE ub.id_usuario = p_id_vendedor
    ORDER BY COALESCE(ub.fecha_actualizacion, ub.fecha_creacion) DESC
    LIMIT 1;

    IF v_seller_punto IS NULL THEN
        RAISE EXCEPTION 'No existe ubicación registrada para el vendedor'
            USING ERRCODE = 'P0002';
    END IF;

    -- Compradores activos en radio (usando auth.v_active_market_buyers)
    SELECT COUNT(*)
    INTO v_nearby_buyers
    FROM auth.v_active_market_buyers b
    WHERE ST_DWithin(b.geom::geography, v_seller_punto, p_radius_meters);

    -- Competidores activos en radio (usando auth.v_active_market_sellers)
    SELECT COUNT(*)
    INTO v_active_competitors
    FROM auth.v_active_market_sellers s
    WHERE s.id_vendedor <> p_id_vendedor
      AND ST_DWithin(s.geom::geography, v_seller_punto, p_radius_meters);

    -- Compradores únicos últimos 30 días (RN-07: 40%)
    SELECT COALESCE(COUNT(DISTINCT o.id_comprador), 0)
    INTO v_unique_buyers_30d
    FROM auth.ordenes o
    WHERE o.id_vendedor = p_id_vendedor
      AND o.fecha_creacion >= now() - interval '30 days';

    -- Órdenes últimos 7 días (RN-07: 30%)
    SELECT COALESCE(COUNT(*), 0)
    INTO v_orders_7d
    FROM auth.ordenes o
    WHERE o.id_vendedor = p_id_vendedor
      AND o.fecha_creacion >= now() - interval '7 days';

    -- Score de reputación (RN-07)
    v_reputation_score := ROUND((
        v_unique_buyers_30d * 0.4
      + v_orders_7d         * 0.3
      + GREATEST(v_nearby_buyers - v_active_competitors, 0) * 0.3
    )::numeric, 2);

    -- Construir respuesta
    v_result := jsonb_build_object(
        'id_vendedor',   p_id_vendedor,
        'is_disponible',    COALESCE(v_is_disponible, false),
        'spot_label',       v_spot_label,
        'visibility_radius_meters', COALESCE(v_visibility_radius, p_radius_meters),
        'market_pulse', jsonb_build_object(
            'nearby_buyers',           COALESCE(v_nearby_buyers, 0),
            'active_competitors',      COALESCE(v_active_competitors, 0),
            'potential_reach_radius_km', ROUND((p_radius_meters / 1000.0)::numeric, 2)
        ),
        'recent_activity', COALESCE(
            (
                SELECT jsonb_agg(x ORDER BY x->>'count' DESC)
                FROM (
                    SELECT jsonb_build_object(
                        'event',  hva.evento,
                        'count',  COUNT(*),
                        'window', '1h'
                    ) AS x
                    FROM auth.h_vendedores_audit hva
                    WHERE hva.id_usuario = p_id_vendedor
                      AND hva.fecha_cambio >= now() - interval '1 hour'
                      AND hva.evento IN ('SELLER_STARTED_SELLING','PROFILE_VIEW','PRODUCT_SAVED')
                    GROUP BY hva.evento
                ) sub
            ),
            '[]'::jsonb
        ),
        'reputation', jsonb_build_object(
            'score', COALESCE(v_reputation_score, 0),
            'tier',
                CASE
                    WHEN COALESCE(v_reputation_score, 0) >= 20 THEN 'ALTA'
                    WHEN COALESCE(v_reputation_score, 0) >= 10 THEN 'MEDIA'
                    ELSE 'BASE'
                END,
            'unique_buyers_30d', v_unique_buyers_30d,
            'orders_7d',         v_orders_7d
        ),
        'ts', now()
    );

    RETURN v_result;
END;
$$;


