    AS $$ SELECT NULL::text; $$;


--
-- Name: seller_poner_portada(uuid, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_poner_portada(p_id_producto uuid, p_imagen_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.current_jwt_user_id();
  v_role  text := auth.current_jwt_role();
BEGIN
  IF v_actor IS NULL OR v_role NOT IN ('seller','db_admin') THEN
    RAISE EXCEPTION 'No autenticado como vendedor' USING ERRCODE = 'PT401';
  END IF;

  IF v_role <> 'db_admin' THEN
    IF NOT EXISTS (SELECT 1 FROM auth.productos WHERE id = p_id_producto AND id_vendedor = v_actor) THEN
      RAISE EXCEPTION 'Producto no encontrado o no pertenece al vendedor actual.' USING ERRCODE = 'PT403';
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM auth.galeria_fotos
     WHERE id = p_imagen_id AND id_producto = p_id_producto AND fecha_eliminacion IS NULL
  ) THEN
    RAISE EXCEPTION 'Imagen no encontrada o no pertenece al producto.' USING ERRCODE = 'P0404';
  END IF;

  UPDATE auth.galeria_fotos SET es_portada = false, fecha_modificacion = now()
   WHERE id_producto = p_id_producto;

  UPDATE auth.galeria_fotos SET es_portada = true, fecha_modificacion = now()
   WHERE id = p_imagen_id;
END;
$$;


--
-- Name: seller_promos_vecindad_activas(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_promos_vecindad_activas() RETURNS TABLE(id_zona_promo uuid, nombre text, descuento_pct numeric, inicia_en timestamp with time zone, vence_en timestamp with time zone, canjes_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'ag_catalog'
    AS $$
DECLARE
    v_actor_id uuid := auth.fn_current_user_id();
BEGIN
    RETURN QUERY
    SELECT
        spz.id,
        spz.nombre,
        spz.descuento_pct,
        spz.inicia_en,
        spz.vence_en,
        COUNT(spc.id) AS canjes_count
    FROM auth.seller_promo_zones spz
    LEFT JOIN auth.seller_promo_claims spc
        ON spc.id_zona_promo = spz.id AND spc.claim_estado = 'CANJEADO'
    WHERE spz.id_vendedor = v_actor_id
      AND spz.activo = true
      AND spz.fecha_eliminacion IS NULL
      AND now() BETWEEN spz.inicia_en AND spz.vence_en
    GROUP BY spz.id, spz.nombre, spz.descuento_pct, spz.inicia_en, spz.vence_en
    ORDER BY spz.inicia_en DESC;
END;
$$;


--
-- Name: seller_publicar_borrador(uuid, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_publicar_borrador(p_producto_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE v_actor uuid;
BEGIN
  v_actor := COALESCE(p_user_id, auth.fn_current_user_id());

  UPDATE auth.productos
  SET borrador=false, activo=true, fecha_modificacion=now()
  WHERE id=p_producto_id AND id_vendedor=v_actor AND borrador=true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Borrador no encontrado o no pertenece al vendedor' USING ERRCODE='P0001';
  END IF;

  INSERT INTO auth.h_productos_audit(id_producto,operacion,datos_anteriores,datos_nuevos,modificado_por,motivo)
  VALUES (p_producto_id,'UPDATE',
    jsonb_build_object('borrador',true,'activo',false),
    jsonb_build_object('borrador',false,'activo',true),
    v_actor,'Publicar borrador');

  RETURN jsonb_build_object('producto_id',p_producto_id,'publicado',true,'timestamp',now());
END;
$$;


--
-- Name: seller_publicar_imagen_rapida(uuid, uuid, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_publicar_imagen_rapida(p_id_vendedor uuid, p_product_id uuid, p_image_url text, p_descripcion text DEFAULT NULL::text, p_category_hint text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_caller_id     UUID;
    v_product_owner UUID;
    v_seller_punto  GEOGRAPHY;
    v_orden_max     INT;
    v_new_id        UUID;
BEGIN
    v_caller_id := auth.jwt_user_id();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'No autenticado' USING ERRCODE = 'PT401';
    END IF;

    IF v_caller_id <> p_id_vendedor THEN
        RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = 'PT403';
    END IF;

    -- Validar URL (RN-05)
    IF p_image_url IS NULL OR length(trim(p_image_url)) = 0 THEN
        RAISE EXCEPTION 'La URL de imagen es obligatoria'
            USING ERRCODE = 'P0001';
    END IF;

    IF length(p_image_url) > 2000 THEN
        RAISE EXCEPTION 'URL de imagen excede longitud máxima (2000 chars)'
            USING ERRCODE = 'P0001';
    END IF;

    -- Verificar propiedad del producto (RN-05)
    SELECT p.id_vendedor
    INTO v_product_owner
    FROM auth.productos p
    WHERE p.id = p_product_id
      AND p.activo = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Producto no existe o está inactivo'
            USING ERRCODE = 'P0404';
    END IF;

    IF v_product_owner <> p_id_vendedor THEN
        RAISE EXCEPTION 'El producto no pertenece a este vendedor'
            USING ERRCODE = 'PT403';
    END IF;

    -- Obtener geotag de auth.ubicaciones.punto
    SELECT ub.punto::geography
    INTO v_seller_punto
    FROM auth.ubicaciones ub
    WHERE ub.id_usuario = p_id_vendedor
    ORDER BY COALESCE(ub.fecha_actualizacion, ub.fecha_creacion) DESC
    LIMIT 1;

    -- Calcular orden para nueva imagen
    SELECT COALESCE(MAX(gf.orden), -1) + 1
    INTO v_orden_max
    FROM auth.galeria_fotos gf
    WHERE gf.id_producto = p_product_id
      AND gf.activo = true;

    -- Insertar en auth.galeria_fotos (tabla real, no product_images)
    INSERT INTO auth.galeria_fotos (
        id_producto,
        url,
        descripcion,
        orden,
        activo,
        fecha_creacion,
        fecha_modificacion
    ) VALUES (
        p_product_id,
        p_image_url,
        COALESCE(p_descripcion, p_category_hint),
        v_orden_max,
        true,
        now(),
        now()
    )
    RETURNING id INTO v_new_id;

    -- Auditoría
    INSERT INTO auth.h_vendedores_audit (
        id_usuario, modificado_por, evento, datos_nuevos, fecha_cambio
    ) VALUES (
        p_id_vendedor, v_caller_id, 'PRODUCT_IMAGE_UPLOADED',
        jsonb_build_object(
            'galeria_fotos_id', v_new_id,
            'product_id',       p_product_id,
            'image_url',        p_image_url,
            'category_hint',    p_category_hint,
            'geo_tag',          CASE WHEN v_seller_punto IS NOT NULL
                                     THEN ST_AsGeoJSON(v_seller_punto::geometry)::jsonb
                                     ELSE NULL END,
            'orden',            v_orden_max
        ),
        now()
    );

    RETURN jsonb_build_object(
        'status',      'OK',
        'id',          v_new_id,
        'product_id',  p_product_id,
        'url',         p_image_url,
        'orden',       v_orden_max,
        'geo_tagged',  v_seller_punto IS NOT NULL,
        'ts',          now()
    );
END;
$$;


--
-- Name: seller_recalcular_predicciones(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_recalcular_predicciones(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_res jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'prediction_id', m.prediction_id, 'model_name', m.model_name,
    'prediction_type', m.prediction_type, 'prediction_score', m.prediction_score,
    'confidence', m.confidence, 'fecha_expiracion', m.fecha_expiracion)),
    '[]'::jsonb)
  INTO v_res
  FROM analytics.predicciones_ml m
 WHERE m.fecha_expiracion > now();
  RETURN v_res;
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: seller_refresh_geo_cache(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_refresh_geo_cache(p_id_vendedor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_res jsonb;
BEGIN
  UPDATE seller.dashboard_cache
     SET last_computed = now()
   WHERE id_vendedor = p_id_vendedor;
  SELECT jsonb_build_object(
    'id_vendedor', p_id_vendedor,
    'refrescado', (SELECT COUNT(*) FROM seller.dashboard_cache WHERE id_vendedor = p_id_vendedor),
    'last_computed', (SELECT last_computed FROM seller.dashboard_cache WHERE id_vendedor = p_id_vendedor LIMIT 1)
  ) INTO v_res;
  RETURN v_res;
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: seller_registrar_costo_producto(uuid, numeric, date, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_registrar_costo_producto(p_id_producto uuid, p_costo_unitario numeric, p_vigente_desde date DEFAULT CURRENT_DATE, p_notas text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_vid    uuid := auth.uid();
    v_exists boolean;
BEGIN
    -- Verificar que el producto pertenece al vendedor
    SELECT EXISTS (
        SELECT 1 FROM auth.productos
        WHERE id = p_id_producto AND id_vendedor = v_vid
    ) INTO v_exists;

    IF NOT v_exists THEN
        RAISE EXCEPTION 'Producto no encontrado o no pertenece a este vendedor'
            USING ERRCODE = 'P0049';
    END IF;

    IF p_costo_unitario < 0 THEN
        RAISE EXCEPTION 'El costo unitario no puede ser negativo'
            USING ERRCODE = 'P0050';
    END IF;

    INSERT INTO auth.costos_producto
        (id_producto, id_vendedor, costo_unitario, vigente_desde, notas)
    VALUES (p_id_producto, v_vid, p_costo_unitario, p_vigente_desde, p_notas)
    ON CONFLICT (id_producto, vigente_desde) DO UPDATE
        SET costo_unitario = EXCLUDED.costo_unitario,
            notas          = EXCLUDED.notas;

    RETURN jsonb_build_object(
        'ok',             true,
        'id_producto',    p_id_producto,
        'costo_unitario', p_costo_unitario,
        'vigente_desde',  p_vigente_desde
    );
END;
$$;


--
-- Name: seller_reordenar_imagenes(uuid, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_reordenar_imagenes(p_id_producto uuid, p_ids jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.current_jwt_user_id();
  v_role  text := auth.current_jwt_role();
  v_ids   uuid[];
  v_id    uuid;
  v_pos   integer;
BEGIN
  IF v_actor IS NULL OR v_role NOT IN ('seller','db_admin') THEN
    RAISE EXCEPTION 'No autenticado como vendedor' USING ERRCODE = 'PT401';
  END IF;

  IF v_role <> 'db_admin' THEN
    IF NOT EXISTS (SELECT 1 FROM auth.productos WHERE id = p_id_producto AND id_vendedor = v_actor) THEN
      RAISE EXCEPTION 'Producto no encontrado o no pertenece al vendedor actual.' USING ERRCODE = 'PT403';
    END IF;
  END IF;

  SELECT array_agg(x) INTO v_ids
    FROM (SELECT (jsonb_array_elements_text(p_ids))::uuid AS x) t;

  IF v_ids IS NULL OR array_length(v_ids,1) = 0 THEN
    RAISE EXCEPTION 'La lista de imágenes está vacía.' USING ERRCODE = 'P0001';
  END IF;

  -- Todas las imágenes suministradas deben pertenecer al producto.
  IF EXISTS (
    SELECT 1 FROM auth.galeria_fotos g
     WHERE g.id = ANY(v_ids)
       AND (g.id_producto IS DISTINCT FROM p_id_producto)
  ) THEN
    RAISE EXCEPTION 'Una o más imágenes no pertenecen al producto indicado.' USING ERRCODE = 'P0404';
  END IF;

  v_pos := 0;
  FOREACH v_id IN ARRAY v_ids LOOP
    UPDATE auth.galeria_fotos
       SET orden = v_pos, fecha_modificacion = now()
     WHERE id = v_id AND id_producto = p_id_producto;
    v_pos := v_pos + 1;
  END LOOP;
END;
$$;


--
-- Name: seller_request_account_deletion(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_request_account_deletion(p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE v_actor uuid := auth.fn_current_user_id();
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Autenticación requerida'; END IF;
  IF (SELECT legal_hold FROM auth.users WHERE id=v_actor) THEN
    RETURN jsonb_build_object('blocked',true,'reason','legal_hold_active');
  END IF;
  INSERT INTO auth.user_purge_queue(
    target_user_id,target_role,target_effective_tier,strategy,estado,eligible_at,requested_by)
  SELECT id,role,auth.resolve_effective_tier(id,now()),'seller_request','pending',
    now()+interval '30 days',v_actor
  FROM auth.users WHERE id=v_actor
  ON CONFLICT (target_user_id,estado) DO NOTHING;
  RETURN jsonb_build_object('queued',true,'review_in_days',30);
END;
$$;


--
-- Name: seller_responder_resena(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_responder_resena(p_resena_id uuid, p_respuesta text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor    uuid;
    v_vendedor uuid;
    v_es_edicion boolean;
BEGIN
    v_actor := auth.fn_current_user_id();

    -- Validar feature flag Silver+
    IF NOT auth.fn_get_feature_flag(v_actor, 'respuesta_resenas') THEN
        RAISE EXCEPTION 'Tu plan no incluye respuesta a reseñas (Silver+)'
            USING ERRCODE = 'P0003';
    END IF;

    -- Validar propiedad
    SELECT id_vendedor INTO v_vendedor
    FROM auth.resenas WHERE id = p_resena_id AND moderada = false;

    IF v_vendedor IS NULL THEN
        RAISE EXCEPTION 'Reseña no encontrada' USING ERRCODE = 'P0054';
    END IF;
    IF v_vendedor <> v_actor THEN
        RAISE EXCEPTION 'Solo puedes responder reseñas de tu tienda' USING ERRCODE = '42501';
    END IF;

    -- Validar longitud
    IF char_length(trim(COALESCE(p_respuesta, ''))) > 1000 THEN
        RAISE EXCEPTION 'Respuesta demasiado larga (máx 1000 caracteres)' USING ERRCODE = '22001';
    END IF;

    -- Detectar si es primera respuesta o edición
    v_es_edicion := EXISTS (
        SELECT 1 FROM auth.resenas
        WHERE id = p_resena_id AND respuesta_publica IS NOT NULL
    );

    UPDATE auth.resenas SET
        respuesta_publica       = trim(p_respuesta),
        respuesta_fecha         = CASE WHEN NOT v_es_edicion THEN now() ELSE respuesta_fecha END,
        respuesta_modificada_at = CASE WHEN v_es_edicion THEN now() ELSE NULL END,
        fecha_modificacion      = now()
    WHERE id = p_resena_id;

    -- Auditoría en h_vendedores_audit (operacion=UPDATE)
    INSERT INTO auth.h_vendedores_audit
        (id_usuario, operacion, datos_anteriores, datos_nuevos, motivo)
    VALUES (
        v_actor, 'UPDATE',
        jsonb_build_object('resena_id', p_resena_id, 'accion', 'sin_respuesta'),
        jsonb_build_object('resena_id', p_resena_id, 'accion',
            CASE WHEN v_es_edicion THEN 'edicion_respuesta' ELSE 'primera_respuesta' END),
        'Vendedor respondió reseña'
    );

    RETURN jsonb_build_object(
        'ok',          true,
        'resena_id',   p_resena_id,
        'es_edicion',  v_es_edicion
    );
END;
$$;


--
-- Name: seller_restore_product(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_restore_product(p_producto_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
declare v_actor_id uuid;
 v_before jsonb;
 v_after jsonb;
 v_limits record;
 v_geo_exists boolean;

begin
  v_actor_id := auth.fn_current_user_id();

  if auth.fn_current_user_role() <> 'seller' then raise exception 'seller_role_required';
 end if;

  if p_reason is null or btrim(p_reason) = '' then raise exception 'reason_required';
 end if;

  perform auth.fn_assert_seller_operable(v_actor_id);


  select to_jsonb(p) into v_before from auth.productos p
  where p.id = p_producto_id and p.id_vendedor = v_actor_id for update;

  if v_before is null then raise exception 'producto_not_found_for_seller';
 end if;

  if (v_before ->> 'deleted_at') is null then
    return jsonb_build_object('producto_id', p_producto_id, 'restored', true, 'status', 'noop');

  end if;


  select * into v_limits from auth.fn_get_publication_limits(v_actor_id) limit 1;

  if auth.fn_count_active_products(v_actor_id, p_producto_id) >= v_limits.max_productos_activos then
    raise exception 'max_productos_activos_excedido';

  end if;

  select exists (select 1 from auth.productos_geo pg where pg.id_producto = p_producto_id) into v_geo_exists;

  if not v_geo_exists then raise exception 'ubicacion_operativa_requerida_para_restaurar';
 end if;


  update auth.productos
  set activo=true, fecha_eliminacion=null, deleted_by=null, delete_reason=null
  where id = p_producto_id and id_vendedor = v_actor_id;


  select to_jsonb(p) into v_after from auth.productos p where p.id = p_producto_id;

  perform auth.fn_write_publicacion_audit(p_producto_id, 'RESTORE_PRODUCT', p_reason, v_before, v_after);

  return jsonb_build_object('producto_id', p_producto_id, 'restored', true, 'data', v_after);

end;
 $$;


--
-- Name: seller_send_push_clientes_frecuentes(text, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_send_push_clientes_frecuentes(p_tipo text DEFAULT 'frecuente'::text, p_titulo text DEFAULT ''::text, p_cuerpo text DEFAULT ''::text, p_segmento text DEFAULT 'champion'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor   uuid;
    v_count   integer := 0;
    v_mail_c  integer := 0;
    v_rc      integer;
    v_comp    record;
    v_max_snap date;
BEGIN
    v_actor := auth.fn_current_user_id();

    -- RN-015: Feature flag push_clientes (Gold)
    IF NOT auth.fn_get_feature_flag(v_actor, 'push_clientes') THEN
        RAISE EXCEPTION 'feature_not_available_for_plan' USING ERRCODE = '42501';
    END IF;

    -- RN-016: Validaciones de entrada
    IF p_tipo NOT IN ('frecuente','churn_prevention','reactivacion','promo_exclusiva','comunidad') THEN
        RAISE EXCEPTION 'tipo_invalido' USING ERRCODE = '22023';
    END IF;
    IF p_segmento NOT IN ('champion','loyal','at_risk','hibernating','new','lost') THEN
        RAISE EXCEPTION 'segmento_invalido' USING ERRCODE = '22023';
    END IF;
    IF char_length(trim(p_titulo)) = 0 OR char_length(trim(p_cuerpo)) = 0 THEN
        RAISE EXCEPTION 'titulo_cuerpo_requeridos' USING ERRCODE = '22023';
    END IF;

    -- Obtener snapshot más reciente
    SELECT MAX(snapshot_date) INTO v_max_snap
    FROM auth.rfm_snapshots WHERE id_vendedor = v_actor;

    -- FA-6: Segmento sin compradores activos
    IF v_max_snap IS NULL THEN
        RETURN jsonb_build_object(
            'encolados', 0,
            'segmento',  p_segmento,
            'motivo',    'sin_snapshot_rfm'
        );
    END IF;

    -- RN-017: Máximo 200 notificaciones por campaña
    FOR v_comp IN
        SELECT DISTINCT rs.id_comprador
        FROM auth.rfm_snapshots rs
        JOIN auth.users u ON u.id = rs.id_comprador
        WHERE rs.id_vendedor = v_actor
          AND rs.segmento = p_segmento
          AND rs.snapshot_date = v_max_snap
          AND u.activo IS NOT FALSE
          AND u.fecha_eliminacion IS NULL
        ORDER BY rs.id_comprador
        LIMIT 200
    LOOP
        -- Encolar push (daemon Python local lee esta tabla)
        INSERT INTO auth.push_notification_queue (
            id_vendedor, id_comprador, tipo, titulo, cuerpo
        ) VALUES (
            v_actor, v_comp.id_comprador, p_tipo, p_titulo, p_cuerpo
        );
        v_count := v_count + 1;

        -- Encolar mail como respaldo
        INSERT INTO auth.mail_queue (id_usuario, recipient, subject, body)
        SELECT
            v_comp.id_comprador,
            u.email,
            p_titulo,
            p_cuerpo
        FROM auth.users u
        WHERE u.id = v_comp.id_comprador
          AND u.activo IS NOT FALSE
          AND u.fecha_eliminacion IS NULL;
        GET DIAGNOSTICS v_rc = ROW_COUNT;
        v_mail_c := v_mail_c + v_rc;
    END LOOP;

    -- Auditoría
    INSERT INTO auth.h_vendedores_audit (
        id_usuario, operacion, datos_nuevos, motivo
    ) VALUES (
        v_actor, 'UPDATE',
        jsonb_build_object(
            'push_encolados', v_count,
            'mail_encolados', v_mail_c,
            'tipo',           p_tipo,
            'segmento',       p_segmento
        ),
        'Push a segmento ' || p_segmento || ' tipo ' || p_tipo
    );

    RETURN jsonb_build_object(
        'encolados',      v_count,
        'mail_encolados', v_mail_c,
        'segmento',       p_segmento,
        'tipo',           p_tipo
    );
END;
$$;


--
-- Name: seller_set_availability(boolean, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_set_availability(p_disponible boolean, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'ag_catalog'
    AS $$
DECLARE
  v_caller        uuid;
  v_perfil_activo boolean;
  v_tiene_spot    boolean;
  v_before        jsonb;
  v_after         jsonb;
BEGIN
  v_caller := auth.fn_current_user_id();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'JWT requerido' USING ERRCODE = 'P0001';
  END IF;

  -- Verificar rol seller
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = v_caller AND role = 'seller') THEN
    RAISE EXCEPTION 'Usuario no es vendedor' USING ERRCODE = 'P0301';
  END IF;

  -- Verificar perfil activo (no suspendido)
  SELECT activo INTO v_perfil_activo
  FROM auth.perfiles_publicos_vendedor
  WHERE id_vendedor = v_caller;

  IF v_perfil_activo IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'Perfil público no activo o inexistente' USING ERRCODE = 'P0303';
  END IF;

  -- Para activar: exigir check-in previo
  IF p_disponible THEN
    SELECT EXISTS (
      SELECT 1 FROM auth.ubicaciones
      WHERE id_usuario = v_caller AND estado = 'activo'
    ) INTO v_tiene_spot;

    IF v_tiene_spot IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'Sin ubicación operativa activa: check-in requerido' USING ERRCODE = 'P0300';
    END IF;
  END IF;

  -- Snapshot antes
  SELECT to_jsonb(ppv.*) INTO v_before
  FROM auth.perfiles_publicos_vendedor ppv
  WHERE ppv.id_vendedor = v_caller;

  UPDATE auth.perfiles_publicos_vendedor
  SET disponible_ahora  = p_disponible,
      disponible_desde  = CASE WHEN p_disponible     THEN now() ELSE disponible_desde END,
      disponible_hasta  = CASE WHEN NOT p_disponible THEN now() ELSE NULL              END,
      fecha_modificacion = now()
  WHERE id_vendedor = v_caller;

  -- Snapshot después
  SELECT to_jsonb(ppv.*) INTO v_after
  FROM auth.perfiles_publicos_vendedor ppv
  WHERE ppv.id_vendedor = v_caller;

  -- Auditoría
  INSERT INTO auth.h_vendedores_audit (
    id_usuario, operacion, datos_anteriores, datos_nuevos, modificado_por, motivo
  ) VALUES (
    v_caller,
    'UPDATE',
    v_before,
    v_after,
    v_caller,
    COALESCE(p_motivo, 'seller_set_availability')
  );

  RETURN jsonb_build_object(
    'disponible_ahora', p_disponible,
    'changed_at',       now()
  );
END;
$$;


--
-- Name: seller_set_metricas_visibles(jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_set_metricas_visibles(p_metricas_visibles jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
BEGIN
  v_actor := auth.current_jwt_user_id();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'actor_no_autenticado'; END IF;

  IF jsonb_typeof(p_metricas_visibles) <> 'object' THEN
    RAISE EXCEPTION 'metricas_visibles_debe_ser_objeto_json';
  END IF;

  UPDATE auth.perfiles_publicos_vendedor
     SET metricas_visibles = p_metricas_visibles,
         fecha_modificacion = now()
   WHERE id_vendedor = v_actor;

  RETURN jsonb_build_object('ok', true, 'metricas_visibles', p_metricas_visibles);
END;
$$;


--
-- Name: seller_set_principal_ubicacion(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_set_principal_ubicacion(p_ubicacion_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_user_id uuid := (nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM auth.ubicaciones
    WHERE id = p_ubicacion_id AND id_usuario = v_user_id
      AND estado = 'activo' AND fecha_eliminacion IS NULL
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ubicacion_no_encontrada_inactiva_o_sin_permiso');
  END IF;

  -- Desmarcar todas (trigger también lo hace, doble garantía)
  UPDATE auth.ubicaciones SET es_principal = false
  WHERE id_usuario = v_user_id AND fecha_eliminacion IS NULL;

  UPDATE auth.ubicaciones
  SET es_principal = true, fecha_actualizacion = now()
  WHERE id = p_ubicacion_id;

  INSERT INTO auth.h_vendedores_audit (id_usuario, operacion, datos_nuevos, modificado_por, motivo)
  VALUES (v_user_id, 'UPDATE',
    jsonb_build_object('ubicacion_id', p_ubicacion_id, 'es_principal', true),
    v_user_id, 'seller_set_principal_ubicacion');

  RETURN jsonb_build_object('ok', true, 'principal_id', p_ubicacion_id);
END;
$$;


--
-- Name: seller_set_product_active(uuid, boolean, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_set_product_active(p_producto_id uuid, p_activo boolean, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
declare v_actor_id uuid;
 v_before jsonb;
 v_after jsonb;
 v_limits record;
 v_geo_exists boolean;

begin
  v_actor_id := auth.fn_current_user_id();

  if auth.fn_current_user_role() <> 'seller' then raise exception 'seller_role_required';
 end if;

  perform auth.fn_assert_seller_operable(v_actor_id);


  select to_jsonb(p) into v_before from auth.productos p
  where p.id = p_producto_id and p.id_vendedor = v_actor_id for update;

  if v_before is null then raise exception 'producto_not_found_for_seller';
 end if;

  if (v_before ->> 'deleted_at') is not null then raise exception 'producto_soft_deleted_use_restore';
 end if;


  if p_activo = true then
    select * into v_limits from auth.fn_get_publication_limits(v_actor_id) limit 1;

    if auth.fn_count_active_products(v_actor_id, p_producto_id) >= v_limits.max_productos_activos then
      raise exception 'max_productos_activos_excedido';

    end if;

    select exists (select 1 from auth.productos_geo pg where pg.id_producto = p_producto_id)
    into v_geo_exists;

    if not v_geo_exists then raise exception 'ubicacion_operativa_requerida_para_activar';
 end if;

  end if;


  update auth.productos set activo = p_activo where id = p_producto_id and id_vendedor = v_actor_id;

  select to_jsonb(p) into v_after from auth.productos p where p.id = p_producto_id;


  perform auth.fn_write_publicacion_audit(
    p_producto_id,
    case when p_activo then 'ACTIVATE_PRODUCT' else 'DEACTIVATE_PRODUCT' end,
    p_reason, v_before, v_after
  );

  return jsonb_build_object('producto_id', p_producto_id, 'activo', p_activo, 'data', v_after);

end;
 $$;


--
-- Name: seller_set_profile_active(boolean, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_set_profile_active(p_activo boolean, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'ag_catalog'
    AS $$
DECLARE
  v_caller uuid;
  v_before jsonb;
  v_after  jsonb;
BEGIN
  v_caller := auth.fn_current_user_id();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'JWT requerido' USING ERRCODE = 'P0001';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id=v_caller AND role='seller') THEN
    RAISE EXCEPTION 'Actor no es vendedor' USING ERRCODE = 'P0301';
  END IF;

  SELECT to_jsonb(ppv.*) INTO v_before
  FROM auth.perfiles_publicos_vendedor ppv
  WHERE ppv.id_vendedor = v_caller;

  IF v_before IS NULL THEN
    RAISE EXCEPTION 'Perfil público inexistente' USING ERRCODE = 'P0600';
  END IF;

  UPDATE auth.perfiles_publicos_vendedor
  SET activo           = p_activo,
      -- Si se desactiva: forzar disponible_ahora=false. Si reactiva: NO cambiar disponible.
      disponible_ahora  = CASE WHEN p_activo THEN disponible_ahora ELSE false END,
      disponible_hasta  = CASE WHEN NOT p_activo THEN now() ELSE disponible_hasta END,
      fecha_modificacion = now()
  WHERE id_vendedor = v_caller;

  SELECT to_jsonb(ppv.*) INTO v_after
  FROM auth.perfiles_publicos_vendedor ppv
  WHERE ppv.id_vendedor = v_caller;

  INSERT INTO auth.h_vendedores_audit (
    id_usuario, operacion, datos_anteriores, datos_nuevos, modificado_por, motivo
  ) VALUES (
    v_caller,
    CASE WHEN p_activo THEN 'REACTIVATE' ELSE 'SUSPEND' END,
    v_before, v_after, v_caller,
    COALESCE(p_motivo, 'seller_set_profile_active')
  );

  -- Revocación condicional de sesiones (solo si tabla enforcement real)
  IF NOT p_activo THEN
    BEGIN
      UPDATE auth.sesiones_tokens
      SET revocado = true
      WHERE id_usuario = v_caller AND revocado = false;
    EXCEPTION WHEN undefined_table THEN
      -- sesiones_tokens no existe en este entorno: silencioso
      NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'perfil_activo',   p_activo,
    'disponible_ahora', CASE WHEN p_activo THEN (v_after->'disponible_ahora')::boolean ELSE false END,
    'changed_at',      now()
  );
END;
$$;


--
-- Name: seller_set_zona_cobertura(uuid, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_set_zona_cobertura(p_ubicacion_id uuid, p_geojson jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_user_id uuid := (nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid;
  v_limits  jsonb;
  v_geom    geometry(Polygon,4326);
BEGIN
  -- Verificar plan Silver+
  v_limits := auth.fn_get_location_limits(v_user_id);
  IF NOT (v_limits->>'zona_cobertura_custom')::boolean THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'feature_requiere_plan_silver_o_superior'
    );
  END IF;

  -- Verificar propiedad de la ubicación
  IF NOT EXISTS (
    SELECT 1 FROM auth.ubicaciones
    WHERE id = p_ubicacion_id AND id_usuario = v_user_id AND fecha_eliminacion IS NULL
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ubicacion_no_encontrada_o_sin_permiso');
  END IF;

  -- Parsear GeoJSON → geometry
  BEGIN
    v_geom := ST_GeomFromGeoJSON(p_geojson::text);
    IF ST_GeometryType(v_geom) NOT IN ('ST_Polygon','ST_MultiPolygon') THEN
      RETURN jsonb_build_object('ok', false, 'error', 'geojson_debe_ser_polygon');
    END IF;
    -- Forzar SRID 4326
    v_geom := ST_SetSRID(v_geom, 4326);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', 'geojson_invalido', 'detalle', SQLERRM);
  END;

  -- Validar área máxima: máx 500 km²
  IF ST_Area(v_geom::geography) / 1e6 > 500 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'zona_excede_area_maxima_500km2',
      'area_km2', ROUND((ST_Area(v_geom::geography) / 1e6)::numeric, 2)
    );
  END IF;

  UPDATE auth.ubicaciones
  SET zona_cobertura = v_geom, fecha_actualizacion = now()
  WHERE id = p_ubicacion_id;

  INSERT INTO auth.h_vendedores_audit (id_usuario, operacion, datos_nuevos, modificado_por, motivo)
  VALUES (v_user_id, 'UPDATE',
    jsonb_build_object(
      'ubicacion_id', p_ubicacion_id,
      'zona_cobertura_area_km2', ROUND((ST_Area(v_geom::geography) / 1e6)::numeric, 2)
    ),
    v_user_id, 'seller_set_zona_cobertura');

  RETURN jsonb_build_object(
    'ok', true,
    'area_km2', ROUND((ST_Area(v_geom::geography) / 1e6)::numeric, 2)
  );
END;
$$;


--
-- Name: seller_soft_delete_product(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_soft_delete_product(p_producto_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
declare v_actor_id uuid;
 v_before jsonb;
 v_after jsonb;

begin
  v_actor_id := auth.fn_current_user_id();

  if auth.fn_current_user_role() <> 'seller' then raise exception 'seller_role_required';
 end if;

  if p_reason is null or btrim(p_reason) = '' then raise exception 'reason_required';
 end if;


  select to_jsonb(p) into v_before from auth.productos p
  where p.id = p_producto_id and p.id_vendedor = v_actor_id for update;

  if v_before is null then raise exception 'producto_not_found_for_seller';
 end if;

  if (v_before ->> 'deleted_at') is not null then
    return jsonb_build_object('producto_id', p_producto_id, 'deleted', true, 'status', 'noop');

  end if;


  update auth.productos
  set activo=false, fecha_eliminacion=now(), deleted_by=v_actor_id, delete_reason=p_reason
  where id = p_producto_id and id_vendedor = v_actor_id;


  select to_jsonb(p) into v_after from auth.productos p where p.id = p_producto_id;

  perform auth.fn_write_publicacion_audit(p_producto_id, 'SOFT_DELETE_PRODUCT', p_reason, v_before, v_after);

  return jsonb_build_object('producto_id', p_producto_id, 'deleted', true, 'data', v_after);

end;
 $$;


--
-- Name: seller_solicitar_apelacion(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_solicitar_apelacion(p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid;
    v_memb_id uuid;
BEGIN
    v_actor := auth.fn_current_user_id();

    SELECT id INTO v_memb_id
    FROM auth.membresias_vendedor
    WHERE id_vendedor = v_actor AND estado = 'suspendida' AND fecha_eliminacion IS NULL
    LIMIT 1;

    IF v_memb_id IS NULL THEN
        RAISE EXCEPTION 'sin_suspension_activa: solo puedes apelar una suspensión activa'
        USING ERRCODE = 'P0001';
    END IF;

    -- Registrar apelación en historial
    INSERT INTO auth.membresias_historial
        (id_vendedor, membresia_id, evento, motivo, metadata)
    VALUES (
        v_actor, v_memb_id, 'reactivacion',
        'Apelación pendiente: ' || p_motivo,
        jsonb_build_object('tipo', 'apelacion', 'estado', 'pendiente_revision')
    );

    -- Insertar en mail_queue para notificación admin
    INSERT INTO auth.mail_queue (id_vendedor, tipo, payload)
    VALUES (
        v_actor,
        'apelacion_suspension',
        jsonb_build_object(
            'id_vendedor', v_actor,
            'membresia_id', v_memb_id,
            'motivo', p_motivo
        )
    )
    ON CONFLICT DO NOTHING;

    RETURN jsonb_build_object(
        'apelacion_registrada', true,
        'estado',               'pendiente_revision_admin'
    );
END;
$$;


--
-- Name: seller_solicitar_export_historial(date, date, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_solicitar_export_historial(p_desde date, p_hasta date, p_agrupacion text DEFAULT 'dia'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_vid    uuid := auth.uid();
    v_exp_id uuid;
BEGIN
    IF NOT auth.fn_get_feature_flag(v_vid, 'exportar_historial') THEN
        RAISE EXCEPTION 'Exportación de historial requiere plan Gold o superior'
            USING ERRCODE = 'P0042';
    END IF;

    IF (p_hasta - p_desde) > 366 THEN
        RAISE EXCEPTION 'Rango máximo de exportación: 366 días'
            USING ERRCODE = 'P0043';
    END IF;

    IF p_agrupacion NOT IN ('dia','semana','mes','anio') THEN
        RAISE EXCEPTION 'Agrupación inválida. Use: dia, semana, mes, anio'
            USING ERRCODE = 'P0041';
    END IF;

    -- Anti-spam: una exportación activa a la vez
    IF EXISTS (
        SELECT 1 FROM auth.exportaciones_historial
        WHERE id_vendedor = v_vid
          AND estado IN ('pendiente','procesando')
          AND solicitado_at > now() - interval '10 minutes'
    ) THEN
        RAISE EXCEPTION 'Ya tienes una exportación en proceso. Espera unos minutos.'
            USING ERRCODE = 'P0044';
    END IF;

    INSERT INTO auth.exportaciones_historial
        (id_vendedor, desde, hasta, agrupacion, estado)
    VALUES (v_vid, p_desde, p_hasta, p_agrupacion, 'pendiente')
    RETURNING id INTO v_exp_id;

    -- Notificar al servicio local de exportación
    PERFORM pg_notify(
        'exportacion_kambalache',
        json_build_object('exportacion_id', v_exp_id, 'id_vendedor', v_vid)::text
    );

    RETURN jsonb_build_object(
        'ok',             true,
        'exportacion_id', v_exp_id,
        'estado',         'pendiente',
        'expira_horas',   48,
        'nota',           'El archivo CSV se generará localmente. Revisa el estado con seller_get_export_estado()'
    );
END;
$$;


--
-- Name: seller_solicitar_fp_growth(numeric, numeric); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_solicitar_fp_growth(p_min_soporte numeric DEFAULT 0.02, p_min_confianza numeric DEFAULT 0.3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor uuid;
    v_job_id bigint;
    v_plan_cod text;
BEGIN
    v_actor := auth.fn_current_user_id();

    SELECT pm.codigo INTO v_plan_cod
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.id_vendedor = v_actor AND mv.estado IN ('activo','grace_period')
    LIMIT 1;

    IF coalesce(v_plan_cod,'bronze') NOT IN ('silver','gold') THEN
        RAISE EXCEPTION 'FP-Growth avanzado requiere plan Silver o Gold' USING ERRCODE = '42501';
    END IF;

    -- Solo 1 job activo por vendedor
    IF EXISTS (
        SELECT 1 FROM auth.basket_daemon_queue
        WHERE id_vendedor = v_actor AND estado IN ('pendiente','procesando')
    ) THEN
        RAISE EXCEPTION 'Ya existe un análisis FP-Growth en proceso para este vendedor' USING ERRCODE = 'P0003';
    END IF;

    INSERT INTO auth.basket_daemon_queue (id_vendedor, min_soporte, min_confianza)
    VALUES (v_actor, p_min_soporte, p_min_confianza)
    RETURNING id INTO v_job_id;

    RETURN jsonb_build_object(
        'job_id', v_job_id,
        'status', 'pendiente',
        'mensaje', 'Análisis FP-Growth encolado. El daemon kambalache-basket.service lo procesará en breve.'
    );
END;
$$;


--
-- Name: seller_subir_imagen(uuid, bytea, text, text, text, boolean); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_subir_imagen(p_id_producto uuid, p_data bytea, p_mime text, p_nombre_archivo text, p_descripcion text DEFAULT NULL::text, p_es_portada boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor   uuid := auth.current_jwt_user_id();
  v_role    text := auth.current_jwt_role();
  v_mime    text;
  v_orden   integer;
  v_count   integer;
  v_nuevo   uuid;
BEGIN
  IF v_actor IS NULL OR v_role NOT IN ('seller','db_admin') THEN
    RAISE EXCEPTION 'No autenticado como vendedor' USING ERRCODE = 'PT401';
  END IF;

  v_mime := lower(btrim(coalesce(p_mime, '')));
  IF v_mime NOT IN ('image/jpeg','image/png','image/webp','image/heic','image/heif','image/gif') THEN
    RAISE EXCEPTION 'Tipo de archivo no permitido: "%". Sólo se admiten imágenes JPEG, PNG, WebP, HEIC, HEIF y GIF.', v_mime
      USING ERRCODE = 'P0001';
  END IF;

  IF p_data IS NULL OR octet_length(p_data) = 0 THEN
    RAISE EXCEPTION 'El contenido de la imagen está vacío.' USING ERRCODE = 'P0001';
  END IF;

  IF v_role <> 'db_admin' THEN
    IF NOT EXISTS (SELECT 1 FROM auth.productos WHERE id = p_id_producto AND id_vendedor = v_actor) THEN
      RAISE EXCEPTION 'Producto no encontrado o no pertenece al vendedor actual (%s).', p_id_producto USING ERRCODE = 'PT403';
    END IF;
  END IF;

  SELECT count(*) INTO v_count
    FROM auth.galeria_fotos
   WHERE id_producto = p_id_producto
     AND fecha_eliminacion IS NULL
     AND coalesce(activo, true);
  IF v_count >= 10 THEN
    RAISE EXCEPTION 'Límite alcanzado: el producto ya tiene 10 imágenes activas.' USING ERRCODE = 'P0001';
  END IF;

  SELECT coalesce(max(orden), -1) + 1 INTO v_orden
    FROM auth.galeria_fotos
   WHERE id_producto = p_id_producto AND fecha_eliminacion IS NULL;

  INSERT INTO auth.galeria_fotos (
    id_vendedor, id_producto, mime_type, tamano_bytes, orden, es_portada,
    descripcion, activo, data_bytea, storage_path, metadata, fecha_creacion
  ) VALUES (
    v_actor, p_id_producto, v_mime, octet_length(p_data), v_orden, coalesce(p_es_portada, false),
    nullif(btrim(coalesce(p_descripcion,'')), ''), true, p_data, 'data_bytea',
    jsonb_build_object(
      'nombre_archivo', coalesce(p_nombre_archivo, ''),
      'almacenamiento', 'inline_bytea',
      'fuente', 'seller_subir_imagen'
    ), now()
  ) RETURNING id INTO v_nuevo;

  IF coalesce(p_es_portada, false) THEN
    UPDATE auth.galeria_fotos SET es_portada = false
     WHERE id_producto = p_id_producto AND id <> v_nuevo;
  END IF;

  RETURN v_nuevo;
END;
$$;


--
-- Name: seller_transferir_puntos(uuid, numeric, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_transferir_puntos(p_receptor_id uuid, p_monto numeric, p_nota text DEFAULT NULL::text, p_ref_operacion text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_actor_id        uuid;
    v_billetera       record;
    v_receptor        record;
    v_limites         jsonb;
    v_max_diario      numeric;
    v_transferido_hoy numeric;
    v_comision        numeric;
    v_monto_neto      numeric;
    v_plataforma_id   uuid;
    v_transferencia_id uuid;
    v_ref             text;
BEGIN
    v_actor_id := auth.fn_current_user_id();
    v_ref      := COALESCE(p_ref_operacion, public.gen_random_uuid()::text);

    -- Idempotencia 60s
    IF EXISTS (
        SELECT 1 FROM auth.transferencias_puntos
        WHERE referencia_operacion = v_ref
          AND id_usuario_origen = v_actor_id
          AND fecha_creacion > now() - INTERVAL '60 seconds'
    ) THEN
        RETURN jsonb_build_object('idempotente', true, 'referencia', v_ref);
    END IF;

    IF p_monto < 10 THEN
        RETURN jsonb_build_object('error', 'monto_minimo_10', 'codigo', 'WALLET_041');
    END IF;

    -- Validar receptor
    SELECT id, activo, fecha_eliminacion, role INTO v_receptor
    FROM auth.users WHERE id = p_receptor_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'receptor_no_encontrado', 'codigo', 'WALLET_020');
    END IF;
    IF v_receptor.fecha_eliminacion IS NOT NULL THEN
        RETURN jsonb_build_object('error', 'receptor_eliminado', 'codigo', 'WALLET_021');
    END IF;
    IF COALESCE(v_receptor.activo, true) = false THEN
        RETURN jsonb_build_object('error', 'receptor_inactivo', 'codigo', 'WALLET_022');
    END IF;
    IF v_receptor.role NOT IN ('buyer', 'seller') THEN
        RETURN jsonb_build_object('error', 'receptor_invalido', 'codigo', 'WALLET_023');
    END IF;

    -- Verificar límite diario por plan
    v_limites    := auth.fn_get_wallet_limits(v_actor_id);
    v_max_diario := (v_limites ->> 'max_transferencia_diaria')::numeric;

    SELECT COALESCE(SUM(monto_bruto), 0) INTO v_transferido_hoy
    FROM auth.transferencias_puntos
    WHERE id_usuario_origen = v_actor_id
      AND fecha_creacion >= date_trunc('day', now())
      AND estado = 'completada';

    IF v_transferido_hoy + p_monto > v_max_diario THEN
        RETURN jsonb_build_object(
            'error',           'limite_diario_excedido', 'codigo', 'WALLET_040',
            'transferido_hoy', v_transferido_hoy,
            'limite_diario',   v_max_diario,
            'disponible_hoy',  GREATEST(0, v_max_diario - v_transferido_hoy)
        );
    END IF;

    -- Comisión 2%
    v_comision   := ROUND(p_monto * 0.02, 2);
    v_monto_neto := p_monto - v_comision;

    -- Lock origen
    SELECT * INTO v_billetera FROM auth.billetera
    WHERE id_usuario = v_actor_id FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'billetera_no_encontrada', 'codigo', 'WALLET_001');
    END IF;
    IF NOT v_billetera.activo THEN
        RETURN jsonb_build_object('error', 'billetera_suspendida', 'codigo', 'WALLET_003');
    END IF;
    IF v_billetera.saldo < p_monto THEN
        RETURN jsonb_build_object(
            'error',        'saldo_insuficiente', 'codigo', 'WALLET_002',
            'saldo_actual', v_billetera.saldo, 'requerido', p_monto
        );
    END IF;

    -- Débito origen
    UPDATE auth.billetera
    SET saldo = saldo - p_monto, fecha_modificacion = now()
    WHERE id_usuario = v_actor_id;

    -- Crédito receptor (con lock)
    PERFORM saldo FROM auth.billetera WHERE id_usuario = p_receptor_id FOR UPDATE;
    UPDATE auth.billetera
    SET saldo = saldo + v_monto_neto, fecha_modificacion = now()
    WHERE id_usuario = p_receptor_id;

    -- Crédito comisión → platform user
    SELECT id INTO v_plataforma_id FROM auth.users WHERE role = 'platform' LIMIT 1;
    IF v_plataforma_id IS NOT NULL AND v_comision > 0 THEN
        PERFORM saldo FROM auth.billetera WHERE id_usuario = v_plataforma_id FOR UPDATE;
        UPDATE auth.billetera
        SET saldo = saldo + v_comision, fecha_modificacion = now()
        WHERE id_usuario = v_plataforma_id;
    END IF;

    -- Log transferencia
    INSERT INTO auth.transferencias_puntos (
        id_usuario_origen, id_usuario_receptor, monto_bruto, comision_puntos, monto_neto,
        nota, estado, referencia_operacion, detalle
    ) VALUES (
        v_actor_id, p_receptor_id, p_monto, v_comision, v_monto_neto,
        p_nota, 'completada', v_ref,
        jsonb_build_object('tasa_comision', 0.02, 'platform_user_id', v_plataforma_id)
    ) RETURNING id INTO v_transferencia_id;

    -- Movimientos en ambas billeteras
    INSERT INTO auth.movimientos_puntos (
        id_usuario, tipo_movimiento, monto, saldo_anterior, saldo_posterior,
        referencia, detalle
    ) VALUES
        (v_actor_id, 'transferencia_enviada', -p_monto,
         v_billetera.saldo, v_billetera.saldo - p_monto,
         v_transferencia_id::text,
         jsonb_build_object('receptor_id', p_receptor_id, 'comision', v_comision)),
        (p_receptor_id, 'transferencia_recibida', v_monto_neto,
         (SELECT saldo - v_monto_neto FROM auth.billetera WHERE id_usuario = p_receptor_id),
         (SELECT saldo FROM auth.billetera WHERE id_usuario = p_receptor_id),
         v_transferencia_id::text,
         jsonb_build_object('origen_id', v_actor_id));

    -- Outbox AGE (async)
    INSERT INTO auth.billetera_graph_outbox (
        tipo_evento, origen_id, receptor_id, payload
    ) VALUES (
        'TRANSFERRED_POINTS', v_actor_id, p_receptor_id,
        jsonb_build_object(
            'transferencia_id', v_transferencia_id,
            'monto_bruto',      p_monto,
            'comision',         v_comision,
            'monto_neto',       v_monto_neto
        )
    );

    RETURN jsonb_build_object(
        'transferencia_id', v_transferencia_id,
        'monto_bruto',      p_monto,
        'comision',         v_comision,
        'monto_neto',       v_monto_neto,
        'saldo_nuevo',      v_billetera.saldo - p_monto
    );
END;
$$;


--
-- Name: seller_unir_zonas_delivery(uuid, uuid[], text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_unir_zonas_delivery(p_id_vendedor uuid, p_ids_zonas uuid[], p_name text, p_slug text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_union geometry;
  v_id uuid;
BEGIN
  SELECT ST_Union(geom)
    INTO v_union
   FROM public.geo_zones
  WHERE id_zona = ANY(p_ids_zonas)
    AND is_active = true
    AND fecha_eliminacion IS NULL;

  IF v_union IS NULL THEN
    RETURN jsonb_build_object('error', 'ninguna zona activa encontrada para unir');
  END IF;

  INSERT INTO public.geo_zones (id_zona, name, slug, zone_type, geom, is_active, es_publica, metadata)
  VALUES (
    gen_random_uuid(), p_name, p_slug, 'delivery', v_union, true, true,
    jsonb_build_object('id_vendedor', p_id_vendedor, 'unida_de', p_ids_zonas)
  )
  RETURNING id_zona INTO v_id;

  UPDATE public.geo_zones
     SET is_active = false, fecha_eliminacion = now()
   WHERE id_zona = ANY(p_ids_zonas);

  RETURN jsonb_build_object('id_zona', v_id, 'name', p_name, 'unidas', p_ids_zonas);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: seller_update_ubicacion(uuid, text, text, text, double precision, double precision, jsonb, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_update_ubicacion(p_ubicacion_id uuid, p_nombre text DEFAULT NULL::text, p_direccion_texto text DEFAULT NULL::text, p_tipo text DEFAULT NULL::text, p_latitud double precision DEFAULT NULL::double precision, p_longitud double precision DEFAULT NULL::double precision, p_horarios jsonb DEFAULT NULL::jsonb, p_fotos jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
  v_user_id uuid := (nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid;
  v_old     auth.ubicaciones%ROWTYPE;
BEGIN
  SELECT * INTO v_old FROM auth.ubicaciones
  WHERE id = p_ubicacion_id AND id_usuario = v_user_id AND fecha_eliminacion IS NULL;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ubicacion_no_encontrada_o_sin_permiso');
  END IF;

  -- RN-006: No editar ubicación inactiva sin reactivar primero
  IF v_old.estado = 'inactivo' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ubicacion_inactiva_reactivar_primero');
  END IF;

  UPDATE auth.ubicaciones SET
    nombre          = COALESCE(p_nombre, nombre),
    direccion_texto = COALESCE(p_direccion_texto, direccion_texto),
    tipo            = COALESCE(p_tipo, tipo),
    latitud         = COALESCE(p_latitud, latitud),
    longitud        = COALESCE(p_longitud, longitud),
    punto           = CASE
                        WHEN p_latitud IS NOT NULL AND p_longitud IS NOT NULL
                        THEN ST_SetSRID(ST_MakePoint(p_longitud, p_latitud), 4326)::geography
                        ELSE punto
                      END,
    horarios        = COALESCE(p_horarios, horarios),
    fotos           = COALESCE(p_fotos, fotos),
    fecha_actualizacion      = now()
  WHERE id = p_ubicacion_id AND id_usuario = v_user_id;

  INSERT INTO auth.h_vendedores_audit
    (id_usuario, operacion, datos_anteriores, datos_nuevos, modificado_por, motivo)
  VALUES (v_user_id, 'UPDATE',
    row_to_json(v_old)::jsonb,
    jsonb_strip_nulls(jsonb_build_object(
      'ubicacion_id', p_ubicacion_id,
      'nombre', p_nombre, 'tipo', p_tipo,
      'latitud', p_latitud, 'longitud', p_longitud
    )),
    v_user_id, 'seller_update_ubicacion');

  -- Outbox AGE: re-sincronizar nodo
  INSERT INTO auth.ubicacion_graph_outbox (id_ubicacion, id_usuario, operacion, payload)
  VALUES (p_ubicacion_id, v_user_id, 'UPSERT',
    jsonb_build_object(
      'nombre', COALESCE(p_nombre, v_old.nombre),
      'tipo', COALESCE(p_tipo, v_old.tipo),
      'latitud', COALESCE(p_latitud, v_old.latitud),
      'longitud', COALESCE(p_longitud, v_old.longitud),
      'estado', v_old.estado
    ));

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: seller_upgrade_plan(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_upgrade_plan(p_plan_codigo text DEFAULT 'silver'::text, p_ciclo text DEFAULT 'mensual'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'ag_catalog'
    AS $$
DECLARE
    v_actor         uuid;
    v_plan_id       uuid;
    v_plan_ant      text;
    v_plan_ant_id   uuid;
    v_descuento     numeric := 0;
    v_precio_ant    numeric;
    v_precio_nuevo  numeric;
    v_expiracion    timestamptz;
BEGIN
    v_actor := auth.fn_current_user_id();

    IF p_ciclo NOT IN ('mensual', 'anual') THEN
        RAISE EXCEPTION 'ciclo_invalido: debe ser mensual o anual' USING ERRCODE = '22023';
    END IF;

    SELECT id, precio_mensual INTO v_plan_id, v_precio_nuevo
    FROM auth.planes_membresia
    WHERE codigo = p_plan_codigo AND activo = true;
    IF v_plan_id IS NULL THEN
        RAISE EXCEPTION 'plan_no_encontrado: %', p_plan_codigo USING ERRCODE = 'P0001';
    END IF;

    -- Plan actual
    SELECT pm.codigo, pm.id, pm.precio_mensual
    INTO v_plan_ant, v_plan_ant_id, v_precio_ant
    FROM auth.membresias_vendedor mv
    JOIN auth.planes_membresia pm ON pm.id = mv.id_plan
    WHERE mv.id_vendedor = v_actor AND mv.estado IN ('activo', 'grace_period')
    LIMIT 1;

    IF v_plan_ant = p_plan_codigo THEN
        RAISE EXCEPTION 'ya_tienes_ese_plan: %', p_plan_codigo USING ERRCODE = 'P0001';
    END IF;

    -- Descuento anual
    IF p_ciclo = 'anual' THEN
        v_descuento := 17; -- 2 meses gratis ≈ 17%
        v_expiracion := now() + interval '1 year';
    ELSE
        v_expiracion := now() + interval '1 month';
    END IF;

    -- Encolar pago si no es Bronze (Bronze es gratuito)
    IF v_precio_nuevo > 0 THEN
        INSERT INTO auth.membresia_pagos_queue
            (id_vendedor, tipo_pago, monto, ciclo, plan_codigo,
             membresia_id)
        SELECT
            v_actor,
            CASE WHEN v_precio_nuevo > COALESCE(v_precio_ant, 0) THEN 'upgrade' ELSE 'upgrade' END,
            CASE WHEN p_ciclo = 'anual' THEN v_precio_nuevo * 12 * (1 - v_descuento/100)
                 ELSE v_precio_nuevo END,
            p_ciclo,
            p_plan_codigo,
            mv.id
        FROM auth.membresias_vendedor mv
        WHERE mv.id_vendedor = v_actor AND mv.estado IN ('activo', 'grace_period')
        LIMIT 1;
    END IF;

    -- Actualizar membresía (solo si Bronze→Bronze gratis o pago ya encolado)
    -- Para Bronze (gratuito) cambio inmediato; para pagos: el daemon confirma y activa
    IF v_precio_nuevo = 0 THEN
        UPDATE auth.membresias_vendedor
        SET id_plan             = v_plan_id,
            ciclo_pago          = p_ciclo,
            descuento_anual_pct = v_descuento,
            es_trial            = false,
            fecha_expiracion    = v_expiracion,
            auto_renovar        = true
        WHERE id_vendedor = v_actor
          AND estado IN ('activo', 'grace_period')
          AND fecha_eliminacion IS NULL;
    END IF;

    RETURN jsonb_build_object(
        'plan_anterior',  v_plan_ant,
        'plan_nuevo',     p_plan_codigo,
        'ciclo',          p_ciclo,
        'descuento_pct',  v_descuento,
        'pago_encolado',  v_precio_nuevo > 0,
        'expiracion',     v_expiracion
    );
END;
$$;


--
-- Name: seller_upsert_categoria(uuid, text, text, uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_upsert_categoria(p_id uuid DEFAULT NULL::uuid, p_nombre text DEFAULT NULL::text, p_descripcion text DEFAULT NULL::text, p_id_tipo_producto uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.current_jwt_user_id();
  v_role  text := auth.current_jwt_role();
  v_nombre text;
  v_id    uuid;
BEGIN
  IF v_actor IS NULL OR v_role NOT IN ('seller','db_admin') THEN
    RAISE EXCEPTION 'No autenticado como vendedor' USING ERRCODE = 'PT401';
  END IF;

  v_nombre := btrim(coalesce(p_nombre, ''));
  IF v_nombre = '' THEN
    RAISE EXCEPTION 'El nombre de la categoría es obligatorio.' USING ERRCODE = 'P0001';
  END IF;

  IF p_id IS NOT NULL THEN
    UPDATE auth.categorias
       SET nombre = v_nombre,
           descripcion = nullif(btrim(coalesce(p_descripcion,'')), ''),
           id_tipo_producto = p_id_tipo_producto,
           activo = true,
           fecha_actualizacion = now(),
           fecha_eliminacion = NULL,
           deleted_by = NULL,
           delete_reason = NULL
     WHERE id = p_id AND id_vendedor = v_actor
     RETURNING id INTO v_id;

    IF v_id IS NULL THEN
      RAISE EXCEPTION 'Categoría no encontrada o no pertenece al vendedor actual.' USING ERRCODE = 'P0404';
    END IF;
    RETURN v_id;
  END IF;

  INSERT INTO auth.categorias (
    id_vendedor, nombre, descripcion, id_tipo_producto, activo, fecha_creacion, fecha_actualizacion
  ) VALUES (
    v_actor, v_nombre, nullif(btrim(coalesce(p_descripcion,'')), ''), p_id_tipo_producto, true, now(), now()
  )
  ON CONFLICT (id_vendedor, nombre) DO UPDATE
    SET descripcion = EXCLUDED.descripcion,
        id_tipo_producto = EXCLUDED.id_tipo_producto,
        activo = true,
        fecha_actualizacion = now(),
        fecha_eliminacion = NULL,
        deleted_by = NULL,
        delete_reason = NULL
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: seller_upsert_perfil_publico(text, text, text, text, text, jsonb, uuid, boolean, boolean, boolean, text, jsonb); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_upsert_perfil_publico(p_nombre_marca text, p_biografia text DEFAULT NULL::text, p_url_logo text DEFAULT NULL::text, p_url_banner text DEFAULT NULL::text, p_slogan text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_ubicacion_principal_id uuid DEFAULT NULL::uuid, p_mostrar_estadisticas boolean DEFAULT true, p_mostrar_contacto boolean DEFAULT false, p_mostrar_ubicacion boolean DEFAULT true, p_slug_publico text DEFAULT NULL::text, p_metricas_visibles jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_row   auth.perfiles_publicos_vendedor%ROWTYPE;
BEGIN
  v_actor := auth.current_jwt_user_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'actor_no_autenticado';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM auth.users u
    WHERE u.id = v_actor AND u.role = 'seller'
  ) THEN
    RAISE EXCEPTION 'solo_vendedores_pueden_editar_perfil_publico';
  END IF;

  IF p_metadata IS NULL OR jsonb_typeof(p_metadata) <> 'object' THEN
    RAISE EXCEPTION 'metadata_debe_ser_objeto_json' USING ERRCODE = '22023';
  END IF;

  IF p_metricas_visibles IS NOT NULL AND jsonb_typeof(p_metricas_visibles) <> 'object' THEN
    RAISE EXCEPTION 'metricas_visibles_debe_ser_objeto_json' USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('app.audit_reason', 'seller_upsert_perfil_publico', true);

  INSERT INTO auth.perfiles_publicos_vendedor (
    id_vendedor, slug_publico, nombre_marca, biografia, url_logo, metadata,
    activo, fecha_creacion, fecha_modificacion,
    slogan, url_banner, ubicacion_principal_id,
    mostrar_estadisticas, mostrar_contacto, mostrar_ubicacion,
    metricas_visibles
  )
  VALUES (
    v_actor, p_slug_publico, p_nombre_marca, p_biografia, p_url_logo,
    p_metadata, true, now(), now(),
    p_slogan, p_url_banner, p_ubicacion_principal_id,
    COALESCE(p_mostrar_estadisticas, true),
    COALESCE(p_mostrar_contacto, false),
    COALESCE(p_mostrar_ubicacion, true),
    COALESCE(p_metricas_visibles, '{}')
  )
  ON CONFLICT (id_vendedor) DO UPDATE SET
    slug_publico         = COALESCE(EXCLUDED.slug_publico, auth.perfiles_publicos_vendedor.slug_publico),
    nombre_marca         = EXCLUDED.nombre_marca,
    biografia            = EXCLUDED.biografia,
    url_logo             = EXCLUDED.url_logo,
    metadata             = EXCLUDED.metadata,
    fecha_modificacion   = now(),
    slogan               = EXCLUDED.slogan,
    url_banner           = EXCLUDED.url_banner,
    ubicacion_principal_id = EXCLUDED.ubicacion_principal_id,
    mostrar_estadisticas = EXCLUDED.mostrar_estadisticas,
    mostrar_contacto     = EXCLUDED.mostrar_contacto,
    mostrar_ubicacion    = EXCLUDED.mostrar_ubicacion,
    metricas_visibles    = EXCLUDED.metricas_visibles,
    activo               = auth.perfiles_publicos_vendedor.activo,   -- PRESERVAR
    verificado           = auth.perfiles_publicos_vendedor.verificado  -- PRESERVAR
  RETURNING * INTO v_row;

  PERFORM set_config('app.audit_reason', '', true);

  RETURN jsonb_build_object(
    'ok', true,
    'id_vendedor', v_row.id_vendedor,
    'slug_publico', v_row.slug_publico,
    'activo', v_row.activo,
    'verificado', v_row.verificado,
    'badge_membresia', v_row.badge_membresia,
    'fecha_modificacion', v_row.fecha_modificacion
  );
END;
$$;


--
-- Name: seller_upsert_product(uuid, uuid, text, text, uuid, uuid, text, text, text, text, numeric, numeric, integer, text, boolean, integer, integer, double precision, double precision, uuid[], jsonb, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_upsert_product(p_producto_id uuid DEFAULT NULL::uuid, p_id_categoria uuid DEFAULT NULL::uuid, p_nombre_categoria text DEFAULT NULL::text, p_descripcion_categoria text DEFAULT NULL::text, p_id_tipo_producto uuid DEFAULT NULL::uuid, p_id_subcategoria uuid DEFAULT NULL::uuid, p_nombre_subcategoria text DEFAULT NULL::text, p_descripcion_subcategoria text DEFAULT NULL::text, p_nombre text DEFAULT NULL::text, p_descripcion text DEFAULT NULL::text, p_precio numeric DEFAULT NULL::numeric, p_descuento_porcentaje numeric DEFAULT NULL::numeric, p_puntos_recompensa integer DEFAULT NULL::integer, p_condicion text DEFAULT NULL::text, p_activo boolean DEFAULT true, p_stock_total integer DEFAULT NULL::integer, p_umbral_alerta integer DEFAULT NULL::integer, p_latitud double precision DEFAULT NULL::double precision, p_longitud double precision DEFAULT NULL::double precision, p_categoria_global_ids uuid[] DEFAULT NULL::uuid[], p_fotos jsonb DEFAULT NULL::jsonb, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public'
    AS $$
declare
  v_actor_id          uuid;

  v_before            jsonb;

  v_after             jsonb;

  v_producto_id       uuid;

  v_categoria_id      uuid;

  v_subcategoria_id   uuid;

  v_geo_lat           double precision;

  v_geo_lon           double precision;

  v_fotos_count       integer;

  v_max_productos     integer;

  v_max_fotos         integer;

  v_membresia_codigo  text;

  v_producto_previo   auth.productos%rowtype;

  v_foto              jsonb;

  v_foto_idx          integer := 0;

  v_should_be_active  boolean;

begin
  v_actor_id := auth.fn_current_user_id();


  if auth.fn_current_user_role() <> 'seller' then raise exception 'seller_role_required';
 end if;

  perform auth.fn_assert_seller_operable(v_actor_id);


    select membresia_codigo, max_productos_activos, max_fotos_por_producto
  into v_membresia_codigo, v_max_productos, v_max_fotos
  from auth.fn_get_publication_limits(v_actor_id)
  limit 1;


  if v_max_productos is null then raise exception 'membership_limits_not_resolved';
 end if;


    if p_precio is not null and p_precio < 0 then raise exception 'precio_must_be_non_negative';
 end if;

  if p_descuento_porcentaje is not null and (p_descuento_porcentaje < 0 or p_descuento_porcentaje > 100) then raise exception 'descuento_fuera_de_rango';
 end if;

  if p_puntos_recompensa is not null and p_puntos_recompensa < 0 then raise exception 'puntos_recompensa_must_be_non_negative';
 end if;

  if p_stock_total is not null and p_stock_total < 0 then raise exception 'stock_total_must_be_non_negative';
 end if;

  if p_umbral_alerta is not null and p_umbral_alerta < 0 then raise exception 'umbral_alerta_must_be_non_negative';
 end if;

  if p_fotos is not null and jsonb_typeof(p_fotos) <> 'array' then raise exception 'p_fotos_must_be_json_array';
 end if;


  v_fotos_count := case when p_fotos is null then 0 else jsonb_array_length(p_fotos) end;

  if v_fotos_count > v_max_fotos then raise exception 'max_fotos_por_producto_excedido';
 end if;


    if p_id_categoria is not null then
    select c.id into v_categoria_id
    from auth.categorias c
    where c.id = p_id_categoria and c.id_vendedor = v_actor_id
      and c.activo = true and c.fecha_eliminacion is null;

    if v_categoria_id is null then raise exception 'categoria_invalida_para_vendedor';
 end if;

  elsif p_nombre_categoria is not null and btrim(p_nombre_categoria) <> '' then
    insert into auth.categorias (id_vendedor, id_tipo_producto, nombre, descripcion, activo, fecha_eliminacion, deleted_by, delete_reason)
    values (v_actor_id, p_id_tipo_producto, btrim(p_nombre_categoria), nullif(btrim(coalesce(p_descripcion_categoria,'')), ''), true, null, null, null)
    ON CONFLICT (id_vendedor, nombre) do update
      set id_tipo_producto = coalesce(excluded.id_tipo_producto, auth.categorias.id_tipo_producto),
          descripcion      = coalesce(excluded.descripcion,      auth.categorias.descripcion),
          activo=true, fecha_eliminacion=null, deleted_by=null, delete_reason=null, fecha_actualizacion=now()
    returning id into v_categoria_id;

  end if;


  if p_producto_id is null and v_categoria_id is null then raise exception 'categoria_required';
 end if;


    if p_id_subcategoria is not null then
    select s.id into v_subcategoria_id
    from auth.subcategorias s
    where s.id = p_id_subcategoria
      and s.id_categoria = coalesce(v_categoria_id, p_id_categoria)
      and s.activo = true and s.fecha_eliminacion is null;

    if v_subcategoria_id is null then raise exception 'subcategoria_invalida_para_categoria';
 end if;

  elsif p_nombre_subcategoria is not null and btrim(p_nombre_subcategoria) <> '' then
    if coalesce(v_categoria_id, p_id_categoria) is null then raise exception 'categoria_required_for_subcategoria';
 end if;

    insert into auth.subcategorias (id_categoria, nombre, descripcion, activo, fecha_eliminacion, deleted_by, delete_reason)
    values (coalesce(v_categoria_id, p_id_categoria), btrim(p_nombre_subcategoria),
            nullif(btrim(coalesce(p_descripcion_subcategoria,'')), ''), true, null, null, null)
    ON CONFLICT (id_categoria, nombre) do update
      set descripcion=coalesce(excluded.descripcion, auth.subcategorias.descripcion),
          activo=true, fecha_eliminacion=null, deleted_by=null, delete_reason=null, fecha_modificacion=now()
    returning id into v_subcategoria_id;

  end if;


  v_geo_lat := p_latitud;
 v_geo_lon := p_longitud;

  if (v_geo_lat is null) <> (v_geo_lon is null) then raise exception 'latitud_y_longitud_deben_venir_juntas';
 end if;


  v_should_be_active := coalesce(p_activo, true);


    if p_producto_id is null then
    if p_nombre  is null or btrim(p_nombre)  = '' then raise exception 'nombre_required';
  end if;

    if p_precio  is null then raise exception 'precio_required';
 end if;


    if v_should_be_active and auth.fn_count_active_products(v_actor_id, null) >= v_max_productos then
      raise exception 'max_productos_activos_excedido';

    end if;


        if v_should_be_active and (v_geo_lat is null or v_geo_lon is null) then
      select u.latitud, u.longitud into v_geo_lat, v_geo_lon
      from auth.ubicaciones u
      where u.id_usuario = v_actor_id and u.estado = 'activo'
      order by u.fecha_actualizacion desc, u.fecha_creacion desc limit 1;

    end if;


    if v_should_be_active and (v_geo_lat is null or v_geo_lon is null) then
      raise exception 'ubicacion_operativa_requerida_para_publicar';

    end if;


    insert into auth.productos (
      id_vendedor, id_categoria, id_subcategoria,
      nombre, descripcion, precio, descuento_porcentaje,
      puntos_recompensa, activo, condicion,
      fecha_eliminacion, deleted_by, delete_reason
    ) values (
      v_actor_id, v_categoria_id, v_subcategoria_id,
      btrim(p_nombre), nullif(btrim(coalesce(p_descripcion,'')), ''),
      p_precio, coalesce(p_descuento_porcentaje, 0),
      coalesce(p_puntos_recompensa, 0), v_should_be_active,
      coalesce(p_condicion, 'buen_estado'),
      null, null, null
    ) returning id into v_producto_id;


    insert into auth.inventario_producto (id_producto, id_vendedor, total_stock, umbral_alerta)
    values (v_producto_id, v_actor_id, coalesce(p_stock_total, 0), coalesce(p_umbral_alerta, 0))
    ON CONFLICT (id_producto) do update
      set total_stock=excluded.total_stock, umbral_alerta=excluded.umbral_alerta, fecha_modificacion=now();


    else
    select p.* into v_producto_previo
    from auth.productos p
    where p.id = p_producto_id and p.id_vendedor = v_actor_id
    for update;

    if not found then raise exception 'producto_not_found_for_seller';
 end if;

    if v_producto_previo.fecha_eliminacion is not null then raise exception 'producto_soft_deleted_use_restore';
 end if;

    select to_jsonb(p) into v_before from auth.productos p where p.id = p_producto_id;


    if not coalesce(v_producto_previo.activo, false) and v_should_be_active
       and auth.fn_count_active_products(v_actor_id, p_producto_id) >= v_max_productos then
      raise exception 'max_productos_activos_excedido';

    end if;


    if v_should_be_active and (v_geo_lat is null or v_geo_lon is null) then
      select pg.latitud, pg.longitud into v_geo_lat, v_geo_lon
      from auth.productos_geo pg where pg.id_producto = p_producto_id;

      if v_geo_lat is null then
        select u.latitud, u.longitud into v_geo_lat, v_geo_lon
        from auth.ubicaciones u
        where u.id_usuario = v_actor_id and u.estado = 'activo'
        order by u.fecha_actualizacion desc limit 1;

      end if;

    end if;


    if v_should_be_active and (v_geo_lat is null or v_geo_lon is null) then
      raise exception 'ubicacion_operativa_requerida_para_publicar';

    end if;


    update auth.productos
    set id_categoria          = coalesce(v_categoria_id,    id_categoria),
        id_subcategoria       = coalesce(v_subcategoria_id, id_subcategoria),
        nombre                = coalesce(nullif(btrim(coalesce(p_nombre,'')), ''), nombre),
        descripcion           = case when p_descripcion is null then descripcion else nullif(btrim(p_descripcion), '') end,
        precio                = coalesce(p_precio,                precio),
        descuento_porcentaje  = coalesce(p_descuento_porcentaje,  descuento_porcentaje),
        puntos_recompensa     = coalesce(p_puntos_recompensa,     puntos_recompensa),
        activo                = coalesce(p_activo,                activo),
        condicion             = coalesce(p_condicion,             condicion)
    where id = p_producto_id
    returning id into v_producto_id;


    if p_stock_total is not null or p_umbral_alerta is not null then
      insert into auth.inventario_producto (id_producto, id_vendedor, total_stock, umbral_alerta)
      values (v_producto_id, v_actor_id, coalesce(p_stock_total,0), coalesce(p_umbral_alerta,0))
      ON CONFLICT (id_producto) do update
        set total_stock  = coalesce(p_stock_total,   auth.inventario_producto.total_stock),
            umbral_alerta= coalesce(p_umbral_alerta, auth.inventario_producto.umbral_alerta),
            fecha_modificacion   = now();

    end if;

  end if;


    if v_geo_lat is not null and v_geo_lon is not null then
    insert into auth.productos_geo (id_producto, id_vendedor, latitud, longitud,
      punto, fecha_creacion, fecha_actualizacion)
    values (v_producto_id, v_actor_id, v_geo_lat, v_geo_lon,
      st_setsrid(st_makepoint(v_geo_lon, v_geo_lat), 4326)::geography, now(), now())
    ON CONFLICT (id_producto) do update
      set id_vendedor=excluded.id_vendedor, latitud=excluded.latitud,
          longitud=excluded.longitud, punto=excluded.punto, fecha_actualizacion=now();

  end if;


    if p_categoria_global_ids is not null then
    update auth.producto_categorias_globales
    set fecha_eliminacion=coalesce(fecha_eliminacion, now()),
        deleted_by=coalesce(deleted_by, v_actor_id),
        delete_reason=coalesce(p_motivo, 'replace_categorias_globales')
    where id_producto = v_producto_id and fecha_eliminacion is null;


    insert into auth.producto_categorias_globales (id_producto, categoria_global_id, created_by)
    select v_producto_id, x, v_actor_id
    from (select distinct unnest(p_categoria_global_ids)) s(x)
    join auth.categorias_globales cg on cg.id = s.x and cg.fecha_eliminacion is null and cg.activo = true;

  end if;


    if p_fotos is not null then
    update auth.galeria_fotos
    set activo=false, fecha_eliminacion=coalesce(fecha_eliminacion, now()),
        deleted_by=coalesce(deleted_by, v_actor_id), delete_reason=coalesce(p_motivo, 'replace_fotos')
    where id_producto = v_producto_id and fecha_eliminacion is null;


    v_foto_idx := 0;

    for v_foto in select value from jsonb_array_elements(p_fotos) loop
      if coalesce(nullif(btrim(v_foto ->> 'url'), ''), '') = '' then raise exception 'foto_url_required';
 end if;

      insert into auth.galeria_fotos (id_producto, url, descripcion, orden, activo, fecha_eliminacion, deleted_by, delete_reason)
      values (v_producto_id, btrim(v_foto ->> 'url'), nullif(btrim(coalesce(v_foto ->> 'descripcion', '')), ''),
              coalesce((v_foto ->> 'orden')::integer, v_foto_idx), true, null, null, null);

      v_foto_idx := v_foto_idx + 1;

    end loop;

  end if;


  select to_jsonb(p) into v_after from auth.productos p where p.id = v_producto_id;

  perform auth.fn_write_publicacion_audit(
    v_producto_id,
    case when p_producto_id is null then 'CREATE_PRODUCT' else 'UPDATE_PRODUCT' end,
    p_motivo, v_before, v_after
  );


  return jsonb_build_object(
    'producto_id',         v_producto_id,
    'membresia_codigo',    v_membresia_codigo,
    'max_productos_activos',  v_max_productos,
    'max_fotos_por_producto', v_max_fotos,
    'data', v_after
  );

end;
 
$$;


--
-- Name: seller_upsert_regla_precio(uuid, uuid, text, jsonb, numeric, numeric, smallint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_upsert_regla_precio(p_regla_id uuid DEFAULT NULL::uuid, p_producto_id uuid DEFAULT NULL::uuid, p_tipo_regla text DEFAULT NULL::text, p_condicion jsonb DEFAULT '{}'::jsonb, p_descuento_pct numeric DEFAULT NULL::numeric, p_precio_fijo numeric DEFAULT NULL::numeric, p_prioridad smallint DEFAULT 5, p_vigencia_desde timestamp with time zone DEFAULT NULL::timestamp with time zone, p_vigencia_hasta timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
declare v_actor_id uuid;
 v_id uuid;

begin
  v_actor_id := auth.fn_current_user_id();

  if auth.fn_current_user_role() <> 'seller' then raise exception 'seller_role_required';
 end if;


    if not auth.fn_get_feature_flag(v_actor_id, 'pricing_dinamico') then
    raise exception 'feature_pricing_dinamico_requires_gold_plan';

  end if;


  if p_regla_id is null then
        if p_producto_id is null then raise exception 'producto_id_required';
 end if;

    if p_tipo_regla  is null then raise exception 'tipo_regla_required';
  end if;

    if p_descuento_pct is null and p_precio_fijo is null then raise exception 'descuento_o_precio_fijo_required';
 end if;


    if not exists (select 1 from auth.productos p where p.id = p_producto_id and p.id_vendedor = v_actor_id and p.fecha_eliminacion is null) then
      raise exception 'producto_not_found_for_seller';

    end if;


    insert into auth.producto_precio_reglas (id_producto, tipo_regla, condicion, descuento_pct, precio_fijo, prioridad, vigencia_desde, vigencia_hasta)
    values (p_producto_id, p_tipo_regla, coalesce(p_condicion, '{}'), coalesce(p_descuento_pct, 0), p_precio_fijo,
            coalesce(p_prioridad, 5), p_vigencia_desde, p_vigencia_hasta)
    returning id into v_id;

  else
        update auth.producto_precio_reglas
    set tipo_regla     = coalesce(p_tipo_regla,    tipo_regla),
        condicion      = coalesce(p_condicion,     condicion),
        descuento_pct  = coalesce(p_descuento_pct, descuento_pct),
        precio_fijo    = coalesce(p_precio_fijo,   precio_fijo),
        prioridad      = coalesce(p_prioridad,     prioridad),
        vigencia_desde = coalesce(p_vigencia_desde, vigencia_desde),
        vigencia_hasta = coalesce(p_vigencia_hasta, vigencia_hasta),
        fecha_actualizacion     = now()
    where id = p_regla_id
      and exists (select 1 from auth.productos p where p.id = producto_precio_reglas.id_producto and p.id_vendedor = v_actor_id)
    returning id into v_id;

    if v_id is null then raise exception 'regla_not_found_for_seller';
 end if;

  end if;


  return jsonb_build_object('regla_id', v_id, 'tipo_regla', p_tipo_regla);

end;
 $$;


--
-- Name: seller_upsert_seo_metadata(text, text, text, text[]); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_upsert_seo_metadata(p_og_title text DEFAULT NULL::text, p_og_description text DEFAULT NULL::text, p_og_image_url text DEFAULT NULL::text, p_keywords text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
BEGIN
  v_actor := auth.current_jwt_user_id();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'actor_no_autenticado'; END IF;

  INSERT INTO auth.perfil_seo_metadata
    (id_vendedor, og_title, og_description, og_image_url, keywords, fecha_actualizacion)
  VALUES
    (v_actor, p_og_title, p_og_description, p_og_image_url, p_keywords, now())
  ON CONFLICT (id_vendedor) DO UPDATE SET
    og_title       = EXCLUDED.og_title,
    og_description = EXCLUDED.og_description,
    og_image_url   = EXCLUDED.og_image_url,
    keywords       = EXCLUDED.keywords,
    fecha_actualizacion     = now();

  RETURN jsonb_build_object('ok', true, 'id_vendedor', v_actor);
END;
$$;


--
-- Name: seller_upsert_subcategoria(uuid, uuid, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.seller_upsert_subcategoria(p_id uuid DEFAULT NULL::uuid, p_id_categoria uuid DEFAULT NULL::uuid, p_nombre text DEFAULT NULL::text, p_descripcion text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor  uuid := auth.current_jwt_user_id();
  v_role   text := auth.current_jwt_role();
  v_nombre text;
  v_id     uuid;
BEGIN
  IF v_actor IS NULL OR v_role NOT IN ('seller','db_admin') THEN
    RAISE EXCEPTION 'No autenticado como vendedor' USING ERRCODE = 'PT401';
  END IF;

  v_nombre := btrim(coalesce(p_nombre, ''));
  IF v_nombre = '' THEN
    RAISE EXCEPTION 'El nombre de la subcategoría es obligatorio.' USING ERRCODE = 'P0001';
  END IF;

  IF p_id_categoria IS NULL THEN
    RAISE EXCEPTION 'La categoría padre es obligatoria.' USING ERRCODE = 'P0001';
  END IF;

  -- Validar que la categoría padre pertenece al vendedor (admin saltea).
  IF v_role <> 'db_admin' THEN
    IF NOT EXISTS (SELECT 1 FROM auth.categorias WHERE id = p_id_categoria AND id_vendedor = v_actor) THEN
      RAISE EXCEPTION 'Categoría padre no encontrada o no pertenece al vendedor actual.' USING ERRCODE = 'PT403';
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM auth.categorias WHERE id = p_id_categoria) THEN
      RAISE EXCEPTION 'Categoría padre no encontrada.' USING ERRCODE = 'P0404';
    END IF;
  END IF;

  IF p_id IS NOT NULL THEN
    UPDATE auth.subcategorias
       SET nombre = v_nombre,
           descripcion = nullif(btrim(coalesce(p_descripcion,'')), ''),
           activo = true,
           fecha_modificacion = now(),
           fecha_eliminacion = NULL,
           deleted_by = NULL,
           delete_reason = NULL
     WHERE id = p_id AND id_categoria = p_id_categoria
     RETURNING id INTO v_id;

    IF v_id IS NULL THEN
      RAISE EXCEPTION 'Subcategoría no encontrada o no pertenece a la categoría indicada.' USING ERRCODE = 'P0404';
    END IF;
    RETURN v_id;
  END IF;

  INSERT INTO auth.subcategorias (
    id_categoria, nombre, descripcion, activo, fecha_creacion, fecha_modificacion
  ) VALUES (
    p_id_categoria, v_nombre, nullif(btrim(coalesce(p_descripcion,'')), ''), true, now(), now()
  )
  ON CONFLICT (id_categoria, nombre) DO UPDATE
    SET descripcion = EXCLUDED.descripcion,
        activo = true,
        fecha_modificacion = now(),
        fecha_eliminacion = NULL,
        deleted_by = NULL,
        delete_reason = NULL
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- auth.productos usa fecha_modificacion en lugar de updated_at
    IF TG_TABLE_SCHEMA = 'auth' AND TG_TABLE_NAME = 'productos' THEN
        NEW.fecha_modificacion = NOW();
    ELSE
        NEW.updated_at = NOW();
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: simular_compra(uuid, integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.simular_compra(p_producto_id uuid, p_cantidad integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_uid UUID;
    v_role TEXT;
    v_producto RECORD;
    v_saldo_billetera NUMERIC(14,2) := 0;
    v_subtotal NUMERIC(14,2);
    v_monto_descuento NUMERIC(14,2);
    v_total NUMERIC(14,2);
    v_puntos INTEGER;
    v_elegible BOOLEAN;
    v_uc_id INTEGER;
    v_user_node BIGINT;
    v_uc_node BIGINT;
BEGIN
    v_role := auth.current_jwt_role();
    v_uid := auth.current_jwt_user_id();

    IF v_role NOT IN ('buyer', 'db_admin') THEN
        RAISE EXCEPTION 'Permiso denegado: role=%', COALESCE(v_role, 'null');
    END IF;

    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'JWT sin claim sub (user id)';
    END IF;

    IF p_cantidad IS NULL OR p_cantidad <= 0 THEN
        RAISE EXCEPTION 'Cantidad invalida: %', p_cantidad;
    END IF;

    SELECT
        p.id,
        p.nombre,
        p.precio,
        p.descuento_porcentaje,
        p.puntos_recompensa,
        p.activo
    INTO v_producto
    FROM auth.productos p
    WHERE p.id = p_producto_id;

    IF NOT FOUND OR COALESCE(v_producto.activo, FALSE) = FALSE THEN
        RAISE EXCEPTION 'Producto no encontrado o inactivo: %', p_producto_id;
    END IF;

    v_subtotal := ROUND(v_producto.precio * p_cantidad, 2);
    v_monto_descuento := ROUND(v_subtotal * (COALESCE(v_producto.descuento_porcentaje, 0) / 100.0), 2);
    v_total := ROUND(v_subtotal - v_monto_descuento, 2);
    v_puntos := COALESCE(v_producto.puntos_recompensa, 0) * p_cantidad;

    SELECT COALESCE(b.saldo, 0)
    INTO v_saldo_billetera
    FROM auth.billetera b
    WHERE b.id_usuario = v_uid
    LIMIT 1;

    v_elegible := (COALESCE(v_saldo_billetera, 0) >= v_total);

    SELECT id INTO v_uc_id FROM auth.use_cases WHERE slug = 'simular_compra';

    v_user_node := auth.ensure_query_graph_node(
        'user',
        v_uid,
        NULL,
        NULL,
        v_uid,
        'buyer:' || v_uid::TEXT,
        jsonb_build_object('id_usuario', v_uid)
    );

    v_uc_node := auth.ensure_query_graph_node(
        'use_case',
        NULL,
        NULL,
        v_uc_id,
        NULL,
        'simular_compra',
        '{}'::JSONB
    );

    PERFORM auth.ensure_query_graph_edge(
        v_user_node,
        v_uc_node,
        'BUYER_PURCHASE_SIMULATION:' || p_producto_id::TEXT,
        v_uid,
        jsonb_build_object(
            'producto_id', p_producto_id,
            'cantidad', p_cantidad,
            'subtotal', v_subtotal,
            'total', v_total,
            'elegible_compra_con_puntos', v_elegible,
            'simulado_en', NOW()
        )
    );

    RETURN jsonb_build_object(
        'producto_id', p_producto_id,
        'producto_nombre', v_producto.nombre,
        'precio_unitario', v_producto.precio,
        'cantidad', p_cantidad,
        'subtotal', v_subtotal,
        'descuento_porcentaje', COALESCE(v_producto.descuento_porcentaje, 0),
        'monto_descuento', v_monto_descuento,
        'total', v_total,
        'puntos_a_ganar', v_puntos,
        'saldo_billetera_actual', COALESCE(v_saldo_billetera, 0),
        'elegible_compra_con_puntos', v_elegible,
        'moneda', 'MXN',
        'metadata', jsonb_build_object(
            'fuente', 'auth.simular_compra',
            'calculado_en', NOW()
        )
    );
END;
$$;


--
-- Name: sync_user_lifecycle_projection(uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.sync_user_lifecycle_projection(p_target_user_id uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
declare
  v_user auth.users%rowtype;

  v_user_node_id bigint;
 v_use_case_id integer;
 v_use_case_node_id bigint;

begin
  select * into v_user from auth.users where id=p_target_user_id;

  if not found then return;
 end if;

  select id into v_use_case_id from auth.use_cases where slug='admin_secure_delete_user_lifecycle';


  insert into auth.query_graph_nodes(node_type,id_usuario,owner_user_id,label,payload)
  values ('user',v_user.id,auth.fn_current_user_id(),'UserLifecycle',jsonb_build_object(
    'role',v_user.role,'tier',auth.resolve_effective_tier(v_user.id,now()),
    'lifecycle_state',v_user.lifecycle_state,'legal_hold',v_user.legal_hold,
    'deleted_at',v_user.fecha_eliminacion,'anonymized_at',v_user.fecha_anonimizacion,'last_action',p_action))
  ON CONFLICT (id_usuario) WHERE id_usuario IS NOT NULL do update set owner_user_id=excluded.owner_user_id,
    label=excluded.label, payload=excluded.payload, updated_at=now();


  insert into auth.query_graph_nodes(node_type,use_case_id,owner_user_id,label,payload)
  values ('use_case',v_use_case_id,auth.fn_current_user_id(),'SecureDeleteUseCase',
    jsonb_build_object('slug','admin_secure_delete_user_lifecycle'))
  ON CONFLICT (use_case_id) WHERE use_case_id IS NOT NULL do update set payload=excluded.payload, updated_at=now();


  select id into v_user_node_id from auth.query_graph_nodes where id_usuario=v_user.id;

  select id into v_use_case_node_id from auth.query_graph_nodes where use_case_id=v_use_case_id;


  insert into auth.query_graph_edges(from_node_id,to_node_id,edge_type,owner_user_id,payload)
  values (v_user_node_id,v_use_case_node_id,'AFFECTED_BY_LIFECYCLE',
    auth.fn_current_user_id(),jsonb_build_object('last_action',p_action))
  ON CONFLICT (from_node_id,to_node_id,edge_type) do update
  set owner_user_id=excluded.owner_user_id, payload=excluded.payload, updated_at=now();


  perform auth.ensure_age_lifecycle_labels();

  perform set_config('search_path','ag_catalog,auth,public',true);


  execute format($f$
    select * from cypher('smtp_posix_graph', $cypher$
      merge (u:UserLifecycleMirror {auth_user_id: '%s'})
      set u.role='%s', u.tier='%s', u.lifecycle_state='%s',
          u.legal_hold='%s', u.fecha_eliminacion='%s', u.fecha_anonimizacion='%s', u.last_action='%s'
      return u
    $cypher$) as (v agtype)
  $f$, v_user.id, v_user.role, auth.resolve_effective_tier(v_user.id,now()),
       v_user.lifecycle_state,
       case when v_user.legal_hold then 'true' else 'false' end,
       coalesce(v_user.fecha_eliminacion::text,''),
       coalesce(v_user.fecha_anonimizacion::text,''), p_action);

end;

$_$;


