--
-- Name: trg_defensive_delete_auth_users(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.trg_defensive_delete_auth_users() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'auth', 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_allow text := current_setting('app.allow_physical_purge', true);
  v_before jsonb;
  v_after jsonb;
begin
  if v_allow IN ('true', 'on') then
    return old;
  end if;

  v_before := to_jsonb(old);

  update auth.users
  set activo=false,
      lifecycle_state=case when old.fecha_anonimizacion is null then 'soft_deleted' else old.lifecycle_state end,
      fecha_eliminacion=coalesce(old.fecha_eliminacion,now()),
      deleted_reason=coalesce(old.deleted_reason,'DELETE_INTERCEPTED'),
      fecha_actualizacion=now()
  where id=old.id;

  select to_jsonb(u) into v_after from auth.users u where u.id=old.id;

  perform auth.lifecycle_log_event('DELETE_INTERCEPTED','critical',old.id,'DELETE_INTERCEPTED',
    v_before,v_after,old.lifecycle_state,coalesce(v_after->>'lifecycle_state','soft_deleted'),'trigger',null);

  return null;
end;
$$;


--
-- Name: trg_fn_bridge_activo_is_active(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.trg_fn_bridge_activo_is_active() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- is_active cambia → sincronizar activo
  IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN
    NEW.activo := NEW.is_active;
  END IF;
  -- activo cambia sin cambio en is_active → sincronizar is_active
  IF NEW.activo IS DISTINCT FROM OLD.activo
     AND NEW.is_active IS NOT DISTINCT FROM OLD.is_active THEN
    NEW.is_active := NEW.activo;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_fn_bridge_name_nombre(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.trg_fn_bridge_name_nombre() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.name IS NOT NULL AND NEW.nombre IS DISTINCT FROM NEW.name THEN
    NEW.nombre := NEW.name;
  ELSIF NEW.nombre IS NOT NULL AND NEW.name IS NULL THEN
    NEW.name := NEW.nombre;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_fn_bridge_producto_id_id_producto(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.trg_fn_bridge_producto_id_id_producto() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.producto_id IS NOT NULL AND NEW.id_producto IS DISTINCT FROM NEW.producto_id THEN
    NEW.id_producto := NEW.producto_id;
  ELSIF NEW.id_producto IS NOT NULL AND NEW.producto_id IS NULL THEN
    NEW.producto_id := NEW.id_producto;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_fn_bridge_status_estado(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.trg_fn_bridge_status_estado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status IS NOT NULL AND NEW.estado IS DISTINCT FROM NEW.status THEN
    NEW.estado := NEW.status;
  ELSIF NEW.estado IS NOT NULL AND NEW.status IS NULL THEN
    NEW.status := NEW.estado;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_fn_bridge_updated_at_fecha_actualizacion(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.trg_fn_bridge_updated_at_fecha_actualizacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.updated_at IS NOT NULL AND NEW.fecha_actualizacion IS DISTINCT FROM NEW.updated_at THEN
    NEW.fecha_actualizacion := NEW.updated_at;
  ELSIF NEW.fecha_actualizacion IS NOT NULL AND NEW.updated_at IS NULL THEN
    NEW.updated_at := NEW.fecha_actualizacion;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_fn_bridge_users_timestamps(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.trg_fn_bridge_users_timestamps() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.created_at IS NULL AND NEW.fecha_creacion IS NOT NULL THEN
      NEW.created_at := NEW.fecha_creacion;
    ELSIF NEW.fecha_creacion IS NULL AND NEW.created_at IS NOT NULL THEN
      NEW.fecha_creacion := NEW.created_at;
    ELSIF NEW.created_at IS NULL AND NEW.fecha_creacion IS NULL THEN
      NEW.created_at := now();
      NEW.fecha_creacion := NEW.created_at;
    END IF;
    IF NEW.updated_at IS NULL AND NEW.fecha_actualizacion IS NOT NULL THEN
      NEW.updated_at := NEW.fecha_actualizacion;
    ELSIF NEW.fecha_actualizacion IS NULL AND NEW.updated_at IS NOT NULL THEN
      NEW.fecha_actualizacion := NEW.updated_at;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.created_at IS DISTINCT FROM OLD.created_at
     AND NEW.fecha_creacion IS NOT DISTINCT FROM OLD.fecha_creacion THEN
    NEW.fecha_creacion := NEW.created_at;
  ELSIF NEW.fecha_creacion IS DISTINCT FROM OLD.fecha_creacion
        AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at THEN
    NEW.created_at := NEW.fecha_creacion;
  END IF;

  IF NEW.updated_at IS DISTINCT FROM OLD.updated_at
     AND NEW.fecha_actualizacion IS NOT DISTINCT FROM OLD.fecha_actualizacion THEN
    NEW.fecha_actualizacion := NEW.updated_at;
  ELSIF NEW.fecha_actualizacion IS DISTINCT FROM OLD.fecha_actualizacion
        AND NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at THEN
    NEW.updated_at := NEW.fecha_actualizacion;
  END IF;
  RETURN NEW;
END;
$$;


