--
-- Name: validar_calificacion_final(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.validar_calificacion_final() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_estado text;
  v_hilo boolean;
BEGIN
  -- Inmutabilidad de la calificacion final (regla CU)
  IF OLD.calificacion <> NEW.calificacion THEN
    RAISE EXCEPTION 'La calificacion final es inmutable'
      USING ERRCODE = '23514';
  END IF;

  -- Orden en estado entregado
  SELECT estado INTO v_estado FROM auth.ordenes WHERE id_orden = NEW.id_orden;
  IF v_estado IS DISTINCT FROM 'entregado' THEN
    RAISE EXCEPTION 'Solo se puede calificar una orden entregada (estado actual: %)',
      COALESCE(v_estado, 'inexistente') USING ERRCODE = '23514';
  END IF;

  -- Hilo de mensajeria previo ligado al pedido
  SELECT EXISTS (
    SELECT 1 FROM auth.conversaciones c
     WHERE c.id_orden = NEW.id_orden
       AND EXISTS (SELECT 1 FROM auth.mensajes m WHERE m.id_conversacion = c.id))
    INTO v_hilo;
  IF NOT v_hilo THEN
    RAISE EXCEPTION 'Debe existir un hilo de mensajeria previo ligado al pedido'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validar_mensaje_lifecycle(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.validar_mensaje_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_conv record;
BEGIN
  SELECT id_orden, id_producto INTO v_conv
    FROM auth.conversaciones WHERE id = NEW.id_conversacion;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conversacion % inexistente', NEW.id_conversacion
      USING ERRCODE = 'P0002';
  END IF;

  -- El mensaje debe tener contexto de producto o pedido (regla CU)
  IF v_conv.id_orden IS NULL AND v_conv.id_producto IS NULL THEN
    RAISE EXCEPTION 'El mensaje debe tener contexto de producto o pedido'
      USING ERRCODE = '23514';
  END IF;

  -- Si trae id_orden, exigir que el pedido exista
  IF v_conv.id_orden IS NOT NULL THEN
    PERFORM 1 FROM auth.ordenes WHERE id = v_conv.id_orden;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'El pedido % referenciado no existe', v_conv.id_orden
        USING ERRCODE = 'P0002';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validar_pedido_lifecycle(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.validar_pedido_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
  v_stock numeric;
BEGIN
  -- Comprador y vendedor distintos (regla CU)
  IF NEW.id_comprador = NEW.id_vendedor THEN
    RAISE EXCEPTION 'El comprador y el vendedor deben ser distintos'
      USING ERRCODE = '23514';
  END IF;

  -- Stock backend: si la orden referencia producto unico, validar stock
  -- (stock_available es TEXT en el schema real: cast numerico)
  IF NEW.id_producto IS NOT NULL THEN
    SELECT stock_available::numeric INTO v_stock
      FROM auth.productos WHERE id = NEW.id_producto;
    IF v_stock IS NULL OR v_stock < COALESCE(NEW.quantity, 1) THEN
      RAISE EXCEPTION 'Stock insuficiente para el producto %', NEW.id_producto
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: verify_otp(text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.verify_otp(p_email text, p_otp text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'pg_temp'
    AS $$
DECLARE
    v_updated INT;
BEGIN
    UPDATE auth.users
    SET is_verified = TRUE,
        otp_code = NULL,
        otp_expiry = NULL
    WHERE email = p_email
      AND otp_code = p_otp
      AND otp_expiry > NOW();

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN v_updated > 0;
END;
$$;


