--
-- Name: calculate_next_retry(character varying, integer); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.calculate_next_retry(p_channel character varying, p_attempt integer) RETURNS timestamp without time zone
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_policy notifications.retry_policies;
  v_delay_seconds INT;
  v_jitter_seconds INT;
  v_max_age_seconds INT := 259200;  -- 72 horas en segundos (no existe columna max_age_seconds)
  v_current_timestamp TIMESTAMP;
BEGIN
  SELECT * INTO v_policy FROM notifications.retry_policies WHERE channel = p_channel;
  IF v_policy IS NULL THEN
    RETURN NOW() + INTERVAL '1 hour';
  END IF;
  v_delay_seconds := (v_policy.base_delay_seconds * POWER(v_policy.backoff_multiplier, p_attempt - 1))::INT;
  IF v_policy.jitter_enabled THEN
    v_jitter_seconds := (random() * (v_delay_seconds * 0.2) - (v_delay_seconds * 0.1))::INT;
    v_delay_seconds := v_delay_seconds + v_jitter_seconds;
  END IF;
  v_current_timestamp := NOW() + (v_delay_seconds || ' seconds')::INTERVAL;
  IF (v_current_timestamp - NOW()) > (v_max_age_seconds || ' seconds')::INTERVAL THEN
    RETURN NULL;
  END IF;
  RETURN v_current_timestamp;
END;
$$;


--
-- Name: check_sms_rate_limits(uuid, character varying, character varying); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.check_sms_rate_limits(p_user_id uuid, p_phone_destination character varying, p_country_code character varying) RETURNS TABLE(allowed boolean, error_message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_sent_hour INT;
  v_destination_sent_day INT;
  v_country_sent_minute INT;
  v_max_per_hour INT := 3;
  v_max_per_day INT := 10;
  v_max_per_minute INT := 100;
BEGIN
  SELECT COUNT(*) INTO v_user_sent_hour FROM notifications.queue
  WHERE id_usuario = p_user_id
  AND channel = 'sms'
  AND fecha_creacion > NOW() - INTERVAL '1 hour'
  AND estado IN ('sent', 'retrying', 'pending');
  IF v_user_sent_hour >= v_max_per_hour THEN
    RETURN QUERY SELECT FALSE, 'User exceeded SMS limit (3 per hour)';
    RETURN;
  END IF;

  SELECT COUNT(*) INTO v_destination_sent_day FROM notifications.queue nq
  JOIN notifications.sms_delivery_reports sdr ON nq.id = sdr.id_notificacion
  WHERE sdr.phone_number = p_phone_destination
  AND nq.fecha_creacion > NOW() - INTERVAL '1 day';
  IF v_destination_sent_day >= v_max_per_day THEN
    RETURN QUERY SELECT FALSE, 'Destination number exceeded SMS limit (10 per day)';
    RETURN;
  END IF;

  SELECT COUNT(*) INTO v_country_sent_minute FROM notifications.queue nq
  JOIN notifications.sms_delivery_reports sdr ON nq.id = sdr.id_notificacion
  WHERE sdr.phone_number LIKE '+' || p_country_code || '%'
  AND sdr.submitted_at > NOW() - INTERVAL '1 minute';
  IF v_country_sent_minute >= v_max_per_minute THEN
    RETURN QUERY SELECT FALSE, 'Country exceeded SMS limit (100 per minute)';
    RETURN;
  END IF;

  RETURN QUERY SELECT TRUE, NULL::TEXT;
END;
$$;


--
-- Name: cleanup_expired_dlr(); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.cleanup_expired_dlr() RETURNS TABLE(cleaned integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cleaned INT;
BEGIN
  -- Marcar como failed los SMS sin DLR en 24h
  UPDATE notifications.queue
  SET estado = 'failed',
      error_details = 'No DLR received within 24 hours',
      fecha_actualizacion = NOW()
  WHERE id IN (
    SELECT nq.id FROM notifications.queue nq
    LEFT JOIN notifications.sms_delivery_reports sdr ON nq.id = sdr.id_notificacion
    WHERE nq.channel = 'sms'
    AND nq.estado IN ('pending', 'retrying')
    AND nq.fecha_creacion < NOW() - INTERVAL '24 hours'
    AND (sdr.estado IS NULL OR sdr.estado = 'submitted')
  );
  
  GET DIAGNOSTICS v_cleaned = ROW_COUNT;
  RETURN QUERY SELECT v_cleaned;
END;
$$;


--
-- Name: cleanup_inactive_devices(); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.cleanup_inactive_devices() RETURNS TABLE(removed integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_removed INT;
BEGIN
  DELETE FROM notifications.user_devices
  WHERE active = FALSE AND fecha_actualizacion < NOW() - INTERVAL '30 days';
  
  GET DIAGNOSTICS v_removed = ROW_COUNT;
  RETURN QUERY SELECT v_removed;
END;
$$;


