--
-- Name: enqueue_notification(uuid, character varying, uuid, jsonb, jsonb); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.enqueue_notification(p_user_id uuid, p_channel character varying, p_template_id uuid, p_payload jsonb, p_metadata jsonb) RETURNS TABLE(id_notificacion uuid, estado character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'notifications', 'pg_temp'
    AS $$
DECLARE
  v_notification_id UUID;
  v_pref_enabled BOOLEAN;
  v_retry_policy notifications.retry_policies;
  v_next_retry TIMESTAMP;
  v_freq_limit INT;
  v_estado VARCHAR(20);
BEGIN
  IF NOT EXISTS(SELECT 1 FROM notifications.templates
                WHERE id = p_template_id AND channel = p_channel AND active = true) THEN
    RAISE EXCEPTION 'Template % not found or inactive for channel %', p_template_id, p_channel;
  END IF;

  SELECT pref.enabled INTO v_pref_enabled
  FROM notifications.preferences pref
  WHERE pref.id_usuario = p_user_id AND pref.channel = p_channel;

  IF v_pref_enabled IS FALSE THEN
    RAISE EXCEPTION 'User % has disabled channel %', p_user_id, p_channel;
  END IF;

  SELECT COALESCE(frequency_limit, 999) INTO v_freq_limit
  FROM notifications.preferences
  WHERE id_usuario = p_user_id AND channel = p_channel;

  IF (SELECT COUNT(*) FROM notifications.queue q
      WHERE q.id_usuario = p_user_id AND q.channel = p_channel
        AND q.fecha_creacion > NOW() - INTERVAL '1 day'
        AND q.estado IN ('sent', 'pending', 'retrying')) >= v_freq_limit THEN
    RAISE EXCEPTION 'User % exceeded frequency limit for channel %', p_user_id, p_channel;
  END IF;

  SELECT * INTO v_retry_policy
  FROM notifications.retry_policies
  WHERE channel = p_channel AND enabled = true;

  v_next_retry := NOW() + COALESCE(
      (v_retry_policy.base_delay_seconds * POWER(v_retry_policy.backoff_multiplier, 0))::INT, 0)
      * INTERVAL '1 second';

  INSERT INTO notifications.queue (
    id_usuario, channel, template_id, payload, estado, retry_count, next_retry_at,
    fecha_creacion, fecha_actualizacion, fecha_expiracion
  ) VALUES (
    p_user_id, p_channel, p_template_id, p_payload, 'pending', 0, v_next_retry,
    NOW(), NOW(), NOW() + INTERVAL '90 days'
  )
  RETURNING queue.id, queue.estado INTO v_notification_id, v_estado;

  RETURN QUERY SELECT v_notification_id, v_estado;
END;
$$;


--
-- Name: handle_channel_dispatch(text, character varying, uuid, jsonb); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.handle_channel_dispatch(p_id text, p_channel character varying, p_template_id uuid, p_payload jsonb) RETURNS text
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF p_channel = 'email' THEN
    PERFORM notifications.handle_email_channel(p_id::uuid, p_template_id, p_payload);
  END IF;
  -- sms/push/inapp/webhook: delegados al worker Node.js (HTTP RPC fuera de SQL)
  RETURN 'dispatched';
END;
$$;


--
-- Name: handle_email_channel(uuid, uuid, jsonb); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.handle_email_channel(p_notification_id uuid, p_template_id uuid, p_payload jsonb) RETURNS TABLE(success boolean, error_message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_email VARCHAR(255);
  v_is_valid BOOLEAN;
  v_err TEXT;
BEGIN
  v_email := p_payload->'recipient'->>'email';

  SELECT ve.is_valid, ve.error_message INTO v_is_valid, v_err
  FROM notifications.validate_email(v_email) AS ve;
  IF v_is_valid IS FALSE THEN
    RETURN QUERY SELECT FALSE, v_err;
    RETURN;
  END IF;

  INSERT INTO notifications.send_logs (id_notificacion, attempt, estado, timestamp)
  VALUES (p_notification_id, 1, 'pending', NOW());

  RETURN QUERY SELECT TRUE, NULL::TEXT;
END;
$$;


--
-- Name: invalidate_device_token(uuid, character varying); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.invalidate_device_token(p_device_id uuid, p_reason character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'notifications', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO notifications.push_device_tokens_log (id_usuario, id_dispositivo, old_token, reason)
  SELECT id_usuario, id_dispositivo, device_token, p_reason
  FROM notifications.user_devices
  WHERE id = p_device_id;

  UPDATE notifications.user_devices
  SET active = FALSE, fecha_actualizacion = NOW()
  WHERE id = p_device_id;
END;
$$;


--
-- Name: mark_notification_failed(uuid, text); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.mark_notification_failed(p_notification_id uuid, p_error_details text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_retry_policy notifications.retry_policies;
  v_current_retry INT;
BEGIN
  SELECT retry_count INTO v_current_retry FROM notifications.queue WHERE id = p_notification_id;
  SELECT * INTO v_retry_policy FROM notifications.retry_policies 
    WHERE channel = (SELECT channel FROM notifications.queue WHERE id = p_notification_id);
  
  -- Si se agotaron reintentos, marcar como FAILED
  IF v_current_retry >= v_retry_policy.max_attempts THEN
    UPDATE notifications.queue
    SET estado = 'failed', error_details = p_error_details, fecha_actualizacion = NOW()
    WHERE id = p_notification_id;
  ELSE
    -- Sino, marcar como RETRYING y calcular próximo intento
    UPDATE notifications.queue
    SET estado = 'retrying', 
        retry_count = retry_count + 1,
        next_retry_at = notifications.calculate_next_retry((SELECT channel FROM notifications.queue WHERE id = p_notification_id), retry_count + 1),
        error_details = p_error_details,
        fecha_actualizacion = NOW()
    WHERE id = p_notification_id;
  END IF;
END;
$$;


--
-- Name: move_to_dead_letter_queue(uuid, character varying, text); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.move_to_dead_letter_queue(p_notification_id uuid, p_reason character varying, p_error_details text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO notifications.dead_letter_queue (id_notificacion, reason, last_error)
  VALUES (p_notification_id, p_reason, p_error_details)
  ON CONFLICT (id_notificacion) DO UPDATE SET
    last_seen = NOW(),
    last_error = COALESCE(p_error_details, dead_letter_queue.last_error),
    attempts_made = dead_letter_queue.attempts_made + 1;
  
  UPDATE notifications.queue
  SET estado = 'failed', error_details = p_reason
  WHERE id = p_notification_id;
END;
$$;


--
-- Name: process_pending_notifications(); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.process_pending_notifications() RETURNS TABLE(processed integer, failed integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'notifications', 'pg_temp'
    AS $$
DECLARE
  v_processed INT := 0;
  v_failed INT := 0;
  v_notif RECORD;
BEGIN
  -- Seleccionar notificaciones listas para procesar (LOCK)
  FOR v_notif IN
    SELECT id, channel, id_usuario, template_id, payload
    FROM notifications.queue
    WHERE (estado = 'pending' OR (estado = 'retrying' AND next_retry_at <= NOW()))
    AND fecha_creacion > NOW() - INTERVAL '90 days'
    ORDER BY fecha_creacion ASC
    LIMIT 100
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      -- Delegar a canal específico (llamado a función canal handler)
      PERFORM notifications.handle_channel_dispatch(
        v_notif.id::TEXT, 
        v_notif.channel, 
        v_notif.template_id, 
        v_notif.payload
      );
      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      -- Error será manejado por retry logic
    END;
  END LOOP;
  
  RETURN QUERY SELECT v_processed, v_failed;
END;
$$;


--
-- Name: process_pending_webhooks(); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.process_pending_webhooks() RETURNS TABLE(processed integer, failed integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_processed INT := 0;
  v_failed INT := 0;
  v_webhook RECORD;
BEGIN
  -- Procesar webhooks listos para retry
  FOR v_webhook IN
    SELECT wd.id, wd.id_suscriptor_webhook, wd.id_notificacion, wd.attempt
    FROM notifications.webhook_deliveries wd
    WHERE (wd.estado = 'queued' OR (wd.estado = 'retrying' AND wd.next_retry_at <= NOW()))
    AND wd.attempt <= 3
    ORDER BY wd.fecha_creacion ASC
    LIMIT 100
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      -- Delegar a handler (implementado en Node.js)
      PERFORM notifications.dispatch_webhook_delivery(v_webhook.id_suscriptor_webhook, v_webhook.id_notificacion);
      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
    END;
  END LOOP;
  
  RETURN QUERY SELECT v_processed, v_failed;
END;
$$;


--
-- Name: register_device(uuid, character varying, text, character varying, character varying, character varying); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.register_device(p_user_id uuid, p_device_type character varying, p_device_token text, p_device_id character varying, p_os_version character varying, p_app_version character varying) RETURNS TABLE(id_dispositivo uuid, is_new boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_device_id UUID;
  v_is_new BOOLEAN := FALSE;
  v_existing_count INT;
BEGIN
  SELECT id INTO v_device_id FROM notifications.user_devices
  WHERE id_usuario = p_user_id AND device_token = p_device_token;

  IF v_device_id IS NOT NULL THEN
    UPDATE notifications.user_devices
    SET active = TRUE, last_used_at = NOW(), fecha_actualizacion = NOW()
    WHERE id = v_device_id;
  ELSE
    v_is_new := TRUE;

    SELECT COUNT(*) INTO v_existing_count FROM notifications.user_devices
    WHERE id_usuario = p_user_id AND active = TRUE;

    IF v_existing_count >= 5 THEN
      UPDATE notifications.user_devices
      SET active = FALSE
      WHERE id = (
        SELECT id FROM notifications.user_devices
        WHERE id_usuario = p_user_id AND active = TRUE
        ORDER BY last_used_at ASC NULLS FIRST
        LIMIT 1
      );
    END IF;

    INSERT INTO notifications.user_devices (
      id_usuario, device_type, device_token, id_dispositivo, os_version, app_version, active
    ) VALUES (
      p_user_id, p_device_type, p_device_token, p_device_id, p_os_version, p_app_version, TRUE
    )
    RETURNING id INTO v_device_id;
  END IF;

  RETURN QUERY SELECT v_device_id, v_is_new;
END;
$$;


--
-- Name: register_dlr(character varying, character varying, character varying, character varying, text); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.register_dlr(p_provider_id character varying, p_provider_message_id character varying, p_status character varying, p_dlr_code character varying DEFAULT NULL::character varying, p_dlr_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_notif_id UUID;
  v_phone VARCHAR(20);
BEGIN
  -- Actualizar report
  UPDATE notifications.sms_delivery_reports
  SET estado = p_status,
      dlr_code = p_dlr_code,
      dlr_reason = p_dlr_reason,
      delivered_at = CASE WHEN p_status = 'sent' THEN NOW() ELSE delivered_at END,
      fecha_actualizacion = NOW()
  WHERE provider_message_id = p_provider_message_id
  RETURNING id_notificacion, phone_number INTO v_notif_id, v_phone;
  
  IF v_notif_id IS NOT NULL THEN
    -- Actualizar queue según estado
    IF p_status = 'sent' THEN
      UPDATE notifications.queue
      SET estado = 'sent', fecha_actualizacion = NOW()
      WHERE id = v_notif_id;
    ELSIF p_status IN ('failed', 'rejected', 'undelivered') THEN
      -- Añadir a blacklist si fallo permanente
      INSERT INTO notifications.sms_blacklist (phone_number, reason, failure_count)
      VALUES (v_phone, 'DLR: ' || p_dlr_reason, 1)
      ON CONFLICT (phone_number) DO UPDATE SET
        failure_count = failure_count + 1,
        last_failure_at = NOW();
      
      -- Actualizar queue
      PERFORM notifications.mark_notification_failed(v_notif_id, 'DLR: ' || p_dlr_reason);
    END IF;
  END IF;
END;
$$;


--
-- Name: register_email_bounce(character varying, character varying, character varying); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.register_email_bounce(p_email character varying, p_bounce_type character varying, p_reason character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO notifications.email_bounce_rules (email, bounce_type, bounce_reason)
  VALUES (p_email, p_bounce_type, p_reason)
  ON CONFLICT (email) DO UPDATE SET
    bounce_count = email_bounce_rules.bounce_count + 1,
    last_bounce_at = NOW(),
    bounce_reason = EXCLUDED.bounce_reason,
    bounce_type = CASE
      WHEN EXCLUDED.bounce_type = 'permanent' THEN 'permanent'
      ELSE email_bounce_rules.bounce_type
    END;

  IF p_bounce_type = 'permanent' THEN
    UPDATE notifications.preferences
    SET enabled = FALSE
    WHERE channel = 'email'
    AND id_usuario = (SELECT id_usuario FROM notifications.queue
                   WHERE payload->>'recipient' = p_email
                   LIMIT 1);
  END IF;
END;
$$;


--
-- Name: register_webhook_delivery(uuid, uuid, text, integer, text, integer, integer); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.register_webhook_delivery(p_webhook_id uuid, p_notification_id uuid, p_payload text, p_response_status integer, p_response_body text, p_latency_ms integer, p_attempt integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_is_success BOOLEAN;
  v_next_retry TIMESTAMP;
  v_estado VARCHAR(20);
BEGIN
  v_is_success := p_response_status >= 200 AND p_response_status < 300;

  IF NOT v_is_success AND p_response_status NOT BETWEEN 400 AND 499 THEN
    v_next_retry := notifications.calculate_next_retry('webhook', p_attempt);
  END IF;

  IF v_is_success THEN
    v_estado := 'delivered';
  ELSIF p_response_status BETWEEN 400 AND 499 THEN
    v_estado := 'failed';
  ELSE
    v_estado := 'queued';  -- 'retrying' no está en el CHECK de webhook_deliveries
  END IF;

  INSERT INTO notifications.webhook_deliveries (
    id_suscriptor_webhook, id_notificacion, webhook_id, estado, attempt,
    request_body, response_status, response_body, latency_ms, next_retry_at
  ) VALUES (
    p_webhook_id, p_notification_id, gen_random_uuid()::text, v_estado, p_attempt,
    p_payload, p_response_status, p_response_body, p_latency_ms, v_next_retry
  );

  IF p_response_status BETWEEN 400 AND 499 THEN
    UPDATE notifications.webhooks_subscribers
    SET fail_count_24h = CASE
          WHEN fail_count_24h < 10 THEN fail_count_24h + 1 ELSE 10 END,
        last_error = p_response_body,
        last_attempt_at = NOW(),
        active = CASE WHEN fail_count_24h >= 9 THEN FALSE ELSE active END
    WHERE id = p_webhook_id;
  END IF;
END;
$$;


--
-- Name: reset_webhook_fail_count(); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.reset_webhook_fail_count() RETURNS TABLE(reset integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_reset INT;
BEGIN
  UPDATE notifications.webhooks_subscribers
  SET fail_count_24h = 0
  WHERE last_attempt_at < NOW() - INTERVAL '24 hours'
  AND fail_count_24h > 0;
  
  GET DIAGNOSTICS v_reset = ROW_COUNT;
  RETURN QUERY SELECT v_reset;
END;
$$;


--
-- Name: sanitize_email_headers(jsonb); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.sanitize_email_headers(p_headers jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_dangerous_headers TEXT[] := ARRAY['Content-Disposition', 'Content-Transfer-Encoding', 'MIME-Version'];
  v_header TEXT;
  v_result JSONB := '{}'::JSONB;
BEGIN
  FOR v_header IN
    SELECT jsonb_object_keys(p_headers)
  LOOP
    -- Bloquear headers peligrosos
    IF NOT (v_header = ANY(v_dangerous_headers)) AND v_header NOT LIKE 'X-%' THEN
      v_result := v_result || jsonb_build_object(v_header, p_headers->>v_header);
    END IF;
  END LOOP;
  RETURN v_result;
END;
$$;


--
-- Name: should_send_notification(uuid, character varying, character varying, boolean); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.should_send_notification(p_user_id uuid, p_channel character varying, p_event_category character varying, p_is_urgent boolean DEFAULT false) RETURNS TABLE(should_send boolean, reason character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'notifications', 'pg_temp'
    AS $$
DECLARE
  v_pref notifications.user_preferences;
  v_freq_count INT;
  v_current_hour INT;
  v_quiet_hours_active BOOLEAN;
  v_user_tz VARCHAR(50);
BEGIN
  -- Obtener preferencias
  SELECT * INTO v_pref
  FROM notifications.user_preferences
  WHERE id_usuario = p_user_id 
  AND channel = p_channel
  AND event_category = p_event_category;
  
  -- Si no hay preferencia específica, usar default
  IF v_pref IS NULL THEN
    v_pref.enabled := TRUE;
    v_pref.frequency_limit := 999;
    v_pref.allow_urgent_during_quiet := TRUE;
  END IF;
  
  -- 1. ¿Canal habilitado?
  IF NOT v_pref.enabled THEN
    RETURN QUERY SELECT FALSE, 'Channel disabled by user';
    RETURN;
  END IF;
  
  -- 2. ¿Excede frequency limit?
  SELECT COUNT(*) INTO v_freq_count
  FROM notifications.queue
  WHERE id_usuario = p_user_id
  AND channel = p_channel
  AND estado IN ('sent', 'retrying', 'pending')
  AND fecha_creacion > NOW() - INTERVAL '1 day'; -- Asumir límite diario por defecto
  
  IF v_pref.frequency_limit IS NOT NULL AND v_freq_count >= v_pref.frequency_limit THEN
    RETURN QUERY SELECT FALSE, 'Frequency limit exceeded';
    RETURN;
  END IF;
  
  -- 3. ¿En horario de silencio?
  IF v_pref.quiet_hours_enabled THEN
    v_user_tz := COALESCE(v_pref.quiet_hours_tz, 'UTC');
    v_current_hour := EXTRACT(HOUR FROM NOW() AT TIME ZONE v_user_tz);
    
    v_quiet_hours_active := 
      (EXTRACT(HOUR FROM v_pref.quiet_hours_start)::INT <= v_current_hour AND
       v_current_hour < EXTRACT(HOUR FROM v_pref.quiet_hours_end)::INT);
    
    IF v_quiet_hours_active AND NOT (p_is_urgent AND v_pref.allow_urgent_during_quiet) THEN
      RETURN QUERY SELECT FALSE, 'In quiet hours';
      RETURN;
    END IF;
  END IF;
  
  RETURN QUERY SELECT TRUE, NULL::VARCHAR;
END;
$$;


--
-- Name: update_user_preferences(uuid, jsonb[], uuid, inet); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.update_user_preferences(p_user_id uuid, p_updates jsonb[], p_changed_by uuid, p_ip_address inet) RETURNS TABLE(updated integer, errors integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_update JSONB;
  v_updated INT := 0;
  v_errors INT := 0;
  v_channel VARCHAR(20);
  v_event_category VARCHAR(50);
  v_field_name VARCHAR(100);
  v_new_value TEXT;
  v_old_value TEXT;
BEGIN
  FOREACH v_update IN ARRAY p_updates
  LOOP
    BEGIN
      v_channel := v_update->>'channel';
      v_event_category := v_update->>'event_category';
      v_field_name := v_update->>'field';
      v_new_value := v_update->>'value';

      SELECT CASE
        WHEN v_field_name = 'enabled' THEN enabled::TEXT
        WHEN v_field_name = 'frequency_limit' THEN frequency_limit::TEXT
        WHEN v_field_name = 'quiet_hours_start' THEN quiet_hours_start::TEXT
        ELSE NULL END
      INTO v_old_value
      FROM notifications.user_preferences
      WHERE id_usuario = p_user_id
      AND channel = v_channel
      AND (event_category = v_event_category OR (v_event_category IS NULL AND event_category IS NULL));

      UPDATE notifications.user_preferences
      SET
        enabled = CASE WHEN v_field_name = 'enabled' THEN v_new_value::BOOLEAN ELSE enabled END,
        frequency_limit = CASE WHEN v_field_name = 'frequency_limit' THEN v_new_value::INT ELSE frequency_limit END,
        quiet_hours_start = CASE WHEN v_field_name = 'quiet_hours_start' THEN v_new_value::TIME ELSE quiet_hours_start END,
        quiet_hours_end = CASE WHEN v_field_name = 'quiet_hours_end' THEN v_new_value::TIME ELSE quiet_hours_end END,
        quiet_hours_enabled = CASE WHEN v_field_name = 'quiet_hours_enabled' THEN v_new_value::BOOLEAN ELSE quiet_hours_enabled END,
        fecha_actualizacion = NOW()
      WHERE id_usuario = p_user_id
      AND channel = v_channel
      AND (event_category = v_event_category OR (v_event_category IS NULL AND event_category IS NULL));

      INSERT INTO notifications.preferences_audit_log (
        id_usuario, channel, event_category, field_name, old_value, new_value, changed_by, ip_address
      ) VALUES (
        p_user_id, v_channel, v_event_category, v_field_name, v_old_value, v_new_value, p_changed_by, p_ip_address
      );

      v_updated := v_updated + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;
  RETURN QUERY SELECT v_updated, v_errors;
END;
$$;


--
-- Name: validate_email(character varying); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.validate_email(p_email character varying) RETURNS TABLE(is_valid boolean, error_message text)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_pattern TEXT := '^[a-zA-Z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$';
  v_is_valid BOOLEAN;
  v_error_msg TEXT := '';
BEGIN
  -- RFC 5321 validation
  IF p_email IS NULL OR LENGTH(p_email) = 0 THEN
    v_is_valid := FALSE;
    v_error_msg := 'Email is required';
  ELSIF LENGTH(p_email) > 254 THEN
    v_is_valid := FALSE;
    v_error_msg := 'Email exceeds 254 characters';
  ELSIF NOT p_email ~* v_pattern THEN
    v_is_valid := FALSE;
    v_error_msg := 'Invalid email format';
  ELSIF EXISTS(SELECT 1 FROM notifications.email_bounce_rules WHERE email = p_email AND active = true AND bounce_type = 'permanent') THEN
    v_is_valid := FALSE;
    v_error_msg := 'Email in permanent bounce list';
  ELSE
    v_is_valid := TRUE;
  END IF;
  
  RETURN QUERY SELECT v_is_valid, v_error_msg;
END;
$_$;


--
-- Name: validate_phone_e164(character varying); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.validate_phone_e164(p_phone character varying) RETURNS TABLE(is_valid boolean, error_message text, country_code character varying, formatted_phone character varying)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_phone_cleaned VARCHAR(20);
  v_country_code VARCHAR(3);
  v_is_valid BOOLEAN := TRUE;
  v_error_msg TEXT := '';
BEGIN
  v_phone_cleaned := regexp_replace(p_phone, '[^0-9+]', '', 'g');
  IF v_phone_cleaned !~ '^\+[1-9]{1,3}[0-9]{4,14}$' THEN
    v_is_valid := FALSE;
    v_error_msg := 'Invalid E.164 format. Expected: +<country><number>';
  ELSIF EXISTS(SELECT 1 FROM notifications.sms_blacklist WHERE phone_number = v_phone_cleaned AND expiry_date IS NULL) THEN
    v_is_valid := FALSE;
    v_error_msg := 'Phone number is permanently blacklisted';
  ELSE
    v_country_code := substring(v_phone_cleaned FROM 2 FOR 3);
    IF (v_country_code::INT < 1 OR v_country_code::INT > 999) THEN
      v_is_valid := FALSE;
      v_error_msg := 'Invalid country code';
    END IF;
  END IF;
  RETURN QUERY SELECT v_is_valid, v_error_msg, v_country_code, v_phone_cleaned;
END;
$_$;


--
-- Name: validate_variables(jsonb, jsonb); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.validate_variables(p_required_vars jsonb, p_provided_vars jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_var TEXT;
BEGIN
  -- Verificar que todas las variables requeridas estén presentes
  FOR v_var IN SELECT jsonb_array_elements_text(p_required_vars)
  LOOP
    IF NOT p_provided_vars ? v_var THEN
      RETURN FALSE;
    END IF;
  END LOOP;
  RETURN TRUE;
END;
$$;


--
-- Name: validate_webhook_url(text); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION notifications.validate_webhook_url(p_url text) RETURNS TABLE(is_valid boolean, error_message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'notifications', 'pg_temp'
    AS $$
DECLARE
  v_is_valid BOOLEAN := TRUE;
  v_error_msg TEXT := '';
BEGIN
  IF p_url !~ '^https?:\/\/' THEN
    v_is_valid := FALSE;
    v_error_msg := 'URL must start with http:// or https://';
  ELSIF p_url !~ '^https:' AND COALESCE(current_setting('app.environment', true), 'development') = 'production' THEN
    v_is_valid := FALSE;
    v_error_msg := 'HTTPS required in production';
  ELSIF LENGTH(p_url) > 2000 THEN
    v_is_valid := FALSE;
    v_error_msg := 'URL too long (max 2000 chars)';
  ELSIF p_url LIKE 'http://localhost%' THEN
    v_is_valid := FALSE;
    v_error_msg := 'Localhost URLs not allowed';
  ELSIF p_url LIKE '%<script%' OR p_url LIKE '%javascript:%' THEN
    v_is_valid := FALSE;
    v_error_msg := 'Invalid URL format';
  END IF;
  RETURN QUERY SELECT v_is_valid, v_error_msg;
END;
$$;


