--
-- Name: _age_reflejar_ajuste_billetera(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._age_reflejar_ajuste_billetera(p_actor uuid, p_billetera uuid, p_dif numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $_$
BEGIN
  PERFORM 1 FROM pg_extension WHERE extname='age';
  IF NOT FOUND THEN RETURN; END IF;
  BEGIN
    PERFORM public.age_execute_safe(format($c$
      SELECT * FROM cypher('tienda_grafo', $q$
        MERGE (u:Usuario {id:'%s'})
        MERGE (b:Billetera {id:'%s'})
        CREATE (u)-[:AJUSTO_SALDO {dif:%s, ts:'%s'}]->(:EventoModeracion)-[:DESTINO]->(b)
      $q$) AS (v agtype)$c$, p_actor, p_billetera, p_dif, now()));
  EXCEPTION WHEN OTHERS THEN NULL; END;
END $_$;


--
-- Name: _age_reflejar_moderacion(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._age_reflejar_moderacion(p_actor uuid, p_producto uuid, p_accion text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $_$
BEGIN
  PERFORM 1 FROM pg_extension WHERE extname='age';
  IF NOT FOUND THEN RETURN; END IF;
  BEGIN
    PERFORM public.age_execute_safe(format($c$
      SELECT * FROM cypher('tienda_grafo', $q$
        MERGE (u:Usuario {id:'%s'})
        MERGE (p:Producto {id:'%s'})
        CREATE (u)-[:MODERO {accion:'%s', ts:'%s'}]->(:EventoModeracion)-[:AFECTO]->(p)
      $q$) AS (v agtype)$c$, p_actor, p_producto, p_accion, now()));
  EXCEPTION WHEN OTHERS THEN NULL; END;
END $_$;


--
-- Name: add_item_to_purchase_plan(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_item_to_purchase_plan(p_plan_id uuid, p_product_id uuid, p_id_vendedor uuid, p_quantity integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
    v_actor_id UUID;
    v_item_id  UUID;
BEGIN
    v_actor_id := auth.jwt_user_id_safe();
    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'ACTOR_NO_AUTENTICADO' USING ERRCODE = '28000';
    END IF;

    IF p_quantity IS NULL OR p_quantity <= 0 THEN
        RAISE EXCEPTION 'CANTIDAD_INVALIDA' USING ERRCODE = '22023';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.buyer_purchase_plans
        WHERE id = p_plan_id
          AND id_comprador = v_actor_id
          AND fecha_eliminacion IS NULL
    ) THEN
        RAISE EXCEPTION 'PLAN_NO_ENCONTRADO_O_NO_AUTORIZADO' USING ERRCODE = '42501';
    END IF;

    -- Idempotencia (R-35): mismo (plan, product, seller) ⇒ suma cantidad
    INSERT INTO public.buyer_purchase_plan_items (id_plan, id_producto, id_vendedor, quantity)
    VALUES (p_plan_id, p_product_id, p_id_vendedor, p_quantity)
    RETURNING id INTO v_item_id;

    RETURN jsonb_build_object(
        'status','OK',
        'item_id',v_item_id,
        'plan_id',p_plan_id,
        'product_id',p_product_id,
        'id_vendedor',p_id_vendedor,
        'quantity',p_quantity
    );

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'add_item_to_purchase_plan_ERROR: % (SQLSTATE=%)', SQLERRM, SQLSTATE;
END;
$$;


--
-- Name: admin_alerta_drilldown(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_alerta_drilldown(p_alerta_id uuid, p_hops integer DEFAULT 2) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'ag_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid;
  v_alerta record;
  v_age_json jsonb;
  v_evidence jsonb;
BEGIN
  v_actor := app.jwt_user_id_safe();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'no_auth' USING ERRCODE='28000'; END IF;
  IF NOT (public.is_admin_activo() OR public.is_superadmin_activo()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;
  IF p_alerta_id IS NULL THEN RAISE EXCEPTION 'alerta_id_null' USING ERRCODE='22004'; END IF;
  IF p_hops < 1 OR p_hops > 3 THEN p_hops := 2; END IF;

  -- 1) Datos SQL de la alerta (FOR SHARE para consistencia lectura)
  SELECT id, tipo, nivel_riesgo, referencia_tipo, referencia_id, descripcion, payload
  INTO v_alerta
  FROM public.admin_alerts
  WHERE id = p_alerta_id AND oculto_en_dash = false
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'alerta_no_encontrada' USING ERRCODE='P0002';
  END IF;

  -- 2) Evidencia estructural SQL (contexto)
  v_evidence := jsonb_build_object(
    'alerta', to_jsonb(v_alerta),
    'related_audit', COALESCE((
      SELECT jsonb_agg(to_jsonb(al.*) ORDER BY al.created_at DESC)
      FROM auth.auditoria al
      WHERE al.tipo_objetivo = v_alerta.referencia_tipo
        AND al.id_objetivo = v_alerta.referencia_id::text
      LIMIT 20
    ), '[]'::jsonb)
  );

  -- 3) Contexto AGE (degradación elegante)
  BEGIN
    PERFORM 1 FROM pg_extension WHERE extname='age';
    EXECUTE format($age$
      LOAD 'age'; SET search_path = ag_catalog, "$user", public;
      SELECT jsonb_agg(v) FROM (
        SELECT * FROM cypher('smtp_posix_graph', $q$
          MATCH (n {referencia_id: '%s'})-[r*1..%s]-(m)
          RETURN n, r, m LIMIT 100
        $q$) AS (n agtype, r agtype, m agtype)
      ) t
    $age$, v_alerta.referencia_id::text, p_hops)
    INTO v_age_json;
  EXCEPTION WHEN OTHERS THEN
    v_age_json := jsonb_build_object('age_available', false, 'sqlstate', SQLSTATE);
  END;

  -- 4) Auditoría (LEDGER WORM)
  INSERT INTO auth.auditoria(id_actor, action, tipo_objetivo, id_objetivo, metadata)
  VALUES (v_actor, 'ALERT_DRILLDOWN', 'alerta_admin', p_alerta_id::text,
          jsonb_build_object('hops', p_hops, 'entity_type', v_alerta.referencia_tipo));

  RETURN jsonb_build_object(
    'evidence', v_evidence,
    'graph_context', COALESCE(v_age_json, jsonb_build_object('age_available', false))
  );
END;
$_$;


--
-- Name: admin_alertas_consola_listar(text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_alertas_consola_listar(p_estado text DEFAULT NULL::text, p_nivel_riesgo text DEFAULT NULL::text, p_entity_type text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, tipo_alerta text, nivel_riesgo text, score_riesgo numeric, estado text, tipo_entidad text, id_entidad uuid, fecha_creacion timestamp with time zone, descripcion_breve text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_actor uuid;
BEGIN
  -- Autenticación
  v_actor := app.jwt_user_id_safe();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'no_auth' USING ERRCODE='28000';
  END IF;
  IF NOT (public.is_admin_activo() OR public.is_superadmin_activo()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;

  -- Validación de entrada
  IF p_limit IS NULL OR p_limit <= 0 OR p_limit > 500 THEN p_limit := 50; END IF;
  IF p_offset IS NULL OR p_offset < 0 THEN p_offset := 0; END IF;

  RETURN QUERY
    SELECT v.id, v.tipo_alerta, v.nivel_riesgo, v.score_riesgo, v.estado,
           v.tipo_entidad, v.id_entidad, v.fecha_creacion, v.descripcion_breve
    FROM public.v_alertas_consola v
    WHERE (p_estado IS NULL OR v.estado = p_estado)
      AND (p_nivel_riesgo IS NULL OR v.nivel_riesgo = p_nivel_riesgo)
      AND (p_entity_type IS NULL OR v.tipo_entidad = p_entity_type)
    ORDER BY v.fecha_creacion DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: admin_apply_k_anonymity_heatmap(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_apply_k_anonymity_heatmap(p_min_count bigint DEFAULT 3) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'pg_temp'
    AS $$
DECLARE
  v_actor  uuid := app.jwt_user_id_safe();
  v_hidden bigint := 0;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
  END IF;
  IF p_min_count < 1 THEN
    RAISE EXCEPTION 'p_min_count debe ser >= 1' USING ERRCODE = '22003';
  END IF;

  -- K-anonimidad: alertas en zonas con incidentes < umbral k -> ocultas.
  UPDATE public.admin_alerts a
     SET oculto_en_dash = true,
         updated_at    = now()
   WHERE a.oculto_en_dash = false
     AND a.payload ? 'zone_lat'
     AND EXISTS (
       SELECT 1
         FROM app.v_risk_heatmap_projection v
        WHERE round((a.payload->>'zone_lat')::numeric, 3) = round(v.zone_lat::numeric, 3)
          AND round((a.payload->>'zone_lng')::numeric, 3) = round(v.zone_lng::numeric, 3)
          AND v.incident_count < p_min_count
     );
  GET DIAGNOSTICS v_hidden = ROW_COUNT;

  RAISE NOTICE 'k-anonimidad aplicada: % alertas ocultas (umbral k=%)', v_hidden, p_min_count;
END;
$$;


--
-- Name: admin_audit_listar(uuid, text, text, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_audit_listar(p_actor_id uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, p_target_type text DEFAULT NULL::text, p_desde timestamp with time zone DEFAULT NULL::timestamp with time zone, p_hasta timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, id_actor uuid, action text, tipo_objetivo text, id_objetivo text, metadata_safe jsonb, fecha_creacion timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_actor uuid;
BEGIN
  v_actor := app.jwt_user_id_safe();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'no_auth' USING ERRCODE='28000'; END IF;
  IF NOT (public.is_admin_activo() OR public.is_superadmin_activo()
          OR COALESCE(app.jwt_role_safe(),'') = 'auditor_role') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;

  IF p_limit IS NULL OR p_limit <= 0 OR p_limit > 1000 THEN p_limit := 100; END IF;
  IF p_offset IS NULL OR p_offset < 0 THEN p_offset := 0; END IF;

  RETURN QUERY
    SELECT v.id, v.id_actor, v.action, v.tipo_objetivo, v.id_objetivo,
           v.metadata_safe, v.fecha_creacion
    FROM public.v_audit_tablero v
    WHERE (p_actor_id IS NULL OR v.id_actor = p_actor_id)
      AND (p_action IS NULL OR v.action = p_action)
      AND (p_target_type IS NULL OR v.tipo_objetivo = p_target_type)
      AND (p_desde IS NULL OR v.fecha_creacion >= p_desde)
      AND (p_hasta IS NULL OR v.fecha_creacion <= p_hasta)
    ORDER BY v.fecha_creacion DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: admin_change_user_tier(uuid, text, text, numeric, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_change_user_tier(p_id_usuario uuid, p_nuevo_tier text, p_reason text DEFAULT NULL::text, p_monto numeric DEFAULT 0, p_metodo text DEFAULT NULL::text, p_referencia text DEFAULT NULL::text, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
    v_meta jsonb;
    v_res jsonb;
BEGIN
    IF NOT auth.is_db_admin() THEN
        RAISE EXCEPTION 'Requiere rol db_admin' USING ERRCODE = '42501';
    END IF;

    v_meta := jsonb_build_object(
        'inversion', jsonb_build_object(
            'monto', p_monto, 'metodo', p_metodo, 'referencia', p_referencia),
        'tier_anterior', auth.resolve_effective_tier(p_id_usuario, now()));

    v_res := auth.admin_set_user_membership(
        p_id_usuario, p_nuevo_tier, now(), p_ends_at, p_reason, v_meta);

    RETURN v_res || jsonb_build_object('referencia', p_referencia);
END;
$$;


--
-- Name: admin_confirm_fraud_and_apply_action(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_confirm_fraud_and_apply_action(p_case_id uuid, p_action text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := app.jwt_user_id_safe();
  v_case  public.investigation_cases%ROWTYPE;
  v_res   jsonb := '{}'::jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
  END IF;
  IF p_action NOT IN ('suspend_entity','intervene_network','notify_only','none') THEN
    RAISE EXCEPTION 'action inválida: %', p_action USING ERRCODE = '22P02';
  END IF;

  SELECT * INTO v_case FROM public.investigation_cases WHERE id_caso = p_case_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Caso % no encontrado', p_case_id USING ERRCODE = '02000';
  END IF;
  IF v_case.estado <> 'open' THEN
    RAISE EXCEPTION 'Caso % ya cerrado (status=%)', p_case_id, v_case.estado USING ERRCODE = '55000';
  END IF;

  UPDATE public.investigation_cases
     SET estado         = 'confirmed',
         confirmed_by   = v_actor,
         fecha_confirmacion   = now(),
         applied_action = p_action,
         applied_at     = now()
   WHERE id_caso = p_case_id;

  IF p_action = 'suspend_entity' THEN
    v_res := public.admin_suspend_entity(v_case.id_entidad, v_case.entity_kind,
                                         'confirmed_by_case:'||v_case.id_caso::text,
                                         v_case.id_caso, v_case.evidence);
  ELSIF p_action = 'intervene_network' THEN
    v_res := public.admin_intervenir_red_sospechosa(v_case.id_entidad, v_case.id_caso, 1, 20);
  END IF;

  INSERT INTO auth.auditoria(id_actor, action, target_kind, id_objetivo, payload)
  VALUES (v_actor, 'fraud_confirmed', v_case.entity_kind, v_case.id_entidad,
          jsonb_build_object('case_id', p_case_id, 'action', p_action, 'sub_result', v_res));

  RETURN jsonb_build_object('success', true, 'case_id', p_case_id, 'action', p_action, 'sub_result', v_res,
                            'timestamp_utc', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
END;
$$;


--
-- Name: admin_create_administrator(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_create_administrator(p_email text, p_role text DEFAULT 'Administrador'::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor_id UUID := public.get_app_actor_id();  -- R-30: wrapper canónico
  v_new_id   UUID := gen_random_uuid();
BEGIN
  IF NOT public.is_superadmin_activo() THEN
    RETURN jsonb_build_object('status','forbidden');
  END IF;

  IF EXISTS (SELECT 1 FROM auth.users WHERE email = p_email AND fecha_eliminacion IS NULL) THEN
    RETURN jsonb_build_object('status','already_exists','email',p_email);
  END IF;

  INSERT INTO auth.users (id, email, is_active, fecha_eliminacion, role, created_by)
  VALUES (v_new_id, p_email, true, NULL, p_role, v_actor_id);

  INSERT INTO public.admin_role_lifecycle_audit
    (id_admin, id_actor, tipo_evento, role_new, reason, metadata)
  VALUES (v_new_id, v_actor_id, 'ADMIN_CREATED', p_role, p_reason,
          jsonb_build_object('email', p_email));

  INSERT INTO auth.auditoria
    (id_actor, action, tipo_objetivo, id_objetivo, metadata, fecha_creacion)
  VALUES (v_actor_id, 'ADMIN_CREATE', 'auth.users', v_new_id::text,
    jsonb_build_object('email', p_email, 'role', p_role, 'reason', p_reason),
    now());

  RETURN jsonb_build_object(
    'status',    'ok',
    'admin_id',  v_new_id,
    'email',     p_email,
    'role',      p_role,
    'actor_id',  v_actor_id
  );
END;
$$;


--
-- Name: admin_demand_density_grid(public.geography, timestamp with time zone, timestamp with time zone, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_demand_density_grid(p_bbox public.geography, p_from timestamp with time zone, p_to timestamp with time zone, p_cell_size numeric DEFAULT 0.01) RETURNS TABLE(cell_geom public.geometry, cell_centroid public.geography, demand_count bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $_$
BEGIN
    -- Guardia estructural: schema V4 no tiene fuente confirmada de demanda geoespacial.
    -- Cuando CU-ADMIN-EVT-DEMANDA-GEO-001 exponga public.v_admin_demand_points, este bloque
    -- se reemplaza por la implementación análoga a admin_supply_density_grid.
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.views
        WHERE table_schema = 'public'
          AND table_name = 'v_admin_demand_points'
    ) THEN
        RAISE EXCEPTION
            'DEMANDA_NO_DISPONIBLE_SIN_FUENTE_GEOESPACIAL_CONFIRMADA: '
            'implementar CU-ADMIN-EVT-DEMANDA-GEO-001 antes de habilitar capa demanda.'
            USING ERRCODE = 'P0001';
    END IF;

    -- Implementación futura (ejecutable sólo cuando exista v_admin_demand_points):
    RETURN QUERY
    EXECUTE $q$
        WITH filtered AS (
            SELECT dp.punto::geometry AS geom_pt
            FROM public.v_admin_demand_points dp
            WHERE dp.fecha_creacion >= $1
              AND dp.fecha_creacion <= $2
              AND ST_Intersects(dp.punto, $3)
        ),
        snapped AS (
            SELECT ST_SnapToGrid(geom_pt, $4, $4) AS cell_pt
            FROM filtered
        ),
        aggregated AS (
            SELECT cell_pt, COUNT(*)::bigint AS demand_count
            FROM snapped
            GROUP BY cell_pt
        )
        SELECT
            ST_SetSRID(ST_MakeEnvelope(
                ST_X(cell_pt), ST_Y(cell_pt),
                ST_X(cell_pt)+$4, ST_Y(cell_pt)+$4, 4326), 4326)          AS cell_geom,
            ST_SetSRID(ST_MakePoint(
                ST_X(cell_pt)+$4/2.0, ST_Y(cell_pt)+$4/2.0), 4326)::geography AS cell_centroid,
            demand_count
        FROM aggregated
    $q$ USING p_from, p_to, p_bbox, p_cell_size;
END;
$_$;


--
-- Name: admin_densidad_listar_hotspots(integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_densidad_listar_hotspots(p_limit integer DEFAULT 50, p_solo_anomalias boolean DEFAULT false) RETURNS TABLE(id uuid, window_start timestamp with time zone, window_end timestamp with time zone, geohash text, lat double precision, lon double precision, order_count integer, unique_vendors integer, unique_buyers integer, total numeric, density_score numeric, is_anomaly boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_actor uuid;
BEGIN
  v_actor := app.jwt_user_id_safe();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'no_auth' USING ERRCODE='28000'; END IF;
  IF NOT (public.is_admin_activo() OR public.is_superadmin_activo()
          OR COALESCE(app.jwt_role_safe(),'')='auditor_role') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;
  IF p_limit IS NULL OR p_limit <= 0 OR p_limit > 500 THEN p_limit := 50; END IF;

  RETURN QUERY
    SELECT v.id, v.window_start, v.window_end, v.geohash, v.lat, v.lon,
           v.order_count, v.unique_vendors, v.unique_buyers, v.total,
           v.density_score, v.is_anomaly
    FROM public.v_density_hotspots v
    WHERE (NOT p_solo_anomalias OR v.is_anomaly = true)
    ORDER BY COALESCE(v.density_score, 0) DESC, v.window_end DESC
    LIMIT p_limit;
END;
$$;


--
-- Name: admin_densidad_snapshot(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_densidad_snapshot(p_window_hours integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_ws timestamptz;
  v_we timestamptz;
  v_inserted int := 0;
  v_anomalies int := 0;
BEGIN
  v_actor := app.jwt_user_id_safe();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'no_auth' USING ERRCODE='28000'; END IF;
  IF NOT (public.is_admin_activo() OR public.is_superadmin_activo()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;
  IF p_window_hours IS NULL OR p_window_hours <= 0 OR p_window_hours > 24 THEN
    p_window_hours := 1;
  END IF;

  v_we := date_trunc('hour', now());
  v_ws := v_we - (p_window_hours || ' hours')::interval;

  -- Agregación por geohash 6 (usa PostGIS ST_GeoHash)
  WITH agg AS (
    SELECT
      ST_GeoHash(ogs.location::geometry, 6) AS gh,
      ST_Centroid(ST_Collect(ogs.location::geometry))::geography AS centroid,
      count(*) AS oc,
      count(DISTINCT o.vendor_id) AS uv,
      count(DISTINCT o.id_comprador) AS ub,
      COALESCE(sum(o.total), 0) AS ta
    FROM public.order_geo_snapshots ogs
    JOIN auth.ordenes o ON o.id = ogs.id_orden
    WHERE ogs.created_at >= v_ws AND ogs.created_at < v_we
      AND ogs.location IS NOT NULL
    GROUP BY 1
    HAVING count(*) >= 3
  ), stats AS (
    -- Estadísticas históricas (últimos 30 días excluyendo ventana actual)
    SELECT geohash, avg(order_count)::numeric AS mu, stddev_samp(order_count)::numeric AS sigma
    FROM public.market_density_snapshots
    WHERE window_end BETWEEN now() - interval '30 days' AND v_ws
    GROUP BY geohash
  ), scored AS (
    SELECT a.gh, a.centroid, a.oc, a.uv, a.ub, a.ta,
           CASE
             WHEN s.sigma IS NULL OR s.sigma = 0 THEN NULL
             ELSE round((a.oc - s.mu) / s.sigma, 2)
           END AS z_score
    FROM agg a
    LEFT JOIN stats s ON s.geohash = a.gh
  )
  INSERT INTO public.market_density_snapshots(
    window_start, window_end, geohash, centroid,
    order_count, unique_vendors, unique_buyers, total,
    density_score, is_anomaly
  )
  SELECT v_ws, v_we, gh, centroid, oc, uv, ub, ta, z_score,
         COALESCE(z_score, 0) > 3.0
  FROM scored;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  -- Generar alertas para anomalías nuevas
  INSERT INTO public.admin_alerts(tipo, descripcion, nivel_riesgo, score_riesgo,
                                    referencia_tipo, referencia_id, estado, payload)
  SELECT 'DENSITY_ANOMALY',
         'Hotspot geoespacial detectado en geohash '||geohash||' (z='||density_score||')',
         CASE WHEN density_score > 5 THEN 'alto'
              WHEN density_score > 3 THEN 'medio'
              ELSE 'bajo' END,
         LEAST(density_score * 10, 100),
         'geohash', NULL, 'open',
         jsonb_build_object('geohash', geohash,
                            'window_start', window_start,
                            'window_end', window_end,
                            'order_count', order_count,
                            'z_score', density_score)
  FROM public.market_density_snapshots
  WHERE is_anomaly = true
    AND window_end = v_we;
  GET DIAGNOSTICS v_anomalies = ROW_COUNT;

  INSERT INTO auth.auditoria(id_actor, action, tipo_objetivo, id_objetivo, metadata)
  VALUES (v_actor, 'DENSITY_SNAPSHOT', 'market_density_snapshots', NULL,
          jsonb_build_object('window_start', v_ws, 'window_end', v_we,
                             'cells', v_inserted, 'anomalies', v_anomalies));

  RETURN jsonb_build_object('ok', true, 'window_start', v_ws, 'window_end', v_we,
                            'cells', v_inserted, 'anomalies', v_anomalies);

EXCEPTION WHEN OTHERS THEN
  INSERT INTO auth.auditoria(id_actor, action, tipo_objetivo, id_objetivo, metadata)
  VALUES (v_actor, 'DENSITY_SNAPSHOT_ERROR', 'market_density_snapshots', NULL,
          jsonb_build_object('sqlstate', SQLSTATE, 'sqlerrm', SQLERRM));
  RAISE;
END;
$$;


--
-- Name: admin_deteccion_cercania_sospechosa(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_deteccion_cercania_sospechosa(p_umbral_metros integer DEFAULT 5, p_ventana_min integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := app.jwt_user_id_safe();
  v_inserted int := 0;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
  END IF;
  IF p_umbral_metros NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'umbral fuera de rango' USING ERRCODE = '22003';
  END IF;

  -- Distancia geodésica entre comprador y vendedor al momento de la compra
  WITH candidatos AS (
    SELECT DISTINCT ON (o.id_orden)
           o.id_orden,
           o.id_comprador, o.id_vendedor,
           ST_Distance(ulb.last_transaction_geom::geography,
                       uls.last_transaction_geom::geography) AS dist_m,
           o.fecha_creacion
    FROM auth.ordenes o
    JOIN public.user_locations ulb ON ulb.id_usuario::uuid = o.id_comprador
    JOIN public.user_locations uls ON uls.id_usuario = o.id_vendedor
    WHERE o.fecha_creacion > now() - (p_ventana_min || ' minutes')::interval
      AND ulb.last_transaction_geom IS NOT NULL
      AND uls.last_transaction_geom IS NOT NULL
    ORDER BY o.id_orden, ulb.fecha_captura DESC, uls.fecha_captura DESC
  )
  INSERT INTO public.fraud_alerts
    (tipo_alerta, primary_entity_id, primary_entity_kind, related_entity_ids, severity, evidence, score)
  SELECT
    'proximity_suspicious',
    c.id_comprador, 'user',
    ARRAY[c.id_vendedor],
    CASE WHEN c.dist_m < 1 THEN 'critical'
         WHEN c.dist_m < p_umbral_metros THEN 'high'
         ELSE 'medium' END,
    jsonb_build_object('order_id', c.id_orden, 'distance_m', c.dist_m,
                       'ventana_min', p_ventana_min),
    LEAST(1.0, GREATEST(0.5, 1.0 - c.dist_m / GREATEST(p_umbral_metros,1)))::numeric
  FROM candidatos c
  WHERE c.dist_m < p_umbral_metros
    AND NOT EXISTS (   -- idempotencia: no duplicar alerta para misma order
      SELECT 1 FROM public.fraud_alerts fa
       WHERE fa.tipo_alerta = 'proximity_suspicious'
         AND fa.evidence ->> 'order_id' = c.id_orden::text
    );
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  INSERT INTO auth.auditoria(id_actor, action, target_kind, id_objetivo, payload)
  VALUES (v_actor, 'proximity_scan', 'system', NULL,
          jsonb_build_object('umbral_m', p_umbral_metros, 'ventana_min', p_ventana_min,
                             'alertas_generadas', v_inserted));

  RETURN jsonb_build_object('success', true, 'alertas_generadas', v_inserted,
                            'timestamp_utc', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'));
END;
$$;


--
-- Name: admin_deteccion_zonas_desbalanceadas(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_deteccion_zonas_desbalanceadas(p_periodo_dias integer DEFAULT 7) RETURNS TABLE(id_zona uuid, name text, oferta_count bigint, demanda_count bigint, ratio numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_actor uuid := app.jwt_user_id_safe();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
  END IF;
  IF p_periodo_dias NOT BETWEEN 1 AND 90 THEN
    RAISE EXCEPTION 'periodo_dias fuera de rango' USING ERRCODE = '22003';
  END IF;

  RETURN QUERY
    WITH ofer AS (
      SELECT z.id_zona, count(*)::bigint AS n_vendedores
      FROM public.geo_zones z
      LEFT JOIN auth.ubicaciones l ON ST_Within(l.geom, z.geom) AND l.fecha_eliminacion IS NULL
      WHERE z.is_active AND z.fecha_eliminacion IS NULL
      GROUP BY z.id_zona
    ),
    dem AS (
      SELECT z.id_zona, count(*)::bigint AS n_ordenes
      FROM public.geo_zones z
      LEFT JOIN auth.ordenes o
             ON o.buyer_geom IS NOT NULL
            AND ST_Within(o.buyer_geom, z.geom)
            AND o.fecha_creacion > now() - (p_periodo_dias || ' days')::interval
      WHERE z.is_active AND z.fecha_eliminacion IS NULL
      GROUP BY z.id_zona
    )
    SELECT z.id_zona, z.name, o.n_vendedores, d.n_ordenes,
           CASE WHEN d.n_ordenes = 0 THEN NULL
                ELSE ROUND(o.n_vendedores::numeric / d.n_ordenes, 3) END
      FROM public.geo_zones z
      JOIN ofer o USING(id_zona)
      JOIN dem  d USING(id_zona)
     WHERE (o.n_vendedores > 0 OR d.n_ordenes > 0)
     ORDER BY (COALESCE(o.n_vendedores,0) + COALESCE(d.n_ordenes,0)) DESC;
END;
$$;


--
-- Name: admin_detect_orphan_administrators(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_detect_orphan_administrators() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_rows JSONB := '[]'::jsonb;
BEGIN
  IF NOT (public.is_superadmin_activo()
          OR app.jwt_role_safe() = 'auditor_role') THEN
    RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT
      u.id          AS id_admin,
      u.email       AS admin_email,
      u.created_by  AS creator_id,
      c.email       AS creator_email,
      c.fecha_eliminacion  AS creator_deleted_at
    FROM auth.users u
    JOIN auth.users c ON u.created_by = c.id
    WHERE COALESCE(u.is_active, false) = true
      AND u.fecha_eliminacion IS NULL
      AND COALESCE(c.is_active, false) = false
      AND c.fecha_eliminacion IS NOT NULL
  ) t;

  RETURN jsonb_build_object('status','ok','items',v_rows);
END;
$$;


--
-- Name: admin_generar_reporte_riesgo_medianoche(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_generar_reporte_riesgo_medianoche(p_fecha date DEFAULT (CURRENT_DATE - '1 day'::interval)) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
    v_report_id uuid;
    v_payload text;
    v_hash text;
BEGIN
    -- Validación fecha (R-37)
    IF p_fecha IS NULL OR p_fecha > current_date THEN
        RAISE EXCEPTION 'Fecha inválida para reporte'
            USING ERRCODE = '23502';
    END IF;

    -- Construcción payload (R-30)
    SELECT jsonb_agg(subq) INTO v_payload
    FROM (
        -- Datos de alertas del día
        SELECT 'alerts' AS section, count(*) AS count, 
               jsonb_agg(type) AS types
        FROM public.fraud_alerts
        WHERE fecha_creacion::date = p_fecha
        
        UNION ALL
        
        -- Resumen casos investigación
        SELECT 'investigations' AS section, count(*) AS count,
               jsonb_agg(estado) AS statuses
        FROM public.investigation_cases
        WHERE fecha_creacion::date = p_fecha
    ) subq;

    -- Generación hash SHA-256 (R-46)
    v_hash := encode(digest(v_payload, 'sha256'), 'hex');

    -- Inserción WORM (R-38)
    INSERT INTO public.reportes_seguridad (
        fecha_reporte, payload, hash_evento, generado_por
    ) VALUES (
        p_fecha, v_payload::jsonb, v_hash, public.get_app_actor_id()
    ) RETURNING id INTO v_report_id;

    -- Auditoría (R-38)
    PERFORM public.log_audit_event(
        'reporte_riesgo_generado',
        jsonb_build_object('report_id', v_report_id, 'fecha', p_fecha),
        'admin_generar_reporte_riesgo_medianoche'
    );

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object('report_id', v_report_id, 'hash', v_hash),
        'timestamp_utc', (now() at time zone 'utc')
    );
END;
$$;


--
-- Name: admin_get_administrator_lifecycle_timeline(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_administrator_lifecycle_timeline(p_admin_id uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_events JSONB := '[]'::jsonb;
BEGIN
  IF NOT (public.is_superadmin_activo()
          OR app.jwt_role_safe() = 'auditor_role') THEN
    RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO';
  END IF;

  WITH timeline AS (
    SELECT tipo_evento,
           fecha_creacion AS event_at,
           'admin_role_lifecycle_audit'::text AS source,
           to_jsonb(a.*) AS payload
    FROM public.admin_role_lifecycle_audit a
    WHERE a.id_admin  = p_admin_id
      AND a.fecha_eliminacion IS NULL

    UNION ALL

    SELECT action AS tipo_evento,
           fecha_creacion AS event_at,
           'audit_logs'::text AS source,
           to_jsonb(l.*) AS payload
    FROM auth.auditoria l
    WHERE l.tipo_objetivo IN ('auth.users','users')  -- columna canónica
      AND l.id_objetivo = p_admin_id::text
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
  INTO v_events
  FROM (
    SELECT * FROM timeline
    ORDER BY event_at DESC
    LIMIT p_limit OFFSET p_offset
  ) t;

  RETURN jsonb_build_object(
    'status',   'ok',
    'admin_id', p_admin_id,
    'events',   v_events
  );
END;
$$;


--
-- Name: admin_get_administrators_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_administrators_list() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_rows JSONB := '[]'::jsonb;
BEGIN
  IF NOT (public.is_superadmin_activo()
          OR app.jwt_role_safe() = 'auditor_role') THEN
    RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT
      u.id,
      u.email,
      u.role,
      u.is_active,
      u.fecha_eliminacion,
      u.deleted_reason,
      u.created_by,
      c.email AS creator_email
    FROM auth.users u
    LEFT JOIN auth.users c ON u.created_by = c.id
    WHERE u.role IN ('SuperAdmin','Administrador','Moderador')
    ORDER BY u.email
  ) t;

  RETURN jsonb_build_object('status','ok','items',v_rows);
END;
$$;


--
-- Name: admin_get_audit_feed(timestamp with time zone, timestamp with time zone, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_audit_feed(p_desde timestamp with time zone DEFAULT (now() - '30 days'::interval), p_hasta timestamp with time zone DEFAULT now(), p_action text DEFAULT NULL::text, p_limit integer DEFAULT 200) RETURNS TABLE(id bigint, action text, id_actor uuid, target_kind text, id_objetivo text, reason text, before_state jsonb, after_state jsonb, fecha_creacion timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
  SELECT l.id, l.action, l.id_actor, l.target_kind, l.id_objetivo,
         l.reason, l.before_state, l.after_state, l.fecha_creacion
    FROM auth.auditoria l
   WHERE l.fecha_creacion BETWEEN p_desde AND p_hasta
     AND (p_action IS NULL OR l.action = p_action)
   ORDER BY l.fecha_creacion DESC
   LIMIT GREATEST(p_limit, 0);
$$;


--
-- Name: admin_get_detection_config(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_detection_config() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_rol  TEXT;
  v_rows JSONB;
BEGIN
  v_rol := app.jwt_role_safe();
  IF v_rol NOT IN ('administrador_role','superadmin_role','auditor_role') THEN
    RETURN jsonb_build_object(
      'status',  'error',
      'message', 'Acceso denegado: se requiere rol administrador, superadmin o auditor'
    );
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'config_key',   config_key,
        'config_scope', config_scope,
        'config_value', config_value,
        'description',  description,
        'is_active',    is_active,
        'updated_at',   fecha_actualizacion
      ) ORDER BY config_key
    ),
    '[]'::jsonb
  )
  INTO v_rows
  FROM public.detection_configurations
  WHERE fecha_eliminacion IS NULL;

  RETURN jsonb_build_object('status', 'ok', 'items', v_rows);

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'status',   'error',
    'message',  SQLERRM,
    'sqlstate', SQLSTATE
  );
END;
$$;


--
-- Name: admin_get_ecosystem_health_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_ecosystem_health_summary() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'alertas_abiertas', (SELECT COUNT(*) FROM public.admin_alerts WHERE estado='ABIERTA' AND oculto_en_dash=FALSE),
    'alertas_criticas', (SELECT COUNT(*) FROM public.admin_alerts WHERE severidad='CRITICAL' AND estado='ABIERTA'),
    'ultimas_24h',      (SELECT COUNT(*) FROM public.admin_alerts WHERE created_at >= NOW() - INTERVAL '24 hours'),
    'has_postgis',      EXISTS(SELECT 1 FROM pg_extension WHERE extname='postgis'),
    'has_age',          EXISTS(SELECT 1 FROM pg_extension WHERE extname='age')
  );
$$;


--
-- Name: admin_get_entity_timeline(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_entity_timeline(p_entity_type text, p_entity_id text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_rol         TEXT;
  v_events      JSONB := '[]'::jsonb;
  v_resolutions JSONB := '[]'::jsonb;
  v_audits      JSONB := '[]'::jsonb;
  v_transitions JSONB := '[]'::jsonb;
BEGIN
  v_rol := app.jwt_role_safe();
  IF v_rol NOT IN ('administrador_role','superadmin_role','auditor_role') THEN
    RETURN jsonb_build_object(
      'status',  'error',
      'message', 'Acceso denegado: se requiere rol administrador, superadmin o auditor'
    );
  END IF;

  -- Rama 1: admin_case_resolutions
  BEGIN
    SELECT COALESCE(
      jsonb_agg(jsonb_build_object(
        'event_type', 'admin_resolution',
        'event_at',   r.fecha_creacion,
        'source',     'admin_case_resolutions',
        'payload',    to_jsonb(r.*)
      ) ORDER BY r.fecha_creacion DESC),
      '[]'::jsonb
    )
    INTO v_resolutions
    FROM public.admin_case_resolutions r
    WHERE r.tipo_entidad = p_entity_type
      AND r.id_entidad   = p_entity_id
      AND r.fecha_eliminacion IS NULL;
  EXCEPTION WHEN undefined_table THEN
    v_resolutions := '[]'::jsonb;
  END;

  -- Rama 2: audit_logs (definida en CU-041/042)
  BEGIN
    SELECT COALESCE(
      jsonb_agg(jsonb_build_object(
        'event_type', 'audit_event',
        'event_at',   a.fecha_creacion,
        'source',     'audit_logs',
        'payload',    to_jsonb(a.*)
      ) ORDER BY a.fecha_creacion DESC),
      '[]'::jsonb
    )
    INTO v_audits
    FROM auth.auditoria a
    WHERE a.tipo_objetivo = p_entity_type   -- columna canónica
      AND a.id_objetivo::text = p_entity_id;
  EXCEPTION
    WHEN undefined_table THEN v_audits := '[]'::jsonb;
    WHEN invalid_text_representation THEN v_audits := '[]'::jsonb;
  END;

  -- Rama 3: entity_state_transitions (definida en CU-043)
  BEGIN
    SELECT COALESCE(
      jsonb_agg(jsonb_build_object(
        'event_type', 'state_transition',
        'event_at',   s.fecha_creacion,
        'source',     'entity_state_transitions',
        'payload',    to_jsonb(s.*)
      ) ORDER BY s.fecha_creacion DESC),
      '[]'::jsonb
    )
    INTO v_transitions
    FROM public.entity_state_transitions s
    WHERE s.tipo_entidad = p_entity_type
      AND s.id_entidad::text = p_entity_id;
  EXCEPTION
    WHEN undefined_table THEN v_transitions := '[]'::jsonb;
    WHEN invalid_text_representation THEN v_transitions := '[]'::jsonb;
  END;

  -- Unión, ordenación y paginación en memoria JSONB
  WITH combined AS (
    SELECT evt FROM jsonb_array_elements(v_resolutions) AS evt
    UNION ALL
    SELECT evt FROM jsonb_array_elements(v_audits) AS evt
    UNION ALL
    SELECT evt FROM jsonb_array_elements(v_transitions) AS evt
  ),
  ordered AS (
    SELECT evt FROM combined
    ORDER BY (evt->>'event_at')::timestamptz DESC
    LIMIT p_limit OFFSET p_offset
  )
  SELECT COALESCE(jsonb_agg(evt), '[]'::jsonb)
  INTO v_events
  FROM ordered;

  RETURN jsonb_build_object(
    'status',      'ok',
    'entity_type', p_entity_type,
    'entity_id',   p_entity_id,
    'fuentes',     jsonb_build_object(
      'admin_case_resolutions',   jsonb_array_length(v_resolutions),
      'audit_logs',               jsonb_array_length(v_audits),
      'entity_state_transitions', jsonb_array_length(v_transitions)
    ),
    'events', COALESCE(v_events, '[]'::jsonb)
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'status',   'error',
    'message',  SQLERRM,
    'sqlstate', SQLSTATE
  );
END;
$$;


--
-- Name: admin_get_fraud_alert_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_fraud_alert_detail(p_alert_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := COALESCE((current_setting('request.jwt.claims', true)::jsonb ->> 'role'), '');
  v_out  JSONB;
BEGIN
  IF v_role NOT IN ('admin','auditor','super_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'alerta',   to_jsonb(a),
    'auditoria', COALESCE((
        SELECT jsonb_agg(to_jsonb(l) ORDER BY l.created_at DESC)
          FROM auth.auditoria l
         WHERE l.target_kind = 'alerta_admin' AND l.id_objetivo = a.id::text
    ), '[]'::jsonb)
  )
  INTO v_out
  FROM public.admin_alerts a
  WHERE a.id = p_alert_id;

  IF v_out IS NULL THEN
    RAISE EXCEPTION 'alert_not_found' USING ERRCODE = 'P0002';
  END IF;

  RETURN v_out;
END;
$$;


--
-- Name: admin_get_fraud_graph_context(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_fraud_graph_context(p_alert_id uuid, p_max_depth integer DEFAULT 2, p_max_nodes integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_role     TEXT := COALESCE((current_setting('request.jwt.claims', true)::jsonb ->> 'role'), '');
  v_entity   UUID;
  v_kind     TEXT;
  v_out      JSONB := jsonb_build_object('age_available', FALSE);
BEGIN
  IF v_role NOT IN ('admin','auditor','super_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;

  IF p_max_depth NOT BETWEEN 1 AND 3 THEN
    RAISE EXCEPTION 'invalid_depth' USING ERRCODE='22023';
  END IF;

  SELECT referencia_id, referencia_tipo INTO v_entity, v_kind
    FROM public.admin_alerts WHERE id = p_alert_id;

  IF v_entity IS NULL THEN
    RAISE EXCEPTION 'alert_not_found' USING ERRCODE='P0002';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname='age') THEN
    RETURN v_out || jsonb_build_object(
      'entity_id', v_entity, 'referencia_tipo', v_kind,
      'reason', 'age_extension_not_installed'
    );
  END IF;

  -- Retornar solo el catálogo real del grafo (no se inventan labels)
  v_out := jsonb_build_object(
    'age_available', TRUE,
    'entity_id',   v_entity,
    'referencia_tipo', v_kind,
    'max_depth',   p_max_depth,
    'max_nodes',   p_max_nodes,
    'available_labels', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('name', name, 'kind', kind))
          FROM ag_catalog.ag_label
    ), '[]'::jsonb)
  );

  RETURN v_out;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('age_available', FALSE, 'error', SQLERRM);
END;
$$;


--
-- Name: admin_get_graph_metrics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_graph_metrics() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_out JSONB := jsonb_build_object('age_available', FALSE);
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'age') THEN
    v_out := jsonb_build_object(
      'age_available', TRUE,
      'graphs', COALESCE((
         SELECT jsonb_agg(name) FROM ag_catalog.ag_graph
      ), '[]'::jsonb),
      'labels', COALESCE((
         SELECT jsonb_agg(jsonb_build_object('name', name, 'kind', kind))
           FROM ag_catalog.ag_label
      ), '[]'::jsonb)
    );
  END IF;
  RETURN v_out;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('age_available', FALSE, 'error', SQLERRM);
END;
$$;


--
-- Name: admin_get_location_collision_alerts(numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_location_collision_alerts(p_radio_m numeric DEFAULT 5, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_role   TEXT := COALESCE((current_setting('request.jwt.claims', true)::jsonb ->> 'role'), '');
  v_has_gps BOOLEAN;
  v_has_postgis BOOLEAN;
BEGIN
  IF v_role NOT IN ('admin','auditor','super_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
     WHERE table_schema='public' AND table_name='users'
       AND column_name IN ('last_gps','latitude','longitude')
  ) INTO v_has_gps;

  SELECT EXISTS (SELECT 1 FROM pg_extension WHERE extname='postgis') INTO v_has_postgis;

  IF NOT v_has_gps THEN
    RETURN jsonb_build_object(
      'available', FALSE, 'reason', 'no_gps_columns', 'items', '[]'::jsonb
    );
  END IF;

  -- Colisión exacta (fallback sin postgis): mismo par (lat,lng)
  IF NOT v_has_postgis THEN
    RETURN jsonb_build_object(
      'available', TRUE, 'mode', 'exact_match',
      'items', COALESCE((
        SELECT jsonb_agg(row_to_json(t))
          FROM (
            SELECT u.latitude, u.longitude, COUNT(*) AS user_count,
                   array_agg(u.id) AS user_ids
              FROM auth.users u
             WHERE u.latitude IS NOT NULL AND u.longitude IS NOT NULL
             GROUP BY u.latitude, u.longitude
            HAVING COUNT(*) > 1
             ORDER BY user_count DESC
             LIMIT GREATEST(p_limit, 0)
          ) t
      ), '[]'::jsonb)
    );
  END IF;

  RETURN jsonb_build_object('available', TRUE, 'mode', 'postgis',
    'radio_m', p_radio_m, 'items', '[]'::jsonb);
END;
$$;


--
-- Name: admin_get_market_density(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_market_density(p_bbox_wkt text DEFAULT NULL::text, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := COALESCE((current_setting('request.jwt.claims', true)::jsonb ->> 'role'),'');
BEGIN
  IF v_role NOT IN ('admin','auditor','super_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname='postgis') THEN
    RETURN jsonb_build_object('status','PARCIAL','reason','no_postgis','items','[]'::jsonb);
  END IF;

  RETURN jsonb_build_object(
    'status','OK','bbox',p_bbox_wkt,'limit',p_limit,'items','[]'::jsonb
  );
END;
$$;


--
-- Name: admin_get_operational_alerts(text, text, text, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_operational_alerts(p_estado text DEFAULT NULL::text, p_severidad text DEFAULT NULL::text, p_tipo text DEFAULT NULL::text, p_incluir_ocultas boolean DEFAULT false, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, tipo text, id_entidad text, referencia_tipo text, severidad text, estado text, fuente text, payload jsonb, created_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
  SELECT a.id, a.tipo, a.id_entidad, a.referencia_tipo,
         a.severidad, a.estado, a.fuente, a.payload, a.created_at
    FROM public.admin_alerts a
   WHERE (p_estado    IS NULL OR a.estado    = p_estado)
     AND (p_severidad IS NULL OR a.severidad = p_severidad)
     AND (p_tipo      IS NULL OR a.tipo      = p_tipo)
     AND (p_incluir_ocultas OR a.oculto_en_dash = FALSE)
   ORDER BY a.created_at DESC
   LIMIT GREATEST(p_limit, 0)
  OFFSET GREATEST(p_offset, 0);
$$;


--
-- Name: admin_get_operations_queue(text[], text[], text[], boolean, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_operations_queue(p_statuses text[] DEFAULT ARRAY['open'::text, 'in_review'::text, 'escalated'::text], p_entity_types text[] DEFAULT ARRAY['user'::text, 'alert'::text, 'zone'::text, 'suspicious_relation'::text, 'report'::text], p_risk_levels text[] DEFAULT ARRAY['alto'::text, 'medio'::text, 'bajo'::text], p_assigned_to_me boolean DEFAULT false, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_sort_by text DEFAULT 'priority_score'::text, p_sort_direction text DEFAULT 'desc'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_rol        TEXT;
  v_items      JSONB   := '[]'::jsonb;
  v_total      INTEGER := 0;
  v_vista_ok   BOOLEAN := false;
BEGIN
  v_rol := app.jwt_role_safe();
  IF v_rol NOT IN ('administrador_role','superadmin_role','auditor_role') THEN
    RETURN jsonb_build_object(
      'status',  'error',
      'message', 'Acceso denegado: se requiere rol administrador, superadmin o auditor'
    );
  END IF;

  -- Introspección: verificar si existe la vista de alertas activas
  SELECT EXISTS (
    SELECT 1 FROM information_schema.views
    WHERE table_schema = 'public'
      AND table_name   = 'v_alertas_activas'
  ) INTO v_vista_ok;

  IF v_vista_ok THEN
    EXECUTE $sql$
      WITH base AS (
        SELECT
          ('alert-' || COALESCE(id::text, md5(random()::text))) AS queue_item_id,
          'alert'::text                                          AS tipo_item,
          id::text                                               AS id_entidad,
          COALESCE(tipo_alerta,   'Alerta operativa')            AS title,
          COALESCE(descripcion,   'Sin descripción')             AS subtitle,
          COALESCE(nivel_riesgo,  'medio')                       AS risk_level,
          COALESCE(score_riesgo,  50)::numeric                   AS priority_score,
          COALESCE(estado_operativo, 'open')                     AS estado,
          COALESCE(creado_en,     now())                         AS fecha_creacion,
          COALESCE(actualizado_en, creado_en, now())             AS fecha_actualizacion,
          'open_detail'::text                                    AS primary_action,
          '/rpc/admin_get_entity_timeline'::text                 AS detail_route
        FROM public.v_alertas_activas
      ),
      filtered AS (
        SELECT * FROM base
        WHERE tipo_item  = ANY($1)
          AND risk_level = ANY($2)
          AND estado     = ANY($3)
      ),
      counted AS (SELECT COUNT(*)::int AS total FROM filtered),
      paged AS (
        SELECT * FROM filtered
        ORDER BY
          CASE WHEN lower($4) = 'asc'  THEN priority_score END ASC  NULLS LAST,
          CASE WHEN lower($4) = 'desc' THEN priority_score END DESC NULLS LAST,
          fecha_actualizacion DESC
        LIMIT $5 OFFSET $6
      )
      SELECT
        (SELECT total FROM counted),
        COALESCE(jsonb_agg(to_jsonb(p)), '[]'::jsonb)
      FROM paged p
    $sql$
    INTO v_total, v_items
    USING
      p_entity_types,    -- $1
      p_risk_levels,     -- $2
      p_statuses,        -- $3
      p_sort_direction,  -- $4
      p_limit,           -- $5
      p_offset;          -- $6
  END IF;

  RETURN jsonb_build_object(
    'status',  'ok',
    'summary', jsonb_build_object(
      'total',  v_total,
      'fuente', CASE WHEN v_vista_ok THEN 'v_alertas_activas' ELSE 'sin_fuente' END
    ),
    'items', COALESCE(v_items, '[]'::jsonb)
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'status',   'error',
    'message',  SQLERRM,
    'sqlstate', SQLSTATE
  );
END;
$_$;


--
-- Name: admin_get_risk_history(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_risk_history(p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date) RETURNS TABLE(fecha date, nivel_riesgo numeric, total_incidentes bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
BEGIN
  -- R-30: Validación de acceso
  IF NOT (public.is_admin_activo()
          OR app.jwt_role_safe() IN ('auditor_role','superadmin_role')) THEN
    RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO' USING ERRCODE = '42501';
  END IF;

  -- Degradación elegante: si la vista no existe aún
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.views
    WHERE table_schema = 'public' AND table_name = 'v_riesgo_historico'
  ) THEN RETURN; END IF;

  RETURN QUERY
  SELECT r.fecha, r.nivel_riesgo, r.total_incidentes
  FROM public.v_riesgo_historico r
  WHERE (p_from_date IS NULL OR r.fecha >= p_from_date)
    AND (p_to_date   IS NULL OR r.fecha <= p_to_date)
  ORDER BY r.fecha ASC;

EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'admin_get_risk_history error: %', SQLERRM USING ERRCODE = SQLSTATE;
END;
$$;


--
-- Name: admin_get_risk_snapshot(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_risk_snapshot(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_result JSONB;
BEGIN
  -- R-30: Validación de entrada
  IF p_days IS NULL OR p_days <= 0 THEN
    RAISE EXCEPTION 'p_days debe ser un entero positivo' USING ERRCODE = '22003';
  END IF;
  IF NOT (public.is_admin_activo()
          OR app.jwt_role_safe() IN ('auditor_role','superadmin_role')) THEN
    RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'window_days',    p_days,
    'latest_date',    (SELECT MAX(fecha) FROM public.v_riesgo_historico),
    'avg_risk',       (SELECT ROUND(AVG(nivel_riesgo)::numeric, 2)
                       FROM public.v_riesgo_historico
                       WHERE fecha >= CURRENT_DATE - p_days),
    'max_risk',       (SELECT MAX(nivel_riesgo)
                       FROM public.v_riesgo_historico
                       WHERE fecha >= CURRENT_DATE - p_days),
    'total_incidents',(SELECT SUM(total_incidentes)
                       FROM public.v_riesgo_historico
                       WHERE fecha >= CURRENT_DATE - p_days)
  ) INTO v_result;

  RETURN COALESCE(v_result, jsonb_build_object(
    'window_days', p_days, 'latest_date', NULL,
    'avg_risk', 0, 'max_risk', 0, 'total_incidents', 0
  ));

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('status','error','message',SQLERRM,'sqlstate',SQLSTATE);
END;
$$;


--
-- Name: admin_get_shared_device_alerts(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_shared_device_alerts(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_role  TEXT := COALESCE((current_setting('request.jwt.claims', true)::jsonb ->> 'role'), '');
  v_has_dev BOOLEAN;
BEGIN
  IF v_role NOT IN ('admin','auditor','super_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
     WHERE table_schema='public' AND table_name='users'
       AND column_name IN ('device_id','device_hash','hardware_id')
  ) INTO v_has_dev;

  IF NOT v_has_dev THEN
    RETURN jsonb_build_object(
      'available', FALSE,
      'reason', 'no_device_columns_in_users',
      'items', '[]'::jsonb
    );
  END IF;

  RETURN jsonb_build_object(
    'available', TRUE,
    'items', COALESCE((
      SELECT jsonb_agg(row_to_json(t))
        FROM (
          SELECT u.id_dispositivo, COUNT(*) AS user_count,
                 array_agg(u.id) AS user_ids
            FROM auth.users u
           WHERE u.id_dispositivo IS NOT NULL
           GROUP BY u.id_dispositivo
          HAVING COUNT(*) > 1
           ORDER BY user_count DESC
           LIMIT GREATEST(p_limit, 0)
        ) t
    ), '[]'::jsonb)
  );
END;
$$;


--
-- Name: admin_get_suspicious_node_context(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_suspicious_node_context(p_entity_id uuid, p_entity_kind text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
