    AS $$
  SELECT jsonb_build_object(
    'alertas', COALESCE((
      SELECT jsonb_agg(to_jsonb(a) ORDER BY a.created_at DESC)
        FROM public.admin_alerts a
       WHERE a.id_entidad = p_entity_id::text AND a.referencia_tipo = p_entity_kind
