--
-- Name: admin_get_suspicious_nodes(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_suspicious_nodes(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'items', COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
  )
  FROM (
    SELECT a.referencia_id, a.referencia_tipo,
           COUNT(*) AS alertas_activas,
           MAX(CASE a.severidad WHEN 'CRITICAL' THEN 4 WHEN 'HIGH' THEN 3
                                 WHEN 'MEDIUM' THEN 2 ELSE 1 END) AS peor_severidad
      FROM public.admin_alerts a
     WHERE a.estado='ABIERTA' AND a.oculto_en_dash=FALSE
     GROUP BY a.referencia_id, a.referencia_tipo
     ORDER BY peor_severidad DESC, alertas_activas DESC
     LIMIT GREATEST(p_limit, 0)
  ) t;
$$;


--
-- Name: admin_get_visible_dashboard_alerts(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_visible_dashboard_alerts(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_rows JSONB := '[]'::jsonb;
BEGIN
  IF NOT (public.is_admin_activo()
          OR app.jwt_role_safe() IN ('auditor_role','superadmin_role')) THEN
    RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT *
    FROM public.admin_alerts
    WHERE COALESCE(oculto_en_dash, false) = false
    ORDER BY created_at DESC
    LIMIT p_limit OFFSET p_offset
  ) t;

  RETURN jsonb_build_object('status', 'ok', 'items', v_rows);

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('status','error','message',SQLERRM,'sqlstate',SQLSTATE);
END;
$$;


--
-- Name: admin_graph_detect_mirror_accounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_graph_detect_mirror_accounts() RETURNS TABLE(id_entidad uuid, related_ids uuid[], score numeric, evidence jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid := app.jwt_user_id_safe();
  v_age_available boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
  END IF;

  -- Degradación elegante AGE
  BEGIN
    LOAD 'age';
    SET LOCAL search_path = ag_catalog, public, pg_temp;
    v_age_available := true;
  EXCEPTION WHEN OTHERS THEN
    v_age_available := false;
  END;

  IF NOT v_age_available THEN
    -- Fallback SQL puro: cuentas con mismo device_fingerprint / IP en <24h
    RETURN QUERY
      SELECT u1.id,
             array_agg(DISTINCT u2.id),
             0.85::numeric,
             jsonb_build_object('fallback','sql_only','reason','age_unavailable')
      FROM auth.users u1
      JOIN public.user_locations ul1 ON ul1.id_usuario = u1.id
      JOIN public.user_locations ul2 ON ul2.device_fingerprint = ul1.device_fingerprint
                                     AND ul2.id_usuario <> u1.id
      JOIN auth.users u2 ON u2.id = ul2.id_usuario
      WHERE u1.fecha_eliminacion IS NULL AND u2.fecha_eliminacion IS NULL
        AND ul1.fecha_captura > now() - interval '24 hours'
      GROUP BY u1.id
      HAVING count(DISTINCT u2.id) >= 1;
    RETURN;
  END IF;

  -- Cypher path (AGE cargado)
  RETURN QUERY
    SELECT (r.a)::uuid, ARRAY[(r.b)::uuid], 0.95::numeric,
           jsonb_build_object('via','age_cypher','path','mirror_via_device')
    FROM cypher('smtp_posix_graph', $c$
      MATCH (u1:User)-[:USES_DEVICE]->(d:Device)<-[:USES_DEVICE]-(u2:User)
      WHERE u1.id_usuario < u2.id_usuario
      RETURN u1.id_usuario AS a, u2.id_usuario AS b
    $c$) AS r(a, b);
END;
$_$;


--
-- Name: admin_heatmap_comercial(numeric, numeric, numeric, numeric, timestamp with time zone, timestamp with time zone, text, numeric, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_heatmap_comercial(p_min_lng numeric, p_min_lat numeric, p_max_lng numeric, p_max_lat numeric, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_layer text DEFAULT 'oferta'::text, p_cell_size numeric DEFAULT 0.01, p_min_cardinalidad bigint DEFAULT 3, p_output_format text DEFAULT 'wkt'::text) RETURNS TABLE(layer_type text, cell_wkt text, cell_geojson jsonb, supply_count bigint, demand_count bigint, density_score numeric, zone_status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
    v_bbox     geography;
    v_actor_id uuid;
BEGIN
    -- 6.a) Gate de rol admin (helper canónico R-crítica #2)
    IF NOT public.is_admin_activo() THEN
        RAISE EXCEPTION 'ACCION_DENEGADA_ADMIN_REQUERIDO'
            USING ERRCODE = '42501';
    END IF;
    v_actor_id := public.get_app_actor_id();

    -- 6.b) Validaciones de entrada (R-37)
    IF p_min_lng IS NULL OR p_min_lat IS NULL
       OR p_max_lng IS NULL OR p_max_lat IS NULL THEN
        RAISE EXCEPTION 'BBOX_INCOMPLETO' USING ERRCODE = '22023';
    END IF;
    IF p_min_lng >= p_max_lng OR p_min_lat >= p_max_lat THEN
        RAISE EXCEPTION 'BBOX_INVALIDO_MIN_MAYOR_O_IGUAL_MAX' USING ERRCODE = '22023';
    END IF;
    IF p_cell_size <= 0 OR p_cell_size > 1 THEN
        RAISE EXCEPTION 'CELL_SIZE_FUERA_DE_RANGO' USING ERRCODE = '22023';
    END IF;
    IF p_layer NOT IN ('oferta','demanda','ambas') THEN
        RAISE EXCEPTION 'CAPA_INVALIDA: %', p_layer USING ERRCODE = '22023';
    END IF;
    IF p_output_format NOT IN ('wkt','geojson') THEN
        RAISE EXCEPTION 'FORMATO_SALIDA_INVALIDO: %', p_output_format USING ERRCODE = '22023';
    END IF;
    IF p_min_cardinalidad < 1 THEN
        RAISE EXCEPTION 'K_ANONIMATO_MINIMO_1' USING ERRCODE = '22023';
    END IF;

    -- 6.c) Construcción de bbox como geography(4326)
    v_bbox := ST_SetSRID(
        ST_MakeEnvelope(p_min_lng, p_min_lat, p_max_lng, p_max_lat, 4326),
        4326
    )::geography;

    -- 6.d) Registro en ledger WORM (R-38) — best-effort, no bloqueante
    BEGIN
        IF EXISTS (SELECT 1 FROM information_schema.tables
                   WHERE table_schema='public' AND table_name='audit_logs') THEN
            INSERT INTO auth.auditoria (id_actor, action, target_kind, id_objetivo, metadata, fecha_creacion)
            VALUES (
                v_actor_id,
                'admin_heatmap_comercial_invocado',
                'heatmap',
                'heatmap:' || COALESCE(p_layer, 'comercial'),
                jsonb_build_object(
                    'bbox', jsonb_build_array(p_min_lng,p_min_lat,p_max_lng,p_max_lat),
                    'layer', p_layer,
                    'cell_size', p_cell_size,
                    'k_min', p_min_cardinalidad,
                    'from', p_from, 'to', p_to
                ),
                now()
            );
        END IF;
    EXCEPTION WHEN OTHERS THEN
        -- Auditoría no debe bloquear el flujo administrativo (degradación elegante)
        RAISE NOTICE 'audit_logs no disponible: %', SQLERRM;
    END;

    -- 6.e) Ramas por capa
    IF p_layer = 'oferta' THEN
        RETURN QUERY
        SELECT
            'oferta'::text                                            AS layer_type,
            CASE WHEN p_output_format='wkt'
                 THEN ST_AsText(g.cell_geom) ELSE NULL END             AS cell_wkt,
            CASE WHEN p_output_format='geojson'
                 THEN ST_AsGeoJSON(g.cell_geom)::jsonb ELSE NULL END   AS cell_geojson,
            g.supply_count,
            0::bigint                                                  AS demand_count,
            g.supply_count::numeric                                    AS density_score,
            CASE
                WHEN g.supply_count >= 20 THEN 'SATURACION_OFERTA'
                WHEN g.supply_count >= 10 THEN 'COBERTURA_MEDIA'
                WHEN g.supply_count >=  1 THEN 'COBERTURA_BAJA'
                ELSE 'SIN_COBERTURA'
            END                                                        AS zone_status
        FROM public.admin_supply_density_grid(v_bbox, p_cell_size) g
        WHERE g.supply_count >= p_min_cardinalidad;

    ELSIF p_layer = 'demanda' THEN
        -- Delegación a admin_demand_density_grid; esta levantará excepción defensiva
        -- si aún no existe public.v_admin_demand_points (esperado en v8_40).
        RETURN QUERY
        SELECT
            'demanda'::text                                            AS layer_type,
            CASE WHEN p_output_format='wkt'
                 THEN ST_AsText(g.cell_geom) ELSE NULL END             AS cell_wkt,
            CASE WHEN p_output_format='geojson'
                 THEN ST_AsGeoJSON(g.cell_geom)::jsonb ELSE NULL END   AS cell_geojson,
            0::bigint                                                  AS supply_count,
            g.demand_count,
            g.demand_count::numeric                                    AS density_score,
            'DEMANDA_PURA'::text                                       AS zone_status
        FROM public.admin_demand_density_grid(
            v_bbox,
            COALESCE(p_from, now() - interval '30 days'),
            COALESCE(p_to,   now()),
            p_cell_size
        ) g
        WHERE g.demand_count >= p_min_cardinalidad;

    ELSE  -- 'ambas'
        RETURN QUERY
        WITH s AS (
            SELECT
                ST_AsText(cell_geom) AS cell_key,
                cell_geom,
                supply_count
            FROM public.admin_supply_density_grid(v_bbox, p_cell_size)
        ),
        d AS (
            SELECT
                ST_AsText(cell_geom) AS cell_key,
                cell_geom,
                demand_count
            FROM public.admin_demand_density_grid(
                v_bbox,
                COALESCE(p_from, now() - interval '30 days'),
                COALESCE(p_to,   now()),
                p_cell_size
            )
        ),
        merged AS (
            SELECT
                COALESCE(s.cell_key, d.cell_key)                   AS cell_key,
                COALESCE(s.cell_geom, d.cell_geom)                 AS cell_geom,
                COALESCE(s.supply_count, 0)::bigint                AS sc,
                COALESCE(d.demand_count, 0)::bigint                AS dc
            FROM s
            FULL OUTER JOIN d ON s.cell_key = d.cell_key
        )
        SELECT
            'ambas'::text                                              AS layer_type,
            CASE WHEN p_output_format='wkt'
                 THEN ST_AsText(m.cell_geom) ELSE NULL END             AS cell_wkt,
            CASE WHEN p_output_format='geojson'
                 THEN ST_AsGeoJSON(m.cell_geom)::jsonb ELSE NULL END   AS cell_geojson,
            m.sc                                                        AS supply_count,
            m.dc                                                        AS demand_count,
            (m.dc - m.sc)::numeric                                      AS density_score,
            CASE
                WHEN m.dc > m.sc * 1.5 THEN 'BRECHA_OFERTA'
                WHEN m.sc > m.dc * 2.0 THEN 'SATURACION_OFERTA'
                WHEN m.sc = 0 AND m.dc > 0 THEN 'VACIO_COMERCIAL'
                WHEN m.sc > 0 AND m.dc = 0 THEN 'OFERTA_SIN_DEMANDA'
                ELSE 'BALANCEADA'
            END                                                         AS zone_status
        FROM merged m
        WHERE GREATEST(m.sc, m.dc) >= p_min_cardinalidad;
    END IF;
END;
$$;


--
-- Name: admin_hide_dashboard_alert(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_hide_dashboard_alert(p_alert_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor_id UUID  := public.get_app_actor_id();
  v_before   JSONB;
BEGIN
  -- R-30: Validaciones
  IF p_alert_id IS NULL THEN
    RAISE EXCEPTION 'p_alert_id es obligatorio' USING ERRCODE = '23502';
  END IF;
  IF NOT public.is_admin_activo() THEN
    RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO' USING ERRCODE = '42501';
  END IF;

  SELECT to_jsonb(a) INTO v_before
  FROM public.admin_alerts a WHERE a.id = p_alert_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found', 'alert_id', p_alert_id);
  END IF;

  -- Idempotente
  IF (v_before->>'oculto_en_dash')::boolean = true THEN
    RETURN jsonb_build_object('status', 'already_hidden', 'alert_id', p_alert_id);
  END IF;

  UPDATE public.admin_alerts
  SET oculto_en_dash = true,
      hidden_at      = now(),
      hidden_by      = v_actor_id,
      hidden_reason  = p_reason
  WHERE id = p_alert_id;

  -- R-38: Auditoría con snapshot before
  INSERT INTO auth.auditoria
    (id_actor, action, tipo_objetivo, id_objetivo, metadata, fecha_creacion)
  VALUES (
    v_actor_id, 'DASHBOARD_ALERT_HIDDEN', 'admin_alerts', p_alert_id::text,
    jsonb_build_object(
      'reason', p_reason,
      'before', v_before,
      'after',  jsonb_build_object('oculto_en_dash', true, 'hidden_at', now())
    ),
    now()
  );

  RETURN jsonb_build_object('status', 'ok', 'alert_id', p_alert_id, 'hidden', true);

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('status','error','message',SQLERRM,'sqlstate',SQLSTATE);
END;
$$;


--
-- Name: admin_intervenir_red_sospechosa(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_intervenir_red_sospechosa(p_seed_entity_id uuid, p_case_id uuid, p_hops integer DEFAULT 1, p_max_targets integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_actor    uuid := app.jwt_user_id_safe();
  v_targets  uuid[];
  v_target   uuid;
  v_count    int  := 0;
  v_snapshot jsonb := '[]'::jsonb;
  v_age_ok   boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
  END IF;
  IF p_hops NOT BETWEEN 1 AND 2 THEN
    RAISE EXCEPTION 'hops debe estar entre 1 y 2' USING ERRCODE = '22003';
  END IF;
  IF p_max_targets NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'max_targets fuera de rango (1..100)' USING ERRCODE = '22003';
  END IF;

  BEGIN LOAD 'age'; v_age_ok := true; EXCEPTION WHEN OTHERS THEN v_age_ok := false; END;

  IF v_age_ok THEN
    SELECT array_agg(t) INTO v_targets FROM (
      SELECT DISTINCT (r.neighbor)::uuid AS t
      FROM cypher('smtp_posix_graph', format($c$
        MATCH (u:User {id_usuario: "%s"})-[*1..%s]-(n:User)
        WHERE n.id_usuario <> "%s"
        RETURN DISTINCT n.id_usuario AS neighbor LIMIT %s
      $c$, p_seed_entity_id::text, p_hops, p_seed_entity_id::text, p_max_targets)) AS r(neighbor)
    ) s;
  ELSE
    -- Fallback SQL: mismos device_fp o mismas IPs recientes
    SELECT array_agg(DISTINCT ul2.id_usuario) INTO v_targets
    FROM public.user_locations ul1
    JOIN public.user_locations ul2
      ON (ul1.device_fingerprint = ul2.device_fingerprint
          OR ul1.ip_address = ul2.ip_address)
     AND ul2.id_usuario <> p_seed_entity_id
    WHERE ul1.id_usuario = p_seed_entity_id
      AND ul1.fecha_captura > now() - interval '30 days'
    LIMIT p_max_targets;
  END IF;

  IF v_targets IS NULL THEN
    v_targets := ARRAY[]::uuid[];
  END IF;

  FOREACH v_target IN ARRAY v_targets LOOP
    v_snapshot := v_snapshot || jsonb_build_object(
      'id_usuario', v_target,
      'prev_state', (SELECT estado_administrativo FROM auth.users WHERE id = v_target)
    );
    PERFORM public.admin_suspend_entity(v_target, 'user',
                                        'network_intervention_case:'||p_case_id::text,
                                        p_case_id,
                                        jsonb_build_object('seed', p_seed_entity_id));
    v_count := v_count + 1;
  END LOOP;

  INSERT INTO auth.auditoria(id_actor, action, target_kind, id_objetivo, payload)
  VALUES (v_actor, 'network_intervention', 'user', p_seed_entity_id,
          jsonb_build_object('case_id', p_case_id, 'hops', p_hops,
                             'targets_count', v_count, 'snapshot', v_snapshot));

  RETURN jsonb_build_object('success', true, 'suspended_count', v_count, 'targets', v_targets,
                            'timestamp_utc', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
END;
$_$;


--
-- Name: admin_mark_under_investigation(uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_mark_under_investigation(p_entity_id uuid, p_entity_kind text, p_detector_name text, p_evidence jsonb DEFAULT '{}'::jsonb, p_severity text DEFAULT 'medium'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid := app.jwt_user_id_safe();
  v_case_id  uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
  END IF;
  IF p_entity_id IS NULL OR p_entity_kind IS NULL OR p_detector_name IS NULL THEN
    RAISE EXCEPTION 'Parámetros obligatorios NULL' USING ERRCODE = '23502';
  END IF;
  IF p_severity NOT IN ('low','medium','high','critical') THEN
    RAISE EXCEPTION 'severity inválido: %', p_severity USING ERRCODE = '22P02';
  END IF;

  INSERT INTO public.investigation_cases
    (id_entidad, entity_kind, detector_name, evidence, severity, opened_by)
  VALUES
    (p_entity_id, p_entity_kind, p_detector_name, p_evidence, p_severity, v_actor)
  RETURNING id_caso INTO v_case_id;

  -- Ledger WORM (R-38)
  INSERT INTO auth.auditoria(id_actor, action, target_kind, id_objetivo, payload)
  VALUES (v_actor, 'investigation_opened', p_entity_kind, p_entity_id,
          jsonb_build_object('case_id', v_case_id, 'detector', p_detector_name, 'severity', p_severity));

  RETURN jsonb_build_object(
    'success', true,
    'case_id', v_case_id,
    'timestamp_utc', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
END;
$$;


