--
-- Name: admin_preview_administrator_deactivation_impact(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_preview_administrator_deactivation_impact(p_admin_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_is_active BOOLEAN;
  v_email     TEXT;
  v_role      TEXT;
BEGIN
  IF NOT public.is_superadmin_activo() THEN
    RETURN jsonb_build_object('status','forbidden');
  END IF;

  SELECT is_active, email, role
  INTO v_is_active, v_email, v_role
  FROM auth.users WHERE id = p_admin_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status','not_found','admin_id',p_admin_id);
  END IF;

  RETURN jsonb_build_object(
    'status',            'ok',
    'admin_id',          p_admin_id,
    'email',             v_email,
    'role',              v_role,
    'is_active',         v_is_active,
    'open_alerts',       jsonb_build_array(),
    'assigned_cases',    jsonb_build_array(),
    'recommended_action', CASE
      WHEN v_is_active THEN 'ALLOW_REVIEW'
      ELSE 'ALREADY_INACTIVE'
    END
  );
END;
$$;


--
-- Name: admin_preview_administrator_responsibility_scope(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_preview_administrator_responsibility_scope(p_admin_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.is_superadmin_activo() THEN
    RETURN jsonb_build_object('status','forbidden');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_admin_id) THEN
    RETURN jsonb_build_object('status','not_found','admin_id',p_admin_id);
  END IF;

  RETURN jsonb_build_object(
    'status',           'ok',
    'admin_id',         p_admin_id,
    'assigned_assets',  jsonb_build_array(),
    'open_cases',       jsonb_build_array(),
    'moderation_queue', jsonb_build_array(),
    'operational_risk', 'unknown_until_mapped'
  );
END;
$$;


--
-- Name: admin_reassign_administrator_responsibilities(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reassign_administrator_responsibilities(p_from_admin_id uuid, p_to_admin_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor_id UUID := public.get_app_actor_id();  -- R-30
BEGIN
  IF NOT public.is_superadmin_activo() THEN
    RETURN jsonb_build_object('status','forbidden');
  END IF;

  IF p_from_admin_id = p_to_admin_id THEN
    RETURN jsonb_build_object('status','invalid',
      'message','No se puede reasignar al mismo administrador');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_from_admin_id) THEN
    RETURN jsonb_build_object('status','not_found_from','from_admin_id',p_from_admin_id);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM auth.users
    WHERE id = p_to_admin_id AND COALESCE(is_active, false) = true AND fecha_eliminacion IS NULL
  ) THEN
    RETURN jsonb_build_object('status','to_admin_not_active','to_admin_id',p_to_admin_id);
  END IF;

  INSERT INTO auth.auditoria
    (id_actor, action, tipo_objetivo, id_objetivo, metadata, fecha_creacion)
  VALUES (v_actor_id, 'ADMIN_RESPONSIBILITIES_REASSIGNED', 'auth.users',
    p_from_admin_id::text,
    jsonb_build_object(
      'from_admin_id', p_from_admin_id,
      'to_admin_id',   p_to_admin_id,
      'reason',        p_reason
    ),
    now());

  RETURN jsonb_build_object(
    'status',            'ok',
    'from_admin_id',     p_from_admin_id,
    'to_admin_id',       p_to_admin_id,
    'reassigned_assets', jsonb_build_array(),
    'reason',            p_reason,
    'actor_id',          v_actor_id
  );
END;
$$;


--
-- Name: admin_registrar_senal_fraude(text, text, text, text, text, text, text, numeric, numeric, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_registrar_senal_fraude(p_entity_type text, p_entity_id text, p_signal_type text, p_device_fingerprint text DEFAULT NULL::text, p_ip text DEFAULT NULL::text, p_geo_country text DEFAULT NULL::text, p_geo_region text DEFAULT NULL::text, p_geo_lat numeric DEFAULT NULL::numeric, p_geo_lon numeric DEFAULT NULL::numeric, p_risk_score numeric DEFAULT 0, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_enabled boolean;
  v_signal_id uuid;
  v_ip_hash text;
BEGIN
  v_actor := app.jwt_user_id_safe();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'no_auth' USING ERRCODE='28000'; END IF;
  IF NOT (public.is_admin_activo() OR public.is_superadmin_activo()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;

  -- Feature-flag
  SELECT COALESCE((setting_value)::text::boolean, false) INTO v_enabled
  FROM public.config_seguridad WHERE setting_key='fraud_signals.enabled';
  IF NOT COALESCE(v_enabled, false) THEN
    RETURN jsonb_build_object('ok', true, 'skipped', true,
                              'reason','fraud_signals.disabled');
  END IF;

  -- Validaciones
  IF p_entity_type NOT IN ('vendedor','comprador','orden','producto') THEN
    RAISE EXCEPTION 'entity_type_invalido' USING ERRCODE='22023';
  END IF;
  IF p_entity_id IS NULL OR length(trim(p_entity_id))=0 THEN
    RAISE EXCEPTION 'entity_id_null' USING ERRCODE='22004';
  END IF;
  IF p_risk_score IS NULL OR p_risk_score < 0 OR p_risk_score > 100 THEN
    RAISE EXCEPTION 'risk_score_out_of_range' USING ERRCODE='22023';
  END IF;

  IF p_ip IS NOT NULL AND length(p_ip)>0 THEN
    v_ip_hash := encode(digest(p_ip,'sha256'),'hex');
  END IF;

  INSERT INTO public.fraud_signals(
    referencia_tipo, referencia_id, device_fingerprint, ip_hash,
    geo_country, geo_region, geo_lat, geo_lon,
    risk_score, signal_type, metadata, created_by
  ) VALUES (
    p_entity_type, p_entity_id, p_device_fingerprint, v_ip_hash,
    p_geo_country, p_geo_region, p_geo_lat, p_geo_lon,
    p_risk_score, p_signal_type, p_metadata, v_actor
  ) RETURNING id INTO v_signal_id;

  -- Enriquecer alertas abiertas de la misma entidad (últimas 6h)
  UPDATE public.admin_alerts
     SET payload = payload || jsonb_build_object('fraud_signal_id', v_signal_id,
                                                   'signal_type', p_signal_type,
                                                   'risk_score', p_risk_score),
         updated_at = now()
   WHERE referencia_tipo = p_entity_type
     AND referencia_id::text = p_entity_id
     AND estado IN ('open','in_review')
     AND created_at > now() - interval '6 hours';

  -- WORM
  INSERT INTO auth.auditoria(id_actor, action, tipo_objetivo, id_objetivo, metadata)
  VALUES (v_actor, 'FRAUD_SIGNAL_REGISTER', p_entity_type, p_entity_id,
          jsonb_build_object('signal_id', v_signal_id, 'signal_type', p_signal_type,
                             'risk_score', p_risk_score));

  RETURN jsonb_build_object('ok', true, 'signal_id', v_signal_id);
END;
$$;


--
-- Name: admin_resolve_operational_case(text, text, text, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_resolve_operational_case(p_entity_type text, p_entity_id text, p_resolution_action text, p_resolution_reason text DEFAULT NULL::text, p_evidence jsonb DEFAULT '{}'::jsonb, p_apply_side_effects boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_rol           TEXT;
  v_actor_id      UUID;   -- R-30
  v_resolution_id UUID;
  v_side_effects  JSONB := '{}'::jsonb;
BEGIN
  v_rol := app.jwt_role_safe();
  IF v_rol NOT IN ('administrador_role','superadmin_role') THEN
    RETURN jsonb_build_object(
      'status',  'error',
      'message', 'Acceso denegado: se requiere rol administrador o superadmin'
    );
  END IF;

  IF p_entity_type IS NULL OR trim(p_entity_type) = '' THEN
    RETURN jsonb_build_object('status','error','message','p_entity_type es obligatorio');
  END IF;
  IF p_entity_id IS NULL OR trim(p_entity_id) = '' THEN
    RETURN jsonb_build_object('status','error','message','p_entity_id es obligatorio');
  END IF;
  IF p_resolution_action IS NULL OR trim(p_resolution_action) = '' THEN
    RETURN jsonb_build_object('status','error','message','p_resolution_action es obligatorio');
  END IF;

  v_actor_id := public.get_app_actor_id();  -- R-30: wrapper canónico

  INSERT INTO public.admin_case_resolutions
    (tipo_entidad, id_entidad, resolution_action, resolution_reason,
     evidence, applied_side_effects, created_by)
  VALUES
    (p_entity_type, p_entity_id, p_resolution_action, p_resolution_reason,
     COALESCE(p_evidence, '{}'::jsonb), '{}'::jsonb, v_actor_id)
  RETURNING id INTO v_resolution_id;

  -- Side effects opcionales (con degradación por introspección)
  IF p_apply_side_effects THEN
    IF p_entity_type = 'user'
       AND p_resolution_action IN ('confirm_fraud','suspend_user')
    THEN
      IF EXISTS (
        SELECT 1 FROM information_schema.routines
        WHERE routine_schema = 'public' AND routine_name = 'admin_panel_suspend_user'
      ) THEN
        BEGIN
          PERFORM public.admin_panel_suspend_user(p_entity_id::uuid);
          v_side_effects := v_side_effects
            || jsonb_build_object('user_suspended', true, 'via', 'admin_panel_suspend_user');
        EXCEPTION WHEN OTHERS THEN
          v_side_effects := v_side_effects
            || jsonb_build_object('user_suspended', false, 'suspend_error', SQLERRM);
        END;
      ELSIF EXISTS (
        SELECT 1 FROM information_schema.routines
        WHERE routine_schema = 'public' AND routine_name = 'admin_soft_delete_user'
      ) THEN
        BEGIN
          PERFORM public.admin_soft_delete_user(p_entity_id::uuid, p_resolution_reason);
          v_side_effects := v_side_effects
            || jsonb_build_object('user_suspended', true, 'via', 'admin_soft_delete_user');
        EXCEPTION WHEN OTHERS THEN
          v_side_effects := v_side_effects
            || jsonb_build_object('user_suspended', false, 'suspend_error', SQLERRM);
        END;
      ELSE
        v_side_effects := v_side_effects
          || jsonb_build_object('user_suspended', false, 'suspend_skip', 'sin_rpc_disponible');
      END IF;
    END IF;
  END IF;

  UPDATE public.admin_case_resolutions
  SET applied_side_effects = v_side_effects
  WHERE id = v_resolution_id;

  INSERT INTO auth.auditoria
    (id_actor, action, tipo_objetivo, id_objetivo, metadata)
  VALUES (
    v_actor_id,
    'ADMIN_RESOLVE_OPERATIONAL_CASE',
    p_entity_type,
    v_resolution_id::text,
    jsonb_build_object(
      'entity_id',         p_entity_id,
      'resolution_action', p_resolution_action,
      'side_effects',      v_side_effects
    )
  );

  v_side_effects := v_side_effects || jsonb_build_object('audit_logged', true);

  RETURN jsonb_build_object(
    'status',            'ok',
    'resolution_id',     v_resolution_id,
    'entity_type',       p_entity_type,
    'entity_id',         p_entity_id,
    'resolution_action', p_resolution_action,
    'side_effects',      v_side_effects
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'status',   'error',
    'message',  SQLERRM,
    'sqlstate', SQLSTATE
  );
END;
$$;


--
-- Name: admin_restore_administrator(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_restore_administrator(p_admin_id uuid, p_reason text DEFAULT NULL::text, p_sync_age boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor_id UUID := public.get_app_actor_id();  -- R-30
  v_role     TEXT;
BEGIN
  IF NOT public.is_superadmin_activo() THEN
    RETURN jsonb_build_object('status','forbidden');
  END IF;

  SELECT role INTO v_role FROM auth.users WHERE id = p_admin_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status','not_found','admin_id',p_admin_id);
  END IF;

  UPDATE auth.users
  SET is_active      = true,
      fecha_eliminacion     = NULL,
      deleted_by     = NULL,
      deleted_reason = NULL
  WHERE id = p_admin_id AND fecha_eliminacion IS NOT NULL;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status','not_restorable','admin_id',p_admin_id);
  END IF;

  INSERT INTO public.admin_role_lifecycle_audit
    (id_admin, id_actor, tipo_evento, role_old, role_new, reason, metadata)
  VALUES (p_admin_id, v_actor_id, 'ADMIN_RESTORED', v_role, v_role, p_reason,
          jsonb_build_object('sync_age_requested', p_sync_age));

  INSERT INTO public.entity_state_transitions
    (tipo_entidad, id_entidad, from_state, to_state, changed_by, reason, fecha_creacion)
  VALUES ('user', p_admin_id::text, 'inactive', 'active', v_actor_id, p_reason, now());

  RETURN jsonb_build_object(
    'status',             'ok',
    'admin_id',           p_admin_id,
    'restored_by',        v_actor_id,
    'sync_age_requested', p_sync_age
  );
END;
$$;


--
-- Name: admin_revert_network_intervention(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_revert_network_intervention(p_case_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor    uuid := app.jwt_user_id_safe();
  v_snapshot jsonb;
  v_item     jsonb;
  v_reverted int := 0;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
  END IF;

  SELECT payload->'snapshot' INTO v_snapshot
    FROM auth.auditoria
   WHERE action = 'network_intervention'
     AND payload->>'case_id' = p_case_id::text
   ORDER BY fecha_creacion DESC LIMIT 1;

  IF v_snapshot IS NULL THEN
    RAISE EXCEPTION 'No hay snapshot para case_id=%', p_case_id USING ERRCODE = '02000';
  END IF;

  FOR v_item IN SELECT jsonb_array_elements(v_snapshot) LOOP
    UPDATE auth.users
       SET estado_administrativo = COALESCE(v_item->>'prev_state','active'),
           fecha_actualizacion = now()
     WHERE id = (v_item->>'id_usuario')::uuid;
    PERFORM public.sync_user_status_to_age((v_item->>'id_usuario')::uuid,
                                            COALESCE(v_item->>'prev_state','active'));
    v_reverted := v_reverted + 1;
  END LOOP;

  UPDATE public.investigation_cases
     SET estado = 'reverted', reverted_at = now()
   WHERE id_caso = p_case_id;

  INSERT INTO auth.auditoria(id_actor, action, target_kind, id_objetivo, payload)
  VALUES (v_actor, 'network_intervention_reverted', 'case', p_case_id,
          jsonb_build_object('reason', p_reason, 'reverted_count', v_reverted));

  RETURN jsonb_build_object('success', true, 'reverted_count', v_reverted,
                            'timestamp_utc', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
END;
$$;


--
-- Name: admin_riesgo_historico(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_riesgo_historico(p_dias integer DEFAULT 30) RETURNS TABLE(dia date, nivel_riesgo text, total_alertas integer, resueltas integer, pendientes integer, score_promedio numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_actor uuid;
BEGIN
  v_actor := app.jwt_user_id_safe();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'no_auth' USING ERRCODE='28000'; END IF;
  IF NOT (public.is_admin_activo() OR public.is_superadmin_activo()
          OR COALESCE(app.jwt_role_safe(),'')='auditor_role') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;
  IF p_dias IS NULL OR p_dias <= 0 OR p_dias > 365 THEN p_dias := 30; END IF;

  RETURN QUERY
    SELECT v.dia::date, v.nivel_riesgo, v.total_alertas, v.resueltas,
           v.pendientes, v.score_promedio
    FROM public.v_riesgo_historico v
    WHERE v.dia > now() - (p_dias||' days')::interval
    ORDER BY v.dia DESC, v.nivel_riesgo;
END;
$$;


--
-- Name: admin_set_plan_limit(text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_plan_limit(p_codigo text, p_limit text, p_value numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
    IF NOT auth.is_db_admin() THEN
        RAISE EXCEPTION 'Requiere rol db_admin' USING ERRCODE = '42501';
    END IF;

    CASE p_limit
        WHEN 'precio_mensual'     THEN UPDATE auth.planes_membresia SET precio_mensual = p_value, fecha_modificacion = now() WHERE codigo = p_codigo;
        WHEN 'precio_anual'       THEN UPDATE auth.planes_membresia SET precio_anual = p_value, fecha_modificacion = now() WHERE codigo = p_codigo;
        WHEN 'max_productos'      THEN UPDATE auth.planes_membresia SET max_productos = p_value::integer, fecha_modificacion = now() WHERE codigo = p_codigo;
        WHEN 'max_ubicaciones'    THEN UPDATE auth.planes_membresia SET max_ubicaciones = p_value::integer, fecha_modificacion = now() WHERE codigo = p_codigo;
        WHEN 'max_promociones'    THEN UPDATE auth.planes_membresia SET max_promociones = p_value::integer, fecha_modificacion = now() WHERE codigo = p_codigo;
        WHEN 'max_fotos_producto' THEN UPDATE auth.planes_membresia SET max_fotos_producto = p_value::integer, fecha_modificacion = now() WHERE codigo = p_codigo;
        ELSE
            RAISE EXCEPTION 'limit no soportado: %', p_limit USING ERRCODE = '22023';
    END CASE;

    RETURN jsonb_build_object('status','OK','codigo',p_codigo,'limit',p_limit,'value',p_value);
END;
$$;


--
-- Name: admin_set_tier_rule(text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_tier_rule(p_tier text, p_actor_role text, p_rule_code text, p_numeric numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
    IF NOT auth.is_db_admin() THEN
        RAISE EXCEPTION 'Requiere rol db_admin' USING ERRCODE = '42501';
    END IF;
    IF p_tier NOT IN ('bronze','silver','gold','platinum') THEN
        RAISE EXCEPTION 'tier inválido: %', p_tier USING ERRCODE = '22023';
    END IF;
    IF p_actor_role NOT IN ('buyer','seller') THEN
        RAISE EXCEPTION 'actor_role inválido: %', p_actor_role USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.commercial_rule_catalog c WHERE c.rule_code = p_rule_code) THEN
        RAISE EXCEPTION 'rule_code no registrado: %', p_rule_code USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.commercial_tier_rule_values (actor_role, tier_code, rule_code, numeric_value)
    VALUES (p_actor_role, p_tier, p_rule_code, p_numeric)
    ON CONFLICT (actor_role, tier_code, rule_code)
    DO UPDATE SET numeric_value = EXCLUDED.numeric_value;

    RETURN jsonb_build_object(
        'status', 'OK',
        'tier', p_tier, 'actor_role', p_actor_role, 'rule_code', p_rule_code,
        'numeric_value', p_numeric,
        'efectivo_ahora', public.get_tier_rule_numeric(p_tier, p_actor_role, p_rule_code));
END;
$$;


--
-- Name: admin_soft_block_vendor_by_risk(uuid, text, bigint, text, integer, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_soft_block_vendor_by_risk(p_vendor_id uuid, p_reason text, p_incident_id bigint DEFAULT NULL::bigint, p_incident_description text DEFAULT NULL::text, p_incident_level integer DEFAULT NULL::integer, p_alert_id bigint DEFAULT NULL::bigint) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_before jsonb;
    v_after  jsonb;
    v_alert_id uuid;
    v_severity text;
BEGIN
    IF p_reason IS NULL OR btrim(p_reason) = '' THEN
        RAISE EXCEPTION 'motivo_obligatorio' USING ERRCODE = '23514';
    END IF;

    v_severity := CASE
        WHEN coalesce(p_incident_level, 2) >= 4 THEN 'critical'
        WHEN coalesce(p_incident_level, 2) >= 3 THEN 'high'
        ELSE 'medium'
    END;

    SELECT to_jsonb(ppv) INTO v_before
    FROM (SELECT ppv.activo, ppv.visibilidad_reducida,
                 ppv.inventario_congelado, ppv.motivo_congelamiento
          FROM auth.perfiles_publicos_vendedor ppv
          WHERE ppv.id_vendedor = p_vendor_id) ppv;
    IF v_before IS NULL THEN
        v_before := '{}'::jsonb;
    END IF;

    -- Soft-block: congelar inventario + reducir visibilidad + persistir motivo.
    -- No toca `activo`: el trigger fn_trg_prepare_perfil_publico_vendedor lo
    -- preserva en UPDATE ("solo admin modifica") y corresponde al bloqueo DURO;
    -- el bloqueo suave se materializa con visibilidad_reducida + inventario_congelado.
    -- UPDATE sobre perfil existente (no se inserta perfil nuevo, para no violar la
    -- FK perfil_graph_outbox.id_vendedor -> auth.users(id)). El trigger
    -- fn_trg_perfil_graph_outbox emite el evento SUSPEND y sincroniza el grafo.
    UPDATE auth.perfiles_publicos_vendedor
    SET visibilidad_reducida = true,
        inventario_congelado = true,
        motivo_congelamiento = p_reason
    WHERE id_vendedor = p_vendor_id;

    -- Productos del vendedor fuera del consumo publico (modelo real auth.productos,
    -- id_vendedor -> auth.users(id)); trg_productos_graph_outbox propaga al grafo.
    UPDATE auth.productos
    SET activo = false
    WHERE id_vendedor = p_vendor_id
      AND activo = true;

    v_after := jsonb_build_object(
        'visibilidad_reducida', true,
        'inventario_congelado', true,
        'motivo_congelamiento', p_reason);

    -- Traza: reutiliza el helper de auditoria/riesgo existente.
    PERFORM public.log_admin_risk_event(
        'soft_block_vendor_by_risk',
        'vendedor',
        p_vendor_id::text,
        p_reason,
        v_before,
        v_after);

    -- Ledger de acciones de admin sobre vendedor (persiste motivo + incidente).
    INSERT INTO auth.admin_acciones_vendedor
        (id_vendedor, accion, motivo, admin_user_id,
         datos_anteriores, datos_nuevos, metadata)
    VALUES
        (p_vendor_id, 'disable_seller_profile', p_reason, public.get_app_actor_id(),
         v_before, v_after,
         jsonb_strip_nulls(jsonb_build_object(
             'incident_id', p_incident_id,
             'incident_description', p_incident_description,
             'incident_level', p_incident_level,
             'alert_id', p_alert_id)));

    -- Alerta de riesgo.
    INSERT INTO public.fraud_alerts
        (tipo_alerta, primary_entity_id, primary_entity_kind, severity, evidence)
    VALUES
        ('vendor_soft_blocked', p_vendor_id, 'user', v_severity,
         jsonb_strip_nulls(jsonb_build_object(
             'motivo', p_reason,
             'incident_id', p_incident_id,
             'incident_level', p_incident_level,
             'alert_id', p_alert_id,
             'incident_description', p_incident_description)))
    RETURNING alert_id INTO v_alert_id;

    RETURN v_alert_id;
END;
$$;


--
-- Name: admin_soft_delete_administrator(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_soft_delete_administrator(p_admin_id uuid, p_reason text DEFAULT NULL::text, p_sync_age boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor_id UUID := public.get_app_actor_id();  -- R-30
  v_role     TEXT;
BEGIN
  IF NOT public.is_superadmin_activo() THEN
    RETURN jsonb_build_object('status','forbidden');
  END IF;

  SELECT role INTO v_role
  FROM auth.users WHERE id = p_admin_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status','not_found','admin_id',p_admin_id);
  END IF;

  IF EXISTS (
    SELECT 1 FROM auth.users
    WHERE id = p_admin_id
      AND (fecha_eliminacion IS NOT NULL OR COALESCE(is_active, false) = false)
  ) THEN
    RETURN jsonb_build_object('status','already_deactivated','admin_id',p_admin_id);
  END IF;

  UPDATE auth.users
  SET is_active      = false,
      fecha_eliminacion     = now(),
      deleted_by     = v_actor_id,
      deleted_reason = p_reason
  WHERE id = p_admin_id;

  INSERT INTO public.admin_role_lifecycle_audit
    (id_admin, id_actor, tipo_evento, role_old, role_new, reason, metadata)
  VALUES (p_admin_id, v_actor_id, 'ADMIN_SOFT_DELETED', v_role, v_role, p_reason,
          jsonb_build_object('sync_age_requested', p_sync_age));

  INSERT INTO auth.auditoria
    (id_actor, action, tipo_objetivo, id_objetivo, metadata, fecha_creacion)
  VALUES (v_actor_id, 'ADMIN_SOFT_DELETE', 'auth.users', p_admin_id::text,
    jsonb_build_object('reason', p_reason, 'sync_age_requested', p_sync_age),
    now());

  INSERT INTO public.entity_state_transitions
    (tipo_entidad, id_entidad, from_state, to_state, changed_by, reason, fecha_creacion)
  VALUES ('user', p_admin_id::text, 'active', 'inactive', v_actor_id, p_reason, now());

  RETURN jsonb_build_object(
    'status',              'ok',
    'admin_id',            p_admin_id,
    'deleted_by',          v_actor_id,
    'sync_age_requested',  p_sync_age
  );
END;
$$;


--
-- Name: admin_supply_density_grid(public.geography, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_supply_density_grid(p_bbox public.geography, p_cell_size numeric DEFAULT 0.01) RETURNS TABLE(cell_geom public.geometry, cell_centroid public.geography, supply_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
    WITH filtered AS (
        SELECT sp.punto::geometry AS geom_pt
        FROM public.v_admin_supply_points sp
        WHERE sp.is_operational_supply = true
          AND ST_Intersects(sp.punto, p_bbox)
    ),
    snapped AS (
        SELECT ST_SnapToGrid(geom_pt, p_cell_size, p_cell_size) AS cell_pt
        FROM filtered
    ),
    aggregated AS (
        SELECT
            cell_pt,
            COUNT(*)::bigint AS supply_count
        FROM snapped
        GROUP BY cell_pt
    )
    SELECT
        ST_SetSRID(
            ST_MakeEnvelope(
                ST_X(cell_pt),
                ST_Y(cell_pt),
                ST_X(cell_pt) + p_cell_size,
                ST_Y(cell_pt) + p_cell_size,
                4326
            ),
            4326
        )                                                         AS cell_geom,
        ST_SetSRID(
            ST_MakePoint(
                ST_X(cell_pt) + p_cell_size/2.0,
                ST_Y(cell_pt) + p_cell_size/2.0
            ),
            4326
        )::geography                                              AS cell_centroid,
        supply_count
    FROM aggregated;
$$;


--
-- Name: admin_suspend_entity(uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_suspend_entity(p_entity_id uuid, p_entity_kind text, p_reason text, p_case_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor  uuid := app.jwt_user_id_safe();
  v_prev   text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
  END IF;
  IF p_entity_kind <> 'user' THEN
    RAISE EXCEPTION 'entity_kind % no soportado en v8_39' , p_entity_kind USING ERRCODE = '0A000';
  END IF;

  UPDATE auth.users
     SET estado_administrativo = 'suspended',
         fecha_actualizacion            = now()
   WHERE id = p_entity_id
     AND fecha_eliminacion IS NULL
     AND estado_administrativo <> 'suspended'
  RETURNING (SELECT estado_administrativo FROM auth.users WHERE id = p_entity_id) INTO v_prev;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Entidad no encontrada o ya suspendida' USING ERRCODE = '02000';
  END IF;

  -- AGE sync (best-effort)
  PERFORM public.sync_user_status_to_age(p_entity_id, 'suspended');

  INSERT INTO auth.auditoria(id_actor, action, target_kind, id_objetivo, payload)
  VALUES (v_actor, 'entity_suspended', p_entity_kind, p_entity_id,
          jsonb_build_object('reason', p_reason, 'case_id', p_case_id, 'metadata', p_metadata));

  RETURN jsonb_build_object('success', true, 'entity_id', p_entity_id, 'new_state','suspended',
                            'timestamp_utc', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
END;
$$;


--
-- Name: admin_suspend_user(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_suspend_user(p_user_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_role     TEXT := COALESCE((current_setting('request.jwt.claims', true)::jsonb ->> 'role'), '');
  v_actor    UUID := public.get_app_actor_id();
  v_before   JSONB;
  v_after    JSONB;
  v_has_col  BOOLEAN;
BEGIN
  IF v_role NOT IN ('admin','super_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE='23514';
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM information_schema.columns
     WHERE table_schema='public' AND table_name='users' AND column_name='estado'
  ) INTO v_has_col;

  IF NOT v_has_col THEN
    RAISE EXCEPTION 'users.estado_column_missing' USING ERRCODE='42703';
  END IF;

  SELECT to_jsonb(u) INTO v_before FROM auth.users u WHERE u.id = p_user_id;
  IF v_before IS NULL THEN
    RAISE EXCEPTION 'user_not_found' USING ERRCODE='P0002';
  END IF;

  UPDATE auth.users
     SET estado = 'SUSPENDIDO', fecha_actualizacion = NOW()
   WHERE id = p_user_id
     AND estado IS DISTINCT FROM 'SUSPENDIDO';

  SELECT to_jsonb(u) INTO v_after FROM auth.users u WHERE u.id = p_user_id;

  INSERT INTO public.entity_state_transitions(
    entity_kind, id_entidad, from_state, to_state, id_actor, reason
  ) VALUES (
    'user', p_user_id,
    v_before ->> 'estado', 'SUSPENDIDO', v_actor, p_reason
  );

  PERFORM public.log_admin_risk_event(
    'ADMIN_SUSPEND_USER', 'user', p_user_id::text, p_reason, v_before, v_after
  );

  RETURN jsonb_build_object(
    'ok', TRUE, 'id_usuario', p_user_id,
    'from_state', v_before ->> 'estado', 'to_state', 'SUSPENDIDO'
  );
END;
$$;


--
-- Name: admin_suspender_entidad(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_suspender_entidad(p_alerta_id uuid, p_entity_type text, p_entity_id text, p_reason text, p_evidence jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid;
  v_alerta_row record;
  v_from_state text;
  v_resolution_id uuid;
BEGIN
  -- b) Autenticación / contexto JWT (R-30)
  v_actor := app.jwt_user_id_safe();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'no_auth' USING ERRCODE='28000'; END IF;
  IF NOT (public.is_admin_activo() OR public.is_superadmin_activo()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;

  -- a) Validaciones de entrada
  IF p_alerta_id IS NULL OR p_entity_type IS NULL OR p_entity_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE='22004';
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) < 6 THEN
    RAISE EXCEPTION 'reason_too_short' USING ERRCODE='22023';
  END IF;
  IF p_entity_type NOT IN ('vendedor','comprador','producto','orden') THEN
    RAISE EXCEPTION 'entity_type_invalido' USING ERRCODE='22023';
  END IF;

  -- c) Transacción atómica con FOR UPDATE
  SELECT id, estado INTO v_alerta_row
  FROM public.admin_alerts
  WHERE id = p_alerta_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'alerta_no_encontrada' USING ERRCODE='P0002';
  END IF;
  IF v_alerta_row.estado = 'closed' THEN
    RAISE EXCEPTION 'alerta_ya_cerrada' USING ERRCODE='55000';
  END IF;

  -- Registrar transición
  v_from_state := 'activo';
  INSERT INTO public.entity_state_transitions(
    referencia_tipo, referencia_id, from_state, to_state, changed_by, reason
  ) VALUES (p_entity_type, p_entity_id, v_from_state, 'suspendido', v_actor, p_reason);

  -- Aplicar efecto (marca lógica en auth.users si es persona)
  IF p_entity_type IN ('vendedor','comprador') THEN
    UPDATE auth.users
       SET raw_app_meta_data = COALESCE(raw_app_meta_data,'{}'::jsonb)
                                || jsonb_build_object('suspended', true,
                                                      'suspended_reason', p_reason,
                                                      'suspended_at', now())
     WHERE id = p_entity_id::uuid;
  END IF;

  -- Resolución de caso (ledger)
  INSERT INTO public.admin_case_resolutions(
    referencia_tipo, referencia_id, resolution_action, resolution_reason, evidence,
    applied_side_effects, created_by
  ) VALUES (
    p_entity_type, p_entity_id, 'SUSPEND', p_reason, p_evidence,
    jsonb_build_object('alerta_id', p_alerta_id, 'state', 'suspendido'), v_actor
  ) RETURNING id INTO v_resolution_id;

  -- Cerrar alerta
  UPDATE public.admin_alerts
     SET estado = 'closed', updated_at = now()
   WHERE id = p_alerta_id;

  -- d) LEDGER WORM
  INSERT INTO auth.auditoria(id_actor, action, tipo_objetivo, id_objetivo, metadata)
  VALUES (v_actor, 'ENTITY_SUSPEND', p_entity_type, p_entity_id,
          jsonb_build_object('alerta_id', p_alerta_id, 'resolution_id', v_resolution_id,
                             'reason', p_reason));

  INSERT INTO public.h_alertas_audit(alerta_id, id_actor, accion, datos_antes, datos_despues)
  SELECT p_alerta_id, v_actor, 'SUSPEND_ENTIDAD',
         jsonb_build_object('estado', v_alerta_row.estado),
         jsonb_build_object('estado','closed','resolution_id', v_resolution_id)
  WHERE EXISTS (SELECT 1 FROM public.alertas_criticas WHERE id = p_alerta_id);

  -- f) Sincronización AGE (degradación elegante)
  BEGIN
    PERFORM 1 FROM pg_extension WHERE extname='age';
    EXECUTE format($age$
      LOAD 'age'; SET search_path = ag_catalog, "$user", public;
      SELECT * FROM cypher('smtp_posix_graph', $q$
        MATCH (n {referencia_id: '%s'}) SET n.suspended = true, n.suspended_at = timestamp()
        RETURN n
      $q$) AS (n agtype)
    $age$, p_entity_id);
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO auth.auditoria(id_actor, action, tipo_objetivo, id_objetivo, metadata)
    VALUES (v_actor, 'AGE_SYNC_FAILED', p_entity_type, p_entity_id,
            jsonb_build_object('sqlstate', SQLSTATE, 'context', 'suspend'));
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'resolution_id', v_resolution_id,
    'alerta_id', p_alerta_id,
    'entity', jsonb_build_object('type', p_entity_type, 'id', p_entity_id),
    'new_state', 'suspendido'
  );

EXCEPTION
  WHEN SQLSTATE '28000' THEN RAISE;
  WHEN SQLSTATE '42501' THEN RAISE;
  WHEN OTHERS THEN
    INSERT INTO auth.auditoria(id_actor, action, tipo_objetivo, id_objetivo, metadata)
    VALUES (v_actor, 'ENTITY_SUSPEND_ERROR', p_entity_type, p_entity_id,
            jsonb_build_object('sqlstate', SQLSTATE, 'sqlerrm', SQLERRM));
    RAISE;
END;
$_$;


--
-- Name: admin_sync_risk_alert_to_age(uuid, bigint, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_sync_risk_alert_to_age(p_vendor_id uuid, p_alert_id bigint, p_reason text, p_incident_level integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid := app.jwt_user_id_safe();
  v_age_ok boolean := false;
  v_exists bigint;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
  END IF;

  -- Validar que la alerta exista
  SELECT count(*) INTO v_exists FROM public.alertas_criticas WHERE id = p_alert_id;
  IF v_exists = 0 THEN
    RAISE EXCEPTION 'Alerta % no existe', p_alert_id USING ERRCODE = 'P0002';
  END IF;

  BEGIN LOAD 'age'; v_age_ok := true; EXCEPTION WHEN OTHERS THEN v_age_ok := false; END;

  IF v_age_ok THEN
    -- Vincular vendedor con alerta en el grafo (idempotente: MERGE)
    PERFORM cypher('smtp_posix_graph', format($c$
      MERGE (u:User {id_usuario: "%s"})
      MERGE (a:AlertaRiesgo {alert_id: %s})
        SET a.reason = "%s", a.incident_level = %s
      MERGE (u)-[r:TIENE_RIESGO_ALTO]->(a)
    $c$, p_vendor_id, p_alert_id, p_reason, p_incident_level)) IN (a);
  ELSE
    RAISE NOTICE 'AGE no disponible: alerta % no sincronizada al grafo', p_alert_id;
  END IF;
END;
$_$;


--
-- Name: admin_tablero_kpis(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_tablero_kpis() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_actor uuid; v_row app.mv_admin_control_panel%ROWTYPE;
BEGIN
  v_actor := app.jwt_user_id_safe();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'no_auth' USING ERRCODE='28000'; END IF;
  IF NOT (public.is_admin_activo() OR public.is_superadmin_activo()
          OR COALESCE(app.jwt_role_safe(),'') = 'auditor_role') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_row FROM app.mv_admin_control_panel ORDER BY refrescado_en DESC LIMIT 1;

  RETURN jsonb_build_object(
    'refreshed_at', v_row.refrescado_en,
    'alertas_activas', v_row.alertas_activas,
    'alertas_activas_alto', v_row.alertas_activas_alto,
    'alertas_24h', v_row.alertas_24h,
    'alertas_7d', v_row.alertas_7d,
    'acciones_24h', v_row.acciones_24h,
    'suspensiones_7d', v_row.suspensiones_7d,
    'admins_activos_24h', v_row.admins_activos_24h
  );
END;
$$;


--
-- Name: admin_tablero_refresh(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_tablero_refresh() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_actor uuid; v_started timestamptz := clock_timestamp();
BEGIN
  v_actor := app.jwt_user_id_safe();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'no_auth' USING ERRCODE='28000'; END IF;
  IF NOT (public.is_admin_activo() OR public.is_superadmin_activo()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;

  BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY app.mv_admin_control_panel;
  EXCEPTION WHEN OTHERS THEN
    REFRESH MATERIALIZED VIEW app.mv_admin_control_panel;
  END;

  INSERT INTO auth.auditoria(id_actor, action, tipo_objetivo, id_objetivo, metadata)
  VALUES (v_actor, 'MV_REFRESH', 'mv_admin_control_panel', NULL,
          jsonb_build_object('duration_ms',
            extract(millisecond from clock_timestamp() - v_started)::int));

  RETURN jsonb_build_object('ok', true, 'refreshed_at', now());
END;
$$;


--
-- Name: admin_unhide_dashboard_alert(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_unhide_dashboard_alert(p_alert_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_actor_id UUID := public.get_app_actor_id();
BEGIN
  IF p_alert_id IS NULL THEN
    RAISE EXCEPTION 'p_alert_id es obligatorio' USING ERRCODE = '23502';
  END IF;
  IF NOT public.is_admin_activo() THEN
    RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.admin_alerts WHERE id = p_alert_id) THEN
    RETURN jsonb_build_object('status', 'not_found', 'alert_id', p_alert_id);
  END IF;

  UPDATE public.admin_alerts
  SET oculto_en_dash = false,
      hidden_at      = NULL,
      hidden_by      = NULL,
      hidden_reason  = NULL
  WHERE id = p_alert_id AND oculto_en_dash = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'already_visible', 'alert_id', p_alert_id);
  END IF;

  -- R-38: Auditoría de reversión
  INSERT INTO auth.auditoria
    (id_actor, action, tipo_objetivo, id_objetivo, metadata, fecha_creacion)
  VALUES (
    v_actor_id, 'DASHBOARD_ALERT_UNHIDDEN', 'admin_alerts', p_alert_id::text,
    jsonb_build_object('reason', p_reason, 'unhidden_at', now()),
    now()
  );

  RETURN jsonb_build_object('status', 'ok', 'alert_id', p_alert_id, 'hidden', false);

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('status','error','message',SQLERRM,'sqlstate',SQLSTATE);
END;
$$;


--
-- Name: admin_update_administrator_access(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_administrator_access(p_admin_id uuid, p_new_role text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor_id UUID := public.get_app_actor_id();  -- R-30
  v_old_role TEXT;
BEGIN
  IF NOT public.is_superadmin_activo() THEN
    RETURN jsonb_build_object('status','forbidden');
  END IF;

  SELECT role INTO v_old_role FROM auth.users
  WHERE id = p_admin_id AND fecha_eliminacion IS NULL;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status','not_found','admin_id',p_admin_id);
  END IF;

  IF p_new_role IS NOT NULL AND p_new_role <> v_old_role THEN
    UPDATE auth.users SET role = p_new_role WHERE id = p_admin_id;

    INSERT INTO public.admin_role_lifecycle_audit
      (id_admin, id_actor, tipo_evento, role_old, role_new, reason, metadata)
    VALUES (p_admin_id, v_actor_id, 'ADMIN_ROLE_CHANGED', v_old_role, p_new_role, p_reason,
            jsonb_build_object('reason', p_reason));

    INSERT INTO auth.auditoria
      (id_actor, action, tipo_objetivo, id_objetivo, metadata, fecha_creacion)
    VALUES (v_actor_id, 'ADMIN_ACCESS_UPDATE', 'auth.users', p_admin_id::text,
      jsonb_build_object(
        'role_old', v_old_role, 'role_new', p_new_role, 'reason', p_reason
      ),
      now());
  END IF;

  RETURN jsonb_build_object(
    'status',    'ok',
    'admin_id',  p_admin_id,
    'role_old',  v_old_role,
    'role_new',  COALESCE(p_new_role, v_old_role),
    'actor_id',  v_actor_id
  );
END;
$$;


--
-- Name: admin_update_risk_setting(text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_risk_setting(p_setting_key text, p_new_value jsonb, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_actor_id  UUID  := public.get_app_actor_id();
  v_old_value JSONB;
BEGIN
  -- R-30: Validaciones de entrada
  IF p_setting_key IS NULL OR trim(p_setting_key) = '' THEN
    RAISE EXCEPTION 'p_setting_key es obligatorio' USING ERRCODE = '23502';
  END IF;
  IF p_new_value IS NULL THEN
    RAISE EXCEPTION 'p_new_value es obligatorio' USING ERRCODE = '23502';
  END IF;
  IF NOT public.is_admin_activo() THEN
    RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO' USING ERRCODE = '42501';
  END IF;

  SELECT to_jsonb(c) INTO v_old_value
  FROM public.config_seguridad c
  WHERE c.setting_key = p_setting_key;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found', 'setting_key', p_setting_key);
  END IF;

  UPDATE public.config_seguridad
  SET setting_value = p_new_value,
      fecha_actualizacion    = now(),
      updated_by    = v_actor_id
  WHERE setting_key = p_setting_key;

  -- R-38: Auditoría con antes/después
  INSERT INTO auth.auditoria
    (id_actor, action, tipo_objetivo, id_objetivo, metadata, fecha_creacion)
  VALUES (
    v_actor_id,
    'RISK_SETTING_UPDATED',
    'config_seguridad',
    p_setting_key,
    jsonb_build_object(
      'old_value', v_old_value,
      'new_value', p_new_value,
      'reason',    p_reason
    ),
    now()
  );

  RETURN jsonb_build_object('status', 'ok', 'setting_key', p_setting_key);

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('status','error','message',SQLERRM,'sqlstate',SQLSTATE);
END;
$$;


--
-- Name: admin_upsert_detection_config(text, text, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_upsert_detection_config(p_config_key text, p_config_scope text, p_config_value jsonb, p_description text DEFAULT NULL::text, p_is_active boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_rol       TEXT;
  v_actor_id  UUID;   -- R-30
  v_config_id UUID;
  v_era_nuevo BOOLEAN := false;
BEGIN
  v_rol := app.jwt_role_safe();
  IF v_rol NOT IN ('administrador_role','superadmin_role') THEN
    RETURN jsonb_build_object(
      'status',  'error',
      'message', 'Acceso denegado: se requiere rol administrador o superadmin'
    );
  END IF;

  IF p_config_key IS NULL OR trim(p_config_key) = '' THEN
    RETURN jsonb_build_object('status','error','message','p_config_key es obligatorio');
  END IF;
  IF p_config_scope IS NULL OR trim(p_config_scope) = '' THEN
    RETURN jsonb_build_object('status','error','message','p_config_scope es obligatorio');
  END IF;
  IF p_config_value IS NULL THEN
    RETURN jsonb_build_object('status','error','message','p_config_value es obligatorio');
  END IF;

  v_actor_id := public.get_app_actor_id();  -- R-30: wrapper canónico

  SELECT NOT EXISTS (
    SELECT 1 FROM public.detection_configurations
    WHERE config_key = p_config_key AND fecha_eliminacion IS NULL
  ) INTO v_era_nuevo;

  INSERT INTO public.detection_configurations
    (config_key, config_scope, config_value, description, is_active, updated_by, fecha_actualizacion)
  VALUES
    (p_config_key, p_config_scope, p_config_value, p_description, p_is_active, v_actor_id, now())
  ON CONFLICT (config_key)
  DO UPDATE SET
    config_scope = EXCLUDED.config_scope,
    config_value = EXCLUDED.config_value,
    description  = EXCLUDED.description,
    is_active    = EXCLUDED.is_active,
    updated_by   = v_actor_id,
    fecha_actualizacion   = now()
  RETURNING id INTO v_config_id;

  INSERT INTO auth.auditoria
    (id_actor, action, tipo_objetivo, id_objetivo, metadata)
  VALUES (
    v_actor_id,
    'ADMIN_UPSERT_DETECTION_CONFIG',
    'detection_configurations',
    v_config_id::text,
    jsonb_build_object(
      'config_key',   p_config_key,
      'config_scope', p_config_scope,
      'is_active',    p_is_active,
      'fue_nuevo',    v_era_nuevo
    )
  );

  RETURN jsonb_build_object(
    'status',     'ok',
    'config_id',  v_config_id,
    'config_key', p_config_key,
    'fue_nuevo',  v_era_nuevo
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'status',   'error',
    'message',  SQLERRM,
    'sqlstate', SQLSTATE
  );
END;
$$;


--
-- Name: admin_validate_administrator_operational_continuity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_validate_administrator_operational_continuity(p_admin_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_preview JSONB;
BEGIN
  IF NOT public.is_superadmin_activo() THEN
    RETURN jsonb_build_object('status','forbidden');
  END IF;

  v_preview := public.admin_preview_administrator_responsibility_scope(p_admin_id);

  IF v_preview->>'status' <> 'ok' THEN
    RETURN v_preview;
  END IF;

  RETURN jsonb_build_object(
    'status',         'ok',
    'admin_id',       p_admin_id,
    'can_deactivate', true,
    'hard_blockers',  jsonb_build_array(),
    'warnings',       jsonb_build_array(),
    'scope_preview',  v_preview
  );
END;
$$;


--
-- Name: admin_visibilidad_vendedor_regulada(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_visibilidad_vendedor_regulada(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_estado text; v_deleted timestamptz;
  v_geom   geometry; v_visible boolean := false;
BEGIN
  IF p_user_id IS NULL THEN RETURN false; END IF;

  SELECT estado_administrativo, fecha_eliminacion
    INTO v_estado, v_deleted
    FROM auth.users WHERE id = p_user_id;

  IF v_estado IS NULL OR v_deleted IS NOT NULL OR v_estado <> 'active' THEN
    RETURN false;
  END IF;

  SELECT last_transaction_geom INTO v_geom
    FROM public.user_locations
   WHERE id_usuario = p_user_id
   ORDER BY fecha_captura DESC LIMIT 1;

  -- Vendedor con ubicación → validar zona + horario
  IF v_geom IS NULL THEN
    -- Vendedor fijo (ubicaciones.geom canónico)
    SELECT geom INTO v_geom FROM auth.ubicaciones
     WHERE id_usuario = p_user_id AND fecha_eliminacion IS NULL
     ORDER BY fecha_actualizacion DESC LIMIT 1;
  END IF;

  IF v_geom IS NULL THEN
    RETURN false;
  END IF;

  SELECT true INTO v_visible
   WHERE EXISTS (
     SELECT 1
       FROM public.geo_zones z
       JOIN public.zone_schedules zs ON zs.id_zona = z.id_zona
      WHERE z.is_active = true AND z.fecha_eliminacion IS NULL
        AND zs.is_active = true AND zs.fecha_eliminacion IS NULL
        AND z.zone_type IN ('open_market','pilot')
        AND ST_Within(v_geom, z.geom)
        AND zs.day_of_week = EXTRACT(DOW FROM now())::int
        AND CURRENT_TIME BETWEEN zs.start_time AND zs.end_time
   );

  RETURN COALESCE(v_visible, false);
END;
$$;


--
-- Name: ajustar_billetera_admin(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ajustar_billetera_admin(p_billetera_id uuid, p_nuevo_saldo numeric, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_antes NUMERIC; v_dif NUMERIC;
  v_actor UUID := public.get_app_actor_id();
BEGIN
  IF NOT public.is_admin_activo() THEN
    RAISE EXCEPTION 'acceso denegado' USING ERRCODE='42501';
  END IF;
  IF length(COALESCE(p_motivo,'')) < 8 THEN
    RAISE EXCEPTION 'motivo obligatorio (mínimo 8 chars)' USING ERRCODE='22023';
  END IF;
  IF p_nuevo_saldo IS NULL OR p_nuevo_saldo < 0 THEN
    RAISE EXCEPTION 'saldo inválido' USING ERRCODE='22023';
  END IF;

  SELECT saldo INTO v_antes FROM auth.billetera WHERE id=p_billetera_id FOR UPDATE;
  IF v_antes IS NULL THEN
    RAISE EXCEPTION 'billetera inexistente' USING ERRCODE='P0001';
  END IF;
  v_dif := p_nuevo_saldo - v_antes;

  UPDATE auth.billetera SET saldo=p_nuevo_saldo, actualizado_en=now()
   WHERE id=p_billetera_id;

  INSERT INTO public.moderacion_h_audit(accion, entidad_tipo, entidad_id,
    valor_antes, valor_despues, diferencia, motivo, id_actor)
  VALUES ('BILLETERA_AJUSTE','billetera',p_billetera_id,
    jsonb_build_object('saldo',v_antes),
    jsonb_build_object('saldo',p_nuevo_saldo),
    v_dif, p_motivo, v_actor);

  PERFORM public._age_reflejar_ajuste_billetera(v_actor, p_billetera_id, v_dif);

  RETURN jsonb_build_object('ok',true,'antes',v_antes,'despues',p_nuevo_saldo,'diferencia',v_dif);
END $$;


--
-- Name: archivar_reportes_antiguos(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archivar_reportes_antiguos(p_dias integer DEFAULT 90) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_count INT;
BEGIN
  UPDATE public.reportes_seguridad
     SET archivado=true, archivado_en=now()
   WHERE archivado=false
     AND fecha_reporte < CURRENT_DATE - p_dias;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END $$;


--
-- Name: archive_old_logs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_old_logs() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cutoff_date TIMESTAMP;
    v_policy audit.log_retention_policy%ROWTYPE;
BEGIN
    FOR v_policy IN 
        SELECT * FROM audit.log_retention_policy 
        WHERE is_active = TRUE
    LOOP
        v_cutoff_date := NOW() - (v_policy.retention_days || ' days')::INTERVAL;
        
        -- Mover a archive storage
        UPDATE audit.logs
        SET is_archived = TRUE
        WHERE tipo_evento = v_policy.tipo_evento
          AND fecha_creacion < v_cutoff_date
          AND is_archived = FALSE;
        
        -- Opcionalmente, comprimir y borrar
        -- DELETE FROM audit.logs WHERE ... (después de backup)
    END LOOP;
END;
$$;


--
-- Name: archive_reporte_seguridad(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_reporte_seguridad(p_older_than_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_actor uuid := app.jwt_user_id_safe(); v_n int;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
  END IF;
  IF p_older_than_days < 30 THEN
    RAISE EXCEPTION 'archivar < 30 días no permitido' USING ERRCODE = '22003';
  END IF;

  UPDATE public.reportes_seguridad
     SET archivado = true, archivado_at = now()
   WHERE archivado = false
     AND fecha_reporte < (current_date - p_older_than_days);
  GET DIAGNOSTICS v_n = ROW_COUNT;

  INSERT INTO auth.auditoria(id_actor, action, target_kind, id_objetivo, payload)
  VALUES (v_actor, 'reportes_archived', 'reporte', NULL,
          jsonb_build_object('count', v_n, 'older_than_days', p_older_than_days));

  RETURN jsonb_build_object('success', true, 'archived', v_n);
END;
$$;


--
-- Name: assert_buyer_actor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_buyer_actor(p_id_comprador uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_actor_id UUID := auth.jwt_user_id_safe();
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'ACTOR_NO_IDENTIFICADO'
      USING ERRCODE = '28000';
  END IF;
  IF v_actor_id <> p_id_comprador THEN
    RAISE EXCEPTION 'BUYER_ID_NO_COINCIDE_CON_ACTOR_AUTORIZADO'
      USING ERRCODE = '42501';
  END IF;
  RETURN v_actor_id;
END;
$$;


--
-- Name: assert_purchase_entities(uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_purchase_entities(p_id_comprador uuid, p_product_id uuid, p_id_vendedor uuid, p_total_amount numeric) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_buyer   RECORD;
  v_seller  RECORD;
  v_product RECORD;
BEGIN
  -- Comprador
  SELECT id, is_active, fecha_eliminacion INTO v_buyer
  FROM auth.users WHERE id = p_id_comprador;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'COMPRADOR_NO_EXISTE' USING ERRCODE = 'P0002';
  END IF;
  IF v_buyer.is_active IS DISTINCT FROM true OR v_buyer.fecha_eliminacion IS NOT NULL THEN
    RAISE EXCEPTION 'COMPRADOR_INACTIVO_O_ELIMINADO_LOGICAMENTE' USING ERRCODE = 'P0001';
  END IF;

  -- Vendedor
  SELECT id, is_active, fecha_eliminacion INTO v_seller
  FROM auth.users WHERE id = p_id_vendedor;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'VENDEDOR_NO_EXISTE' USING ERRCODE = 'P0002';
  END IF;
  IF v_seller.is_active IS DISTINCT FROM true OR v_seller.fecha_eliminacion IS NOT NULL THEN
    RAISE EXCEPTION 'VENDEDOR_INACTIVO_O_ELIMINADO_LOGICAMENTE' USING ERRCODE = 'P0001';
  END IF;

  -- Autocompra
  IF p_id_comprador = p_id_vendedor THEN
    RAISE EXCEPTION 'AUTOCOMPRA_PROHIBIDA' USING ERRCODE = '23514';
  END IF;

  -- Producto
  SELECT id, id_vendedor, is_active, fecha_eliminacion, price INTO v_product
  FROM auth.productos WHERE id = p_product_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PRODUCTO_NO_EXISTE' USING ERRCODE = 'P0002';
  END IF;
  IF v_product.is_active IS DISTINCT FROM true OR v_product.fecha_eliminacion IS NOT NULL THEN
    RAISE EXCEPTION 'PRODUCTO_INACTIVO_O_ELIMINADO_LOGICAMENTE' USING ERRCODE = 'P0001';
  END IF;
  IF v_product.id_vendedor <> p_id_vendedor THEN
    RAISE EXCEPTION 'PRODUCTO_NO_PERTENECE_AL_VENDEDOR_INDICADO' USING ERRCODE = '23514';
  END IF;

  -- Monto
  IF p_total_amount IS NULL OR p_total_amount <= 0 THEN
    RAISE EXCEPTION 'MONTO_INVALIDO' USING ERRCODE = '22023';
  END IF;
END;
$$;


--
-- Name: audit_admin_action(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_admin_action() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO audit.admin_actions (
        id_admin, tipo_accion, resource_type, resource_id,
        changes_before, changes_after
    ) VALUES (
        CURRENT_USER_ID(),
        CASE 
            WHEN TG_OP = 'INSERT' THEN 'CREATE'
            WHEN TG_OP = 'UPDATE' THEN 'UPDATE'
            WHEN TG_OP = 'DELETE' THEN 'DELETE'
        END,
        'admin_users',
        NEW.id_admin::TEXT,
        to_jsonb(OLD),
        to_jsonb(NEW)
    );
    RETURN NEW;
END;
$$;


--
-- Name: audit_risk_threshold(text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_risk_threshold(p_key text, p_new_value numeric, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'audit', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_role  TEXT := COALESCE((current_setting('request.jwt.claims', true)::jsonb ->> 'role'),'');
  v_actor UUID := public.get_app_actor_id();
  v_old   JSONB;
BEGIN
  IF v_role NOT IN ('admin','super_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason)='' THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE='23514';
  END IF;

  SELECT jsonb_build_object('value_num', value_num) INTO v_old
    FROM public.config_seguridad WHERE key = p_key;

  INSERT INTO public.config_seguridad(key, value_num, fecha_actualizacion, updated_by)
  VALUES (p_key, p_new_value, NOW(), v_actor)
  ON CONFLICT (key) DO UPDATE
    SET value_num=EXCLUDED.value_num, fecha_actualizacion=NOW(), updated_by=v_actor;

  INSERT INTO audit.config_seguridad_audit(key, old_value, new_value, id_actor, reason)
  VALUES (p_key, v_old, jsonb_build_object('value_num', p_new_value), v_actor, p_reason);

  PERFORM public.log_admin_risk_event(
    'ADMIN_UPDATE_RISK_THRESHOLD','config_seguridad',p_key,p_reason,
    v_old, jsonb_build_object('value_num', p_new_value)
  );

  RETURN jsonb_build_object('ok',TRUE,'key',p_key,'new_value',p_new_value);
END;
$$;


--
-- Name: buscar_vendedores_cercanos(uuid, double precision, double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.buscar_vendedores_cercanos(p_id_comprador uuid, p_lat double precision, p_lng double precision, p_radius_meters double precision, p_limit integer DEFAULT 100) RETURNS TABLE(id_vendedor uuid, distancia_metros double precision, rank_score numeric, is_recommended boolean, thumbnail_url text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid;
  v_t0    timestamptz := clock_timestamp();
  v_count int;
BEGIN
  -- (a) Autorización JWT
  v_actor := auth.jwt_user_id_safe();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'JWT_ACTOR_INVALIDO' USING ERRCODE='P0001';
  END IF;
  IF v_actor <> p_id_comprador THEN
    RAISE EXCEPTION 'JWT_BUYER_MISMATCH' USING ERRCODE='P0001';
  END IF;

  -- (b) Validación de contrato (R-30)
  IF p_lat  IS NULL OR p_lat  NOT BETWEEN -90  AND 90  THEN
     RAISE EXCEPTION 'PARAM_LAT_INVALIDO' USING ERRCODE='22023'; END IF;
  IF p_lng  IS NULL OR p_lng  NOT BETWEEN -180 AND 180 THEN
     RAISE EXCEPTION 'PARAM_LNG_INVALIDO' USING ERRCODE='22023'; END IF;
  IF p_radius_meters IS NULL OR p_radius_meters <= 0 OR p_radius_meters > 50000 THEN
     RAISE EXCEPTION 'PARAM_RADIO_FUERA_DE_RANGO' USING ERRCODE='22023'; END IF;
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 250 THEN
     RAISE EXCEPTION 'PARAM_LIMIT_FUERA_DE_RANGO' USING ERRCODE='22023'; END IF;

  -- (c) Consulta canónica
  RETURN QUERY
  WITH base AS (
    SELECT sa.id_vendedor,
           ST_Distance(
             sa.geom::geography,
             ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography
           ) AS distancia_metros
    FROM   public.sellers_active sa
    WHERE  ST_DWithin(
             sa.geom::geography,
             ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography,
             p_radius_meters)
    ORDER  BY distancia_metros ASC
    LIMIT  p_limit
  ),
  scored AS (
    SELECT b.id_vendedor,
           b.distancia_metros,
           COALESCE(public.get_age_rank_score(
             'kambalache_marketplace_graph','Buyer','Seller',
             p_id_comprador, b.id_vendedor), 0) AS rank_score
    FROM   base b
  )
  SELECT s.id_vendedor,
         s.distancia_metros,
         s.rank_score,
         (s.rank_score > 0)          AS is_recommended,
         t.thumbnail_url             AS thumbnail_url
  FROM   scored s
  LEFT JOIN public.seller_primary_thumbnail t
         ON t.id_vendedor = s.id_vendedor
  ORDER  BY s.distancia_metros ASC;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- (d) Auditoría opcional
  INSERT INTO public.radar_query_audit(id_comprador, p_lat, p_lng, radius_meters, result_count, latency_ms)
  VALUES (p_id_comprador, p_lat, p_lng, p_radius_meters, v_count,
          EXTRACT(MILLISECONDS FROM clock_timestamp() - v_t0)::int);

EXCEPTION WHEN OTHERS THEN
  -- Manejo diferenciado por SQLSTATE (R-37)
  RAISE;
END; $$;


--
-- Name: calculate_user_reputation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_user_reputation(p_usuario_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_avg_rating NUMERIC;
    v_total_ratings INTEGER;
    v_intercambios_completados INTEGER;
    v_intercambios_cancelados INTEGER;
    v_antiguedad_dias INTEGER;
    v_puntos_total INTEGER;
    v_risk_score NUMERIC;
    v_reputacion NUMERIC;
    v_nivel VARCHAR(20);
BEGIN
    -- Verificar que el usuario existe
    IF NOT EXISTS (SELECT 1 FROM usuarios WHERE id = p_usuario_id) THEN
        RETURN json_build_object('success', FALSE, 'error', 'Usuario no encontrado');
    END IF;

    -- Rating promedio recibido
    SELECT COALESCE(ROUND(AVG(puntuacion)::NUMERIC, 2), 0), COUNT(*)
    INTO v_avg_rating, v_total_ratings
    FROM ratings WHERE calificado_id = p_usuario_id;

    -- Intercambios completados y cancelados
    SELECT
        COUNT(*) FILTER (WHERE e.nombre = 'completado'),
        COUNT(*) FILTER (WHERE e.nombre = 'cancelaciones')
    INTO v_intercambios_completados, v_intercambios_cancelados
    FROM intercambios i
    JOIN estados_intercambio e ON i.estado_id = e.id
    WHERE i.usuario_ofertante_id = p_usuario_id OR i.usuario_receptor_id = p_usuario_id;

    -- Antigüedad
    SELECT EXTRACT(DAY FROM NOW() - created_at)::INTEGER INTO v_antiguedad_dias
    FROM usuarios WHERE id = p_usuario_id;

    -- Puntos totales
    SELECT COALESCE(total_acumulado, 0) INTO v_puntos_total
    FROM puntos_cuenta WHERE id_usuario = p_usuario_id;

    -- Risk score
    SELECT COALESCE(score, 0) INTO v_risk_score
    FROM user_risk_scores WHERE id_usuario = p_usuario_id;

    -- Cálculo de reputación (0-100)
    v_reputacion := LEAST(100, GREATEST(0,
        (v_avg_rating * 10) +                        -- Max 50 puntos por rating
        (LEAST(v_intercambios_completados, 20) * 1.5) + -- Max 30 por trueques
        (LEAST(v_antiguedad_dias, 365) * 0.02) +     -- Max 7.3 por antigüedad
        (LEAST(v_puntos_total, 1000) * 0.01) -        -- Max 10 por puntos
        (v_intercambios_cancelados * 2) -              -- Penalización cancelados
        (v_risk_score * 0.3)                           -- Penalización riesgo
    ));

    -- Determinar nivel
    v_nivel := CASE
        WHEN v_reputacion >= 80 THEN 'excelente'
        WHEN v_reputacion >= 60 THEN 'buena'
        WHEN v_reputacion >= 40 THEN 'regular'
        WHEN v_reputacion >= 20 THEN 'baja'
        ELSE 'nueva'
    END;

    RETURN json_build_object(
        'success', TRUE,
        'id_usuario', p_usuario_id,
        'reputacion', ROUND(v_reputacion, 2),
        'nivel', v_nivel,
        'detalles', json_build_object(
            'rating_promedio', v_avg_rating,
            'total_ratings', v_total_ratings,
            'intercambios_completados', v_intercambios_completados,
            'intercambios_cancelados', v_intercambios_cancelados,
            'antiguedad_dias', v_antiguedad_dias,
            'puntos_acumulados', v_puntos_total,
            'risk_score', v_risk_score
        )
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object('success', FALSE, 'error', SQLERRM);
END;
$$;


--
-- Name: FUNCTION calculate_user_reputation(p_usuario_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calculate_user_reputation(p_usuario_id uuid) IS 'Calcula la reputación de un usuario (0-100) basada en ratings, intercambios, antigüedad, puntos y riesgo. v3.12';


--
-- Name: check_failed_logins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_failed_logins() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'auth', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_recientes integer;
BEGIN
    IF NEW.exitoso = false THEN
        SELECT count(*) INTO v_recientes
          FROM auth.login_attempts
         WHERE email = NEW.email
           AND exitoso = false
           AND fecha > now() - interval '15 minutes';

        IF v_recientes >= 5 THEN
            RAISE EXCEPTION 'CREDENCIALES_BLOQUEADAS: demasiados intentos fallidos'
                USING ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: check_riesgo_cuentas_espejo(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_riesgo_cuentas_espejo(p_window interval DEFAULT '30 days'::interval) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $_$
DECLARE
    v_alerts integer := 0;
    r record;
BEGIN
    FOR r IN
        WITH signals AS (
            SELECT device_fingerprint, ip_hash, id_entidad::uuid AS uid
            FROM public.fraud_signals
            WHERE fecha_creacion >= now() - p_window
              AND tipo_entidad IN ('vendedor', 'comprador')
              AND (device_fingerprint IS NOT NULL OR ip_hash IS NOT NULL)
              AND id_entidad ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        )
        SELECT device_fingerprint, ip_hash, array_agg(DISTINCT uid) AS ids
        FROM signals
        GROUP BY 1, 2
        HAVING count(DISTINCT uid) >= 2
    LOOP
        IF coalesce(array_length(r.ids, 1), 0) >= 2 THEN
            INSERT INTO public.fraud_alerts
                (tipo_alerta, primary_entity_id, primary_entity_kind,
                 related_entity_ids, severity, evidence)
            VALUES
                ('cuentas_espejo', r.ids[1], 'user', r.ids[2:],
                 'high',
                 jsonb_build_object(
                     'device_fingerprint', r.device_fingerprint,
                     'ip_hash', r.ip_hash,
                     'cuentas_detectadas', r.ids));

            INSERT INTO public.user_risk_scores
                (id_usuario, score, factores_riesgo, ultima_evaluacion)
            SELECT u.id, 15, '["cuentas_espejo"]'::jsonb, now()
            FROM auth.users u
            WHERE u.id = ANY(r.ids)
            ON CONFLICT (id_usuario) DO UPDATE
            SET score = public.user_risk_scores.score + 15,
                factores_riesgo = coalesce(public.user_risk_scores.factores_riesgo, '[]'::jsonb)
                                  || '["cuentas_espejo"]'::jsonb,
                ultima_evaluacion = now(),
                fecha_actualizacion = now();

            v_alerts := v_alerts + 1;
        END IF;
    END LOOP;

    RETURN v_alerts;
END;
$_$;


--
-- Name: check_riesgo_ghosting_vendedor(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_riesgo_ghosting_vendedor(p_stale_after interval DEFAULT '7 days'::interval) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_alerts integer := 0;
    r record;
BEGIN
    FOR r IN
        SELECT i.receptor_id AS id_vendedor,
               count(*) AS n_estancados,
               max(i.actualizado_en) AS ultimo_movimiento
        FROM auth.intercambios i
        WHERE i.estado = 'propuesta'
          AND i.actualizado_en < now() - p_stale_after
          AND i.receptor_id IS NOT NULL
        GROUP BY i.receptor_id
    LOOP
        INSERT INTO public.fraud_alerts
            (tipo_alerta, primary_entity_id, primary_entity_kind, severity, evidence)
        VALUES
            ('ghosting_vendedor', r.id_vendedor, 'user', 'medium',
             jsonb_build_object(
                 'intercambios_estancados', r.n_estancados,
                 'ultimo_movimiento', r.ultimo_movimiento));

        INSERT INTO public.user_risk_scores
            (id_usuario, score, factores_riesgo, ultima_evaluacion)
        VALUES (r.id_vendedor, 10, '["ghosting_vendedor"]'::jsonb, now())
        ON CONFLICT (id_usuario) DO UPDATE
        SET score = public.user_risk_scores.score + 10,
            factores_riesgo = coalesce(public.user_risk_scores.factores_riesgo, '[]'::jsonb)
                              || '["ghosting_vendedor"]'::jsonb,
            ultima_evaluacion = now(),
            fecha_actualizacion = now();

        v_alerts := v_alerts + 1;
    END LOOP;

    RETURN v_alerts;
END;
$$;


--
-- Name: check_riesgo_lavado_puntos(interval, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_riesgo_lavado_puntos(p_window interval DEFAULT '24:00:00'::interval, p_min_movimientos integer DEFAULT 20) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_alerts integer := 0;
    r record;
BEGIN
    FOR r IN
        SELECT pc.id_usuario,
               m.cuenta_id,
               count(*) AS n_movs,
               coalesce(sum(m.cantidad) FILTER (WHERE t.es_credito), 0)      AS total_creditos,
               coalesce(sum(abs(m.cantidad)) FILTER (WHERE NOT t.es_credito), 0) AS total_debitos
        FROM public.movimientos_puntos m
        JOIN public.tipos_movimiento_puntos t ON t.id = m.tipo_id
        JOIN public.puntos_cuenta pc ON pc.id = m.cuenta_id
        WHERE m.created_at >= now() - p_window
        GROUP BY pc.id_usuario, m.cuenta_id
        HAVING count(*) >= p_min_movimientos
           AND count(*) FILTER (WHERE t.es_credito) > 0
           AND count(*) FILTER (WHERE NOT t.es_credito) > 0
    LOOP
        INSERT INTO public.fraud_alerts
            (tipo_alerta, primary_entity_id, primary_entity_kind, severity, evidence)
        VALUES
            ('lavado_puntos', r.id_usuario, 'user', 'high',
             jsonb_build_object(
                 'cuenta_id', r.cuenta_id,
                 'movimientos', r.n_movs,
                 'creditos', r.total_creditos,
                 'debitos', r.total_debitos));

        -- NOTA (costura de id-spaces): no se actualiza user_risk_scores aqui.
        -- La cola de puntos es legacy: puntos_cuenta.id_usuario -> public.usuarios(id),
        -- mientras user_risk_scores.id_usuario -> auth.users(id). Son id-spaces
        -- distintos; un upsert directo violaria la FK. La deteccion se materializa
        -- unicamente en fraud_alerts (primary_entity_id = id del usuario legacy;
        -- sin FK sobre ese campo, valido).

        v_alerts := v_alerts + 1;
    END LOOP;

    RETURN v_alerts;
END;
$$;


--
-- Name: confirmar_compra(uuid, uuid, uuid, numeric, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirmar_compra(p_id_comprador uuid, p_product_id uuid, p_id_vendedor uuid, p_total_amount numeric, p_buyer_lat double precision, p_buyer_lng double precision) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order_id     UUID;
  v_is_near      BOOLEAN;
  v_buyer_point  GEOGRAPHY(POINT, 4326);
BEGIN
  -- 1) Identidad real
  PERFORM public.assert_buyer_actor(p_id_comprador);

  -- 2) Integridad
  PERFORM public.assert_purchase_entities(
    p_id_comprador, p_product_id, p_id_vendedor, p_total_amount
  );

  -- 3) Proximidad
  v_is_near := public.validar_proximidad_compra(
    p_buyer_lat, p_buyer_lng, p_id_vendedor, 100
  );
  IF NOT v_is_near THEN
    RAISE EXCEPTION 'LA_COMPRA_EXCEDE_LA_DISTANCIA_PRESENCIAL_PERMITIDA'
      USING ERRCODE = '22023';
  END IF;

  -- 4) Persistir orden (fuente primaria)
  INSERT INTO auth.ordenes (
    id, id_comprador, id_producto, id_vendedor,
    total, estado, fecha_creacion
  ) VALUES (
    uuid_generate_v4(), p_id_comprador, p_product_id, p_id_vendedor,
    p_total_amount, 'CONFIRMED', now()
  )
  RETURNING id INTO v_order_id;

  -- 5) Actualizar último geocontexto del comprador
  v_buyer_point := ST_SetSRID(ST_MakePoint(p_buyer_lng, p_buyer_lat), 4326)::geography;
  UPDATE auth.ubicaciones
     SET last_transaction_geom = v_buyer_point::geometry,
         fecha_actualizacion = now()
   WHERE id_usuario   = p_id_comprador
     AND is_active = true
     AND fecha_eliminacion IS NULL;

  -- 6) Persistir evidencia geoespacial histórica
  INSERT INTO public.order_geo_evidence (
    id_orden, id_comprador, id_vendedor, geom, metadata
  ) VALUES (
    v_order_id, p_id_comprador, p_id_vendedor,
    ST_SetSRID(ST_MakePoint(p_buyer_lng, p_buyer_lat), 4326),
    jsonb_build_object('geo_audited', true)
  );

  -- 7) Contrato de salida JSONB (R-30)
  RETURN jsonb_build_object(
    'status',              'OK',
    'order_id',            v_order_id,
    'id_comprador',       p_id_comprador,
    'id_vendedor',      p_id_vendedor,
    'product_id',          p_product_id,
    'total_amount',        p_total_amount,
    'geo_audited',         true,
    'graph_sync_expected', true
  );
END;
$$;


--
-- Name: confirmar_compra_idempotente(uuid, uuid, uuid, numeric, double precision, double precision, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirmar_compra_idempotente(p_id_comprador uuid, p_product_id uuid, p_id_vendedor uuid, p_total_amount numeric, p_buyer_lat double precision, p_buyer_lng double precision, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor_id          UUID;
  v_existing_order_id UUID;
  v_response          JSONB;
BEGIN
  v_actor_id := public.assert_buyer_actor(p_id_comprador);

  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_REQUERIDA' USING ERRCODE = '22023';
  END IF;

  -- Replay: si ya existe, devolver misma id_orden
  SELECT id_orden INTO v_existing_order_id
  FROM public.purchase_idempotency_keys
  WHERE id_actor = v_actor_id
    AND idempotency_key = p_idempotency_key;

  IF v_existing_order_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'status',   'IDEMPOTENT_REPLAY',
      'order_id', v_existing_order_id
    );
  END IF;

  -- Reserva de clave
  INSERT INTO public.purchase_idempotency_keys (
    id_actor, idempotency_key, estado
  ) VALUES (
    v_actor_id, p_idempotency_key, 'PENDING'
  )
  ON CONFLICT (id_actor, idempotency_key) DO NOTHING;

  -- Ejecución real
  v_response := public.confirmar_compra(
    p_id_comprador, p_product_id, p_id_vendedor,
    p_total_amount, p_buyer_lat, p_buyer_lng
  );

  -- Consolidación
  UPDATE public.purchase_idempotency_keys
     SET id_orden   = (v_response ->> 'order_id')::uuid,
         estado     = 'COMPLETED',
         fecha_actualizacion = now()
   WHERE id_actor = v_actor_id
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: contar_vendedores_en_radio(double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contar_vendedores_en_radio(p_lat double precision, p_lng double precision, p_radius_meters double precision) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog'
    AS $$
DECLARE v_count int;
BEGIN
  IF p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180 THEN
    RAISE EXCEPTION 'PARAM_COORDS_INVALIDAS' USING ERRCODE='22023';
  END IF;
  IF p_radius_meters <= 0 OR p_radius_meters > 50000 THEN
    RAISE EXCEPTION 'PARAM_RADIO_FUERA_DE_RANGO' USING ERRCODE='22023';
  END IF;

  SELECT COUNT(*) INTO v_count
  FROM public.sellers_active sa
  WHERE ST_DWithin(
    sa.geom::geography,
    ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography,
    p_radius_meters);

  RETURN v_count;
END; $$;


--
-- Name: create_admin_alert(character varying, character varying, text, uuid, character varying, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_admin_alert(p_tipo character varying, p_severidad character varying, p_descripcion text, p_usuario_afectado_id uuid DEFAULT NULL::uuid, p_titulo character varying DEFAULT NULL::character varying, p_referencia_id uuid DEFAULT NULL::uuid, p_referencia_tipo character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_tipo_id INTEGER;
    v_alerta_id UUID;
    v_titulo_final VARCHAR;
BEGIN
    -- Verificar permisos
    IF current_user_role() != 'admin' THEN
        RAISE EXCEPTION 'Acceso denegado: se requiere rol admin' USING ERRCODE = 'P0003';
    END IF;

    -- Validar tipo de alerta
    SELECT id INTO v_tipo_id FROM tipos_alerta WHERE nombre = p_tipo;
    IF NOT FOUND THEN
        RETURN json_build_object('success', FALSE, 'error', 'Tipo de alerta inválido: ' || p_tipo);
    END IF;

    -- Validar severidad
    IF p_severidad NOT IN ('baja', 'media', 'alta', 'critica') THEN
        RETURN json_build_object('success', FALSE, 'error', 'Severidad inválida. Use: baja, media, alta, critica');
    END IF;

    v_titulo_final := COALESCE(p_titulo, 'Alerta: ' || p_tipo || ' (' || p_severidad || ')');

    INSERT INTO admin_alerts (tipo_alerta_id, severidad, titulo, descripcion, usuario_afectado_id, referencia_id, referencia_tipo)
    VALUES (v_tipo_id, p_severidad, v_titulo_final, p_descripcion, p_usuario_afectado_id, p_referencia_id, p_referencia_tipo)
    RETURNING id INTO v_alerta_id;

    RETURN json_build_object(
        'success', TRUE,
        'alerta_id', v_alerta_id,
        'mensaje', 'Alerta administrativa creada'
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object('success', FALSE, 'error', SQLERRM);
END;
$$;


--
-- Name: FUNCTION create_admin_alert(p_tipo character varying, p_severidad character varying, p_descripcion text, p_usuario_afectado_id uuid, p_titulo character varying, p_referencia_id uuid, p_referencia_tipo character varying); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_admin_alert(p_tipo character varying, p_severidad character varying, p_descripcion text, p_usuario_afectado_id uuid, p_titulo character varying, p_referencia_id uuid, p_referencia_tipo character varying) IS 'Crea una alerta administrativa manualmente. Requiere rol admin. v3.12';


--
-- Name: create_rating(uuid, uuid, uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_rating(p_usuario_id uuid, p_calificado_id uuid, p_articulo_id uuid DEFAULT NULL::uuid, p_trueque_id uuid DEFAULT NULL::uuid, p_puntuacion integer DEFAULT 5, p_comentario text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_rating_id UUID;
BEGIN
    -- Validaciones
    IF p_usuario_id = p_calificado_id THEN
        RETURN json_build_object('success', FALSE, 'error', 'No puedes calificarte a ti mismo');
    END IF;

    IF p_puntuacion NOT BETWEEN 1 AND 5 THEN
        RETURN json_build_object('success', FALSE, 'error', 'Puntuación debe estar entre 1 y 5');
    END IF;

    IF p_articulo_id IS NULL AND p_trueque_id IS NULL THEN
        RETURN json_build_object('success', FALSE, 'error', 'Debe especificar un artículo o trueque');
    END IF;

    -- Si es por trueque, verificar que el usuario participó
    IF p_trueque_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM intercambios
            WHERE id = p_trueque_id
              AND (usuario_ofertante_id = p_usuario_id OR usuario_receptor_id = p_usuario_id)
        ) THEN
            RETURN json_build_object('success', FALSE, 'error', 'Solo participantes del trueque pueden calificar');
        END IF;

        -- Verificar que el trueque está completado
        IF NOT EXISTS (
            SELECT 1 FROM intercambios i
            JOIN estados_intercambio e ON i.estado_id = e.id
            WHERE i.id = p_trueque_id AND e.nombre = 'completado'
        ) THEN
            RETURN json_build_object('success', FALSE, 'error', 'El trueque debe estar completado para calificar');
        END IF;

        -- Verificar que no haya calificado ya este trueque
        IF EXISTS (
            SELECT 1 FROM ratings WHERE id_usuario = p_usuario_id AND trueque_id = p_trueque_id
        ) THEN
            RETURN json_build_object('success', FALSE, 'error', 'Ya calificaste este trueque');
        END IF;
    END IF;

    INSERT INTO ratings (id_usuario, calificado_id, articulo_id, trueque_id, puntuacion, comentario)
    VALUES (p_usuario_id, p_calificado_id, p_articulo_id, p_trueque_id, p_puntuacion, p_comentario)
    RETURNING id INTO v_rating_id;

    RETURN json_build_object(
        'success', TRUE,
        'rating_id', v_rating_id,
        'mensaje', 'Calificación registrada exitosamente'
    );

EXCEPTION
    WHEN unique_violation THEN
        RETURN json_build_object('success', FALSE, 'error', 'Ya existe una calificación para este trueque');
    WHEN OTHERS THEN
        RETURN json_build_object('success', FALSE, 'error', SQLERRM);
END;
$$;


--
-- Name: FUNCTION create_rating(p_usuario_id uuid, p_calificado_id uuid, p_articulo_id uuid, p_trueque_id uuid, p_puntuacion integer, p_comentario text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_rating(p_usuario_id uuid, p_calificado_id uuid, p_articulo_id uuid, p_trueque_id uuid, p_puntuacion integer, p_comentario text) IS 'Crea una calificación de un usuario a otro, asociada a un artículo o trueque completado. v3.12';


