--
-- Name: derive_estado_compra(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_estado_compra(p_id_orden uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_orden auth.ordenes%ROWTYPE;
BEGIN
  SELECT * INTO v_orden FROM auth.ordenes WHERE id = p_id_orden;
  IF NOT FOUND THEN
    RETURN 'orden_no_encontrada';
  END IF;

  -- Terminal states
  IF v_orden.estado IN ('cancelada', 'reembolsada', 'rechazada') THEN
    RETURN v_orden.estado;
  END IF;

  -- Pendiente con posible expiración
  IF v_orden.estado = 'pendiente' THEN
    IF v_orden.expiracion_coordinacion_en IS NOT NULL
       AND v_orden.expiracion_coordinacion_en < now() THEN
      RETURN 'expirada';
    END IF;
    RETURN 'pendiente';
  END IF;

  -- Confirmada → en_preparacion si ya hay respuesta
  IF v_orden.estado = 'confirmada' THEN
    IF v_orden.vendedor_listo_en IS NOT NULL THEN
      RETURN 'en_preparacion';
    END IF;
    RETURN 'confirmada';
  END IF;

  -- Estado directo para los demás
  IF v_orden.estado IN ('en_transito', 'entregada', 'completada') THEN
    RETURN v_orden.estado;
  END IF;

  -- Fallback
  RETURN v_orden.estado;
END;
$$;


--
-- Name: desactivar_producto(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.desactivar_producto(p_producto_id uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_antes JSONB; v_despues JSONB; v_actor UUID := public.get_app_actor_id();
BEGIN
  IF NOT public.is_admin_activo() THEN RAISE EXCEPTION 'denegado' USING ERRCODE='42501'; END IF;
  IF length(COALESCE(p_motivo,'')) < 8 THEN RAISE EXCEPTION 'motivo obligatorio' USING ERRCODE='22023'; END IF;

  SELECT to_jsonb(p) INTO v_antes FROM auth.productos p WHERE id=p_producto_id;
  UPDATE auth.productos SET activo=false, fecha_eliminacion=now() WHERE id=p_producto_id;
  SELECT to_jsonb(p) INTO v_despues FROM auth.productos p WHERE id=p_producto_id;

  INSERT INTO public.moderacion_h_audit(accion, entidad_tipo, entidad_id,
    valor_antes, valor_despues, motivo, id_actor)
  VALUES ('PRODUCTO_DESACTIVAR','producto',p_producto_id,v_antes,v_despues,p_motivo,v_actor);

  PERFORM public._age_reflejar_moderacion(v_actor, p_producto_id, 'PRODUCTO_DESACTIVAR');
  RETURN jsonb_build_object('ok',true);
END $$;


--
-- Name: detector_cuentas_espejo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detector_cuentas_espejo() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_umbral NUMERIC := 7;
  v_result JSONB;
BEGIN
  -- Umbral de días (config_seguridad.setting_value es JSON {"value": N}).
  -- Si no existe el parámetro, se usa el default 7.
  SELECT (setting_value->>'value')::numeric
    INTO v_umbral
   FROM public.config_seguridad
  WHERE setting_key = 'umbral_espejo_dias'
  LIMIT 1;
  v_umbral := COALESCE(v_umbral, 7);  -- fila ausente -> default 7

  -- Cuentas espejo: email con sufijo +alias que duplica una cuenta base distinta,
  -- creadas dentro del umbral de días.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id_usuario', u.id,
           'email',   u.email,
           'creado',  u.fecha_creacion
         )), '[]'::jsonb)
    INTO v_result
   FROM auth.users u
  WHERE u.fecha_creacion >= now() - (v_umbral || ' days')::interval
    AND EXISTS (
      SELECT 1 FROM auth.users u2
       WHERE u2.id <> u.id
         AND lower(u2.email) = lower(regexp_replace(u.email, '\+.*@', '@'))
    );

  RETURN v_result;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: detector_ghosting_vendedor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detector_ghosting_vendedor() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_dias NUMERIC := 30;
BEGIN
  -- config_seguridad.setting_value es JSONB {"value": N}.
  SELECT (setting_value->>'value')::numeric
    INTO v_dias
   FROM public.config_seguridad
  WHERE setting_key = 'umbral_ghosting_dias'
  LIMIT 1;
  v_dias := COALESCE(v_dias, 30);  -- fila ausente -> default 30

  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object('id_vendedor', id, 'email', email))
      FROM auth.users
     WHERE role = 'seller'
       AND activo = true
       AND fecha_eliminacion IS NULL
       -- proxy de "último login": fecha_actualizacion (no existe last_sign_in_at)
       AND (fecha_actualizacion IS NULL OR fecha_actualizacion < now() - (v_dias || ' days')::interval)
  ), '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: detector_lavado_puntos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detector_lavado_puntos() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object('id_usuario', id_usuario, 'total', total))
      FROM (
        SELECT id_usuario AS id_usuario, COUNT(*) AS total
          FROM auth.auditoria
         WHERE accion IN ('POINTS_TRANSFER','POINTS_REDEEM')
           AND fecha_creacion >= now() - interval '24 hours'
         GROUP BY id_usuario HAVING COUNT(*) > 50
      ) q
  ), '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END $$;


--
-- Name: enqueue_risk_report_notification(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_risk_report_notification(p_reporte_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_outbox uuid; v_rep public.reportes_seguridad%ROWTYPE;
BEGIN
  SELECT * INTO v_rep FROM public.reportes_seguridad WHERE reporte_id = p_reporte_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reporte % no encontrado', p_reporte_id USING ERRCODE = '02000';
  END IF;

  INSERT INTO public.notification_outbox
    (channel, target, subject, payload, correlation_id)
  VALUES (
    'email',
    'admin-security@kambalache.local',
    format('Reporte diario de riesgo %s', v_rep.fecha_reporte),
    jsonb_build_object('reporte_id', p_reporte_id,
                       'fecha_reporte', v_rep.fecha_reporte,
                       'hash', v_rep.hash_evento,
                       'summary', v_rep.payload - 'internal_debug'),
    v_rep.correlation_id
  )
  RETURNING outbox_id INTO v_outbox;
  RETURN v_outbox;
END;
$$;


--
-- Name: escalate_disputed_if_timeout(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escalate_disputed_if_timeout() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE disputes.disputes
    SET 
        is_escalated = TRUE,
        escalation_reason = 'no_response_48h',
        priority = 'high'
    WHERE 
        estado = 'awaiting_response'
        AND NOW() - fecha_creacion > INTERVAL '48 hours'
        AND is_escalated = FALSE;
        
    -- Notificar a db_admin
    INSERT INTO admin.notifications (id_admin, message, severity)
    SELECT DISTINCT assigned_to, 
           'Disputa escalada por falta de respuesta',
           'high'
    FROM disputes.disputes
    WHERE is_escalated = TRUE AND escalation_reason = 'no_response_48h';
END;
$$;


--
-- Name: fn_aceptar_intercambio(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_aceptar_intercambio(p_intercambio_id uuid, p_usuario_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_intercambio RECORD;
    v_estado_aceptado INTEGER;
BEGIN
    SELECT * INTO v_intercambio FROM intercambios WHERE id = p_intercambio_id;

    IF NOT FOUND THEN
        RETURN json_build_object('success', FALSE, 'error', 'Intercambio no encontrado');
    END IF;

    IF v_intercambio.usuario_receptor_id != p_usuario_id AND current_user_role() != 'admin' THEN
        RETURN json_build_object('success', FALSE, 'error', 'Solo el receptor puede aceptar');
    END IF;

    IF (SELECT nombre FROM estados_intercambio WHERE id = v_intercambio.estado_id) NOT IN ('propuesto', 'en_negociacion') THEN
        RETURN json_build_object('success', FALSE, 'error', 'El intercambio no está en estado aceptable');
    END IF;

    SELECT id INTO v_estado_aceptado FROM estados_intercambio WHERE nombre = 'aceptado';

    UPDATE intercambios SET estado_id = v_estado_aceptado WHERE id = p_intercambio_id;

    RETURN json_build_object('success', TRUE, 'mensaje', 'Intercambio aceptado');

EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object('success', FALSE, 'error', SQLERRM);
END;
$$;


