--

CREATE FUNCTION public.fn_auditoria_generica() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        INSERT INTO auditoria (tabla, operacion, registro_id, id_usuario, datos_antes)
        VALUES (TG_TABLE_NAME, TG_OP, OLD.id::TEXT, current_user_id(), to_jsonb(OLD));
        RETURN OLD;
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO auditoria (tabla, operacion, registro_id, id_usuario, datos_antes, datos_despues)
        VALUES (TG_TABLE_NAME, TG_OP, NEW.id::TEXT, current_user_id(), to_jsonb(OLD), to_jsonb(NEW));
        RETURN NEW;
    ELSIF TG_OP = 'INSERT' THEN
        INSERT INTO auditoria (tabla, operacion, registro_id, id_usuario, datos_despues)
        VALUES (TG_TABLE_NAME, TG_OP, NEW.id::TEXT, current_user_id(), to_jsonb(NEW));
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$$;


