--
-- Name: generar_reporte_riesgo_medianoche(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generar_reporte_riesgo_medianoche() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_espejo   JSONB;
  v_lavado   JSONB;
  v_ghost    JSONB;
  v_content  JSONB;
  v_reporte  UUID;
  v_actor    UUID := public.get_app_actor_id();
BEGIN
  BEGIN v_espejo := public.detector_cuentas_espejo();
  EXCEPTION WHEN OTHERS THEN v_espejo := jsonb_build_object('error',SQLERRM); END;
  BEGIN v_lavado := public.detector_lavado_puntos();
  EXCEPTION WHEN OTHERS THEN v_lavado := jsonb_build_object('error',SQLERRM); END;
  BEGIN v_ghost  := public.detector_ghosting_vendedor();
  EXCEPTION WHEN OTHERS THEN v_ghost  := jsonb_build_object('error',SQLERRM); END;

  v_content := jsonb_build_object(
    'generado_en', now(),
    'cuentas_espejo', v_espejo,
    'lavado_puntos',  v_lavado,
    'ghosting',       v_ghost
  );

  INSERT INTO public.reportes_seguridad(tipo, fecha_reporte, contenido, generado_por)
  VALUES ('DIARIO_RIESGOS', CURRENT_DATE, v_content, v_actor)
  ON CONFLICT (tipo, fecha_reporte) DO UPDATE
    SET contenido = EXCLUDED.contenido
  RETURNING id INTO v_reporte;

  IF jsonb_typeof(v_espejo)='array' AND jsonb_array_length(v_espejo)>0 THEN
    INSERT INTO public.admin_alerts(tipo, nivel_riesgo, payload, creado_por)
    VALUES ('CUENTAS_ESPEJO', 7.0, v_espejo, v_actor) ON CONFLICT DO NOTHING;
  END IF;
  IF jsonb_typeof(v_lavado)='array' AND jsonb_array_length(v_lavado)>0 THEN
    INSERT INTO public.admin_alerts(tipo, nivel_riesgo, payload, creado_por)
    VALUES ('LAVADO_PUNTOS', 8.5, v_lavado, v_actor) ON CONFLICT DO NOTHING;
  END IF;
  IF jsonb_typeof(v_ghost)='array' AND jsonb_array_length(v_ghost)>0 THEN
    INSERT INTO public.admin_alerts(tipo, nivel_riesgo, payload, creado_por)
    VALUES ('GHOSTING_VENDEDOR', 5.0, v_ghost, v_actor) ON CONFLICT DO NOTHING;
  END IF;

  BEGIN
    INSERT INTO auth.auditoria(id_actor, action, target_kind, id_objetivo, payload)
    VALUES (v_actor, 'RIESGO_REPORTE_GENERADO', 'reportes_seguridad', v_reporte::text, v_content);
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('reporte_id', v_reporte, 'contenido', v_content);
END $$;


--
