--
-- Name: get_active_actor_tier(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_actor_tier(p_id_usuario uuid, p_rol text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT cpa.tier_code FROM public.commercial_profile_assignments cpa
  WHERE cpa.id_usuario = p_id_usuario AND cpa.actor_role = p_rol
    AND cpa.subscription_status = 'active'
    AND (cpa.effective_to IS NULL OR cpa.effective_to >= now())
  ORDER BY cpa.effective_from DESC LIMIT 1
$$;


--
-- Name: get_advanced_purchase_route(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_advanced_purchase_route(p_source_node bigint, p_target_node bigint) RETURNS TABLE(seq integer, node bigint, edge bigint, cost double precision, agg_cost double precision)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname='pgrouting') THEN
        RAISE EXCEPTION 'PGROUTING_NO_DISPONIBLE' USING ERRCODE = '0A000';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.road_network LIMIT 1) THEN
        RAISE EXCEPTION 'RED_VIAL_NO_DISPONIBLE' USING ERRCODE = 'P0001';
    END IF;

    RETURN QUERY
    SELECT r.seq::INTEGER, r.node, r.edge, r.cost, r.agg_cost
    FROM pgr_dijkstra(
        'SELECT id, source, target, cost, reverse_cost FROM public.road_network',
        p_source_node, p_target_node, directed := true
    ) r;
END;
$$;


--
-- Name: get_age_rank_score(text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_age_rank_score(p_graph_name text, p_buyer_label text, p_seller_label text, p_id_comprador uuid, p_id_vendedor uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog'
    AS $_$
DECLARE
  v_score numeric := 0;
  v_has_age boolean;
BEGIN
  -- R-88: si AGE no está, devolver 0 sin fallar
  SELECT EXISTS(SELECT 1 FROM pg_extension WHERE extname='age') INTO v_has_age;
  IF NOT v_has_age THEN
    RETURN 0;
  END IF;

  BEGIN
    EXECUTE format($f$
      SELECT COALESCE((score::text)::numeric, 0)
      FROM cypher(%L, $q$
        MATCH (b:%I {id: %L})-[r]->(s:%I {id: %L})
        RETURN COALESCE(r.score, 1) AS score
        LIMIT 1
      $q$) AS (score agtype)
    $f$, p_graph_name, p_buyer_label, p_id_comprador::text, p_seller_label, p_id_vendedor::text)
    INTO v_score;
  EXCEPTION WHEN OTHERS THEN
    v_score := 0;  -- degradación R-88
  END;

  RETURN COALESCE(v_score, 0);
END; $_$;


