--
-- Name: get_articles_nearby(double precision, double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_articles_nearby(p_lat double precision, p_lon double precision, p_radius_km double precision DEFAULT 5.0, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'center',    jsonb_build_object('lat', p_lat, 'lon', p_lon),
    'radius_km', p_radius_km,
    'total',     COUNT(*),
    'articles',  COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id',           sub.id,
          'titulo',       sub.titulo,
          'disponible',   sub.disponible,
          'ubicacion',    sub.ubicacion,
          'distance_km',  sub.distance_km,
          'creator_name', sub.creator_name
        ) ORDER BY sub.distance_km
      ),
      '[]'::jsonb
    )
  )
  FROM (
    SELECT
      a.id,
      a.titulo,
      a.disponible,
      a.ubicacion,
      u.username AS creator_name,
      (
        6371.0 * 2.0 * ASIN(SQRT(
          POWER(SIN((RADIANS(CAST(a.ubicacion->>'lat' AS float) - p_lat) / 2.0)), 2) +
          COS(RADIANS(p_lat)) *
          COS(RADIANS(CAST(a.ubicacion->>'lat' AS float))) *
          POWER(SIN((RADIANS(CAST(a.ubicacion->>'lon' AS float) - p_lon) / 2.0)), 2)
        ))
      )::numeric(8,2) AS distance_km
    FROM articulos a
    JOIN usuarios u ON u.id = a.id_usuario
    WHERE a.disponible = true
      AND a.ubicacion->>'lat' IS NOT NULL
      AND a.ubicacion->>'lon' IS NOT NULL
    ORDER BY distance_km
    LIMIT p_limit * 3
  ) sub
  WHERE sub.distance_km <= p_radius_km
  LIMIT p_limit;
$$;


--
-- Name: FUNCTION get_articles_nearby(p_lat double precision, p_lon double precision, p_radius_km double precision, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_articles_nearby(p_lat double precision, p_lon double precision, p_radius_km double precision, p_limit integer) IS 'Artículos cercanos a las coordenadas dadas usando fórmula Haversine (sin PostGIS)';


--
-- Name: get_articles_trending(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_articles_trending(p_interval text DEFAULT '7 days'::text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'period_interval', p_interval,
    'total',           COUNT(*),
    'articles', COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id',                sub.id,
          'titulo',            sub.titulo,
          'disponible',        sub.disponible,
          'views_count',       sub.vistas_count,
          'created_at',        sub.created_at,
          'creator_username',  sub.creator_username,
          'creator_name',      sub.creator_name,
          'avg_rating',        sub.avg_rating,
          'rating_count',      sub.rating_count,
          'exchange_mentions', sub.exchange_mentions
        ) ORDER BY sub.vistas_count DESC, sub.exchange_mentions DESC
      ),
      '[]'::jsonb
    )
  )
  FROM (
    SELECT
      a.id,
      a.titulo,
      a.disponible,
      a.vistas_count,
      a.created_at,
      u.username                                              AS creator_username,
      u.username                                              AS creator_name,
      COALESCE(ROUND(AVG(r.calificacion)::numeric, 2), 0)     AS avg_rating,
      COUNT(DISTINCT r.id)                                    AS rating_count,
      COUNT(DISTINCT ia.intercambio_id)                       AS exchange_mentions
    FROM articulos a
    JOIN usuarios u          ON u.id = a.id_usuario
    LEFT JOIN auth.resenas r ON r.id_vendedor = a.id_usuario AND r.activo = true
    LEFT JOIN auth.intercambio_articulos ia ON ia.producto_id = a.id
    WHERE a.disponible = true
      AND a.created_at >= NOW() - p_interval::interval
    GROUP BY a.id, a.titulo, a.disponible, a.vistas_count, a.created_at, u.username
    ORDER BY a.vistas_count DESC, exchange_mentions DESC
    LIMIT p_limit
  ) sub;
$$;


--
-- Name: FUNCTION get_articles_trending(p_interval text, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_articles_trending(p_interval text, p_limit integer) IS 'Artículos más activos (vistas + intercambios) en el período dado';


--
-- Name: get_buyer_hyperlocal_context(uuid, double precision, double precision, uuid, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_buyer_hyperlocal_context(p_id_comprador uuid, p_lat double precision, p_lng double precision, p_plan_id uuid DEFAULT NULL::uuid, p_radius_meters double precision DEFAULT 1500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
    v_actor_id UUID;
    v_trending JSONB;
    v_route    JSONB;
BEGIN
    v_actor_id := auth.jwt_user_id_safe();
    IF v_actor_id IS NULL OR v_actor_id <> p_id_comprador THEN
        RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO' USING ERRCODE = '28000';
    END IF;

    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
    INTO v_trending
    FROM public.get_local_trending_sellers(p_lat, p_lng, p_radius_meters, 20) t;

    IF p_plan_id IS NOT NULL THEN
        SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb)
        INTO v_route
        FROM public.get_simple_purchase_route(p_plan_id, p_lat, p_lng) r;
    ELSE
        v_route := '[]'::jsonb;
    END IF;

    RETURN jsonb_build_object(
        'id_comprador', p_id_comprador,
        'trending_sellers', v_trending,
        'suggested_route', v_route,
        'generated_at', now()
    );
END;
$$;


--
-- Name: get_dashboard_kpis(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_kpis() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
DECLARE
    v_kpis json;
BEGIN
    IF auth.current_jwt_role() <> 'db_admin' THEN
        RAISE EXCEPTION 'Solo administradores' USING ERRCODE = '42501';
    END IF;

    SELECT json_build_object(
        'success', TRUE,
        'kpis', json_build_object(
            'total_usuarios_activos',   (SELECT COUNT(*) FROM auth.users WHERE activo = TRUE AND fecha_eliminacion IS NULL),
            'nuevos_usuarios_mes',      (SELECT COUNT(*) FROM auth.users WHERE fecha_creacion >= DATE_TRUNC('month', NOW())),
            'total_ordenes_mes',        (SELECT COUNT(*) FROM auth.ordenes WHERE fecha_creacion >= DATE_TRUNC('month', NOW())),
            'total_intercambios_mes',   (SELECT COUNT(*) FROM auth.intercambios WHERE creado_en >= DATE_TRUNC('month', NOW())),
            'intercambios_completados', (SELECT COUNT(*) FROM auth.intercambios WHERE estado = 'completada'),
            'productos_disponibles',    (SELECT COUNT(*) FROM auth.productos WHERE activo = TRUE AND fecha_eliminacion IS NULL),
            'rating_promedio_global',   (SELECT COALESCE(ROUND(AVG(calificacion)::numeric, 2), 0) FROM auth.resenas WHERE activo = TRUE),
            'resenas_mes',              (SELECT COUNT(*) FROM auth.resenas WHERE fecha_creacion >= DATE_TRUNC('month', NOW())),
            'puntos_en_circulacion',    (SELECT COALESCE(SUM(saldo), 0) FROM public.puntos_cuenta),
            'puntos_total_emitidos',    (SELECT COALESCE(SUM(total_acumulado), 0) FROM public.puntos_cuenta),
            'alertas_abiertas',         (SELECT COUNT(*) FROM public.admin_alerts WHERE estado = 'abierta'),
            'alertas_criticas',         (SELECT COUNT(*) FROM public.admin_alerts WHERE estado = 'abierta' AND severidad IN ('alta', 'critica'))
        )
    ) INTO v_kpis;

    RETURN v_kpis;
END;
$$;


--
-- Name: FUNCTION get_dashboard_kpis(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_dashboard_kpis() IS 'Retorna JSON con KPIs principales del dashboard. Lee de vista materializada si está disponible, o calcula en vivo. Requiere rol admin/moderador. v3.12';


--
-- Name: get_exchange_stats(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_exchange_stats(p_interval text DEFAULT '30 days'::text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'period_interval', p_interval,
    'stats', COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'estado_id',     sub.estado_id,
          'estado_nombre', sub.estado_nombre,
          'total',         sub.total,
          'in_period',     sub.in_period
        ) ORDER BY sub.total DESC
      ),
      '[]'::jsonb
    )
  )
  FROM (
    SELECT
      ie.estado                                                        AS estado_id,
      ie.estado                                                        AS estado_nombre,
      COUNT(ie.id)                                                     AS total,
      COUNT(CASE WHEN ie.creado_en >= NOW() - p_interval::interval
                 THEN 1 END)                                           AS in_period
    FROM auth.intercambios ie
    GROUP BY ie.estado
    ORDER BY total DESC
    LIMIT p_limit
  ) sub;
$$;


