-- Name: FUNCTION get_exchange_stats(p_interval text, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_exchange_stats(p_interval text, p_limit integer) IS 'Estadísticas de intercambios por estado para el intervalo dado';


--
-- Name: alertas_fraude; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.alertas_fraude (
    alert_id uuid DEFAULT gen_random_uuid() NOT NULL,
    tipo_alerta text NOT NULL,
    primary_entity_id uuid NOT NULL,
    primary_entity_kind text NOT NULL,
    related_entity_ids uuid[] DEFAULT ARRAY[]::uuid[] NOT NULL,
    estado text DEFAULT 'open'::text NOT NULL,
    severity text DEFAULT 'medium'::text NOT NULL,
    detected_at timestamp with time zone DEFAULT now() NOT NULL,
    id_caso uuid,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    score numeric(6,3),
    alerta_id uuid,
    fecha_creacion timestamp with time zone,
    fecha_eliminacion timestamp with time zone,
    id uuid,
    resuelto_en text,
    priority text,
    CONSTRAINT alertas_fraude_estado_check CHECK ((estado = ANY (ARRAY['open'::text, 'investigating'::text, 'confirmed'::text, 'dismissed'::text]))),
    CONSTRAINT alertas_fraude_primary_entity_kind_check CHECK ((primary_entity_kind = ANY (ARRAY['user'::text, 'wallet'::text, 'product'::text, 'order'::text, 'ip'::text, 'device'::text]))),
    CONSTRAINT alertas_fraude_score_check CHECK (((score IS NULL) OR ((score >= (0)::numeric) AND (score <= (1)::numeric))))
);


--
-- Name: casos_investigacion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.casos_investigacion (
    id_caso uuid DEFAULT gen_random_uuid() NOT NULL,
    id_entidad text NOT NULL,
    entity_kind text NOT NULL,
    detector_name text NOT NULL,
    estado text DEFAULT 'open'::text NOT NULL,
    severity text DEFAULT 'medium'::text NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    correlation_id uuid DEFAULT gen_random_uuid(),
    opened_by uuid NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    confirmed_by uuid,
    fecha_confirmacion timestamp with time zone,
    dismissed_by uuid,
    dismissed_at timestamp with time zone,
    applied_action text,
    applied_at timestamp with time zone,
    reverted_at timestamp with time zone,
    notes text,
    id uuid,
    tipo_entidad text,
    assigned_to text,
    fecha_creacion timestamp with time zone,
    fecha_eliminacion timestamp with time zone,
    CONSTRAINT casos_investigacion_applied_action_check CHECK ((applied_action = ANY (ARRAY['suspend_entity'::text, 'intervene_network'::text, 'notify_only'::text, 'none'::text]))),
    CONSTRAINT casos_investigacion_entity_kind_check CHECK ((entity_kind = ANY (ARRAY['user'::text, 'wallet'::text, 'product'::text, 'order'::text, 'device'::text, 'ip'::text]))),
    CONSTRAINT casos_investigacion_estado_check CHECK ((estado = ANY (ARRAY['open'::text, 'confirmed'::text, 'dismissed'::text, 'reverted'::text]))),
    CONSTRAINT casos_investigacion_severity_check CHECK ((severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT chk_investigacion_terminal CHECK ((((estado = 'confirmed'::text) AND (fecha_confirmacion IS NOT NULL)) OR ((estado = 'dismissed'::text) AND (dismissed_at IS NOT NULL)) OR (estado = ANY (ARRAY['open'::text, 'reverted'::text]))))
);


--
-- Name: v_fraud_alerts_open; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_fraud_alerts_open AS
 SELECT fa.id,
    fa.severity,
    fa.fecha_creacion,
    ic.id_entidad,
    ic.tipo_entidad,
    fa.evidence
   FROM (public.alertas_fraude fa
     JOIN public.casos_investigacion ic ON ((fa.id_caso = ic.id)))
  WHERE ((fa.resuelto_en IS NULL) AND (fa.fecha_eliminacion IS NULL));


--
-- Name: get_fraud_alerts(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_fraud_alerts(p_type text DEFAULT NULL::text, p_status text DEFAULT 'open'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS SETOF public.v_fraud_alerts_open
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_actor uuid := app.jwt_user_id_safe();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
    SELECT * FROM public.v_fraud_alerts_open
     WHERE (p_type IS NULL OR tipo_alerta = p_type)
       AND (p_status IS NULL OR estado = p_status)
     ORDER BY detected_at DESC
     LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: get_local_trending_sellers(double precision, double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_local_trending_sellers(p_buyer_lat double precision, p_buyer_lng double precision, p_radius_meters double precision DEFAULT 1500, p_limit integer DEFAULT 20) RETURNS TABLE(id_vendedor uuid, distance_meters double precision, interaction_score bigint)
    LANGUAGE sql STABLE
    AS $$
WITH buyer_point AS (
    SELECT ST_SetSRID(ST_MakePoint(p_buyer_lng, p_buyer_lat), 4326)::geography AS geom
),
nearby_sellers AS (
    SELECT
        l.id_usuario AS id_vendedor,
        ST_Distance((SELECT geom FROM buyer_point), l.geom::geography) AS distance_meters
    FROM auth.ubicaciones l
    WHERE l.is_active = true
      AND l.fecha_eliminacion IS NULL
      AND l.geom IS NOT NULL
      AND ST_DWithin((SELECT geom FROM buyer_point), l.geom::geography, p_radius_meters)
),
scores AS (
    SELECT id_vendedor, SUM(total_interactions) AS interaction_score
    FROM public.mv_local_seller_popularity
    GROUP BY id_vendedor
)
SELECT
    n.id_vendedor,
    n.distance_meters,
    COALESCE(s.interaction_score, 0) AS interaction_score
FROM nearby_sellers n
LEFT JOIN scores s ON s.id_vendedor = n.id_vendedor
ORDER BY interaction_score DESC, distance_meters ASC
LIMIT p_limit;
$$;


