-- Name: get_metricas_grafo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_metricas_grafo() RETURNS TABLE(metrica text, valor bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'ag_catalog', 'pg_temp'
