--
-- Name: get_nearby_merchants(double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_nearby_merchants(p_lat double precision, p_lng double precision, p_radius_m integer DEFAULT 2000) RETURNS TABLE(id_vendedor uuid, nombre_tienda text, distancia_m double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH origen AS (
    SELECT ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography AS pto
  )
  SELECT u.id,
         COALESCE(ppv.nombre_marca, u.nombre_visible),
         ROUND(ST_Distance(o.pto, ub.punto)::numeric, 1)::double precision
    FROM auth.users u
    JOIN auth.ubicaciones ub ON ub.id_usuario = u.id AND ub.is_active = true
    LEFT JOIN auth.perfiles_publicos_vendedor ppv ON ppv.id_vendedor = u.id
    CROSS JOIN origen o
   WHERE u.role = 'seller'
     AND (u.activo IS DISTINCT FROM false)
     AND u.fecha_eliminacion IS NULL
     AND ST_DWithin(o.pto, ub.punto, p_radius_m)
   ORDER BY ST_Distance(o.pto, ub.punto);
$$;


--
-- Name: get_nearby_merchants_regulated(double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_nearby_merchants_regulated(p_lat double precision, p_lng double precision, p_radius_m integer DEFAULT 2000) RETURNS TABLE(id_usuario uuid, distance_m numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_point geometry := ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326);
BEGIN
  RETURN QUERY
    SELECT l.id_usuario,
           ST_Distance(l.geom::geography, v_point::geography)::numeric
    FROM auth.ubicaciones l
    JOIN auth.users u ON u.id = l.id_usuario
    WHERE l.fecha_eliminacion IS NULL
      AND u.fecha_eliminacion IS NULL
      AND u.estado_administrativo = 'active'
      AND ST_DWithin(l.geom::geography, v_point::geography, p_radius_m)
      AND public.admin_visibilidad_vendedor_regulada(l.id_usuario) = true
    ORDER BY 2 ASC
    LIMIT 200;
END;
$$;


--
-- Name: get_nearby_merchants_social(double precision, double precision, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_nearby_merchants_social(p_lat double precision, p_lng double precision, p_radius_m integer DEFAULT 2000, p_id_comprador uuid DEFAULT NULL::uuid) RETURNS TABLE(id_vendedor uuid, nombre_tienda text, distancia_m double precision, es_favorito boolean, tipo_relacion text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH origen AS (
    SELECT ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography AS pto
  )
  SELECT u.id,
         COALESCE(ppv.nombre_marca, u.nombre_visible),
         ROUND(ST_Distance(o.pto, ub.punto)::numeric, 1)::double precision,
         (fav.id IS NOT NULL) AS es_favorito,
         rel.relationship_type
    FROM auth.users u
    JOIN auth.ubicaciones ub ON ub.id_usuario = u.id AND ub.is_active = true
    LEFT JOIN auth.perfiles_publicos_vendedor ppv ON ppv.id_vendedor = u.id
    LEFT JOIN public.buyer_favorite_sellers fav
      ON fav.id_vendedor = u.id AND fav.id_comprador = p_id_comprador AND fav.fecha_eliminacion IS NULL
    LEFT JOIN public.user_relationships rel
      ON rel.to_user_id = u.id AND rel.from_user_id = p_id_comprador AND rel.fecha_eliminacion IS NULL
    CROSS JOIN origen o
   WHERE u.role = 'seller'
     AND (u.activo IS DISTINCT FROM false)
     AND u.fecha_eliminacion IS NULL
     AND ST_DWithin(o.pto, ub.punto, p_radius_m)
   ORDER BY ST_Distance(o.pto, ub.punto);
$$;


--
-- Name: get_plan_limit(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_plan_limit(p_tier text, p_limit text) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
    SELECT CASE p_limit
        WHEN 'max_productos'      THEN max_productos::numeric
        WHEN 'max_ubicaciones'    THEN max_ubicaciones::numeric
        WHEN 'max_promociones'    THEN max_promociones::numeric
        WHEN 'max_fotos_producto' THEN max_fotos_producto::numeric
        WHEN 'precio_mensual'     THEN precio_mensual
        WHEN 'precio_anual'       THEN precio_anual
        ELSE NULL
    END
    FROM auth.planes_membresia WHERE codigo = p_tier;
$$;


--
-- Name: get_public_vendor_profile(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_vendor_profile(p_slug_publico text, p_visitor_hash text DEFAULT NULL::text, p_fuente text DEFAULT 'direct'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_slug    text;
  v_payload jsonb;
  v_metricas jsonb;
BEGIN
  v_slug := auth.fn_slugify_text(p_slug_publico);

  SELECT pp.metricas_visibles, to_jsonb(pp) INTO v_metricas, v_payload
  FROM auth.perfiles_publicos_vendedor pp
  WHERE pp.slug_publico = v_slug AND pp.activo = true
  LIMIT 1;

  IF v_payload IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT jsonb_build_object(
    'slug_publico',   pp.slug_publico,
    'nombre_marca',   pp.nombre_marca,
    'slogan',         pp.slogan,
    'biografia',      pp.biografia,
    'url_logo',       COALESCE(pp.url_logo, up.url_avatar),
    'url_banner',     pp.url_banner,
    'metadata',       pp.metadata,
    'verificado',     pp.verificado,
    'badge_membresia', pp.badge_membresia,
    'miembro_desde',  u.fecha_creacion,
    'estadisticas', CASE
      WHEN pp.mostrar_estadisticas
        AND (v_metricas ->> 'ocultar_estadisticas') IS DISTINCT FROM 'true'
      THEN jsonb_build_object(
        'rating_promedio',          COALESCE(stats.rating_promedio, 0),
        'total_resenas',            COALESCE(stats.total_resenas, 0),
        'total_productos_activos',  CASE
          WHEN (v_metricas ->> 'ocultar_productos') = 'true' THEN NULL
          ELSE COALESCE(stats.total_productos_activos, 0)
        END,
        'total_ventas_confirmadas', CASE
          WHEN (v_metricas ->> 'ocultar_ventas') = 'true' THEN NULL
          ELSE COALESCE(stats.total_ventas_confirmadas, 0)
        END
      )
      ELSE NULL
    END,
    'contacto_publico', CASE
      WHEN pp.mostrar_contacto THEN jsonb_build_object('telefono', up.telefono)
      ELSE NULL
    END,
    'ubicacion_publica', CASE
      WHEN pp.mostrar_ubicacion AND loc.id IS NOT NULL THEN
        jsonb_build_object('id', loc.id, 'latitud', loc.latitud, 'longitud', loc.longitud)
      ELSE NULL
    END
  )
  INTO v_payload
  FROM auth.perfiles_publicos_vendedor pp
  JOIN auth.users u ON u.id = pp.id_vendedor AND u.role = 'seller'
  LEFT JOIN auth.user_profiles up ON up.id_usuario = pp.id_vendedor
  LEFT JOIN LATERAL (
    SELECT AVG(r.calificacion)::numeric(10,2) AS rating_promedio,
           COUNT(*)::integer AS total_resenas,
           (SELECT COUNT(*)::integer FROM auth.productos p
            WHERE p.id_vendedor = pp.id_vendedor AND p.activo = true AND p.fecha_eliminacion IS NULL)
             AS total_productos_activos,
           (SELECT COUNT(*)::integer FROM auth.ordenes o
            WHERE o.id_vendedor = pp.id_vendedor AND o.estado = 'confirmada')
             AS total_ventas_confirmadas
    FROM auth.resenas r WHERE r.id_vendedor = pp.id_vendedor
  ) stats ON true
  LEFT JOIN LATERAL (
    SELECT ub.id, ub.latitud, ub.longitud
    FROM auth.ubicaciones ub
    WHERE (
      (pp.ubicacion_principal_id IS NOT NULL AND ub.id = pp.ubicacion_principal_id)
      OR (pp.ubicacion_principal_id IS NULL AND ub.id_usuario = pp.id_vendedor)
    )
    AND ub.estado = 'activo'
    ORDER BY ub.fecha_actualizacion DESC NULLS LAST, ub.fecha_creacion DESC
    LIMIT 1
  ) loc ON true
  WHERE pp.slug_publico = v_slug AND pp.activo = true;

  -- CF-5: Registrar visita (async, no falla si tabla no existe)
  IF p_visitor_hash IS NOT NULL THEN
    BEGIN
      PERFORM auth.fn_registrar_visita_perfil(
        (SELECT id_vendedor FROM auth.perfiles_publicos_vendedor
          WHERE slug_publico = v_slug),
        p_visitor_hash,
        p_fuente
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;  -- Degradación elegante: visita no registrada no afecta respuesta
    END;
  END IF;

  RETURN v_payload;
END;
$$;


--
-- Name: get_public_vendor_seo(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_vendor_seo(p_slug_publico text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'og_title',       COALESCE(seo.og_title, pp.nombre_marca),
    'og_description', COALESCE(seo.og_description, pp.slogan, pp.biografia),
    'og_image_url',   COALESCE(seo.og_image_url, pp.url_logo),
    'og_url',         '/tienda/' || pp.slug_publico,
    'keywords',       seo.keywords,
    'schema_org_type', COALESCE(seo.schema_org_type, 'LocalBusiness')
  )
  INTO v_result
  FROM auth.perfiles_publicos_vendedor pp
  LEFT JOIN auth.perfil_seo_metadata seo ON seo.id_vendedor = pp.id_vendedor
  WHERE pp.slug_publico = auth.fn_slugify_text(p_slug_publico)
    AND pp.activo = true;

  RETURN v_result;
END;
$$;


--
-- Name: get_ratings_by_user(uuid, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ratings_by_user(p_usuario_id uuid, p_tipo character varying DEFAULT 'recibidos'::character varying, p_limite integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_resultados JSON;
    v_promedio NUMERIC;
    v_total INTEGER;
BEGIN
    IF p_tipo = 'recibidos' THEN
        SELECT json_agg(row_to_json(t)), COUNT(*) OVER() INTO v_resultados, v_total
        FROM (
            SELECT r.id, r.puntuacion, r.comentario, r.es_publico, r.created_at,
                   u.username AS calificador_username,
                   p.nombre AS calificador_nombre,
                   a.titulo AS articulo_titulo
            FROM ratings r
            JOIN usuarios u ON r.id_usuario = u.id
            LEFT JOIN perfiles p ON p.id_usuario = u.id
            LEFT JOIN articulos a ON r.articulo_id = a.id
            WHERE r.calificado_id = p_usuario_id
              AND (r.es_publico = TRUE OR r.id_usuario = current_user_id() OR current_user_role() IN ('admin', 'moderador'))
            ORDER BY r.created_at DESC
            LIMIT p_limite OFFSET p_offset
        ) t;

        SELECT COALESCE(ROUND(AVG(puntuacion)::NUMERIC, 2), 0) INTO v_promedio
        FROM ratings WHERE calificado_id = p_usuario_id;

        SELECT COUNT(*) INTO v_total FROM ratings WHERE calificado_id = p_usuario_id;

    ELSE -- realizados
        SELECT json_agg(row_to_json(t)) INTO v_resultados
        FROM (
            SELECT r.id, r.puntuacion, r.comentario, r.created_at,
                   u.username AS calificado_username,
                   a.titulo AS articulo_titulo
            FROM ratings r
            JOIN usuarios u ON r.calificado_id = u.id
            LEFT JOIN articulos a ON r.articulo_id = a.id
            WHERE r.id_usuario = p_usuario_id
            ORDER BY r.created_at DESC
            LIMIT p_limite OFFSET p_offset
        ) t;

        SELECT COALESCE(ROUND(AVG(puntuacion)::NUMERIC, 2), 0) INTO v_promedio
        FROM ratings WHERE id_usuario = p_usuario_id;

        SELECT COUNT(*) INTO v_total FROM ratings WHERE id_usuario = p_usuario_id;
    END IF;

    RETURN json_build_object(
        'success', TRUE,
        'tipo', p_tipo,
        'id_usuario', p_usuario_id,
        'promedio', v_promedio,
        'total', v_total,
        'ratings', COALESCE(v_resultados, '[]'::JSON)
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object('success', FALSE, 'error', SQLERRM);
END;
$$;


--
-- Name: FUNCTION get_ratings_by_user(p_usuario_id uuid, p_tipo character varying, p_limite integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_ratings_by_user(p_usuario_id uuid, p_tipo character varying, p_limite integer, p_offset integer) IS 'Retorna ratings recibidos o realizados por un usuario con promedio. v3.12';


--
-- Name: get_recommendations(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recommendations(p_user_id uuid, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'strategy', 'hybrid',
    'total',    COUNT(*),
    'recommendations', COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id',              sub.id,
          'titulo',          sub.titulo,
          'descripcion',     sub.descripcion,
          'disponible',      sub.disponible,
          'ubicacion',       sub.ubicacion,
          'views_count',     sub.vistas_count,
          'created_at',      sub.created_at,
          'creator_name',    sub.creator_name,
          'creator_score',   sub.creator_score,
          'relevance',       sub.relevance
        ) ORDER BY sub.relevance DESC
      ),
      '[]'::jsonb
    )
  )
  FROM (
    SELECT
      a.id,
      a.titulo,
      a.descripcion,
      a.disponible,
      a.ubicacion,
      a.vistas_count,
      a.created_at,
      u.username                                              AS creator_name,
      COALESCE(ROUND(AVG(r.calificacion)::numeric, 2), 0)     AS creator_score,
      (
        a.vistas_count * 0.3 +
        COALESCE(AVG(r.calificacion), 3) * 0.4 +
        CASE WHEN a.created_at > NOW() - INTERVAL '7 days' THEN 2 ELSE 0 END
      )::numeric(8,2)                                         AS relevance
    FROM articulos a
    JOIN usuarios u          ON u.id = a.id_usuario
    LEFT JOIN auth.resenas r ON r.id_vendedor = a.id_usuario AND r.activo = true
    WHERE a.disponible = true
      AND a.id_usuario != p_user_id
      AND a.id NOT IN (
        SELECT ia.producto_id
        FROM auth.intercambio_articulos ia
        JOIN auth.intercambios i ON i.id = ia.intercambio_id
        WHERE i.solicitante_id = p_user_id OR i.receptor_id = p_user_id
      )
    GROUP BY a.id, a.titulo, a.descripcion, a.disponible, a.ubicacion,
             a.vistas_count, a.created_at, u.username
    ORDER BY relevance DESC
    LIMIT p_limit
  ) sub;
$$;


--
-- Name: FUNCTION get_recommendations(p_user_id uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_recommendations(p_user_id uuid, p_limit integer) IS 'Recomendaciones híbridas de artículos (vistas × 0.3 + rating × 0.4 + recencia × 0.3)';


--
-- Name: get_request_jwt_claims(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_request_jwt_claims() RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(current_setting('request.jwt.claims', true)::jsonb, '{}'::jsonb);
$$;


--
-- Name: get_request_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_request_role() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims jsonb;
  v_role text;
BEGIN
  BEGIN
    v_claims := NULLIF(current_setting('request.jwt.claims', true), '')::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_claims := '{}'::jsonb;
  END;

  v_role := COALESCE(
    NULLIF(v_claims->>'role', ''),
    NULLIF(v_claims->>'user_role', ''),
    NULLIF(current_setting('app.current_user_role', true), ''),
    'anonimo'
  );

  RETURN v_role;
END;
$$;


--
-- Name: get_riesgo_historico(text, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_riesgo_historico(p_entity_kind text, p_entity_id uuid, p_desde timestamp with time zone DEFAULT (now() - '90 days'::interval), p_hasta timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'analytics', 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := COALESCE((current_setting('request.jwt.claims', true)::jsonb ->> 'role'),'');
  v_out  JSONB;
BEGIN
  IF v_role NOT IN ('admin','auditor','super_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.tables
     WHERE table_schema='analytics' AND table_name='instantaneas_riesgo'
  ) THEN
    RETURN jsonb_build_object('status','BLOQUEADO','reason','no_snapshots_table','series','[]'::jsonb);
  END IF;

  SELECT jsonb_build_object(
    'status', 'OK',
    'entity_kind', p_entity_kind,
    'entity_id',   p_entity_id,
    'series', COALESCE(jsonb_agg(
      jsonb_build_object(
        'snapshot_at', s.instantanea_en,
        'risk_score',  s.risk_score,
        'factors',     s.factors
      ) ORDER BY s.instantanea_en
    ), '[]'::jsonb)
  ) INTO v_out
  FROM analytics.instantaneas_riesgo s
  WHERE s.entity_kind = p_entity_kind
    AND s.id_entidad   = p_entity_id::text
    AND s.instantanea_en BETWEEN p_desde AND p_hasta;

  RETURN v_out;
END;
$$;


--
-- Name: get_schema_details(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_schema_details(p_schema text DEFAULT 'public'::text) RETURNS TABLE(tabla text, columna text, tipo text, descripcion text, rls_activo boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.is_admin_activo() THEN
    RAISE EXCEPTION 'acceso denegado' USING ERRCODE='42501';
  END IF;
  RETURN QUERY
    SELECT c.table_name::TEXT,
           c.column_name::TEXT,
           c.data_type::TEXT,
           col_description((c.table_schema||'.'||c.table_name)::regclass::oid,
                           c.ordinal_position)::TEXT,
           t.rowsecurity
      FROM information_schema.columns c
      JOIN pg_class pc  ON pc.relname = c.table_name
      JOIN pg_tables t  ON t.tablename = c.table_name AND t.schemaname=c.table_schema
     WHERE c.table_schema = p_schema
     ORDER BY c.table_name, c.ordinal_position;
END $$;


--
-- Name: get_seller_quick_sheet(uuid, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_seller_quick_sheet(p_id_vendedor uuid, p_lat double precision, p_lng double precision) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'ag_catalog'
    AS $$
DECLARE
  v_actor  uuid;
  v_result jsonb;
BEGIN
  -- (a) JWT
  v_actor := auth.jwt_user_id_safe();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'JWT_ACTOR_INVALIDO' USING ERRCODE='P0001';
  END IF;

  -- (b) Validación de contrato (R-30)
  IF p_id_vendedor IS NULL THEN
    RAISE EXCEPTION 'PARAM_SELLER_NULL' USING ERRCODE='22023';
  END IF;
  IF p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180 THEN
    RAISE EXCEPTION 'PARAM_COORDS_INVALIDAS' USING ERRCODE='22023';
  END IF;

  -- (c) Payload
  SELECT jsonb_build_object(
           'status',            'ok',
           'id_vendedor',         s.id,
           'display_name',      s.nombre_visible,
           'thumbnail_url',     t.thumbnail_url,
           'distancia_metros',
             ROUND(ST_Distance(
               l.geom::geography,
               ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography
             )::numeric, 2),
           'location_updated_at', l.fecha_actualizacion,
           'top_products',
             COALESCE((
               SELECT jsonb_agg(jsonb_build_object(
                        'product_id',   tp.id_producto,
                        'product_name', tp.nombre_producto,
                        'price',        tp.price)
                      ORDER BY tp.rn)
               FROM   public.seller_top_products tp
               WHERE  tp.id_vendedor = s.id AND tp.rn <= 3
             ), '[]'::jsonb)
         )
    INTO v_result
    FROM auth.users s
    LEFT JOIN auth.ubicaciones l                 ON l.id_usuario  = s.id
    LEFT JOIN public.seller_primary_thumbnail t  ON t.id_vendedor = s.id
   WHERE s.id = p_id_vendedor
     AND s.role = 'seller'
     AND COALESCE(s.is_active, true) = true
     AND s.fecha_eliminacion IS NULL;

  RETURN COALESCE(
    v_result,
    jsonb_build_object('status','not_found','id_vendedor', p_id_vendedor)
  );
END; $$;


--
-- Name: get_seller_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_seller_stats(vendedor_uuid uuid) RETURNS TABLE(nivel_riesgo text, total_alertas bigint, alertas_activas bigint, score_promedio numeric, en_grafo boolean)
