END;
$$;


--
-- Name: get_simple_purchase_route(uuid, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_simple_purchase_route(p_plan_id uuid, p_buyer_lat double precision, p_buyer_lng double precision) RETURNS TABLE(stop_order integer, id_vendedor uuid, seller_lat double precision, seller_lng double precision, distance_meters double precision)
    LANGUAGE sql STABLE
    AS $$
WITH buyer_point AS (
    SELECT ST_SetSRID(ST_MakePoint(p_buyer_lng, p_buyer_lat), 4326)::geography AS geom
),
seller_points AS (
    SELECT
        d.id_vendedor,
        ST_Y(l.geom) AS seller_lat,
        ST_X(l.geom) AS seller_lng,
        ST_Distance((SELECT geom FROM buyer_point), l.geom::geography) AS distance_meters
    FROM public.v_buyer_plan_destinations d
    JOIN auth.ubicaciones l
      ON l.id_usuario = d.id_vendedor
     AND l.is_active = true
     AND l.fecha_eliminacion IS NULL
    WHERE d.id_plan = p_plan_id
      AND d.id_comprador = auth.jwt_user_id_safe()   -- R-82
)
SELECT
    (ROW_NUMBER() OVER (ORDER BY distance_meters ASC, id_vendedor))::INTEGER AS stop_order,
    id_vendedor, seller_lat, seller_lng, distance_meters
FROM seller_points
ORDER BY stop_order;
$$;


--
-- Name: get_system_kpis(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_system_kpis() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'total_users',           (SELECT COUNT(*) FROM usuarios WHERE activo = true),
    'total_articles_active', (SELECT COUNT(*) FROM articulos WHERE disponible = true),
    'total_articles',        (SELECT COUNT(*) FROM articulos),
    'total_exchanges',       (SELECT COUNT(*) FROM auth.intercambios),
    'exchanges_last30d',     (SELECT COUNT(*) FROM auth.intercambios
                               WHERE creado_en >= NOW() - INTERVAL '30 days'),
    'avg_platform_rating',   (SELECT COALESCE(ROUND(AVG(calificacion)::numeric, 2), 0)
                               FROM auth.resenas),
    'total_ratings',         (SELECT COUNT(*) FROM auth.resenas),
    'verified_users',        (SELECT COUNT(*) FROM usuarios WHERE verificado = true),
    'generated_at',          NOW()::text
  );
$$;


