--
-- Name: identity_verification_audit(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.identity_verification_audit(p_request_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
    v_uid  uuid := auth.current_jwt_user_id();
    v_role text := auth.current_jwt_role();
    v_rows jsonb;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'jwt requerido' USING ERRCODE = '42501';
    END IF;

    SELECT jsonb_agg(t ORDER BY t.id DESC)
      INTO v_rows
      FROM (
        SELECT a.id, a.request_id, a.actor_user_id, a.action,
               a.before_state, a.after_state
          FROM auth.identity_verification_audit a
         WHERE (p_request_id IS NULL OR a.request_id = p_request_id)
           AND (v_role = 'db_admin'
                OR a.actor_user_id = v_uid
                OR EXISTS (SELECT 1 FROM auth.identity_verification_requests r
                            WHERE r.id = a.request_id AND r.id_usuario = v_uid))
         ORDER BY a.id DESC
         LIMIT p_limit OFFSET p_offset
      ) t;

    RETURN jsonb_build_object('items', COALESCE(v_rows, '[]'::jsonb));
END;
$$;


--
-- Name: identity_verification_requests(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.identity_verification_requests(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
    v_uid  uuid := auth.current_jwt_user_id();
    v_role text := auth.current_jwt_role();
    v_rows jsonb;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'jwt requerido' USING ERRCODE = '42501';
    END IF;

    SELECT jsonb_agg(t ORDER BY t.requested_at DESC NULLS LAST)
      INTO v_rows
      FROM (
        SELECT r.id, r.id_usuario, r.document_type, r.document_number_masked,
               r.estado, r.requested_at, r.resolved_at, r.review_notes
          FROM auth.identity_verification_requests r
         WHERE (v_role = 'db_admin' OR r.id_usuario = v_uid)
         ORDER BY r.requested_at DESC NULLS LAST
         LIMIT p_limit OFFSET p_offset
      ) t;

    RETURN jsonb_build_object('items', COALESCE(v_rows, '[]'::jsonb));
END;
$$;


--
-- Name: introspect_radar_schema(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.introspect_radar_schema() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'ag_catalog'
    AS $_$
DECLARE
  v_result jsonb;
  v_has_postgis boolean;
  v_has_age     boolean;
  v_has_users   boolean;
  v_has_locations_geom boolean;
  v_graphs jsonb;
  v_labels jsonb;
  v_rpcs   jsonb;
  v_policies jsonb;
BEGIN
  -- Extensiones
  SELECT EXISTS(SELECT 1 FROM pg_extension WHERE extname='postgis') INTO v_has_postgis;
  SELECT EXISTS(SELECT 1 FROM pg_extension WHERE extname='age')     INTO v_has_age;

  -- Tablas críticas
  SELECT EXISTS(SELECT 1 FROM information_schema.tables
                WHERE table_schema='public' AND table_name='users') INTO v_has_users;

  SELECT EXISTS(SELECT 1 FROM information_schema.columns
                WHERE table_schema='public' AND table_name='locations' AND column_name='geom')
    INTO v_has_locations_geom;

  -- AGE: grafos y labels si aplica
  IF v_has_age THEN
    BEGIN
      EXECUTE $q$
        SELECT jsonb_agg(jsonb_build_object('graph_name', name, 'graphid', graphid))
        FROM ag_catalog.ag_graph
      $q$ INTO v_graphs;

      EXECUTE $q$
        SELECT jsonb_agg(jsonb_build_object('graph', g.name, 'label', l.name, 'kind', l.kind))
        FROM ag_catalog.ag_label l JOIN ag_catalog.ag_graph g ON g.graphid = l.graph
      $q$ INTO v_labels;
    EXCEPTION WHEN OTHERS THEN
      v_graphs := '[]'::jsonb; v_labels := '[]'::jsonb;
    END;
  ELSE
    v_graphs := '[]'::jsonb; v_labels := '[]'::jsonb;
  END IF;

  -- RPCs esperadas
  SELECT jsonb_agg(jsonb_build_object(
           'name', p.proname,
           'args', pg_get_function_identity_arguments(p.oid)
         ))
    INTO v_rpcs
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public'
     AND p.proname IN ('buscar_vendedores_cercanos','get_seller_quick_sheet','get_age_rank_score');

  -- Políticas RLS activas
  SELECT jsonb_agg(jsonb_build_object(
           'table', tablename, 'policy', policyname, 'cmd', cmd, 'roles', roles
         ))
    INTO v_policies
    FROM pg_policies
   WHERE schemaname='public'
     AND tablename IN ('users','locations','products','product_images','orders');

  v_result := jsonb_build_object(
    'status', 'ok',
    'timestamp', now(),
    'extensions', jsonb_build_object('postgis', v_has_postgis, 'age', v_has_age),
    'tables', jsonb_build_object(
      'users', v_has_users,
      'locations_has_geom', v_has_locations_geom
    ),
    'age', jsonb_build_object('graphs', COALESCE(v_graphs,'[]'::jsonb),
                              'labels', COALESCE(v_labels,'[]'::jsonb)),
    'rpcs',     COALESCE(v_rpcs,'[]'::jsonb),
    'policies', COALESCE(v_policies,'[]'::jsonb),
    'degradation', jsonb_build_object(
      'age_missing_action', 'rank_score := 0 (R-88 degradación controlada)',
      'postgis_missing_action', 'ABORT — POSTGIS_NO_DISPONIBLE'
    )
  );

  RETURN v_result;
END;
$_$;


--
-- Name: introspect_radar_schema_audited(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.introspect_radar_schema_audited() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_r jsonb;
BEGIN
  v_r := public.introspect_radar_schema();
  INSERT INTO public.introspection_audit_log(result) VALUES (v_r);
  RETURN v_r;
END; $$;


