--
-- Name: is_buyer_near_favorite_seller(uuid, uuid, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_buyer_near_favorite_seller(p_id_comprador uuid, p_id_vendedor uuid, p_buyer_lat double precision, p_buyer_lng double precision, p_radius_meters double precision DEFAULT 500) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_seller_geom GEOGRAPHY;
    v_buyer_geom  GEOGRAPHY;
BEGIN
    SELECT l.geom::geography
    INTO v_seller_geom
    FROM auth.ubicaciones l
    WHERE l.id_usuario = p_id_vendedor
      AND l.is_active = true
      AND l.fecha_eliminacion IS NULL
      AND l.geom IS NOT NULL
    ORDER BY l.fecha_actualizacion DESC NULLS LAST, l.fecha_creacion DESC NULLS LAST
    LIMIT 1;

    IF v_seller_geom IS NULL THEN
        RETURN false;
    END IF;

    v_buyer_geom := ST_SetSRID(ST_MakePoint(p_buyer_lng, p_buyer_lat), 4326)::geography;
    RETURN ST_DWithin(v_buyer_geom, v_seller_geom, p_radius_meters);
END;
$$;


