BEGIN
  RETURN EXISTS (
    SELECT 1 FROM auth.users
    WHERE id       = v_actor_id
      AND role     = 'SuperAdmin'
      AND COALESCE(is_active, false) = true
      AND fecha_eliminacion IS NULL
  );
END;
$$;


--
-- Name: log_admin_analytics_event(text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_admin_analytics_event(p_event_type text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_old_state jsonb DEFAULT NULL::jsonb, p_new_state jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO audit.admin_analytics_logs (
    tipo_evento, tipo_entidad, id_entidad, id_actor,
    old_state, new_state, client_ip, user_agent
  ) VALUES (
    p_event_type, p_entity_type, p_entity_id,
    (current_setting('request.jwt.claims', true)::jsonb->>'sub')::UUID,
    p_old_state, p_new_state,
    current_setting('request.headers', true)::jsonb->>'x-client-ip',
    current_setting('request.headers', true)::jsonb->>'user-agent'
  );
END;
$$;


--
-- Name: log_admin_risk_event(text, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_admin_risk_event(p_action text, p_target_kind text, p_target_id text, p_reason text, p_before_state jsonb DEFAULT NULL::jsonb, p_after_state jsonb DEFAULT NULL::jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_id BIGINT;
BEGIN
  IF p_action IS NULL OR p_target_kind IS NULL OR p_target_id IS NULL
     OR p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'audit_contract_violation' USING ERRCODE='23514';
  END IF;

  INSERT INTO auth.auditoria(
    action, id_actor, target_kind, id_objetivo, reason, before_state, after_state,
    request_id, correlation_id
  ) VALUES (
    p_action,
    public.get_app_actor_id(),
    p_target_kind, p_target_id, p_reason, p_before_state, p_after_state,
    NULLIF(current_setting('request.headers', true)::jsonb ->> 'x-request-id',''),
    NULLIF(current_setting('request.headers', true)::jsonb ->> 'x-correlation-id','')
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: log_audit_event(text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_audit_event(p_event_type text, p_payload jsonb DEFAULT '{}'::jsonb, p_cu_origen text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'public', 'pg_temp'
    AS $$
DECLARE
  v_claims jsonb;
  v_actor_id uuid;
  v_actor_role text;
BEGIN
  v_claims := COALESCE(current_setting('request.jwt.claims', true)::jsonb, '{}'::jsonb);
  BEGIN
    v_actor_id := auth.fn_current_user_id();
  EXCEPTION WHEN OTHERS THEN
    v_actor_id := NULL;
  END;
  v_actor_role := COALESCE(v_claims ->> 'role', current_user);

  INSERT INTO auth.superset_audit_log (tipo_evento, actor_role, event_payload, cu_origen)
  VALUES (p_event_type, v_actor_role, COALESCE(p_payload, '{}'::jsonb), p_cu_origen);
END;
$$;


--
-- Name: log_interaction_event(uuid, uuid, uuid, text, double precision, double precision, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_interaction_event(p_user_id uuid, p_id_vendedor uuid, p_product_id uuid, p_event_type text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
    v_actor_id UUID;
    v_event_id UUID;
BEGIN
    v_actor_id := auth.jwt_user_id_safe();
    IF v_actor_id IS NULL OR v_actor_id <> p_user_id THEN
        RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO' USING ERRCODE = '28000';
    END IF;

    IF p_event_type NOT IN ('view','click','save','route_open','plan_add','purchase_confirmed') THEN
        RAISE EXCEPTION 'EVENT_TYPE_INVALIDO' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.interaction_events (
        id_usuario, id_vendedor, id_producto, tipo_evento, geom, metadata
    )
    VALUES (
        p_user_id, p_id_vendedor, p_product_id, p_event_type,
        CASE WHEN p_lat IS NOT NULL AND p_lng IS NOT NULL
             THEN ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)
             ELSE NULL END,
        COALESCE(p_metadata,'{}'::jsonb)
    )
    RETURNING id INTO v_event_id;

    RETURN jsonb_build_object('status','OK','event_id',v_event_id,'event_type',p_event_type);
END;
$$;


--
-- Name: moderar_producto(uuid, numeric, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.moderar_producto(p_producto_id uuid, p_nuevo_precio numeric DEFAULT NULL::numeric, p_nuevo_stock integer DEFAULT NULL::integer, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_antes JSONB;
  v_despues JSONB;
  v_actor UUID := public.get_app_actor_id();
  v_accion TEXT;
BEGIN
  IF NOT public.is_admin_activo() THEN
    RAISE EXCEPTION 'acceso denegado' USING ERRCODE='42501';
  END IF;
  IF p_motivo IS NULL OR length(p_motivo) < 8 THEN
    RAISE EXCEPTION 'motivo obligatorio (mínimo 8 chars)' USING ERRCODE='22023';
  END IF;

  SELECT to_jsonb(p) INTO v_antes FROM auth.productos p WHERE id=p_producto_id;
  IF v_antes IS NULL THEN
    RAISE EXCEPTION 'producto inexistente' USING ERRCODE='P0001';
  END IF;

  UPDATE auth.productos
     SET precio = COALESCE(p_nuevo_precio, precio),
         stock  = COALESCE(p_nuevo_stock,  stock)
   WHERE id=p_producto_id;

  SELECT to_jsonb(p) INTO v_despues FROM auth.productos p WHERE id=p_producto_id;
  v_accion := CASE
    WHEN p_nuevo_precio IS NOT NULL AND p_nuevo_stock IS NULL THEN 'PRODUCTO_MODERAR_PRECIO'
    WHEN p_nuevo_stock  IS NOT NULL AND p_nuevo_precio IS NULL THEN 'PRODUCTO_MODERAR_STOCK'
    ELSE 'PRODUCTO_MODERAR_PRECIO'
  END;

  INSERT INTO public.moderacion_h_audit(accion, entidad_tipo, entidad_id,
    valor_antes, valor_despues, motivo, id_actor)
  VALUES (v_accion,'producto',p_producto_id, v_antes, v_despues, p_motivo, v_actor);

  PERFORM public._age_reflejar_moderacion(v_actor, p_producto_id, v_accion);

  RETURN jsonb_build_object('ok',true,'antes',v_antes,'despues',v_despues);
END $$;


