--
-- Name: notify_ddl_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_ddl_change() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  schemas_sync TEXT[] := ARRAY['public','auth','app','analytics','admin','seller',
    'notifications','disputes','fraud','kambalache_cu','moderation','topology',
    'smtp_posix_graph','api','audit'];
  cmd RECORD;
BEGIN
  FOR cmd IN
    SELECT c.schema_name, c.object_identity, c.object_type
    FROM pg_event_trigger_ddl_commands() AS c
    WHERE c.schema_name = ANY(schemas_sync)
  LOOP
    PERFORM pg_notify('ddl_change',
      json_build_object(
        'schema', cmd.schema_name,
        'obj_identity', cmd.object_identity,
        'obj_type', cmd.object_type,
        'cmd_tag', tg_tag,
        'ts', clock_timestamp()
      )::text
    );
  END LOOP;
END;
$$;


--
-- Name: obtener_estadisticas_vendedor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obtener_estadisticas_vendedor(vendedor_uuid uuid) RETURNS TABLE(nivel_riesgo text, total_alertas bigint, alertas_activas bigint, score_promedio numeric, en_grafo boolean)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'fraud', 'analytics', 'ag_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_age_ok boolean := false;
  v_en_grafo bigint := 0;
BEGIN
  SELECT EXISTS (SELECT 1 FROM pg_extension WHERE extname='age') INTO v_age_ok;

  IF v_age_ok THEN
    EXECUTE 'SELECT count(*) FROM ag_catalog.cypher(''smtp_posix_graph'', $$ MATCH (u:User {id_usuario: "' || vendedor_uuid::text || '"})-[:TIENE_RIESGO_ALTO]->() RETURN u $$) AS u(agtype agtype)'
      INTO v_en_grafo;
  END IF;

  RETURN QUERY
  SELECT urp.risk_level::text,
         (SELECT count(*) FROM public.alertas_criticas al WHERE al.id_vendedor = vendedor_uuid) AS total_alertas,
         (SELECT count(*) FROM public.alertas_criticas al WHERE al.id_vendedor = vendedor_uuid AND al.is_active) AS alertas_activas,
         urp.current_risk_score::numeric AS score_promedio,
         (v_en_grafo > 0) AS en_grafo
    FROM fraud.user_risk_profile urp
   WHERE urp.id_usuario = vendedor_uuid;
END;
$_$;


--
-- Name: obtener_metricas_grafo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obtener_metricas_grafo() RETURNS TABLE(metrica text, valor bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'ag_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_age_ok boolean := false;
BEGIN
  SELECT EXISTS (SELECT 1 FROM pg_extension WHERE extname='age') INTO v_age_ok;

  IF NOT v_age_ok THEN
    RAISE EXCEPTION 'AGE no disponible en esta instancia';
  END IF;

  RETURN QUERY
  SELECT 'usuarios_grafo'::text, count(*)::bigint
    FROM cypher('smtp_posix_graph', $$ MATCH (u:User) RETURN u $$) AS u(agtype agtype);
  RETURN QUERY
  SELECT 'alertas_riesgo_grafo'::text, count(*)::bigint
    FROM cypher('smtp_posix_graph', $$ MATCH (a:AlertaRiesgo) RETURN a $$) AS a(agtype agtype);
  RETURN QUERY
  SELECT 'relaciones_riesgo'::text, count(*)::bigint
    FROM cypher('smtp_posix_graph', $$ MATCH ()-[r:TIENE_RIESGO_ALTO]->() RETURN r $$) AS r(agtype agtype);
END;
$_$;


--
-- Name: ocultar_alerta_dashboard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ocultar_alerta_dashboard(p_alerta_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_admin_id  UUID;
  v_timestamp TEXT;
BEGIN
  -- 1. Autenticación
  v_admin_id := public.get_app_actor_id();
  IF NOT public.is_admin_activo() THEN
    RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO: admin % no está activo', v_admin_id;
  END IF;

  -- 2. Ocultar del dashboard (visible=false, alerta sigue activa e histórica)
  UPDATE public.alertas_criticas
  SET    visible    = false,
         fecha_actualizacion = now()
  WHERE  id        = p_alerta_id
    AND  is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ALERTA_NO_ENCONTRADA_O_INACTIVA: %', p_alerta_id;
  END IF;

  -- 3. Auditoría WORM
  v_timestamp := to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"');

  INSERT INTO public.h_alertas_audit (
    alerta_id, id_actor, accion, datos_despues
  ) VALUES (
    p_alerta_id,
    v_admin_id,
    'OCULTO',
    jsonb_build_object(
      'visible', false,
      'motivo',  'dismiss_dashboard',
      'ts',      v_timestamp
    )
  );

  -- 4. Respuesta
  RETURN jsonb_build_object(
    'status',    'SUCCESS',
    'alerta_id', p_alerta_id,
    'visible',   false,
    'actor_id',  v_admin_id,
    'timestamp', v_timestamp
  );
END;
$$;


--
-- Name: ocultar_ruta(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ocultar_ruta(p_funcion text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.is_superadmin_activo() THEN
    RAISE EXCEPTION 'denegado' USING ERRCODE='42501';
  END IF;
  EXECUTE format('ALTER FUNCTION public.%I SET SCHEMA privado', p_funcion);
  INSERT INTO public.h_doc_audit(tipo_cambio, objeto_tipo, objeto_nombre,
                                 ddl_command, id_actor, actor_source)
  VALUES ('ROUTE_HIDE','function', p_funcion,
          format('ALTER FUNCTION public.%s SET SCHEMA privado', p_funcion),
          public.get_app_actor_id(),'jwt');
END $$;


--
-- Name: prevent_physical_delete_admin_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_physical_delete_admin_users() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_purge text := current_setting('app.allow_physical_purge', true);
BEGIN
  -- Escape hatch para purga física LEGÍTIMA: los purgadores oficiales
  -- (auth.admin_purge_user, auth.rpc_admin_physical_purge_user) setean el GUC
  -- is_local=true antes del DELETE. Aceptamos 'true' y 'on' (histórico) para no
  -- romper ninguno de los dos.
  IF v_purge IN ('true', 'on') THEN
    RETURN OLD;
  END IF;

  RAISE EXCEPTION
    'DELETE físico bloqueado sobre auth.users (%) fila id=%. El borrado de usuarios pasa SIEMPRE por la RPC soft-delete: POST /rpc/rpc_admin_soft_delete_user (auth.rpc_admin_soft_delete_user). Para purga física legítima use auth.admin_purge_user / auth.rpc_admin_physical_purge_user (ellos gestionan app.allow_physical_purge). Escape hatch de superusuario: SET LOCAL app.allow_physical_purge = ''true''.',
    TG_TABLE_NAME, OLD.id
    USING ERRCODE = 'P0001',
          HINT = 'Use la RPC soft-delete o el GUC app.allow_physical_purge';
END;
$$;


--
-- Name: product_search_audit(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.product_search_audit(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
    v_uid  uuid := auth.current_jwt_user_id();
    v_role text := auth.current_jwt_role();
    v_rows jsonb;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'jwt requerido' USING ERRCODE = '42501';
    END IF;

    SELECT jsonb_agg(t ORDER BY t.fecha_creacion DESC NULLS LAST)
      INTO v_rows
      FROM (
        SELECT a.id, a.search_text, a.latitud, a.longitud,
               COALESCE(a.radio_metros, (a.radio_km::numeric)::integer) AS radio_m,
               a.result_count, a.resultados_count, a.requester_role,
               a.requester_user_id, a.id_usuario, a.fecha_creacion
          FROM auth.product_search_audit a
         WHERE (v_role = 'db_admin'
                OR a.requester_user_id = v_uid
                OR a.id_usuario = v_uid
                OR a.id_actor = v_uid)
         ORDER BY a.fecha_creacion DESC NULLS LAST
         LIMIT p_limit OFFSET p_offset
      ) t;

    RETURN jsonb_build_object('items', COALESCE(v_rows, '[]'::jsonb));
END;
$$;


--
-- Name: radar_mvt(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.radar_mvt(z integer, x integer, y integer) RETURNS bytea
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'ag_catalog'
    AS $$
DECLARE
  v_mvt bytea;
  v_bbox geometry;
BEGIN
  IF z < 0 OR z > 22 THEN
    RAISE EXCEPTION 'PARAM_Z_FUERA_DE_RANGO' USING ERRCODE='22023';
  END IF;

  v_bbox := ST_TileEnvelope(z, x, y);   -- SRID 3857

  SELECT ST_AsMVT(t, 'sellers', 4096, 'geom')
    INTO v_mvt
    FROM (
      SELECT sa.id_vendedor,
             ST_AsMVTGeom(
               ST_Transform(sa.geom, 3857),
               v_bbox, 4096, 64, true) AS geom
      FROM public.sellers_active sa
      WHERE sa.geom && ST_Transform(v_bbox, 4326)
      LIMIT 5000
    ) t
   WHERE t.geom IS NOT NULL;

  RETURN COALESCE(v_mvt, ''::bytea);
END; $$;


--
-- Name: reactivar_vendedor(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reactivar_vendedor(p_usuario_id uuid, p_motivo text, p_reactivar_productos boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_actor UUID := public.get_app_actor_id();
  v_n_prod INT := 0;
BEGIN
  IF NOT public.is_admin_activo() THEN
    RAISE EXCEPTION 'acceso denegado' USING ERRCODE='42501';
  END IF;
  IF length(COALESCE(p_motivo,'')) < 8 THEN
    RAISE EXCEPTION 'motivo obligatorio (mínimo 8 chars)' USING ERRCODE='22023';
  END IF;

  UPDATE auth.users
     SET is_active=true, fecha_eliminacion=NULL
   WHERE id=p_usuario_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'usuario inexistente' USING ERRCODE='P0001';
  END IF;

  IF p_reactivar_productos THEN
    UPDATE auth.productos
       SET activo=true, fecha_eliminacion=NULL
     WHERE id_vendedor=p_usuario_id
       AND fecha_eliminacion IS NOT NULL;
    GET DIAGNOSTICS v_n_prod = ROW_COUNT;
  END IF;

  INSERT INTO public.moderacion_h_audit(accion, entidad_tipo, entidad_id,
    valor_antes, valor_despues, motivo, id_actor)
  VALUES ('PRODUCTO_RESTAURAR','producto', p_usuario_id,
    jsonb_build_object('is_active',false),
    jsonb_build_object('is_active',true,'n_productos',v_n_prod),
    p_motivo, v_actor);

  -- Reversión AGE best-effort
  BEGIN
    PERFORM 1 FROM pg_extension WHERE extname='age';
    IF FOUND THEN
      PERFORM public.age_execute_safe(format($c$
        SELECT * FROM cypher('kambalache_marketplace_graph', $q$
          MERGE (u:Seller {id:'%s'})
          CREATE (u)-[:REACTIVADO {motivo:'%s', ts:'%s', admin:'%s'}]->
            (:EventoReactivacion)
        $q$) AS (v agtype)$c$, p_usuario_id, p_motivo, now(), v_actor));
    END IF;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok',true,'usuario',p_usuario_id,'productos_reactivados',v_n_prod);
END $_$;


