--
-- Name: registrar_accion_admin(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_accion_admin(p_alerta_id uuid, p_accion text, p_notas text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_admin_id    UUID;
  v_estado_nuevo TEXT;
  v_before      JSONB;
  v_timestamp   TEXT;
BEGIN
  -- 1. Autenticación y autorización
  v_admin_id := public.get_app_actor_id();
  IF NOT public.is_admin_activo() THEN
    RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO: admin % no está activo', v_admin_id;
  END IF;

  -- 2. Validar acción permitida
  IF p_accion NOT IN ('APROBO', 'IGNORO', 'CERRO') THEN
    RAISE EXCEPTION 'ACCION_INVALIDA: % — valores permitidos: APROBO, IGNORO, CERRO', p_accion;
  END IF;

  -- 3. Mapeo de acción a estado
  v_estado_nuevo := CASE p_accion
    WHEN 'APROBO' THEN 'PROCESADA'
    WHEN 'IGNORO' THEN 'IGNORADA'
    WHEN 'CERRO'  THEN 'PROCESADA'
  END;

  -- 4. Bloqueo y snapshot de la alerta
  SELECT to_jsonb(a)
  INTO   v_before
  FROM   public.alertas_criticas a
  WHERE  a.id        = p_alerta_id
    AND  a.is_active = true
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ALERTA_NO_PROCESABLE: alerta % no encontrada o inactiva', p_alerta_id;
  END IF;

  IF (v_before->>'estado') IS DISTINCT FROM 'PENDIENTE' THEN
    RAISE EXCEPTION 'ALERTA_NO_PROCESABLE: alerta % ya en estado %',
      p_alerta_id, v_before->>'estado';
  END IF;

  -- 5. Actualizar alerta
  UPDATE public.alertas_criticas
  SET    estado       = v_estado_nuevo,
         resuelto_por = v_admin_id,
         resuelto_at  = now(),
         fecha_actualizacion   = now()
  WHERE  id = p_alerta_id;

  -- 6. Registro de auditoría (WORM)
  v_timestamp := to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"');

  INSERT INTO public.h_alertas_audit (
    alerta_id, id_actor, accion, datos_antes, datos_despues
  ) VALUES (
    p_alerta_id,
    v_admin_id,
    p_accion,
    v_before,
    jsonb_build_object(
      'estado_nuevo', v_estado_nuevo,
      'notas',        p_notas
    )
  );

  -- 7. Sincronización AGE (degradación elegante si AGE no disponible)
  BEGIN
    PERFORM * FROM cypher('smtp_posix_graph', $cypher$
      MATCH (admin:User {id_sql: $aid})
      MATCH (a:AlertaCritica {id_sql: $alerta})
      CREATE (admin)-[:VALIDO_ADMIN {
        accion: $accion,
        fecha:  $ts,
        notas:  $notas
      }]->(a)
      SET a.estado = $estado
    $cypher$, jsonb_build_object(
      'aid',    v_admin_id::text,
      'alerta', p_alerta_id::text,
      'accion', p_accion,
      'ts',     v_timestamp,
      'notas',  COALESCE(p_notas, ''),
      'estado', v_estado_nuevo
    )) AS (r agtype);
  EXCEPTION WHEN OTHERS THEN
    NULL; -- AGE degradation: SQL y auditoría siguen siendo consistentes
  END;

  -- 8. Respuesta
  RETURN jsonb_build_object(
    'status',    'SUCCESS',
    'alerta_id', p_alerta_id,
    'accion',    p_accion,
    'estado',    v_estado_nuevo,
    'actor_id',  v_admin_id,
    'timestamp', v_timestamp
  );
END;
$_$;


--
-- Name: reportes_moderacion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reportes_moderacion() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'moderation', 'app', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := app.current_request_user_id_safe();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_UID_REQUIRED' USING ERRCODE = '28000';
  END IF;
  RETURN jsonb_build_object(
    'generado_en', now(),
    'cola_moderacion', jsonb_build_object(
      'total', (SELECT count(*) FROM moderation.moderation_queue),
      'pendientes', (SELECT count(*) FROM moderation.moderation_queue WHERE NOT is_completed),
      'completadas', (SELECT count(*) FROM moderation.moderation_queue WHERE is_completed),
      'vencidas', (SELECT count(*) FROM moderation.moderation_queue
                   WHERE NOT is_completed AND expected_review_by < now())
    ),
    'contenido_moderacion', jsonb_build_object(
      'total_activo', (SELECT count(*) FROM app.content_moderation WHERE fecha_eliminacion IS NULL),
      'marcados', (SELECT count(*) FROM app.content_moderation
                    WHERE fecha_eliminacion IS NULL AND flagged_reason IS NOT NULL),
      'por_estado', COALESCE((
        SELECT jsonb_object_agg(e.estado, e.cnt)
        FROM (SELECT estado, count(*) AS cnt
              FROM app.content_moderation
              WHERE fecha_eliminacion IS NULL
              GROUP BY estado) e
      ), '{}'::jsonb)
    )
  );
END
$$;


--
-- Name: reputacion_dashboard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reputacion_dashboard(p_vendedor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_actor_id uuid;
  v_result jsonb;
  v_total_resenas integer := 0;
  v_promedio numeric(5,2) := 0;
  v_resenas_positivas integer := 0;
  v_resenas_negativas integer := 0;
  v_distribucion jsonb := '{}'::jsonb;
  v_ultimas_resenas jsonb := '[]'::jsonb;
  v_ordenes_completadas integer := 0;
BEGIN
  v_actor_id := COALESCE(p_vendedor_id, auth.jwt_user_id_safe());

  IF v_actor_id IS NULL THEN
    RETURN '{"error": "vendedor_no_especificado"}'::jsonb;
  END IF;

  -- Estadísticas de reseñas
  SELECT
    COUNT(*),
    COALESCE(ROUND(AVG(calificacion)::numeric, 2), 0),
    COUNT(*) FILTER (WHERE calificacion >= 4),
    COUNT(*) FILTER (WHERE calificacion <= 2)
  INTO
    v_total_resenas, v_promedio, v_resenas_positivas, v_resenas_negativas
  FROM auth.resenas
  WHERE id_vendedor = v_actor_id AND activo = true;

  -- Distribución de calificaciones
  SELECT jsonb_object_agg(grupo, cnt)
  INTO v_distribucion
  FROM (
    SELECT
      CASE
        WHEN calificacion = 5 THEN '5_excelente'
        WHEN calificacion = 4 THEN '4_buena'
        WHEN calificacion = 3 THEN '3_regular'
        WHEN calificacion = 2 THEN '2_mala'
        ELSE '1_pesima'
      END as grupo,
      COUNT(*) as cnt
    FROM auth.resenas
    WHERE id_vendedor = v_actor_id AND activo = true
    GROUP BY grupo
  ) d;

  -- Últimas 5 reseñas
  SELECT jsonb_agg(jsonb_build_object(
    'calificacion', r.calificacion,
    'comentario', r.comentario,
    'fecha', r.fecha_creacion,
    'comprador_id', r.id_comprador
  ) ORDER BY r.fecha_creacion DESC)
  INTO v_ultimas_resenas
  FROM (
    SELECT calificacion, comentario, fecha_creacion, id_comprador
    FROM auth.resenas
    WHERE id_vendedor = v_actor_id AND activo = true
    ORDER BY fecha_creacion DESC
    LIMIT 5
  ) r;

  -- Órdenes completadas
  SELECT COUNT(*) INTO v_ordenes_completadas
  FROM auth.ordenes
  WHERE id_vendedor = v_actor_id
    AND estado IN ('completada', 'entregada')
    AND fecha_eliminacion IS NULL;

  -- Armar resultado
  v_result := jsonb_build_object(
    'vendedor_id', v_actor_id::text,
    'total_resenas', v_total_resenas,
    'promedio_calificacion', v_promedio::text,
    'resenas_positivas', v_resenas_positivas,
    'resenas_negativas', v_resenas_negativas,
    'distribucion', COALESCE(v_distribucion, '{}'::jsonb),
    'ultimas_resenas', COALESCE(v_ultimas_resenas, '[]'::jsonb),
    'ordenes_completadas', v_ordenes_completadas,
    'score_reputacion', CASE
      WHEN v_total_resenas = 0 THEN 0
      ELSE ROUND((v_promedio / 5.0) * 100, 2)
    END
  );

  RETURN v_result;
END;
$$;


--
-- Name: resolve_admin_alert(uuid, uuid, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_admin_alert(p_alert_id uuid, p_admin_id uuid, p_accion character varying, p_notas text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_alerta RECORD;
BEGIN
    -- Verificar permisos
    IF current_user_role() != 'admin' THEN
        RAISE EXCEPTION 'Acceso denegado: se requiere rol admin' USING ERRCODE = 'P0003';
    END IF;

    SELECT * INTO v_alerta FROM admin_alerts WHERE id = p_alert_id;
    IF NOT FOUND THEN
        RETURN json_build_object('success', FALSE, 'error', 'Alerta no encontrada');
    END IF;

    IF v_alerta.estado IN ('resuelta', 'descartada') THEN
        RETURN json_build_object('success', FALSE, 'error', 'Alerta ya cerrada con estado: ' || v_alerta.estado);
    END IF;

    -- Validar acción
    IF p_accion NOT IN ('revisar', 'escalar', 'resolver', 'descartar', 'comentar', 'bloquear_usuario', 'suspender_usuario') THEN
        RETURN json_build_object('success', FALSE, 'error', 'Acción inválida');
    END IF;

    -- Registrar acción
    INSERT INTO admin_alert_actions (alerta_id, admin_id, accion, notas)
    VALUES (p_alert_id, p_admin_id, p_accion, p_notas);

    -- Actualizar estado de alerta según acción
    IF p_accion = 'resolver' THEN
        UPDATE admin_alerts SET estado = 'resuelta', fecha_resolucion = NOW(), resuelta_por = p_admin_id
        WHERE id = p_alert_id;
    ELSIF p_accion = 'descartar' THEN
        UPDATE admin_alerts SET estado = 'descartada', fecha_resolucion = NOW(), resuelta_por = p_admin_id
        WHERE id = p_alert_id;
    ELSIF p_accion = 'escalar' THEN
        UPDATE admin_alerts SET estado = 'escalada', severidad = 'critica'
        WHERE id = p_alert_id;
    ELSIF p_accion = 'revisar' THEN
        UPDATE admin_alerts SET estado = 'en_revision'
        WHERE id = p_alert_id;
    ELSIF p_accion IN ('bloquear_usuario', 'suspender_usuario') THEN
        -- Desactivar usuario si se bloquea/suspende
        IF v_alerta.usuario_afectado_id IS NOT NULL THEN
            UPDATE usuarios SET activo = FALSE WHERE id = v_alerta.usuario_afectado_id;
        END IF;
        UPDATE admin_alerts SET estado = 'resuelta', fecha_resolucion = NOW(), resuelta_por = p_admin_id
        WHERE id = p_alert_id;
    END IF;

    RETURN json_build_object(
        'success', TRUE,
        'alerta_id', p_alert_id,
        'accion', p_accion,
        'nuevo_estado', (SELECT estado FROM admin_alerts WHERE id = p_alert_id),
        'mensaje', 'Acción registrada exitosamente'
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object('success', FALSE, 'error', SQLERRM);
END;
$$;


--
-- Name: FUNCTION resolve_admin_alert(p_alert_id uuid, p_admin_id uuid, p_accion character varying, p_notas text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_admin_alert(p_alert_id uuid, p_admin_id uuid, p_accion character varying, p_notas text) IS 'Ejecuta una acción sobre una alerta administrativa (resolver, escalar, descartar, etc.). Requiere rol admin. v3.12';


--
-- Name: restaurar_producto(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurar_producto(p_producto_id uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE v_antes JSONB; v_despues JSONB; v_actor UUID := public.get_app_actor_id();
BEGIN
  IF NOT public.is_admin_activo() THEN RAISE EXCEPTION 'denegado' USING ERRCODE='42501'; END IF;
  IF length(COALESCE(p_motivo,'')) < 8 THEN RAISE EXCEPTION 'motivo obligatorio' USING ERRCODE='22023'; END IF;

  SELECT to_jsonb(p) INTO v_antes FROM auth.productos p WHERE id=p_producto_id;
  UPDATE auth.productos SET activo=true, fecha_eliminacion=NULL WHERE id=p_producto_id;
  SELECT to_jsonb(p) INTO v_despues FROM auth.productos p WHERE id=p_producto_id;

  INSERT INTO public.moderacion_h_audit(accion, entidad_tipo, entidad_id,
    valor_antes, valor_despues, motivo, id_actor)
  VALUES ('PRODUCTO_RESTAURAR','producto',p_producto_id,v_antes,v_despues,p_motivo,v_actor);

  PERFORM public._age_reflejar_moderacion(v_actor, p_producto_id, 'PRODUCTO_RESTAURAR');
  RETURN jsonb_build_object('ok',true);
END $$;


--
-- Name: restaurar_ruta(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurar_ruta(p_funcion text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.is_superadmin_activo() THEN
    RAISE EXCEPTION 'denegado' USING ERRCODE='42501';
  END IF;
  EXECUTE format('ALTER FUNCTION privado.%I SET SCHEMA public', p_funcion);
  INSERT INTO public.h_doc_audit(tipo_cambio, objeto_tipo, objeto_nombre,
                                 ddl_command, id_actor, actor_source)
  VALUES ('ROUTE_SHOW','function', p_funcion,
          format('ALTER FUNCTION privado.%s SET SCHEMA public', p_funcion),
          public.get_app_actor_id(),'jwt');
END $$;


--
-- Name: revertir_cambio_vendedor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revertir_cambio_vendedor(alerta_uuid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_id_vendedor    UUID;
  v_campo          TEXT;
  v_valor_antiguo  TEXT;
  v_admin_id       UUID;
  v_alerta_estado  TEXT;
  v_before         JSONB;
  v_timestamp      TEXT;
  v_rows           INTEGER;
BEGIN
  -- 1. Autenticación
  v_admin_id := public.get_app_actor_id();
  IF NOT public.is_admin_activo() THEN
    RAISE EXCEPTION 'ACTOR_NO_AUTORIZADO: admin % no está activo', v_admin_id;
  END IF;

  -- 2. Bloqueo y lectura de la alerta
  SELECT a.id_vendedor,
         a.campo_afectado,
         a.valor_anterior,
         a.estado,
         to_jsonb(a)
  INTO   v_id_vendedor,
         v_campo,
         v_valor_antiguo,
         v_alerta_estado,
         v_before
  FROM   public.alertas_criticas a
  WHERE  a.id        = alerta_uuid
    AND  a.is_active = true
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ALERTA_NO_ENCONTRADA: UUID %', alerta_uuid;
  END IF;

  -- 3. Verificar estado procesable
  IF v_alerta_estado <> 'PENDIENTE' THEN
    RAISE EXCEPTION 'ALERTA_YA_PROCESADA: estado actual = %', v_alerta_estado;
  END IF;

  -- 4. Whitelist de campo
  IF NOT public.validar_campo_reversible(v_campo) THEN
    RAISE EXCEPTION 'CAMPO_NO_REVERSIBLE: % no está en la whitelist', v_campo;
  END IF;

  -- 5. Revertir campo en auth.users (SQL dinámico seguro: campo whitelist + valor de alerta + UUID exacto)
  EXECUTE format(
    'UPDATE auth.users SET %I = %L, updated_at = now()
     WHERE id = %L AND is_active = true AND deleted_at IS NULL',
    v_campo, v_valor_antiguo, v_id_vendedor
  );

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'VENDEDOR_NO_ENCONTRADO_O_INACTIVO: UUID %', v_id_vendedor;
  END IF;

  -- 6. Marcar alerta como REVERTIDA
  UPDATE public.alertas_criticas
  SET    estado       = 'REVERTIDA',
         resuelto_por = v_admin_id,
         resuelto_at  = now(),
         fecha_actualizacion   = now()
  WHERE  id = alerta_uuid;

  -- 7. Auditoría WORM
  v_timestamp := to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"');

  INSERT INTO public.h_alertas_audit (
    alerta_id, id_actor, accion, datos_antes, datos_despues
  ) VALUES (
    alerta_uuid,
    v_admin_id,
    'REVERTIO',
    v_before,
    jsonb_build_object(
      'id_vendedor', v_id_vendedor,
      'campo',       v_campo,
      'revertido_a', v_valor_antiguo,
      'timestamp',   v_timestamp
    )
  );

  -- 8. Sincronización AGE (degradación elegante)
  BEGIN
    PERFORM * FROM cypher('kambalache_marketplace_graph', $cypher$
      MATCH (admin:Usuario  {id_sql: $aid})
      MATCH (v:Seller     {id_sql: $vid})
      MATCH (a:AlertaCritica{id_sql: $alerta})
      CREATE (admin)-[:REVERTIO_CAMBIO {
        fecha:       $ts,
        campo:       $campo,
        nivel_riesgo:'ALTO',
        inmutable:   true
      }]->(v)
      SET a.estado       = 'REVERTIDA',
          a.resuelto_por = $aid,
          a.resuelto_at  = $ts
    $cypher$, jsonb_build_object(
      'aid',    v_admin_id::text,
      'vid',    v_id_vendedor::text,
      'alerta', alerta_uuid::text,
      'ts',     v_timestamp,
      'campo',  v_campo
    )) AS (resultado agtype);
  EXCEPTION WHEN OTHERS THEN
    NULL; -- AGE degradation: SQL y auditoría siguen siendo consistentes
  END;

  -- 9. Respuesta
  RETURN jsonb_build_object(
    'status',      'SUCCESS',
    'alerta_id',   alerta_uuid,
    'id_vendedor', v_id_vendedor,
    'campo',       v_campo,
    'revertido_a', v_valor_antiguo,
    'actor_id',    v_admin_id,
    'timestamp',   v_timestamp
  );

EXCEPTION WHEN OTHERS THEN
  -- 10. Auditoría de error (también WORM — actor puede ser NULL si falla antes de obtenerlo)
  INSERT INTO public.h_alertas_audit (
    alerta_id, id_actor, accion, datos_antes
  ) VALUES (
    alerta_uuid,
    COALESCE(v_admin_id, uuid_nil()),
    'ERROR_REVERSION',
    jsonb_build_object(
      'error',    SQLERRM,
      'sqlstate', SQLSTATE
    )
  );
  RAISE;
END;
$_$;


