--
-- Name: rpc_v4_seller_accept_order(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_v4_seller_accept_order(p_order_id uuid, p_expected_fulfillment_days integer DEFAULT 7) RETURNS TABLE(success boolean, message text, estado text, fulfillment_date timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'seller', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_id_vendedor uuid;
  v_order_record record;
  v_fulfillment_date timestamptz;
BEGIN
  SELECT id INTO v_id_vendedor
  FROM seller.profiles
  WHERE id_usuario = auth.jwt_user_id_safe() AND is_verified = true;

  IF v_id_vendedor IS NULL THEN
    RETURN QUERY SELECT false, 'Vendedor no verificado'::text, NULL::text, NULL::timestamptz;
    RETURN;
  END IF;

  SELECT id, estado, id_vendedor
  INTO v_order_record
  FROM auth.ordenes
  WHERE id = p_order_id;

  IF v_order_record.id IS NULL THEN
    RETURN QUERY SELECT false, 'Orden no encontrada'::text, NULL::text, NULL::timestamptz;
    RETURN;
  END IF;

  IF v_order_record.id_vendedor != v_id_vendedor THEN
    RETURN QUERY SELECT false, 'No autorizado para esta orden'::text, NULL::text, NULL::timestamptz;
    RETURN;
  END IF;

  IF v_order_record.estado != 'pendiente' THEN
    RETURN QUERY SELECT false, 'Orden no está en estado pendiente'::text, v_order_record.estado::text, NULL::timestamptz;
    RETURN;
  END IF;

  v_fulfillment_date := now() + (p_expected_fulfillment_days || ' days')::interval;

  UPDATE auth.ordenes
  SET
    estado = 'confirmada',
    metadata = jsonb_set(
      COALESCE(metadata, '{}'::jsonb),
      '{accepted_at}', to_jsonb(now()::text)
    ),
    metadata = jsonb_set(
      COALESCE(metadata, '{}'::jsonb),
      '{expected_fulfillment}', to_jsonb(v_fulfillment_date::text)
    ),
    vendedor_listo_en = now(),
    fecha_actualizacion = now()
  WHERE id = p_order_id;

  INSERT INTO seller.order_actions (id_orden, id_vendedor, tipo_accion, action_status, expected_fulfillment_date, processed_at)
  VALUES (p_order_id, v_id_vendedor, 'accept', 'completed', v_fulfillment_date, now());

  INSERT INTO seller.order_timeline (id_orden, id_vendedor, tipo_evento, event_description, previous_status, new_status)
  VALUES (p_order_id, v_id_vendedor, 'order_confirmada', 'Orden aceptada por el vendedor', 'pendiente', 'confirmada');

  RETURN QUERY SELECT true, 'Orden aceptada exitosamente'::text, 'confirmada'::text, v_fulfillment_date;
END;
$$;


--
-- Name: safe_hide_alert(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.safe_hide_alert(p_alert_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_role  TEXT := COALESCE((current_setting('request.jwt.claims', true)::jsonb ->> 'role'),'');
  v_before JSONB;
BEGIN
  IF v_role NOT IN ('admin','super_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason)='' THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE='23514';
  END IF;

  SELECT to_jsonb(a) INTO v_before FROM public.admin_alerts a WHERE a.id=p_alert_id;
  IF v_before IS NULL THEN
    RAISE EXCEPTION 'alert_not_found' USING ERRCODE='P0002';
  END IF;

  UPDATE public.admin_alerts
     SET oculto_en_dash = TRUE, updated_at = NOW()
   WHERE id = p_alert_id AND oculto_en_dash = FALSE;

  PERFORM public.log_admin_risk_event(
    'ADMIN_HIDE_ALERT','alerta_admin',p_alert_id::text,p_reason,
    v_before,
    jsonb_set(v_before, '{oculto_en_dash}', 'true'::jsonb)
  );

  RETURN jsonb_build_object('ok',TRUE,'alert_id',p_alert_id);
END;
$$;


--
-- Name: sessions_tokens(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sessions_tokens() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := app.current_request_user_id_safe();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_UID_REQUIRED' USING ERRCODE = '28000';
  END IF;

  RETURN jsonb_build_object(
    'id_usuario', v_user_id,
    'sesiones', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'id', s.id,
               'expires_at', s.expires_at,
               'refresh_expires_at', s.refresh_expires_at,
               'revocado', s.revocado
             ) ORDER BY s.expires_at DESC NULLS LAST)
      FROM auth.sesiones_tokens s
      WHERE s.id_usuario = v_user_id
    ), '[]'::jsonb)
  );
END;
$$;


--
-- Name: sincronizar_grafo_comercial(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sincronizar_grafo_comercial() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_m text := 'sync_a';
BEGIN
  -- 1) limpieza idempotente (edges primero, luego vertices)
  DELETE FROM kambalache_marketplace_graph."VENDE"       WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;
  DELETE FROM kambalache_marketplace_graph."COMPRO"      WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;
  DELETE FROM kambalache_marketplace_graph."COMPRO_A"    WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;
  DELETE FROM kambalache_marketplace_graph."FAVORITO"    WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;
  DELETE FROM kambalache_marketplace_graph."RESENO_A"    WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;
  DELETE FROM kambalache_marketplace_graph."PERTENECE_A" WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;
  DELETE FROM kambalache_marketplace_graph."Seller"      WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;
  DELETE FROM kambalache_marketplace_graph."Buyer"       WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;
  DELETE FROM kambalache_marketplace_graph."Producto"    WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;
  DELETE FROM kambalache_marketplace_graph."Categoria"   WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;

  -- 2) vertices
  INSERT INTO kambalache_marketplace_graph."Seller" (properties)
  SELECT ag_catalog.agtype_build_map(
      'seller_id', u.id::text,
      'email', coalesce(u.email, ''),
      'tier', coalesce(u.default_tier_code, ''),
      'origen', v_m)
  FROM auth.users u WHERE u.role = 'seller';

  INSERT INTO kambalache_marketplace_graph."Buyer" (properties)
  SELECT ag_catalog.agtype_build_map(
      'buyer_id', u.id::text,
      'email', coalesce(u.email, ''),
      'tier', coalesce(u.default_tier_code, ''),
      'origen', v_m)
  FROM auth.users u WHERE u.role = 'buyer';

  INSERT INTO kambalache_marketplace_graph."Producto" (properties)
  SELECT ag_catalog.agtype_build_map(
      'producto_id', p.id::text,
      'nombre', coalesce(p.nombre, ''),
      'precio', coalesce(p.precio, 0)::text,
      'vendedor_id', coalesce(p.id_vendedor, '00000000-0000-0000-0000-000000000000')::text,
      'id_categoria', coalesce(p.id_categoria, '00000000-0000-0000-0000-000000000000')::text,
      'activo', coalesce(p.activo, false)::text,
      'origen', v_m)
  FROM auth.productos p;

  INSERT INTO kambalache_marketplace_graph."Categoria" (properties)
  SELECT ag_catalog.agtype_build_map(
      'categoria_id', c.id::text,
      'nombre', coalesce(c.nombre, ''),
      'origen', v_m)
  FROM auth.categorias c;

  -- 3) edges (start_id/end_id = graphid de los vertices)
  INSERT INTO kambalache_marketplace_graph."VENDE" (start_id, end_id, properties)
  SELECT s.id, p.id, ag_catalog.agtype_build_map('origen', v_m, 'data_prueba', 'true')
  FROM kambalache_marketplace_graph."Producto" p
  JOIN kambalache_marketplace_graph."Seller" s
    ON ag_catalog.agtype_to_json(s.properties)->>'seller_id' = ag_catalog.agtype_to_json(p.properties)->>'vendedor_id';

  INSERT INTO kambalache_marketplace_graph."COMPRO" (start_id, end_id, properties)
  SELECT b.id, p.id, ag_catalog.agtype_build_map('id_orden', o.id::text, 'origen', v_m, 'data_prueba', 'true')
  FROM auth.ordenes o
  JOIN kambalache_marketplace_graph."Buyer" b
    ON ag_catalog.agtype_to_json(b.properties)->>'buyer_id' = o.id_comprador::text
  JOIN kambalache_marketplace_graph."Producto" p
    ON ag_catalog.agtype_to_json(p.properties)->>'producto_id' = o.id_producto::text;

  INSERT INTO kambalache_marketplace_graph."COMPRO_A" (start_id, end_id, properties)
  SELECT b.id, s.id, ag_catalog.agtype_build_map('id_orden', o.id::text, 'origen', v_m, 'data_prueba', 'true')
  FROM auth.ordenes o
  JOIN kambalache_marketplace_graph."Buyer" b
    ON ag_catalog.agtype_to_json(b.properties)->>'buyer_id' = o.id_comprador::text
  JOIN kambalache_marketplace_graph."Seller" s
    ON ag_catalog.agtype_to_json(s.properties)->>'seller_id' = o.id_vendedor::text;

  INSERT INTO kambalache_marketplace_graph."FAVORITO" (start_id, end_id, properties)
  SELECT b.id, p.id, ag_catalog.agtype_build_map('origen', v_m, 'data_prueba', 'true')
  FROM auth.favoritos f
  JOIN kambalache_marketplace_graph."Buyer" b
    ON ag_catalog.agtype_to_json(b.properties)->>'buyer_id' = f.id_usuario::text
  JOIN kambalache_marketplace_graph."Producto" p
    ON ag_catalog.agtype_to_json(p.properties)->>'producto_id' = f.id_producto::text;

  INSERT INTO kambalache_marketplace_graph."RESENO_A" (start_id, end_id, properties)
  SELECT b.id, s.id, ag_catalog.agtype_build_map('calificacion', coalesce(r.calificacion, 0)::text, 'origen', v_m, 'data_prueba', 'true')
  FROM auth.resenas r
  JOIN kambalache_marketplace_graph."Buyer" b
    ON ag_catalog.agtype_to_json(b.properties)->>'buyer_id' = r.id_comprador::text
  JOIN kambalache_marketplace_graph."Seller" s
    ON ag_catalog.agtype_to_json(s.properties)->>'seller_id' = r.id_vendedor::text;

  INSERT INTO kambalache_marketplace_graph."PERTENECE_A" (start_id, end_id, properties)
  SELECT p.id, c.id, ag_catalog.agtype_build_map('origen', v_m, 'data_prueba', 'true')
  FROM kambalache_marketplace_graph."Producto" p
  JOIN kambalache_marketplace_graph."Categoria" c
    ON ag_catalog.agtype_to_json(c.properties)->>'categoria_id' = ag_catalog.agtype_to_json(p.properties)->>'id_categoria';

  RETURN 'sync_a ok';
END;
$$;


--
-- Name: sincronizar_grafo_ordenes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sincronizar_grafo_ordenes() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_m text := 'sync_b';
BEGIN
  -- 0) alinear secuencias de label: el seed inserto con _graphid explicito
  --    dejando la secuencia detras de los ids usados -> colision en nextval.
  PERFORM setval('kambalache_network."SellerNode_id_seq"', 1000000);
  PERFORM setval('kambalache_network."UserNode_id_seq"', 1000000);
  PERFORM setval('kambalache_network."OrderNode_id_seq"', 1000000);
  PERFORM setval('kambalache_network."PLACED_id_seq"', 1000000);
  PERFORM setval('kambalache_network."COMPRO_EXITOSAMENTE_id_seq"', 1000000);

  -- 1) limpieza idempotente de lo propio (edges luego vertices)
  DELETE FROM kambalache_network."PLACED"              WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;
  DELETE FROM kambalache_network."COMPRO_EXITOSAMENTE" WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;
  DELETE FROM kambalache_network."OrderNode"           WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;
  DELETE FROM kambalache_network."UserNode"            WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;
  DELETE FROM kambalache_network."SellerNode"          WHERE ag_catalog.agtype_to_json(properties)->>'origen' = v_m;

  -- 2) vertices: vendedores reales (aditivo, solo los que faltan)
  INSERT INTO kambalache_network."SellerNode" (properties)
  SELECT ag_catalog.agtype_build_map(
      'user_id', u.id::text,
      'username', coalesce(u.email, ''),
      'email', coalesce(u.email, ''),
      'tier', coalesce(u.default_tier_code, ''),
      'origen', v_m)
  FROM auth.users u
  WHERE u.role = 'seller'
    AND NOT EXISTS (SELECT 1 FROM kambalache_network."SellerNode" s
                    WHERE ag_catalog.agtype_to_json(s.properties)->>'user_id' = u.id::text);

  -- vertices: compradores con ordenes (aditivo)
  INSERT INTO kambalache_network."UserNode" (properties)
  SELECT ag_catalog.agtype_build_map(
      'user_id', u.id::text,
      'username', coalesce(u.email, ''),
      'role', 'buyer',
      'origen', v_m)
  FROM (SELECT DISTINCT id_comprador FROM auth.ordenes) o
  JOIN auth.users u ON u.id = o.id_comprador
  WHERE NOT EXISTS (SELECT 1 FROM kambalache_network."UserNode" x
                    WHERE ag_catalog.agtype_to_json(x.properties)->>'user_id' = u.id::text);

  -- vertices: ordenes
  INSERT INTO kambalache_network."OrderNode" (properties)
  SELECT ag_catalog.agtype_build_map(
      'order_id', o.id::text,
      'estado', coalesce(o.estado, ''),
      'total', coalesce(o.total, 0)::text,
      'fecha', coalesce(o.fecha_creacion::text, ''),
      'vendedor_id', coalesce(o.id_vendedor, '00000000-0000-0000-0000-000000000000')::text,
      'comprador_id', coalesce(o.id_comprador::text, ''),
      'producto_id', coalesce(o.id_producto::text, ''),
      'origen', v_m)
  FROM auth.ordenes o;

  -- 3) edges
  -- PLACED: comprador -> orden
  INSERT INTO kambalache_network."PLACED" (start_id, end_id, properties)
  SELECT u.id, od.id, ag_catalog.agtype_build_map('origen', v_m, 'data_prueba', 'true')
  FROM kambalache_network."OrderNode" od
  JOIN kambalache_network."UserNode" u
    ON ag_catalog.agtype_to_json(u.properties)->>'user_id' = ag_catalog.agtype_to_json(od.properties)->>'comprador_id';

  -- COMPRO_EXITOSAMENTE: comprador -> vendedor (orden confirmada)
  INSERT INTO kambalache_network."COMPRO_EXITOSAMENTE" (start_id, end_id, properties)
  SELECT u.id, s.id, ag_catalog.agtype_build_map('order_id', od.id::text, 'origen', v_m, 'data_prueba', 'true')
  FROM kambalache_network."OrderNode" od
  JOIN kambalache_network."UserNode" u
    ON ag_catalog.agtype_to_json(u.properties)->>'user_id' = ag_catalog.agtype_to_json(od.properties)->>'comprador_id'
  JOIN kambalache_network."SellerNode" s
    ON ag_catalog.agtype_to_json(s.properties)->>'user_id' = ag_catalog.agtype_to_json(od.properties)->>'vendedor_id'
  WHERE ag_catalog.agtype_to_json(od.properties)->>'estado' = 'confirmada';

  RETURN 'sync_b ok';
END;
$$;


--
-- Name: sync_alerta_to_graph(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_alerta_to_graph() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth', 'ag_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_timestamp TEXT;
BEGIN
  v_timestamp := to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"');

  -- Inserción en AGE con degradación elegante
  BEGIN
    PERFORM * FROM cypher('kambalache_marketplace_graph', $cypher$
      MERGE (a:AlertaCritica {id_sql: $aid})
      ON CREATE SET
        a.tipo        = $tipo,
        a.nivel_riesgo= $nivel,
        a.estado      = 'PENDIENTE',
        a.fecha_creacion  = $ts,
        a.inmutable   = true
      WITH a
      MATCH (v:Seller {id_sql: $vid})
      MERGE (v)-[:TIENE_ALERTA {fecha: $ts}]->(a)
    $cypher$, jsonb_build_object(
      'aid',   NEW.id::text,
      'tipo',  NEW.tipo_alerta,
      'nivel', NEW.nivel_riesgo,
      'vid',   NEW.id_vendedor::text,
      'ts',    v_timestamp
    )) AS (r agtype);
  EXCEPTION WHEN OTHERS THEN
    NULL; -- AGE no disponible: alerta creada en SQL de todas formas
  END;

  RETURN NEW;
END;
$_$;


--
-- Name: sync_order_completion_to_graph(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_order_completion_to_graph(p_id_orden uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'ag_catalog'
    AS $_$
DECLARE r RECORD; v_n integer := 0;
BEGIN
  LOAD 'age';
  SET LOCAL search_path = ag_catalog, public, pg_temp;
  IF NOT EXISTS (SELECT 1 FROM ag_catalog.ag_label
                 WHERE graph = (SELECT graphid FROM ag_catalog.ag_graph WHERE name = 'smtp_posix_graph')
                   AND name = 'COMPRO' AND kind = 'e') THEN
    PERFORM ag_catalog.create_elabel('smtp_posix_graph', 'COMPRO');
  END IF;

  FOR r IN
    SELECT id_comprador, id_vendedor
      FROM auth.ordenes
     WHERE (p_id_orden IS NULL OR id = p_id_orden)
       AND id_comprador IS NOT NULL AND id_vendedor IS NOT NULL
       AND estado = 'completada' AND fecha_eliminacion IS NULL
  LOOP
    BEGIN
      PERFORM 1 FROM cypher('smtp_posix_graph',
        $$ MATCH (b:User {user_uuid: $id_comprador}), (v:User {user_uuid: $id_vendedor})
           MERGE (b)-[e:COMPRO]->(v)
           SET e.estado = 'completada', e.fecha_completada = timestamp()
           RETURN e $$,
        jsonb_build_object('id_comprador', r.id_comprador::text, 'id_vendedor', r.id_vendedor::text)
      ) AS (e agtype);
      v_n := v_n + 1;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END LOOP;
  RETURN v_n;
END $_$;


--
-- Name: sync_order_geo_to_graph(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_order_geo_to_graph() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog'
    AS $_$
DECLARE
  v_id_comprador text;
  v_id_vendedor text;
BEGIN
  -- Extraer actores desde sub-partición
  SELECT id_comprador::text, id_vendedor::text 
  INTO v_id_comprador, v_id_vendedor
  FROM auth.ordenes
  WHERE id = NEW.id_orden
    AND order_month = NEW.order_month
    AND region_code = NEW.region_code;

  -- Proyectar nodos y aristas geográficas
  PERFORM * FROM cypher('kambalache_network', $cypher$
    MERGE (o:OrderNode {id: $id_orden, month: $month, region: $region})
    MERGE (b:UserNode {id: $id_comprador})
    MERGE (s:SellerNode {id: $id_vendedor})
    MERGE (z:Zone {label: coalesce($delivery_zone, 'unknown')})
    MERGE (b)-[:PLACED]->(o)
    MERGE (o)-[:DELIVERS_TO]->(z)
    MERGE (s)-[:SUPPLIES_IN]->(z)
    SET o.buyer_to_delivery_meters = toFloat($b_to_d),
        o.seller_to_delivery_meters = toFloat($s_to_d)
  $cypher$, jsonb_build_object(
    'order_id', NEW.id_orden::text,
    'month', NEW.order_month::text,
    'region', NEW.region_code,
    'id_comprador', v_id_comprador,
    'id_vendedor', v_id_vendedor,
    'delivery_zone', NEW.delivery_zone_label,
    'b_to_d', NEW.buyer_to_delivery_meters,
    's_to_d', NEW.seller_to_delivery_meters
  )) AS (result agtype);

  RETURN NEW;
END;
$_$;


--
-- Name: sync_purchase_to_graph(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_purchase_to_graph(p_id_orden uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'ag_catalog'
    AS $$
DECLARE
  r RECORD;
  v_buyer  ag_catalog.graphid;
  v_seller ag_catalog.graphid;
  v_edge   ag_catalog.graphid;
  v_n integer := 0;
BEGIN
  LOAD 'age';
  SET LOCAL search_path = ag_catalog, public, pg_temp;

  FOR r IN
    SELECT id_comprador,
           id_vendedor,
           count(*) AS total_ordenes,
           sum(total) AS suma,
           max(fecha_confirmacion) AS ultima
      FROM auth.ordenes
     WHERE (p_id_orden IS NULL OR id = p_id_orden)
       AND id_comprador IS NOT NULL
       AND id_vendedor IS NOT NULL
       AND estado = 'confirmada'
       AND fecha_eliminacion IS NULL
     GROUP BY id_comprador, id_vendedor
  LOOP
    -- localizar vértices User por user_uuid (INSERT directo, sin cypher)
    SELECT id INTO v_buyer FROM smtp_posix_graph."User"
     WHERE agtype_to_json(properties)->>'user_uuid' = r.id_comprador::text;
    SELECT id INTO v_seller FROM smtp_posix_graph."User"
     WHERE agtype_to_json(properties)->>'user_uuid' = r.id_vendedor::text;
    IF v_buyer IS NULL OR v_seller IS NULL THEN
      CONTINUE;  -- no inventar vértices; los User los sincroniza su propio flujo
    END IF;

    -- upsert edge COMPRO (buyer -> seller)
    SELECT id INTO v_edge FROM smtp_posix_graph."COMPRO"
     WHERE start_id = v_buyer AND end_id = v_seller;

    IF v_edge IS NULL THEN
      INSERT INTO smtp_posix_graph."COMPRO" (start_id, end_id, properties)
      VALUES (v_buyer, v_seller,
        agtype_build_map(
          'total_ordenes', r.total_ordenes::text,
          'total', COALESCE(r.suma::text, '0'),
          'estado', 'comprado',
          'ultima_compra', COALESCE(r.ultima::text, '')));
    ELSE
      UPDATE smtp_posix_graph."COMPRO"
         SET properties = agtype_build_map(
               'total_ordenes', r.total_ordenes::text,
               'total', COALESCE(r.suma::text, '0'),
               'estado', 'comprado',
               'ultima_compra', COALESCE(r.ultima::text, ''))
       WHERE id = v_edge;
    END IF;
    v_n := v_n + 1;
  END LOOP;

  RETURN v_n;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'sync_purchase_to_graph: % (procesadas %)', SQLERRM, v_n;
  RETURN v_n;
END $$;


--
-- Name: sync_reputacion_score_desde_age(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_reputacion_score_desde_age(p_vendedor_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'auth', 'pg_temp'
    AS $_$
DECLARE
  r record;
  v_actualizado integer := 0;
  v_age_avg agtype;
  v_age_count agtype;
  v_sql_avg numeric(5,2);
  v_sql_count integer;
BEGIN
  -- Obtener lista de vendedores a procesar
  FOR r IN
    SELECT DISTINCT id_vendedor
    FROM auth.resenas
    WHERE (p_vendedor_id IS NULL OR id_vendedor = p_vendedor_id)
      AND activo = true
  LOOP
    BEGIN
      -- Cargar AGE y consultar score desde el grafo
      -- El promedio en AGE usa aristas RECIBIO_CALIFICACION
      SELECT avg_calif, total_calif INTO v_age_avg, v_age_count
      FROM cypher('kambalache_marketplace_graph', $$
        MATCH (v:Vendedor {vendedor_uuid: $vendedor_id})-[r:RECIBIO_CALIFICACION]->(:Calificacion)
        RETURN avg(r.calificacion) AS avg_calif, count(r) AS total_calif
      $$, jsonb_build_object('vendedor_id', r.id_vendedor::text))
      AS (avg_calif agtype, total_calif agtype);

      -- Si AGE retornó datos usarlos; si no, fallback a SQL directo
      IF v_age_count IS NOT NULL AND v_age_count::text::integer > 0 THEN
        v_sql_avg := COALESCE(ROUND(v_age_avg::text::numeric, 2), 0);
        v_sql_count := v_age_count::text::integer;
      ELSE
        SELECT
          COALESCE(ROUND(AVG(calificacion)::numeric, 2), 0),
          COUNT(*)
        INTO v_sql_avg, v_sql_count
        FROM auth.resenas
        WHERE id_vendedor = r.id_vendedor AND activo = true;
      END IF;

      -- Actualizar perfil público del vendedor
      UPDATE auth.perfiles_publicos_vendedor
      SET
        score_reputacion = v_sql_avg::text,
        total_resenas = v_sql_count::text,
        resenas_positivas = (
          SELECT COUNT(*)
          FROM auth.resenas
          WHERE id_vendedor = r.id_vendedor AND activo = true AND calificacion >= 4
        ),
        ultima_actualizacion_score = now(),
        fecha_modificacion = now()
      WHERE id_vendedor = r.id_vendedor;

      -- Crear perfil si no existe
      IF NOT FOUND THEN
        INSERT INTO auth.perfiles_publicos_vendedor (
          id_vendedor, score_reputacion, total_resenas, resenas_positivas,
          ultima_actualizacion_score, fecha_modificacion
        ) VALUES (
          r.id_vendedor, v_sql_avg::text, v_sql_count::text,
          (SELECT COUNT(*) FROM auth.resenas
           WHERE id_vendedor = r.id_vendedor AND activo = true AND calificacion >= 4),
          now(), now()
        );
      END IF;

      v_actualizado := v_actualizado + 1;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END LOOP;

  RETURN v_actualizado;
END;
$_$;


--
-- Name: sync_user_status_to_age(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_user_status_to_age(p_user_id uuid, p_state text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $_$
DECLARE v_ok boolean := false;
BEGIN
  BEGIN
    LOAD 'age';
    SET LOCAL search_path = ag_catalog, public, pg_temp;
    PERFORM cypher('smtp_posix_graph', format($c$
      MERGE (u:User {id_usuario: "%s"})
      SET u.admin_state = "%s", u.fecha_actualizacion = "%s"
    $c$, p_user_id::text, p_state, to_char(now(),'YYYY-MM-DD"T"HH24:MI:SS"Z"')));
    v_ok := true;
  EXCEPTION WHEN OTHERS THEN
    -- Silencioso, se loguea pero no rompe la transacción del caller
    INSERT INTO auth.auditoria(id_actor, action, target_kind, id_objetivo, payload)
    VALUES (app.jwt_user_id_safe(), 'age_sync_failed', 'user', p_user_id,
            jsonb_build_object('reason', SQLERRM, 'target_state', p_state));
    v_ok := false;
  END;
  RETURN v_ok;
END;
$_$;


--
-- Name: tg_admin_moderacion_audit_age(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_admin_moderacion_audit_age() RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
  r record;
  v_age_ok boolean := false;
  v_n int := 0;
BEGIN
  BEGIN
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_extension WHERE extname = 'age')
       AND pg_catalog.has_schema_privilege(current_user, 'ag_catalog', 'USAGE') THEN
      LOAD 'age';
      v_age_ok := true;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_age_ok := false;
  END;

  IF NOT v_age_ok THEN
    RAISE NOTICE 'tg_admin_moderacion_audit_age: AGE no disponible para % (degradación elegante, sin cambios)', current_user;
    RETURN;
  END IF;

  FOR r IN
    SELECT h.id, h.producto_id, h.operacion, h.estado_prev, h.estado_nuevo,
           h.operado_por, h.created_at
      FROM auth.historial_moderacion_productos h
     WHERE h.created_at >= now() - interval '7 days'
     ORDER BY h.created_at
  LOOP
    BEGIN
      PERFORM * FROM ag_catalog.cypher('tienda_grafo', $c$
        MERGE (m:Moderacion {id_historial: $hid})
        SET m.operacion = $op, m.estado_prev = $ep, m.estado_nuevo = $en, m.ts = $ts
      $c$, jsonb_build_object(
          'hid', r.id::text, 'op', COALESCE(r.operacion, ''),
          'ep', COALESCE(r.estado_prev, ''), 'en', COALESCE(r.estado_nuevo, ''),
          'ts', to_char(r.created_at, 'YYYY-MM-DD"T"HH24:MI:SS"Z"')))
        AS (v ag_catalog.agtype);
      IF r.operado_por IS NOT NULL THEN
        PERFORM * FROM ag_catalog.cypher('tienda_grafo', $c$
          MERGE (u:Usuario {id_sql: $uid})
          MERGE (m:Moderacion {id_historial: $hid})
          MERGE (u)-[:MODERO]->(m)
        $c$, jsonb_build_object('uid', r.operado_por::text, 'hid', r.id::text))
          AS (v ag_catalog.agtype);
      END IF;
      IF r.producto_id IS NOT NULL THEN
        PERFORM * FROM ag_catalog.cypher('tienda_grafo', $c$
          MERGE (m:Moderacion {id_historial: $hid})
          MERGE (p:Producto {id_producto: $pid})
          MERGE (m)-[:SOBRE]->(p)
        $c$, jsonb_build_object('hid', r.id::text, 'pid', r.producto_id::text))
          AS (v ag_catalog.agtype);
      END IF;
      v_n := v_n + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[MODERACION_AGE_FAILED] historial=%: %', r.id, SQLERRM;
    END;
  END LOOP;
  RAISE NOTICE 'tg_admin_moderacion_audit_age: % eventos de moderación reflejados en tienda_grafo', v_n;
END;
$_$;


--
-- Name: tg_admin_monitor_alert_age(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_admin_monitor_alert_age() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $$
DECLARE
  v_amount_threshold NUMERIC;
  v_tipo             TEXT;
  v_alert_id         BIGINT;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RETURN NEW;
  END IF;

  SELECT value_num INTO v_amount_threshold
    FROM public.risk_detection_config WHERE key = 'tx_amount_threshold';
  v_amount_threshold := COALESCE(v_amount_threshold, 10000);

  -- Regla 1: monto alto
  IF NEW.monto IS NOT NULL AND NEW.monto >= v_amount_threshold THEN
    v_tipo := 'TX_MONTO_ALTO';

    INSERT INTO public.admin_alerts(
      tipo, referencia_id, referencia_tipo, severidad, estado, fuente, payload
    ) VALUES (
      v_tipo, NEW.id_usuario, 'user',
      CASE WHEN NEW.monto >= v_amount_threshold * 5 THEN 'critica'
           WHEN NEW.monto >= v_amount_threshold * 2 THEN 'alta'
           ELSE 'media' END,
      'abierta',
      'trigger:transacciones',
      jsonb_build_object(
        'evento_fuente',   'transacciones',
        'evento_fuente_id', NEW.id::text,
        'monto',            NEW.monto,
        'umbral',           v_amount_threshold
      )
    )
    ON CONFLICT ((payload->>'evento_fuente_id'), tipo) DO NOTHING
    RETURNING id INTO v_alert_id;

    -- Sincronización con AGE — best-effort, no aborta si falla
    IF v_alert_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM pg_extension WHERE extname='age') THEN
      BEGIN
        PERFORM public.log_admin_risk_event(
          'AGE_SYNC_ALERT', 'alerta_admin', v_alert_id::text,
          'auto-sync from trigger',
          NULL,
          jsonb_build_object('alert_id', v_alert_id, 'tipo', v_tipo)
        );
      EXCEPTION WHEN OTHERS THEN
        -- SQL persiste; el error AGE se registra pero no revierte la transacción
        NULL;
      END;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: tg_archivar_reporte(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_archivar_reporte() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_n     int := 0;
  v_actor uuid;
BEGIN
  IF NOT pg_catalog.has_table_privilege(current_user, 'public.reportes_seguridad', 'UPDATE') THEN
    RAISE NOTICE 'tg_archivar_reporte: % sin privilegio UPDATE en public.reportes_seguridad (degradación elegante, sin cambios)', current_user;
    RETURN;
  END IF;
  UPDATE public.reportes_seguridad
     SET archivado = true,
         archivado_en = now()
   WHERE archivado = false
     AND fecha_reporte < (current_date - 90);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  BEGIN
    v_actor := public.get_app_actor_id();
    INSERT INTO auth.auditoria (id_actor, action, target_kind, id_objetivo, payload)
    VALUES (v_actor, 'reportes_archived', 'reporte', NULL,
            jsonb_build_object('count', v_n, 'older_than_days', 90,
                               'fuente', 'tg_archivar_reporte'));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[ARCHIVO_AUDIT_FAILED]: %', SQLERRM;
  END;
  RAISE NOTICE 'tg_archivar_reporte: % reportes archivados', v_n;
END;
$$;


--
-- Name: tg_audit_api_doc_age(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_audit_api_doc_age() RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
  r record;
  v_age_ok boolean := false;
  v_n int := 0;
BEGIN
  BEGIN
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_extension WHERE extname = 'age')
       AND pg_catalog.has_schema_privilege(current_user, 'ag_catalog', 'USAGE') THEN
      LOAD 'age';
      v_age_ok := true;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_age_ok := false;
  END;

  IF NOT v_age_ok THEN
    RAISE NOTICE 'tg_audit_api_doc_age: AGE no disponible para % (degradación elegante, sin cambios)', current_user;
    RETURN;
  END IF;

  FOR r IN
    SELECT d.id, d.tipo_cambio, d.objeto_tipo, d.objeto_nombre, d.creado_en
      FROM public.h_doc_audit d
     WHERE d.creado_en >= now() - interval '7 days'
       AND COALESCE(d.es_dato_prueba, false) = false
     ORDER BY d.creado_en
  LOOP
    BEGIN
      PERFORM * FROM ag_catalog.cypher('tienda_grafo', $c$
        MERGE (doc:DocUpdate {id_audit: $did})
        SET doc.objeto = $obj, doc.tipo = $tip, doc.ts = $ts
      $c$, jsonb_build_object('did', r.id::text,
                              'obj', COALESCE(r.objeto_nombre, ''),
                              'tip', COALESCE(r.tipo_cambio, ''),
                              'ts', to_char(r.creado_en, 'YYYY-MM-DD"T"HH24:MI:SS"Z"')))
        AS (v ag_catalog.agtype);
      v_n := v_n + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[DOCAUDIT_AGE_FAILED] doc_audit=%: %', r.id, SQLERRM;
    END;
  END LOOP;
  RAISE NOTICE 'tg_audit_api_doc_age: % entradas h_doc_audit reflejadas en tienda_grafo', v_n;
END;
$_$;


--
-- Name: tg_audit_config_seguridad(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_audit_config_seguridad() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_n int := 0;
BEGIN
  IF NOT (pg_catalog.has_schema_privilege(current_user, 'audit', 'USAGE')
          AND pg_catalog.has_table_privilege(current_user, 'audit.config_seguridad_audit', 'INSERT')) THEN
    RAISE NOTICE 'tg_audit_config_seguridad: % sin privilegios INSERT en audit.config_seguridad_audit (degradación elegante, sin cambios)', current_user;
    RETURN;
  END IF;
  INSERT INTO audit.config_seguridad_audit (key, old_value, new_value, id_actor, reason, fecha_cambio)
  SELECT s.setting_key,
         COALESCE((SELECT a.new_value
                     FROM audit.config_seguridad_audit a
                    WHERE a.key = s.setting_key
                    ORDER BY a.fecha_cambio DESC
                    LIMIT 1), '{}'::jsonb),
         s.setting_value,
         s.updated_by,
         'AUDIT_SNAPSHOT',
         now()
    FROM public.config_seguridad s
   WHERE NOT EXISTS (SELECT 1
                       FROM audit.config_seguridad_audit a2
                      WHERE a2.key = s.setting_key
                        AND a2.fecha_cambio >= s.fecha_actualizacion);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RAISE NOTICE 'tg_audit_config_seguridad: % settings auditados', v_n;
END;
$$;


--
-- Name: tg_cu064_risk_score_graph_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_cu064_risk_score_graph_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ag_catalog', 'smtp_posix_graph', 'auth', 'public', 'pg_catalog'
    AS $_$
DECLARE
    r RECORD;
    v_usuario_id UUID;
    v_nivel TEXT;
BEGIN
    LOAD 'age';
    SET LOCAL search_path = ag_catalog, smtp_posix_graph, auth, public, pg_catalog;

    -- On DELETE: remove all TIENE_RIESGO_ALTO edges involving this user
    IF TG_OP = 'DELETE' THEN
        v_usuario_id := OLD.id_usuario;
        BEGIN
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    MATCH (:User {user_uuid: %L})-[e:TIENE_RIESGO_ALTO]-()
                    DELETE e RETURN count(e)
                $c$) AS (r ag_catalog.agtype)$q$,
                v_usuario_id::text
            );
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    MATCH ()-[e:TIENE_RIESGO_ALTO]-(:User {user_uuid: %L})
                    DELETE e RETURN count(e)
                $c$) AS (r ag_catalog.agtype)$q$,
                v_usuario_id::text
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'tg_cu064_risk_score_graph_sync DELETE %: %', v_usuario_id, SQLERRM;
        END;
        RETURN OLD;
    END IF;

    v_usuario_id := NEW.id_usuario;
    v_nivel := COALESCE(NEW.nivel_riesgo, 'bajo');

    -- If risk dropped out of high/critical: remove outgoing+incoming TIENE_RIESGO_ALTO edges
    IF v_nivel NOT IN ('alto', 'critico') THEN
        BEGIN
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    MATCH (:User {user_uuid: %L})-[e:TIENE_RIESGO_ALTO]-()
                    DELETE e RETURN count(e)
                $c$) AS (r ag_catalog.agtype)$q$,
                v_usuario_id::text
            );
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    MATCH ()-[e:TIENE_RIESGO_ALTO]-(:User {user_uuid: %L})
                    DELETE e RETURN count(e)
                $c$) AS (r ag_catalog.agtype)$q$,
                v_usuario_id::text
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'tg_cu064_risk_score_graph_sync remove %: %', v_usuario_id, SQLERRM;
        END;
        RETURN NEW;
    END IF;

    -- Risk is alto/critico: MERGE TIENE_RIESGO_ALTO edges with all connected high-risk users
    -- Connected = participated in at least one intercambio together
    FOR r IN
        SELECT DISTINCT
            CASE
                WHEN i.solicitante_id = v_usuario_id THEN i.receptor_id
                ELSE i.solicitante_id
            END AS peer_id
        FROM auth.intercambios i
        WHERE (i.solicitante_id = v_usuario_id OR i.receptor_id = v_usuario_id)
          AND EXISTS (
              SELECT 1 FROM public.user_risk_scores urs2
              WHERE urs2.id_usuario = CASE
                  WHEN i.solicitante_id = v_usuario_id THEN i.receptor_id
                  ELSE i.solicitante_id
              END
              AND urs2.nivel_riesgo IN ('alto', 'critico')
          )
    LOOP
        BEGIN
            EXECUTE format(
                $q$SELECT * FROM ag_catalog.cypher('smtp_posix_graph', $c$
                    MATCH (u1:User {user_uuid: %L}), (u2:User {user_uuid: %L})
                    MERGE (u1)-[:TIENE_RIESGO_ALTO]->(u2)
                    MERGE (u2)-[:TIENE_RIESGO_ALTO]->(u1)
                    RETURN 1
                $c$) AS (r ag_catalog.agtype)$q$,
                v_usuario_id::text,
                r.peer_id::text
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'tg_cu064_risk_score_graph_sync edge %-%: %', v_usuario_id, r.peer_id, SQLERRM;
        END;
    END LOOP;

    RETURN NEW;
END;
$_$;


--
-- Name: tg_deny_delete_worm(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_deny_delete_worm() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'WORM_VIOLATION: Deletion prohibited on %.%', TG_TABLE_SCHEMA, TG_TABLE_NAME
        USING ERRCODE = '42501';
    ELSIF TG_OP = 'UPDATE' AND TG_TABLE_NAME = 'reportes_seguridad' AND 
          (OLD.archivado IS DISTINCT FROM NEW.archivado AND NEW.archivado = FALSE) THEN
        RAISE EXCEPTION 'WORM_VIOLATION: Cannot unarchive reportes_seguridad'
        USING ERRCODE = '42501';
    END IF;
    RETURN NULL; -- Siempre aborta la operación
END;
$$;


--
-- Name: tg_disparar_alerta_riesgo_age(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_disparar_alerta_riesgo_age() RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
  r record;
  v_age_ok boolean := false;
  v_n int := 0;
BEGIN
  BEGIN
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_extension WHERE extname = 'age')
       AND pg_catalog.has_schema_privilege(current_user, 'ag_catalog', 'USAGE') THEN
      LOAD 'age';
      v_age_ok := true;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_age_ok := false;
  END;

  IF NOT v_age_ok THEN
    RAISE NOTICE 'tg_disparar_alerta_riesgo_age: AGE no disponible para % (degradación elegante, sin cambios)', current_user;
    RETURN;
  END IF;

  FOR r IN
    SELECT a.id, a.id_vendedor, a.tipo_alerta, a.estado, a.nivel_riesgo
      FROM public.alertas_criticas a
     WHERE a.is_active = true
       AND a.estado = 'PENDIENTE'
  LOOP
    BEGIN
      PERFORM * FROM ag_catalog.cypher('smtp_posix_graph', $c$
        MERGE (u:User {id_usuario: $uid})
        MERGE (al:AlertaRiesgo {alert_id: $aid})
        SET al.tipo = $tip, al.nivel = $niv, al.estado = $est
        MERGE (u)-[t:TIENE_RIESGO_ALTO]->(al)
      $c$, jsonb_build_object('uid', r.id_vendedor::text, 'aid', r.id::text,
                              'tip', r.tipo_alerta, 'niv', r.nivel_riesgo,
                              'est', r.estado)) AS (v ag_catalog.agtype);
      v_n := v_n + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[ALERTA_AGE_FAILED] alerta=%: %', r.id, SQLERRM;
    END;
  END LOOP;
  RAISE NOTICE 'tg_disparar_alerta_riesgo_age: % alertas reflejadas en smtp_posix_graph', v_n;
END;
$_$;


