--
-- Name: tg_orders_risk_detect(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_orders_risk_detect() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_umbral numeric := 10000;
  v_campo  text;
  v_nivel  text;
BEGIN
  -- Umbral desde columnas REALES (key, value_num) de public.config_seguridad
  BEGIN
    SELECT c.value_num::numeric INTO v_umbral
      FROM public.config_seguridad c
     WHERE c.key = 'tx_amount_threshold';
    v_umbral := COALESCE(v_umbral, 10000);
  EXCEPTION WHEN OTHERS THEN
    v_umbral := 10000;
  END;

  IF (NEW.total >= v_umbral) OR (NEW.quantity >= 50) THEN
    v_campo := CASE WHEN NEW.total >= v_umbral THEN 'total' ELSE 'quantity' END;
    v_nivel := CASE WHEN NEW.total >= v_umbral * 5 THEN 'CRITICO' ELSE 'ALTO' END;
    BEGIN
      INSERT INTO public.alertas_criticas
        (id_vendedor, tipo_alerta, campo_afectado, valor_anterior, valor_nuevo,
         estado, visible, nivel_riesgo, is_active, metadata)
      SELECT NEW.id_vendedor,
             'PATRON_FRAUDE',            -- valor permitido por CHECK real
             v_campo,
             CASE WHEN TG_OP = 'UPDATE'
                  THEN CASE WHEN v_campo = 'total' THEN OLD.total::text ELSE OLD.quantity::text END
             END,
             CASE WHEN v_campo = 'total' THEN NEW.total::text ELSE NEW.quantity::text END,
             'PENDIENTE',                -- valor permitido por CHECK real
             true,
             v_nivel,                    -- CRITICO/ALTO permitidos por CHECK real
             true,
             jsonb_build_object('orden_id', NEW.id::text, 'cantidad', NEW.quantity,
                                'estado', NEW.estado, 'umbral', v_umbral,
                                'fuente', 'tg_orders_risk_detect')
      WHERE NOT EXISTS (SELECT 1 FROM public.alertas_criticas ac
                         WHERE ac.tipo_alerta = 'PATRON_FRAUDE'
                           AND ac.is_active
                           AND ac.metadata->>'orden_id' = NEW.id::text);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[RISK_ALERT_FAILED] orden=%: %', NEW.id, SQLERRM;
    END;
  END IF;
  RETURN NEW;
END;
$$;


