--
-- Name: tg_soft_hide_alerta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_soft_hide_alerta() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_n int := 0;
BEGIN
  IF NOT pg_catalog.has_table_privilege(current_user, 'public.alertas_criticas', 'UPDATE') THEN
    RAISE NOTICE 'tg_soft_hide_alerta: % sin privilegio UPDATE en public.alertas_criticas (degradación elegante, sin cambios)', current_user;
    RETURN;
  END IF;
  UPDATE public.alertas_criticas
     SET visible = false,
         fecha_actualizacion = now()
   WHERE visible = true
     AND estado IN ('PROCESADA', 'REVERTIDA', 'IGNORADA')
     AND fecha_actualizacion < now() - interval '30 days';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RAISE NOTICE 'tg_soft_hide_alerta: % alertas ocultadas (visible=false, soft-hide sin borrado físico)', v_n;
END;
$$;


--
-- Name: tg_sync_investigation_case_to_age(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sync_investigation_case_to_age() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'ag_catalog', 'pg_temp'
    AS $_$
BEGIN
  IF NEW.entity_kind = 'user' THEN
    BEGIN
      LOAD 'age';
      PERFORM cypher('smtp_posix_graph', format($c$
        MERGE (u:User {id_usuario: "%s"})
        SET u.investigation_status = "%s", u.last_case_id = "%s"
      $c$, NEW.id_entidad::text, NEW.estado, NEW.id_caso::text));
    EXCEPTION WHEN OTHERS THEN
      -- degradación silenciosa
      NULL;
    END;
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: tg_sync_vendedor_status_age(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sync_vendedor_status_age() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_nuevo_estado text;
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RETURN NEW;
  END IF;

  IF (COALESCE(OLD.is_active,true) IS DISTINCT FROM COALESCE(NEW.is_active,true))
     OR (OLD.fecha_eliminacion IS DISTINCT FROM NEW.fecha_eliminacion) THEN

    v_nuevo_estado := CASE
      WHEN COALESCE(NEW.is_active,true)=true AND NEW.fecha_eliminacion IS NULL THEN 'active'
      ELSE 'inactive'
    END;

    PERFORM api.sync_vendedor_status_to_age(NEW.id_usuario, v_nuevo_estado);
  END IF;

  RETURN NEW;
END;
$$;


