--
-- Name: trg_audit_buyer_purchase_plan_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_audit_buyer_purchase_plan_items() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Registrar cambios en items del plan
  INSERT INTO public.contextual_alert_events (
    id_comprador, id_vendedor, tipo_alerta, trigger_reason, metadata
  ) VALUES (
    (SELECT id_comprador FROM public.buyer_purchase_plans WHERE id = NEW.id_plan),
    NEW.id_vendedor,
    'PLAN_ITEM_LIFECYCLE',
    CASE WHEN TG_OP = 'INSERT' THEN 'ITEM_ADDED'
         WHEN TG_OP = 'UPDATE' THEN 'ITEM_UPDATED'
         WHEN TG_OP = 'DELETE' THEN 'ITEM_REMOVED'
    END,
    jsonb_build_object(
      'plan_id', NEW.id_plan,
      'product_id', NEW.id_producto,
      'id_vendedor', NEW.id_vendedor,
      'quantity', NEW.quantity,
      'operation', TG_OP,
      'timestamp', now()
    )
  );
  RETURN NEW;
END;
$$;


--
-- Name: trg_audit_buyer_purchase_plans(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_audit_buyer_purchase_plans() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Proyectar evento de auditoría a tabla central de auditoría (WORM)
  -- Pattern: INSERT INTO ledger.audit_events (tipo_evento, id_actor, entity, payload, ...)
  -- Aquí se registra el cambio para trazabilidad
  INSERT INTO public.contextual_alert_events (
    id_comprador, id_vendedor, tipo_alerta, trigger_reason, metadata
  ) VALUES (
    NEW.id_comprador, NULL, 'PLAN_LIFECYCLE', 
    CASE WHEN TG_OP = 'INSERT' THEN 'PLAN_CREATED'
         WHEN TG_OP = 'UPDATE' THEN 'PLAN_UPDATED'
         WHEN TG_OP = 'DELETE' THEN 'PLAN_DELETED'
    END,
    jsonb_build_object(
      'plan_id', NEW.id,
      'status', NEW.estado,
      'operation', TG_OP,
      'timestamp', now()
    )
  );
  RETURN NEW;
END;
$$;


