--
-- Name: trg_audit_rls_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_audit_rls_changes() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM pg_event_trigger_ddl_commands() LOOP
    IF r.command_tag IN ('CREATE POLICY','ALTER POLICY','DROP POLICY') THEN
      INSERT INTO public.rls_change_audit(command_tag, object_ident)
      VALUES (r.command_tag, r.object_identity);
    END IF;
  END LOOP;
END; $$;


--
-- Name: trg_audit_user_location_consents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_audit_user_location_consents() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Registrar eventos de consentimiento (crítico para privacidad)
  INSERT INTO public.contextual_alert_events (
    id_comprador, id_vendedor, tipo_alerta, trigger_reason, metadata
  ) VALUES (
    NEW.id_usuario, NULL, 'CONSENT_LIFECYCLE',
    CASE WHEN TG_OP = 'INSERT' THEN 'CONSENT_GRANTED'
         WHEN TG_OP = 'UPDATE' THEN 
           CASE WHEN NEW.revoked_at IS NOT NULL AND OLD.revoked_at IS NULL
                THEN 'CONSENT_REVOKED'
                ELSE 'CONSENT_UPDATED'
           END
    END,
    jsonb_build_object(
      'consent_type', NEW.consent_type,
      'granted', NEW.granted,
      'granted_at', NEW.granted_at,
      'revoked_at', NEW.revoked_at,
      'operation', TG_OP,
      'timestamp', now()
    )
  );
  RETURN NEW;
END;
$$;


--
-- Name: trg_introspection_audit_worm(); Type: FUNCTION; Schema: public; Owner: -
