--
-- Name: trg_sync_order_to_graph(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_sync_order_to_graph() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_age_ok boolean := false;
BEGIN
  BEGIN
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_extension WHERE extname = 'age')
       AND pg_catalog.has_schema_privilege(current_user, 'ag_catalog', 'USAGE') THEN
      LOAD 'age';
      v_age_ok := true;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_age_ok := false;
  END;

  IF NOT v_age_ok THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  BEGIN
    IF TG_OP = 'DELETE' THEN
      PERFORM * FROM ag_catalog.cypher('smtp_posix_graph', $c$
        MATCH (o:Order {id_orden: $oid}) DETACH DELETE o
      $c$, jsonb_build_object('oid', OLD.id::text)) AS (v ag_catalog.agtype);
      RETURN OLD;
    ELSE
      PERFORM * FROM ag_catalog.cypher('smtp_posix_graph', $c$
        MERGE (o:Order {id_orden: $oid})
        SET o.estado = $est, o.total = $tot, o.id_comprador = $ic
      $c$, jsonb_build_object('oid', NEW.id::text, 'est', NEW.estado,
                              'tot', NEW.total::text, 'ic', NEW.id_comprador::text))
        AS (v ag_catalog.agtype);
      IF NEW.id_vendedor IS NOT NULL THEN
        PERFORM * FROM ag_catalog.cypher('smtp_posix_graph', $c$
          MERGE (s:Seller {id_usuario: $sid})
          MERGE (o:Order {id_orden: $oid})
          MERGE (s)-[f:FULFILLS]->(o)
        $c$, jsonb_build_object('sid', NEW.id_vendedor::text, 'oid', NEW.id::text))
          AS (v ag_catalog.agtype);
      END IF;
      RETURN NEW;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[AGE_SYNC_FAILED] order=%: %',
      CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END, SQLERRM;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END;
END;
$_$;


--
-- Name: trg_update_query_graph_edges(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_update_query_graph_edges() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_node_id BIGINT;
BEGIN
    -- Buscar nodo de usuario, crearlo si no existe
    SELECT id INTO v_node_id FROM auth.query_graph_nodes WHERE id_usuario = NEW.id_usuario;
    IF v_node_id IS NULL THEN
        INSERT INTO auth.query_graph_nodes (node_type, id_usuario, label, payload)
        VALUES ('user', NEW.id_usuario, 'user_' || LEFT(NEW.id_usuario::TEXT, 8), '{}'::jsonb)
        RETURNING id INTO v_node_id;
    END IF;
    -- Insertar edge de tipo 'saldo_consultado' usando el id del nodo
    INSERT INTO auth.query_graph_edges (from_node_id, to_node_id, edge_type, owner_user_id, payload)
    VALUES (v_node_id, v_node_id, 'saldo_consultado', NEW.id_usuario, jsonb_build_object('timestamp', NEW.consulta_timestamp))
    ON CONFLICT (from_node_id, to_node_id, edge_type) DO UPDATE
      SET payload = auth.query_graph_edges.payload || EXCLUDED.payload,
          owner_user_id = EXCLUDED.owner_user_id;
    RETURN NEW;
END;
$$;


--
-- Name: trg_v4_invalidate_nginx_cache_on_price_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_v4_invalidate_nginx_cache_on_price_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'seller', 'auth', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_n int := 0;
BEGIN
  IF TG_OP = 'UPDATE' AND (OLD.precio IS DISTINCT FROM NEW.precio) THEN
    BEGIN
      DELETE FROM seller.dashboard_cache WHERE id_vendedor = NEW.id_vendedor;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      RAISE NOTICE '[NGINX_CACHE_INVALIDATED] vendedor=% cache_rows=% (precio % -> %)',
        NEW.id_vendedor, v_n, OLD.precio, NEW.precio;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[NGINX_CACHE_INVALIDATE_FAILED] producto=%: %', NEW.id, SQLERRM;
    END;
  END IF;
  RETURN NEW;
END;
$$;


