--
-- Name: user_role_change_audit(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_role_change_audit(p_target_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
    v_uid  uuid := auth.current_jwt_user_id();
    v_role text := auth.current_jwt_role();
    v_rows jsonb;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'jwt requerido' USING ERRCODE = '42501';
    END IF;

    SELECT jsonb_agg(t ORDER BY t.id DESC)
      INTO v_rows
      FROM (
        SELECT a.id, a.target_user_id, a.old_role, a.new_role,
               a.changed_by, a.change_source, a.change_reason
          FROM auth.user_role_change_audit a
         WHERE (p_target_user_id IS NULL OR a.target_user_id = p_target_user_id)
           AND (v_role = 'db_admin'
                OR a.target_user_id = v_uid
                OR a.changed_by = v_uid)
         ORDER BY a.id DESC
         LIMIT p_limit OFFSET p_offset
      ) t;

    RETURN jsonb_build_object('items', COALESCE(v_rows, '[]'::jsonb));
END;
$$;


