--
-- Name: validar_coordenadas_comprador(double precision, double precision, double precision, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_coordenadas_comprador(p_user_lat double precision, p_user_lon double precision, p_radio_m double precision DEFAULT 2000, p_busqueda text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_lat double precision := p_user_lat;
    v_lon double precision := p_user_lon;
BEGIN
    IF v_lat IS NULL OR v_lon IS NULL THEN
        RETURN jsonb_build_object('valido', false, 'error', 'COORDENADAS_REQUERIDAS');
    END IF;

    IF v_lat < -90 OR v_lat > 90 THEN
        RETURN jsonb_build_object('valido', false, 'error', 'LATITUD_FUERA_DE_RANGO',
                                  'latitud', v_lat);
    END IF;

    IF v_lon < -180 OR v_lon > 180 THEN
        RETURN jsonb_build_object('valido', false, 'error', 'LONGITUD_FUERA_DE_RANGO',
                                  'longitud', v_lon);
    END IF;

    RETURN jsonb_build_object(
        'valido', true,
        'latitud', v_lat,
        'longitud', v_lon,
        'vendedores', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                       'seller_id',     s.seller_id,
                       'nombre_tienda', s.nombre_tienda,
                       'distancia_m',   s.distancia_m
                   ) ORDER BY s.distancia_m)
              FROM (
                SELECT u.id AS seller_id,
                       COALESCE(ppv.nombre_marca, u.nombre_visible) AS nombre_tienda,
                       ROUND(ST_Distance(o.pto, ub.punto)::numeric, 1)::double precision AS distancia_m
                  FROM (SELECT ST_SetSRID(ST_MakePoint(v_lon, v_lat), 4326)::geography AS pto) o
                  JOIN auth.ubicaciones ub
                    ON ST_DWithin(o.pto, ub.punto, p_radio_m)
                   AND ub.is_active IS NOT FALSE
                   AND ub.fecha_eliminacion IS NULL
                  JOIN auth.users u
                    ON u.id = ub.id_usuario
                   AND u.role = 'seller'
                   AND (u.activo IS NOT FALSE)
                   AND u.fecha_eliminacion IS NULL
                  LEFT JOIN auth.perfiles_publicos_vendedor ppv ON ppv.id_vendedor = u.id
                 WHERE (p_busqueda IS NULL
                        OR COALESCE(ppv.nombre_marca, u.nombre_visible) ILIKE '%' || p_busqueda || '%')
                 ORDER BY ST_Distance(o.pto, ub.punto)
                 LIMIT 50
              ) s
        ), '[]'::jsonb),
        'productos', CASE WHEN p_busqueda IS NULL THEN '[]'::jsonb ELSE COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                       'producto_id',   p.id,
                       'nombre',        p.nombre,
                       'seller_id',     p.id_vendedor,
                       'nombre_tienda', COALESCE(ppv.nombre_marca, u.nombre_visible)
                   ))
              FROM auth.productos p
              JOIN auth.users u ON u.id = p.id_vendedor
                                 AND u.role = 'seller'
                                 AND (u.activo IS NOT FALSE)
                                 AND u.fecha_eliminacion IS NULL
              LEFT JOIN auth.perfiles_publicos_vendedor ppv ON ppv.id_vendedor = u.id
             WHERE p.activo IS NOT FALSE
               AND p.fecha_eliminacion IS NULL
               AND p.nombre ILIKE '%' || p_busqueda || '%'
             LIMIT 50
        ), '[]'::jsonb) END
    );
END;
$$;


--
-- Name: validar_proximidad_compra(double precision, double precision, uuid, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_proximidad_compra(p_buyer_lat double precision, p_buyer_lng double precision, p_id_vendedor uuid, p_max_distance_meters double precision DEFAULT 100) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_seller_geom GEOGRAPHY;
  v_buyer_geom  GEOGRAPHY;
  v_distance    DOUBLE PRECISION;
BEGIN
  SELECT l.geom::geography INTO v_seller_geom
  FROM auth.ubicaciones l
  WHERE l.id_usuario = p_id_vendedor
    AND l.is_active = true
    AND l.fecha_eliminacion IS NULL
    AND l.geom IS NOT NULL
  ORDER BY l.fecha_actualizacion DESC NULLS LAST, l.fecha_creacion DESC NULLS LAST
  LIMIT 1;

  IF v_seller_geom IS NULL THEN
    RAISE EXCEPTION 'NO_EXISTE_UBICACION_ACTIVA_DEL_VENDEDOR' USING ERRCODE = 'P0002';
  END IF;

  IF p_buyer_lat IS NULL OR p_buyer_lng IS NULL THEN
    RAISE EXCEPTION 'COORDENADAS_COMPRADOR_REQUERIDAS' USING ERRCODE = '22023';
  END IF;

  v_buyer_geom := ST_SetSRID(ST_MakePoint(p_buyer_lng, p_buyer_lat), 4326)::geography;
  v_distance   := ST_Distance(v_buyer_geom, v_seller_geom);

  RETURN v_distance <= p_max_distance_meters;
END;
$$;


