--
-- Name: validate_password_strength(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_password_strength(password character varying) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
BEGIN
    RETURN 
        length(password) >= 16 AND
        (password ~ '[A-Z]') AND  -- Mayúscula
        (password ~ '[a-z]') AND  -- Minúscula
        (password ~ '[0-9]') AND  -- Número
        (password ~ '[!@#$%^&*]'); -- Símbolo
END;
$_$;


--
-- Name: validate_timeline_hash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_timeline_hash() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    prev_hash VARCHAR(64);
BEGIN
    -- Obtener hash anterior
    SELECT hash_evento INTO prev_hash
    FROM disputes.dispute_timeline
    WHERE id_disputa = NEW.id_disputa
    ORDER BY fecha_creacion DESC
    LIMIT 1;
    
    -- Calcular hash actual con encadenamiento
    NEW.hash_evento := encode(
        digest(
            concat(NEW.tipo_evento, '|', NEW.event_description, '|', 
                   COALESCE(prev_hash, '')),
            'sha256'
        ),
        'hex'
    );
    
    NEW.prev_event_hash := prev_hash;
    RETURN NEW;
END;
$$;


