CREATE FUNCTION seller.accept_order(p_order_id uuid, p_expected_fulfillment_days integer DEFAULT 7) RETURNS TABLE(success boolean, message character varying, estado character varying, fulfillment_date timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
