--
-- Name: actualizar_metricas_diarias(); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.actualizar_metricas_diarias() RETURNS TABLE(processed_sellers integer, alerts_created integer, suspensions_triggered integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_seller RECORD;
    v_processed INTEGER := 0;
    v_alerts INTEGER := 0;
    v_suspensions INTEGER := 0;
    v_acceptance NUMERIC;
    v_fulfillment NUMERIC;
    v_rating NUMERIC;
    v_negative_reviews INTEGER;
BEGIN
    -- Procesar cada vendedor
    FOR v_seller IN SELECT id, id_usuario FROM seller.profiles LOOP
        
        -- Calcular métricas
        SELECT seller.calculate_acceptance_rate(v_seller.id) INTO v_acceptance;
        SELECT seller.calculate_fulfillment_rate(v_seller.id) INTO v_fulfillment;
        SELECT average_rating INTO v_rating FROM seller.performance_metrics WHERE id_vendedor = v_seller.id;
        SELECT COUNT(*) INTO v_negative_reviews FROM seller.seller_reviews
            WHERE id_vendedor = v_seller.id AND rating <= 2
              AND fecha_creacion > now() - INTERVAL '7 days';
        
        -- Actualizar performance_metrics
        UPDATE seller.performance_metrics
        SET
            acceptance_rate = v_acceptance,
            fulfillment_rate = v_fulfillment,
            average_rating = COALESCE(v_rating, 0),
            negative_reviews_30d = COALESCE(v_negative_reviews, 0),
            last_computed = now()
        WHERE id_vendedor = v_seller.id;
        
        -- Crear snapshot histórico
        INSERT INTO seller.performance_history (
            id_vendedor, snapshot_date, acceptance_rate, fulfillment_rate, average_rating
        ) VALUES (
            v_seller.id, CURRENT_DATE, v_acceptance, v_fulfillment, COALESCE(v_rating, 0)
        ) ON CONFLICT (id_vendedor, snapshot_date) DO UPDATE SET
            acceptance_rate = v_acceptance,
            fulfillment_rate = v_fulfillment,
            average_rating = COALESCE(v_rating, 0);
        
        -- Verificar alertas
        -- Alerta 1: Acceptance rate bajo
        IF v_acceptance < 70 THEN
            INSERT INTO seller.inventory_alerts (
                id_inventario, id_vendedor, tipo_alerta, severity, message
            ) SELECT 
                NULL, v_seller.id, 'low_acceptance', 'high',
                'Tasa de aceptación baja: ' || v_acceptance || '%'
            WHERE NOT EXISTS (
                SELECT 1 FROM seller.inventory_alerts
                WHERE id_vendedor = v_seller.id AND tipo_alerta = 'low_acceptance'
                  AND is_resolved = FALSE
                  AND DATE(fecha_creacion) = CURRENT_DATE
            );
            v_alerts := v_alerts + 1;
        END IF;
        
        -- Alerta 2: Rating bajo (suspensión potencial)
        IF v_rating < 2.5 THEN
            UPDATE seller.profiles
            SET is_verified = FALSE
            WHERE id = v_seller.id AND is_verified = TRUE;
            
            UPDATE seller.performance_metrics
            SET 
                is_suspended = TRUE,
                suspension_reason = 'Rating crítico: ' || v_rating
            WHERE id_vendedor = v_seller.id;
            
            v_suspensions := v_suspensions + 1;
        END IF;
        
        v_processed := v_processed + 1;
    END LOOP;
    
    RETURN QUERY SELECT v_processed, v_alerts, v_suspensions;
END;
$$;


--
-- Name: actualizar_precio_dinamico(uuid, numeric, character varying); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.actualizar_precio_dinamico(p_inventory_id uuid, p_new_price numeric, p_reason character varying DEFAULT 'manual_adjustment'::character varying) RETURNS TABLE(success boolean, old_price numeric, new_price numeric, discount_percentage numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_old_price NUMERIC;
    v_price_base NUMERIC;
    v_discount NUMERIC;
    v_inventory_exists BOOLEAN;
BEGIN
    SELECT pr.id INTO v_id_vendedor
    FROM seller.profiles pr
    WHERE pr.id_usuario = auth.jwt_user_id_safe();

    IF p_inventory_id IS NULL THEN
        RETURN QUERY SELECT FALSE, NULL::NUMERIC, NULL::NUMERIC, NULL::NUMERIC;
        RETURN;
    END IF;

    SELECT EXISTS(
        SELECT 1 FROM seller.inventory
        WHERE id = p_inventory_id AND id_vendedor = v_id_vendedor
    ), price_current, price_base INTO
        v_inventory_exists, v_old_price, v_price_base
    FROM seller.inventory WHERE id = p_inventory_id;

    IF NOT COALESCE(v_inventory_exists, FALSE) THEN
        RETURN QUERY SELECT FALSE, NULL::NUMERIC, NULL::NUMERIC, NULL::NUMERIC;
        RETURN;
    END IF;

    IF p_new_price < 0 THEN
        RETURN QUERY SELECT FALSE, v_old_price, NULL::NUMERIC, NULL::NUMERIC;
        RETURN;
    END IF;

    v_discount := CASE
        WHEN v_price_base > 0 THEN ROUND(((v_price_base - p_new_price) / v_price_base * 100)::NUMERIC, 2)
        ELSE 0
    END;

    UPDATE seller.inventory
    SET
        price_current = p_new_price,
        discount_percentage = GREATEST(0, v_discount),
        fecha_actualizacion = now()
    WHERE id = p_inventory_id;

    INSERT INTO seller.price_history (
        id_inventario, id_vendedor, price_previous, price_new, change_reason
    ) VALUES (
        p_inventory_id, v_id_vendedor, v_old_price, p_new_price, p_reason
    );

    RETURN QUERY SELECT TRUE, v_old_price, p_new_price, v_discount;
END;
$$;


--
-- Name: actualizar_producto(uuid, character varying, numeric, text, character varying, integer); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.actualizar_producto(p_inventory_id uuid, p_product_name character varying DEFAULT NULL::character varying, p_price_base numeric DEFAULT NULL::numeric, p_description text DEFAULT NULL::text, p_category character varying DEFAULT NULL::character varying, p_low_stock_threshold integer DEFAULT NULL::integer) RETURNS TABLE(success boolean, message character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_old_price NUMERIC;
    v_product_exists BOOLEAN;
BEGIN
    -- Obtener id_vendedor
    SELECT id INTO v_id_vendedor 
    FROM seller.profiles 
    WHERE id_usuario = auth.jwt_user_id_safe();
    
    -- Verificar propiedad del producto
    SELECT EXISTS(
        SELECT 1 FROM seller.inventory 
        WHERE id = p_inventory_id AND id_vendedor = v_id_vendedor
    ) INTO v_product_exists;
    
    IF NOT v_product_exists THEN
        RETURN QUERY SELECT FALSE, 'Producto no encontrado o no autorizado'::VARCHAR;
        RETURN;
    END IF;
    
    -- Guardar precio anterior
    SELECT price_base INTO v_old_price 
    FROM seller.inventory WHERE id = p_inventory_id;
    
    -- Validar precio si se proporciona
    IF p_price_base IS NOT NULL AND p_price_base <= 0 THEN
        RETURN QUERY SELECT FALSE, 'Precio debe ser > 0'::VARCHAR;
        RETURN;
    END IF;
    
    -- Actualizar campos
    UPDATE seller.inventory SET
        nombre_producto = COALESCE(p_product_name, nombre_producto),
        price_base = COALESCE(p_price_base, price_base),
        price_current = COALESCE(p_price_base, price_current),
        description = COALESCE(p_description, description),
        category = COALESCE(p_category, category),
        low_stock_threshold = COALESCE(p_low_stock_threshold, low_stock_threshold)
    WHERE id = p_inventory_id;
    
    -- Registrar auditoría de precio
    IF p_price_base IS NOT NULL AND p_price_base != v_old_price THEN
        INSERT INTO seller.inventory_audit (
            id_inventario, id_vendedor, tipo_accion, field_name, old_value, new_value
        ) VALUES (
            p_inventory_id, v_id_vendedor, 'price_change', 'price_base',
            v_old_price::VARCHAR, p_price_base::VARCHAR
        );
    END IF;
    
    RETURN QUERY SELECT TRUE, 'Producto actualizado exitosamente'::VARCHAR;
END;
$$;


--
-- Name: adjust_stock(uuid, integer, character varying); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.adjust_stock(p_inventory_id uuid, p_quantity_delta integer, p_reason character varying DEFAULT 'manual_adjustment'::character varying) RETURNS TABLE(success boolean, new_quantity integer, message character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY SELECT * FROM seller.ajustar_existencia(p_inventory_id, p_quantity_delta, p_reason);
END;
$$;


--
-- Name: ajustar_existencia(uuid, integer, character varying); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.ajustar_existencia(p_inventory_id uuid, p_quantity_delta integer, p_reason character varying DEFAULT 'manual_adjustment'::character varying) RETURNS TABLE(success boolean, new_quantity integer, message character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_current_qty INTEGER;
    v_new_qty INTEGER;
    v_threshold INTEGER;
    v_product_exists BOOLEAN;
BEGIN
    -- Obtener id_vendedor
    SELECT id INTO v_id_vendedor 
    FROM seller.profiles 
    WHERE id_usuario = auth.jwt_user_id_safe();
    
    -- Verificar propiedad
    SELECT EXISTS(
        SELECT 1 FROM seller.inventory 
        WHERE id = p_inventory_id AND id_vendedor = v_id_vendedor
    ) INTO v_product_exists;
    
    IF NOT v_product_exists THEN
        RETURN QUERY SELECT FALSE, 0, 'Producto no encontrado'::VARCHAR;
        RETURN;
    END IF;
    
    -- Obtener cantidad actual y threshold
    SELECT quantity_available, low_stock_threshold 
    INTO v_current_qty, v_threshold
    FROM seller.inventory WHERE id = p_inventory_id;
    
    -- Calcular nueva cantidad
    v_new_qty := v_current_qty + p_quantity_delta;
    
    -- Validar que no sea negativa
    IF v_new_qty < 0 THEN
        RETURN QUERY SELECT FALSE, v_current_qty, 'Stock insuficiente para esta operación'::VARCHAR;
        RETURN;
    END IF;
    
    -- Actualizar cantidad
    UPDATE seller.inventory 
    SET quantity_available = v_new_qty
    WHERE id = p_inventory_id;
    
    -- Registrar auditoría
    INSERT INTO seller.inventory_audit (
        id_inventario, id_vendedor, tipo_accion, field_name, old_value, new_value
    ) VALUES (
        p_inventory_id, v_id_vendedor, 'stock_adjust', 'quantity_available',
        v_current_qty::VARCHAR, v_new_qty::VARCHAR
    );
    
    -- Crear alerta si stock bajo
    IF v_new_qty < v_threshold AND v_current_qty >= v_threshold THEN
        INSERT INTO seller.inventory_alerts (
            id_inventario, id_vendedor, tipo_alerta, severity, message
        ) VALUES (
            p_inventory_id, v_id_vendedor, 'low_stock', 'high',
            'Stock bajo: ' || v_new_qty || ' unidades'
        );
    END IF;
    
    -- Resolver alerta si stock recuperado
    IF v_new_qty >= v_threshold THEN
        UPDATE seller.inventory_alerts SET
            is_resolved = TRUE,
            resuelto_en = now()
        WHERE id_inventario = p_inventory_id 
          AND tipo_alerta = 'low_stock'
          AND is_resolved = FALSE;
    END IF;
    
    RETURN QUERY SELECT TRUE, v_new_qty, 'Stock ajustado exitosamente'::VARCHAR;
END;
$$;


--
-- Name: calcular_tasa_aceptacion(uuid, integer); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.calcular_tasa_aceptacion(p_id_vendedor uuid, p_days_back integer DEFAULT 30) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_total_orders INTEGER;
    v_accepted_orders INTEGER;
    v_rate NUMERIC;
BEGIN
    -- Contar órdenes totales
    SELECT COUNT(*)
    INTO v_total_orders
    FROM auth.ordenes
    WHERE id_vendedor = p_id_vendedor
      AND fecha_creacion > now() - (p_days_back || ' days')::INTERVAL
      AND estado IN ('confirmada', 'cancelada', 'pendiente');
    
    -- Contar órdenes aceptadas
    SELECT COUNT(*)
    INTO v_accepted_orders
    FROM auth.ordenes
    WHERE id_vendedor = p_id_vendedor
      AND fecha_creacion > now() - (p_days_back || ' days')::INTERVAL
      AND estado = 'confirmada';
    
    -- Calcular tasa
    IF v_total_orders = 0 THEN
        v_rate := 0.00;
    ELSE
        v_rate := ROUND(
            v_accepted_orders::NUMERIC / v_total_orders * 100, 2
        );
    END IF;
    
    RETURN v_rate;
END;
$$;


--
-- Name: calcular_tasa_cumplimiento(uuid, integer); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.calcular_tasa_cumplimiento(p_id_vendedor uuid, p_days_back integer DEFAULT 30) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_accepted_orders INTEGER;
    v_delivered_orders INTEGER;
    v_rate NUMERIC;
BEGIN
    -- Órdenes aceptadas
    SELECT COUNT(*)
    INTO v_accepted_orders
    FROM auth.ordenes
    WHERE id_vendedor = p_id_vendedor
      AND fecha_creacion > now() - (p_days_back || ' days')::INTERVAL
      AND estado IN ('confirmada', 'completada', 'entregado');
    
    -- Órdenes entregadas
    SELECT COUNT(*)
    INTO v_delivered_orders
    FROM auth.ordenes
    WHERE id_vendedor = p_id_vendedor
      AND fecha_creacion > now() - (p_days_back || ' days')::INTERVAL
      AND estado = 'entregado';
    
    -- Calcular tasa
    IF v_accepted_orders = 0 THEN
        v_rate := 0.00;
    ELSE
        v_rate := ROUND(
            v_delivered_orders::NUMERIC / v_accepted_orders * 100, 2
        );
    END IF;
    
    RETURN v_rate;
END;
$$;


--
-- Name: calculate_acceptance_rate(uuid, integer); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.calculate_acceptance_rate(p_id_vendedor uuid, p_days_back integer DEFAULT 30) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
BEGIN
    RETURN seller.calcular_tasa_aceptacion(p_id_vendedor, p_days_back);
END;
$$;


