--
-- Name: crear_oferta(character varying, uuid[], character varying, numeric, timestamp with time zone, timestamp with time zone, integer, text, character varying); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.crear_oferta(p_offer_name character varying, p_inventory_ids uuid[], p_discount_type character varying, p_discount_value numeric, p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_quantity_available integer DEFAULT NULL::integer, p_description text DEFAULT NULL::text, p_offer_type character varying DEFAULT 'limited_time'::character varying) RETURNS TABLE(id_oferta uuid, success boolean, message character varying, products_affected integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_offer_id UUID;
    v_product_count INTEGER := 0;
    v_inventory RECORD;
BEGIN
    -- Obtener id_vendedor
    SELECT id INTO v_id_vendedor 
    FROM seller.profiles 
    WHERE id_usuario = auth.jwt_user_id_safe() AND is_verified = TRUE;
    
    IF v_id_vendedor IS NULL THEN
        RETURN QUERY SELECT NULL::UUID, FALSE, 'Vendedor no verificado'::VARCHAR, 0;
        RETURN;
    END IF;
    
    -- Validar descuento
    IF p_discount_type = 'percentage' AND (p_discount_value <= 0 OR p_discount_value > 100) THEN
        RETURN QUERY SELECT NULL::UUID, FALSE, 'Descuento porcentaje debe estar entre 0-100'::VARCHAR, 0;
        RETURN;
    END IF;
    
    IF p_discount_type = 'fixed_amount' AND p_discount_value <= 0 THEN
        RETURN QUERY SELECT NULL::UUID, FALSE, 'Descuento fijo debe ser > 0'::VARCHAR, 0;
        RETURN;
    END IF;
    
    -- Validar fechas
    IF p_start_date >= p_end_date THEN
        RETURN QUERY SELECT NULL::UUID, FALSE, 'Fecha inicio debe ser antes que fin'::VARCHAR, 0;
        RETURN;
    END IF;
    
    -- Validar que los productos pertenecen al vendedor
    FOR v_inventory IN SELECT id FROM seller.inventory WHERE id = ANY(p_inventory_ids) AND id_vendedor = v_id_vendedor LOOP
        v_product_count := v_product_count + 1;
    END LOOP;
    
    IF v_product_count = 0 THEN
        RETURN QUERY SELECT NULL::UUID, FALSE, 'No se encontraron productos válidos'::VARCHAR, 0;
        RETURN;
    END IF;
    
    -- Crear oferta
    INSERT INTO seller.offers (
        id_vendedor, nombre_oferta, description, offer_type,
        inventory_ids, discount_type, discount_value,
        start_date, end_date, quantity_available
    ) VALUES (
        v_id_vendedor, p_offer_name, p_description, p_offer_type,
        p_inventory_ids, p_discount_type, p_discount_value,
        p_start_date, p_end_date, p_quantity_available
    ) RETURNING seller.offers.id INTO v_offer_id;
    
    -- Crear entrada en offer_usage
    INSERT INTO seller.offer_usage (id_oferta, id_vendedor)
    VALUES (v_offer_id, v_id_vendedor);
    
    -- Actualizar precios en inventory (aplicar descuento)
    UPDATE seller.inventory
    SET 
        price_current = CASE
            WHEN p_discount_type = 'percentage' 
            THEN price_base * (1 - p_discount_value / 100)
            WHEN p_discount_type = 'fixed_amount'
            THEN GREATEST(0, price_base - p_discount_value)
            ELSE price_base
        END,
        discount_percentage = CASE
            WHEN p_discount_type = 'percentage' THEN p_discount_value
            WHEN p_discount_type = 'fixed_amount' THEN ROUND((p_discount_value / price_base * 100)::NUMERIC, 2)
            ELSE 0
        END
    WHERE id = ANY(p_inventory_ids) AND id_vendedor = v_id_vendedor;
    
    -- Registrar cambios en price_history
    INSERT INTO seller.price_history (
        id_inventario, id_vendedor, price_previous, price_new, change_reason, related_offer_id
    )
    SELECT
        id,
        v_id_vendedor,
        price_base,
        CASE
            WHEN p_discount_type = 'percentage' THEN price_base * (1 - p_discount_value / 100)
            ELSE GREATEST(0, price_base - p_discount_value)
        END,
        'offer_' || p_offer_name,
        v_offer_id
    FROM seller.inventory
    WHERE id = ANY(p_inventory_ids) AND id_vendedor = v_id_vendedor;
    
    RETURN QUERY SELECT v_offer_id, TRUE, 'Oferta creada exitosamente'::VARCHAR, v_product_count;
END;
$$;


--
-- Name: crear_producto(character varying, character varying, text, character varying, numeric, integer, integer); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.crear_producto(p_product_name character varying, p_product_sku character varying, p_description text, p_category character varying, p_price_base numeric, p_quantity_available integer, p_low_stock_threshold integer DEFAULT 10) RETURNS TABLE(id uuid, message character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_inventory_id UUID;
    v_sku_exists BOOLEAN;
BEGIN
    SELECT pr.id INTO v_id_vendedor
    FROM seller.profiles pr
    WHERE pr.id_usuario = auth.jwt_user_id_safe() AND pr.is_verified = TRUE;

    IF v_id_vendedor IS NULL THEN
        RETURN QUERY SELECT NULL::UUID, 'Vendedor no verificado'::VARCHAR;
        RETURN;
    END IF;

    SELECT EXISTS(
        SELECT 1 FROM seller.inventory
        WHERE id_vendedor = v_id_vendedor AND product_sku = p_product_sku
    ) INTO v_sku_exists;

    IF v_sku_exists THEN
        RETURN QUERY SELECT NULL::UUID, 'SKU ya existe'::VARCHAR;
        RETURN;
    END IF;

    IF p_price_base <= 0 THEN
        RETURN QUERY SELECT NULL::UUID, 'Precio debe ser > 0'::VARCHAR;
        RETURN;
    END IF;

    IF p_quantity_available < 0 THEN
        RETURN QUERY SELECT NULL::UUID, 'Cantidad no puede ser negativa'::VARCHAR;
        RETURN;
    END IF;

    INSERT INTO seller.inventory (
        id_vendedor, nombre_producto, product_sku, description, category,
        price_base, price_current, quantity_available, low_stock_threshold
    ) VALUES (
        v_id_vendedor, p_product_name, p_product_sku, p_description, p_category,
        p_price_base, p_price_base, p_quantity_available, p_low_stock_threshold
    ) RETURNING inventory.id INTO v_inventory_id;

    INSERT INTO seller.inventory_audit (
        id_inventario, id_vendedor, tipo_accion
    ) VALUES (v_inventory_id, v_id_vendedor, 'create');

    IF p_quantity_available < p_low_stock_threshold THEN
        INSERT INTO seller.inventory_alerts (
            id_inventario, id_vendedor, tipo_alerta, severity, message
        ) VALUES (
            v_inventory_id, v_id_vendedor, 'low_stock', 'medium',
            'Stock bajo al crear producto: ' || p_quantity_available
        );
    END IF;

    RETURN QUERY SELECT v_inventory_id, 'Producto creado exitosamente'::VARCHAR;
END;
$$;


--
-- Name: create_offer(character varying, uuid[], character varying, numeric, timestamp with time zone, timestamp with time zone, integer, text, character varying); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.create_offer(p_offer_name character varying, p_inventory_ids uuid[], p_discount_type character varying, p_discount_value numeric, p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_quantity_available integer DEFAULT NULL::integer, p_description text DEFAULT NULL::text, p_offer_type character varying DEFAULT 'limited_time'::character varying) RETURNS TABLE(id_oferta uuid, success boolean, message character varying, products_affected integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
BEGIN
