CREATE FUNCTION seller.create_product(p_product_name character varying, p_product_sku character varying, p_description text, p_category character varying, p_price_base numeric, p_quantity_available integer, p_low_stock_threshold integer DEFAULT 10) RETURNS TABLE(id uuid, message character varying)
