--
-- Name: liberar_existencia_reservada(uuid); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.liberar_existencia_reservada(p_order_id uuid) RETURNS TABLE(success boolean, message character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_reservation RECORD;
BEGIN
    -- Obtener reservas
    FOR v_reservation IN
        SELECT * FROM seller.order_stock_reservations
        WHERE id_orden = p_order_id AND reservation_status = 'active'
    LOOP
        -- Liberar cantidad en inventory
        UPDATE seller.inventory
        SET quantity_reserved = GREATEST(0, quantity_reserved - v_reservation.quantity_reserved)
        WHERE id = v_reservation.id_inventario;
        
        -- Marcar reserva como released
        UPDATE seller.order_stock_reservations
        SET 
            reservation_status = 'released',
            released_at = now()
        WHERE id = v_reservation.id;
    END LOOP;
    
    RETURN QUERY SELECT TRUE, 'Stock reservado liberado'::VARCHAR;
END;
$$;


