--
-- Name: listar_ofertas_activas(integer, integer); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.listar_ofertas_activas(p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id_oferta uuid, nombre_oferta character varying, offer_type character varying, discount_percentage numeric, products_count integer, quantity_left integer, start_date timestamp with time zone, end_date timestamp with time zone, orders_count integer, revenue numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
BEGIN
    -- Obtener id_vendedor
    SELECT id INTO v_id_vendedor 
    FROM seller.profiles 
    WHERE id_usuario = auth.jwt_user_id_safe();
    
    IF v_id_vendedor IS NULL THEN
        RETURN;
    END IF;
    
    RETURN QUERY
    SELECT
        o.id,
        o.nombre_oferta,
        o.offer_type,
        CASE
            WHEN o.discount_type = 'percentage' THEN o.discount_value
            ELSE ROUND((o.discount_value / (SELECT AVG(price_base) FROM seller.inventory WHERE id = ANY(o.inventory_ids)) * 100)::NUMERIC, 2)
        END,
        o.product_count,
        COALESCE(o.quantity_available - o.quantity_purchased, -1),
        o.start_date,
        o.end_date,
        COALESCE(ou.orders_using_offer, 0),
        COALESCE(ou.total_revenue_with_offer, 0)
    FROM seller.offers o
    LEFT JOIN seller.offer_usage ou ON o.id = ou.id_oferta
    WHERE o.id_vendedor = v_id_vendedor
      AND o.is_active = TRUE
      AND o.end_date > now()
    ORDER BY o.start_date DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: listar_ordenes_vendedor(character varying, integer, integer, integer, character varying); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.listar_ordenes_vendedor(p_status character varying DEFAULT NULL::character varying, p_days_back integer DEFAULT 30, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_sort_by character varying DEFAULT 'created_at'::character varying) RETURNS TABLE(id uuid, id_comprador uuid, buyer_email character varying, total numeric, estado character varying, items_count integer, fecha_creacion timestamp with time zone, expected_delivery timestamp with time zone, payment_confirmed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_date_filter TIMESTAMP WITH TIME ZONE;
BEGIN
    SELECT pr.id INTO v_id_vendedor
    FROM seller.profiles pr
    WHERE pr.id_usuario = auth.jwt_user_id_safe();

    IF v_id_vendedor IS NULL THEN
        RAISE EXCEPTION 'No authenticated seller';
    END IF;

    v_date_filter := now() - (p_days_back || ' days')::INTERVAL;

    RETURN QUERY
    SELECT
        o.id, o.id_comprador, u.email, o.total, o.estado,
        COALESCE((o.metadata->>'items_count')::INTEGER, 0),
        o.fecha_creacion, o.fecha_creacion + INTERVAL '7 days',
        COALESCE((o.metadata->>'payment_confirmed')::BOOLEAN, FALSE)
    FROM auth.ordenes o
    JOIN auth.users u ON o.id_comprador = u.id
    WHERE o.id_vendedor = v_id_vendedor
      AND o.fecha_creacion > v_date_filter
      AND (p_status IS NULL OR o.estado = p_status)
    ORDER BY
        CASE WHEN p_sort_by = 'created_at' THEN o.fecha_creacion END DESC,
        CASE WHEN p_sort_by = 'amount' THEN o.total END DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: listar_productos(integer, integer, character varying, character varying); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.listar_productos(p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_category character varying DEFAULT NULL::character varying, p_search character varying DEFAULT NULL::character varying) RETURNS TABLE(id uuid, nombre_producto character varying, product_sku character varying, category character varying, price_current numeric, quantity_available integer, rating numeric, fecha_creacion timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
BEGIN
    SELECT pr.id INTO v_id_vendedor
    FROM seller.profiles pr
    WHERE pr.id_usuario = auth.jwt_user_id_safe();

    IF v_id_vendedor IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    SELECT
        i.id,
        i.nombre_producto,
        i.product_sku,
        i.category,
        i.price_current,
        i.quantity_available,
        i.average_rating,
        i.fecha_creacion
    FROM seller.inventory i
    WHERE i.id_vendedor = v_id_vendedor
        AND (p_category IS NULL OR i.category = p_category)
        AND (p_search IS NULL OR
             i.nombre_producto ILIKE '%' || p_search || '%' OR
             i.product_sku ILIKE '%' || p_search || '%')
    ORDER BY i.fecha_actualizacion DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: marcar_notificacion_leida(uuid); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.marcar_notificacion_leida(p_notification_id uuid) RETURNS TABLE(success boolean, message character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_notif_exists BOOLEAN;
BEGIN
    -- Obtener id_vendedor
    SELECT id INTO v_id_vendedor 
    FROM seller.profiles 
    WHERE id_usuario = auth.jwt_user_id_safe();
    
    -- Verificar pertenencia
    SELECT EXISTS(
        SELECT 1 FROM seller.seller_notifications
        WHERE id = p_notification_id AND id_vendedor = v_id_vendedor
    ) INTO v_notif_exists;
    
    IF NOT v_notif_exists THEN
        RETURN QUERY SELECT FALSE, 'Notification not found'::VARCHAR;
        RETURN;
    END IF;
    
    -- Actualizar
    UPDATE seller.seller_notifications
    SET is_read = TRUE, read_at = now()
    WHERE id = p_notification_id;
    
    RETURN QUERY SELECT TRUE, 'Notification marked as read'::VARCHAR;
END;
$$;


