--
-- Name: obtener_acciones_orden_pendiente(integer); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.obtener_acciones_orden_pendiente(p_limit integer DEFAULT 10) RETURNS TABLE(id_orden uuid, buyer_email character varying, total numeric, fecha_creacion timestamp with time zone, time_pending_hours numeric, items_json jsonb, buyer_location character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
BEGIN
    -- Obtener id_vendedor
    SELECT id INTO v_id_vendedor 
    FROM seller.profiles 
    WHERE id_usuario = auth.jwt_user_id_safe();
    
    IF v_id_vendedor IS NULL THEN
        RETURN;
    END IF;
    
    RETURN QUERY
    SELECT
        o.id,
        u.email,
        o.total,
        o.fecha_creacion,
        EXTRACT(EPOCH FROM (now() - o.fecha_creacion)) / 3600,
        o.metadata->'items',
        COALESCE(o.metadata->>'buyer_location', 'Unknown')
    FROM auth.ordenes o
    JOIN auth.users u ON o.id_comprador = u.id
    WHERE o.id_vendedor = v_id_vendedor AND o.estado = 'pendiente'
    ORDER BY o.fecha_creacion ASC
    LIMIT p_limit;
END;
$$;


--
-- Name: obtener_calificacion_promedio(uuid, boolean); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.obtener_calificacion_promedio(p_id_vendedor uuid, p_verified_only boolean DEFAULT true) RETURNS TABLE(average_rating numeric, total_reviews integer, rating_distribution jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_avg NUMERIC;
    v_count INTEGER;
    v_distribution JSONB;
BEGIN
    -- Obtener rating promedio
    SELECT 
        ROUND(AVG(rating)::NUMERIC, 2),
        COUNT(*)
    INTO v_avg, v_count
    FROM seller.seller_reviews
    WHERE id_vendedor = p_id_vendedor
      AND (NOT p_verified_only OR verified_purchase = TRUE);
    
    -- Obtener distribución
    SELECT jsonb_object_agg(
        rating::VARCHAR,
        count
    ) INTO v_distribution
    FROM (
        SELECT 
            rating,
            COUNT(*) as count
        FROM seller.seller_reviews
        WHERE id_vendedor = p_id_vendedor
          AND (NOT p_verified_only OR verified_purchase = TRUE)
        GROUP BY rating
    ) t;
    
    RETURN QUERY SELECT
        COALESCE(v_avg, 0.00),
        COALESCE(v_count, 0),
        COALESCE(v_distribution, '{}'::JSONB);
END;
$$;


--
-- Name: obtener_datos_analitica(integer); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.obtener_datos_analitica(p_days_back integer DEFAULT 30) RETURNS TABLE(metric_name character varying, metric_date date, metric_value numeric, trend_direction character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
BEGIN
    -- Obtener id_vendedor
    SELECT id INTO v_id_vendedor 
    FROM seller.profiles 
    WHERE id_usuario = auth.jwt_user_id_safe();
    
    IF v_id_vendedor IS NULL THEN
        RAISE EXCEPTION 'No authenticated seller';
    END IF;
    
    RETURN QUERY
    -- Órdenes por día
    SELECT 
        'orders_per_day'::VARCHAR,
        o.fecha_creacion::DATE,
        COUNT(*)::NUMERIC,
        'up'::VARCHAR
    FROM auth.ordenes o
    WHERE o.id_vendedor = v_id_vendedor 
      AND o.fecha_creacion > now() - (p_days_back || ' days')::INTERVAL
    GROUP BY o.fecha_creacion::DATE
    
    UNION ALL
    
    -- Revenue por día
    SELECT
        'revenue_per_day'::VARCHAR,
        o.fecha_creacion::DATE,
        COALESCE(SUM(o.total), 0),
        'up'::VARCHAR
    FROM auth.ordenes o
    WHERE o.id_vendedor = v_id_vendedor
      AND o.fecha_creacion > now() - (p_days_back || ' days')::INTERVAL
    GROUP BY o.fecha_creacion::DATE
    
    UNION ALL
    
    -- Aceptación por día
    SELECT
        'acceptance_rate_per_day'::VARCHAR,
        date_trunc('day', oa.fecha_creacion)::DATE,
        (COUNT(CASE WHEN oa.tipo_accion = 'accept' THEN 1 END)::NUMERIC / 
         NULLIF(COUNT(*), 0) * 100),
        'up'::VARCHAR
    FROM seller.order_actions oa
    WHERE oa.id_vendedor = v_id_vendedor
      AND oa.fecha_creacion > now() - (p_days_back || ' days')::INTERVAL
    GROUP BY date_trunc('day', oa.fecha_creacion);
END;
$$;


--
-- Name: obtener_detalle_orden(uuid); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.obtener_detalle_orden(p_order_id uuid) RETURNS TABLE(id_orden uuid, buyer_name character varying, buyer_email character varying, buyer_phone character varying, shipping_address jsonb, total numeric, estado character varying, payment_status character varying, items_json jsonb, timeline_json jsonb, tracking_number character varying, estimated_delivery date, fecha_creacion timestamp with time zone, fecha_actualizacion timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_items_json JSONB;
    v_timeline_json JSONB;
    v_order_exists BOOLEAN;
BEGIN
    -- Obtener id_vendedor
    SELECT id INTO v_id_vendedor 
    FROM seller.profiles 
    WHERE id_usuario = auth.jwt_user_id_safe();
    
    -- Verificar que orden pertenece a este vendedor
    SELECT EXISTS(
        SELECT 1 FROM auth.ordenes 
        WHERE id = p_order_id AND id_vendedor = v_id_vendedor
    ) INTO v_order_exists;
    
    IF NOT v_order_exists THEN
        RAISE EXCEPTION 'Order not found or not authorized';
    END IF;
    
    -- Obtener items de la orden (si están en metadata)
    SELECT o.metadata->'items'
    INTO v_items_json
    FROM auth.ordenes o
    WHERE o.id = p_order_id;
    
    -- Obtener timeline de eventos
    SELECT jsonb_agg(
        jsonb_build_object(
            'event_type', tipo_evento,
            'description', event_description,
            'created_at', fecha_creacion
        ) ORDER BY fecha_creacion DESC
    )
    INTO v_timeline_json
    FROM seller.order_timeline
    WHERE id_orden = p_order_id;
    
    RETURN QUERY
    SELECT
        o.id,
        u.nombre_visible,
        u.email,
        NULL::text,
        o.metadata->'shipping_address',
        o.total,
        o.estado,
        COALESCE(o.metadata->>'payment_status', 'pendiente'),
        v_items_json,
        COALESCE(v_timeline_json, '[]'::JSONB),
        COALESCE(o.metadata->>'tracking_number', ''),
        (o.fecha_creacion + INTERVAL '7 days')::DATE,
        o.fecha_creacion,
        o.fecha_actualizacion
    FROM auth.ordenes o
    JOIN auth.users u ON o.id_comprador = u.id
    WHERE o.id = p_order_id;
END;
$$;


--
-- Name: obtener_detalles_producto(uuid); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.obtener_detalles_producto(p_inventory_id uuid) RETURNS TABLE(id uuid, nombre_producto character varying, product_sku character varying, description text, category character varying, price_base numeric, price_current numeric, discount_percentage numeric, quantity_available integer, quantity_reserved integer, quantity_sold integer, low_stock_threshold integer, average_rating numeric, images_count integer, alerts_count integer, fecha_creacion timestamp with time zone, fecha_actualizacion timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_alerts_count INTEGER;
BEGIN
    SELECT pr.id INTO v_id_vendedor
    FROM seller.profiles pr
    WHERE pr.id_usuario = auth.jwt_user_id_safe();

    SELECT COUNT(*) INTO v_alerts_count
    FROM seller.inventory_alerts
    WHERE id_inventario = p_inventory_id AND is_resolved = FALSE;

    RETURN QUERY
    SELECT
        i.id, i.nombre_producto, i.product_sku, i.description, i.category,
        i.price_base, i.price_current, i.discount_percentage,
        i.quantity_available, i.quantity_reserved, i.quantity_sold,
        i.low_stock_threshold, i.average_rating, i.images_count,
        v_alerts_count, i.fecha_creacion, i.fecha_actualizacion
    FROM seller.inventory i
    WHERE i.id = p_inventory_id AND i.id_vendedor = v_id_vendedor;
END;
$$;


--
-- Name: obtener_detalles_rendimiento(uuid); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.obtener_detalles_rendimiento(p_id_vendedor uuid DEFAULT NULL::uuid) RETURNS TABLE(nombre_negocio character varying, total_orders integer, acceptance_rate numeric, fulfillment_rate numeric, return_rate numeric, average_rating numeric, total_reviews integer, sla_compliance numeric, suspension_status boolean, performance_trend character varying, key_metrics jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_prev_rating NUMERIC;
    v_curr_rating NUMERIC;
BEGIN
    -- Obtener id_vendedor si no se proporciona
    IF p_id_vendedor IS NULL THEN
        SELECT id INTO v_id_vendedor 
        FROM seller.profiles 
        WHERE id_usuario = auth.jwt_user_id_safe();
    ELSE
        v_id_vendedor := p_id_vendedor;
    END IF;
    
    IF v_id_vendedor IS NULL THEN
        RAISE EXCEPTION 'Seller not found';
    END IF;
    
    -- Obtener rating anterior
    SELECT average_rating INTO v_prev_rating
    FROM seller.performance_history
    WHERE id_vendedor = v_id_vendedor
      AND snapshot_date = CURRENT_DATE - 7
    LIMIT 1;
    
    RETURN QUERY
    SELECT
        sp.nombre_negocio,
        COALESCE(pm.total_orders, 0)::INTEGER,
        COALESCE(pm.acceptance_rate, 0),
        COALESCE(pm.fulfillment_rate, 0),
        COALESCE(pm.return_rate, 0),
        COALESCE(pm.average_rating, 0),
        (SELECT COUNT(*) FROM seller.seller_reviews WHERE id_vendedor = v_id_vendedor)::INTEGER,
        COALESCE(pm.sla_compliance_rate, 0),
        COALESCE(pm.is_suspended, FALSE),
        CASE
            WHEN pm.average_rating > v_prev_rating THEN 'improving'
            WHEN pm.average_rating < v_prev_rating THEN 'declining'
            ELSE 'stable'
        END::VARCHAR,
        jsonb_build_object(
            'total_revenue', COALESCE(pm.total_revenue, 0),
            'total_refunds', COALESCE(pm.total_refunds, 0),
            'on_time_rate', COALESCE(pm.on_time_delivery_rate, 0),
            'response_time_minutes', COALESCE(pm.avg_response_time_minutes, 0),
            'negative_reviews_7d', COALESCE(pm.negative_reviews_30d, 0)
        )
    FROM seller.profiles sp
    LEFT JOIN seller.performance_metrics pm ON sp.id = pm.id_vendedor
    WHERE sp.id = v_id_vendedor;
END;
$$;


--
-- Name: obtener_estadisticas_oferta(uuid); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.obtener_estadisticas_oferta(p_offer_id uuid) RETURNS TABLE(id_oferta uuid, nombre_oferta character varying, impression_count integer, conversion_count integer, conversion_rate numeric, total_discount_given numeric, net_revenue numeric, roi_percentage numeric, average_order_value numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_offer_exists BOOLEAN;
BEGIN
    -- Obtener id_vendedor
    SELECT id INTO v_id_vendedor 
    FROM seller.profiles 
    WHERE id_usuario = auth.jwt_user_id_safe();
    
    -- Validar propiedad de oferta
    SELECT EXISTS(
        SELECT 1 FROM seller.offers 
        WHERE id = p_offer_id AND id_vendedor = v_id_vendedor
    ) INTO v_offer_exists;
    
    IF NOT v_offer_exists THEN
        RAISE EXCEPTION 'Offer not found or not authorized';
    END IF;
    
    RETURN QUERY
    SELECT
        o.id,
        o.nombre_oferta,
        COALESCE(ou.impressions_count, 0),
        COALESCE(ou.orders_using_offer, 0),
        COALESCE(ou.conversion_rate, 0),
        COALESCE(ou.total_discount_value, 0),
        COALESCE(ou.net_revenue, 0),
        COALESCE(ou.roi_percentage, 0),
        COALESCE(ou.average_order_value, 0)
    FROM seller.offers o
    LEFT JOIN seller.offer_usage ou ON o.id = ou.id_oferta
    WHERE o.id = p_offer_id;
END;
$$;


--
-- Name: obtener_historial_precios(uuid, integer); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.obtener_historial_precios(p_inventory_id uuid, p_days_back integer DEFAULT 90) RETURNS TABLE(change_date date, old_price numeric, new_price numeric, change_reason character varying, discount_percentage numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
BEGIN
    -- Obtener id_vendedor
    SELECT id INTO v_id_vendedor 
    FROM seller.profiles 
    WHERE id_usuario = auth.jwt_user_id_safe();
    
    RETURN QUERY
    SELECT
        ph.fecha_creacion::DATE,
        ph.price_previous,
        ph.price_new,
        ph.change_reason,
        ph.price_change_percentage
    FROM seller.price_history ph
    WHERE ph.id_inventario = p_inventory_id
      AND ph.id_vendedor = v_id_vendedor
      AND ph.fecha_creacion > now() - (p_days_back || ' days')::INTERVAL
    ORDER BY ph.fecha_creacion DESC;
END;
$$;


--
-- Name: obtener_mi_puntaje_riesgo(); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.obtener_mi_puntaje_riesgo() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'seller', 'auth', 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_score numeric;
  v_nivel text;
  v_factores jsonb;
  v_cancelados integer;
  v_negativos integer;
  v_reportes integer;
BEGIN
  v_user_id := auth.fn_current_user_id();

  SELECT s.score, s.nivel_riesgo, s.factores_riesgo,
         s.intercambios_cancelados, s.ratings_negativos, s.reportes_recibidos
  INTO v_score, v_nivel, v_factores, v_cancelados, v_negativos, v_reportes
  FROM public.user_risk_scores s
  WHERE s.id_usuario = v_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Vendedor sin score de riesgo registrado',
      'id_usuario', v_user_id
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'id_usuario', v_user_id,
    'score', v_score,
    'nivel_riesgo', v_nivel,
    'factores', v_factores,
    'detalle', jsonb_build_object(
      'intercambios_cancelados', v_cancelados,
      'ratings_negativos', v_negativos,
      'reportes_recibidos', v_reportes
    )
  );
END;
$$;


--
-- Name: obtener_resumen_panel(); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.obtener_resumen_panel() RETURNS TABLE(total_orders_30d integer, total_revenue_30d numeric, pending_orders integer, acceptance_rate numeric, fulfillment_rate numeric, average_rating numeric, review_count integer, negative_reviews_7d integer, critical_alerts integer, unread_notifications integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_total_orders INTEGER;
    v_total_revenue NUMERIC;
    v_pending INTEGER;
    v_acceptance NUMERIC;
    v_fulfillment NUMERIC;
    v_rating NUMERIC;
    v_reviews INTEGER;
    v_negative INTEGER;
    v_critical_alerts INTEGER;
    v_unread INTEGER;
BEGIN
    -- Obtener id_vendedor
    SELECT id INTO v_id_vendedor 
    FROM seller.profiles 
    WHERE id_usuario = auth.jwt_user_id_safe() AND is_verified = TRUE;
    
    IF v_id_vendedor IS NULL THEN
        RAISE EXCEPTION 'Vendedor no verificado';
    END IF;
    
    -- Obtener métricas de cache si es reciente
    SELECT 
        total_orders_30d, revenue_30d, pending_orders,
        acceptance_rate_30d, fulfillment_rate_30d,
        average_rating, review_count, negative_reviews_7d
    INTO
        v_total_orders, v_total_revenue, v_pending,
        v_acceptance, v_fulfillment, v_rating,
        v_reviews, v_negative
    FROM seller.dashboard_cache
    WHERE id_vendedor = v_id_vendedor
      AND (now() - last_computed) < (cache_validity_seconds || 'seconds')::INTERVAL;
    
    -- Si no hay cache reciente, calcular
    IF v_total_orders IS NULL THEN
        -- Calcular órdenes últimos 30 días
        SELECT COUNT(*), COALESCE(SUM(total), 0)
        INTO v_total_orders, v_total_revenue
        FROM auth.ordenes
        WHERE id_vendedor = v_id_vendedor
          AND fecha_creacion > now() - INTERVAL '30 days';
        
        -- Órdenes pendientes
        SELECT COUNT(*)
        INTO v_pending
        FROM auth.ordenes
        WHERE id_vendedor = v_id_vendedor AND estado = 'pendiente';
        
        -- Tasa de aceptación
        v_acceptance := 0;
        
        -- Tasa de fulfillment
        v_fulfillment := 0;
        
        -- Rating y reviews
        SELECT average_rating, total_reviews, 0
        INTO v_rating, v_reviews, v_negative
        FROM seller.performance_metrics
        WHERE id_vendedor = v_id_vendedor;
    END IF;
    
    -- Alertas críticas
    SELECT COUNT(*)
    INTO v_critical_alerts
    FROM seller.inventory_alerts
    WHERE id_vendedor = v_id_vendedor AND is_resolved = FALSE AND severity = 'critical';
    
    -- Notificaciones sin leer
    SELECT COUNT(*)
    INTO v_unread
    FROM seller.seller_notifications
    WHERE id_vendedor = v_id_vendedor AND is_read = FALSE;
    
    RETURN QUERY SELECT
        v_total_orders,
        v_total_revenue,
        v_pending,
        v_acceptance,
        v_fulfillment,
        v_rating,
        v_reviews,
        v_negative,
        v_critical_alerts,
        v_unread;
END;
$$;


--
-- Name: rechazar_orden(uuid, character varying, text); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.rechazar_orden(p_order_id uuid, p_rejection_reason character varying, p_rejection_details text DEFAULT NULL::text) RETURNS TABLE(success boolean, message character varying, refund_initiated boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_order_exists BOOLEAN;
    v_order_status VARCHAR;
    v_total_amount NUMERIC;
    v_id_comprador UUID;
    v_rejection_id UUID;
BEGIN
    -- Obtener id_vendedor
    SELECT id INTO v_id_vendedor 
    FROM seller.profiles 
    WHERE id_usuario = auth.jwt_user_id_safe();
    
    IF v_id_vendedor IS NULL THEN
        RETURN QUERY SELECT FALSE, 'Vendedor no verificado'::VARCHAR, FALSE;
        RETURN;
    END IF;
    
    -- Validar orden
    SELECT EXISTS(
        SELECT 1 FROM auth.ordenes 
        WHERE id = p_order_id AND id_vendedor = v_id_vendedor
    ), estado, total, id_comprador
    INTO v_order_exists, v_order_status, v_total_amount, v_id_comprador
    FROM auth.ordenes WHERE id = p_order_id;
    
    IF NOT v_order_exists THEN
        RETURN QUERY SELECT FALSE, 'Orden no encontrada'::VARCHAR, FALSE;
        RETURN;
    END IF;
    
    IF v_order_status != 'pendiente' THEN
        RETURN QUERY SELECT FALSE, 'Orden no está pendiente'::VARCHAR, FALSE;
        RETURN;
    END IF;
    
    -- Actualizar orden a rejected
    UPDATE auth.ordenes
    SET 
        estado = 'cancelada',
        metadata = jsonb_set(
            metadata,
            '{rejected_at}',
            to_jsonb(now()::TEXT)
        ),
        metadata = jsonb_set(
            metadata,
            '{rejection_reason}',
            to_jsonb(p_rejection_reason)
        ),
        fecha_actualizacion = now()
    WHERE id = p_order_id;
    
    -- Crear registro en order_actions
    INSERT INTO seller.order_actions (
        id_orden, id_vendedor, tipo_accion, action_status,
        reason, processed_at
    ) VALUES (
        p_order_id, v_id_vendedor, 'reject', 'completed',
        p_rejection_reason, now()
    );
    
    -- Registrar en rejections
    INSERT INTO seller.order_rejections (
        id_orden, id_vendedor, rejection_reason, rejection_details,
        refund_initiated, refund_amount, refund_status
    ) VALUES (
        p_order_id, v_id_vendedor, p_rejection_reason, p_rejection_details,
        TRUE, v_total_amount, 'initiated'
    ) RETURNING seller.order_rejections.id INTO v_rejection_id;
    
    -- Registrar en timeline
    INSERT INTO seller.order_timeline (
        id_orden, id_vendedor, tipo_evento, event_description,
        previous_status, new_status
    ) VALUES (
        p_order_id, v_id_vendedor, 'order_cancelada',
        'Orden rechazada: ' || p_rejection_reason,
        'pendiente', 'cancelada'
    );
    
    -- Actualizar tasa de aceptación
    UPDATE seller.performance_metrics
    SET 
        acceptance_rate = CASE 
            WHEN (SELECT COUNT(*) FROM auth.ordenes WHERE id_vendedor = v_id_vendedor) > 0
            THEN (SELECT COUNT(*) FROM auth.ordenes WHERE id_vendedor = v_id_vendedor AND estado = 'confirmada')::NUMERIC * 100 / 
                 (SELECT COUNT(*) FROM auth.ordenes WHERE id_vendedor = v_id_vendedor)::NUMERIC
            ELSE 0
        END
    WHERE id_vendedor = v_id_vendedor;
    
    RETURN QUERY SELECT TRUE, 'Orden rechazada. Reembolso iniciado'::VARCHAR, TRUE;
END;
$$;


--
-- Name: registrar_cambio_estado_orden(); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.registrar_cambio_estado_orden() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'seller', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF NEW.estado != OLD.estado THEN
        INSERT INTO seller.order_timeline (
            id_orden, id_vendedor, tipo_evento, event_description,
            previous_status, new_status
        ) SELECT
            NEW.id,
            NEW.id_vendedor,
            'order_' || NEW.estado,
            'Order status changed to ' || NEW.estado,
            OLD.estado,
            NEW.estado;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: registrar_cambio_rendimiento(); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.registrar_cambio_rendimiento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        -- Registrar cambios en average_rating
        IF NEW.average_rating != OLD.average_rating THEN
            NEW.metrics_history := NEW.metrics_history || jsonb_build_object(
                'date', now()::TEXT,
                'old_rating', OLD.average_rating,
                'new_rating', NEW.average_rating,
                'change_type', 'rating_update'
            );
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: registrar_cambios_inventario(); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.registrar_cambios_inventario() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.quantity_available != OLD.quantity_available THEN
            INSERT INTO seller.inventory_audit (
                id_inventario, id_vendedor, tipo_accion, field_name, old_value, new_value
            ) VALUES (
                NEW.id, NEW.id_vendedor, 'stock_adjust', 'quantity_available',
                OLD.quantity_available::VARCHAR, NEW.quantity_available::VARCHAR
            );
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


