--
-- Name: reservar_existencia_orden(uuid); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.reservar_existencia_orden(p_order_id uuid) RETURNS TABLE(success boolean, message character varying, reservations_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_items JSONB;
    v_item RECORD;
    v_item_sku VARCHAR;
    v_item_qty INTEGER;
    v_inventory_id UUID;
    v_reserved_count INTEGER := 0;
BEGIN
    -- Obtener datos de orden
    SELECT id_vendedor, metadata->'items'
    INTO v_id_vendedor, v_items
    FROM auth.ordenes WHERE id = p_order_id;
    
    IF v_id_vendedor IS NULL THEN
        RETURN QUERY SELECT FALSE, 'Order not found'::VARCHAR, 0;
        RETURN;
    END IF;
    
    -- Procesar cada item
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_items) LOOP
        v_item_sku := v_item.value->>'sku';
        v_item_qty := (v_item.value->>'quantity')::INTEGER;
        
        -- Obtener id_inventario
        SELECT id INTO v_inventory_id
        FROM seller.inventory
        WHERE id_vendedor = v_id_vendedor AND product_sku = v_item_sku;
        
        IF v_inventory_id IS NULL THEN
            RETURN QUERY SELECT FALSE, 'Product not found: ' || v_item_sku, v_reserved_count;
            RETURN;
        END IF;
        
        -- Crear reserva
        INSERT INTO seller.order_stock_reservations (
            id_orden, id_inventario, id_vendedor, quantity_reserved, product_sku
        ) VALUES (
            p_order_id, v_inventory_id, v_id_vendedor, v_item_qty, v_item_sku
        );
        
        -- Actualizar inventory (quantity_reserved)
        UPDATE seller.inventory
        SET quantity_reserved = quantity_reserved + v_item_qty
        WHERE id = v_inventory_id;
        
        v_reserved_count := v_reserved_count + 1;
    END LOOP;
    
    RETURN QUERY SELECT TRUE, 'Stock reservado exitosamente'::VARCHAR, v_reserved_count;
END;
$$;


