--
-- Name: validar_existencia_antes_aceptar(); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.validar_existencia_antes_aceptar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'seller', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_inventory_valid boolean;
    v_missing         jsonb;
BEGIN
    IF TG_OP = 'UPDATE'
       AND NEW.estado = 'confirmada'
       AND OLD.estado IS DISTINCT FROM 'confirmada' THEN

        SELECT t.inventory_available, t.missing_items
          INTO v_inventory_valid, v_missing
        FROM seller.validate_order_inventory(NEW.id) AS t;

        IF COALESCE(v_inventory_valid, false) = false THEN
            RAISE EXCEPTION 'STOCK_INSUFICIENTE: la orden % no puede confirmarse. Items faltantes: %',
                NEW.id, COALESCE(v_missing, '[]'::jsonb)
                USING ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION validar_existencia_antes_aceptar(); Type: COMMENT; Schema: seller; Owner: -
--

COMMENT ON FUNCTION seller.validar_existencia_antes_aceptar() IS 'Trigger BEFORE UPDATE sobre auth.ordenes: valida stock real (orden_items + inventario_producto) y bloquea la transición a confirmada si falta inventario.';


--
-- Name: validar_inventario_orden(uuid); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.validar_inventario_orden(p_order_id uuid) RETURNS TABLE(inventory_available boolean, missing_items jsonb, available_items jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'auth', 'seller', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_id_vendedor uuid;
    v_missing     jsonb := '[]'::jsonb;
    v_available   jsonb := '[]'::jsonb;
    v_item        record;
BEGIN
    -- Vendedor de la orden (fuente real: auth.ordenes)
    SELECT o.id_vendedor
      INTO v_id_vendedor
    FROM auth.ordenes o
    WHERE o.id = p_order_id;

    IF v_id_vendedor IS NULL THEN
        RAISE EXCEPTION 'Order not found: %', p_order_id;
    END IF;

    -- Items reales (auth.orden_items) cruzados con inventario real del
    -- vendedor (auth.inventario_producto.stock_disponible, generada).
    FOR v_item IN
        SELECT oi.id_producto,
               oi.cantidad,
               COALESCE(ip.sku, '')  AS sku,
               ip.stock_disponible
        FROM auth.orden_items oi
        LEFT JOIN auth.inventario_producto ip
               ON ip.id_producto = oi.id_producto
              AND ip.id_vendedor = v_id_vendedor
              AND ip.activo = true
        WHERE oi.id_orden = p_order_id
        ORDER BY oi.posicion NULLS LAST
    LOOP
        IF v_item.id_producto IS NULL THEN
            v_missing := v_missing || jsonb_build_object(
                'producto_id', NULL,
                'sku', v_item.sku,
                'required', v_item.cantidad,
                'available', 0,
                'reason', 'Item sin producto asociado'
            );
        ELSIF v_item.stock_disponible IS NULL THEN
            v_missing := v_missing || jsonb_build_object(
                'producto_id', v_item.id_producto,
                'sku', v_item.sku,
                'required', v_item.cantidad,
                'available', 0,
                'reason', 'Producto sin inventario activo del vendedor'
            );
        ELSIF v_item.stock_disponible < v_item.cantidad THEN
            v_missing := v_missing || jsonb_build_object(
                'producto_id', v_item.id_producto,
                'sku', v_item.sku,
                'required', v_item.cantidad,
                'available', v_item.stock_disponible,
                'reason', 'Stock insuficiente'
            );
        ELSE
            v_available := v_available || jsonb_build_object(
                'producto_id', v_item.id_producto,
                'sku', v_item.sku,
                'quantity', v_item.cantidad,
                'available', v_item.stock_disponible
            );
        END IF;
    END LOOP;

    RETURN QUERY SELECT
        (v_missing = '[]'::jsonb),
        CASE WHEN v_missing = '[]'::jsonb THEN NULL::jsonb ELSE v_missing END,
        v_available;
END;
$$;


--
-- Name: FUNCTION validar_inventario_orden(p_order_id uuid); Type: COMMENT; Schema: seller; Owner: -
--

COMMENT ON FUNCTION seller.validar_inventario_orden(p_order_id uuid) IS 'Valida stock de una orden contra schema real: auth.orden_items + auth.inventario_producto (stock_disponible generada) del vendedor de la orden.';


