--
-- Name: verificar_cumplimiento_sla(uuid); Type: FUNCTION; Schema: seller; Owner: -
--

CREATE FUNCTION seller.verificar_cumplimiento_sla(p_order_id uuid) RETURNS TABLE(is_compliant boolean, breaches jsonb, sla_score numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'seller', 'pg_temp'
    AS $$
DECLARE
    v_id_vendedor UUID;
    v_created_at TIMESTAMP WITH TIME ZONE;
    v_accepted_at TIMESTAMP WITH TIME ZONE;
    v_delivered_at TIMESTAMP WITH TIME ZONE;
    v_avg_rating NUMERIC;
    v_breaches JSONB := '[]'::JSONB;
    v_score NUMERIC := 100.00;
    v_response_hours NUMERIC;
    v_fulfillment_hours NUMERIC;
    v_delivery_hours NUMERIC;
BEGIN
    -- Obtener datos de orden
    SELECT 
        id_vendedor, fecha_creacion,
        (metadata->>'accepted_at')::TIMESTAMP WITH TIME ZONE,
        (metadata->>'delivered_at')::TIMESTAMP WITH TIME ZONE
    INTO
        v_id_vendedor, v_created_at, v_accepted_at, v_delivered_at
    FROM auth.ordenes WHERE id = p_order_id;
    
    IF v_id_vendedor IS NULL THEN
        RAISE EXCEPTION 'Order not found';
    END IF;
    
    -- SLA 1: Response Time (24 horas)
    IF v_accepted_at IS NOT NULL THEN
        v_response_hours := EXTRACT(EPOCH FROM (v_accepted_at - v_created_at)) / 3600;
        IF v_response_hours > 24 THEN
            v_breaches := v_breaches || jsonb_build_object(
                'type', 'response_time',
                'expected', '24 horas',
                'actual', ROUND(v_response_hours, 2) || ' horas'
            );
            v_score := v_score - 15;
        END IF;
    END IF;
    
    -- SLA 2: Fulfillment Time (7 días)
    IF v_delivered_at IS NOT NULL AND v_accepted_at IS NOT NULL THEN
        v_fulfillment_hours := EXTRACT(EPOCH FROM (v_delivered_at - v_accepted_at)) / 3600;
        IF v_fulfillment_hours > (7 * 24) THEN
            v_breaches := v_breaches || jsonb_build_object(
                'type', 'fulfillment_time',
                'expected', '7 días',
                'actual', ROUND(v_fulfillment_hours / 24, 1) || ' días'
            );
            v_score := v_score - 25;
        END IF;
    END IF;
    
    -- SLA 3: Overall Delivery Time (14 días)
    IF v_delivered_at IS NOT NULL THEN
        v_delivery_hours := EXTRACT(EPOCH FROM (v_delivered_at - v_created_at)) / 3600;
        IF v_delivery_hours > (14 * 24) THEN
            v_breaches := v_breaches || jsonb_build_object(
                'type', 'delivery_time',
                'expected', '14 días',
                'actual', ROUND(v_delivery_hours / 24, 1) || ' días'
            );
            v_score := v_score - 15;
        END IF;
    END IF;
    
    -- SLA 4: Rating (mínimo 3.5)
    SELECT average_rating INTO v_avg_rating
    FROM seller.performance_metrics WHERE id_vendedor = v_id_vendedor;
    
    IF v_avg_rating < 3.5 THEN
        v_breaches := v_breaches || jsonb_build_object(
            'type', 'rating',
            'expected', '3.5 mínimo',
            'actual', v_avg_rating
        );
        v_score := v_score - 20;
    END IF;
    
    -- Normalizar score
    v_score := GREATEST(0, v_score);
    
    RETURN QUERY SELECT
        (v_breaches = '[]'::JSONB)::BOOLEAN,
        NULLIF(v_breaches, '[]'::JSONB),
        v_score;
END;
$$;


