CREATE TABLE auth.intercambios (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    solicitante_id uuid NOT NULL,
    receptor_id uuid NOT NULL,
    estado text DEFAULT 'propuesta'::text NOT NULL,
    mensaje text,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_intercambios_estado CHECK ((estado = ANY (ARRAY['propuesta'::text, 'aceptada'::text, 'rechazada'::text, 'cancelada'::text, 'completada'::text]))),
    CONSTRAINT chk_intercambios_participantes CHECK ((solicitante_id <> receptor_id))
);


--
-- Name: reportes_estadisticos; Type: MATERIALIZED VIEW; Schema: admin; Owner: -
--

CREATE MATERIALIZED VIEW admin.reportes_estadisticos AS
 SELECT i.id AS intercambio_id,
    i.solicitante_id AS usuario_ofertante_id,
    i.receptor_id AS usuario_receptor_id,
    i.estado AS estado_id,
    i.creado_en AS fecha_propuesta,
    NULL::timestamp with time zone AS fecha_completado,
    NULL::integer AS puntos_otorgados,
    b.id_usuario AS puntos_usuario_id,
    b.saldo AS puntos_saldo,
    b.puntos_acumulados_historico AS total_acumulado,
    NULL::numeric AS total_canjeado,
    b.nivel_lealtad_id AS puntos_nivel,
    a.id AS auditoria_id,
    a.action AS auditoria_operacion,
    a.fecha_creacion AS auditoria_fecha
   FROM ((auth.intercambios i
     LEFT JOIN auth.billetera b ON ((b.id_usuario = i.solicitante_id)))
     LEFT JOIN auth.auditoria a ON (((a.id_objetivo = (i.id)::text) AND (a.target_kind = 'intercambio'::text))))
  WITH NO DATA;


