--
-- Name: mv_daily_metrics; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.mv_daily_metrics AS
 SELECT d.id_fecha,
    to_date((d.id_fecha)::text, 'YYYYMMDD'::text) AS metric_date,
    count(DISTINCT f.id_orden) AS orders_count,
    sum(f.amount_gross) AS total_gmv,
    avg(f.amount_gross) AS avg_order_value,
    count(DISTINCT f.customer_id_fk) AS unique_customers,
    count(DISTINCT f.seller_id_fk) AS active_sellers,
    CURRENT_TIMESTAMP AS _last_updated
   FROM (analytics.hecho_ordenes f
     JOIN analytics.dim_fecha d ON ((f.date_id_fk = d.id_fecha)))
  WHERE ((f.estado)::text = 'completed'::text)
  GROUP BY d.id_fecha
  WITH NO DATA;


--
-- Name: mv_anomaly_detection; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.mv_anomaly_detection AS
 SELECT metric_date,
    total_gmv,
    lag(total_gmv) OVER (ORDER BY metric_date) AS gmv_prev_day,
    avg(total_gmv) OVER (ORDER BY metric_date ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS gmv_7d_avg,
    stddev_pop(total_gmv) OVER (ORDER BY metric_date ROWS BETWEEN 30 PRECEDING AND CURRENT ROW) AS gmv_30d_stddev,
        CASE
            WHEN (((total_gmv - lag(total_gmv) OVER (ORDER BY metric_date)) / NULLIF(lag(total_gmv) OVER (ORDER BY metric_date), (0)::numeric)) > 0.20) THEN 'ANOMALY_UP'::text
            WHEN (((total_gmv - lag(total_gmv) OVER (ORDER BY metric_date)) / NULLIF(lag(total_gmv) OVER (ORDER BY metric_date), (0)::numeric)) < '-0.20'::numeric) THEN 'ANOMALY_DOWN'::text
            ELSE 'NORMAL'::text
        END AS anomaly_flag,
    CURRENT_TIMESTAMP AS _last_updated
   FROM analytics.mv_daily_metrics
  WITH NO DATA;


--
-- Name: mv_category_performance; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.mv_category_performance AS
 SELECT dp.category,
    sum(fo.amount_gross) AS category_gmv,
    count(DISTINCT fo.id_orden) AS category_orders,
    count(DISTINCT fo.customer_id_fk) AS category_unique_customers,
    (count(DISTINCT fi.customer_id_fk) / NULLIF(count(DISTINCT fi.customer_id_fk), 0)) AS category_conversion,
    avg(fo.amount_gross) AS category_aov,
    CURRENT_TIMESTAMP AS _last_updated
   FROM ((analytics.dim_productos_scd dp
     LEFT JOIN analytics.hecho_ordenes fo ON ((dp.id_producto = fo.product_id_fk)))
     LEFT JOIN analytics.hecho_impresiones fi ON ((dp.id_producto = fi.product_id_fk)))
  WHERE (dp.is_active = true)
  GROUP BY dp.category
  WITH NO DATA;


--
-- Name: mv_orders_enriched; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.mv_orders_enriched AS
 SELECT f.id_orden,
    dc.name AS customer_name,
    dc.email AS customer_email,
    ds.name AS seller_name,
    dp.name AS nombre_producto,
    dp.category AS product_category,
    f.amount_gross AS gmv,
    f.estado,
    f.date_id_fk,
    to_date((f.date_id_fk)::text, 'YYYYMMDD'::text) AS order_date,
    row_number() OVER (PARTITION BY f.customer_id_fk ORDER BY f.date_id_fk DESC) AS recency_rank
   FROM (((analytics.hecho_ordenes f
     JOIN analytics.dim_clientes_scd dc ON (((f.customer_id_fk = dc.id_cliente) AND dc.is_active)))
     JOIN analytics.dim_vendedores_scd ds ON (((f.seller_id_fk = ds.id_vendedor) AND ds.is_active)))
     JOIN analytics.dim_productos_scd dp ON (((f.product_id_fk = dp.id_producto) AND dp.is_active)))
  WHERE ((f.estado)::text = 'completed'::text)
  WITH NO DATA;


--
-- Name: mv_seller_rankings; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.mv_seller_rankings AS
 SELECT ds.id_vendedor,
    ds.name AS seller_name,
    sum(fo.amount_gross) AS seller_gmv,
    count(DISTINCT fo.id_orden) AS seller_orders,
    avg(ds.avg_rating) AS seller_rating,
    count(DISTINCT fo.customer_id_fk) AS unique_customers,
    rank() OVER (ORDER BY (sum(fo.amount_gross)) DESC) AS gmv_rank,
    CURRENT_TIMESTAMP AS _last_updated
   FROM (analytics.dim_vendedores_scd ds
     LEFT JOIN analytics.hecho_ordenes fo ON ((ds.id_vendedor = fo.seller_id_fk)))
  WHERE ((ds.is_active = true) AND ((CURRENT_DATE - ds.valid_from) <= 90))
  GROUP BY ds.id_vendedor, ds.name
  WITH NO DATA;


