--
-- Name: v_estadisticas_etiquetas_age; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.v_estadisticas_etiquetas_age AS
 SELECT al.name AS label_name,
        CASE al.kind
            WHEN 'v'::"char" THEN 'vertex'::text
            WHEN 'e'::"char" THEN 'edge'::text
            ELSE 'unknown'::text
        END AS label_kind,
    ( SELECT (pg_class.reltuples)::bigint AS reltuples
           FROM pg_class
          WHERE (pg_class.oid = (al.relation)::oid)) AS approx_count
   FROM (ag_catalog.ag_label al
     JOIN ag_catalog.ag_graph ag ON ((ag.graphid = al.graph)))
  WHERE (ag.name = 'smtp_posix_graph'::name)
  ORDER BY
        CASE al.kind
            WHEN 'v'::"char" THEN 'vertex'::text
            WHEN 'e'::"char" THEN 'edge'::text
            ELSE 'unknown'::text
        END, al.name;


--
-- Name: VIEW v_estadisticas_etiquetas_age; Type: COMMENT; Schema: analytics; Owner: -
--

COMMENT ON VIEW analytics.v_estadisticas_etiquetas_age IS 'Conteos aproximados por etiqueta en smtp_posix_graph. Util para dashboards de Superset.';


