);


--
-- Name: TABLE cola_correo; Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON TABLE auth.cola_correo IS 'T11-SMTP-BRAIN: cola de correo transaccional del stack SMTP POSIX. Consumida por mail-worker.service (worker Python); estado: pendiente|enviado|fallido|cancelado; trigger trg_mail_queue_updated_at mantiene fecha_actualizacion; RPC auth.enqueue_mail (SECURITY DEFINER) encola via PostgREST.';


--
-- Name: COLUMN cola_correo.estado; Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON COLUMN auth.cola_correo.estado IS 'T11: ciclo de vida del correo: pendiente -> enviado|fallido (worker), cancelado (operacion).';


