   FROM auth.cola_correo;


--
-- Name: vw_mail_queue_metrics; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_mail_queue_metrics AS
 SELECT estado AS status,
    (date_trunc('day'::text, fecha_creacion))::date AS bucket_day,
    count(*) AS total_messages,
    count(*) FILTER (WHERE (estado = 'enviado'::text)) AS total_sent,
    count(*) FILTER (WHERE (estado = ANY (ARRAY['fallido'::text, 'error'::text]))) AS total_failed,
    min(fecha_creacion) AS first_event_at,
    max(fecha_actualizacion) AS last_event_at
   FROM auth.mail_queue m
  GROUP BY estado, ((date_trunc('day'::text, fecha_creacion))::date);


--
-- Name: vw_mail_queue_recent; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_mail_queue_recent AS
 SELECT id,
    id_usuario AS user_id,
    recipient,
    subject,
    estado AS status,
    fecha_creacion AS created_at,
    fecha_actualizacion AS updated_at
   FROM auth.mail_queue m
  ORDER BY id DESC
 LIMIT 1000;


