-- Name: nodos_grafo_consulta; Type: TABLE; Schema: auth; Owner: -
--

CREATE TABLE auth.nodos_grafo_consulta (
    id bigint NOT NULL,
    node_type text NOT NULL,
    id_usuario uuid,
    mail_id integer,
    use_case_id integer,
    owner_user_id uuid,
    label text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT nodos_grafo_consulta_node_type_check CHECK ((node_type = ANY (ARRAY['user'::text, 'mail'::text, 'use_case'::text]))),
    CONSTRAINT nodos_grafo_consulta_single_ref CHECK ((((
CASE
    WHEN (id_usuario IS NOT NULL) THEN 1
    ELSE 0
END +
CASE
    WHEN (mail_id IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN (use_case_id IS NOT NULL) THEN 1
    ELSE 0
END) = 1))
);


