CREATE VIEW analytics.vw_use_case_edge_metrics AS
 SELECT uc.slug,
    uc.name,
    e.edge_type,
    count(*) AS total_edges,
    min(e.created_at) AS first_event_at,
    max(e.updated_at) AS last_event_at
   FROM ((auth.query_graph_edges e
     JOIN auth.query_graph_nodes n ON ((n.id = e.from_node_id)))
     LEFT JOIN auth.use_cases uc ON ((uc.id = n.use_case_id)))
  GROUP BY uc.slug, uc.name, e.edge_type;


