);


--
-- Name: alertas_criticas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.alertas_criticas (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    id_vendedor uuid NOT NULL,
    tipo_alerta text NOT NULL,
    campo_afectado text,
    valor_anterior text,
    valor_nuevo text,
    estado text DEFAULT 'PENDIENTE'::text NOT NULL,
    visible boolean DEFAULT true NOT NULL,
    nivel_riesgo text DEFAULT 'ALTO'::text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    fecha_eliminacion timestamp with time zone,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    fecha_actualizacion timestamp with time zone DEFAULT now() NOT NULL,
    resuelto_por uuid,
    resuelto_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT alertas_criticas_estado_check CHECK ((estado = ANY (ARRAY['PENDIENTE'::text, 'PROCESADA'::text, 'REVERTIDA'::text, 'IGNORADA'::text]))),
    CONSTRAINT alertas_criticas_nivel_riesgo_check CHECK ((nivel_riesgo = ANY (ARRAY['CRITICO'::text, 'ALTO'::text, 'MEDIO'::text, 'BAJO'::text]))),
    CONSTRAINT alertas_criticas_tipo_alerta_check CHECK ((tipo_alerta = ANY (ARRAY['CAMBIO_EMAIL'::text, 'CAMBIO_CUENTA_BANCARIA'::text, 'MULTIPLES_REVERSIONES'::text, 'PATRON_FRAUDE'::text, 'WEBHOOK_EXTERNO'::text])))
);


--
-- Name: mv_riesgo_historico; Type: MATERIALIZED VIEW; Schema: app; Owner: -
--

CREATE MATERIALIZED VIEW app.mv_riesgo_historico AS
 SELECT date_trunc('day'::text, fecha_creacion) AS dia,
    nivel_riesgo,
    (count(*))::integer AS total_alertas,
    (count(*) FILTER (WHERE (estado = 'RESUELTA'::text)))::integer AS resueltas,
    (count(*) FILTER (WHERE (estado = 'PENDIENTE'::text)))::integer AS pendientes,
    round(avg(
        CASE nivel_riesgo
            WHEN 'ALTO'::text THEN 3
            WHEN 'MEDIO'::text THEN 2
            WHEN 'BAJO'::text THEN 1
            ELSE 0
        END), 2) AS score_promedio
   FROM public.alertas_criticas a
  WHERE ((fecha_creacion > (now() - '365 days'::interval)) AND (is_active = true))
  GROUP BY (date_trunc('day'::text, fecha_creacion)), nivel_riesgo
  WITH NO DATA;


