CREATE TABLE app.registro_eliminacion (
    delete_log_id uuid DEFAULT gen_random_uuid() NOT NULL,
    log_seq bigint NOT NULL,
    target_table text NOT NULL,
    id_objetivo uuid NOT NULL,
    deleted_by uuid NOT NULL,
