--
-- Name: admin_alertas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.admin_alertas (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tipo_alerta_id integer NOT NULL,
    severidad character varying(20) DEFAULT 'media'::character varying NOT NULL,
    titulo character varying(200) NOT NULL,
    descripcion text NOT NULL,
    usuario_afectado_id uuid,
    referencia_id uuid,
    referencia_tipo character varying(50),
    estado character varying(30) DEFAULT 'abierta'::character varying NOT NULL,
    prioridad integer DEFAULT 0,
    fecha_resolucion timestamp with time zone,
    resuelta_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    fuente text,
    oculto_en_dash boolean DEFAULT false NOT NULL,
    tipo text,
    payload jsonb,
    nivel_riesgo text,
    score_riesgo text,
    creado_por text,
    id_entidad text,
    tipo_entidad text,
    hidden_at timestamp with time zone,
    hidden_by uuid,
    hidden_reason text,
    evento_fuente_id uuid,
    CONSTRAINT admin_alertas_estado_check CHECK (((estado)::text = ANY (ARRAY[('abierta'::character varying)::text, ('en_revision'::character varying)::text, ('resuelta'::character varying)::text, ('descartada'::character varying)::text, ('escalada'::character varying)::text]))),
    CONSTRAINT admin_alertas_severidad_check CHECK (((severidad)::text = ANY (ARRAY[('baja'::character varying)::text, ('media'::character varying)::text, ('alta'::character varying)::text, ('critica'::character varying)::text])))
);


--
-- Name: TABLE admin_alertas; Type: COMMENT; Schema: public; Owner: -
