COMMENT ON TABLE public.admin_alertas IS 'Alertas administrativas generadas automáticamente por triggers o manualmente por admins (v3.12)';


--
-- Name: COLUMN admin_alertas.tipo_alerta_id; Type: COMMENT; Schema: public; Owner: -
