COMMENT ON COLUMN public.admin_alertas.tipo_alerta_id IS 'FK a tipos_alerta - categoría de la alerta';


--
-- Name: COLUMN admin_alertas.severidad; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.admin_alertas.severidad IS 'Nivel: baja, media, alta, critica';


--
-- Name: COLUMN admin_alertas.usuario_afectado_id; Type: COMMENT; Schema: public; Owner: -
