COMMENT ON COLUMN public.admin_alertas.referencia_tipo IS 'Tipo del objeto referenciado: intercambio, articulo, rating, user_risk_score';


--
-- Name: COLUMN admin_alertas.estado; Type: COMMENT; Schema: public; Owner: -
