COMMENT ON COLUMN public.admin_alertas.estado IS 'Ciclo de vida: abierta → en_revision → resuelta/descartada/escalada';


--
-- Name: v_admin_top_anomalies; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_admin_top_anomalies AS
