    tipo AS tipo_alerta,
    descripcion,
    nivel_riesgo,
    score_riesgo,
    estado,
    id_entidad,
    tipo_entidad,
    created_at AS fecha_creacion
   FROM public.admin_alertas a
  WHERE ((COALESCE(oculto_en_dash, false) = false) AND ((estado)::text = ANY (ARRAY['abierta'::text, 'en_revision'::text])));


