    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    fecha_eliminacion timestamp with time zone
);


--
-- Name: v_admin_visual_state; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_admin_visual_state AS
 SELECT 'user'::text AS tipo_entidad,
    (u.id)::text AS id_entidad,
        CASE
            WHEN (u.fecha_eliminacion IS NOT NULL) THEN 'suspendido'::text
            WHEN (COALESCE(u.activo, true) = false) THEN 'suspendido'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.admin_alertas a
              WHERE ((a.id_entidad = (u.id)::text) AND ((a.estado)::text = ANY (ARRAY['abierta'::text, 'en_revision'::text])) AND (a.nivel_riesgo = ANY (ARRAY['alto'::text, 'critico'::text])) AND (COALESCE(a.oculto_en_dash, false) = false)))) THEN 'en_revision'::text
            ELSE 'activo'::text
        END AS visual_state
   FROM auth.users u
UNION ALL
 SELECT 'alert'::text AS tipo_entidad,
    (a.id)::text AS id_entidad,
        CASE
            WHEN ((a.estado)::text = ANY (ARRAY['resuelta'::text, 'descartada'::text])) THEN 'suspendido'::text
            WHEN ((a.estado)::text = 'en_revision'::text) THEN 'en_revision'::text
            WHEN (((a.estado)::text = 'abierta'::text) AND (a.nivel_riesgo = ANY (ARRAY['alto'::text, 'critico'::text]))) THEN 'en_revision'::text
            WHEN ((a.estado)::text = 'abierta'::text) THEN 'activo'::text
            ELSE 'activo'::text
        END AS visual_state
   FROM public.admin_alertas a
  WHERE (COALESCE(a.oculto_en_dash, false) = false)
UNION ALL
 SELECT 'case'::text AS tipo_entidad,
    (c.id)::text AS id_entidad,
        CASE
            WHEN (c.fecha_eliminacion IS NOT NULL) THEN 'suspendido'::text
            WHEN (c.resolution_action = ANY (ARRAY['SOFT_DELETE'::text, 'SUSPEND'::text])) THEN 'suspendido'::text
            WHEN (c.resolution_action = ANY (ARRAY['REVIEW'::text, 'ESCALATE'::text])) THEN 'en_revision'::text
            ELSE 'activo'::text
        END AS visual_state
   FROM public.admin_resoluciones_caso c;


--
-- Name: v_admin_work_queue_projection; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_admin_work_queue_projection AS
 SELECT work_item_id,
    tipo_item,
    ref_table,
    ref_id,
    priority,
    estado,
    title,
    summary,
    vencimiento_sla_en,
        CASE
            WHEN ((vencimiento_sla_en < now()) AND (estado <> ALL (ARRAY['resolved'::text, 'dismissed'::text]))) THEN true
            ELSE false
        END AS is_overdue,
    id_admin_asignado,
    assigned_at,
    fecha_creacion
   FROM app.items_trabajo wi;


--
-- Name: v_case_decisions_projection; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_case_decisions_projection AS
 SELECT decision_id,
