--
-- Name: v_categorias_audit; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_categorias_audit AS
 SELECT c.id AS id_categoria,
    c.nombre,
    c.activo,
    c.fecha_eliminacion,
    c.deleted_by,
    c.deletion_reason,
    a.tipo_cambio,
    a.id_actor,
    a.fecha_creacion AS evento_ts,
    a.hash_evento
   FROM (auth.categorias c
     LEFT JOIN app.h_categorias_auditoria a ON ((a.id_categoria = c.id)));


--
-- Name: v_entity_summary_projection; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_entity_summary_projection AS
 SELECT u.id AS id_entidad,
    'user'::text AS tipo_entidad,
    ("left"(u.email, 2) || '***@***'::text) AS email_masked,
    u.role,
    u.fecha_creacion,
    u.fecha_eliminacion,
    COALESCE(f.score_value, (0)::numeric) AS fraud_score,
    COALESCE(f.estado_flag, 'none'::text) AS fraud_flag,
    count(DISTINCT d.id_disputa) AS dispute_count,
    count(DISTINCT cm.moderation_id) AS moderation_count
   FROM (((auth.users u
     LEFT JOIN app.puntajes_fraude f ON (((f.id_usuario = u.id) AND (f.fecha_expiracion > now()))))
     LEFT JOIN app.disputas d ON (((d.id_iniciador = u.id) AND (d.fecha_eliminacion IS NULL))))
     LEFT JOIN app.moderacion_contenido cm ON ((cm.id_autor = u.id)))
  WHERE (u.fecha_eliminacion IS NULL)
  GROUP BY u.id, u.email, u.role, u.fecha_creacion, u.fecha_eliminacion, f.score_value, f.estado_flag;


--
-- Name: v_forensic_timeline_projection; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_forensic_timeline_projection AS
 SELECT al.audit_id AS event_id,
    'admin_action'::text AS event_source,
    al.tipo_accion AS tipo_evento,
    al.id_recurso_objetivo AS id_entidad,
    NULL::uuid AS related_entity_id,
    al.ejecutado_en AS event_time,
    al.id_admin AS id_actor,
    to_jsonb(al.action_details) AS event_data,
    al.audit_hash AS integrity_hash
   FROM app.bitacora_admin al
UNION ALL
 SELECT cd.decision_id AS event_id,
    'case_decision'::text AS event_source,
    cd.decision AS tipo_evento,
    cd.id_caso AS id_entidad,
    NULL::uuid AS related_entity_id,
    cd.fecha_creacion AS event_time,
    cd.id_admin AS id_actor,
    jsonb_build_object('case_type', cd.case_type, 'decision', cd.decision, 'rationale_summary', ("left"(cd.rationale, 80) || '…'::text)) AS event_data,
    cd.decision_hash AS integrity_hash
   FROM app.decisiones_caso cd
UNION ALL
 SELECT sdl.delete_log_id AS event_id,
    'soft_delete'::text AS event_source,
    'record_deleted'::text AS tipo_evento,
    sdl.id_objetivo AS id_entidad,
    NULL::uuid AS related_entity_id,
    sdl.fecha_eliminacion AS event_time,
    sdl.deleted_by AS id_actor,
    jsonb_build_object('target_table', sdl.target_table, 'reason', sdl.reason) AS event_data,
    sdl.log_hash AS integrity_hash
   FROM app.registro_eliminacion sdl
UNION ALL
 SELECT d.id_disputa AS event_id,
    'dispute_state'::text AS event_source,
    ('dispute_'::text || d.estado) AS tipo_evento,
    d.id_disputa AS id_entidad,
    d.id_orden AS related_entity_id,
    COALESCE(d.resolved_at, d.fecha_creacion) AS event_time,
    COALESCE(d.id_admin_asignado, d.id_iniciador) AS id_actor,
    jsonb_build_object('dispute_reason', d.dispute_reason, 'severity', d.severity, 'resolution_type', d.resolution_type) AS event_data,
    NULL::text AS integrity_hash
   FROM app.disputas d;


--
-- Name: v_monitor_seq_scans; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_monitor_seq_scans AS
 SELECT schemaname,
    relname,
    seq_scan,
    seq_tup_read,
    idx_scan,
        CASE
            WHEN ((seq_scan + idx_scan) > 0) THEN round((((seq_scan)::numeric / ((seq_scan + idx_scan))::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS seq_scan_percentage
   FROM pg_stat_user_tables
  WHERE ((schemaname = ANY (ARRAY['public'::name, 'app'::name])) AND (seq_scan > 1000))
  ORDER BY
        CASE
            WHEN ((seq_scan + idx_scan) > 0) THEN round((((seq_scan)::numeric / ((seq_scan + idx_scan))::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END DESC;


--
-- Name: ordenes; Type: TABLE; Schema: auth; Owner: -
--

CREATE TABLE auth.ordenes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_month date,
    region_code text,
    id_comprador uuid NOT NULL,
    id_vendedor uuid,
    id_producto uuid,
    quantity integer DEFAULT 1 NOT NULL,
    estado text DEFAULT 'CONFIRMED'::text NOT NULL,
    total numeric(12,2) NOT NULL,
    unit_price_snapshot numeric(12,2),
    delivery_verification_hash text,
    location_delivery public.geometry(Point,4326),
    expiracion_coordinacion_en timestamp with time zone,
    vendedor_listo_en timestamp with time zone,
    fecha_confirmacion timestamp with time zone,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    fecha_actualizacion timestamp with time zone DEFAULT now() NOT NULL,
    fecha_eliminacion timestamp with time zone,
    id_orden uuid,
    metadata jsonb,
    moneda text,
    CONSTRAINT ordenes_estado_check CHECK ((estado = ANY (ARRAY['pendiente'::text, 'confirmada'::text, 'cancelada'::text, 'completada'::text, 'entregado'::text, 'proposed'::text, 'assigned'::text, 'payment_confirmed'::text, 'preparing'::text, 'in_delivery'::text, 'completed'::text, 'cancelled'::text, 'CREATED'::text, 'CONFIRMED'::text, 'IN_PROGRESS'::text, 'DELIVERED'::text, 'CANCELLED'::text]))),
    CONSTRAINT ordenes_quantity_check CHECK ((quantity > 0)),
    CONSTRAINT ordenes_total_check CHECK ((total >= (0)::numeric))
);

ALTER TABLE ONLY auth.ordenes FORCE ROW LEVEL SECURITY;


--
-- Name: instantaneas_geo_orden; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.instantaneas_geo_orden (
    id_orden uuid NOT NULL,
    order_month date NOT NULL,
    region_code text NOT NULL,
    buyer_location public.geometry(Point,4326),
    seller_location public.geometry(Point,4326),
    delivery_location public.geometry(Point,4326),
    delivery_zone_label text,
    buyer_to_seller_meters numeric,
    buyer_to_delivery_meters numeric,
    seller_to_delivery_meters numeric,
    fecha_creacion timestamp with time zone DEFAULT now(),
    fecha_captura timestamp with time zone,
    snapshot_location text
);

ALTER TABLE ONLY public.instantaneas_geo_orden FORCE ROW LEVEL SECURITY;


--
-- Name: v_risk_heatmap_projection; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_risk_heatmap_projection AS
 SELECT public.st_x(public.st_snaptogrid((ogs.snapshot_location)::public.geometry, (0.01)::double precision)) AS zone_lng,
    public.st_y(public.st_snaptogrid((ogs.snapshot_location)::public.geometry, (0.01)::double precision)) AS zone_lat,
    count(DISTINCT o.id_comprador) AS incident_count,
    round(avg(COALESCE(f.score_value, (0)::numeric)), 2) AS avg_risk_score,
    max(f.estado_flag) AS max_flag_status
   FROM ((public.instantaneas_geo_orden ogs
     JOIN auth.ordenes o ON ((o.id_orden = ogs.id_orden)))
     LEFT JOIN app.puntajes_fraude f ON (((f.id_usuario = o.id_comprador) AND (f.fecha_expiracion > now()))))
  WHERE (ogs.fecha_captura > (now() - '30 days'::interval))
  GROUP BY (public.st_x(public.st_snaptogrid((ogs.snapshot_location)::public.geometry, (0.01)::double precision))), (public.st_y(public.st_snaptogrid((ogs.snapshot_location)::public.geometry, (0.01)::double precision)))
 HAVING (count(DISTINCT o.id_comprador) >= 3);


--
-- Name: v_seller_operational_capacity_v4; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_seller_operational_capacity_v4 AS
 WITH seller_ctx AS (
         SELECT DISTINCT p.id_vendedor
           FROM auth.productos p
          WHERE (p.activo = true)
        )
 SELECT s.id_vendedor,
    (((ctx.context_data -> 'rules'::text) ->> 'max_concurrent_orders'::text))::integer AS max_profile_capacity,
    (((ctx.context_data -> 'rules'::text) ->> 'remaining_capacity'::text))::integer AS remaining_capacity,
    ((((ctx.context_data -> 'rules'::text) ->> 'remaining_capacity'::text))::integer > 0) AS is_eligible_for_matching
   FROM (seller_ctx s
     CROSS JOIN LATERAL ( SELECT app.get_seller_sales_context_v2() AS context_data) ctx);


