--
-- Name: v_technical_anomalies_device; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_technical_anomalies_device AS
 SELECT id_dispositivo,
    count(DISTINCT id_usuario) AS user_count,
    min(started_at) AS first_seen,
    max(started_at) AS last_seen,
    array_agg(DISTINCT (id_usuario)::text ORDER BY (id_usuario)::text) AS user_ids
   FROM auth.sesiones_telemetria_usuario
  WHERE (id_dispositivo IS NOT NULL)
  GROUP BY id_dispositivo
 HAVING (count(DISTINCT id_usuario) > 1);


--
-- Name: v_technical_anomalies_hardware; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_technical_anomalies_hardware AS
 SELECT hardware_id,
    count(DISTINCT id_usuario) AS user_count,
    array_agg(DISTINCT (id_usuario)::text ORDER BY (id_usuario)::text) AS user_ids
   FROM auth.sesiones_telemetria_usuario
  WHERE (hardware_id IS NOT NULL)
  GROUP BY hardware_id
 HAVING (count(DISTINCT id_usuario) > 1);


--
-- Name: v_technical_anomalies_ip; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_technical_anomalies_ip AS
 SELECT ip_address,
    count(DISTINCT id_usuario) AS user_count,
    min(started_at) AS first_seen,
    max(started_at) AS last_seen,
    array_agg(DISTINCT (id_usuario)::text ORDER BY (id_usuario)::text) AS user_ids
   FROM auth.sesiones_telemetria_usuario
  WHERE (ip_address IS NOT NULL)
  GROUP BY ip_address
 HAVING (count(DISTINCT id_usuario) > 1);


