--

CREATE TABLE auth.membresias_vendedor (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    id_vendedor uuid NOT NULL,
    id_plan uuid NOT NULL,
    estado text DEFAULT 'activo'::text NOT NULL,
    fecha_inicio timestamp with time zone DEFAULT now() NOT NULL,
    fecha_expiracion timestamp with time zone,
    auto_renovar boolean DEFAULT true NOT NULL,
    ciclo_pago text DEFAULT 'mensual'::text NOT NULL,
    descuento_anual_pct numeric(5,2) DEFAULT 0 NOT NULL,
    es_trial boolean DEFAULT false NOT NULL,
    trial_expiracion timestamp with time zone,
    score_confianza numeric(5,2) DEFAULT 100 NOT NULL,
    override_flags jsonb DEFAULT '{}'::jsonb NOT NULL,
    fecha_eliminacion timestamp with time zone,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    fecha_modificacion timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT membresias_vendedor_ciclo_pago_check CHECK ((ciclo_pago = ANY (ARRAY['mensual'::text, 'anual'::text]))),
    CONSTRAINT membresias_vendedor_descuento_anual_pct_check CHECK (((descuento_anual_pct >= (0)::numeric) AND (descuento_anual_pct <= (100)::numeric))),
    CONSTRAINT membresias_vendedor_estado_check CHECK ((estado = ANY (ARRAY['activo'::text, 'grace_period'::text, 'expirada'::text, 'cancelada'::text, 'suspendida'::text]))),
    CONSTRAINT membresias_vendedor_score_confianza_check CHECK (((score_confianza >= (0)::numeric) AND (score_confianza <= (100)::numeric)))
);


--
-- Name: transiciones_estado_entidad; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.transiciones_estado_entidad (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entity_kind text NOT NULL,
    id_entidad text NOT NULL,
    from_state text,
    to_state text NOT NULL,
