    tipo_entidad text,
    changed_by text
);


--
-- Name: v_user_impact_projection; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_user_impact_projection AS
 SELECT id AS id_usuario,
    role,
    activo AS is_active,
    fecha_eliminacion,
    ( SELECT count(*) AS count
           FROM public.admin_alertas a
          WHERE ((a.id_entidad = (u.id)::text) AND ((a.estado)::text = 'abierta'::text) AND (COALESCE(a.oculto_en_dash, false) = false))) AS open_alerts,
    ( SELECT count(*) AS count
           FROM auth.membresias_vendedor m
          WHERE ((m.id_vendedor = u.id) AND (m.estado = ANY (ARRAY['activo'::text, 'grace_period'::text])) AND (m.fecha_eliminacion IS NULL))) AS active_memberships,
    ( SELECT count(*) AS count
           FROM public.transiciones_estado_entidad t
          WHERE ((t.tipo_entidad = 'user'::text) AND (t.id_entidad = (u.id)::text))) AS transitions_count
   FROM auth.users u;


--
-- Name: v_users_admin_projection; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.v_users_admin_projection AS
 SELECT id,
    role,
    activo AS is_active,
    fecha_eliminacion,
    deleted_by,
    deleted_reason,
    created_by,
        CASE
            WHEN (fecha_eliminacion IS NOT NULL) THEN 'suspendido'::text
            WHEN (COALESCE(activo, true) = false) THEN 'suspendido'::text
            ELSE 'activo'::text
        END AS visual_state
   FROM auth.users u;


