--
-- Name: recent_config_changes; Type: VIEW; Schema: audit; Owner: -
--

CREATE VIEW audit.recent_config_changes AS
 SELECT c.key,
    (c.old_value ->> 'value_num'::text) AS old_value,
    (c.new_value ->> 'value_num'::text) AS new_value,
    u.email AS changed_by,
    c.reason,
    c.fecha_cambio
   FROM (audit.config_seguridad_audit c
     LEFT JOIN auth.users u ON ((c.id_actor = u.id)))
  WHERE (c.fecha_cambio > (now() - '30 days'::interval))
  ORDER BY c.fecha_cambio DESC;


