--
-- Name: vw_cert_busqueda_geo; Type: VIEW; Schema: audit; Owner: -
--

CREATE VIEW audit.vw_cert_busqueda_geo AS
 SELECT id,
    id_actor,
    payload,
    fecha_creacion,
    encode(public.digest((((id)::text || (payload)::text) || (fecha_creacion)::text), 'sha256'::text), 'hex'::text) AS certificado_sha256
   FROM audit.audit_log
  WHERE (tipo_evento = 'CU-C-010.BUSQUEDA_GEO'::text);


