    id_actor,
    payload,
    fecha_creacion,
    encode(public.digest(((((id)::text || tipo_evento) || (fecha_creacion)::text) || (payload)::text), 'sha256'::text), 'hex'::text) AS certificado_sha256
   FROM audit.audit_log;


--
-- Name: vw_cert_sync_sql_age; Type: VIEW; Schema: audit; Owner: -
