    dispositivo_id text,
    checkin_en timestamp with time zone,
    fecha_creacion timestamp with time zone,
    geom public.geometry(Point,4326),
    is_active boolean,
    is_merchant_spot boolean,
    es_dato_prueba boolean,
    CONSTRAINT chk_ubicaciones_fotos_array CHECK ((jsonb_typeof(fotos) = 'array'::text)),
    CONSTRAINT chk_ubicaciones_horarios_json CHECK (((horarios IS NULL) OR (jsonb_typeof(horarios) = 'object'::text))),
    CONSTRAINT chk_ubicaciones_nombre_len CHECK (((nombre IS NULL) OR ((char_length(nombre) >= 1) AND (char_length(nombre) <= 100)))),
    CONSTRAINT chk_ubicaciones_tipo CHECK ((tipo = ANY (ARRAY['punto_venta'::text, 'almacen'::text, 'punto_entrega'::text, 'oficina'::text, 'otro'::text])))
);

ALTER TABLE ONLY auth.ubicaciones FORCE ROW LEVEL SECURITY;


--
-- Name: mv_seller_reach_summary; Type: MATERIALIZED VIEW; Schema: auth; Owner: -
--

CREATE MATERIALIZED VIEW auth.mv_seller_reach_summary AS
 SELECT u_seller.id_usuario AS id_vendedor,
    count(DISTINCT u_buyer.id_usuario) AS buyers_in_1km,
    count(DISTINCT u_buyer.id_usuario) FILTER (WHERE public.st_dwithin((u_buyer.punto)::public.geography, (u_seller.punto)::public.geography, (500)::double precision)) AS buyers_in_500m,
    now() AS refrescado_en
   FROM (((auth.ubicaciones u_seller
     JOIN auth.users usr_seller ON (((usr_seller.id = u_seller.id_usuario) AND (usr_seller.role = 'seller'::text) AND (u_seller.estado = 'activo'::text))))
     LEFT JOIN auth.ubicaciones u_buyer ON (((u_buyer.estado = 'activo'::text) AND (u_buyer.id_usuario <> u_seller.id_usuario) AND public.st_dwithin((u_buyer.punto)::public.geography, (u_seller.punto)::public.geography, (1000)::double precision))))
     JOIN auth.users usr_buyer ON (((usr_buyer.id = u_buyer.id_usuario) AND (usr_buyer.role = 'buyer'::text))))
  WHERE (u_buyer.fecha_actualizacion >= (now() - '24:00:00'::interval))
  GROUP BY u_seller.id_usuario, u_seller.punto
  WITH NO DATA;


