    fecha_modificacion timestamp with time zone,
    verificada boolean DEFAULT false NOT NULL,
    respuesta_publica text,
    respuesta_fecha timestamp with time zone,
    respuesta_modificada_at timestamp with time zone,
    sentimiento text,
    sentimiento_score numeric(5,4),
    sentimiento_modelo text,
    moderada boolean DEFAULT false NOT NULL,
    moderada_at timestamp with time zone,
    moderada_por uuid,
    moderacion_motivo text,
    metadata jsonb,
    activo boolean,
    id_intercambio uuid,
    CONSTRAINT resenas_sentimiento_check CHECK (((sentimiento IS NULL) OR (sentimiento = ANY (ARRAY['positivo'::text, 'neutro'::text, 'negativo'::text, 'mixto'::text])))),
    CONSTRAINT resenas_sentimiento_score_check CHECK (((sentimiento_score IS NULL) OR ((sentimiento_score >= ('-1'::integer)::numeric) AND (sentimiento_score <= (1)::numeric))))
);


--
-- Name: mv_vendedores_activos; Type: MATERIALIZED VIEW; Schema: auth; Owner: -
--

CREATE MATERIALIZED VIEW auth.mv_vendedores_activos AS
 SELECT u.id AS id_vendedor,
    ppv.slug_publico,
    ppv.nombre_marca,
    ppv.url_logo,
    ppv.disponible_ahora,
    ppv.ultima_disponibilidad,
    ppv.score_reputacion,
    ub.id AS id_ubicacion,
    ub.nombre AS ubicacion_nombre,
    ub.latitud,
    ub.longitud,
    ub.punto,
    ub.tipo AS tipo_ubicacion,
    ub.horarios,
    COALESCE(stats.total_resenas, (0)::bigint) AS total_resenas,
    COALESCE(stats.calificacion_prom, (0)::numeric) AS calificacion_promedio
   FROM (((auth.users u
     JOIN auth.perfiles_publicos_vendedor ppv ON ((ppv.id_vendedor = u.id)))
     JOIN auth.ubicaciones ub ON ((ub.id_usuario = u.id)))
     LEFT JOIN ( SELECT resenas.id_vendedor,
            count(*) AS total_resenas,
            round(avg(resenas.calificacion), 2) AS calificacion_prom
           FROM auth.resenas
          GROUP BY resenas.id_vendedor) stats ON ((stats.id_vendedor = u.id)))
  WHERE ((u.role = 'seller'::text) AND (u.is_verified = true) AND (u.activo = true) AND (u.fecha_eliminacion IS NULL) AND (ppv.activo = true) AND (ppv.disponible_ahora = true) AND (ub.estado = 'activo'::text) AND (ub.punto IS NOT NULL))
  WITH NO DATA;


