    descuento_monto numeric(14,4),
    total_linea numeric(14,4),
    detalle_jsonb jsonb,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nombre_producto_snapshot text,
    categoria_snapshot text
);


--
-- Name: mv_ventas_vendedor; Type: MATERIALIZED VIEW; Schema: auth; Owner: -
--

CREATE MATERIALIZED VIEW auth.mv_ventas_vendedor AS
 SELECT o.id_vendedor,
    (date_trunc('day'::text, o.fecha_creacion))::date AS fecha_venta,
    count(DISTINCT o.id) AS total_ordenes,
    sum(o.total) AS ingresos_brutos,
    sum(COALESCE(oi_agg.total_descuentos, (0)::numeric)) AS total_descuentos,
    (sum(o.total) - sum(COALESCE(oi_agg.total_descuentos, (0)::numeric))) AS ingresos_netos,
    count(DISTINCT o.id_comprador) AS compradores_unicos,
    sum(COALESCE((oi_agg.unidades_vendidas)::numeric, (0)::numeric)) AS unidades_vendidas,
    round(avg(o.total), 2) AS ticket_promedio
   FROM (auth.ordenes o
     LEFT JOIN LATERAL ( SELECT sum(oi.descuento_monto) AS total_descuentos,
            sum(oi.cantidad) AS unidades_vendidas
           FROM auth.orden_elementos oi
          WHERE (oi.id_orden = o.id)) oi_agg ON (true))
  WHERE (o.estado = 'confirmada'::text)
  GROUP BY o.id_vendedor, ((date_trunc('day'::text, o.fecha_creacion))::date)
  WITH NO DATA;


