--
-- Name: v_active_market_buyers; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_active_market_buyers AS
 SELECT u.id AS id_comprador,
    u.role,
    ub.punto AS geom,
    ub.latitud,
    ub.longitud,
    COALESCE((ub.fecha_actualizacion)::timestamp with time zone, ub.fecha_creacion) AS presence_ts,
    (now() - COALESCE((ub.fecha_actualizacion)::timestamp with time zone, ub.fecha_creacion)) AS presence_age
   FROM (auth.users u
     JOIN auth.ubicaciones ub ON ((ub.id_usuario = u.id)))
  WHERE ((u.role = 'buyer'::text) AND (ub.estado = 'activo'::text) AND (COALESCE((ub.fecha_actualizacion)::timestamp with time zone, ub.fecha_creacion) >= (now() - '00:15:00'::interval)));


