    ppv.is_disponible,
    ppv.visibility_radius_meters,
    ppv.spot_label,
    ub.punto AS geom,
    ub.latitud,
    ub.longitud,
    ub.estado,
    COALESCE((ub.fecha_actualizacion)::timestamp with time zone, ub.fecha_creacion) AS presence_ts
   FROM ((auth.users u
     JOIN auth.ubicaciones ub ON ((ub.id_usuario = u.id)))
     JOIN auth.perfiles_publicos_vendedor ppv ON ((ppv.id_vendedor = u.id)))
  WHERE ((u.role = 'seller'::text) AND (ub.estado = 'activo'::text) AND (ppv.is_disponible = true) AND (ppv.activo = true) AND (EXISTS ( SELECT 1
           FROM auth.productos p
          WHERE ((p.id_vendedor = u.id) AND (p.activo = true)))));


