--
-- Name: v_inventario_vendedor_resumen; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_inventario_vendedor_resumen AS
 SELECT ip.id_vendedor,
    ip.id_producto,
    p.nombre AS producto_nombre,
    p.activo AS producto_activo,
    ip.sku,
    ip.total_stock,
    ip.stock_reservado,
    ip.stock_disponible,
    ip.umbral_alerta,
    ip.permite_backorder,
    ppv.activo AS perfil_activo,
    ppv.disponible_ahora,
    ppv.inventario_congelado,
    ppv.plan_vendedor,
        CASE
            WHEN (ip.stock_disponible <= 0) THEN 'sin_stock'::text
            WHEN (ip.stock_disponible <= ip.umbral_alerta) THEN 'stock_bajo'::text
            ELSE 'normal'::text
        END AS estado_stock,
    count(iu.id) FILTER (WHERE (iu.activo AND (iu.stock > 0))) AS ubicaciones_con_stock,
    count(ai.id) FILTER (WHERE ((ai.leida = false) AND (ai.resuelta = false))) AS alertas_pendientes,
    ip.fecha_modificacion AS actualizado_en
   FROM ((((auth.inventario_producto ip
     JOIN auth.productos p ON ((p.id = ip.id_producto)))
     JOIN auth.perfiles_publicos_vendedor ppv ON ((ppv.id_vendedor = ip.id_vendedor)))
     LEFT JOIN auth.inventario_ubicacion iu ON ((iu.id_producto = ip.id_producto)))
     LEFT JOIN auth.alertas_inventario ai ON ((ai.id_producto = ip.id_producto)))
  GROUP BY ip.id_vendedor, ip.id_producto, p.nombre, p.activo, ip.sku, ip.total_stock, ip.stock_reservado, ip.stock_disponible, ip.umbral_alerta, ip.permite_backorder, ppv.activo, ppv.disponible_ahora, ppv.inventario_congelado, ppv.plan_vendedor, ip.fecha_modificacion;


