--
-- Name: perfiles; Type: TABLE; Schema: seller; Owner: -
--

CREATE TABLE seller.perfiles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    id_usuario uuid NOT NULL,
    nombre_negocio character varying(255) NOT NULL,
    business_category character varying(100) NOT NULL,
    description text,
    email character varying(255) NOT NULL,
    phone character varying(20),
    address jsonb DEFAULT '{}'::jsonb,
    is_verified boolean DEFAULT false,
    verification_date timestamp with time zone,
    business_license character varying(100),
    tax_id character varying(50),
    return_policy_days integer DEFAULT 30,
    max_refund_percentage numeric(5,2) DEFAULT 100.00,
    fecha_creacion timestamp with time zone DEFAULT now(),
    fecha_actualizacion timestamp with time zone DEFAULT now(),
    CONSTRAINT chk_categoria CHECK (((business_category)::text = ANY ((ARRAY['electronics'::character varying, 'clothing'::character varying, 'food'::character varying, 'services'::character varying, 'other'::character varying])::text[]))),
    CONSTRAINT chk_politica_devolucion CHECK ((return_policy_days >= 0)),
    CONSTRAINT chk_reembolso CHECK (((max_refund_percentage >= (0)::numeric) AND (max_refund_percentage <= (100)::numeric)))
);


--
-- Name: v_metricas_reputacion_vendedor; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_metricas_reputacion_vendedor AS
 SELECT u.id AS id_vendedor,
    COALESCE(p.nombre_negocio, (u.username)::character varying) AS slug_publico,
    COALESCE(r.promedio_calificacion, 0.0) AS calificacion_promedio,
    COALESCE(r.total_resenas, (0)::bigint) AS total_resenas,
    COALESCE(o.ordenes_confirmadas, (0)::bigint) AS ordenes_confirmadas,
    COALESCE(e.envios_entregados, (0)::bigint) AS envios_entregados,
    u.fecha_actualizacion AS fecha_modificacion
   FROM ((((auth.usuarios u
     LEFT JOIN seller.perfiles p ON ((p.id_usuario = u.id)))
     LEFT JOIN ( SELECT resenas.id_vendedor,
            avg(resenas.calificacion) AS promedio_calificacion,
            count(*) AS total_resenas
           FROM auth.resenas
          WHERE (resenas.calificacion IS NOT NULL)
          GROUP BY resenas.id_vendedor) r ON ((r.id_vendedor = u.id)))
     LEFT JOIN ( SELECT ordenes.id_vendedor,
            count(*) AS ordenes_confirmadas
           FROM auth.ordenes
          WHERE (ordenes.estado = 'confirmada'::text)
          GROUP BY ordenes.id_vendedor) o ON ((o.id_vendedor = u.id)))
     LEFT JOIN ( SELECT envios.id_vendedor,
            count(*) AS envios_entregados
           FROM auth.envios
          WHERE (envios.estado = 'entregado'::text)
          GROUP BY envios.id_vendedor) e ON ((e.id_vendedor = u.id)))
  WHERE (u.role = 'seller'::text);


