--
-- Name: v_mis_ordenes; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_mis_ordenes AS
 SELECT id,
    estado,
    total,
    moneda,
    metadata,
    fecha_creacion,
    fecha_actualizacion AS fecha_modificacion,
    id_comprador,
    id_vendedor,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('id_producto', oi.id_producto, 'cantidad', oi.cantidad, 'precio_unitario', oi.precio_unitario, 'total_linea', oi.total_linea, 'nombre_producto', oi.nombre_producto_snapshot) ORDER BY oi.posicion) AS jsonb_agg
           FROM auth.orden_items oi
          WHERE (oi.id_orden = o.id)), '[]'::jsonb) AS items_jsonb
   FROM auth.ordenes o
  WHERE (id_comprador = auth.current_jwt_user_id());


--
-- Name: v_mis_pagos; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_mis_pagos AS
 SELECT pt.id,
    pt.id_orden,
    o.estado AS estado_orden,
    pt.id_vendedor,
    uv.nombre_visible AS nombre_vendedor,
    uv.email AS email_vendedor,
    pt.estado AS estado_pago,
    pt.metodo,
    pt.monto,
    o.moneda,
    o.fecha_creacion AS fecha_orden,
    pt.referencia_externa
   FROM ((auth.transacciones_pago pt
     LEFT JOIN auth.ordenes o ON ((o.id = pt.id_orden)))
     LEFT JOIN auth.users uv ON ((uv.id = pt.id_vendedor)))
  WHERE (pt.id_comprador = auth.fn_current_user_id());


--
-- Name: VIEW v_mis_pagos; Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON VIEW auth.v_mis_pagos IS 'cu-dev-013: pagos realizados por el comprador autenticado (JWT), filtrada por owner. Base: auth.payment_transactions + auth.ordenes + auth.users. Lote L6 triage27.';


--
-- Name: v_mis_productos; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_mis_productos AS
 SELECT p.id AS producto_id,
    p.id_vendedor,
    p.id_categoria,
    p.id_subcategoria,
    p.nombre,
    p.descripcion,
    p.precio,
    p.condicion,
    p.descuento_porcentaje,
    p.puntos_recompensa,
    p.estado_moderacion,
    p.activo,
    p.fecha_eliminacion AS deleted_at,
    c.nombre AS categoria,
    s.nombre AS subcategoria,
    inv.stock_disponible,
    p.fecha_creacion,
    p.fecha_actualizacion AS fecha_modificacion
   FROM (((auth.productos p
     LEFT JOIN auth.categorias c ON ((c.id = p.id_categoria)))
     LEFT JOIN auth.subcategorias s ON ((s.id = p.id_subcategoria)))
     LEFT JOIN auth.inventario_producto inv ON ((inv.id_producto = p.id)))
  WHERE ((p.id_vendedor = auth.fn_current_user_id()) AND (p.fecha_eliminacion IS NULL));


--
-- Name: v_my_membership_policy; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_my_membership_policy AS
 SELECT u.id AS id_usuario,
    u.role,
    u.default_tier_code AS membership_tier,
    u.membership_expires_at,
    mpc.nombre_visible,
    mpc.features,
    mpc.admin_parameters,
    mpc.retention_days,
    uma.inicia_en AS membership_started_at,
    uma.fecha_expiracion AS membership_expires_detail
   FROM ((auth.users u
     JOIN auth.catalogo_politicas_membresia mpc ON ((mpc.tier = u.default_tier_code)))
     LEFT JOIN auth.asignaciones_membresia_usuario uma ON (((uma.id_usuario = u.id) AND (uma.estado = 'active'::text))))
  WHERE ((u.id = auth.fn_current_user_id()) AND (u.fecha_eliminacion IS NULL) AND (u.lifecycle_state = 'active'::text) AND (mpc.active = true));


--
-- Name: v_ordenes_por_recibir; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_ordenes_por_recibir AS
 SELECT id,
    estado,
    total,
    moneda,
    metadata,
    fecha_creacion,
    fecha_actualizacion AS fecha_modificacion,
    id_comprador,
    id_vendedor,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('id_producto', oi.id_producto, 'cantidad', oi.cantidad, 'nombre_producto', oi.nombre_producto_snapshot) ORDER BY oi.posicion) AS jsonb_agg
           FROM auth.orden_items oi
          WHERE (oi.id_orden = o.id)), '[]'::jsonb) AS items_jsonb
   FROM auth.ordenes o
  WHERE ((id_comprador = auth.current_jwt_user_id()) AND (estado = ANY (ARRAY['pendiente'::text, 'confirmada'::text, 'en_preparacion'::text])));


--
-- Name: v_pagos_vendedor; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_pagos_vendedor AS
 SELECT pt.id,
    pt.id_orden,
    o.estado AS estado_orden,
    pt.id_comprador,
    uc.nombre_visible AS nombre_comprador,
    uc.email AS email_comprador,
    pt.estado AS estado_pago,
    pt.metodo,
    pt.monto,
    o.moneda,
    o.fecha_creacion AS fecha_orden,
    pt.referencia_externa
   FROM ((auth.transacciones_pago pt
     LEFT JOIN auth.ordenes o ON ((o.id = pt.id_orden)))
     LEFT JOIN auth.users uc ON ((uc.id = pt.id_comprador)))
  WHERE (pt.id_vendedor = auth.fn_current_user_id());


--
-- Name: VIEW v_pagos_vendedor; Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON VIEW auth.v_pagos_vendedor IS 'cu-dev-013: pagos recibidos por el vendedor autenticado (JWT), filtrada por owner. Base: auth.payment_transactions + auth.ordenes + auth.users. Lote L6 triage27.';


--
-- Name: v_perfil_comprador; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_perfil_comprador AS
 SELECT u.id,
    u.email,
    u.username,
    u.role,
    u.is_verified,
    b.saldo,
    b.moneda,
    b.fecha_modificacion AS billetera_desde,
    b.fecha_modificacion AS billetera_actualizado,
    u.fecha_creacion AS usuario_desde
   FROM (auth.users u
     LEFT JOIN auth.billetera b ON ((u.id = b.id_usuario)))
  WHERE ((u.role = 'buyer'::text) AND ((u.id = auth.current_jwt_user_id()) OR (auth.current_jwt_role() = 'db_admin'::text)));


--
-- Name: v_perfiles_publicos_vendedor; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_perfiles_publicos_vendedor AS
 SELECT u.id AS id_vendedor,
    p.nombre_negocio,
    p.business_category,
    p.description AS biografia,
    p.is_verified AS activo,
    p.fecha_creacion,
    p.fecha_actualizacion AS fecha_modificacion,
    COALESCE(r.promedio_calificacion, 0.0) AS calificacion_promedio,
    COALESCE(r.total_resenas, (0)::bigint) AS total_resenas,
    COALESCE(o.ordenes_confirmadas, (0)::bigint) AS ordenes_confirmadas,
    COALESCE(e.envios_entregados, (0)::bigint) AS envios_entregados
   FROM ((((auth.usuarios u
     JOIN seller.perfiles p ON ((p.id_usuario = u.id)))
     LEFT JOIN ( SELECT resenas.id_vendedor,
            avg(resenas.calificacion) AS promedio_calificacion,
            count(*) AS total_resenas
           FROM auth.resenas
          WHERE (resenas.calificacion IS NOT NULL)
          GROUP BY resenas.id_vendedor) r ON ((r.id_vendedor = u.id)))
     LEFT JOIN ( SELECT ordenes.id_vendedor,
            count(*) AS ordenes_confirmadas
           FROM auth.ordenes
          WHERE (ordenes.estado = 'confirmada'::text)
          GROUP BY ordenes.id_vendedor) o ON ((o.id_vendedor = u.id)))
     LEFT JOIN ( SELECT envios.id_vendedor,
            count(*) AS envios_entregados
           FROM auth.envios
          WHERE (envios.estado = 'entregado'::text)
          GROUP BY envios.id_vendedor) e ON ((e.id_vendedor = u.id)))
  WHERE (u.role = 'seller'::text);


--
-- Name: v_rentabilidad_resumen; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_rentabilidad_resumen AS
 SELECT cp.id_vendedor,
    p.nombre AS producto,
    cp.costo_unitario,
    p.precio AS precio_venta,
    round((p.precio - cp.costo_unitario), 2) AS margen_unitario,
    round((((p.precio - cp.costo_unitario) / NULLIF(p.precio, (0)::numeric)) * (100)::numeric), 2) AS margen_pct,
    cp.vigente_desde,
    cp.vigente_hasta
   FROM (auth.costos_producto cp
     JOIN auth.productos p ON ((p.id = cp.id_producto)))
  WHERE (p.activo = true);


--
-- Name: v_resenas_producto; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_resenas_producto AS
 SELECT id_producto,
    round(avg(calificacion), 2) AS promedio_calificacion,
    count(*) AS total_resenas
   FROM auth.resenas r
  WHERE (calificacion IS NOT NULL)
  GROUP BY id_producto;


--
-- Name: v_resenas_vendedor; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_resenas_vendedor AS
 SELECT id_vendedor,
    round(avg(calificacion), 2) AS promedio_calificacion,
    count(*) AS total_resenas,
    jsonb_agg(jsonb_build_object('id', id, 'calificacion', calificacion, 'comentario', comentario, 'id_comprador', id_comprador, 'fecha_creacion', fecha_creacion, 'verificada', verificada) ORDER BY fecha_creacion DESC) AS resenas_jsonb
   FROM auth.resenas r
  WHERE (calificacion IS NOT NULL)
  GROUP BY id_vendedor;


--
-- Name: v_sellers_discoverable; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_sellers_discoverable AS
 SELECT ppv.id AS perfil_id,
    ppv.id_vendedor,
    ppv.slug_publico,
    ppv.nombre_marca,
    ppv.url_logo,
    ppv.score_reputacion,
    ppv.total_resenas,
    ppv.disponible_ahora,
    u.latitud,
    u.longitud,
    u.punto,
    u.id AS id_ubicacion
   FROM ((auth.perfiles_publicos_vendedor ppv
     JOIN auth.users usr ON ((usr.id = ppv.id_vendedor)))
     JOIN auth.ubicaciones u ON ((u.id_usuario = ppv.id_vendedor)))
  WHERE ((usr.activo = true) AND (usr.role = 'seller'::text) AND (usr.is_verified = true) AND (usr.fecha_eliminacion IS NULL) AND (ppv.activo = true) AND (ppv.disponible_ahora = true) AND (u.estado = 'activo'::text));


--
-- Name: v_series_ventas_vendedor; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_series_ventas_vendedor AS
 SELECT id_vendedor,
    fecha_venta,
    ingresos_netos,
    total_ordenes,
    lag(ingresos_netos, 7) OVER (PARTITION BY id_vendedor ORDER BY fecha_venta) AS ingresos_hace_7d,
    avg(ingresos_netos) OVER (PARTITION BY id_vendedor ORDER BY fecha_venta ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS media_movil_7d,
    stddev(ingresos_netos) OVER (PARTITION BY id_vendedor ORDER BY fecha_venta ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS stddev_30d
   FROM auth.mv_ventas_vendedor mv;


--
-- Name: v_superset_ventas_dashboard; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_superset_ventas_dashboard AS
 SELECT id_vendedor,
    fecha_venta,
    total_ordenes,
    ingresos_brutos,
    ingresos_netos,
    total_descuentos,
    compradores_unicos,
    unidades_vendidas,
    ticket_promedio,
    EXTRACT(year FROM fecha_venta) AS anio,
    EXTRACT(month FROM fecha_venta) AS mes,
    EXTRACT(week FROM fecha_venta) AS semana,
    to_char((fecha_venta)::timestamp with time zone, 'YYYY-MM'::text) AS anio_mes
   FROM auth.mv_ventas_vendedor mv;


--
-- Name: v_user_effective_lifecycle_policy; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_user_effective_lifecycle_policy AS
 SELECT u.id AS id_usuario,
    u.role,
    auth.resolve_effective_tier(u.id, now()) AS effective_tier_code,
    p.retention_days,
    p.anonymize_after_days,
    p.allow_physical_purge,
    p.require_manual_review,
    p.require_identity_verification,
    p.auto_revoke_sessions,
    p.admin_flags,
    p.frontend_flags,
    p.verification_rules,
    COALESCE(o.verification_required, false) AS override_verification_required,
    COALESCE(o.manual_review_required, false) AS override_manual_review_required,
    COALESCE(o.purge_blocked, false) AS override_purge_blocked,
    o.notes AS override_notes
   FROM ((auth.users u
     JOIN auth.politicas_niveles_servicio p ON (((p.role = u.role) AND (p.tier_code = auth.resolve_effective_tier(u.id, now())) AND (p.is_active = true))))
     LEFT JOIN auth.anulaciones_admin_ciclo_vida o ON ((o.id_usuario = u.id)));


--
-- Name: v_vendedores; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_vendedores AS
 SELECT u.id AS id_vendedor,
    u.nombre_visible,
    u.lifecycle_state,
    u.activo AS usuario_activo,
    u.is_verified AS usuario_verificado,
    u.estado_verificacion,
    u.default_tier_code,
    u.fecha_creacion,
    u.fecha_eliminacion,
    ppv.nombre_marca,
    ppv.plan_vendedor,
    ppv.activo AS perfil_publico_activo,
    ppv.is_disponible,
    ppv.disponible_ahora,
    ppv.verificado AS perfil_verificado,
    ppv.score_reputacion,
    sp.nombre_negocio,
    sp.business_category,
    sp.is_verified AS negocio_verificado
   FROM ((auth.users u
     LEFT JOIN auth.perfiles_publicos_vendedor ppv ON ((ppv.id_vendedor = u.id)))
     LEFT JOIN seller.perfiles sp ON ((sp.id_usuario = u.id)))
  WHERE (u.role = 'seller'::text);


--
-- Name: VIEW v_vendedores; Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON VIEW auth.v_vendedores IS 'cu-dev-008: registro de ciclo de vida de vendedores (rol seller). Base: auth.users + auth.perfiles_publicos_vendedor + seller.profiles. Lote L6 triage27.';


--
-- Name: v_vendedores_activos; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_vendedores_activos AS
 SELECT count(*) FILTER (WHERE (role = 'seller'::text)) AS total_vendedores,
    count(*) FILTER (WHERE ((role = 'seller'::text) AND (activo = true))) AS vendedores_activos,
    count(*) FILTER (WHERE ((role = 'seller'::text) AND (estado_administrativo = 'suspendido'::text))) AS vendedores_suspendidos
   FROM auth.usuarios u;


--
-- Name: v_webhook_queue_monitor; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.v_webhook_queue_monitor AS
 SELECT estado,
    evento,
    count(*) AS total,
    min(fecha_creacion) AS mas_antiguo,
    max(fecha_creacion) AS mas_reciente,
    sum(intentos) AS intentos_totales,
    count(*) FILTER (WHERE ((intentos >= max_intentos) AND (estado = 'error'::text))) AS bloqueados
   FROM auth.cola_webhook
  GROUP BY estado, evento
  ORDER BY estado, evento;


--
-- Name: vw_actividad_auth; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.vw_actividad_auth AS
 SELECT id,
    email,
    exitoso,
    ip_origen,
    fecha
   FROM auth.intentos_acceso la
  ORDER BY fecha DESC;


--
-- Name: vw_consola_riesgo; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.vw_consola_riesgo AS
 SELECT u.id AS usuario_id,
    u.username,
    u.email,
    COALESCE(la.intentos_fallidos_24h, (0)::bigint) AS intentos_fallidos_24h,
        CASE
            WHEN (COALESCE(la.intentos_fallidos_24h, (0)::bigint) >= 5) THEN 'alto'::text
            WHEN (COALESCE(la.intentos_fallidos_24h, (0)::bigint) >= 3) THEN 'medio'::text
            ELSE 'bajo'::text
        END AS nivel_riesgo,
    max(la.ultimo_intento) AS ultimo_intento
   FROM (auth.usuarios u
     LEFT JOIN ( SELECT login_attempts.email,
            count(*) FILTER (WHERE (NOT login_attempts.exitoso)) AS intentos_fallidos_24h,
            max(login_attempts.fecha) AS ultimo_intento
           FROM auth.login_attempts
          WHERE (login_attempts.fecha >= (now() - '24:00:00'::interval))
          GROUP BY login_attempts.email) la ON ((la.email = u.email)))
  GROUP BY u.id, u.username, u.email, la.intentos_fallidos_24h;


--
-- Name: vw_disputas_resumen; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.vw_disputas_resumen AS
 SELECT id,
    tipo_alerta_id,
    severidad,
    titulo,
    descripcion,
    usuario_afectado_id,
    estado,
    prioridad,
    created_at,
    updated_at
   FROM public.admin_alertas a
  ORDER BY prioridad DESC, created_at DESC;


--
-- Name: vw_graph_access_grants; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.vw_graph_access_grants AS
 SELECT g.id,
    g.grantee_id,
    gu.email AS grantee_email,
    gu.username AS grantee_username,
    gu.role AS grantee_role,
    g.granted_by,
    gbu.username AS granted_by_username,
    g.granted_at
   FROM ((auth.graph_access_grants g
     LEFT JOIN auth.usuarios gu ON ((gu.id = g.grantee_id)))
     LEFT JOIN auth.usuarios gbu ON ((gbu.id = g.granted_by)));


--
-- Name: vw_historial_eliminaciones_detalle; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.vw_historial_eliminaciones_detalle AS
 SELECT id,
    tabla_origen,
    registro_id,
    motivo,
    archivado_en,
    retencion_hasta,
    (retencion_hasta < now()) AS vencida,
    (EXTRACT(day FROM (retencion_hasta - now())))::integer AS dias_restantes,
    purgado,
    purgado_en
   FROM auth.historial_eliminaciones
  ORDER BY archivado_en DESC;


--
-- Name: VIEW vw_historial_eliminaciones_detalle; Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON VIEW auth.vw_historial_eliminaciones_detalle IS 'Vista detallada del histórico. vencida=true indica que ya puede purgarse. datos_json NO se expone aquí por privacidad; consultar la tabla directamente con db_admin.';


--
-- Name: vw_historial_pendiente_purga; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.vw_historial_pendiente_purga AS
 SELECT tabla_origen,
    count(*) AS total_registros,
    min(archivado_en) AS mas_antiguo,
    max(archivado_en) AS mas_reciente,
    count(*) FILTER (WHERE (retencion_hasta < now())) AS elegibles_para_purga,
    min(retencion_hasta) FILTER (WHERE (NOT purgado)) AS proxima_purga_en
   FROM auth.historial_eliminaciones
  WHERE (NOT purgado)
  GROUP BY tabla_origen
  ORDER BY (count(*) FILTER (WHERE (retencion_hasta < now()))) DESC, (count(*)) DESC;


--
-- Name: VIEW vw_historial_pendiente_purga; Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON VIEW auth.vw_historial_pendiente_purga IS 'Resumen por tabla de los registros en histórico. elegibles_para_purga = registros cuya retención ya venció y pueden ser purgados.';


--
-- Name: vw_kpis_ejecutivos; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.vw_kpis_ejecutivos AS
 SELECT ( SELECT count(*) AS count
           FROM auth.usuarios) AS usuarios_registrados,
    ( SELECT count(*) AS count
           FROM auth.usuarios
          WHERE usuarios.is_verified) AS usuarios_verificados,
    ( SELECT count(*) AS count
           FROM auth.productos
          WHERE ((productos.activo IS TRUE) AND (productos.fecha_eliminacion IS NULL))) AS productos_activos,
    ( SELECT count(*) AS count
           FROM auth.ordenes) AS ordenes_total,
    ( SELECT count(*) AS count
           FROM auth.ordenes
          WHERE (ordenes.estado = 'completada'::text)) AS ordenes_completadas,
    ( SELECT count(*) AS count
           FROM auth.intercambios) AS intercambios_total,
    ( SELECT count(*) AS count
           FROM auth.intercambios
          WHERE (intercambios.estado = 'completado'::text)) AS intercambios_completados,
    ( SELECT COALESCE(sum(billetera.saldo), (0)::numeric) AS "coalesce"
           FROM auth.billetera) AS saldo_total_wallets,
    ( SELECT count(*) AS count
           FROM auth.billetera
          WHERE billetera.activo) AS wallets_activos,
    now() AS snapshot_at;


--
-- Name: vw_performance_vendedor; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.vw_performance_vendedor AS
 SELECT u.id AS usuario_id,
    u.username,
    COALESCE(pc.total_productos, (0)::bigint) AS total_productos,
    COALESCE(r.total_resenas, (0)::bigint) AS resenas_recibidas,
    COALESCE(r.promedio_calificacion, 0.0) AS calificacion_promedio
   FROM ((auth.usuarios u
     LEFT JOIN ( SELECT productos.id_vendedor,
            count(*) AS total_productos
           FROM auth.productos
          WHERE (productos.fecha_eliminacion IS NULL)
          GROUP BY productos.id_vendedor) pc ON ((pc.id_vendedor = u.id)))
     LEFT JOIN ( SELECT resenas.id_vendedor,
            count(*) AS total_resenas,
            round(avg(resenas.calificacion), 2) AS promedio_calificacion
           FROM auth.resenas
          WHERE (resenas.calificacion IS NOT NULL)
          GROUP BY resenas.id_vendedor) r ON ((r.id_vendedor = u.id)))
  WHERE (u.role = 'seller'::text);


--
-- Name: vw_salud_financiera; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.vw_salud_financiera AS
 SELECT ( SELECT count(*) AS count
           FROM auth.ordenes
          WHERE (ordenes.estado = 'completada'::text)) AS ordenes_completadas,
    ( SELECT count(*) AS count
           FROM auth.ordenes
          WHERE (ordenes.estado = 'cancelada'::text)) AS ordenes_canceladas,
    ( SELECT count(*) AS count
           FROM auth.ordenes
          WHERE (ordenes.estado = 'pendiente'::text)) AS ordenes_pendientes,
    ( SELECT count(*) AS count
           FROM auth.billetera
          WHERE billetera.activo) AS wallets_activos,
    ( SELECT COALESCE(sum(billetera.saldo), (0)::numeric) AS "coalesce"
           FROM auth.billetera
          WHERE billetera.activo) AS saldo_wallets_activos,
    ( SELECT count(*) AS count
           FROM auth.ordenes
          WHERE (ordenes.fecha_confirmacion IS NOT NULL)) AS volumen_facturado,
    now() AS snapshot_at;


--
-- Name: wallet_snapshots; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.wallet_snapshots AS
 SELECT id,
    id_usuario,
    snapshot_date,
    puntos_disponibles,
    puntos_en_escrow,
    puntos_totales,
    total_movimientos,
    total_creditos,
    total_debitos,
    created_at
   FROM auth.instantaneas_billetera;


--
-- Name: webhook_queue; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.webhook_queue AS
 SELECT id,
    evento,
    payload,
    estado,
    intentos,
    max_intentos,
    error_detalle,
    fecha_creacion,
    procesado_at,
    proximo_intento,
    creado_en
   FROM auth.cola_webhook;


--
-- Name: ws_sessions; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.ws_sessions AS
 SELECT id,
    id_usuario,
    channel_id,
    dispositivo_id,
    ip_origen,
    user_agent,
    conectado_at,
    ultimo_ping_at,
    activa,
    metadata
   FROM auth.sesiones_ws;


--
-- Name: dispute_appeals; Type: TABLE; Schema: disputes; Owner: -
--

CREATE TABLE disputes.dispute_appeals (
    appeal_id uuid DEFAULT gen_random_uuid() NOT NULL,
    id_disputa uuid NOT NULL,
    appeal_number integer NOT NULL,
    appealed_by uuid NOT NULL,
    appeal_reason text NOT NULL,
