--
-- Name: disputes; Type: TABLE; Schema: disputes; Owner: -
--

CREATE TABLE disputes.disputes (
    id_disputa uuid DEFAULT gen_random_uuid() NOT NULL,
    id_orden uuid NOT NULL,
    id_comprador uuid NOT NULL,
    id_vendedor uuid NOT NULL,
    estado disputes.disputes_status_enum DEFAULT 'pending'::disputes.disputes_status_enum,
    category character varying(64) NOT NULL,
    reason text NOT NULL,
    priority disputes.disputes_priority_enum DEFAULT 'medium'::disputes.disputes_priority_enum,
    amount_usd numeric(12,2) NOT NULL,
    requested_compensation character varying(255),
    fecha_creacion timestamp without time zone DEFAULT now(),
    fecha_expiracion timestamp without time zone NOT NULL,
    resuelto_en timestamp without time zone,
    appeal_deadline timestamp without time zone,
    assigned_to uuid,
    assigned_at timestamp without time zone,
    resolution_description text,
    final_decision character varying(32),
    appeal_count integer DEFAULT 0,
    is_escalated boolean DEFAULT false,
    escalation_reason character varying(255),
    buyer_responded_at timestamp without time zone,
    seller_responded_at timestamp without time zone,
    created_by uuid,
    resolved_by uuid,
    metadata jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT disputes_amount_usd_check CHECK ((amount_usd > (0)::numeric)),
    CONSTRAINT disputes_appeal_count_check CHECK ((appeal_count <= 2)),
    CONSTRAINT disputes_check CHECK ((id_comprador <> id_vendedor)),
    CONSTRAINT disputes_check1 CHECK (((assigned_to IS NOT NULL) OR (estado = ANY (ARRAY['pending'::disputes.disputes_status_enum, 'in_review'::disputes.disputes_status_enum])))),
    CONSTRAINT disputes_check2 CHECK (((resuelto_en IS NOT NULL) OR (estado <> 'resolved'::disputes.disputes_status_enum))),
    CONSTRAINT disputes_check3 CHECK (((final_decision IS NOT NULL) OR (estado <> 'resolved'::disputes.disputes_status_enum))),
    CONSTRAINT disputes_final_decision_check CHECK (((final_decision)::text = ANY ((ARRAY['buyer_wins'::character varying, 'seller_wins'::character varying, 'partial_refund'::character varying, 'no_action'::character varying])::text[])))
);


