    id_caso uuid DEFAULT gen_random_uuid() NOT NULL,
    case_number character varying(32) NOT NULL,
    id_usuario uuid NOT NULL,
    case_type character varying(64) NOT NULL,
    estado fraud.fraud_cases_status_enum DEFAULT 'open'::fraud.fraud_cases_status_enum,
    risk_score integer,
    confidence_level numeric(3,2),
    description text NOT NULL,
    investigation_notes text,
    fecha_creacion timestamp without time zone DEFAULT now(),
    created_by uuid NOT NULL,
    investigated_by uuid,
    investigated_at timestamp without time zone,
    resuelto_en timestamp without time zone,
    resolved_by uuid,
    resolution_action character varying(64),
    related_orders jsonb DEFAULT '[]'::jsonb,
    related_disputes jsonb DEFAULT '[]'::jsonb,
    is_escalated_to_authorities boolean DEFAULT false,
    authority_report_id character varying(255),
    authority_report_date timestamp without time zone,
    ledger_hash character varying(64),
    metadata jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT fraud_cases_check CHECK (((investigated_at IS NULL) OR (estado = ANY (ARRAY['confirmed'::fraud.fraud_cases_status_enum, 'false_positive'::fraud.fraud_cases_status_enum, 'resolved'::fraud.fraud_cases_status_enum, 'escalated_to_authorities'::fraud.fraud_cases_status_enum])))),
    CONSTRAINT fraud_cases_check1 CHECK (((resuelto_en IS NOT NULL) OR (estado <> 'resolved'::fraud.fraud_cases_status_enum))),
    CONSTRAINT fraud_cases_confidence_level_check CHECK (((confidence_level >= (0)::numeric) AND (confidence_level <= (1)::numeric))),
    CONSTRAINT fraud_cases_risk_score_check CHECK (((risk_score >= 0) AND (risk_score <= 100)))
);


--
-- Name: cases_public; Type: VIEW; Schema: fraud; Owner: -
--

CREATE VIEW fraud.cases_public AS
 SELECT id_caso,
    case_number,
    encode(public.digest((id_usuario)::text, 'sha256'::text), 'hex'::text) AS user_hash,
    case_type,
    estado,
    fecha_creacion
   FROM fraud.fraud_cases;


