    git_commit text DEFAULT ''::text,
    actor text DEFAULT 'desconocido'::text,
    search_vector tsvector GENERATED ALWAYS AS (to_tsvector('spanish'::regconfig, ((((COALESCE(codigo, ''::text) || ' '::text) || COALESCE(titulo, ''::text)) || ' '::text) || COALESCE(tags_json, ''::text)))) STORED
