--
-- Name: vw_cu_summary; Type: VIEW; Schema: kambalache_cu; Owner: -
--

CREATE VIEW kambalache_cu.vw_cu_summary AS
 SELECT o.codigo,
    o.titulo,
    o.actor,
    COALESCE(f.funciones, (0)::bigint) AS total_funciones,
    COALESCE(e.entidades, (0)::bigint) AS total_entidades,
    COALESCE(r.reglas, (0)::bigint) AS total_reglas,
    COALESCE(a.rutas_api, (0)::bigint) AS total_rutas_api,
    COALESCE(rls.rls, (0)::bigint) AS total_rls,
        CASE
            WHEN ((COALESCE(f.funciones, (0)::bigint) > 0) AND (COALESCE(r.reglas, (0)::bigint) > 0) AND (COALESCE(a.rutas_api, (0)::bigint) > 0) AND (COALESCE(rls.rls, (0)::bigint) > 0)) THEN 'CERRADO'::text
            ELSE 'CON_BRECHAS'::text
        END AS estado_ciclo
   FROM (((((kambalache_cu.okf_index o
     LEFT JOIN ( SELECT idx_functions.cu_code,
            count(*) AS funciones
           FROM kambalache_cu.idx_functions
          GROUP BY idx_functions.cu_code) f ON ((o.codigo = f.cu_code)))
     LEFT JOIN ( SELECT idx_db_entities.cu_code,
            count(*) AS entidades
           FROM kambalache_cu.idx_db_entities
          GROUP BY idx_db_entities.cu_code) e ON ((o.codigo = e.cu_code)))
     LEFT JOIN ( SELECT idx_business_rules.cu_code,
            count(*) AS reglas
           FROM kambalache_cu.idx_business_rules
          GROUP BY idx_business_rules.cu_code) r ON ((o.codigo = r.cu_code)))
     LEFT JOIN ( SELECT idx_api_routes.cu_code,
            count(*) AS rutas_api
           FROM kambalache_cu.idx_api_routes
          GROUP BY idx_api_routes.cu_code) a ON ((o.codigo = a.cu_code)))
     LEFT JOIN ( SELECT rls_restrictions.cu_code,
            count(*) AS rls
           FROM kambalache_cu.rls_restrictions
          GROUP BY rls_restrictions.cu_code) rls ON ((o.codigo = rls.cu_code)))
  WHERE (o.actor <> 'softdelete'::text);


