-- Name: content_audit_trail; Type: TABLE; Schema: moderation; Owner: -
--

CREATE TABLE moderation.content_audit_trail (
    audit_id uuid DEFAULT gen_random_uuid() NOT NULL,
    review_id uuid NOT NULL,
    action character varying(64),
    id_actor uuid,
    actor_type character varying(32),
    action_details text,
    fecha_creacion timestamp without time zone DEFAULT now(),
    metadata jsonb DEFAULT '{}'::jsonb
);


--
-- Name: content_reviews; Type: TABLE; Schema: moderation; Owner: -
--

CREATE TABLE moderation.content_reviews (
    review_id uuid DEFAULT gen_random_uuid() NOT NULL,
    content_type character varying(64) NOT NULL,
    content_id uuid NOT NULL,
    id_usuario uuid NOT NULL,
    estado moderation.content_reviews_status_enum DEFAULT 'pending'::moderation.content_reviews_status_enum,
    auto_flagged boolean DEFAULT false,
    flagging_reasons jsonb,
    risk_score integer,
    reviewed_by uuid,
    review_notes text,
    revisado_en timestamp without time zone,
    decision character varying(32),
    rejection_reason character varying(255),
    appealed_by uuid,
    appeal_reason text,
    appealed_at timestamp without time zone,
    appeal_reviewed_by uuid,
    appeal_decision character varying(32),
    appeal_notes text,
    appeal_reviewed_at timestamp without time zone,
    fecha_creacion timestamp without time zone DEFAULT now(),
    fecha_actualizacion timestamp without time zone DEFAULT now(),
    published_at timestamp without time zone,
    removed_at timestamp without time zone,
    ledger_hash character varying(64),
    metadata jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT content_reviews_check CHECK (((estado = 'pending'::moderation.content_reviews_status_enum) OR (revisado_en IS NOT NULL))),
    CONSTRAINT content_reviews_check1 CHECK (((estado = ANY (ARRAY['under_appeal'::moderation.content_reviews_status_enum, 'appeal_approved'::moderation.content_reviews_status_enum, 'appeal_rejected'::moderation.content_reviews_status_enum])) OR (appeal_reviewed_at IS NULL))),
    CONSTRAINT content_reviews_check2 CHECK (((published_at IS NULL) OR (estado = 'approved'::moderation.content_reviews_status_enum))),
    CONSTRAINT content_reviews_check3 CHECK (((removed_at IS NULL) OR (estado = 'rejected'::moderation.content_reviews_status_enum))),
    CONSTRAINT content_reviews_risk_score_check CHECK (((risk_score >= 0) AND (risk_score <= 100)))
);


--
-- Name: moderation_appeals; Type: TABLE; Schema: moderation; Owner: -
--

CREATE TABLE moderation.moderation_appeals (
    appeal_id uuid DEFAULT gen_random_uuid() NOT NULL,
    review_id uuid NOT NULL,
    appealed_by uuid NOT NULL,
    appeal_reason text NOT NULL,
    submitted_at timestamp without time zone DEFAULT now(),
    estado moderation.moderation_appeals_status_enum DEFAULT 'pending'::moderation.moderation_appeals_status_enum,
    reviewed_by uuid,
    review_notes text,
    revisado_en timestamp without time zone,
    original_reviewer_id uuid,
    metadata jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT moderation_appeals_check CHECK ((reviewed_by <> original_reviewer_id))
);


--
-- Name: moderation_queue; Type: TABLE; Schema: moderation; Owner: -
--

CREATE TABLE moderation.moderation_queue (
