    pattern text,
    severity moderation.moderation_rules_severity_enum DEFAULT 'medium'::moderation.moderation_rules_severity_enum,
    action_on_match character varying(32),
    is_active boolean DEFAULT true,
    fecha_creacion timestamp without time zone DEFAULT now(),
    created_by uuid NOT NULL,
    fecha_actualizacion timestamp without time zone,
    updated_by uuid,
    metadata jsonb DEFAULT '{}'::jsonb
);


--
-- Name: cola; Type: TABLE; Schema: notifications; Owner: -
--

CREATE TABLE notifications.cola (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    id_usuario uuid NOT NULL,
    channel character varying(20) NOT NULL,
    template_id uuid NOT NULL,
    payload jsonb NOT NULL,
    estado character varying(20) DEFAULT 'pending'::character varying,
    retry_count integer DEFAULT 0,
    next_retry_at timestamp without time zone DEFAULT now(),
    error_details text,
    fecha_creacion timestamp without time zone DEFAULT now(),
    fecha_actualizacion timestamp without time zone DEFAULT now(),
    fecha_expiracion timestamp without time zone DEFAULT (now() + '90 days'::interval),
    CONSTRAINT cola_estado_check CHECK (((estado)::text = ANY ((ARRAY['pending'::character varying, 'sent'::character varying, 'failed'::character varying, 'retrying'::character varying, 'cancelled'::character varying])::text[]))),
    CONSTRAINT cola_retry_count_check CHECK (((retry_count >= 0) AND (retry_count <= 10)))
);


