    last_seen timestamp without time zone DEFAULT now(),
    estado character varying(20) DEFAULT 'pending_review'::character varying,
    fecha_creacion timestamp without time zone DEFAULT now(),
    CONSTRAINT cola_cartas_muertas_estado_check CHECK (((estado)::text = ANY ((ARRAY['pending_review'::character varying, 'archived'::character varying, 'resolved'::character varying])::text[])))
);


