--
-- Name: mv_admin_heatmap_supply; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_admin_heatmap_supply AS
 SELECT public.st_astext(cell_geom) AS cell_wkt,
    (public.st_asgeojson(cell_geom))::jsonb AS cell_geojson,
    cell_centroid,
    supply_count,
    now() AS refrescado_en
   FROM public.admin_supply_density_grid((public.st_setsrid(public.st_makeenvelope(('-96.98'::numeric)::double precision, (19.48)::double precision, ('-96.78'::numeric)::double precision, (19.62)::double precision, 4326), 4326))::public.geography, 0.01) g(cell_geom, cell_centroid, supply_count)
  WITH NO DATA;


--
-- Name: mv_local_seller_popularity; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_local_seller_popularity AS
 SELECT id_vendedor,
    date_trunc('hour'::text, fecha_creacion) AS bucket_hour,
    count(*) FILTER (WHERE (tipo_evento = 'view'::text)) AS views_count,
    count(*) FILTER (WHERE (tipo_evento = 'click'::text)) AS clicks_count,
    count(*) FILTER (WHERE (tipo_evento = 'save'::text)) AS saves_count,
    count(*) AS total_interactions
   FROM public.eventos_interaccion
  WHERE (fecha_eliminacion IS NULL)
  GROUP BY id_vendedor, (date_trunc('hour'::text, fecha_creacion))
  WITH NO DATA;


