--
-- Name: priority_alerts_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.priority_alerts_view AS
 SELECT fa.id,
    aa.titulo,
    aa.severidad,
    aa.estado,
    fa.score,
    aa.tipo_entidad AS entity_kind,
    aa.id_entidad,
    aa.created_at AS fecha_creacion,
    aa.updated_at AS fecha_actualizacion
   FROM (public.alertas_fraude fa
     JOIN public.admin_alertas aa ON ((fa.alerta_id = aa.id)))
  WHERE (aa.oculto_en_dash = false)
  ORDER BY
        CASE aa.severidad
            WHEN 'critica'::text THEN 4
            WHEN 'alta'::text THEN 3
            WHEN 'media'::text THEN 2
            ELSE 1
        END DESC, fa.score DESC;


