--
-- Name: puntajes_riesgo_usuario; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.puntajes_riesgo_usuario (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    id_usuario uuid NOT NULL,
    score numeric(5,2) DEFAULT 0.00 NOT NULL,
    nivel_riesgo character varying(20) GENERATED ALWAYS AS (
CASE
    WHEN (score < (20)::numeric) THEN 'bajo'::text
    WHEN (score < (50)::numeric) THEN 'medio'::text
    WHEN (score < (80)::numeric) THEN 'alto'::text
    ELSE 'critico'::text
END) STORED,
    factores_riesgo jsonb DEFAULT '[]'::jsonb,
    intercambios_cancelados integer DEFAULT 0,
    reportes_recibidos integer DEFAULT 0,
    ratings_negativos integer DEFAULT 0,
    ultima_evaluacion timestamp with time zone DEFAULT now(),
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    fecha_actualizacion timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT puntajes_riesgo_usuario_intercambios_cancelados_check CHECK ((intercambios_cancelados >= 0)),
    CONSTRAINT puntajes_riesgo_usuario_ratings_negativos_check CHECK ((ratings_negativos >= 0)),
    CONSTRAINT puntajes_riesgo_usuario_reportes_recibidos_check CHECK ((reportes_recibidos >= 0)),
    CONSTRAINT puntajes_riesgo_usuario_score_check CHECK (((score >= (0)::numeric) AND (score <= (100)::numeric)))
);


