--
-- Name: v_admin_spatial_gap; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_admin_spatial_gap AS
 SELECT NULL::text AS cell_wkt,
    NULL::bigint AS supply_count,
    NULL::bigint AS demand_count,
    NULL::numeric AS density_score,
    'DEMANDA_NO_DISPONIBLE'::text AS zone_status
  WHERE false;


--
-- Name: v_admin_supply_points; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_admin_supply_points AS
 SELECT u.id AS id_usuario,
    ub.id AS id_ubicacion,
    ub.punto,
    ub.tipo AS tipo_ubicacion,
    (COALESCE(u.activo, true) AND (u.fecha_eliminacion IS NULL) AND (ub.fecha_eliminacion IS NULL) AND (u.role = ANY (ARRAY['seller'::text, 'vendor'::text, 'vendedor'::text]))) AS is_operational_supply
   FROM (auth.users u
     JOIN auth.ubicaciones ub ON ((ub.id_usuario = u.id)))
  WHERE (ub.punto IS NOT NULL);


--
-- Name: v_admin_supply_saturation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_admin_supply_saturation AS
 WITH g AS (
         SELECT admin_supply_density_grid.cell_geom,
            admin_supply_density_grid.cell_centroid,
            admin_supply_density_grid.supply_count
           FROM public.admin_supply_density_grid((public.st_setsrid(public.st_makeenvelope(('-180'::integer)::double precision, ('-90'::integer)::double precision, (180)::double precision, (90)::double precision, 4326), 4326))::public.geography, 0.05) admin_supply_density_grid(cell_geom, cell_centroid, supply_count)
        ), percentiles AS (
         SELECT percentile_cont((0.66)::double precision) WITHIN GROUP (ORDER BY ((g_1.supply_count)::double precision)) AS p66,
            percentile_cont((0.33)::double precision) WITHIN GROUP (ORDER BY ((g_1.supply_count)::double precision)) AS p33
           FROM g g_1
        )
 SELECT public.st_astext(cell_geom) AS cell_wkt,
    supply_count,
        CASE
            WHEN ((supply_count)::double precision >= ( SELECT percentiles.p66
               FROM percentiles)) THEN 'ALTA'::text
            WHEN ((supply_count)::double precision >= ( SELECT percentiles.p33
               FROM percentiles)) THEN 'MEDIA'::text
            ELSE 'BAJA'::text
        END AS supply_density_band
   FROM g;


--
-- Name: v_alertas_consola; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_alertas_consola AS
 SELECT id,
    tipo AS tipo_alerta,
    nivel_riesgo,
    score_riesgo,
    estado,
    tipo_entidad,
    id_entidad,
    created_at AS fecha_creacion,
    updated_at AS fecha_actualizacion,
    SUBSTRING(COALESCE(descripcion, ''::text) FROM 1 FOR 240) AS descripcion_breve
   FROM public.admin_alertas a
  WHERE ((oculto_en_dash = false) AND ((estado)::text = ANY (ARRAY['abierta'::text, 'en_revision'::text, 'escalada'::text])));


--
-- Name: v_alertas_criticas_age; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_alertas_criticas_age AS
 SELECT a.id,
    a.id_vendedor,
    u.email AS vendedor_email,
    a.tipo_alerta,
    a.campo_afectado,
    a.valor_anterior,
    a.valor_nuevo,
    a.estado,
    a.nivel_riesgo,
    a.visible,
    a.fecha_creacion,
    a.resuelto_por,
    a.resuelto_at,
    a.metadata,
    ( SELECT count(*) AS count
           FROM public.alertas_criticas a2
          WHERE ((a2.id_vendedor = a.id_vendedor) AND (a2.estado = 'REVERTIDA'::text) AND (a2.is_active = true))) AS total_reversiones_vendedor
   FROM (public.alertas_criticas a
     JOIN auth.users u ON ((u.id = a.id_vendedor)))
  WHERE ((a.is_active = true) AND (a.visible = true) AND (a.estado = 'PENDIENTE'::text));


