    ((h.valor_antes ->> 'saldo'::text))::numeric AS saldo_antes,
    ((h.valor_despues ->> 'saldo'::text))::numeric AS saldo_despues,
    h.diferencia,
    h.motivo,
    u.email AS actor_email,
    h.creado_en
   FROM (public.moderacion_h_auditoria h
     JOIN auth.users u ON ((u.id = h.id_actor)))
  WHERE (h.entidad_tipo = 'billetera'::text)
  ORDER BY h.creado_en DESC;


