CREATE VIEW public.v_reportes_seguridad_publicos AS
 SELECT id,
    fecha_reporte,
    tipo_reporte,
    resumen,
    archivado,
    fecha_creacion
   FROM public.reportes_seguridad
  WHERE ((fecha_eliminacion IS NULL) AND (tipo_reporte = ANY (ARRAY['diario'::text, 'semanal'::text])));


--
-- Name: v_riesgo_alertas_activas; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_riesgo_alertas_activas AS
 SELECT id,
    tipo AS tipo_alerta,
    nivel_riesgo,
    created_at AS creado_en,
    payload
   FROM public.admin_alertas a
  WHERE ((created_at >= (now() - '24:00:00'::interval)) AND (oculto_en_dash IS NOT TRUE));


--
-- Name: v_riesgo_historico; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_riesgo_historico AS
 SELECT date(fecha_creacion) AS fecha,
    round(avg(
        CASE action
            WHEN 'RISK_SETTING_UPDATED'::text THEN 0.8
            WHEN 'ADMIN_SOFT_DELETE'::text THEN 0.7
            WHEN 'REVERSION_APLICADA'::text THEN 0.9
            ELSE 0.3
        END), 2) AS nivel_riesgo,
    count(*) AS total_incidentes
   FROM auth.auditoria al
  GROUP BY (date(fecha_creacion))
  ORDER BY (date(fecha_creacion));


--
-- Name: v_riesgo_incidentes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_riesgo_incidentes AS
 SELECT i.id,
    i.id_usuario,
    u.email AS usuario_email,
    i.descripcion,
    i.nivel_riesgo,
    i.origen,
    i.procesado,
    i.creado_en
   FROM (public.log_incidentes_seguridad i
     JOIN auth.users u ON ((u.id = i.id_usuario)))
  ORDER BY i.creado_en DESC;


--
-- Name: v_riesgo_serie_historica; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_riesgo_serie_historica AS
 SELECT fecha_reporte,
    jsonb_array_length(COALESCE((contenido -> 'cuentas_espejo'::text), '[]'::jsonb)) AS n_espejo,
    jsonb_array_length(COALESCE((contenido -> 'lavado_puntos'::text), '[]'::jsonb)) AS n_lavado,
    jsonb_array_length(COALESCE((contenido -> 'ghosting'::text), '[]'::jsonb)) AS n_ghost
   FROM public.reportes_seguridad r
  WHERE (fecha_reporte >= (CURRENT_DATE - 30))
  ORDER BY fecha_reporte DESC;


--
-- Name: v_seller_business_intelligence; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_seller_business_intelligence AS
 WITH seller_monthly_metrics AS (
         SELECT o.id_vendedor,
            o.order_month,
            count(o.id) AS total_orders_received,
            count(o.id) FILTER (WHERE (o.estado = 'completed'::text)) AS completed_orders,
            count(o.id) FILTER (WHERE (o.estado = 'seller_rejected'::text)) AS rejected_orders,
            COALESCE(sum(o.total) FILTER (WHERE (o.estado = 'completed'::text)), (0)::numeric) AS total_revenue,
            (COALESCE(avg(o.total) FILTER (WHERE (o.estado = 'completed'::text)), (0)::numeric))::numeric(12,2) AS average_ticket,
            (avg((EXTRACT(epoch FROM (o.vendedor_listo_en - o.fecha_creacion)) / (60)::numeric)))::numeric(8,2) AS avg_preparation_time_minutes,
            count(o.id) FILTER (WHERE ((o.estado = 'completed'::text) AND (o.vendedor_listo_en > o.expiracion_coordinacion_en))) AS sla_breaches
           FROM auth.ordenes o
          GROUP BY o.id_vendedor, o.order_month
        ), ledger_monthly_metrics AS (
         SELECT r.id_vendedor,
            r.order_month,
            count(DISTINCT r.id_comprador) AS unique_loyal_buyers,
            COALESCE(sum(r.points_credited), (0)::numeric) AS total_reward_points_issued
           FROM public.libro_recompensas_orden r
          GROUP BY r.id_vendedor, r.order_month
        )
 SELECT sm.id_vendedor,
    sm.order_month,
    t.tier_code AS seller_tier_snapshot,
    sm.total_orders_received,
    sm.completed_orders,
    sm.rejected_orders,
        CASE
            WHEN (sm.total_orders_received = 0) THEN (0)::numeric(5,2)
            ELSE ((((sm.rejected_orders)::numeric / (sm.total_orders_received)::numeric) * (100)::numeric))::numeric(5,2)
        END AS rejection_rate_percentage,
    sm.total_revenue,
    sm.average_ticket,
    sm.avg_preparation_time_minutes,
    sm.sla_breaches,
        CASE
            WHEN (sm.completed_orders = 0) THEN (100)::numeric(5,2)
            ELSE (((((sm.completed_orders - sm.sla_breaches))::numeric / (sm.completed_orders)::numeric) * (100)::numeric))::numeric(5,2)
        END AS sla_compliance_rate,
    COALESCE(lm.unique_loyal_buyers, (0)::bigint) AS active_loyalty_customers,
    COALESCE(lm.total_reward_points_issued, (0)::numeric) AS total_rewards_issued
   FROM ((seller_monthly_metrics sm
     LEFT JOIN ledger_monthly_metrics lm ON (((sm.id_vendedor = lm.id_vendedor) AND (sm.order_month = lm.order_month))))
     LEFT JOIN LATERAL ( SELECT asignaciones_perfil_comercial.tier_code
           FROM public.asignaciones_perfil_comercial
          WHERE ((asignaciones_perfil_comercial.id_usuario = sm.id_vendedor) AND (asignaciones_perfil_comercial.actor_role = 'seller'::text) AND (asignaciones_perfil_comercial.effective_from <= ((sm.order_month + '1 mon'::interval) - '00:00:01'::interval)))
          ORDER BY asignaciones_perfil_comercial.effective_from DESC
         LIMIT 1) t ON (true));


--
-- Name: v_seller_geo_zone_intelligence; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_seller_geo_zone_intelligence AS
 SELECT o.id_vendedor,
    o.order_month,
    o.region_code,
    gs.delivery_zone_label AS geographic_quadrant,
    count(o.id) AS total_orders_in_zone,
    count(o.id) FILTER (WHERE (o.estado = 'completed'::text)) AS successful_deliveries,
    COALESCE(sum(o.total) FILTER (WHERE (o.estado = 'completed'::text)), (0)::numeric) AS zone_total_revenue,
    (min(gs.seller_to_delivery_meters))::numeric(10,2) AS min_delivery_distance_meters,
    (avg(gs.seller_to_delivery_meters))::numeric(10,2) AS avg_delivery_distance_meters,
    (max(gs.seller_to_delivery_meters))::numeric(10,2) AS max_delivery_distance_meters,
    (public.st_centroid(public.st_collect(gs.delivery_location)))::public.geometry(Point,4326) AS zone_demand_centroid
   FROM (auth.ordenes o
     JOIN public.instantaneas_geo_orden gs ON (((o.id = gs.id_orden) AND (o.order_month = gs.order_month) AND (o.region_code = gs.region_code))))
  WHERE (o.estado = ANY (ARRAY['in_delivery'::text, 'completed'::text]))
  GROUP BY o.id_vendedor, o.order_month, o.region_code, gs.delivery_zone_label;


--
-- Name: v_seller_performance_v4; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_seller_performance_v4 AS
 SELECT o.id_vendedor,
    public.get_active_actor_tier(o.id_vendedor, 'seller'::text) AS profile_tier,
    count(*) FILTER (WHERE (o.estado = 'completed'::text)) AS completed_orders,
    count(*) FILTER (WHERE (o.estado = ANY (ARRAY['assigned'::text, 'payment_confirmed'::text, 'preparing'::text, 'in_delivery'::text]))) AS active_orders,
    count(*) FILTER (WHERE ((o.estado = 'cancelled'::text) AND (o.id_vendedor IS NOT NULL))) AS cancelled_after_assign,
    avg(gs.buyer_to_seller_meters) FILTER (WHERE (o.estado = 'completed'::text)) AS avg_distance_completed,
    avg((EXTRACT(epoch FROM (o.fecha_actualizacion - o.fecha_creacion)) / (3600)::numeric)) FILTER (WHERE (o.estado = 'completed'::text)) AS avg_hours_to_complete
   FROM (auth.ordenes o
     LEFT JOIN public.instantaneas_geo_orden gs ON (((gs.id_orden = o.id) AND (gs.order_month = o.order_month) AND (gs.region_code = o.region_code))))
  WHERE (o.id_vendedor IS NOT NULL)
  GROUP BY o.id_vendedor;


--
-- Name: v_seller_trade_zone_intelligence_v4; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_seller_trade_zone_intelligence_v4 AS
 SELECT o.id AS id_orden,
    o.id_vendedor,
    o.id_comprador,
    o.estado,
    gs.buyer_to_seller_meters,
    gs.seller_to_delivery_meters,
    gs.seller_location,
    gs.delivery_location,
    o.fecha_creacion,
    o.fecha_actualizacion
   FROM (auth.ordenes o
     JOIN public.instantaneas_geo_orden gs ON (((gs.id_orden = o.id) AND (gs.order_month = o.order_month) AND (gs.region_code = o.region_code))))
  WHERE (o.estado = ANY (ARRAY['assigned'::text, 'payment_confirmed'::text, 'completed'::text]));


--
-- Name: v_tier_config_efectiva; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_tier_config_efectiva AS
 SELECT stc.tier_code,
    stc.nombre_visible,
    stc.sort_order,
    stc.is_default,
    pm.precio_mensual,
    pm.precio_anual,
    pm.max_productos,
    pm.max_ubicaciones,
    pm.max_promociones,
    pm.max_fotos_producto,
    pm.tiene_analytics,
    pm.tiene_analytics_ml,
    pm.tiene_push,
    pm.tiene_campanas_geo,
    pm.tiene_historial_bi,
    rc.rule_code,
    rc.actor_role AS rule_actor_role,
    rc.rule_name,
    crv.numeric_value,
    crv.boolean_value,
    crv.text_value
   FROM (((auth.catalogo_niveles_servicio stc
     LEFT JOIN auth.planes_membresia pm ON ((pm.codigo = stc.tier_code)))
     CROSS JOIN public.catalogo_reglas_comerciales rc)
     LEFT JOIN public.valores_reglas_nivel_comercial crv ON (((crv.tier_code = stc.tier_code) AND (crv.rule_code = rc.rule_code))))
  WHERE stc.is_active
  ORDER BY stc.sort_order, rc.rule_code;


