    CONSTRAINT chk_tipo_accion CHECK (((tipo_accion)::text = ANY ((ARRAY['accept'::character varying, 'reject'::character varying, 'ship'::character varying, 'delay'::character varying, 'update_tracking'::character varying, 'cancel'::character varying])::text[])))
