    detected_at timestamp with time zone DEFAULT now(),
    resuelto_en timestamp with time zone,
    CONSTRAINT chk_severidad_incumplimiento CHECK (((severity)::text = ANY ((ARRAY['low'::character varying, 'medium'::character varying, 'high'::character varying, 'critical'::character varying])::text[]))),
    CONSTRAINT chk_tipo_sla CHECK (((sla_type)::text = ANY ((ARRAY['response_time'::character varying, 'fulfillment_time'::character varying, 'delivery_time'::character varying, 'rating'::character varying, 'return_rate'::character varying])::text[])))
);


