    description text,
    category character varying(100),
    quantity_available integer DEFAULT 0 NOT NULL,
    quantity_reserved integer DEFAULT 0 NOT NULL,
    quantity_sold integer DEFAULT 0 NOT NULL,
    low_stock_threshold integer DEFAULT 10,
    price_base numeric(12,2) NOT NULL,
    price_current numeric(12,2) NOT NULL,
    discount_percentage numeric(5,2) DEFAULT 0.00,
    images_count integer DEFAULT 0,
    rating_count integer DEFAULT 0,
    average_rating numeric(3,2) DEFAULT 0.00,
    fecha_creacion timestamp with time zone DEFAULT now(),
    fecha_actualizacion timestamp with time zone DEFAULT now(),
    CONSTRAINT chk_calificacion CHECK (((average_rating >= (0)::numeric) AND (average_rating <= (5)::numeric))),
    CONSTRAINT chk_cantidad_inventario CHECK ((quantity_available >= 0)),
    CONSTRAINT chk_descuento CHECK (((discount_percentage >= (0)::numeric) AND (discount_percentage <= (100)::numeric))),
    CONSTRAINT chk_inventario_reservado CHECK ((quantity_reserved >= 0)),
    CONSTRAINT chk_precios CHECK (((price_base > (0)::numeric) AND (price_current > (0)::numeric)))
);


