    CONSTRAINT chk_tasas CHECK (((acceptance_rate >= (0)::numeric) AND (acceptance_rate <= (100)::numeric) AND (fulfillment_rate >= (0)::numeric) AND (fulfillment_rate <= (100)::numeric) AND (return_rate >= (0)::numeric) AND (return_rate <= (100)::numeric)))
);


