    nombre_oferta character varying(255) NOT NULL,
    description text,
    offer_type character varying(50) DEFAULT 'limited_time'::character varying,
    inventory_ids uuid[] NOT NULL,
    product_count integer GENERATED ALWAYS AS (array_length(inventory_ids, 1)) STORED,
    discount_type character varying(20) NOT NULL,
    discount_value numeric(10,2) NOT NULL,
    minimum_purchase numeric(12,2) DEFAULT 0,
    quantity_available integer,
    quantity_purchased integer DEFAULT 0,
    max_per_customer integer,
    start_date timestamp with time zone NOT NULL,
    end_date timestamp with time zone NOT NULL,
    is_active boolean DEFAULT true,
    auto_apply boolean DEFAULT true,
    target_audience character varying(50) DEFAULT 'all'::character varying,
    fecha_creacion timestamp with time zone DEFAULT now(),
    fecha_actualizacion timestamp with time zone DEFAULT now(),
    CONSTRAINT chk_audiencia_objetivo CHECK (((target_audience)::text = ANY ((ARRAY['all'::character varying, 'new_customers'::character varying, 'vip'::character varying, 'returning'::character varying])::text[]))),
    CONSTRAINT chk_descuento_fijo CHECK (((((discount_type)::text = 'fixed_amount'::text) AND (discount_value > (0)::numeric)) OR ((discount_type)::text <> 'fixed_amount'::text))),
    CONSTRAINT chk_descuento_porcentaje CHECK (((((discount_type)::text = 'percentage'::text) AND (discount_value > (0)::numeric) AND (discount_value <= (100)::numeric)) OR ((discount_type)::text <> 'percentage'::text))),
    CONSTRAINT chk_fechas CHECK ((start_date < end_date)),
    CONSTRAINT chk_tipo_descuento CHECK (((discount_type)::text = ANY ((ARRAY['percentage'::character varying, 'fixed_amount'::character varying])::text[]))),
    CONSTRAINT chk_tipo_oferta CHECK (((offer_type)::text = ANY ((ARRAY['limited_time'::character varying, 'seasonal'::character varying, 'flash_sale'::character varying, 'bundle'::character varying])::text[])))
);


