    compensation_offered,
    detected_at,
    resuelto_en
   FROM seller.incumplimientos_sla;


--
-- Name: v_alertas_rendimiento_activas; Type: VIEW; Schema: seller; Owner: -
--

CREATE VIEW seller.v_alertas_rendimiento_activas AS
 SELECT sp.nombre_negocio,
    count(*) AS alert_count,
    (max(
        CASE
            WHEN ((ia.severity)::text = 'critical'::text) THEN 1
            ELSE 0
        END))::boolean AS has_critical,
    jsonb_agg(jsonb_build_object('type', ia.tipo_alerta, 'severity', ia.severity, 'message', ia.message)) AS alerts
   FROM (seller.perfiles sp
     JOIN seller.alertas_inventario ia ON ((sp.id = ia.id_vendedor)))
  WHERE (ia.is_resolved = false)
  GROUP BY sp.id, sp.nombre_negocio;


--
-- Name: v_comparacion_precios; Type: VIEW; Schema: seller; Owner: -
--

CREATE VIEW seller.v_comparacion_precios AS
 SELECT id,
    nombre_producto,
    product_sku,
    price_base,
    price_current,
    discount_percentage,
    round((((price_base - price_current) / price_base) * (100)::numeric), 2) AS effective_discount,
    ( SELECT count(*) AS count
           FROM seller.historial_precios
          WHERE (historial_precios.id_inventario = i.id)) AS price_changes_count
   FROM seller.inventario i
  ORDER BY discount_percentage DESC;


--
-- Name: v_estadisticas_rapidas_panel; Type: VIEW; Schema: seller; Owner: -
--

CREATE VIEW seller.v_estadisticas_rapidas_panel AS
 SELECT sp.id,
    sp.nombre_negocio,
    count(DISTINCT o.id) AS total_orders,
    COALESCE(sum(o.total), (0)::numeric) AS total_revenue,
    count(
        CASE
            WHEN (o.estado = 'pending'::text) THEN 1
            ELSE NULL::integer
        END) AS pending_orders,
    count(
        CASE
            WHEN (o.estado = 'delivered'::text) THEN 1
            ELSE NULL::integer
        END) AS completed_orders,
    pm.average_rating,
    count(DISTINCT sn.id) FILTER (WHERE (sn.is_read = false)) AS unread_notifications
   FROM (((seller.perfiles sp
     LEFT JOIN auth.ordenes o ON (((sp.id = o.id_vendedor) AND (o.fecha_creacion > (now() - '30 days'::interval)))))
     LEFT JOIN seller.metricas_rendimiento pm ON ((sp.id = pm.id_vendedor)))
     LEFT JOIN seller.notificaciones_vendedor sn ON ((sp.id = sn.id_vendedor)))
  GROUP BY sp.id, sp.nombre_negocio, pm.average_rating;


--
-- Name: v_inventario_con_alertas; Type: VIEW; Schema: seller; Owner: -
--

CREATE VIEW seller.v_inventario_con_alertas AS
 SELECT i.id,
    i.nombre_producto,
    i.product_sku,
    i.quantity_available,
    i.low_stock_threshold,
    i.price_current,
    count(DISTINCT a.id) AS alert_count,
    (max(
        CASE
            WHEN ((a.tipo_alerta)::text = 'low_stock'::text) THEN 1
            ELSE 0
        END))::boolean AS has_low_stock_alert,
    (max(
        CASE
            WHEN ((a.severity)::text = 'critical'::text) THEN 1
            ELSE 0
        END))::boolean AS has_critical_alert
   FROM (seller.inventario i
     LEFT JOIN seller.alertas_inventario a ON (((i.id = a.id_inventario) AND (a.is_resolved = false))))
  GROUP BY i.id, i.nombre_producto, i.product_sku, i.quantity_available, i.low_stock_threshold, i.price_current;


--
-- Name: v_ofertas_con_metricas; Type: VIEW; Schema: seller; Owner: -
--

CREATE VIEW seller.v_ofertas_con_metricas AS
 SELECT o.id,
    o.nombre_oferta,
    o.discount_value,
    o.product_count,
    o.quantity_available,
    o.quantity_purchased,
    round(COALESCE((((o.quantity_purchased)::numeric / (NULLIF(o.quantity_available, 0))::numeric) * (100)::numeric), (0)::numeric), 2) AS sold_percentage,
    COALESCE(ou.orders_using_offer, 0) AS orders,
    COALESCE(ou.conversion_rate, (0)::numeric) AS conversion_rate,
    COALESCE(ou.net_revenue, (0)::numeric) AS revenue,
    COALESCE(ou.roi_percentage, (0)::numeric) AS roi,
    o.start_date,
    o.end_date,
    o.is_active
   FROM (seller.ofertas o
     LEFT JOIN seller.uso_ofertas ou ON ((o.id = ou.id_oferta)))
  ORDER BY o.start_date DESC;


--
-- Name: v_ordenes_con_acciones; Type: VIEW; Schema: seller; Owner: -
--

CREATE VIEW seller.v_ordenes_con_acciones AS
 SELECT o.id,
    o.id_comprador,
    u.email AS buyer_email,
    o.total,
    o.estado,
    o.fecha_creacion,
        CASE
            WHEN (o.estado = 'pending'::text) THEN 'puede_aceptar'::text
            WHEN (o.estado = 'accepted'::text) THEN 'puede_enviar'::text
            WHEN (o.estado = 'shipped'::text) THEN 'puede_entregar'::text
            ELSE 'sin_acciones'::text
        END AS available_action,
    (( SELECT count(*) AS count
           FROM seller.reservas_stock_orden
          WHERE ((reservas_stock_orden.id_orden = o.id) AND ((reservas_stock_orden.reservation_status)::text = 'active'::text))))::integer AS reservations_count
   FROM (auth.ordenes o
     JOIN auth.users u ON ((o.id_comprador = u.id)));


--
-- Name: v_ordenes_pendientes_accion; Type: VIEW; Schema: seller; Owner: -
--

CREATE VIEW seller.v_ordenes_pendientes_accion AS
 SELECT o.id,
    o.id_comprador,
    u.email,
    o.total,
    o.estado,
    o.fecha_creacion,
    COALESCE((sn.id IS NOT NULL), false) AS has_notification,
    (EXTRACT(epoch FROM (now() - o.fecha_creacion)))::integer AS seconds_pending
   FROM ((auth.ordenes o
     JOIN auth.users u ON ((o.id_comprador = u.id)))
     LEFT JOIN seller.notificaciones_vendedor sn ON ((o.id = sn.related_order_id)))
  WHERE ((o.estado = 'pending'::text) AND (sn.is_action_required = true));


--
-- Name: v_ordenes_vendedor; Type: VIEW; Schema: seller; Owner: -
--

CREATE VIEW seller.v_ordenes_vendedor AS
 SELECT o.id,
    o.fecha_creacion,
    o.estado,
    o.total,
    p.nombre_negocio AS seller_name,
    count(oa.id) AS action_count
   FROM ((auth.ordenes o
     JOIN seller.perfiles p ON ((o.id_vendedor = p.id)))
     LEFT JOIN seller.acciones_orden oa ON ((o.id = oa.id_orden)))
  GROUP BY o.id, o.fecha_creacion, o.estado, o.total, p.nombre_negocio;


--
-- Name: v_ranking_rendimiento; Type: VIEW; Schema: seller; Owner: -
--

CREATE VIEW seller.v_ranking_rendimiento AS
 SELECT sp.nombre_negocio,
    sp.business_category,
    pm.average_rating,
    pm.acceptance_rate,
    pm.fulfillment_rate,
    pm.on_time_delivery_rate,
    ((((pm.average_rating + (pm.acceptance_rate / (20)::numeric)) + (pm.fulfillment_rate / (20)::numeric)) + (pm.on_time_delivery_rate / (20)::numeric)))::numeric(5,2) AS overall_score,
    row_number() OVER (PARTITION BY sp.business_category ORDER BY pm.average_rating DESC) AS rank_in_category,
    pm.is_suspended
   FROM (seller.perfiles sp
     LEFT JOIN seller.metricas_rendimiento pm ON ((sp.id = pm.id_vendedor)))
  WHERE (sp.is_verified = true)
  ORDER BY (((((pm.average_rating + (pm.acceptance_rate / (20)::numeric)) + (pm.fulfillment_rate / (20)::numeric)) + (pm.on_time_delivery_rate / (20)::numeric)))::numeric(5,2)) DESC;


--
-- Name: v_resumen_aceptacion; Type: VIEW; Schema: seller; Owner: -
--

CREATE VIEW seller.v_resumen_aceptacion AS
 SELECT (date_trunc('day'::text, fecha_creacion))::date AS date,
    sum(
        CASE
            WHEN ((tipo_accion)::text = 'accept'::text) THEN 1
            ELSE 0
        END) AS accepted_count,
    sum(
        CASE
            WHEN ((tipo_accion)::text = 'reject'::text) THEN 1
            ELSE 0
        END) AS rejected_count,
    round((((sum(
        CASE
            WHEN ((tipo_accion)::text = 'accept'::text) THEN 1
            ELSE 0
        END))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 2) AS acceptance_rate
   FROM seller.acciones_orden oa
  GROUP BY (date_trunc('day'::text, fecha_creacion));


--
-- Name: v_resumen_stock_por_categoria; Type: VIEW; Schema: seller; Owner: -
--

CREATE VIEW seller.v_resumen_stock_por_categoria AS
 SELECT category,
    count(*) AS product_count,
    sum(quantity_available) AS total_stock,
    sum(quantity_sold) AS total_sold,
    avg(price_current) AS avg_price,
    avg(average_rating) AS avg_rating
   FROM seller.inventario i
  GROUP BY category;


--
-- Name: v_resumen_vendedor; Type: VIEW; Schema: seller; Owner: -
--

CREATE VIEW seller.v_resumen_vendedor AS
 SELECT p.id,
    p.id_usuario,
    p.nombre_negocio,
    p.business_category,
    p.is_verified,
    count(DISTINCT i.id) AS product_count,
    (COALESCE(sum(i.quantity_available), (0)::bigint))::integer AS total_stock,
    m.average_rating,
    m.total_orders,
    m.total_revenue
   FROM ((seller.perfiles p
     LEFT JOIN seller.inventario i ON ((p.id = i.id_vendedor)))
     LEFT JOIN seller.metricas_rendimiento m ON ((p.id = m.id_vendedor)))
  GROUP BY p.id, p.id_usuario, p.nombre_negocio, p.business_category, p.is_verified, m.average_rating, m.total_orders, m.total_revenue;


--
-- Name: columnas; Type: VIEW; Schema: visual; Owner: -
--

CREATE VIEW visual.columnas AS
 SELECT n.nspname AS esquema,
    c.relname AS tabla,
    a.attname AS columna,
    format_type(a.atttypid, a.atttypmod) AS tipo,
    a.attnotnull AS not_null,
    (EXISTS ( SELECT 1
           FROM pg_constraint pk
          WHERE ((pk.conrelid = c.oid) AND (pk.contype = 'p'::"char") AND (a.attnum = ANY (pk.conkey))))) AS es_pk,
    col_description(c.oid, (a.attnum)::integer) AS comentario
   FROM ((pg_class c
     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
     JOIN pg_attribute a ON (((a.attrelid = c.oid) AND (a.attnum > 0) AND (NOT a.attisdropped))))
  WHERE ((n.nspname = ANY (ARRAY['app'::name, 'admin'::name, 'api'::name, 'analytics'::name, 'auth'::name])) AND (c.relkind = ANY (ARRAY['r'::"char", 'v'::"char", 'm'::"char"])))
  ORDER BY n.nspname, c.relname, a.attnum;


--
-- Name: llaves_foraneas; Type: VIEW; Schema: visual; Owner: -
--

CREATE VIEW visual.llaves_foraneas AS
 SELECT nc.nspname AS esquema_origen,
    cc.relname AS tabla_origen,
    a.attname AS columna,
    nf.nspname AS esquema_referido,
    cf.relname AS tabla_referida,
    cn.conname AS nombre_constraint
   FROM (((((pg_constraint cn
     JOIN pg_class cc ON ((cc.oid = cn.conrelid)))
     JOIN pg_namespace nc ON ((nc.oid = cc.relnamespace)))
     JOIN pg_class cf ON ((cf.oid = cn.confrelid)))
     JOIN pg_namespace nf ON ((nf.oid = cf.relnamespace)))
     JOIN pg_attribute a ON (((a.attrelid = cc.oid) AND (a.attnum = ANY (cn.conkey)))))
  WHERE ((cn.contype = 'f'::"char") AND (nc.nspname = ANY (ARRAY['app'::name, 'admin'::name, 'api'::name, 'analytics'::name, 'auth'::name])))
  ORDER BY nc.nspname, cc.relname, a.attname;


--
-- Name: llaves_primarias; Type: VIEW; Schema: visual; Owner: -
--

CREATE VIEW visual.llaves_primarias AS
 SELECT nc.nspname AS esquema,
    cc.relname AS tabla,
    a.attname AS columna_pk
   FROM (((pg_constraint cn
     JOIN pg_class cc ON ((cc.oid = cn.conrelid)))
     JOIN pg_namespace nc ON ((nc.oid = cc.relnamespace)))
     JOIN pg_attribute a ON (((a.attrelid = cc.oid) AND (a.attnum = ANY (cn.conkey)))))
  WHERE ((cn.contype = 'p'::"char") AND (nc.nspname = ANY (ARRAY['app'::name, 'admin'::name, 'api'::name, 'analytics'::name, 'auth'::name])))
  ORDER BY nc.nspname, cc.relname, a.attname;


--
-- Name: politicas_rls; Type: VIEW; Schema: visual; Owner: -
--

CREATE VIEW visual.politicas_rls AS
 SELECT schemaname AS esquema,
    tablename AS tabla,
    policyname,
    cmd,
    roles
   FROM pg_policies
  WHERE (schemaname = ANY (ARRAY['app'::name, 'admin'::name, 'api'::name, 'analytics'::name, 'auth'::name]))
  ORDER BY schemaname, tablename, policyname;


--
-- Name: tablas; Type: VIEW; Schema: visual; Owner: -
--

CREATE VIEW visual.tablas AS
 SELECT n.nspname AS esquema,
    c.relname AS tabla,
    c.relkind,
        CASE c.relkind
            WHEN 'r'::"char" THEN 'tabla'::text
            WHEN 'v'::"char" THEN 'vista'::text
            WHEN 'm'::"char" THEN 'matview'::text
            ELSE NULL::text
        END AS tipo_objeto,
    c.relrowsecurity AS rls_activado,
    c.reltuples AS filas_estimadas,
    pg_get_userbyid(c.relowner) AS owner,
    obj_description(c.oid, 'pg_class'::name) AS comentario
   FROM (pg_class c
     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
  WHERE ((n.nspname = ANY (ARRAY['app'::name, 'admin'::name, 'api'::name, 'analytics'::name, 'auth'::name])) AND (c.relkind = ANY (ARRAY['r'::"char", 'v'::"char", 'm'::"char"])))
  ORDER BY n.nspname, c.relname;


