--
-- Name: v_campanas_dashboard _RETURN; Type: RULE; Schema: auth; Owner: -
--

CREATE OR REPLACE VIEW auth.v_campanas_dashboard AS
 SELECT c.id AS id_campana,
    c.id_vendedor,
    c.nombre,
    c.tipo,
    c.estado,
    c.fecha_inicio,
    c.fecha_fin,
    c.alcance_total,
    c.conversiones,
    round((((c.conversiones)::numeric / (NULLIF(c.alcance_total, 0))::numeric) * (100)::numeric), 1) AS tasa_conversion_pct,
    p.codigo AS promo_codigo,
    p.tipo AS promo_tipo,
    p.valor AS promo_valor,
    count(cl.id) FILTER (WHERE (cl.evento = 'enviado'::text)) AS enviados_log,
    count(cl.id) FILTER (WHERE (cl.evento = 'visto'::text)) AS vistos,
    count(cl.id) FILTER (WHERE (cl.evento = 'click'::text)) AS clicks,
    round((((count(cl.id) FILTER (WHERE (cl.evento = 'visto'::text)))::numeric / (NULLIF(count(cl.id) FILTER (WHERE (cl.evento = 'enviado'::text)), 0))::numeric) * (100)::numeric), 1) AS tasa_apertura_pct,
    ab.ganador AS ab_ganador,
    ab.confianza_pct AS ab_confianza,
    c.fecha_creacion,
    c.fecha_modificacion
   FROM (((auth.campanas c
     LEFT JOIN auth.promociones p ON ((p.id = c.id_promocion)))
     LEFT JOIN auth.campana_registro cl ON ((cl.id_campana = c.id)))
     LEFT JOIN auth.campana_ab_configuracion ab ON ((ab.id_campana = c.id)))
  GROUP BY c.id, p.id, ab.id;


